# 由 MaoPet 实例设置的全局显示名转换器。只改 UI 新显示的文字，不触碰 Text
# 控件里已经保存/载入的历史内容，也不会批量改写任何历史记录或旧存档文件。
_ACTIVE_PET_NAME_TRANSFORM = lambda value: str(value if value is not None else "")
_PERSONA_NAME_HOOKS_INSTALLED = False


def _petzhu_groupchat_preserve_display_names(widget):
    """群聊中的参与者名字属于各自独立身份，不能套用当前实例的全局改名规则。"""
    current = widget
    seen = set()
    for _ in range(96):
        if current is None or id(current) in seen:
            return False
        seen.add(id(current))
        try:
            if (getattr(current, "_petzhu_groupchat_preserve_names_v1", False)
                    or getattr(current, "_petzhu_groupchat_active_v1", False)):
                return True
            current = getattr(current, "master", None)
        except Exception:
            return False
    return False


def _install_persona_name_display_hooks():
    """让普通界面控件、窗口标题和消息框使用当前显示名；不改桌宠Canvas气泡正文。"""
    global _PERSONA_NAME_HOOKS_INSTALLED
    if _PERSONA_NAME_HOOKS_INSTALLED:
        return
    _PERSONA_NAME_HOOKS_INSTALLED = True

    def _transform_text(value):
        if not isinstance(value, str):
            return value
        try:
            return _ACTIVE_PET_NAME_TRANSFORM(value)
        except Exception:
            return value

    try:
        original_options = tk.Misc._options
        def _name_aware_options(self, cnf, kw=None):
            # Canvas 文本包含桌宠对话气泡、绘制出来的动态正文等内容，不能在通用
            # Tk 选项层做名字替换。普通 Label/Button 等静态界面控件仍按新名字显示；
            # 战斗专用 RaidScaledCanvas 会在它自己的 UI 绘制层单独处理界面标签。
            try:
                if (isinstance(self, tk.Canvas)
                        or _petzhu_groupchat_preserve_display_names(self)
                        or bool(globals().get("_PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68", 0))):
                    return original_options(self, cnf, kw)
            except Exception:
                pass
            try:
                if isinstance(cnf, dict):
                    cnf = dict(cnf)
                    for key in ("text", "label", "title", "message"):
                        if key in cnf:
                            cnf[key] = _transform_text(cnf[key])
                if isinstance(kw, dict):
                    kw = dict(kw)
                    for key in ("text", "label", "title", "message"):
                        if key in kw:
                            kw[key] = _transform_text(kw[key])
            except Exception:
                pass
            return original_options(self, cnf, kw)
        if not getattr(tk.Misc._options, "_persona_name_hook", False):
            _name_aware_options._persona_name_hook = True
            tk.Misc._options = _name_aware_options
    except Exception:
        pass

    try:
        original_title = tk.Wm.wm_title
        def _name_aware_title(self, string=None):
            if string is None:
                return original_title(self)
            if _petzhu_groupchat_preserve_display_names(self):
                return original_title(self, str(string))
            return original_title(self, _transform_text(str(string)))
        if not getattr(tk.Wm.wm_title, "_persona_name_hook", False):
            _name_aware_title._persona_name_hook = True
            tk.Wm.wm_title = _name_aware_title
    except Exception:
        pass

    # tkinter.messagebox 最终通过 _show 创建系统消息框；这里仅转换即将显示的文案。
    try:
        original_show = messagebox._show
        def _name_aware_messagebox(*args, **kwargs):
            args = list(args)
            if len(args) > 0 and isinstance(args[0], str):
                args[0] = _transform_text(args[0])
            if len(args) > 1 and isinstance(args[1], str):
                args[1] = _transform_text(args[1])
            for key in ("title", "message"):
                if isinstance(kwargs.get(key), str):
                    kwargs[key] = _transform_text(kwargs[key])
            return original_show(*args, **kwargs)
        if not getattr(messagebox._show, "_persona_name_hook", False):
            _name_aware_messagebox._persona_name_hook = True
            messagebox._show = _name_aware_messagebox
    except Exception:
        pass


_install_persona_name_display_hooks()


# 桌宠/普通界面的“主题色相”映射。只旋转原有粉色系的色相；高难小游戏窗口和绘图明确排除。
# 330° 是旧版粉色方案的参考色相。
_PETZHU_THEME_HUE_DEFAULT = 330
_PETZHU_THEME_HUE_STATE = {
    "hue": _PETZHU_THEME_HUE_DEFAULT,
    "widgets": weakref.WeakSet(),
    "canvases": weakref.WeakKeyDictionary(),
    "styles": weakref.WeakKeyDictionary(),
    # Observation diary windows are entirely exempt from global widget hooks.
    # They register a local palette refresher and theme only their own active Diary category.
    "observation_diary_roots": weakref.WeakSet(),
    "installed": False,
}
_PETZHU_WIDGET_COLOR_KEYS = {
    "bg", "background", "fg", "foreground", "activebackground", "activeforeground",
    "disabledforeground", "selectbackground", "selectforeground", "selectcolor",
    "insertbackground", "highlightbackground", "highlightcolor", "troughcolor",
    "readonlybackground", "bordercolor", "lightcolor", "darkcolor",
}
_PETZHU_CANVAS_COLOR_KEYS = {"fill", "outline", "activefill", "activeoutline", "disabledfill", "disabledoutline"}


def _petzhu_parse_hex_color(value):
    if not isinstance(value, str) or not value.startswith("#"):
        return None
    text = value[1:]
    if len(text) == 3:
        text = "".join(ch * 2 for ch in text)
    if len(text) != 6:
        return None
    try:
        return tuple(int(text[i:i + 2], 16) for i in (0, 2, 4))
    except Exception:
        return None


def _petzhu_is_original_pink(value):
    """判断是否属于旧主题的粉色系，包括低饱和的浅粉背景。"""
    rgb = _petzhu_parse_hex_color(value)
    if rgb is None:
        return False
    h, sat, val = colorsys.rgb_to_hsv(*(channel / 255.0 for channel in rgb))
    return 0.86 <= h <= 0.95 and sat >= 0.005 and val >= 0.30


def _petzhu_shift_theme_color(value):
    rgb = _petzhu_parse_hex_color(value)
    if rgb is None or not _petzhu_is_original_pink(value):
        return value
    target = int(_PETZHU_THEME_HUE_STATE.get("hue", _PETZHU_THEME_HUE_DEFAULT)) % 360
    # 基准色相为330°；以同一角度偏移所有原始粉色，保留不同粉色明暗之间的层次。
    delta = (target - _PETZHU_THEME_HUE_DEFAULT) % 360
    if delta == 0:
        return value
    h, sat, val = colorsys.rgb_to_hsv(*(channel / 255.0 for channel in rgb))
    rr, gg, bb = colorsys.hsv_to_rgb((h + delta / 360.0) % 1.0, sat, val)
    return "#%02x%02x%02x" % (round(rr * 255), round(gg * 255), round(bb * 255))


def _petzhu_story_reader_background(light=True):
    """按当前主题色生成《艾欧泽亚行纪》正文底色；不改变正文文字/标签配色。"""
    try:
        target = int(_PETZHU_THEME_HUE_STATE.get("hue", _PETZHU_THEME_HUE_DEFAULT)) % 360
    except Exception:
        target = _PETZHU_THEME_HUE_DEFAULT
    if bool(light):
        # 浅色界面保持原来的淡色纸张亮度和饱和度，只旋转到当前主题色相。
        base = "#f7d6e5"
        rgb = _petzhu_parse_hex_color(base)
        if rgb is None:
            return base
        h, sat, val = colorsys.rgb_to_hsv(*(channel / 255.0 for channel in rgb))
        delta = ((target - _PETZHU_THEME_HUE_DEFAULT) % 360) / 360.0
        h = (h + delta) % 1.0
        rr, gg, bb = colorsys.hsv_to_rgb(h, sat, val)
        return "#%02x%02x%02x" % (round(rr * 255), round(gg * 255), round(bb * 255))
    # 深色主题采用暗色主题色底，保持足够低的亮度以确保浅色正文易读。
    rr, gg, bb = colorsys.hsv_to_rgb(target / 360.0, 0.28, 0.17)
    return "#%02x%02x%02x" % (round(rr * 255), round(gg * 255), round(bb * 255))


def _petzhu_color_value_matches_shifted(value, original):
    try:
        a = _petzhu_parse_hex_color(str(value))
        b = _petzhu_parse_hex_color(str(_petzhu_shift_theme_color(original)))
        return a is not None and a == b
    except Exception:
        return False


def _petzhu_cnf_dict(cnf=None, kw=None):
    """只合并真正的 Tk 配置字典，不把 Canvas 坐标列表交给 _cnfmerge。

    Canvas 的绘图坐标也可能是 tuple/list，里面通常是整数或浮点数。
    直接调用 tkinter._cnfmerge 会把这些坐标误判为配置并打印 fallback 警告。
    这里仅提取字典配置，安全忽略非配置值。
    """
    out = {}

    def collect(value):
        if isinstance(value, dict):
            out.update(value)
        elif isinstance(value, (tuple, list)):
            for item in value:
                if isinstance(item, dict):
                    out.update(item)
                elif isinstance(item, (tuple, list)):
                    collect(item)
        # 字符串、数字、坐标等不是可合并的配置字典，直接忽略。

    collect(cnf)
    if isinstance(kw, dict):
        out.update(kw)
    return out


def _petzhu_theme_hue_canvas_items_preserved(widget):
    """True when a Canvas contains user artwork whose fill/outline RGB must never be hue-shifted."""
    current = widget
    seen = set()
    for _ in range(96):
        if current is None or id(current) in seen:
            return False
        seen.add(id(current))
        try:
            if getattr(current, "_petzhu_theme_hue_preserve_items", False):
                return True
            current = getattr(current, "master", None)
        except Exception:
            current = None
    return False


def _petzhu_normalize_option_name(key):
    key = str(key)
    return key[:-1] if key.endswith("_") else key


def _petzhu_map_nested_colors(value):
    if isinstance(value, str):
        return _petzhu_shift_theme_color(value)
    if isinstance(value, list):
        return [_petzhu_map_nested_colors(item) for item in value]
    if isinstance(value, tuple):
        return tuple(_petzhu_map_nested_colors(item) for item in value)
    return value


def _petzhu_nested_contains_pink(value):
    if isinstance(value, str):
        return _petzhu_is_original_pink(value)
    if isinstance(value, (list, tuple)):
        return any(_petzhu_nested_contains_pink(item) for item in value)
    return False


def _petzhu_is_song_theme_managed(widget):
    """True when a widget belongs to the song editor, whose palette is managed locally."""
    current = widget
    seen = set()
    for _ in range(96):
        if current is None or id(current) in seen:
            return False
        seen.add(id(current))
        try:
            if getattr(current, "_petzhu_song_theme_managed", False):
                return True
            current = getattr(current, "master", None)
        except Exception:
            current = None
    return False


def _petzhu_theme_hue_is_exempt(widget):
    """战斗窗口及其所有后代控件都不参与桌宠主题色相映射。"""
    current = widget
    seen = set()
    for _ in range(96):
        if current is None:
            return False
        marker = id(current)
        if marker in seen:
            return False
        seen.add(marker)
        try:
            if (getattr(current, "_petzhu_theme_hue_exempt", False)
                    or getattr(current, "_petzhu_raid_ui", False)):
                return True
        except Exception:
            pass
        try:
            parent = getattr(current, "master", None)
        except Exception:
            parent = None
        if parent is None:
            try:
                parent_path = current.winfo_parent()
                parent = current.nametowidget(parent_path) if parent_path else None
            except Exception:
                parent = None
        current = parent
    return False


def _install_theme_hue_hooks():
    if _PETZHU_THEME_HUE_STATE["installed"]:
        return
    _PETZHU_THEME_HUE_STATE["installed"] = True

    # Keep originals so recoloring existing widgets does not accumulate hue rotations.
    original_options = tk.Misc._options
    original_canvas_create = tk.Canvas._create
    original_canvas_itemconfigure = tk.Canvas.itemconfigure
    original_text_tag_configure = tk.Text.tag_configure
    original_style_configure = ttk.Style.configure
    original_style_map = ttk.Style.map

    def hue_aware_options(self, cnf, kw=None):
        try:
            if _petzhu_theme_hue_is_exempt(self):
                return original_options(self, cnf, kw)
            merged = _petzhu_cnf_dict(cnf, kw)
            is_canvas_item = bool(getattr(self, "_petzhu_theme_hue_item_context", False))
            is_text_tag = bool(getattr(self, "_petzhu_theme_hue_tag_context", False))
            if is_canvas_item and _petzhu_theme_hue_canvas_items_preserved(self):
                return original_options(self, cnf, kw)
            if not merged:
                return original_options(self, cnf, kw)
            relevant_keys = _PETZHU_CANVAS_COLOR_KEYS if is_canvas_item else _PETZHU_WIDGET_COLOR_KEYS
            store = None
            if not is_canvas_item and not is_text_tag:
                store = getattr(self, "_petzhu_theme_hue_base_options", None)
            transformed = dict(merged)
            for raw_key, value in list(merged.items()):
                key = _petzhu_normalize_option_name(raw_key)
                if key not in relevant_keys or not isinstance(value, str):
                    continue
                if store is not None:
                    old_source = store.get(key)
                    # Round-tripping a currently displayed cget() color must not erase its source hue.
                    if old_source is not None and _petzhu_color_value_matches_shifted(value, old_source):
                        value = old_source
                        transformed[raw_key] = value
                if _petzhu_is_original_pink(value):
                    if not is_canvas_item and not is_text_tag and store is None:
                        store = {}
                        try:
                            self._petzhu_theme_hue_base_options = store
                            _PETZHU_THEME_HUE_STATE["widgets"].add(self)
                        except Exception:
                            store = None
                    if store is not None:
                        store[key] = value
                elif store is not None:
                    store.pop(key, None)
                transformed[raw_key] = _petzhu_shift_theme_color(value)
            return original_options(self, transformed, None)
        except Exception:
            return original_options(self, cnf, kw)

    if not getattr(tk.Misc._options, "_petzhu_theme_hue_hook", False):
        hue_aware_options._petzhu_theme_hue_hook = True
        tk.Misc._options = hue_aware_options

    def hue_aware_canvas_create(self, itemType, args, kw):
        if _petzhu_theme_hue_is_exempt(self) or _petzhu_theme_hue_canvas_items_preserved(self):
            return original_canvas_create(self, itemType, args, kw)
        options = {}
        try:
            # _create 的 args 主要是坐标；最后一项若为 list/tuple 可能只是坐标数组，
            # 因此只有字典才单独视为位置配置。常见颜色选项由 kw 提供。
            cnf = args[-1] if args and isinstance(args[-1], dict) else None
            options = _petzhu_cnf_dict(cnf, kw)
        except Exception:
            options = _petzhu_cnf_dict(None, kw)
        self._petzhu_theme_hue_item_context = True
        try:
            item_id = original_canvas_create(self, itemType, args, kw)
        finally:
            try:
                self._petzhu_theme_hue_item_context = False
            except Exception:
                pass
        source_colors = {
            _petzhu_normalize_option_name(key): value
            for key, value in options.items()
            if _petzhu_normalize_option_name(key) in _PETZHU_CANVAS_COLOR_KEYS
            and isinstance(value, str) and _petzhu_is_original_pink(value)
        }
        if source_colors:
            try:
                canvas_map = _PETZHU_THEME_HUE_STATE["canvases"].setdefault(self, {})
                canvas_map[int(item_id)] = source_colors
                _PETZHU_THEME_HUE_STATE["widgets"].add(self)
            except Exception:
                pass
        return item_id

    if not getattr(tk.Canvas._create, "_petzhu_theme_hue_hook", False):
        hue_aware_canvas_create._petzhu_theme_hue_hook = True
        tk.Canvas._create = hue_aware_canvas_create

    def hue_aware_canvas_itemconfigure(self, tagOrId, cnf=None, **kw):
        if _petzhu_theme_hue_is_exempt(self) or _petzhu_theme_hue_canvas_items_preserved(self):
            return original_canvas_itemconfigure(self, tagOrId, cnf, **kw)
        # Some individual Canvas items (not the whole Canvas) belong to another
        # player's theme. Let those exact items keep their sender-provided colors.
        try:
            protected_ids = set(getattr(self, "_petzhu_theme_hue_preserve_item_ids", ()) or ())
            if protected_ids:
                if isinstance(tagOrId, int) or (isinstance(tagOrId, str) and tagOrId.isdigit()):
                    target_ids = [int(tagOrId)]
                else:
                    target_ids = [int(x) for x in self.find_withtag(tagOrId)]
                if target_ids and all(item_id in protected_ids for item_id in target_ids):
                    return original_canvas_itemconfigure(self, tagOrId, cnf, **kw)
        except Exception:
            pass
        merged = _petzhu_cnf_dict(cnf, kw)
        configuring = bool(merged)
        try:
            if configuring and not getattr(self, "_petzhu_theme_hue_reapplying", False):
                try:
                    if isinstance(tagOrId, int) or (isinstance(tagOrId, str) and tagOrId.isdigit()):
                        item_ids = [int(tagOrId)]
                    else:
                        item_ids = [int(x) for x in self.find_withtag(tagOrId)]
                except Exception:
                    item_ids = []
                canvas_map = _PETZHU_THEME_HUE_STATE["canvases"].setdefault(self, {})
                if len(item_ids) == 1:
                    existing = canvas_map.get(item_ids[0], {})
                    for raw_key, value in list(merged.items()):
                        key = _petzhu_normalize_option_name(raw_key)
                        old = existing.get(key)
                        if old is not None and isinstance(value, str) and _petzhu_color_value_matches_shifted(value, old):
                            merged[raw_key] = old
                            value = old
                        if key in _PETZHU_CANVAS_COLOR_KEYS:
                            if isinstance(value, str) and _petzhu_is_original_pink(value):
                                existing[key] = value
                            else:
                                existing.pop(key, None)
                    if existing:
                        canvas_map[item_ids[0]] = existing
                        _PETZHU_THEME_HUE_STATE["widgets"].add(self)
                    else:
                        canvas_map.pop(item_ids[0], None)
                elif item_ids:
                    for item_id in item_ids:
                        existing = canvas_map.setdefault(item_id, {})
                        for raw_key, value in merged.items():
                            key = _petzhu_normalize_option_name(raw_key)
                            if key in _PETZHU_CANVAS_COLOR_KEYS:
                                if isinstance(value, str) and _petzhu_is_original_pink(value):
                                    existing[key] = value
                                elif key in existing:
                                    existing.pop(key, None)
                        if existing:
                            _PETZHU_THEME_HUE_STATE["widgets"].add(self)
            self._petzhu_theme_hue_item_context = True
            return original_canvas_itemconfigure(self, tagOrId, merged if configuring else cnf, **({} if configuring else kw))
        finally:
            try:
                self._petzhu_theme_hue_item_context = False
            except Exception:
                pass

    if not getattr(tk.Canvas.itemconfigure, "_petzhu_theme_hue_hook", False):
        hue_aware_canvas_itemconfigure._petzhu_theme_hue_hook = True
        tk.Canvas.itemconfigure = hue_aware_canvas_itemconfigure
        tk.Canvas.itemconfig = hue_aware_canvas_itemconfigure

    def hue_aware_text_tag_configure(self, tagName, cnf=None, **kw):
        if _petzhu_theme_hue_is_exempt(self):
            return original_text_tag_configure(self, tagName, cnf, **kw)
        merged = _petzhu_cnf_dict(cnf, kw)
        if not merged:
            return original_text_tag_configure(self, tagName, cnf, **kw)
        tag_store = getattr(self, "_petzhu_theme_hue_tag_options", None)
        if tag_store is None:
            tag_store = {}
            self._petzhu_theme_hue_tag_options = tag_store
            try:
                _PETZHU_THEME_HUE_STATE["widgets"].add(self)
            except Exception:
                pass
        existing = tag_store.setdefault(str(tagName), {})
        for raw_key, value in list(merged.items()):
            key = _petzhu_normalize_option_name(raw_key)
            old = existing.get(key)
            if old is not None and isinstance(value, str) and _petzhu_color_value_matches_shifted(value, old):
                merged[raw_key] = old
                value = old
            if key in ("foreground", "background"):
                if isinstance(value, str) and _petzhu_is_original_pink(value):
                    existing[key] = value
                else:
                    existing.pop(key, None)
        if not existing:
            tag_store.pop(str(tagName), None)
        self._petzhu_theme_hue_tag_context = True
        try:
            return original_text_tag_configure(self, tagName, merged, **{})
        finally:
            self._petzhu_theme_hue_tag_context = False

    if not getattr(tk.Text.tag_configure, "_petzhu_theme_hue_hook", False):
        hue_aware_text_tag_configure._petzhu_theme_hue_hook = True
        tk.Text.tag_configure = hue_aware_text_tag_configure
        tk.Text.tag_config = hue_aware_text_tag_configure

    def hue_aware_style_configure(self, style, query_opt=None, **kw):
        # ttk.Style 是整个 Tk 应用共享的全局对象，没有可靠的父窗口归属；
        # 为确保高难小游戏样式不受主题滑杆影响，ttk 样式保持原样。
        return original_style_configure(self, style, query_opt, **kw)

    def hue_aware_style_map(self, style, query_opt=None, **kw):
        # 不对进程级 ttk 状态做色相映射，避免影响高难小游戏窗口。
        return original_style_map(self, style, query_opt, **kw)

    if not getattr(ttk.Style.configure, "_petzhu_theme_hue_hook", False):
        hue_aware_style_configure._petzhu_theme_hue_hook = True
        ttk.Style.configure = hue_aware_style_configure
    if not getattr(ttk.Style.map, "_petzhu_theme_hue_hook", False):
        hue_aware_style_map._petzhu_theme_hue_hook = True
        ttk.Style.map = hue_aware_style_map


def _petzhu_apply_global_theme_hue(hue):
    """只更新普通桌宠界面、菜单星星及屏幕落星；高难小游戏窗口完全排除。"""
    try:
        hue = max(0, min(359, int(round(float(hue)))))
    except Exception:
        hue = _PETZHU_THEME_HUE_DEFAULT
    _PETZHU_THEME_HUE_STATE["hue"] = hue

    for widget in list(_PETZHU_THEME_HUE_STATE["widgets"]):
        try:
            if not widget.winfo_exists():
                continue
        except Exception:
            continue
        if _petzhu_theme_hue_is_exempt(widget):
            # 阅读器正文/章节/对白等文字颜色继续保持原样；仅正文背景跟随主题色，
            # 桌宠名称标签仍单独使用主题色。不会对其他文字标签做全局换色。
            try:
                if isinstance(widget, tk.Text):
                    if widget is getattr(self, "story_reader_text", None):
                        reader_light = bool(getattr(widget, "_petzhu_story_reader_light", True))
                        reader_bg = _petzhu_story_reader_background(reader_light)
                        widget.configure(bg=reader_bg)
                        try:
                            if widget.master is not None:
                                widget.master.configure(bg=reader_bg)
                        except Exception:
                            pass
                    pet_tag = str(getattr(widget, "_petzhu_theme_hue_exempt_name_tag", "") or "")
                    pet_base = str(getattr(widget, "_petzhu_theme_hue_exempt_name_base_color", "") or "")
                    if pet_tag and pet_base:
                        widget.tag_configure(
                            pet_tag,
                            foreground=_petzhu_shift_theme_color(pet_base),
                            underline=True,
                        )
            except Exception:
                pass
            continue
        base_options = getattr(widget, "_petzhu_theme_hue_base_options", None)
        if base_options:
            try:
                widget.configure(**dict(base_options))
            except Exception:
                pass
        # Canvas 项目（包括菜单星星和屏幕落星）按其原始颜色重新着色。
        if (isinstance(widget, tk.Canvas)
                and not _petzhu_theme_hue_is_exempt(widget)
                and not _petzhu_theme_hue_canvas_items_preserved(widget)):
            canvas_items = _PETZHU_THEME_HUE_STATE["canvases"].get(widget, {})
            try:
                current_ids = set(int(item) for item in widget.find_all())
            except Exception:
                current_ids = set()
            for item_id in list(canvas_items):
                if item_id not in current_ids:
                    canvas_items.pop(item_id, None)
                    continue
                colors = canvas_items.get(item_id, {})
                if not colors:
                    continue
                try:
                    widget._petzhu_theme_hue_item_context = True
                    widget._petzhu_theme_hue_reapplying = True
                    widget.itemconfigure(item_id, **dict(colors))
                except Exception:
                    pass
                finally:
                    widget._petzhu_theme_hue_item_context = False
                    widget._petzhu_theme_hue_reapplying = False
        # Text 控件上通过 tag_configure 设置的粉色文本也一起更新。
        tag_store = getattr(widget, "_petzhu_theme_hue_tag_options", {})
        if tag_store:
            for tag_name, options in list(tag_store.items()):
                try:
                    widget._petzhu_theme_hue_tag_context = True
                    widget.tag_configure(tag_name, **dict(options))
                except Exception:
                    pass
                finally:
                    widget._petzhu_theme_hue_tag_context = False

    for style_obj, style_state in list(_PETZHU_THEME_HUE_STATE["styles"].items()):
        try:
            for style_name, options in style_state.get("configure", {}).items():
                if options:
                    style_obj.configure(style_name, **dict(options))
            for style_name, options in style_state.get("map", {}).items():
                if options:
                    style_obj.map(style_name, **dict(options))
        except Exception:
            pass

    # The observation diary does not participate in the global Tk/Canvas recoloring hooks.
    # Its own palette refresher derives the correct first-frame palette for the active category.
    for diary_root in list(_PETZHU_THEME_HUE_STATE.get("observation_diary_roots", ())):
        try:
            if diary_root.winfo_exists():
                refresher = getattr(diary_root, "_petzhu_refresh_observation_diary_hue", None)
                if callable(refresher):
                    refresher(hue)
        except Exception:
            pass


_install_theme_hue_hooks()


def _ensure_pygame_mixer():
    """确保 pygame 音频混音器可用。

    v37 直接使用 pygame.mixer.init()；当音频设备曾被 quit、驱动暂时不可用、
    或系统默认参数不兼容时，唱歌界面会直接报“音频初始化失败”。这里统一
    用多组常见参数重试，并避免桌宠/BGM/唱歌各自重复初始化。
    """
    if pygame is None:
        return False
    try:
        info = pygame.mixer.get_init()
        if info:
            return True
    except Exception:
        pass

    attempts = [
        dict(frequency=44100, size=-16, channels=2, buffer=512),
        dict(frequency=48000, size=-16, channels=2, buffer=512),
        dict(frequency=22050, size=-16, channels=2, buffer=1024),
    ]
    last_exc = None
    for kwargs in attempts:
        try:
            pygame.mixer.init(**kwargs)
            # pygame 默认只保证一个有限数量的混音通道；
            # 唱歌界面会使用多个通道来同时演奏和弦/延音，
            # 因此初始化成功后统一扩展到足够的通道。
            try:
                if pygame.mixer.get_num_channels() < 32:
                    pygame.mixer.set_num_channels(32)
            except Exception:
                pass
            return bool(pygame.mixer.get_init())
        except Exception as exc:
            last_exc = exc
            try:
                pygame.mixer.quit()
            except Exception:
                pass

    # Windows 下 SDL 有时会因为默认音频后端短暂异常而初始化失败。
    # 仅在前面的常规参数都失败后，再尝试指定 DirectSound。
    if os.name == "nt":
        old_driver = os.environ.get("SDL_AUDIODRIVER")
        try:
            os.environ["SDL_AUDIODRIVER"] = "directsound"
            for kwargs in attempts:
                try:
                    pygame.mixer.init(**kwargs)
                    try:
                        if pygame.mixer.get_num_channels() < 32:
                            pygame.mixer.set_num_channels(32)
                    except Exception:
                        pass
                    return bool(pygame.mixer.get_init())
                except Exception as exc:
                    last_exc = exc
                    try:
                        pygame.mixer.quit()
                    except Exception:
                        pass
        finally:
            if old_driver is None:
                os.environ.pop("SDL_AUDIODRIVER", None)
            else:
                os.environ["SDL_AUDIODRIVER"] = old_driver

    return False

