def _safe_overrideredirect(window, enabled=True):
    flag = "1" if enabled else "0"
    try:
        window.tk.call("wm", "overrideredirect", window._w, flag)
        return True
    except Exception:
        try:
            window.attributes("-overrideredirect", enabled)
            return True
        except Exception:
            return False


def _find_app_icon_path():
    """寻找应用图标：优先使用当前人设导入的图标，其次使用默认 zhu.ico。"""
    candidates = []
    try:
        custom_icon = os.path.join(get_data_dir(), "persona_assets", "persona_app.ico")
        candidates.append(custom_icon)
    except Exception:
        pass
    if getattr(sys, "frozen", False):
        meipass = str(getattr(sys, "_MEIPASS", "") or "").strip()
        if meipass:
            candidates.append(os.path.join(meipass, "zhu.ico"))
        try:
            candidates.append(os.path.join(os.path.dirname(os.path.abspath(sys.executable)), "zhu.ico"))
        except Exception:
            pass
    else:
        try:
            candidates.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), "zhu.ico"))
        except Exception:
            pass
    candidates.append(r"D:\PETZhu5\zhu.ico")
    for path in candidates:
        try:
            if path and os.path.isfile(path):
                return path
        except Exception:
            pass
    return ""


def _parse_ico_bytes(data):
    """校验 ICO 文件并拆出图像资源；返回可用于写入 PE 图标资源的条目。"""
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("ICO 数据无效。")
    data = bytes(data)
    if len(data) < 6 or len(data) > 32 * 1024 * 1024:
        raise ValueError("ICO 文件大小无效（最大 32 MB）。")
    reserved, image_type, count = struct.unpack_from("<HHH", data, 0)
    if reserved != 0 or image_type != 1 or not (1 <= count <= 256):
        raise ValueError("文件不是有效的 Windows ICO 图标。")
    directory_end = 6 + count * 16
    if directory_end > len(data):
        raise ValueError("ICO 图标目录不完整。")
    entries = []
    for i in range(count):
        offset = 6 + i * 16
        width, height, colors, reserved_byte, planes, bit_count, size, image_offset = struct.unpack_from(
            "<BBBBHHII", data, offset
        )
        if reserved_byte != 0 or size <= 0 or image_offset < directory_end or image_offset + size > len(data):
            raise ValueError("ICO 中第 %d 个图像条目损坏。" % (i + 1))
        if width == 0:
            width = 256
        if height == 0:
            height = 256
        if width > 1024 or height > 1024 or size > 24 * 1024 * 1024:
            raise ValueError("ICO 中的图像尺寸或数据过大。")
        entries.append({
            "width": width, "height": height, "colors": colors,
            "planes": planes, "bit_count": bit_count,
            "data": data[image_offset:image_offset + size],
            "size": size,
        })
    return entries


def _build_group_icon_resource(ico_bytes):
    """把 ICO 文件整理成 Windows PE 的 RT_ICON 与 RT_GROUP_ICON 资源内容。"""
    entries = _parse_ico_bytes(ico_bytes)
    group = bytearray(struct.pack("<HHH", 0, 1, len(entries)))
    for index, entry in enumerate(entries, 1):
        group.extend(struct.pack(
            "<BBBBHHIH",
            0 if entry["width"] == 256 else entry["width"],
            0 if entry["height"] == 256 else entry["height"],
            entry["colors"], 0, entry["planes"], entry["bit_count"],
            entry["size"], index,
        ))
    return entries, bytes(group)


def _pe_overlay_start(data):
    """返回 PE 最后一个节的原始数据末尾；PyInstaller 单文件包通常追加在这里之后。"""
    if not isinstance(data, (bytes, bytearray)) or len(data) < 0x40 or data[:2] != b"MZ":
        raise ValueError("目标文件不是有效的 Windows PE 应用。")
    try:
        pe_offset = struct.unpack_from("<I", data, 0x3C)[0]
        if pe_offset < 0x40 or pe_offset + 24 > len(data) or data[pe_offset:pe_offset + 4] != b"PE\0\0":
            raise ValueError("EXE 的 PE 头无效。")
        section_count = struct.unpack_from("<H", data, pe_offset + 6)[0]
        optional_size = struct.unpack_from("<H", data, pe_offset + 20)[0]
        section_table = pe_offset + 24 + optional_size
        if section_count <= 0 or section_count > 96 or section_table + section_count * 40 > len(data):
            raise ValueError("EXE 的节表无效。")
        section_ends = []
        for index in range(section_count):
            off = section_table + index * 40
            raw_size = struct.unpack_from("<I", data, off + 16)[0]
            raw_ptr = struct.unpack_from("<I", data, off + 20)[0]
            if raw_size:
                section_ends.append(raw_ptr + raw_size)
        if not section_ends:
            raise ValueError("EXE 中没有可识别的 PE 节数据。")
        offset = max(section_ends)
        if offset > len(data):
            raise ValueError("EXE 的节表指向文件末尾之外。")
        return offset
    except struct.error as exc:
        raise ValueError("读取 EXE 的 PE 结构失败：%s" % exc)


def _replace_exe_icon_with_ico(exe_path, ico_bytes):
    """更换副本的 PE 图标，并保留 PyInstaller 单文件 EXE 追加在 PE 后面的程序归档。

    Windows 的 BeginUpdateResource/EndUpdateResource 会重写 PE 资源区；部分 EXE 上
    这一步会丢掉 PE 节之后的 overlay。PyInstaller --onefile 把真正的 Python 程序包放在
    overlay 中，因此如果不恢复它，生成的 EXE 就只剩几百 KB 的启动器。
    """
    if os.name != "nt":
        raise RuntimeError("只有在 Windows 上才能将 ICO 写入 EXE 的应用图标资源。")
    entries, group_payload = _build_group_icon_resource(ico_bytes)

    # 在写资源前备份 PE 节以后的全部数据（PyInstaller 单文件程序包就在这里）。
    with open(exe_path, "rb") as source_file:
        original_data = source_file.read()
    original_overlay_start = _pe_overlay_start(original_data)
    original_overlay = original_data[original_overlay_start:]

    from ctypes import wintypes
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.BeginUpdateResourceW.argtypes = [wintypes.LPCWSTR, wintypes.BOOL]
    kernel32.BeginUpdateResourceW.restype = wintypes.HANDLE
    kernel32.UpdateResourceW.argtypes = [
        wintypes.HANDLE, ctypes.c_void_p, ctypes.c_void_p,
        wintypes.WORD, ctypes.c_void_p, wintypes.DWORD,
    ]
    kernel32.UpdateResourceW.restype = wintypes.BOOL
    kernel32.EndUpdateResourceW.argtypes = [wintypes.HANDLE, wintypes.BOOL]
    kernel32.EndUpdateResourceW.restype = wintypes.BOOL

    update_handle = kernel32.BeginUpdateResourceW(os.path.abspath(exe_path), False)
    if not update_handle:
        raise ctypes.WinError(ctypes.get_last_error())
    committed = False
    # 中性、英文、简体中文及日文语言资源都写入同一图标，避免资源语言选择导致仍显示旧图标。
    languages = (0, 0x0409, 0x0804, 0x0411)
    try:
        for language in languages:
            for index, entry in enumerate(entries, 1):
                buffer = ctypes.create_string_buffer(entry["data"])
                ok = kernel32.UpdateResourceW(
                    update_handle, ctypes.c_void_p(3), ctypes.c_void_p(index),
                    language, ctypes.cast(buffer, ctypes.c_void_p), len(entry["data"]),
                )
                if not ok:
                    raise ctypes.WinError(ctypes.get_last_error())
            group_buffer = ctypes.create_string_buffer(group_payload)
            ok = kernel32.UpdateResourceW(
                update_handle, ctypes.c_void_p(14), ctypes.c_void_p(1),
                language, ctypes.cast(group_buffer, ctypes.c_void_p), len(group_payload),
            )
            if not ok:
                raise ctypes.WinError(ctypes.get_last_error())
        if not kernel32.EndUpdateResourceW(update_handle, False):
            raise ctypes.WinError(ctypes.get_last_error())
        update_handle = None
        committed = True
    finally:
        if update_handle and not committed:
            try:
                kernel32.EndUpdateResourceW(update_handle, True)
            except Exception:
                pass

    # 重新计算被 Windows 改写后的 PE 末尾，并恢复原来全部 overlay。
    # 即使 Windows API 恰好保留了部分 overlay，也先截到新 PE 节末尾再拼接一次，避免重复。
    try:
        with open(exe_path, "rb") as updated_file:
            updated_data = updated_file.read()
        updated_overlay_start = _pe_overlay_start(updated_data)
        if original_overlay:
            restored_data = updated_data[:updated_overlay_start] + original_overlay
        else:
            restored_data = updated_data[:updated_overlay_start]
        if len(restored_data) < len(original_overlay) + updated_overlay_start:
            raise RuntimeError("恢复单文件程序包时长度校验失败。")
        restore_temp = exe_path + ".overlay_restore.tmp"
        with open(restore_temp, "wb") as restore_file:
            restore_file.write(restored_data)
            restore_file.flush()
            os.fsync(restore_file.fileno())
        os.replace(restore_temp, exe_path)

        # 基础完整性检查：若源文件带有 overlay，恢复后尾部必须与源文件备份完全一致。
        if original_overlay:
            with open(exe_path, "rb") as final_file:
                final_file.seek(-len(original_overlay), os.SEEK_END)
                if final_file.read(len(original_overlay)) != original_overlay:
                    raise RuntimeError("单文件程序包尾部校验失败，生成的 EXE 不完整。")
    except Exception:
        try:
            restore_temp = exe_path + ".overlay_restore.tmp"
            if os.path.exists(restore_temp):
                os.remove(restore_temp)
        except Exception:
            pass
        raise



