# Windows 原生系统托盘
# ============================================================

class _WindowsSystemTray:
    """Windows 原生系统托盘实现。

    关键点：所有 Win32 句柄都显式声明为指针宽度类型，避免 64 位 Python 下
    HWND/HINSTANCE/HICON 被 ctypes 默认的 32 位返回值截断。
    """

    WM_APP = 0x8000
    WM_TRAYICON = WM_APP + 101
    WM_CLOSE = 0x0010
    WM_DESTROY = 0x0002
    WM_LBUTTONUP = 0x0202
    WM_LBUTTONDBLCLK = 0x0203
    WM_RBUTTONUP = 0x0205
    WM_NULL = 0x0000

    NIM_ADD = 0x00000000
    NIM_MODIFY = 0x00000001
    NIM_DELETE = 0x00000002
    NIM_SETVERSION = 0x00000004
    NIF_MESSAGE = 0x00000001
    NIF_ICON = 0x00000002
    NIF_TIP = 0x00000004
    NOTIFYICON_VERSION_4 = 4

    TPM_LEFTALIGN = 0x0000
    TPM_BOTTOMALIGN = 0x0020
    TPM_RIGHTBUTTON = 0x0002  # 兼容常量；托盘菜单不再使用它，确保右键不能选中菜单项。
    TPM_RETURNCMD = 0x0100
    MF_STRING = 0x00000000

    CMD_EXIT = 1002
    TRAY_UID = 0x5A5A01

    class NOTIFYICONDATAW(ctypes.Structure):
        _fields_ = [
            ("cbSize", ctypes.c_uint32),
            ("hWnd", ctypes.c_void_p),
            ("uID", ctypes.c_uint32),
            ("uFlags", ctypes.c_uint32),
            ("uCallbackMessage", ctypes.c_uint32),
            ("hIcon", ctypes.c_void_p),
            ("szTip", ctypes.c_wchar * 128),
            ("dwState", ctypes.c_uint32),
            ("dwStateMask", ctypes.c_uint32),
            ("szInfo", ctypes.c_wchar * 256),
            ("uTimeoutOrVersion", ctypes.c_uint32),
            ("szInfoTitle", ctypes.c_wchar * 64),
            ("dwInfoFlags", ctypes.c_uint32),
            ("guidItem", ctypes.c_ubyte * 16),
            ("hBalloonIcon", ctypes.c_void_p),
        ]

    def __init__(self, action_queue, icon_path="", icon_handle=None, pet_name="珠珠"):
        self.action_queue = action_queue
        self.icon_path = str(icon_path or "")
        self.icon_handle = icon_handle
        self.pet_name = str(pet_name or "珠珠")
        self.thread = None
        self.stop_event = threading.Event()
        self.ready_event = threading.Event()
        self.hwnd = 0
        self.hicon = 0
        self._icon_added = False
        self._wndproc_ref = None
        self._class_name = "PETZhuSystemTray_%x" % id(self)

    @staticmethod
    def _configure_user32(user32, wintypes):
        user32.RegisterClassW.argtypes = [ctypes.c_void_p]
        user32.RegisterClassW.restype = wintypes.ATOM

        user32.CreateWindowExW.argtypes = [
            wintypes.DWORD, wintypes.LPCWSTR, wintypes.LPCWSTR, wintypes.DWORD,
            ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int,
            wintypes.HWND, wintypes.HMENU, wintypes.HINSTANCE, wintypes.LPVOID,
        ]
        user32.CreateWindowExW.restype = wintypes.HWND

        user32.DestroyWindow.argtypes = [wintypes.HWND]
        user32.DestroyWindow.restype = wintypes.BOOL
        user32.DefWindowProcW.argtypes = [wintypes.HWND, wintypes.UINT, ctypes.c_size_t, ctypes.c_ssize_t]
        user32.DefWindowProcW.restype = ctypes.c_ssize_t
        user32.PostQuitMessage.argtypes = [ctypes.c_int]
        user32.PostQuitMessage.restype = None
        user32.PostMessageW.argtypes = [wintypes.HWND, wintypes.UINT, ctypes.c_size_t, ctypes.c_ssize_t]
        user32.PostMessageW.restype = wintypes.BOOL
        user32.GetMessageW.argtypes = [ctypes.POINTER(wintypes.MSG), wintypes.HWND, wintypes.UINT, wintypes.UINT]
        user32.GetMessageW.restype = wintypes.BOOL
        user32.TranslateMessage.argtypes = [ctypes.POINTER(wintypes.MSG)]
        user32.TranslateMessage.restype = wintypes.BOOL
        user32.DispatchMessageW.argtypes = [ctypes.POINTER(wintypes.MSG)]
        user32.DispatchMessageW.restype = ctypes.c_ssize_t
        user32.UnregisterClassW.argtypes = [wintypes.LPCWSTR, wintypes.HINSTANCE]
        user32.UnregisterClassW.restype = wintypes.BOOL
        user32.SetForegroundWindow.argtypes = [wintypes.HWND]
        user32.SetForegroundWindow.restype = wintypes.BOOL
        user32.GetCursorPos.argtypes = [ctypes.POINTER(wintypes.POINT)]
        user32.GetCursorPos.restype = wintypes.BOOL
        user32.CreatePopupMenu.argtypes = []
        user32.CreatePopupMenu.restype = wintypes.HMENU
        user32.AppendMenuW.argtypes = [wintypes.HMENU, wintypes.UINT, ctypes.c_size_t, wintypes.LPCWSTR]
        user32.AppendMenuW.restype = wintypes.BOOL
        user32.TrackPopupMenu.argtypes = [
            wintypes.HMENU, wintypes.UINT, ctypes.c_int, ctypes.c_int,
            ctypes.c_int, wintypes.HWND, ctypes.c_void_p,
        ]
        user32.TrackPopupMenu.restype = wintypes.UINT
        user32.DestroyMenu.argtypes = [wintypes.HMENU]
        user32.DestroyMenu.restype = wintypes.BOOL

    @staticmethod
    def _configure_shell32(shell32, wintypes):
        shell32.Shell_NotifyIconW.argtypes = [wintypes.DWORD, ctypes.c_void_p]
        shell32.Shell_NotifyIconW.restype = wintypes.BOOL

    @staticmethod
    def _configure_kernel32(kernel32, wintypes):
        kernel32.GetModuleHandleW.argtypes = [wintypes.LPCWSTR]
        kernel32.GetModuleHandleW.restype = wintypes.HINSTANCE

    def start(self):
        if os.name != "nt":
            return False
        if self.thread and self.thread.is_alive():
            return True
        self.stop_event.clear()
        self.ready_event.clear()
        self.hwnd = 0
        self._icon_added = False
        self.thread = threading.Thread(target=self._thread_main, name="PETZhuSystemTray", daemon=True)
        self.thread.start()
        self.ready_event.wait(timeout=3.0)
        return bool(self.hwnd and self._icon_added and self.thread.is_alive())

    def set_pet_name(self, pet_name):
        self.pet_name = str(pet_name or "珠珠")
        if not self.hwnd or not self._icon_added or os.name != "nt":
            return
        try:
            nid = self.NOTIFYICONDATAW()
            nid.cbSize = ctypes.sizeof(self.NOTIFYICONDATAW)
            nid.hWnd = ctypes.c_void_p(int(self.hwnd))
            nid.uID = self.TRAY_UID
            nid.uFlags = self.NIF_TIP
            nid.szTip = "桌宠"
            ctypes.windll.shell32.Shell_NotifyIconW(self.NIM_MODIFY, ctypes.byref(nid))
        except Exception:
            pass

    def stop(self):
        self.stop_event.set()
        hwnd = int(self.hwnd or 0)
        if hwnd:
            try:
                user32 = ctypes.windll.user32
                from ctypes import wintypes
                user32.PostMessageW.argtypes = [wintypes.HWND, wintypes.UINT, ctypes.c_size_t, ctypes.c_ssize_t]
                user32.PostMessageW.restype = wintypes.BOOL
                user32.PostMessageW(hwnd, self.WM_CLOSE, 0, 0)
            except Exception:
                pass
        t = self.thread
        if t and t.is_alive() and t is not threading.current_thread():
            try:
                t.join(timeout=2.0)
            except Exception:
                pass
        self.thread = None
        self.hwnd = 0
        self._icon_added = False

    @staticmethod
    def _load_icon(icon_path, fallback_handle=0):
        try:
            from ctypes import wintypes
            user32 = ctypes.windll.user32
            user32.LoadImageW.argtypes = [
                wintypes.HINSTANCE, wintypes.LPCWSTR, wintypes.UINT,
                ctypes.c_int, ctypes.c_int, wintypes.UINT,
            ]
            user32.LoadImageW.restype = wintypes.HANDLE
            if icon_path and os.path.isfile(icon_path):
                IMAGE_ICON = 1
                LR_LOADFROMFILE = 0x00000010
                LR_DEFAULTSIZE = 0x00000040
                hicon = user32.LoadImageW(None, icon_path, IMAGE_ICON, 0, 0,
                                           LR_LOADFROMFILE | LR_DEFAULTSIZE)
                if hicon:
                    return int(hicon)
        except Exception:
            pass

        if getattr(sys, "frozen", False):
            try:
                from ctypes import wintypes
                shell32 = ctypes.windll.shell32
                shell32.ExtractIconExW.argtypes = [
                    wintypes.LPCWSTR, ctypes.c_int,
                    ctypes.POINTER(wintypes.HICON), ctypes.POINTER(wintypes.HICON), wintypes.UINT,
                ]
                shell32.ExtractIconExW.restype = wintypes.UINT
                exe_path = os.path.abspath(sys.executable)
                large = wintypes.HICON()
                small = wintypes.HICON()
                count = shell32.ExtractIconExW(exe_path, 0,
                                               ctypes.byref(large), ctypes.byref(small), 1)
                if count:
                    handle = large.value or small.value
                    if handle:
                        return int(handle)
            except Exception:
                pass

        try:
            handle = int(fallback_handle or 0)
            if handle:
                return handle
        except Exception:
            pass

        # 最后兜底：使用 Windows 自带应用图标，保证“托盘功能本身”仍可工作。
        # 正常情况下不会走到这里；zhu.ico / EXE 内嵌图标优先级更高。
        try:
            from ctypes import wintypes
            user32 = ctypes.windll.user32
            user32.LoadIconW.argtypes = [wintypes.HINSTANCE, wintypes.LPCWSTR]
            user32.LoadIconW.restype = wintypes.HICON
            IDI_APPLICATION = ctypes.c_void_p(32512)
            hicon = user32.LoadIconW(None, IDI_APPLICATION)
            if hicon:
                return int(hicon)
        except Exception:
            pass
        return 0

    def _thread_main(self):
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        shell32 = ctypes.windll.shell32
        kernel32 = ctypes.windll.kernel32

        hwnd = 0
        hinstance = 0
        registered = False
        try:
            self._configure_user32(user32, wintypes)
            self._configure_shell32(shell32, wintypes)
            self._configure_kernel32(kernel32, wintypes)

            WNDPROC = ctypes.WINFUNCTYPE(
                ctypes.c_ssize_t,
                wintypes.HWND,
                wintypes.UINT,
                ctypes.c_size_t,
                ctypes.c_ssize_t,
            )

            def wnd_proc(hwnd_arg, msg, wparam, lparam):
                try:
                    if msg == self.WM_TRAYICON:
                        mouse_msg = int(lparam) & 0xFFFF
                        if mouse_msg in (self.WM_LBUTTONUP, self.WM_LBUTTONDBLCLK):
                            self.action_queue.put("show")
                            return 0
                        if mouse_msg == self.WM_RBUTTONUP:
                            self._show_menu(hwnd_arg)
                            return 0
                    elif msg == self.WM_CLOSE:
                        self._delete_icon()
                        user32.DestroyWindow(hwnd_arg)
                        return 0
                    elif msg == self.WM_DESTROY:
                        user32.PostQuitMessage(0)
                        return 0
                except Exception:
                    pass
                return user32.DefWindowProcW(hwnd_arg, msg, wparam, lparam)

            self._wndproc_ref = WNDPROC(wnd_proc)

            class WNDCLASSW(ctypes.Structure):
                _fields_ = [
                    ("style", wintypes.UINT),
                    ("lpfnWndProc", WNDPROC),
                    ("cbClsExtra", ctypes.c_int),
                    ("cbWndExtra", ctypes.c_int),
                    ("hInstance", wintypes.HINSTANCE),
                    ("hIcon", wintypes.HICON),
                    ("hCursor", wintypes.HICON),
                    ("hbrBackground", wintypes.HBRUSH),
                    ("lpszMenuName", wintypes.LPCWSTR),
                    ("lpszClassName", wintypes.LPCWSTR),
                ]

            hinstance = kernel32.GetModuleHandleW(None)
            if not hinstance:
                self.ready_event.set()
                return

            wc = WNDCLASSW()
            wc.style = 0
            wc.lpfnWndProc = self._wndproc_ref
            wc.cbClsExtra = 0
            wc.cbWndExtra = 0
            wc.hInstance = hinstance
            wc.hIcon = None
            wc.hCursor = None
            wc.hbrBackground = None
            wc.lpszMenuName = None
            wc.lpszClassName = self._class_name

            atom = user32.RegisterClassW(ctypes.byref(wc))
            if not atom:
                err = ctypes.get_last_error()
                if err != 1410:  # ERROR_CLASS_ALREADY_EXISTS
                    self.ready_event.set()
                    return
            else:
                registered = True

            WS_EX_TOOLWINDOW = 0x00000080
            hwnd = user32.CreateWindowExW(
                WS_EX_TOOLWINDOW,
                self._class_name,
                "PETZhuTrayHost",
                0,
                0, 0, 0, 0,
                None, None, hinstance, None,
            )
            if not hwnd:
                self.ready_event.set()
                return

            self.hwnd = int(hwnd)
            # 明确标记托盘宿主为工具窗口，绝不创建任务栏按钮。
            try:
                GWL_EXSTYLE = -20
                get_long = user32.GetWindowLongW
                set_long = user32.SetWindowLongW
                get_long.argtypes = [wintypes.HWND, ctypes.c_int]
                get_long.restype = wintypes.LONG
                set_long.argtypes = [wintypes.HWND, ctypes.c_int, wintypes.LONG]
                set_long.restype = wintypes.LONG
                exstyle = int(get_long(hwnd, GWL_EXSTYLE))
                exstyle |= 0x00000080  # WS_EX_TOOLWINDOW
                exstyle &= ~0x00040000  # WS_EX_APPWINDOW
                set_long(hwnd, GWL_EXSTYLE, exstyle)
            except Exception:
                pass
            self.hicon = self._load_icon(self.icon_path, self.icon_handle)
            if not self.hicon:
                self.ready_event.set()
                return

            nid = self.NOTIFYICONDATAW()
            nid.cbSize = ctypes.sizeof(self.NOTIFYICONDATAW)
            nid.hWnd = ctypes.c_void_p(hwnd)
            nid.uID = self.TRAY_UID
            nid.uFlags = self.NIF_MESSAGE | self.NIF_ICON | self.NIF_TIP
            nid.uCallbackMessage = self.WM_TRAYICON
            nid.hIcon = ctypes.c_void_p(self.hicon)
            nid.szTip = "桌宠"

            added = shell32.Shell_NotifyIconW(self.NIM_ADD, ctypes.byref(nid))
            if not added:
                self._icon_added = False
                self.ready_event.set()
                return

            self._icon_added = True
            # 告诉 Shell 使用现代回调行为。
            version_nid = self.NOTIFYICONDATAW()
            version_nid.cbSize = ctypes.sizeof(self.NOTIFYICONDATAW)
            version_nid.hWnd = ctypes.c_void_p(hwnd)
            version_nid.uID = self.TRAY_UID
            # 字段名兼容下方定义的标准结构名。
            version_nid.uTimeoutOrVersion = self.NOTIFYICON_VERSION_4
            shell32.Shell_NotifyIconW(self.NIM_SETVERSION, ctypes.byref(version_nid))

            self.ready_event.set()
            msg = wintypes.MSG()
            while not self.stop_event.is_set():
                result = user32.GetMessageW(ctypes.byref(msg), None, 0, 0)
                if result == 0 or result == -1:
                    break
                user32.TranslateMessage(ctypes.byref(msg))
                user32.DispatchMessageW(ctypes.byref(msg))

        except Exception:
            self.ready_event.set()
        finally:
            try:
                self._delete_icon()
            except Exception:
                pass
            try:
                if hwnd:
                    user32.DestroyWindow(hwnd)
            except Exception:
                pass
            try:
                if registered and hinstance:
                    user32.UnregisterClassW(self._class_name, hinstance)
            except Exception:
                pass
            self.hwnd = 0

    def _delete_icon(self):
        if not getattr(self, "_icon_added", False):
            return
        try:
            from ctypes import wintypes
            nid = self.NOTIFYICONDATAW()
            nid.cbSize = ctypes.sizeof(self.NOTIFYICONDATAW)
            nid.hWnd = ctypes.c_void_p(int(self.hwnd or 0))
            nid.uID = self.TRAY_UID
            ctypes.windll.shell32.Shell_NotifyIconW(self.NIM_DELETE, ctypes.byref(nid))
        except Exception:
            pass
        self._icon_added = False

    def _show_menu(self, hwnd):
        """将右键事件转交给 Tk 主线程，显示可自定义样式的托盘菜单。"""
        try:
            from ctypes import wintypes
            user32 = ctypes.windll.user32
            pt = wintypes.POINT()
            if not user32.GetCursorPos(ctypes.byref(pt)):
                pt.x, pt.y = 0, 0
            # Tk 控件只能在主线程创建；这里只传递屏幕坐标，不创建原生丑菜单。
            self.action_queue.put(("menu", int(pt.x), int(pt.y)))
            try:
                user32.SetForegroundWindow(hwnd)
                user32.PostMessageW(hwnd, self.WM_NULL, 0, 0)
            except Exception:
                pass
        except Exception:
            try:
                self.action_queue.put(("menu", 0, 0))
            except Exception:
                pass


def _setup_windows_taskbar_icon(root):
    """兼容旧代码保留的任务栏图标辅助函数；当前桌宠不调用它，避免产生任务栏按钮。"""
    if os.name != "nt":
        return
    try:
        import ctypes
        from ctypes import wintypes

        user32 = ctypes.windll.user32
        shell32 = ctypes.windll.shell32

        # 给进程设置稳定的AppUserModelID，避免Windows把它识别成临时工具窗口。
        try:
            set_app_id = user32.SetCurrentProcessExplicitAppUserModelID
            set_app_id.argtypes = [wintypes.LPCWSTR]
            set_app_id.restype = ctypes.c_long
            set_app_id("PETZhu.Zhu.DesktopPet")
        except Exception:
            pass

        try:
            root.update_idletasks()
        except Exception:
            pass
        hwnd = int(root.winfo_id())
        if not hwnd:
            return

        # overrideredirect窗口容易带有WS_EX_TOOLWINDOW；改为普通AppWindow后即可出现在任务栏。
        GWL_EXSTYLE = -20
        WS_EX_TOOLWINDOW = 0x00000080
        WS_EX_APPWINDOW = 0x00040000
        try:
            get_long = user32.GetWindowLongW
            set_long = user32.SetWindowLongW
            get_long.argtypes = [wintypes.HWND, ctypes.c_int]
            get_long.restype = wintypes.LONG
            set_long.argtypes = [wintypes.HWND, ctypes.c_int, wintypes.LONG]
            set_long.restype = wintypes.LONG
            exstyle = int(get_long(hwnd, GWL_EXSTYLE))
            exstyle = (exstyle & ~WS_EX_TOOLWINDOW) | WS_EX_APPWINDOW
            set_long(hwnd, GWL_EXSTYLE, exstyle)
        except Exception:
            pass

        icon_path = _find_app_icon_path()
        hicon = None
        if icon_path:
            try:
                IMAGE_ICON = 1
                LR_LOADFROMFILE = 0x00000010
                LR_DEFAULTSIZE = 0x00000040
                load_image = user32.LoadImageW
                load_image.argtypes = [wintypes.HINSTANCE, wintypes.LPCWSTR, wintypes.UINT, ctypes.c_int, ctypes.c_int, wintypes.UINT]
                load_image.restype = wintypes.HANDLE
                hicon = load_image(None, icon_path, IMAGE_ICON, 0, 0, LR_LOADFROMFILE | LR_DEFAULTSIZE)
            except Exception:
                hicon = None

        # 单文件EXE只有一个文件时，从EXE自身提取图标，不要求用户旁边再放zhu.ico。
        if not hicon and getattr(sys, "frozen", False):
            try:
                exe_path = os.path.abspath(sys.executable)
                extract = shell32.ExtractIconExW
                extract.argtypes = [wintypes.LPCWSTR, ctypes.c_int, ctypes.POINTER(wintypes.HICON), ctypes.POINTER(wintypes.HICON), wintypes.UINT]
                extract.restype = wintypes.UINT
                large = wintypes.HICON()
                small = wintypes.HICON()
                if extract(exe_path, 0, ctypes.byref(large), ctypes.byref(small), 1):
                    hicon = large.value or small.value
            except Exception:
                hicon = None

        if icon_path:
            try:
                root.iconbitmap(icon_path)
            except Exception:
                pass

        if hicon:
            WM_SETICON = 0x0080
            ICON_SMALL = 0
            ICON_BIG = 1
            # 保留句柄，避免Python垃圾回收后Windows任务栏图标失效。
            root._windows_taskbar_hicon = hicon
            send_message = user32.SendMessageW
            send_message.argtypes = [wintypes.HWND, wintypes.UINT, ctypes.c_size_t, ctypes.c_ssize_t]
            send_message.restype = ctypes.c_ssize_t
            send_message(hwnd, WM_SETICON, ICON_BIG, hicon)
            send_message(hwnd, WM_SETICON, ICON_SMALL, hicon)

        # 样式变化后通知Windows重新计算任务栏按钮。
        try:
            SWP_NOSIZE = 0x0001
            SWP_NOMOVE = 0x0002
            SWP_NOZORDER = 0x0004
            SWP_FRAMECHANGED = 0x0020
            user32.SetWindowPos(hwnd, 0, 0, 0, 0, 0, SWP_NOSIZE | SWP_NOMOVE | SWP_NOZORDER | SWP_FRAMECHANGED)
        except Exception:
            pass
    except Exception:
        pass


