def _normalize_persona_dialogue_probability(value, default=100):
    """把人设对白触发概率规范为 0–100 的整数百分比。"""
    try:
        number = int(round(float(value)))
    except (TypeError, ValueError, OverflowError):
        try:
            number = int(default)
        except Exception:
            number = 100
    return max(0, min(100, number))


