# 工具函数
# ============================================================

def get_data_dir():
    """返回当前应用自己的数据目录。

    普通主程序仍将数据放在 EXE 同目录，兼容既有配置。
    由“生成角色名.exe”创建的副本带有同名 *_data 目录和标记文件；这些副本改用
    独立数据目录，从而不会读写原 EXE 的 config、历史、故事存档或人设图片。
    """
    if getattr(sys, "frozen", False):
        exe_path = os.path.abspath(sys.executable)
        exe_dir = os.path.dirname(exe_path)
        exe_name = os.path.basename(exe_path)
        stem = os.path.splitext(exe_name)[0]
        private_dir = os.path.join(exe_dir, stem + "_data")
        marker_path = os.path.join(private_dir, ".petzhu_persona_app.json")
        try:
            with open(marker_path, "r", encoding="utf-8") as marker_file:
                marker = json.load(marker_file)
            if (isinstance(marker, dict)
                    and marker.get("format") == "PETZhu-Persona-App-Data"
                    and os.path.normcase(str(marker.get("exe_name", ""))) == os.path.normcase(exe_name)):
                return private_dir
        except Exception:
            pass
        return exe_dir
    try:
        return os.path.dirname(os.path.abspath(__file__))
    except Exception:
        return os.getcwd()


def find_asset(filename):
    candidates = []
    if getattr(sys, "frozen", False):
        candidates.append(os.path.join(os.path.dirname(sys.executable), filename))
        if hasattr(sys, "_MEIPASS"):
            candidates.append(os.path.join(sys._MEIPASS, filename))
    try:
        candidates.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), filename))
    except Exception:
        pass
    candidates.append(os.path.join(os.getcwd(), filename))
    for c in candidates:
        if os.path.isfile(c):
            return c
    return candidates[0]


def lerp_color(c1, c2, t):
    r = int(c1[0] + (c2[0] - c1[0]) * t)
    g = int(c1[1] + (c2[1] - c1[1]) * t)
    b = int(c1[2] + (c2[2] - c1[2]) * t)
    return "#%02x%02x%02x" % (max(0, min(255, r)), max(0, min(255, g)), max(0, min(255, b)))


def hex_to_rgb(h):
    h = h.lstrip("#")
    return (int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16))


def harden_alpha(img, threshold=140, trans_rgb=(0, 255, 1)):
    img = img.convert("RGBA")
    r, g, b, a = img.split()
    a_bin = a.point(lambda v: 255 if v >= threshold else 0, mode="L")
    trans_layer = Image.new("RGB", img.size, trans_rgb)
    rgb = img.convert("RGB")
    result_rgb = Image.composite(rgb, trans_layer, a_bin)
    result = result_rgb.convert("RGBA")
    result.putalpha(a_bin)
    return result


def squeeze_image(base_img, squash, trans_rgb):
    w, h = base_img.size
    nh = max(1, int(h * (1 - squash)))
    nw = max(1, int(w * (1 + squash * 0.55)))
    tmp = base_img.resize((nw, nh), Image.LANCZOS)
    canvas = Image.new("RGBA", (w, h), (trans_rgb[0], trans_rgb[1], trans_rgb[2], 0))
    off_x = (w - nw) // 2
    off_y = h - nh
    canvas.paste(tmp, (off_x, off_y), tmp)
    canvas = harden_alpha(canvas, threshold=ALPHA_THRESHOLD, trans_rgb=trans_rgb)
    return canvas


def _is_english_text(text):
    """仅把纯 ASCII 英文/数字/空白/标点视为英文，避免改变中文及中英混排规则。"""
    text = str(text or "")
    return bool(text) and any(c.isalpha() for c in text) and all(c.isascii() or c.isspace() for c in text)


def split_sentences(text):
    if not text:
        return []
    text = text.replace("\r", " ").replace("\n", " ")
    text = re.sub(r"\s+", " ", text).strip()
    text = text.replace("**", "").replace("```", "").strip()
    parts = re.split(r"(?<=[。！？!?…～~;；])", text)
    result = []
    for p in parts:
        p = p.strip()
        if not p:
            continue
        # 中文及中英混排仍保持原来的45字符上限；纯英文单独提高到68字符。
        limit = 68 if _is_english_text(p) else 45
        while len(p) > limit:
            result.append(p[:limit])
            p = p[limit:]
        if p:
            result.append(p)
    return result[:4] if result else [text]


