class RaidScaledCanvas(tk.Canvas):
    """战斗UI专用Canvas。所有内部绘图使用1400×900设计坐标。

    最大化时只给整个战斗UI一个统一的缩放比例；Canvas坐标、线宽、字体、
    dash/arrowshape等绘图参数一起缩放，因此场地不会发生横纵向拉伸。
    """
    def __init__(self, master=None, *args, scale_getter=None, **kwargs):
        self._raid_scale_getter = scale_getter
        self._raid_canvas_fonts = {}
        super().__init__(master, *args, **kwargs)

    def _scale(self):
        try:
            s = float(self._raid_scale_getter()) if self._raid_scale_getter else 1.0
        except Exception:
            s = 1.0
        return max(0.05, s)

    def _coords(self, coords):
        s = self._scale()
        return tuple(float(v) * s for v in coords)

    def _opts(self, kwargs):
        s = self._scale()
        out = dict(kwargs)
        if isinstance(out.get("text"), str):
            try:
                out["text"] = _ACTIVE_PET_NAME_TRANSFORM(out["text"])
            except Exception:
                pass
        if "width" in out:
            try:
                out["width"] = max(1, int(round(float(out["width"]) * s)))
            except Exception:
                pass
        for key in ("dash", "arrowshape"):
            if key in out and isinstance(out[key], (tuple, list)):
                vals = []
                for v in out[key]:
                    try:
                        vals.append(max(1, int(round(float(v) * s))) )
                    except Exception:
                        vals.append(v)
                out[key] = tuple(vals)
        if "font" in out:
            out["font"] = self._scaled_font(out["font"], s)
        return out

    def _scaled_font(self, font_spec, scale):
        # Canvas绝大多数调用使用("微软雅黑", 9, "bold")这类字体元组。
        # 直接改元组中的字号，避免每次重绘创建Tk命名字体导致重绘/销毁阻塞。
        if not isinstance(font_spec, (tuple, list)) or len(font_spec) < 2:
            return font_spec
        out = list(font_spec)
        try:
            size = int(out[1])
            scaled_size = max(1, int(round(abs(size) * float(scale))))
            if size < 0:
                scaled_size = -scaled_size
            out[1] = scaled_size
            return tuple(out)
        except Exception:
            return font_spec


    def create_arc(self, *coords, **kwargs):
        return super().create_arc(*self._coords(coords), **self._opts(kwargs))

    def create_line(self, *coords, **kwargs):
        return super().create_line(*self._coords(coords), **self._opts(kwargs))

    def create_oval(self, *coords, **kwargs):
        return super().create_oval(*self._coords(coords), **self._opts(kwargs))

    def create_rectangle(self, *coords, **kwargs):
        return super().create_rectangle(*self._coords(coords), **self._opts(kwargs))

    def create_text(self, *coords, **kwargs):
        return super().create_text(*self._coords(coords), **self._opts(kwargs))

    def create_polygon(self, *coords, **kwargs):
        return super().create_polygon(*self._coords(coords), **self._opts(kwargs))



class RaidVirtualWidget:
    """战斗界面的无窗口控件模型。

    只保存文本、颜色、命令和设计坐标，不创建Tk子窗口；因此这些控件没有
    不透明背景，也不会遮住底层战斗场景。实际视觉统一由同一个Canvas绘制。
    """
    def __init__(self, master=None, text="", command=None, **kwargs):
        self.master = master
        self.options = dict(kwargs)
        try:
            text = _ACTIVE_PET_NAME_TRANSFORM(str(text))
        except Exception:
            pass
        self.options["text"] = text
        self.command = command
        self.x = float(kwargs.get("x", 0.0) or 0.0)
        self.y = float(kwargs.get("y", 0.0) or 0.0)
        self.width = float(kwargs.get("width", 0.0) or 0.0)
        self.height = float(kwargs.get("height", 0.0) or 0.0)
        self.visible = True
        self._relx = None
        self._rely = None
        self._anchor = "nw"
        self._grid = None

    def config(self, cnf=None, **kwargs):
        if isinstance(cnf, dict):
            kwargs.update(cnf)
        if "command" in kwargs:
            self.command = kwargs.pop("command")
        for k, v in kwargs.items():
            if k == "text" and isinstance(v, str):
                try:
                    v = _ACTIVE_PET_NAME_TRANSFORM(v)
                except Exception:
                    pass
            self.options[k] = v
        return None
    configure = config

    def cget(self, key):
        if key == "command":
            return self.command
        return self.options.get(key, "")

    def invoke(self):
        if self.command and str(self.options.get("state", "normal")) != "disabled":
            return self.command()
        return None

    def place(self, *args, **kwargs):
        if args:
            return None
        self.visible = True
        self._relx = kwargs.get("relx", None)
        self._rely = kwargs.get("rely", None)
        self._anchor = kwargs.get("anchor", "nw")
        if "x" in kwargs: self.x = float(kwargs["x"])
        if "y" in kwargs: self.y = float(kwargs["y"])
        if "width" in kwargs: self.width = float(kwargs["width"])
        if "height" in kwargs: self.height = float(kwargs["height"])
        return None

    place_configure = place

    def place_forget(self, *args, **kwargs):
        self.visible = False

    def pack(self, *args, **kwargs):
        self.visible = True
        return None
    pack_configure = pack
    def pack_forget(self, *args, **kwargs):
        self.visible = False

    def grid(self, *args, **kwargs):
        self.visible = True
        self._grid = dict(kwargs)
        return None
    grid_configure = grid
    def grid_remove(self, *args, **kwargs):
        self.visible = False
    def grid_forget(self, *args, **kwargs):
        self.visible = False
        self._grid = None

    def lift(self, *args, **kwargs):
        return None
    tkraise = lift

    def lower(self, *args, **kwargs):
        return None

    def winfo_exists(self): return 1
    def winfo_ismapped(self): return 1 if self.visible else 0
    def winfo_x(self): return int(round(self.x))
    def winfo_y(self): return int(round(self.y))
    def winfo_width(self): return int(round(self.width))
    def winfo_height(self): return int(round(self.height))
    def winfo_rootx(self):
        try: return int(self.master.winfo_rootx() + self.x)
        except Exception: return int(self.x)
    def winfo_rooty(self):
        try: return int(self.master.winfo_rooty() + self.y)
        except Exception: return int(self.y)
    def destroy(self): self.visible = False
    def focus_force(self): return None


class RaidVirtualText(RaidVirtualWidget):
    def __init__(self, master=None, **kwargs):
        super().__init__(master, **kwargs)
        self.content = ""
        self.state = "normal"

    def delete(self, *args, **kwargs):
        self.content = ""
    def insert(self, index, text, *args, **kwargs):
        self.content = str(text)
    def get(self, *args, **kwargs):
        return self.content
    def see(self, *args, **kwargs): return None
    def config(self, cnf=None, **kwargs):
        if isinstance(cnf, dict): kwargs.update(cnf)
        if "state" in kwargs: self.state = kwargs["state"]
        return super().config(**kwargs)


class RaidUnifiedCanvas:
    """把原先多个战斗Canvas投影到同一个实际Canvas。

    所有坐标仍保持1400×900设计坐标；绘制时统一加上最大化缩放和留白偏移。
    """
    def __init__(self, owner, root_canvas, x=0, y=0, width=0, height=0, clear_all=False):
        self.owner = owner
        self.root = root_canvas
        self.x = float(x); self.y = float(y)
        self.width = float(width); self.height = float(height)
        self.clear_all = bool(clear_all)
        self._ids = set()
        self._bindings = []
        if not hasattr(owner, "_unified_canvases"):
            owner._unified_canvases = []
        owner._unified_canvases.append(self)

    def _scale(self):
        return max(0.05, float(getattr(self.owner, "_ui_scale", 1.0)))
    def _offset(self):
        return (float(getattr(self.owner, "_ui_offset_x", 0.0)),
                float(getattr(self.owner, "_ui_offset_y", 0.0)))
    def _point(self, x, y):
        s=self._scale(); ox,oy=self._offset()
        return ox+(self.x+float(x))*s, oy+(self.y+float(y))*s
    def _coords(self, coords):
        out=[]
        for i,v in enumerate(coords):
            if i % 2 == 0:
                px, _ = self._point(v, 0); out.append(px)
            else:
                _, py = self._point(0, v); out.append(py)
        return tuple(out)
    def _font(self, spec):
        if not isinstance(spec,(tuple,list)) or len(spec)<2: return spec
        out=list(spec)
        try:
            size=int(out[1]); z=max(1,int(round(abs(size)*self._scale())))
            out[1] = -z if size<0 else z
        except Exception: pass
        return tuple(out)
    def _opts(self, kwargs):
        s=self._scale(); out=dict(kwargs)
        if "width" in out:
            try: out["width"]=max(1,int(round(float(out["width"])*s)))
            except Exception: pass
        for key in ("dash","arrowshape"):
            if isinstance(out.get(key),(tuple,list)):
                vals=[]
                for v in out[key]:
                    try: vals.append(max(1,int(round(float(v)*s))))
                    except Exception: vals.append(v)
                out[key]=tuple(vals)
        if "font" in out: out["font"]=self._font(out["font"])
        return out
    def _create(self, method, *coords, **kwargs):
        cid=getattr(self.root, method)(*self._coords(coords), **self._opts(kwargs))
        self._ids.add(cid)
        return cid
    def create_arc(self,*coords,**kwargs): return self._create("create_arc",*coords,**kwargs)
    def create_line(self,*coords,**kwargs): return self._create("create_line",*coords,**kwargs)
    def create_oval(self,*coords,**kwargs): return self._create("create_oval",*coords,**kwargs)
    def create_rectangle(self,*coords,**kwargs): return self._create("create_rectangle",*coords,**kwargs)
    def create_text(self,*coords,**kwargs): return self._create("create_text",*coords,**kwargs)
    def create_polygon(self,*coords,**kwargs): return self._create("create_polygon",*coords,**kwargs)
    def create_image(self,*coords,**kwargs): return self._create("create_image",*coords,**kwargs)
    def itemconfig(self, item, **kwargs):
        return self.root.itemconfig(item, **kwargs)
    itemconfigure=itemconfig
    def coords(self, item, *coords):
        if coords: return self.root.coords(item, *self._coords(coords))
        return self.root.coords(item)
    def delete(self, item):
        if item == "all":
            if self.clear_all:
                try: self.root.delete("all")
                except Exception: pass
                for p in getattr(self.owner,"_unified_canvases",[]): p._ids.clear()
            else:
                for cid in list(self._ids):
                    try: self.root.delete(cid)
                    except Exception: pass
                self._ids.clear()
            return
        try: self.root.delete(item)
        except Exception: pass
        self._ids.discard(item)
    def configure(self, cnf=None, **kwargs):
        if isinstance(cnf,dict): kwargs.update(cnf)
        if kwargs.get("bg") is not None and self.clear_all:
            return self.root.configure(**kwargs)
        return None
    config=configure

    def _wrap_event(self, event):
        """把真实根 Canvas 的像素坐标转换回当前虚拟 Canvas 的设计坐标。"""
        s=self._scale(); ox,oy=self._offset()
        e2=type("RaidEvent", (), {})()
        try:
            e2.__dict__.update(event.__dict__)
        except Exception:
            pass
        try:
            e2.x=(event.x-ox)/s-self.x
            e2.y=(event.y-oy)/s-self.y
        except Exception:
            e2.x=0; e2.y=0
        try:
            e2.x_root=event.x_root; e2.y_root=event.y_root
        except Exception:
            pass
        return e2

    def bind(self, sequence=None, func=None, add=None):
        if func is None: return None
        def wrapped(event):
            e2=self._wrap_event(event)
            if not (0 <= e2.x <= self.width and 0 <= e2.y <= self.height):
                return None
            return func(e2)
        bid=self.root.bind(sequence,wrapped,add=("+" if add else None))
        self._bindings.append((sequence,bid))
        return bid

    def tag_bind(self, tag_or_id, sequence=None, func=None, add=None):
        """兼容 Tk Canvas.tag_bind；绑定发生在根 Canvas，但事件坐标仍返回本虚拟 Canvas坐标。"""
        if func is None:
            return self.root.tag_bind(tag_or_id, sequence)
        def wrapped(event):
            e2=self._wrap_event(event)
            if not (0 <= e2.x <= self.width and 0 <= e2.y <= self.height):
                return None
            return func(e2)
        return self.root.tag_bind(tag_or_id, sequence, wrapped, add=("+" if add else None))

    def bbox(self, tag_or_id):
        """返回当前虚拟 Canvas 的设计坐标 bbox。"""
        try:
            box=self.root.bbox(tag_or_id)
        except Exception:
            return None
        if not box:
            return None
        s=self._scale(); ox,oy=self._offset()
        x0,y0,x1,y1=box
        return ((x0-ox)/s-self.x, (y0-oy)/s-self.y,
                (x1-ox)/s-self.x, (y1-oy)/s-self.y)

    def tag_unbind(self, tag_or_id, sequence=None, funcid=None):
        try:
            return self.root.tag_unbind(tag_or_id, sequence, funcid)
        except Exception:
            return None

    def winfo_rootx(self):
        try: return self.owner.win.winfo_rootx()+int(round(self.x*self._scale()))+int(round(self._offset()[0]))
        except Exception: return int(self.x)
    def winfo_rooty(self):
        try: return self.owner.win.winfo_rooty()+int(round(self.y*self._scale()))+int(round(self._offset()[1]))
        except Exception: return int(self.y)
    def winfo_width(self): return int(round(self.width*self._scale()))
    def winfo_height(self): return int(round(self.height*self._scale()))
    def winfo_ismapped(self): return 1
    def update_idletasks(self):
        try: self.root.update_idletasks()
        except Exception: pass

class RaidUnit(object):

    def __init__(self, name, role, x, y, color):
        self.name = name
        self.role = role
        self.x = float(x)
        self.y = float(y)
        self.maxhp = 320.0 if role == "tank" else 200.0
        self.hp = self.maxhp
        self.shield = 0.0
        self.shield_layers = {"player": 0.0, "pure": 0.0, "barrier": 0.0, "consolation": 0.0, "adlo_extra": 0.0}
        self.maxhp_bonus_timer = 0.0
        self.maxhp_bonus_ratio = 0.0
        self.heal_received_bonus = 0.0
        self.expedient_timer = 0.0
        self.fey_illumination_timer = 0.0
        self.fairy_embrace_timer = 0.0
        self.move_speed_bonus_timer = 0.0
        self.alive = True
        self.color = color
        self.tx = float(x)
        self.ty = float(y)
        self.react_t = 0.0
        self.flash = 0.0
        self.death_timer = 0.0
        self.death_count = 0
        self.rez_invuln_timer = 0.0
        self.mp = 10000.0
        self.mp_max = 10000.0
        self.mp_regen_timer = 3.0
        self.job = None
        self.cd_single = 0.0
        self.cd_group = 0.0
        self.rez_cd = 0.0
        self.rez_cast_timer = 0.0
        self.rez_target = None
        self.action_timer = 0.0
        self.rez_cast_x = float(x)
        self.rez_cast_y = float(y)
        self.move_dx = 0.0
        self.move_dy = 0.0
        # 双人塔失败后的全场流血：10秒，每秒20点。
        self.bleed_timer = 0.0
        self.bleed_tick_timer = 0.0
        # AI危险区检测：默认每0.1秒刷新一次。
        self.ai_danger_check_timer = 0.0
        self.ai_in_danger = False
        self.ai_danger_mech = None
        # “属性赋予”机制状态：单一主属性Buff + 剩余时间。
        self.element_buff = None
        self.element_buff_timer = 0.0
        self.element_ever_had_buff = False
        self.elemental_dash = None
        # 属性赋予-绝：与原“属性赋予”完全独立的状态空间。
        self.absolute_primary = None
        # 教学阶段允许同一队员同时持有光二与影二；
        # 第二属性槽仅用于绝版机制，普通“属性赋予”不使用。
        self.absolute_secondary_primary = None
        self.absolute_native = False
        self.absolute_fire_seed_stacks = 0
        self.absolute_wind_up_stacks = 0
        self.absolute_wind_mark_stacks = 0
        self.absolute_wind_rest_timer = 0.0
        # 风技能结算后的1秒“站位保持”，直到28m击退动画完成。
        self.absolute_wind_hold_until = 0.0
        self.absolute_thunder_stacks = 0
        self.absolute_wrong_thunder_stacks = 0
        self.absolute_electrified = False
        self.absolute_knockback = None
        # 同一目标可被上下两个风源依次命中；排队处理，避免一次风击退多人。
        self.absolute_pending_wind_knockbacks = []
        self.absolute_wind_next_stage = None
        # 击退完成后的真实落点保持：直到下一张图切换前，不再被普通AI路线拉回。
        self.absolute_wind_landing_hold_until = 0.0
        self.absolute_wind_landing_pos = None
        self.absolute_facing = -math.pi / 2.0
        self.absolute_light_wind_taken = False
        self.absolute_light_fire_taken = False
        self.absolute_shadow_fire_taken = False
        self.absolute_shadow_wind_taken = False
        self.absolute_wind_last_target = None
        self.absolute_wind_event_lock_until = 0.0
        self.absolute_fire_escape_until = 0.0
        self.absolute_fire_escape_target = None
        # 台球机制临时物理状态（仅在“球台”机制中使用）。
        self.pool_pocketed = False
        self.pool_vx = 0.0
        self.pool_vy = 0.0
        self.pool_dead = False
        self.pool_death_pos = None

    def damage_multiplier(self):
        # 复活后的伤害衰减是“对Boss输出降低”，不是受到伤害降低。
        if self.death_timer <= 0:
            return 1.0
        stacks = min(self.death_count, 2)
        return max(0.5, 1.0 - 0.25 * stacks)

    def incoming_damage_multiplier(self):
        # MT/ST 常驻减伤；只影响受到的伤害。
        return 0.8 if self.role == "tank" else 1.0

    def base_dps(self):
        if self.role == "tank":
            return 4.0
        if self.role == "healer":
            return 2.5
        if self.role == "dps":
            return 10.5
        if self.role == "player":
            return 8.0
        return 0.0


class RaidGame(object):

    ARENA_R_M = 20.0
    PPM = 12.0
    # 在上一版基础上，战斗场地再整体下移150px。
    CX, CY = 460, 435
    CW, CH = 830, 530

    PLAYER_SPEED = 6.2
    AI_SPEED = 5.8
    ARENA_LIMIT = 19.4

    # “球台”机制：单位为当前战斗世界坐标。
    POOL_TABLE_HALF_W = 16.5
    POOL_TABLE_HALF_H = 9.3
    POOL_BALL_R = 0.55
    POOL_POCKET_R = 1.42
    # v33：增强击打感与碰撞反馈，同时缩短同等力度的蓄力时间。
    POOL_FRICTION = 1.65
    POOL_RESTITUTION = 0.975
    POOL_BALL_RESTITUTION = 1.00
    # 球台速度：在上一版基础上进一步提高基础速度和最大速度。
    POOL_BASE_SPEED = 9.0
    POOL_MAX_SPEED = 85.0
    POOL_MIN_SPEED = 0.06
    POOL_MAX_CHARGE = 3.0
    # 前2秒用于按键状态的角度积分；超过2秒后继续蓄力只增加力度，不再改变方向。
    POOL_DIRECTION_WINDOW = 2.0
    # 球台碰撞伤害：8 × diff × 2。
    POOL_COLLISION_DAMAGE = 18.0
    POOL_IMPACT_FX_MULT = 1.0
    # 球台机制期间禁用的小仙女/炽天使相关技能。
    POOL_DISABLED_SKILLS = {
        "summon_eos", "dissipation", "whispering_dawn", "fey_illum",
        "fey_blessing", "sacred_soil", "seraph", "seraphism", "consolation",
    }

    BOSS_MAX_HP = 7000.0
    # 全员存活理论最高持续输出：基础团队60.5 + 以太超流驱动的能量吸收长期平均1.8 = 62.3 DPS。
    THEORETICAL_MAX_DPS = 62.3
    ENRAGE_TIME = 120.0  # 狂暴读条开始时间120秒
    ENRAGE_CAST = 8.0
    MECH_SCALE_STEP = 0.045
    MECH_SCALE_CAP = 1.65
    MECH_DAMAGE_MULT = 2.0

    # 属性赋予-绝专用固定伤害；不影响普通“属性赋予”。
    ABSOLUTE_WIND_DAMAGE = 120.0
    ABSOLUTE_FAN_DAMAGE = 120.0
    ABSOLUTE_FIRE_MARK_DAMAGE = 120.0
    ABSOLUTE_ELECTRIC_DAMAGE = 120.0
    ABSOLUTE_THUNDER_DAMAGE = 120.0
    ABSOLUTE_PAIR_DAMAGE = 30.0
    ABSOLUTE_LIGHT_SHADOW_CANCEL_DAMAGE = 60.0
    ABSOLUTE_CANCEL_RADIUS = 3.0

    REZ_MP = 2400.0
    REZ_CAST = 8.0
    REZ_WINDOW = 40.0
    SCHOLAR_CAST = 2.0
    SCHOLAR_CAST_GRACE = 1.5
    # 兼容旧治疗UI与充能字段，避免不同入口初始化顺序导致AttributeError。
    cd_group_heal = 0.0
    cd_single_heal = 0.0
    group_heal_charges = 2
    single_heal_charges = 3
    group_heal_charge_timers = None
    single_heal_charge_timers = None

    def __init__(self, parent):
        self.parent = parent
        self.closed = False
        self.keys = set()
        # 战斗界面的设计分辨率固定为1400×900。最大化时只改变整体scale，
        # 不改变任何元素的逻辑坐标；外层窗口承载多余的留白背景。
        self.BASE_UI_W = 1400
        self.BASE_UI_H = 900
        self._ui_scale = 1.0
        self._maximized = False
        self._raid_widget_bases = {}
        self._raid_widget_fonts = {}
        self._raid_geometry_scalers_installed = False
        # 正在把“原始布局”应用到当前缩放尺寸时，不允许布局包装器
        # 把已经缩放后的数值再次写回基准记录，否则最大化/还原往返会累积误差。
        self._raid_applying_geometry = False
        self.camera_follow = True
        # 战斗场地整体屏幕偏移（仅影响绘制与点击映射，不改变任何世界坐标）。
        self._arena_view_offset_x = 0.0
        self._arena_view_offset_y = 0.0
        self._arena_position_controls_open = False
        self._arena_position_step = 15.0
        # 仅用于测试属性赋予-绝的固定AI路线；关闭时玩家仍完全手动。
        self.player_auto_route = False
        self.zoom = 1.0
        self.base_ppm = float(self.PPM)
        self.zoom_min = 0.65
        self.zoom_max = 3.00
        self.target_is_boss = False
        self.last_player_target = None

        self.win = tk.Toplevel(parent)
        # 高难小游戏主窗口及所有后代控件/Canvas/弹出窗口均排除主题色相调整，
        # 保持战斗界面、技能颜色、AOE绘图及机制提示按原代码显示。
        self.win._petzhu_theme_hue_exempt = True
        self.win._petzhu_raid_ui = True
        # Windows 色键透明会让抗锯齿文字产生彩边/重影。
        # 这里改为与战斗场地一致的无边框底色，让所有文字直接正常绘制。
        self.ui_transparent_color = "#0d1420"
        # Tkinter Canvas 不支持逐项 RGBA 填充。
        # 使用内置 gray12 点阵模拟约 80% 透明度，避免自定义 BitmapImage
        # 在窗口重绘/资源回收后出现 “pyimageXXX not defined” 的问题。
        self._aoe_stipple = "gray50"
        self._ime_captured = False
        self._ime_original_hkl = None
        self._ime_original_open = None
        self._ime_original_conv = 0
        self._ime_original_sent = 0
        self._ime_outside_active = False
        self._restore_refresh_after_id = None
        self._capture_original_input_method()

        self.win.title("高难度讨伐歼灭战 · 学者珠珠")
        self.win.configure(bg="#070b12")
        self.win.resizable(False, False)
        self.win.attributes("-topmost", True)
        self.win.protocol("WM_DELETE_WINDOW", self.close)

        # 战前机制顺序：{轮次: 机制组ID}。未设置的轮次默认为随机。
        self.mech_order = {}
        self._load_mechanic_order()
        self.skill_defs = self._make_skill_defs()
        self._load_skill_layout()
        self._build_ui()
        self._bgm_init()
        self._update_bgm_controls()
        self._reset()

        self.win.bind("<KeyPress>", self._on_key_down)
        self.win.bind("<KeyRelease>", self._on_key_up)
        # Tkinter 的按钮/Canvas 默认会截获 Tab 焦点切换，窗口级 KeyPress 有时无法真正收到。
        # 使用 bind_all 捕获 Tab，并仅在本战斗窗口获得焦点时处理。
        self._tab_bind_id = self.win.bind_all("<KeyPress-Tab>", self._on_tab_global, add="+")
        self.win.bind("<Button-3>", self._on_global_right_click, add="+")
        self.win.bind("<MouseWheel>", self._on_mouse_wheel_zoom, add="+")
        self.win.bind("<Button-4>", self._on_mouse_wheel_zoom, add="+")
        self.win.bind("<Button-5>", self._on_mouse_wheel_zoom, add="+")
        self.win.bind("<FocusIn>", self._on_raid_focus_in, add="+")
        # 鼠标拖拽的力度在拖动过程中实时计算；这里不进行任何预发射。
        self.pool_aiming = False
        # 台球鼠标输入改为全局捕获：避免Canvas/其他控件的Button绑定抢占拖拽事件。
        self._pool_mouse_bind_press = self.win.bind_all("<ButtonPress-1>", self._on_pool_global_press, add="+")
        self._pool_mouse_bind_drag = self.win.bind_all("<B1-Motion>", self._on_pool_global_drag, add="+")
        self._pool_mouse_bind_release = self.win.bind_all("<ButtonRelease-1>", self._on_pool_global_release, add="+")
        self.win.bind("<FocusOut>", self._on_raid_focus_out, add="+")
        self.win.bind("<Unmap>", self._on_raid_unmap, add="+")
        self.win.bind("<Map>", self._on_window_restore, add="+")
        self._max_bind_id = self.win.bind_all("<F11>", self._on_f11_global, add="+")
        self.win.after(100, self._focus)
        self.win.after_idle(self._position_boss_header)

        self._last = time.time()
        self.win.after(25, self._tick)
        self.win.after(80, self._poll_foreground_input_method)

    # --------------------------------------------------------
    # BGM 音乐
    # --------------------------------------------------------
    def _bgm_init(self):
        """初始化高难小游戏BGM。

        普通战斗：每局从 a/b/c/d 四首中随机选择一首，并在整局内无缝循环这一首。
        例如本局抽到 a.wav，则本局始终为 a.wav -> a.wav -> a.wav -> ……。
        属性赋予-绝：切换为 1.wav，仅播放一次；结束后恢复本局已经选定的普通BGM。
        2.wav 保留为一次性音乐接口，目前不绑定到未指定机制。
        BGM默认开启，默认音量80%；开关和音量设置都会保存到程序同级的 bgm_settings.json。
        BGM启停和场景切换使用淡入淡出。
        """
        self._bgm_available = False
        self._bgm_dir = os.path.dirname(
            os.path.abspath(sys.executable if getattr(sys, "frozen", False) else __file__)
        )
        self._bgm_settings_path = os.path.join(self._bgm_dir, "bgm_settings.json")

        # 没有保存过设置时：默认开启、默认音量80%。
        self._bgm_user_enabled = True
        self._bgm_volume = 0.80
        self._bgm_load_settings()

        self._bgm_loop_files = ["a.wav", "b.wav", "c.wav", "d.wav"]
        # 本局从 a/b/c/d 随机抽中的普通BGM；一局内始终循环这一首。
        self._bgm_loop_file = None
        self._bgm_mode = "stopped"
        self._bgm_after_id = None
        self._bgm_generation = 0
        self._bgm_current_file = None
        self._bgm_scene = "normal"
        self._bgm_missing_notice = set()
        self._bgm_fade_ms = 750
        self._bgm_fade_in_next = True

        if pygame is None or os.name != "nt":
            return
        try:
            if not _ensure_pygame_mixer():
                return
            pygame.mixer.music.set_volume(self._bgm_volume)
            self._bgm_available = True
        except Exception:
            self._bgm_available = False

    def _bgm_load_settings(self):
        """读取BGM持久化设置；首次运行或文件损坏时使用默认值。"""
        try:
            with open(self._bgm_settings_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                if "enabled" in data:
                    self._bgm_user_enabled = bool(data.get("enabled"))
                if "volume" in data:
                    self._bgm_volume = max(0.0, min(1.0, float(data.get("volume"))))
        except Exception:
            self._bgm_user_enabled = True
            self._bgm_volume = 0.80

    def _bgm_save_settings(self):
        """保存BGM开关和音量，下一次启动程序继续使用。"""
        try:
            payload = {
                "enabled": bool(self._bgm_user_enabled),
                "volume": round(float(self._bgm_volume), 2),
            }
            tmp_path = self._bgm_settings_path + ".tmp"
            with open(tmp_path, "w", encoding="utf-8") as f:
                json.dump(payload, f, ensure_ascii=False, indent=2)
            os.replace(tmp_path, self._bgm_settings_path)
        except Exception:
            pass

    def _bgm_path(self, filename):
        # Source mode: use files beside the .py. One-file mode: fall back to
        # PyInstaller's temporary bundle directory so embedded WAV files work.
        return find_asset(filename)

    def _bgm_update_volume_display(self):
        if hasattr(self, "bgm_volume_label"):
            try:
                self.bgm_volume_label.config(text="BGM %d%%" % int(round(self._bgm_volume * 100)))
            except Exception:
                pass

    def _update_bgm_controls(self):
        """刷新BGM按钮文字/状态。"""
        if hasattr(self, "bgm_toggle_btn"):
            enabled = bool(getattr(self, "_bgm_user_enabled", True))
            try:
                self.bgm_toggle_btn.config(
                    text="BGM：开" if enabled else "BGM：关",
                    bg="#2f6f4e" if enabled else "#3a5472",
                    activebackground="#3c8d63" if enabled else "#4b6d92",
                )
            except Exception:
                pass
        self._bgm_update_volume_display()

    def _bgm_note_missing(self, filename):
        if filename in self._bgm_missing_notice:
            return
        self._bgm_missing_notice.add(filename)
        try:
            self._toast("未找到BGM：%s（放到oc.py同级文件夹即可）" % filename)
        except Exception:
            pass

    def _bgm_cancel_after(self):
        after_id = self._bgm_after_id
        self._bgm_after_id = None
        if after_id is not None:
            try:
                self.win.after_cancel(after_id)
            except Exception:
                pass

    def _bgm_stop(self, fade_ms=0):
        """停止BGM。fade_ms>0时使用淡出。"""
        self._bgm_generation += 1
        self._bgm_cancel_after()
        self._bgm_mode = "stopped"
        self._bgm_current_file = None
        if self._bgm_available:
            try:
                if fade_ms > 0 and pygame.mixer.music.get_busy():
                    pygame.mixer.music.fadeout(int(fade_ms))
                else:
                    pygame.mixer.music.stop()
            except Exception:
                pass

    def _bgm_fade_transition(self, callback, fade_ms=None):
        """先淡出当前音乐，再执行callback；用于普通BGM/绝BGM场景切换。"""
        if self.closed or not self._bgm_available or not self._bgm_user_enabled:
            return
        if fade_ms is None:
            fade_ms = self._bgm_fade_ms
        self._bgm_generation += 1
        generation = self._bgm_generation
        self._bgm_cancel_after()
        self._bgm_mode = "transition"
        try:
            busy = pygame.mixer.music.get_busy()
        except Exception:
            busy = False
        if not busy:
            callback(generation)
            return
        try:
            pygame.mixer.music.fadeout(int(fade_ms))
        except Exception:
            pass
        self._bgm_after_id = self.win.after(
            int(fade_ms) + 50,
            lambda g=generation: callback(g) if (not self.closed and g == self._bgm_generation) else None
        )

    def _bgm_get_random_loop_file(self):
        """从 a/b/c/d 中随机选择本局使用的一首普通BGM。"""
        available = [
            filename for filename in self._bgm_loop_files
            if os.path.isfile(self._bgm_path(filename))
        ]
        if not available:
            for filename in self._bgm_loop_files:
                self._bgm_note_missing(filename)
            return None
        return random.choice(available)

    def _bgm_play_loop_track(self, generation=None, fade_in=True):
        """播放本局已经选定的普通BGM；歌曲结束后继续播放同一个文件。"""
        if self.closed or not self._bgm_available or not self._bgm_user_enabled:
            return
        if generation is not None and generation != self._bgm_generation:
            return
        if self._bgm_mode != "loop":
            return

        filename = self._bgm_loop_file
        if not filename or not os.path.isfile(self._bgm_path(filename)):
            filename = self._bgm_get_random_loop_file()
            if not filename:
                expected_generation = self._bgm_generation
                self._bgm_after_id = self.win.after(
                    1000, lambda g=expected_generation: self._bgm_play_loop_track(g, True)
                )
                return
            self._bgm_loop_file = filename

        path = self._bgm_path(filename)
        try:
            pygame.mixer.music.load(path)
            pygame.mixer.music.set_volume(self._bgm_volume)
            # fade_ms 以这里的音量作为淡入目标；不能先把目标音量设成0。
            # 使用pygame原生无限循环，确保同一首歌无缝衔接，不在每次循环间产生100ms轮询空窗。
            pygame.mixer.music.play(loops=-1, fade_ms=(self._bgm_fade_ms if fade_in else 0))
            self._bgm_current_file = filename
        except Exception:
            self._bgm_current_file = None
            expected_generation = self._bgm_generation
            self._bgm_after_id = self.win.after(
                1000, lambda g=expected_generation: self._bgm_play_loop_track(g, True)
            )

    def _bgm_poll_loop_track(self, generation):
        """轮询普通BGM播放状态；一首结束后继续播放本局已经选定的同一首。"""
        if self.closed or generation != self._bgm_generation or self._bgm_mode != "loop":
            return
        if not self._bgm_user_enabled or not self._bgm_available:
            return
        self._bgm_after_id = None
        try:
            busy = pygame.mixer.music.get_busy()
        except Exception:
            busy = False
        if busy:
            self._bgm_after_id = self.win.after(
                100, lambda g=generation: self._bgm_poll_loop_track(g)
            )
            return
        # 当前歌曲自然结束，继续播放本局选定的同一首；循环衔接不再重复淡入。
        self._bgm_play_loop_track(generation, fade_in=False)

    def _bgm_start_playlist_now(self, generation):
        if self.closed or not self._bgm_available or not self._bgm_user_enabled:
            return
        if generation != self._bgm_generation:
            return
        self._bgm_after_id = None
        self._bgm_mode = "loop"
        self._bgm_play_loop_track(generation, fade_in=True)

    def _bgm_start_playlist(self, reset=False, fade=True):
        """启动本局普通BGM；每局从 a/b/c/d 随机选择一首并整局单曲循环。"""
        self._bgm_scene = "normal"
        if self.closed or not self._bgm_available or not self._bgm_user_enabled:
            return
        # reset=True 表示开始新的一局，此时重新随机一次；恢复时不重新随机。
        if reset or not self._bgm_loop_file:
            self._bgm_loop_file = self._bgm_get_random_loop_file()
        if not self._bgm_loop_file:
            return
        if fade:
            self._bgm_fade_transition(
                lambda g: self._bgm_start_playlist_now(g),
                self._bgm_fade_ms,
            )
        else:
            self._bgm_generation += 1
            self._bgm_cancel_after()
            self._bgm_start_playlist_now(self._bgm_generation)

    def _bgm_play_one_shot_now(self, filename, generation, resume_playlist=False):
        if self.closed or not self._bgm_available or not self._bgm_user_enabled:
            return False
        if generation != self._bgm_generation:
            return False
        path = self._bgm_path(filename)
        if not os.path.isfile(path):
            self._bgm_note_missing(filename)
            if resume_playlist:
                self._bgm_start_playlist(reset=False, fade=False)
            return False

        self._bgm_after_id = None
        self._bgm_mode = "one_shot"
        try:
            pygame.mixer.music.load(path)
            # 1.wav/2.wav进入时淡入；先设置最终目标音量，再让 pygame 从静音状态淡入。
            pygame.mixer.music.set_volume(self._bgm_volume)
            # 自然播放完毕后不额外制造淡出空档。
            pygame.mixer.music.play(loops=0, fade_ms=self._bgm_fade_ms)
            self._bgm_current_file = filename
            expected_generation = self._bgm_generation
            self._bgm_after_id = self.win.after(
                100, lambda g=expected_generation, r=resume_playlist: self._bgm_poll_one_shot(g, r)
            )
            return True
        except Exception:
            self._bgm_mode = "stopped"
            self._bgm_current_file = None
            if resume_playlist:
                self._bgm_start_playlist(reset=False, fade=False)
            return False

    def _bgm_play_one_shot(self, filename, resume_playlist=False, fade_transition=True):
        if self.closed or not self._bgm_available or not self._bgm_user_enabled:
            return False
        # 先检查目标文件，再进行淡出切歌；1.wav缺失时保留当前普通BGM。
        if not os.path.isfile(self._bgm_path(filename)):
            self._bgm_note_missing(filename)
            return False
        if fade_transition:
            self._bgm_fade_transition(
                lambda g: self._bgm_play_one_shot_now(filename, g, resume_playlist),
                self._bgm_fade_ms,
            )
            return True
        self._bgm_generation += 1
        self._bgm_cancel_after()
        return self._bgm_play_one_shot_now(filename, self._bgm_generation, resume_playlist)

    def _bgm_poll_one_shot(self, generation, resume_playlist):
        if self.closed or generation != self._bgm_generation or self._bgm_mode != "one_shot":
            return
        self._bgm_after_id = None
        try:
            busy = pygame.mixer.music.get_busy()
        except Exception:
            busy = False
        if busy:
            self._bgm_after_id = self.win.after(
                100, lambda g=generation, r=resume_playlist: self._bgm_poll_one_shot(g, r)
            )
            return
        self._bgm_mode = "stopped"
        self._bgm_current_file = None
        if resume_playlist and self._bgm_user_enabled:
            self._bgm_start_playlist(reset=False, fade=False)

    def _bgm_start_absolute(self):
        """进入属性赋予-绝时播放1.wav一次，并淡出当前普通BGM。"""
        self._bgm_scene = "absolute"
        if self.closed or not self._bgm_available or not self._bgm_user_enabled:
            return
        self._bgm_play_one_shot("1.wav", resume_playlist=False, fade_transition=True)

    def _bgm_resume_after_absolute(self):
        """属性赋予-绝结束后恢复本局已经选定的普通单曲循环BGM，并淡入。"""
        if self.closed or not self._bgm_user_enabled:
            return
        self._bgm_scene = "normal"
        self._bgm_start_playlist(reset=False, fade=True)

    def _bgm_play_2_once(self):
        """2.wav一次性音乐入口；目前仅保留为预留接口。"""
        return self._bgm_play_one_shot("2.wav", resume_playlist=True, fade_transition=True)

    def _bgm_toggle(self):
        """BGM开关。关闭时淡出；打开时按当前战斗场景淡入对应BGM。"""
        if not self._bgm_available:
            self._toast("BGM功能不可用：请确认已安装 pygame，并使用Windows运行。")
            return
        if self._bgm_user_enabled:
            self._bgm_user_enabled = False
            self._bgm_stop(fade_ms=self._bgm_fade_ms)
        else:
            self._bgm_user_enabled = True
            if self._bgm_scene == "absolute":
                self._bgm_play_one_shot("1.wav", resume_playlist=False, fade_transition=True)
            else:
                self._bgm_start_playlist(reset=False, fade=True)
        self._bgm_save_settings()
        self._update_bgm_controls()

    def _bgm_change_volume(self, delta):
        """BGM音量按10%步进调整，范围0%~100%。"""
        self._bgm_volume = max(0.0, min(1.0, round(self._bgm_volume + delta, 2)))
        if self._bgm_available:
            try:
                pygame.mixer.music.set_volume(self._bgm_volume)
            except Exception:
                pass
        self._bgm_save_settings()
        self._update_bgm_controls()

