    def _unified_design_xy(self, event):
        s=max(0.05,float(getattr(self,"_ui_scale",1.0)))
        ox=float(getattr(self,"_ui_offset_x",0.0)); oy=float(getattr(self,"_ui_offset_y",0.0))
        return (event.x-ox)/s, (event.y-oy)/s

    def _virtual_widget_is_visible(self, obj):
        """统一Canvas命中检测必须同时考虑控件自身及所有虚拟父容器的可见状态。

        单Canvas改造后，原来Tk子窗口的“父Frame隐藏=>子Button也不接收鼠标”行为已经不存在。
        如果只看子Button.visible，隐藏的复活/放弃/结算按钮会在底层继续抢走点击，导致“开始战斗”看起来点不动。
        """
        cur = obj
        seen = set()
        while cur is not None and id(cur) not in seen:
            seen.add(id(cur))
            if not getattr(cur, "visible", True):
                return False
            cur = getattr(cur, "master", None)
        return True

    def _ui_button_hit(self, x, y):
        for obj in reversed(getattr(self,"_ui_control_registry",[])):
            if getattr(obj,"command",None) is None: continue
            if not self._virtual_widget_is_visible(obj): continue
            w=max(0.0,float(getattr(obj,"width",0.0))); h=max(0.0,float(getattr(obj,"height",0.0)))
            if w<=0 or h<=0: continue
            ox=float(getattr(obj,"x",0.0)); oy=float(getattr(obj,"y",0.0))
            if ox <= x <= ox+w and oy <= y <= oy+h:
                return obj
        return None

    def _unified_control_hit(self, x, y):
        """统一Canvas点击命中：所有真实按钮/弹窗按钮优先于战斗场地与球台输入。"""
        # 弹窗/确认区域按钮优先；这些按钮即使不在普通底部按钮组里，也必须可点。
        priority=(getattr(self,"ai_rez_yes_btn",None), getattr(self,"ai_rez_no_btn",None),
                  getattr(self,"pool_swap_player_btn",None), getattr(self,"pool_swap_h1_btn",None),
                  getattr(self,"replay_pause_btn",None), getattr(self,"replay_speed_05_btn",None),
                  getattr(self,"replay_speed_1_btn",None), getattr(self,"replay_speed_2_btn",None),
                  getattr(self,"replay_speed_5_btn",None), getattr(self,"replay_exit_btn",None),
                  getattr(self,"result_restart_btn",None), getattr(self,"result_exit_btn",None),
                  getattr(self,"result_log_btn",None), getattr(self,"result_replay_btn",None),
                  getattr(self,"arena_position_btn",None), getattr(self,"arena_pos_up_btn",None),
                  getattr(self,"arena_pos_down_btn",None), getattr(self,"arena_pos_left_btn",None),
                  getattr(self,"arena_pos_right_btn",None), getattr(self,"arena_pos_reset_btn",None),
                  getattr(self,"arena_pos_close_btn",None), *getattr(self,"possession_vote_buttons",[]))
        for obj in priority:
            if obj is None or not self._virtual_widget_is_visible(obj) or getattr(obj,"command",None) is None:
                continue
            ox,oy,w,h=float(getattr(obj,"x",0)),float(getattr(obj,"y",0)),float(getattr(obj,"width",0)),float(getattr(obj,"height",0))
            if ox<=x<=ox+w and oy<=y<=oy+h:
                return obj
        return self._ui_button_hit(x,y)

    def _on_unified_left_click(self, event):
        x,y=self._unified_design_xy(event)
        pm=getattr(self,"mech",None)
        if not getattr(self,"paused",False) and pm is not None and pm.get("possession") and self._possession_player_is_possessed(pm) and not pm.get("resolved",False):
            if math.hypot(x-360.0,y-648.0)<=48.0:
                self._possession_register_resist_input(pm); self._render(); return "break"

        # 任何时候先处理UI按钮。这样“开始战斗/战斗中”以及球台期间的底部按钮
        # 不会被球台输入分支提前吞掉。
        obj=self._unified_control_hit(x,y)
        if obj is not None:
            return obj.invoke()

        if getattr(self,"replay_mode",False):
            if 870<=x<1140 and 106<=y<636:
                e=type("RaidEvent",(),{})(); e.x=x-870; e.y=y-106
                return self._on_party_click(e)
            return "break"

        # 技能格点击。球台期间具体哪些技能禁用由 _skill_bar_left/_use_skill_by_id 判定。
        for slot,lbl in enumerate(self.skill_labels):
            if not lbl.visible: continue
            if lbl.x<=x<=lbl.x+lbl.width and lbl.y<=y<=lbl.y+lbl.height:
                return self._skill_bar_left(slot)

        # 右侧小队/ Buff 区要优先于球台输入。
        # 球台期间仍允许点选队员/查看 Buff；否则球台分支会把小队列表点击吞掉。
        if 870<=x<1140 and 106<=y<636:
            e=type("RaidEvent",(),{})(); e.x=x-870; e.y=y-106
            return self._on_party_click(e)
        if 1140<=x<1400 and 106<=y<636:
            e=type("RaidEvent",(),{})(); e.x=x-1140; e.y=y-106
            return self._on_party_buff_click(e)

        # 球台真正开始后，场地上的普通左键不再交给普通“选中队员”逻辑；
        # 击球本身由全局鼠标按下/拖动/松开处理。
        pool=getattr(self,"mech",None)
        if pool is not None and pool.get("kind")=="pool_table" and pool.get("started",False):
            return "break"
        e=type("RaidEvent",(),{})(); e.x=x; e.y=y
        return self._on_arena_click(e)

    def _on_unified_right_click(self,event):
        pm=getattr(self,"mech",None)
        if pm is not None and pm.get("possession") and self._possession_player_is_possessed(pm) and not pm.get("resolved",False):
            return "break"
        if getattr(self,"replay_mode",False):
            x,y=self._unified_design_xy(event)
            obj=self._ui_button_hit(x,y)
            if obj is not None:
                return obj.invoke()
            return "break"
        x,y=self._unified_design_xy(event)
        e=type("RaidEvent",(),{})(); e.x=x; e.y=y
        obj=self._ui_button_hit(x,y)
        if obj is not None and obj is not getattr(self,"window_max_btn",None):
            return None
        return self._on_arena_right_click(e)

    def _on_unified_double_click(self,event):
        pm=getattr(self,"mech",None)
        if pm is not None and pm.get("possession") and self._possession_player_is_possessed(pm) and not pm.get("resolved",False):
            return "break"
        if getattr(self,"replay_mode",False):
            return "break"
        x,y=self._unified_design_xy(event); e=type("RaidEvent",(),{})(); e.x=x; e.y=y
        return self._on_arena_double_click(e)

    def _render_button(self,c,obj):
        if obj is None or not getattr(obj,"visible",False): return
        x,y,w,h=obj.x,obj.y,obj.width,obj.height
        bg=obj.options.get("bg", "#334155")
        fg=obj.options.get("fg", "#ffffff")
        state=str(obj.options.get("state","normal"))
        if state=="disabled": bg="#333941"; fg="#777d86"
        c.create_rectangle(x,y,x+w,y+h,fill=bg,outline="")
        text=str(obj.options.get("text", ""))
        if text:
            c.create_text(x+w/2,y+h/2,text=text,fill=fg,font=("微软雅黑",9,"bold"))

    def _format_unified_log_text(self, text, max_lines, chars_per_line):
        """将战斗日志按Canvas实际显示宽度换行并限制行数，避免文字堆叠出面板。"""
        raw=str(text or "")
        if not raw:
            return ""
        rows=raw.splitlines() or [raw]
        wrapped=[]
        for row in rows:
            row=str(row)
            if not row:
                wrapped.append("")
                continue
            # 中文日志没有空格，直接按显示字符数切分比Canvas默认按单词换行更稳定。
            while len(row) > chars_per_line:
                wrapped.append(row[:chars_per_line])
                row=row[chars_per_line:]
            wrapped.append(row)
        if len(wrapped) > max_lines:
            wrapped=wrapped[-max_lines:]
        return "\n".join(wrapped)

    def _render_unified_ui(self):
        c=self.cv
        # 顶部Boss区 / BGM。
        c.create_text(55,12,text="",fill="#9ec8ff",font=("微软雅黑",8))
        if getattr(self,"enrage_side_label",None) is not None:
            t=str(self.enrage_side_label.options.get("text","") or "")
            if t: c.create_text(972,23,text=t,fill=self.enrage_side_label.options.get("fg","#ff6666"),font=("微软雅黑",9,"bold"))
        for name in ("bgm_toggle_btn","bgm_down_btn","bgm_up_btn"):
            self._render_button(c,getattr(self,name,None))
        v=str(getattr(self,"bgm_volume_label",None).options.get("text", "BGM 80%") if getattr(self,"bgm_volume_label",None) is not None else "BGM 80%")
        c.create_text(1306,25,text=v,fill="#dbeafe",font=("微软雅黑",8,"bold"))
        pm=getattr(self,"mech",None)
        if pm is not None and pm.get("possession") and self._possession_player_is_possessed(pm) and not pm.get("resolved",False):
            cctx=self._possession_ctx(pm); eff=max(0.0,min(1.0,float(cctx.get("resist_eff",0.0))))
            rr=48.0 + (4.0 if float(cctx.get("resist_flash_t",0.0))>0 else 0.0); cx,cy=360.0,648.0
            c.create_oval(cx-rr,cy-rr,cx+rr,cy+rr,fill="#c92d3a",outline="#ff7e86",width=3)
            c.create_text(cx,cy-5,text="反抗",fill="#ffffff",font=("微软雅黑",13,"bold")); c.create_text(cx,cy+15,text="+15%",fill="#ffe0e3",font=("微软雅黑",8,"bold"))
            bx,by,bw=220.0,685.0,280.0
            c.create_rectangle(bx,by,bx+bw,by+14,fill="#24161a",outline="#ff6570",width=1)
            c.create_rectangle(bx+1,by+1,bx+1+(bw-2)*eff,by+13,fill="#f04452",outline="")
            avg=self._possession_average_resistance(pm); ratio=self._possession_manual_ratio(pm)
            c.create_text(bx,by-9,anchor="w",text="反抗效率 %.0f%% · 平均 %.0f%% · 自主控制 %.0f%%"%(eff*100,avg*100,ratio*100),fill="#ffd7dc",font=("微软雅黑",8,"bold"))
        if pm is not None and pm.get("possession") and pm.get("phase")=="vote":
            cctx=self._possession_ctx(pm)
            if cctx and cctx.get("player_possessed"):
                c.create_text(975,655,text="你被附身：持续反抗，无需投票",fill="#ff9ea6",font=("微软雅黑",10,"bold"))
            elif cctx:
                c.create_text(975,655,text="AI已选择：%s · 请选择漏掉的一人" % "、".join(cctx.get("vote_ai_names",[])),fill="#ffd7a1",font=("微软雅黑",10,"bold"))

        # 资源、队伍、读条、Boss血条已经由各自UnifiedCanvas绘制。

        # 技能栏：技能现在是无窗口模型，必须在同一个根Canvas上真正绘制。
        # 空槽不绘制任何矩形，因此下面的战斗场地会直接透出来；已放置技能
        # 则按照原 skill_labels 的设计坐标、颜色、冷却和快捷键绘制。
        for slot, lbl in enumerate(getattr(self, "skill_labels", [])):
            if not getattr(lbl, "visible", False):
                continue
            try:
                x = float(lbl.x)
                y = float(lbl.y)
                w = max(1.0, float(lbl.width))
                h = max(1.0, float(lbl.height))
                options = getattr(lbl, "options", {}) or {}
                bg = options.get("bg", self.skill_colors.get(self._slot_skill_id(slot), "#27384a"))
                fg = options.get("fg", "#ffffff")
                state = str(options.get("state", "normal"))
                if state == "disabled":
                    bg, fg = "#4a4e55", "#969aa1"
                # 轻微边框，保持原技能格的视觉分隔；空槽完全不画。
                c.create_rectangle(x, y, x + w, y + h,
                                   fill=bg, outline="#172231", width=1)
                text = str(options.get("text", "") or "")
                if text:
                    c.create_text(x + w / 2.0, y + h / 2.0,
                                  text=text, fill=fg,
                                  font=("微软雅黑", 8, "bold"),
                                  justify="center", anchor="center",
                                  width=max(20, w - 8))
            except Exception:
                # 单个技能格绘制失败不能中断整帧UI。
                continue
        for b in getattr(self,"possession_vote_buttons",[]): self._render_button(c,b)
        # 场地位置控制只占用小队面板下方的空白区域；展开时显示四向按钮。
        if getattr(self, "arena_position_btn", None) is not None:
            self._render_button(c, self.arena_position_btn)
        if getattr(self, "_arena_position_controls_open", False):
            c.create_text(1275, 626, text="X%+g / Y%+g" % (getattr(self, "_arena_view_offset_x", 0.0), getattr(self, "_arena_view_offset_y", 0.0)), fill="#9ec8ff", font=("微软雅黑",8,"bold"))
            for name in (
                "arena_pos_up_btn", "arena_pos_down_btn", "arena_pos_left_btn",
                "arena_pos_right_btn", "arena_pos_reset_btn", "arena_pos_close_btn"
            ):
                self._render_button(c, getattr(self, name, None))

        # 战斗提示默认折叠；展开时只绘制实际有内容的面板。
        if not getattr(self,"combat_player_collapsed",True):
            panel=getattr(self,"combat_player_panel",None)
            x=float(getattr(panel,"x",33)); y=float(getattr(panel,"y",114))
            w=float(getattr(panel,"width",214)); h=float(getattr(panel,"height",520))
            c.create_rectangle(x,y,x+w,y+h,fill="#142033",stipple="gray50",outline="#6b7f99",width=1)
            c.create_text(x+8,y+12,text="战斗提示 · 珠珠",anchor="w",fill="#ffd166",font=("微软雅黑",10,"bold"))
            c.create_text(x+108,y+12,text=str(self.combat_pause_label.options.get("text","") or ""),fill="#ff8f8f",font=("微软雅黑",8,"bold"))
            # 折叠按钮固定在面板标题栏右侧，不再继承旧Frame的(0,0)坐标。
            self.combat_player_fold_btn.x=x+w-58
            self.combat_player_fold_btn.y=y+3
            self.combat_player_fold_btn.width=54
            self.combat_player_fold_btn.height=22
            self._render_button(c,self.combat_player_fold_btn)
            c.create_text(x+8,y+32,text="受到伤害 / 死亡原因",anchor="w",fill="#ffaaa8",font=("微软雅黑",8,"bold"))
            txt=self.combat_player_damage_text.content if hasattr(self.combat_player_damage_text,"content") else ""
            txt=self._format_unified_log_text(txt, max_lines=15, chars_per_line=27)
            if txt:
                c.create_text(x+8,y+50,text=txt,anchor="nw",fill="#dbeafe",
                              font=("微软雅黑",7),width=w-16)
            c.create_text(x+8,y+270,text="治疗 / 所受治疗",anchor="w",fill="#8fe1b0",font=("微软雅黑",8,"bold"))
            txt=self.combat_player_heal_text.content if hasattr(self.combat_player_heal_text,"content") else ""
            txt=self._format_unified_log_text(txt, max_lines=16, chars_per_line=27)
            if txt:
                c.create_text(x+8,y+288,text=txt,anchor="nw",fill="#dbeafe",
                              font=("微软雅黑",7),width=w-16)
        else:
            c.create_rectangle(46,77,134,105,fill="#334155",outline="")
            c.create_text(90,91,text="战斗提示",fill="#ffffff",font=("微软雅黑",10,"bold"))

        # 其他队员信息。
        if getattr(self,"combat_detail_unit",None) and getattr(self,"combat_detail_panel",None) is not None and self.combat_detail_panel.visible:
            panel=self.combat_detail_panel
            x=float(getattr(panel,"x",872)); y=float(getattr(panel,"y",170))
            w=float(getattr(panel,"width",266)); h=float(getattr(panel,"height",425))
            c.create_rectangle(x,y,x+w,y+h,fill="#142033",stipple="gray50",outline="#6b7f99")
            c.create_text(x+7,y+12,text=str(self.combat_detail_title.options.get("text","战斗信息-其他队员")),anchor="w",fill="#ffd166",font=("微软雅黑",8,"bold"))
            # 折叠按钮永远贴在面板右上角，面板宽度改变时同步移动。
            self.combat_detail_close_btn.x=x+w-58
            self.combat_detail_close_btn.y=y+3
            self.combat_detail_close_btn.width=54
            self.combat_detail_close_btn.height=22
            self._render_button(c,self.combat_detail_close_btn)
            if hasattr(self,"combat_detail_text"):
                detail_txt=self._format_unified_log_text(self.combat_detail_text.content, max_lines=34, chars_per_line=35)
                c.create_text(x+7,y+34,text=detail_txt,anchor="nw",fill="#dbeafe",
                              font=("微软雅黑",7),width=max(20,w-14))

        # 底部操作按钮。
        for name in ("layout_btn","mech_order_btn","start_btn","camera_follow_btn","player_ai_btn","window_max_btn","skill_info_btn","mech_info_btn","combat_other_button"):
            self._render_button(c,getattr(self,name,None))
        for b in getattr(self,"combat_member_buttons",{}).values():
            if b is not None and getattr(b,"visible",True) and getattr(self,"combat_detail_unit",None):
                self._render_button(c,b)
        self._render_button(c,getattr(self,"combat_detail_close_btn",None))
        if getattr(self,"status_label",None) is not None and getattr(self.status_label,"visible",True):
            sx=float(getattr(self.status_label,"x",718))
            sy=float(getattr(self.status_label,"y",842))
            sw=max(20.0,float(getattr(self.status_label,"width",360)))
            sh=max(20.0,float(getattr(self.status_label,"height",36)))
            status_text=str(self.status_label.options.get("text","") or "")
            if status_text:
                c.create_text(sx, sy+sh/2.0, text=status_text, anchor="w",
                              fill=self.status_label.options.get("fg","#9ec8ff"),
                              font=("微软雅黑",8,"bold"), width=sw-6,
                              justify="left")

        # AI复活提示：标题固定两行以内，倒计时与按钮使用独立纵向区域，避免文字互相挤压。
        if getattr(self,"ai_rez_prompt",None) is not None and getattr(self,"ai_rez_prompt_frame",None) is not None and self.ai_rez_prompt_frame.visible:
            cx=550; top=365
            c.create_rectangle(cx-240,top,cx+240,top+155,fill="#141d2c",outline="#ffd166",width=1)
            title=str(self.ai_rez_title.options.get("text","") or "")
            title=self._format_unified_log_text(title, max_lines=2, chars_per_line=22)
            c.create_text(cx,top+25,text=title,fill="#ffd166",font=("微软雅黑",11,"bold"),
                          justify="center",anchor="center",width=400)
            c.create_text(cx,top+66,text=str(self.ai_rez_countdown.options.get("text","10.0")),
                          fill="#ffcf66",font=("微软雅黑",18,"bold"),anchor="center")
            c.create_text(cx,top+92,text="是＝立刻复活　否＝放弃该局游戏",
                          fill="#cbd5e1",font=("微软雅黑",9),anchor="center")
            # 两个按钮固定在底部同一水平线上，避免标题变成两行后发生重叠。
            self.ai_rez_yes_btn.x=460; self.ai_rez_yes_btn.y=474; self.ai_rez_yes_btn.width=78; self.ai_rez_yes_btn.height=34
            self.ai_rez_no_btn.x=562; self.ai_rez_no_btn.y=474; self.ai_rez_no_btn.width=78; self.ai_rez_no_btn.height=34
            self._render_button(c,self.ai_rez_yes_btn); self._render_button(c,self.ai_rez_no_btn)

        if getattr(self,"pool_swap_choice_frame",None) is not None and self.pool_swap_choice_frame.visible:
            cx=550; top=365
            c.create_rectangle(cx-250,top,cx+250,top+135,fill="#141d2c",outline="#d8c6ff",width=1)
            c.create_text(cx,top+22,text=str(self.pool_swap_choice_title.options.get("text","")),fill="#ffd166",font=("微软雅黑",11,"bold"))
            c.create_text(cx,top+49,text=str(self.pool_swap_choice_hint.options.get("text","")),fill="#dbeafe",font=("微软雅黑",9))
            self._render_button(c,self.pool_swap_player_btn); self._render_button(c,self.pool_swap_h1_btn)

        # 暂停/结算遮罩必须覆盖整个实际窗口，而不是只覆盖1400×900设计区域。
        # 用根Canvas的真实像素尺寸绘制，再在遮罩之上绘制暂停/结算内容。
        if getattr(self,"_manual_pause_overlay",False) and self.paused and not self.game_over and not self.win_game:
            root = self._unified_root_canvas
            try:
                root.delete("raid_fullscreen_overlay")
            except Exception:
                pass
            rw=max(1,int(root.winfo_width() or root.cget("width") or 1))
            rh=max(1,int(root.winfo_height() or root.cget("height") or 1))
            root.create_rectangle(0,0,rw,rh,fill="#000000",stipple="gray50",outline="",tags="raid_fullscreen_overlay")
            c.create_text(self.CW // 2, 385, text="战 斗 暂 停",
                          fill="#ffd166", font=("微软雅黑",30,"bold"))
            c.create_text(self.CW // 2, 435, text="按空格继续",
                          fill="#e6eef8", font=("微软雅黑",14,"bold"))

        if (getattr(self,"game_over",False) or getattr(self,"win_game",False)):
            root = self._unified_root_canvas
            try:
                root.delete("raid_fullscreen_overlay")
            except Exception:
                pass
            rw=max(1,int(root.winfo_width() or root.cget("width") or 1))
            rh=max(1,int(root.winfo_height() or root.cget("height") or 1))
            root.create_rectangle(0,0,rw,rh,fill="#000000",stipple="gray50",outline="",tags="raid_fullscreen_overlay")
            if self.game_over:
                c.create_text(self.CW // 2, 370, text="全队倒下",
                              fill="#ff6666", font=("微软雅黑",30,"bold"))
                c.create_text(self.CW // 2, 420, text=self.over_reason,
                              fill="#c8d8ee", font=("微软雅黑",12))
                c.create_text(self.CW // 2, 470,
                              text="存活 %.1fs  机制 %d  Boss %.0f/%.0f"
                                   % (self.survive_t, self.mech_count,
                                      self.boss_hp, self.boss_max_hp),
                              fill="#9ec8ff", font=("微软雅黑",11))
                c.create_text(self.CW // 2, 510, text="使用下方按钮继续",
                              fill="#7a8fa8", font=("微软雅黑",10))
            else:
                c.create_text(self.CW // 2, 370, text="讨 伐 成 功",
                              fill="#5cd68a", font=("微软雅黑",28,"bold"))
                c.create_text(self.CW // 2, 420, text="Boss 已被击败",
                              fill="#c8d8ee", font=("微软雅黑",12))
                c.create_text(self.CW // 2, 470,
                              text="耗时 %.1fs  机制 %d"
                                   % (self.survive_t, self.mech_count),
                              fill="#9ec8ff", font=("微软雅黑",12))
                c.create_text(self.CW // 2, 510, text="使用下方按钮继续",
                              fill="#7a8fa8", font=("微软雅黑",10))

            rf=getattr(self,"result_frame",None)
            if rf is not None and rf.visible:
                x,y=170,550
                for b,ox in ((self.result_restart_btn,0),(self.result_log_btn,112),(self.result_replay_btn,224),(self.result_exit_btn,336)):
                    b.x=x+ox; b.y=y; b.width=105; b.height=38
                    self._render_button(c,b)

        if getattr(self,"replay_mode",False):
            current_t=float(getattr(self,"replay_elapsed",0.0)); total_t=float(getattr(self,"replay_duration",0.0))
            view=getattr(self,"_replay_view_unit",None)
            view_name=self._display_unit_name(view) if view is not None else "H2"
            state_text="回放 %.1f / %.1f秒  ·  视角：%s  ·  %s"%(current_t,total_t,view_name,"已暂停" if self.replay_paused else "播放中")
            c.create_text(self.CW//2,808,text=state_text,fill="#ffd166",font=("微软雅黑",10,"bold"),anchor="center")
            c.create_text(450,873,text="点击右侧小队成员切换队友视角 · 空格暂停/继续 · Esc退出回放",fill="#9ec8ff",font=("微软雅黑",8),anchor="w")
            for b in self.replay_controls: self._render_button(c,b)

        return None

