    def _load_skill_layout(self):
        path = os.path.join(get_data_dir(), "skill_layout.json")
        self.skill_slot_count = 27
        self.default_skill_colors = [
            "#6f8cff", "#7fc9ff", "#7fd9b0", "#5f9cff", "#6aa8ff", "#9b8cff",
            "#5eb4d8", "#c9a7ff", "#72d9a6", "#5aa9ff", "#6ec7a8", "#d6a86e",
            "#e6a35b", "#a97adf", "#68c0d8", "#77c78e", "#6fc2a1", "#d5a6ff",
            "#d78c9a", "#e38e9e", "#7fc2d9", "#86c78f", "#f09aa7", "#b6a0ff",
        ]
        self.skill_slots = [None] * self.skill_slot_count
        self.skill_order = [d["id"] for d in self.skill_defs]
        self.skill_colors = {d["id"]: self.default_skill_colors[i] for i,d in enumerate(self.skill_defs)}
        default_keys = ["1","2","3","4","5","6","7","8","9","0","f1","f2","f3","f4","f5","f6","f7","f8","f9","f10","f11","f12","-","="]
        self.skill_keys = {d["id"]: default_keys[i] for i,d in enumerate(self.skill_defs)}
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            known = {d["id"] for d in self.skill_defs}
            saved_slots = data.get("slots")
            if isinstance(saved_slots, list):
                cleaned = []
                used = set()
                for sid in saved_slots[:self.skill_slot_count]:
                    if sid in known and sid not in used:
                        cleaned.append(sid); used.add(sid)
                    else:
                        cleaned.append(None)
                cleaned += [None] * (self.skill_slot_count - len(cleaned))
                remaining = [d["id"] for d in self.skill_defs if d["id"] not in used]
                # 兼容旧版本布局：若新增技能（如“醒梦”）不在旧布局中，
                # 自动放入第一个空槽，确保新技能能出现在技能布局界面。
                for i,v in enumerate(cleaned):
                    if v is None and remaining:
                        cleaned[i] = remaining.pop(0)
                if any(v is not None for v in cleaned):
                    self.skill_slots = cleaned[:self.skill_slot_count]
            else:
                saved_order = data.get("order", [])
                if set(saved_order) == known and len(saved_order) == len(known):
                    self.skill_slots[:len(saved_order)] = saved_order
                    self.skill_order = list(saved_order)
            placed = [sid for sid in self.skill_slots if sid in known]
            if placed:
                self.skill_order = placed + [d["id"] for d in self.skill_defs if d["id"] not in placed]
            for sid, col in data.get("colors", {}).items():
                if sid in known and isinstance(col, str):
                    self.skill_colors[sid] = col
            saved_keys = data.get("keys", {})
            if isinstance(saved_keys, dict):
                for sid, key in saved_keys.items():
                    if sid in known and isinstance(key, str):
                        self.skill_keys[sid] = key.lower()
        except Exception:
            for i,d in enumerate(self.skill_defs):
                self.skill_slots[i] = d["id"]

    def _save_skill_layout(self):
        path = os.path.join(get_data_dir(), "skill_layout.json")
        data = {"slots": list(self.skill_slots), "order": [sid for sid in self.skill_slots if sid is not None], "colors": dict(self.skill_colors), "keys": dict(self.skill_keys)}
        try:
            with open(path, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            self._toast("技能布局已保存。")
            return True
        except Exception:
            self._toast("技能布局保存失败。")
            return False

    def _skill_defs_by_id(self):
        return {d["id"]: d for d in self.skill_defs}

    def _ordered_defs(self):
        by = self._skill_defs_by_id()
        return [by[sid] for sid in self.skill_slots if sid in by]

    def _slot_skill_id(self, slot):
        if 0 <= slot < len(getattr(self, "skill_slots", [])):
            return self.skill_slots[slot]
        return None

    def _placed_skill_ids(self):
        return [sid for sid in self.skill_slots if sid is not None]

    def _short_skill_name(self, sid):
        # 炽天附体期间，沿用鼓舞/意气原技能槽，动态显示追加技能名称；
        # 技能布局与键位设置仍只显示原始技能，因此不会出现额外技能。
        if getattr(self, "seraphism_timer", 0.0) > 0.0:
            if sid == "adlo":
                return "显灵之章"
            if sid == "succor":
                return "降临之章"
        return {
            "raise":"复生", "summon_eos":"朝日", "whispering_dawn":"仙光",
            "adlo":"鼓舞", "succor":"意气", "fey_illum":"幻光",
            "aetherflow":"超流", "energy_drain":"能量", "lustrate":"活性",
            "sacred_soil":"野战", "indom":"不屈", "deployment":"展开",
            "emergency":"应急", "dissipation":"转化", "excog":"深谋",
            "aetherpact":"契约", "fey_blessing":"祥光", "recitation":"秘策",
            "seraph":"炽天", "consolation":"慰藉", "protraction":"回生",
            "expedient":"疾风", "seraphism":"附体", "lucid_dreaming":"醒梦"
        }.get(sid, sid)

    def _refresh_skill_bar(self):
        if getattr(self,"replay_mode",False):
            for lbl in getattr(self,"skill_labels",[]):
                lbl.visible=False
            return
        defs_by = self._skill_defs_by_id()
        for slot, lbl in enumerate(self.skill_labels):
            sid = self._slot_skill_id(slot)
            if sid is None or sid not in defs_by:
                lbl.grid_remove()
                continue
            d = defs_by[sid]
            cd = getattr(self, "skill_cd", {}).get(sid, 0.0)
            # 就绪状态不再显示“就绪”文字；技能冷却中则使用灰色显示。
            state = "" if cd <= 0 else "%.1fs" % cd
            pool_active = (
                getattr(self, "mech", None) is not None
                and self.mech.get("kind") == "pool_table"
                and not self.mech.get("resolved", False)
            )
            extra = []
            if sid in ("aetherflow","energy_drain","lustrate","sacred_soil","indom","excog"):
                extra.append("以太%d" % getattr(self, "aetherflow", 0))
            if sid == "aetherpact":
                extra.append("异想%d" % getattr(self, "faerie_gauge", 0))
            if sid == "consolation":
                extra.append("慰%d" % getattr(self, "consolation_charges", 0))
            if d.get("cast") and getattr(self, "cast_skill", None) == sid and getattr(self, "cast_timer", 0) > 0:
                state = "读条 %.1fs" % self.cast_timer
            key_name = self.skill_keys.get(sid, "?").upper()
            parts = [x for x in extra + ([state] if state else []) if x]
            skill_disabled = (
                pool_active and (
                    sid == "energy_drain" or sid in getattr(self, "POOL_DISABLED_SKILLS", set())
                )
            )
            lbl.config(
                text="%s [%s]\n%s" % (
                    self._short_skill_name(sid), key_name,
                    " · ".join(parts + (["球台禁用"] if skill_disabled else []))
                ),
                bg=("#4a4e55" if skill_disabled else ("#5a6068" if cd > 0 else self.skill_colors.get(sid, "#27384a"))),
                fg=("#969aa1" if skill_disabled else ("#b8bdc5" if cd > 0 else "#ffffff"))
            )
            row, col = divmod(slot, self.skill_grid_cols)
            lbl.grid(row=row, column=col, padx=2, pady=2, sticky="nsew")

    def _skill_bar_left(self, slot):
        sid = self._slot_skill_id(slot)
        if not sid:
            return
        if (
            sid == "energy_drain"
            and getattr(self, "mech", None) is not None
            and self.mech.get("kind") == "pool_table"
            and not self.mech.get("resolved", False)
        ):
            self._toast("球台期间“能量吸收”不可使用。")
            return
        self._use_skill_by_id(sid)

    def _skill_bar_double(self, slot):
        if getattr(self, "prebattle", False):
            self._skill_bar_color(slot)

    def _skill_bar_color(self, slot):
        if not getattr(self, "prebattle", False):
            return
        sid = self._slot_skill_id(slot)
        if not sid:
            return
        result = colorchooser.askcolor(color=self.skill_colors.get(sid, "#27384a"), title="选择技能颜色")
        if result and result[1]:
            self.skill_colors[sid] = result[1]
            self._refresh_skill_bar()

    def _rebuild_skill_slots(self, source_sid, target_slot):
        if source_sid not in self.skill_slots:
            return
        if not (0 <= target_slot < self.skill_slot_count):
            return
        source_slot = self.skill_slots.index(source_sid)
        if source_slot == target_slot:
            return
        target_sid = self.skill_slots[target_slot]
        self.skill_slots[source_slot] = target_sid
        self.skill_slots[target_slot] = source_sid

    def open_skill_layout(self):
        if not getattr(self, "prebattle", False):
            return self._toast("战斗开始后不能修改技能布局。")
        if getattr(self, "layout_win", None) is not None and self.layout_win.winfo_exists():
            self.layout_win.lift(); return
        win = tk.Toplevel(self.win)
        self.layout_win = win
        win.title("技能布局 · 三排自由配置")
        win.configure(bg="#0d1420")
        win.resizable(False, False)
        win.transient(self.win)
        tk.Label(win, text="拖动技能到任意位置；空槽不会显示；右键修改颜色；保存后永久保留。",
                 bg="#0d1420", fg="#c8d8ee", font=("微软雅黑", 10, "bold")).pack(padx=12, pady=(10,6))
        frame=tk.Frame(win,bg="#0d1420", width=900, height=300); frame.pack(padx=10,pady=6); frame.pack_propagate(False)
        for col in range(9): frame.grid_columnconfigure(col, weight=1, minsize=96)
        for row in range(3): frame.grid_rowconfigure(row, weight=1, minsize=74)
        buttons=[]
        drag={"sid":None}
        def rebuild():
            for b in buttons: b.destroy()
            buttons.clear()
            by=self._skill_defs_by_id()
            for slot,sid in enumerate(self.skill_slots):
                if sid is None or sid not in by: continue
                r,c=divmod(slot,9)
                b=tk.Button(frame,text=self._short_skill_name(sid),bg=self.skill_colors.get(sid,"#27384a"),fg="#fff",
                             width=10,height=2,relief="raised",bd=2)
                b.grid(row=r,column=c,padx=3,pady=3,sticky="nsew")
                b._skill_id=sid
                b.bind("<Button-1>", lambda e: (drag.__setitem__("sid", e.widget._skill_id), drag.__setitem__("start", e.widget)))
                b.bind("<Button-3>", on_color)
                buttons.append(b)
        def on_release_global(e):
            sid=drag.get("sid")
            if sid is None: return
            try:
                rx=frame.winfo_rootx(); ry=frame.winfo_rooty()
                x=e.x_root-rx; y=e.y_root-ry
                if 0 <= x < frame.winfo_width() and 0 <= y < frame.winfo_height():
                    col=min(8,max(0,int(x/(frame.winfo_width()/9))))
                    row=min(2,max(0,int(y/(frame.winfo_height()/3))))
                    target=row*9+col
                    self._rebuild_skill_slots(sid,target)
                    self._refresh_skill_bar(); rebuild()
            finally:
                drag["sid"]=None
        def on_color(e):
            sid=e.widget._skill_id
            result=colorchooser.askcolor(color=self.skill_colors.get(sid,"#27384a"),title="选择技能颜色")
            if result and result[1]:
                self.skill_colors[sid]=result[1]; self._refresh_skill_bar(); rebuild()
        rebuild()
        win.bind("<ButtonRelease-1>", on_release_global, add="+")
        actions=tk.Frame(win,bg="#0d1420"); actions.pack(pady=(4,12))
        tk.Button(actions,text="保存布局",command=self._save_skill_layout,bg="#2f6f4e",fg="#fff",relief="flat",padx=14,pady=5).pack(side="left",padx=4)
        tk.Button(actions,text="自定义键位",command=self.open_keybind_config,bg="#5b547a",fg="#fff",relief="flat",padx=14,pady=5).pack(side="left",padx=4)
        tk.Button(actions,text="恢复默认",command=lambda:(self._reset_default_layout_colors(),self._refresh_skill_bar(),rebuild()),bg="#5b3340",fg="#fff",relief="flat",padx=14,pady=5).pack(side="left",padx=4)
        tk.Button(actions,text="关闭",command=win.destroy,bg="#27435f",fg="#fff",relief="flat",padx=14,pady=5).pack(side="left",padx=4)

    def open_keybind_config(self):
        if not getattr(self, "prebattle", False):
            return self._toast("战斗开始后不能修改技能键位。")
        if getattr(self, "keybind_win", None) is not None and self.keybind_win.winfo_exists():
            self.keybind_win.lift(); return
        win=tk.Toplevel(self.win); self.keybind_win=win
        win.title("技能键位")
        win.configure(bg="#0d1420"); win.geometry("640x720"); win.transient(self.win)
        tk.Label(win,text="点击“设置”后按一个键绑定。WASD、Tab、Esc保留给移动与系统功能，R可以绑定技能。",bg="#0d1420",fg="#c8d8ee",font=("微软雅黑",10,"bold"),wraplength=590,justify="left").pack(padx=14,pady=(12,8),anchor="w")
        body=tk.Frame(win,bg="#0d1420"); body.pack(fill="both",expand=True,padx=10,pady=4)
        sb=tk.Scrollbar(body); sb.pack(side="right",fill="y")
        cv=tk.Canvas(body,bg="#111a26",highlightthickness=0,yscrollcommand=sb.set); cv.pack(side="left",fill="both",expand=True); sb.config(command=cv.yview)
        inner=tk.Frame(cv,bg="#111a26"); cv.create_window((0,0),window=inner,anchor="nw")
        inner.bind("<Configure>",lambda e: cv.configure(scrollregion=cv.bbox("all")))
        pending={"sid":None}
        def refresh():
            for w in inner.winfo_children(): w.destroy()
            for d in self.skill_defs:
                row=tk.Frame(inner,bg="#182332"); row.pack(fill="x",padx=4,pady=3)
                tk.Label(row,text=self._short_skill_name(d["id"]),bg="#182332",fg="#fff",font=("微软雅黑",11,"bold"),width=10).pack(side="left",padx=6,pady=6)
                tk.Label(row,text=(self.skill_keys.get(d["id"]) or "未绑定").upper(),bg="#24364d",fg="#ffd166",font=("微软雅黑",10,"bold"),width=9).pack(side="left",padx=4)
                def choose(sid=d["id"]):
                    pending["sid"]=sid; win.focus_force(); self._toast("请按键设置："+self._short_skill_name(sid))
                tk.Button(row,text="设置",command=choose,bg="#365b7f",fg="#fff",relief="flat",padx=10).pack(side="left",padx=6)
                def clear(sid=d["id"]):
                    self.skill_keys[sid]=""; pending["sid"]=None; refresh(); self._refresh_skill_bar()
                tk.Button(row,text="清除",command=clear,bg="#5b3340",fg="#fff",relief="flat",padx=8).pack(side="left")
        def key_capture(e):
            sid=pending.get("sid")
            if sid is None: return
            k=e.keysym.lower()
            if k in ("tab","w","a","s","d","escape"): 
                self._toast("这个键被系统功能占用。")
                return "break"
            if any(other!=sid and key==k for other,key in self.skill_keys.items()):
                self._toast("该键已经绑定给其他技能。")
                return "break"
            self.skill_keys[sid]=k; pending["sid"]=None; refresh(); self._refresh_skill_bar()
            return "break"
        win.bind("<KeyPress>",key_capture,add="+")
        refresh()
        foot=tk.Frame(win,bg="#0d1420"); foot.pack(pady=(6,12))
        tk.Button(foot,text="保存键位",command=self._save_skill_layout,bg="#2f6f4e",fg="#fff",relief="flat",padx=16,pady=6).pack(side="left",padx=5)
        tk.Button(foot,text="关闭",command=win.destroy,bg="#30445d",fg="#fff",relief="flat",padx=16,pady=6).pack(side="left",padx=5)

    # --------------------------------------------------------
    # 战斗信息 / H1复活询问
    # --------------------------------------------------------
    def _position_boss_header(self):
        """让讨伐目标血条中心与默认视角下的战斗场地中点对齐。"""
        try:
            self.win.update_idletasks()
            mid=self.mid
            scale = max(0.05, float(getattr(self, "_ui_scale", 1.0)))
            arena_x_phys = (mid.winfo_x() + self.arena_left_spacer.winfo_width()
                            + (self.CW * scale / 2.0))
            boss_w = 840.0
            x = max(0.0, arena_x_phys / scale - boss_w / 2.0)
            self.boss_cv.place(x=int(round(x)), y=1, width=840, height=44)
            try:
                self.enrage_side_label.place(x=int(round(x + boss_w + 12)), y=10, height=26)
            except Exception:
                pass
            # 保存Boss血条在整个战斗窗口坐标系中的中心。
            self.boss_header_center_x = float(x) + boss_w / 2.0
        except Exception:
            pass

    def _build_combat_info_overlay(self):
        # 统一Canvas已经不再使用父子窗口自动偏移，因此这里直接保存
        # 战斗窗口坐标，避免“折叠”按钮仍按旧Frame相对坐标绘制而错位。
        self.combat_player_panel=RaidVirtualWidget(self.combat_hud,x=33,y=114,width=214,height=520)
        self.combat_pause_label=RaidVirtualWidget(self.combat_player_panel,text="")
        self.combat_player_fold_btn=RaidVirtualWidget(
            self.combat_player_panel, text="折叠", command=self._toggle_combat_player_panel,
            x=189, y=117, width=54, height=22, bg="#334155", fg="#ffffff"
        )
        self.combat_player_fold_btn.visible=False
        self.combat_player_damage_text=RaidVirtualText(self.combat_player_panel)
        self.combat_player_heal_text=RaidVirtualText(self.combat_player_panel)
        self.combat_player_text=self.combat_player_damage_text
        self.party_buff_detail_panel=RaidVirtualWidget(self.combat_hud,x=3,y=376,width=214,height=148)
        self.party_buff_detail_title=RaidVirtualWidget(self.party_buff_detail_panel,text="Buff说明")
        self.party_buff_detail_text=RaidVirtualWidget(self.party_buff_detail_panel,text="")
        self.combat_member_buttons={}
        # 其他队员战斗信息面板使用整个战斗窗口的绝对设计坐标。
        self.combat_detail_panel=RaidVirtualWidget(self.party_area,x=872,y=170,width=266,height=425)
        self.combat_detail_title=RaidVirtualWidget(self.combat_detail_panel,text="战斗信息-其他队员")
        self.combat_detail_close_btn=RaidVirtualWidget(
            self.combat_detail_panel, text="折叠", command=self._collapse_combat_member,
            x=1080, y=173, width=54, height=22, bg="#334155", fg="#ffffff"
        )
        self.combat_detail_text=RaidVirtualText(self.combat_detail_panel)
        for i,name in enumerate(("MT","ST","H1","D1","D2","D3","D4")):
            b=RaidVirtualWidget(self.combat_detail_panel,text=name,command=lambda n=name:self._select_combat_member(n),
                                x=880+i*34,y=198,width=31,height=22,bg="#1a2636",fg="#c8d8ee")
            self.combat_member_buttons[name]=b
            self._ui_control_registry.append(b)
        self.combat_detail_close_btn.visible=False
        for _b in self.combat_member_buttons.values():
            _b.visible=False
        self._ui_control_registry.append(self.combat_detail_close_btn)
        self.combat_detail_unit=None
        self._other_combat_auto_paused=False
        self.combat_player_collapsed=True
        self.combat_player_fold_btn.visible=False
        self.combat_player_panel.visible=False
        self.combat_hud.visible=False
        self.combat_player_reopen_btn=RaidVirtualWidget(self.main_frame,text="战斗提示",command=self._toggle_combat_player_panel,x=46,y=77,width=88,height=28,bg="#334155",fg="#ffffff")
        # 展开后的折叠按钮也必须注册到统一Canvas命中区。
        self._ui_control_registry.append(self.combat_player_fold_btn)
        self._ui_control_registry.append(self.combat_player_reopen_btn)
        self.combat_other_button=RaidVirtualWidget(self.main_frame,text="战斗信息-其他队员",command=self._open_other_combat_info,x=935,y=655,width=138,height=28,bg="#30445d",fg="#ffffff")
        self._ui_control_registry.append(self.combat_other_button)

    def _build_ai_rez_prompt(self):
        self.ai_rez_prompt_frame=RaidVirtualWidget(self.main_frame,x=330,y=365,width=440,height=155)
        self.ai_rez_prompt_frame.visible=False
        self.ai_rez_title=RaidVirtualWidget(self.ai_rez_prompt_frame,text="")
        self.ai_rez_countdown=RaidVirtualWidget(self.ai_rez_prompt_frame,text="10.0")
        self.ai_rez_yes_btn=RaidVirtualWidget(self.ai_rez_prompt_frame,text="是",command=self._accept_ai_rez,x=460,y=448,width=78,height=34,bg="#2f6f4e",fg="#ffffff")
        self.ai_rez_no_btn=RaidVirtualWidget(self.ai_rez_prompt_frame,text="否",command=self._decline_ai_rez,x=562,y=448,width=78,height=34,bg="#8a3f4f",fg="#ffffff")
        self.ai_rez_yes_btn.visible=False; self.ai_rez_no_btn.visible=False
        self._ui_control_registry.extend([self.ai_rez_yes_btn,self.ai_rez_no_btn])

    def _build_pool_swap_choice_prompt(self):
        self.pool_swap_choice_frame=RaidVirtualWidget(self.main_frame,x=300,y=365,width=500,height=135)
        self.pool_swap_choice_frame.visible=False
        self.pool_swap_choice_title=RaidVirtualWidget(self.pool_swap_choice_frame,text="")
        self.pool_swap_choice_hint=RaidVirtualWidget(self.pool_swap_choice_frame,text="")
        self.pool_swap_player_btn=RaidVirtualWidget(self.pool_swap_choice_frame,text="玩家击球",command=self._pool_swap_choose_swap,x=435,y=440,width=110,height=34,bg="#5b547a",fg="#ffffff")
        self.pool_swap_h1_btn=RaidVirtualWidget(self.pool_swap_choice_frame,text="让h1击球",command=self._pool_swap_choose_skip,x=565,y=440,width=110,height=34,bg="#355f74",fg="#ffffff")
        self.pool_swap_player_btn.visible=False; self.pool_swap_h1_btn.visible=False
        self._ui_control_registry.extend([self.pool_swap_player_btn,self.pool_swap_h1_btn])

    def _toggle_combat_player_panel(self):
        if getattr(self, "combat_player_collapsed", False):
            self.combat_player_collapsed = False
            self.combat_hud.place(in_=self.combat_hud.master, x=20, y=0, width=220, height=self.CH)
            self.combat_player_panel.place(x=33, y=114, width=214, height=520)
            self.combat_player_fold_btn.visible=True
            if hasattr(self, "party_buff_detail_panel"):
                self.party_buff_detail_panel.place_forget()
            self.combat_player_reopen_btn.place_forget()
            self.combat_hud.lift()
            self._refresh_combat_info_ui()
        else:
            self.combat_player_collapsed = True
            # 折叠时必须连同外层 HUD 一起移除，否则透明/同色 Frame
            # 仍会盖住 Canvas，原 HUD 区域看不到战斗场地。
            self.combat_player_panel.place_forget()
            self.combat_player_fold_btn.visible=False
            if hasattr(self, "party_buff_detail_panel"):
                self.party_buff_detail_panel.place_forget()
            self.combat_hud.place_forget()
            self.combat_player_reopen_btn.place(x=46, y=77, width=88, height=28)
            self.combat_player_reopen_btn.lift()
        self.win.update_idletasks()
        self._render()
        return "break"

    def _open_other_combat_info(self):
        if (not self.running and not self.paused) or self.prebattle or self.game_over or self.win_game:
            return
        self.combat_detail_unit = self.combat_detail_unit or "MT"
        # 打开其他队员战斗信息时不再暂停游戏。
        self._other_combat_auto_paused=False
        self.combat_detail_panel.place(x=872,y=170,width=266,height=425)
        self.combat_detail_close_btn.visible=True
        for _b in self.combat_member_buttons.values():
            _b.visible=True
        self.combat_detail_panel.lift()
        self._refresh_combat_info_ui()
        self._toast("已打开其他队员战斗信息，游戏继续进行。")

    def _select_combat_member(self,name):
        self.combat_detail_unit=name
        # 切换其他队员时也不暂停游戏。
        self._other_combat_auto_paused=False
        self._refresh_combat_info_ui()

    def _show_pool_swap_choice(self, m):
        if not hasattr(self, "pool_swap_choice_frame"):
            return
        if m.get("swap_choice_pending", False):
            return
        m["swap_choice_pending"] = True
        m["swap_choice_prev_paused"] = bool(getattr(self, "paused", False))
        # 球台期间的调换选择不暂停游戏；球体/狂暴/机制时间继续推进。
        self.paused = False
        self._manual_pause_overlay = False
        self.keys.clear()
        self.pool_charge_keys.clear()
        self._last = time.time()
        self.pool_swap_choice_title.config(text="下一轮白球控制选择")
        self.pool_swap_choice_hint.config(text="选择“玩家击球”执行白黑调换；选择“让h1击球”则放弃本次调换。")
        self.pool_swap_choice_frame.visible=True; self.pool_swap_player_btn.visible=True; self.pool_swap_h1_btn.visible=True
        # 直接放在战斗窗口正中央。
        self.pool_swap_choice_frame.place(relx=0.5, rely=0.5, anchor="center")
        self.pool_swap_choice_frame.lift()
        try:
            self.win.update_idletasks()
            self.win.focus_force()
            self._force_english_input()
        except Exception:
            pass

    def _resume_after_pool_swap_choice(self):
        m = getattr(self, "mech", None)
        prev = bool(m.get("swap_choice_prev_paused", False)) if m is not None else False
        if m is not None:
            m["swap_choice_prev_paused"] = False
        self.paused = False
        self._last = time.time()
        self._force_english_input()

    def _hide_pool_swap_choice(self):
        m = getattr(self, "mech", None)
        if m is not None:
            m["swap_choice_pending"] = False
        if hasattr(self, "pool_swap_choice_frame"):
            self.pool_swap_choice_frame.place_forget()
            if hasattr(self, "pool_swap_player_btn"): self.pool_swap_player_btn.visible=False
            if hasattr(self, "pool_swap_h1_btn"): self.pool_swap_h1_btn.visible=False

    def _pool_swap_choose_swap(self):
        m = getattr(self, "mech", None)
        if not m or m.get("kind") != "pool_table" or m.get("resolved", False):
            self._hide_pool_swap_choice()
            return
        self._hide_pool_swap_choice()
        self._resume_after_pool_swap_choice()
        if int(m.get("pool_swap_count", 0)) < 3:
            m["swap_cast_active"] = True
            m["swap_cast_elapsed"] = 0.0
            m["swap_pending"] = True
            self._toast("球台：执行白黑调换，读条1秒。")

    def _pool_swap_choose_skip(self):
        m = getattr(self, "mech", None)
        if not m or m.get("kind") != "pool_table" or m.get("resolved", False):
            self._hide_pool_swap_choice()
            return
        self._hide_pool_swap_choice()
        self._resume_after_pool_swap_choice()
        m["swap_pending"] = False
        m["swap_cast_active"] = False
        m["swap_cast_elapsed"] = 0.0
        m["pool_shots_since_swap"] = 0
        m["pool_swap_skip_used"] = True
        m["ai_shot_cooldown"] = 0.65
        self._toast("本次调换已放弃，继续由H1 AI白球击球。")

    def _open_battle_history(self):
        win=tk.Toplevel(self.win); win.title("本局战斗记录"); win.configure(bg="#0d1420"); win.geometry("940x720"); win.transient(self.win)
        top=tk.Frame(win,bg="#0d1420"); top.pack(fill="x",padx=10,pady=8)
        tk.Label(top,text="本局全部战斗信息",bg="#0d1420",fg="#ffd166",font=("微软雅黑",14,"bold")).pack(side="left")
        filters=tk.Frame(top,bg="#0d1420"); filters.pack(side="right")
        body=tk.Frame(win,bg="#0d1420"); body.pack(fill="both",expand=True,padx=10,pady=(0,10))
        sb=tk.Scrollbar(body); sb.pack(side="right",fill="y")
        txt=tk.Text(body,bg="#111a26",fg="#dce8f6",insertbackground="#fff",relief="flat",wrap="word",font=("微软雅黑",9),yscrollcommand=sb.set,padx=10,pady=8); txt.pack(side="left",fill="both",expand=True); sb.config(command=txt.yview)
        def render(filter_name=None):
            txt.config(state="normal"); txt.delete("1.0","end")
            rows=[]
            for ev in self.combat_log:
                if filter_name and ev.get("target")!=filter_name and ev.get("source_unit")!=filter_name: continue
                rows.append(self._format_combat_event(ev,detailed=True))
            txt.insert("1.0","\n".join(rows) if rows else "没有符合条件的记录。"); txt.config(state="disabled"); txt.see("end")
        for name,label in [(None,"全部"),("珠珠","珠珠"),("MT","MT"),("ST","ST"),("H1","H1"),("D1","D1"),("D2","D2"),("D3","D3"),("D4","D4")]:
            tk.Button(filters,text=label,command=lambda n=name:render(n),bg="#30445d",fg="#fff",activebackground="#466984",relief="flat",padx=6,pady=3,font=("微软雅黑",8)).pack(side="left",padx=2)
        tk.Button(filters,text="关闭",command=win.destroy,bg="#5b3340",fg="#fff",relief="flat",padx=8,pady=3,font=("微软雅黑",8)).pack(side="left",padx=4)
        render()

    def _format_combat_event(self,ev,detailed=False):
        t="%.1fs"%float(ev.get("t",0.0)); typ=ev.get("type","")
        if typ=="damage":
            extra=""
            if ev.get("absorbed",0)>0: extra="，护盾吸收%.1f"%ev.get("absorbed",0)
            total=float(ev.get("raw_amount",ev.get("amount",0)) or 0)
            return "[%s] 伤害｜%s ← %s｜总伤 %.1f，实际HP -%.1f%s｜%s"%(t,ev.get("target","?"),ev.get("source","未知机制"),total,ev.get("amount",0),extra,ev.get("mitigation","无额外减伤"))
        if typ=="heal": return "[%s] 治疗｜%s ← %s｜+%.1f HP"%(t,ev.get("target","?"),ev.get("source","未知来源"),ev.get("amount",0))
        if typ=="shield": return "[%s] 护盾｜%s ← %s｜+%.1f"%(t,ev.get("target","?"),ev.get("source","未知来源"),ev.get("amount",0))
        if typ=="death": return "[%s] 死亡｜%s｜原因：%s\n      死前 HP %.1f/%.1f｜盾 %.1f｜%s"%(t,ev.get("target","?"),ev.get("reason","未知"),ev.get("before_hp",0),ev.get("maxhp",0),ev.get("before_shield",0),ev.get("snapshot_text",""))
        if typ=="rez": return "[%s] 复活｜%s ← %s｜HP %.1f/%.1f｜出生点：%s身边"%(t,ev.get("target","?"),ev.get("source","未知"),ev.get("after_hp",0),ev.get("maxhp",0),ev.get("source_unit","施法者"))
        if typ=="status": return "[%s] 状态｜%s｜%s"%(t,ev.get("target","?"),ev.get("text",""))
        return "[%s] %s"%(t,ev.get("text",""))

    def _combat_source_name(self,reason=None):
        if reason: return str(reason)
        m=getattr(self,"mech",None)
        names={"elemental_assignment":"属性赋予","elemental_assignment_absolute":"属性赋予-绝","charge_blood_knock":"连环击退/流血","bridge":"旋转桥","corner_safe":"九宫格安全区","sequence_spread":"顺序分散","linear_danger":"线性危险区","potion_puzzle":"药剂调和与转化","circle":"圆形点名","cone":"扇形攻击","stack":"集合伤害","spread":"分散点名","iron":"钢铁","donut":"月环","cross":"旋转十字","double_circle":"双圆点名","chase_circle":"三目标追踪圈","fan_circle_combo":"扇形+圆形点名+双人塔","tether_death":"接线死刑","tank_buster":"T死刑","possession":"附身·除秽"}
        return (m.get("name") if m else None) or (names.get(m.get("kind"),m.get("kind","机制伤害")) if m else "持续伤害")

    def _snapshot_unit_state(self,u):
        layers=getattr(u,"shield_layers",{}) or {}
        reductions=[]
        if getattr(u,"role","")=="tank": reductions.append("坦克常驻减伤20%")
        if getattr(u,"fey_illumination_timer",0)>0: reductions.append("幻光魔伤-5%")
        if getattr(u,"expedient_timer",0)>0: reductions.append("疾风受伤×0.90")
        if self._has_sacred_soil_buff(u): reductions.append("野战减伤10%")
        elif self._has_h1_sacred_soil_buff(u): reductions.append("野战-h1减伤10%")
        if getattr(u, "ai_sage_clean_juice_timer", 0.0) > 0.0: reductions.append("坚角清汁减伤10%")
        heal_bonuses=[]; hb=float(getattr(u,"heal_received_bonus",0) or 0)
        if hb: heal_bonuses.append("受疗+%.0f%%"%(hb*100))
        if getattr(self,"dissipation_timer",0)>0: heal_bonuses.append("转化治疗+20%")
        if getattr(self,"fey_illumination_timer",0)>0: heal_bonuses.append("幻光治疗+10%")
        hots=[]
        if getattr(self,"whispering_dawn_timer",0)>0: hots.append("仙光低语 %.1fs"%getattr(self,"whispering_dawn_timer",0))
        if getattr(self,"seraphism_timer",0)>0: hots.append("炽天附体 %.1fs"%getattr(self,"seraphism_timer",0))
        if self._has_sacred_soil_buff(u): hots.append("野战治疗阵")
        if self._has_h1_sacred_soil_buff(u): hots.append("野战治疗阵-h1")
        if getattr(u, "ai_sage_clean_juice_timer", 0.0) > 0.0: hots.append("坚角清汁")
        if getattr(self,"aetherpact_target",None) is u and getattr(self,"aetherpact_timer",0)>0: hots.append("以太契约 %.1fs"%getattr(self,"aetherpact_timer",0))
        buffs=[]
        if getattr(u,"element_buff",None): buffs.append("属性:%s %.1fs"%(u.element_buff,getattr(u,"element_buff_timer",0)))
        if getattr(u,"absolute_primary",None): buffs.append("绝属性:%s" % self._absolute_label(u.absolute_primary))
        if getattr(u,"absolute_secondary_primary",None): buffs.append("绝属性:%s" % self._absolute_label(u.absolute_secondary_primary))
        if getattr(u,"absolute_fire_seed_stacks",0): buffs.append("绝火种×%d" % int(u.absolute_fire_seed_stacks))
        if getattr(u,"absolute_wind_up_stacks",0): buffs.append("绝风起×%d" % int(u.absolute_wind_up_stacks))
        if getattr(u,"absolute_wind_mark_stacks",0): buffs.append("绝风印×%d" % int(u.absolute_wind_mark_stacks))
        if getattr(u,"absolute_thunder_stacks",0): buffs.append("绝钧雷×%d" % int(u.absolute_thunder_stacks))
        if getattr(u,"absolute_wrong_thunder_stacks",0): buffs.append("绝错误钧雷×%d" % int(u.absolute_wrong_thunder_stacks))
        if getattr(u,"absolute_electrified",False): buffs.append("绝感电")
        if getattr(u,"absolute_teaching_knockback",False): buffs.append("教学击退")
        if getattr(u,"bleed_timer",0)>0: buffs.append("流血 %.1fs"%getattr(u,"bleed_timer",0))
        if getattr(u,"charge_bleed_stacks",0)>0: buffs.append("冲锋流血×%d"%getattr(u,"charge_bleed_stacks",0))
        if getattr(u,"death_timer",0)>0: buffs.append("复活后输出衰减 %.1fs"%getattr(u,"death_timer",0))
        if getattr(u,"rez_invuln_timer",0)>0: buffs.append("复活无敌 %.1fs"%getattr(u,"rez_invuln_timer",0))
        if not buffs: buffs.append("无流血/Buff")
        return {"hp":float(getattr(u,"hp",0)),"maxhp":float(getattr(u,"maxhp",0)),"shield":float(getattr(u,"shield",0)),"shield_layers":{k:float(v) for k,v in layers.items()},"mp":float(getattr(u,"mp",0)),"reductions":reductions or ["无额外减伤"],"heal_bonuses":heal_bonuses or ["无额外受疗/增疗"],"hots":hots or ["无持续恢复"],"buffs":buffs}

    def _snapshot_text(self,snap):
        return "；".join(["减伤："+"、".join(snap["reductions"]),"增疗/受疗："+"、".join(snap["heal_bonuses"]),"持续恢复："+"、".join(snap["hots"]),"效果："+"、".join(snap["buffs"])])

    def _log_combat_event(self,event):
        # 战斗事件只负责写入内存索引，不在每一次伤害/治疗后立即重绘 Tkinter UI。
        # 高难机制常会在同一瞬间产生几十条事件，逐条刷新 Text 控件会造成明显掉帧。
        event=dict(event); event.setdefault("t",float(getattr(self,"survive_t",0.0))); self.combat_log.append(event)
        if len(self.combat_log)>12000: del self.combat_log[:2000]
        target=event.get("target")
        source_unit=event.get("source_unit")
        names=[]
        if target: names.append(target)
        if source_unit and source_unit != target: names.append(source_unit)
        for name in names:
            if name and name in self.combat_logs_by_unit:
                self.combat_logs_by_unit[name].append(event)
                if len(self.combat_logs_by_unit[name])>4000: del self.combat_logs_by_unit[name][:500]
        self._schedule_combat_info_refresh()

    def _cancel_combat_info_refresh(self):
        pending=getattr(self,"_combat_info_refresh_pending",None)
        if pending is not None:
            try:
                self.win.after_cancel(pending)
            except Exception:
                pass
        self._combat_info_refresh_pending=None

    def _schedule_combat_info_refresh(self):
        # 战斗信息面板默认关闭；关闭时完全不刷新。
        player_visible=not getattr(self,"combat_player_collapsed",True)
        detail_visible=False
        try:
            detail_visible=bool(getattr(self,"combat_detail_panel",None) is not None and self.combat_detail_panel.winfo_ismapped())
        except Exception:
            detail_visible=bool(getattr(self,"combat_detail_unit",None))
        if not player_visible and not detail_visible:
            return
        if getattr(self,"_combat_info_refresh_pending",None) is not None:
            return
        try:
            # 约每80ms最多刷新一次；多个同帧事件会合并成一次 UI 更新。
            self._combat_info_refresh_pending=self.win.after(80,self._flush_combat_info_refresh)
        except Exception:
            self._combat_info_refresh_pending=None

    def _flush_combat_info_refresh(self):
        self._combat_info_refresh_pending=None
        try:
            self._refresh_combat_info_ui()
        except Exception:
            # 战斗结束/窗口销毁时，避免一个过期 after 回调干扰收尾流程。
            pass

    def _format_player_heal_event(self, ev):
        t="%.1fs" % float(ev.get("t",0.0))
        target=ev.get("target","?")
        source=ev.get("source","未知来源")
        amount=float(ev.get("amount",0.0) or 0.0)
        if target == self.player.name and ev.get("source_unit") != self.player.name:
            return "[%s] 所受治疗｜%s ← %s｜+%.1f HP" % (t,target,source,amount)
        if ev.get("source_unit") == self.player.name:
            return "[%s] 治疗｜%s → %s｜+%.1f HP" % (t,source,target,amount)
        return "[%s] 治疗｜%s ← %s｜+%.1f HP" % (t,target,source,amount)

    def _refresh_combat_info_ui(self):
        if not hasattr(self,"combat_player_text") or not hasattr(self,"combat_log"): return

        # 使用按队员建立的索引，而不是每次从完整 combat_log 扫描最多12000条记录。
        player_events=list(getattr(self,"combat_logs_by_unit",{}).get(self.player.name,[]))
        damage_events=[ev for ev in player_events if ev.get("type") in ("damage","death")]
        heal_events=[ev for ev in player_events if ev.get("type")=="heal"]

        damage_rows=[self._format_combat_event(ev) for ev in damage_events[-24:]]
        heal_rows=[self._format_player_heal_event(ev) for ev in heal_events[-24:]]

        # 面板已折叠时不碰 Text 控件；重新打开时会由按钮事件主动刷新。
        if not getattr(self,"combat_player_collapsed",True):
            self.combat_player_damage_text.config(state="normal")
            self.combat_player_damage_text.delete("1.0","end")
            self.combat_player_damage_text.insert("1.0","\n".join(damage_rows) if damage_rows else "暂无受到伤害或死亡记录。")
            self.combat_player_damage_text.see("end")
            self.combat_player_damage_text.config(state="disabled")

            self.combat_player_heal_text.config(state="normal")
            self.combat_player_heal_text.delete("1.0","end")
            self.combat_player_heal_text.insert("1.0","\n".join(heal_rows) if heal_rows else "暂无治疗或所受治疗记录。")
            self.combat_player_heal_text.see("end")
            self.combat_player_heal_text.config(state="disabled")

            for name,b in getattr(self,"combat_member_buttons",{}).items():
                b.config(text=name, bg="#2f4a6a" if self.combat_detail_unit==name else "#1a2636")
            self.combat_pause_label.config(text="已暂停" if getattr(self,"paused",False) else "")

        if self.combat_detail_unit:
            try:
                detail_visible=bool(self.combat_detail_panel.winfo_ismapped())
            except Exception:
                detail_visible=True
            if detail_visible:
                self._render_combat_member_detail(self.combat_detail_unit)

    def _render_combat_member_detail(self,name):
        self.combat_detail_title.config(text="战斗信息 · "+name)
        rows=[self._format_combat_event(ev) for ev in self.combat_logs_by_unit.get(name,[])][-18:]
        self.combat_detail_text.config(state="normal"); self.combat_detail_text.delete("1.0","end"); self.combat_detail_text.insert("1.0","\n".join(rows) if rows else "尚无战斗信息。"); self.combat_detail_text.see("end"); self.combat_detail_text.config(state="disabled")

    def _toggle_combat_member(self,name):
        if (not self.running and not self.paused) or self.prebattle or self.game_over or self.win_game:
            return
        if self.combat_detail_unit == name and self.combat_detail_panel.winfo_ismapped():
            return self._collapse_combat_member()
        self.combat_detail_unit=name
        # 点击其他队员战斗信息时不再暂停游戏。
        self._other_combat_auto_paused=False
        self.combat_detail_panel.place(x=872,y=170,width=266,height=425)
        self.combat_detail_close_btn.visible=True
        for _b in self.combat_member_buttons.values():
            _b.visible=True
        self.combat_detail_panel.lift()
        self._refresh_combat_info_ui()
        self._toast("查看 %s 的战斗信息，游戏继续进行。"%name)

    def _collapse_combat_member(self):
        self.combat_detail_unit=None
        if hasattr(self,"combat_detail_panel"):
            self.combat_detail_panel.place_forget()
        if hasattr(self,"combat_detail_close_btn"):
            self.combat_detail_close_btn.visible=False
        for _b in getattr(self,"combat_member_buttons",{}).values():
            _b.visible=False
        if getattr(self,"_other_combat_auto_paused",False) and self.paused and self.running and getattr(self,"ai_rez_prompt",None) is None:
            self._other_combat_auto_paused=False
            self.paused=False
            self._last=time.time()
        self._refresh_combat_info_ui()

    def _show_ai_rez_prompt(self,healer):
        if getattr(self,"ai_rez_prompt",None) is not None or self.player.alive or not self.running: return
        # 复活选择提示出现时不暂停游戏；10秒倒计时与战斗继续同步运行。
        self.ai_rez_prompt={"healer":healer,"timer":10.0}; self._last=time.time()
        label={"白魔":"白魔","占星":"占星","贤者":"贤者","学者":"学者"}.get(getattr(healer,"job","学者"),getattr(healer,"job","学者"))
        self.ai_rez_title.config(text="%s想要复活你，是否立刻复活"%label); self.ai_rez_countdown.config(text="10.0"); self.ai_rez_prompt_frame.visible=True; self.ai_rez_yes_btn.visible=True; self.ai_rez_no_btn.visible=True; self.ai_rez_prompt_frame.place(relx=.5,rely=.46,anchor="center"); self.ai_rez_prompt_frame.lift()
        self._log_combat_event({"type":"status","target":self.player.name,"source":label,"source_unit":healer.name,"text":"%s提供复活；10秒内选择是否立即复活。"%label})

    def _finish_ai_rez_prompt(self,accepted=True,timeout=False):
        p=getattr(self,"ai_rez_prompt",None)
        if not p: return
        healer=p.get("healer"); self.ai_rez_prompt=None; self.ai_rez_prompt_frame.place_forget(); self.ai_rez_yes_btn.visible=False; self.ai_rez_no_btn.visible=False
        if not accepted: return self._game_over("玩家放弃复活，结束本局游戏")
        if healer is not None:
            self._do_rez(self.player,healer); healer.rez_cd=self.REZ_WINDOW; healer.rez_target=None; healer.rez_cast_timer=0.0
            self._toast(("自动复活" if timeout else "立刻复活")+"，出生点：%s身边。"%healer.name)
        self.running=True; self.paused=False; self._last=time.time(); self._focus()

    def _accept_ai_rez(self): self._finish_ai_rez_prompt(True,False)
    def _decline_ai_rez(self): self._finish_ai_rez_prompt(False,False)
    def _tick_ai_rez_prompt(self,dt):
        p=getattr(self,"ai_rez_prompt",None)
        if not p: return
        p["timer"]-=dt; self.ai_rez_countdown.config(text="%.1f"%max(0,p["timer"]))
        if p["timer"]<=0: self._finish_ai_rez_prompt(True,True)

    def _info_window(self, title, lines):
        win = tk.Toplevel(self.win)
        win.title(title)
        win.configure(bg="#0d1420")
        win.geometry("720x680")
        win.transient(self.win)
        win.grab_set()
        top = tk.Frame(win, bg="#0d1420")
        top.pack(fill="x", padx=14, pady=(12, 8))
        tk.Label(top, text=title, bg="#0d1420", fg="#ffd166",
                 font=("微软雅黑", 16, "bold")).pack(side="left")
        tk.Button(top, text="关闭", command=win.destroy, bg="#30445d", fg="#fff",
                  relief="flat", padx=12, pady=4).pack(side="right")
        frame = tk.Frame(win, bg="#0d1420")
        frame.pack(fill="both", expand=True, padx=14, pady=(0,14))
        scroll = tk.Scrollbar(frame)
        scroll.pack(side="right", fill="y")
        txt = tk.Text(frame, bg="#111a26", fg="#dce8f6", insertbackground="#ffffff",
                      relief="flat", wrap="word", font=("微软雅黑", 10), yscrollcommand=scroll.set,
                      padx=14, pady=12, spacing1=3, spacing3=6)
        txt.pack(side="left", fill="both", expand=True)
        scroll.config(command=txt.yview)
        txt.insert("1.0", "\n".join(lines))
        txt.config(state="disabled")
        return win

