    def _mechanic_order_name_map(self):
        return {gid: name for gid, name, _, _ in self._mechanic_order_defs()}

    def _load_mechanic_order(self):
        # 机制顺序不依赖外部文件；程序启动时默认全部随机。
        # 运行期间只保存在内存中，关闭程序后恢复默认随机。
        if not hasattr(self, "mech_order"):
            self.mech_order = {}

    def open_mechanic_order(self):
        if not self.prebattle:
            self._toast("机制次序只能在战前准备阶段调整。")
            return

        win = tk.Toplevel(self.win)
        win.title("机制次序设置")
        win.configure(bg="#0d1420")
        win.geometry("860x760")
        win.transient(self.win)
        win.grab_set()

        top = tk.Frame(win, bg="#0d1420")
        top.pack(fill="x", padx=14, pady=(12, 8))
        tk.Label(top, text="机制次序设置", bg="#0d1420", fg="#ffd166",
                 font=("微软雅黑", 16, "bold")).pack(side="left")
        tk.Label(top, text="未指定的轮次=随机；球台、属性赋予-绝仅能手动指定，不会进入随机池。随机轮次不会与前3个随机/手动机制组重复。",
                 bg="#0d1420", fg="#9ec8ff", font=("微软雅黑", 9)).pack(side="left", padx=12)

        frame = tk.Frame(win, bg="#0d1420")
        frame.pack(fill="both", expand=True, padx=14)

        left = tk.Frame(frame, bg="#111a26", bd=1, relief="solid")
        left.pack(side="left", fill="both", expand=True, padx=(0, 8))
        tk.Label(left, text="每轮机制", bg="#111a26", fg="#e8f0ff",
                 font=("微软雅黑", 11, "bold")).pack(anchor="w", padx=12, pady=(10, 6))
        list_frame = tk.Frame(left, bg="#111a26")
        list_frame.pack(fill="both", expand=True, padx=8, pady=(0, 8))

        choices = [("", "随机")] + [(gid, name) for gid, name, _, _ in self._mechanic_order_defs()]
        choice_ids = [x[0] for x in choices]
        choice_names = [x[1] for x in choices]
        vars_by_round = {}
        combo_widgets = []
        max_rounds = 20
        for r in range(1, max_rounds + 1):
            row = tk.Frame(list_frame, bg="#111a26")
            row.pack(fill="x", pady=2)
            tk.Label(row, text="第%02d轮" % r, width=8, anchor="w", bg="#111a26", fg="#dce8f6",
                     font=("微软雅黑", 9, "bold")).pack(side="left", padx=(4, 4))
            saved_gid = self.mech_order.get(r, "")
            saved_label = self._mechanic_order_name_map().get(saved_gid, "")
            var = tk.StringVar(value=saved_label)
            cb = tk.OptionMenu(row, var, *choice_names)
            cb.configure(width=27, bg="#2d4157", fg="#ffffff", activebackground="#405d7a", activeforeground="#ffffff",
                         highlightthickness=0, bd=0, relief="flat")
            cb["menu"].configure(bg="#243447", fg="#ffffff", activebackground="#4d6f91", activeforeground="#ffffff")
            cb.pack(side="left", padx=4)
            vars_by_round[r] = (var, cb)
            combo_widgets.append((r, var))

            # 把显示中文名映射为内部group id的辅助信息放在旁边。
            tk.Label(row, text="未指定即随机", bg="#111a26", fg="#6f8298",
                     font=("微软雅黑", 8)).pack(side="left", padx=6)

        # 右侧机制信息表
        right = tk.Frame(frame, bg="#111a26", bd=1, relief="solid", width=330)
        right.pack(side="right", fill="y")
        right.pack_propagate(False)
        tk.Label(right, text="机制难度 / 预计时长", bg="#111a26", fg="#e8f0ff",
                 font=("微软雅黑", 11, "bold")).pack(anchor="w", padx=12, pady=(10, 8))
        info = tk.Text(right, bg="#111a26", fg="#dce8f6", relief="flat", wrap="word",
                       font=("微软雅黑", 9), height=30, width=38, padx=10, pady=6)
        info.pack(fill="both", expand=True, padx=6, pady=(0, 6))
        for i, (_, name, diff_name, duration) in enumerate(self._mechanic_order_defs(), 1):
            info.insert("end", "%02d. %-20s\n    难度：%s\n    时长：%s\n\n" % (i, name, diff_name, duration))
        info.insert("end", "说明：\n• 球台为手动机制，只能在上方轮次中指定，不会进入随机机制池。\n• 钢铁/月环、分摊/分散内部仍按当前机制规则随机决定具体变体。\n• 随机机制每次会排除最近3个已经出现的机制组。\n• 手动指定轮次优先按你的顺序执行。")
        info.config(state="disabled")

        bottom = tk.Frame(win, bg="#0d1420")
        bottom.pack(fill="x", padx=14, pady=10)

        def clear_all():
            for r, var in vars_by_round.items():
                var.set("")

        def save_and_close():
            name_to_id = {name: gid for gid, name, _, _ in self._mechanic_order_defs()}
            new_order = {}
            for r, (var, _) in vars_by_round.items():
                label = var.get().strip()
                if label and label != "随机":
                    gid = name_to_id.get(label)
                    if gid:
                        new_order[r] = gid
            self.mech_order = new_order
            self._toast("机制次序已保存；未指定轮次按随机规则生成。")
            win.destroy()

        tk.Button(bottom, text="全部改为随机", command=clear_all,
                  bg="#3c5068", fg="#ffffff", activebackground="#506a86",
                  relief="flat", padx=14, pady=6).pack(side="left")
        tk.Button(bottom, text="保存并关闭", command=save_and_close,
                  bg="#2f6f4e", fg="#ffffff", activebackground="#3c8d63",
                  relief="flat", padx=18, pady=6).pack(side="right", padx=5)
        tk.Button(bottom, text="取消", command=win.destroy,
                  bg="#6a3f52", fg="#ffffff", activebackground="#87516a",
                  relief="flat", padx=18, pady=6).pack(side="right")

