        self.seraph_active = False
        self.seraph_timer = 0.0
        self.seraphism_timer = 0.0
        self.seraphism_tick = 0.0
        self.dissipation_timer = 0.0
        self.fey_illumination_timer = 0.0
        self.whispering_dawn_timer = 0.0
        self.whisper_tick = 1.0
        self.aetherpact_target = None
        self.aetherpact_timer = 0.0
