            m["center_aoe_dmg"] = 64.0 * diff * self.MECH_DAMAGE_MULT
            m["phase"] = "knockback"
            m["tower_t"] = 0.0
            m["tower_window"] = 2.0
            m["death_zone_delay"] = 1.0
            m["tower_r"] = 1.0
