# ============================================================
# PETZhu 桌面联机层（v1）
# TCP 房间转发 + 独立桌面宠物窗口；不把远端桌宠塞进新的容器界面。
# ============================================================

_PETZHU_MP_MAX_PEERS = 8
_PETZHU_MP_MAX_LINE = 64 * 1024 * 1024
_PETZHU_MP_MAX_IMAGE = 700 * 1024
_PETZHU_MP_MAX_SONG = 420 * 1024


def _petzhu_mp_local_addresses():
    """返回可用的 IPv4 地址；不会请求外部服务查询公网 IP。"""
    values = []
    try:
        probe = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        try:
            probe.connect(("192.0.2.1", 9))
            address = probe.getsockname()[0]
            if address and not address.startswith("127."):
                values.append(address)
        finally:
            probe.close()
    except Exception:
        pass
    try:
        for address in socket.gethostbyname_ex(socket.gethostname())[2]:
            if address and not address.startswith("127.") and address not in values:
                values.append(address)
    except Exception:
        pass
    return values or ["127.0.0.1"]


def _petzhu_mp_read_json_line(stream):
    raw = stream.readline(_PETZHU_MP_MAX_LINE + 1)
    if not raw:
        raise ConnectionError("连接已关闭")
    if len(raw) > _PETZHU_MP_MAX_LINE or not raw.endswith(b"\n"):
        raise ValueError("联机数据包过大或格式错误")
    try:
        value = json.loads(raw.decode("utf-8"))
    except Exception as exc:
        raise ValueError("联机数据不是有效 JSON：%s" % exc)
    if not isinstance(value, dict):
        raise ValueError("联机数据格式错误")
    return value


def _petzhu_mp_send_socket(sock, packet, lock=None):
    payload = (json.dumps(packet, ensure_ascii=False, separators=(",", ":")) + "\n").encode("utf-8")
    if len(payload) > _PETZHU_MP_MAX_LINE:
        raise ValueError("联机数据包超过大小上限")
    if lock is None:
        sock.sendall(payload)
    else:
        with lock:
            sock.sendall(payload)


class _PETZhuMultiplayer:
    """每个进程一个网络端点。房主负责转发，不要求额外 exe 或本地服务。"""
    def __init__(self, app):
        self.app = app
        self.mode = "offline"
        self.running = False
        self.connected = False
        self.local_id = uuid.uuid4().hex[:12]
        self.local_name = str(getattr(app, "pet_name", "珠珠") or "珠珠")[:24]
        self.room_key = ""
        self.host = ""
        self.port = 0
        self.room_code = ""
        self.server_socket = None
        self.server_thread = None
        self.client_socket = None
        self.client_stream = None
        self.client_thread = None
        self.stop_event = threading.Event()
        self.write_lock = threading.Lock()
        self.lock = threading.RLock()
        self.peers = {}
        self.states = {}
        self.local_state = {}
        self.events = queue.Queue()
        self._peer_sockets = {}
        self._peer_locks = {}
        self._pending_asset_sync = {}
        self._ready_timeouts = {}
        self._manual_stop = False
        self._local_meta = {}
        self._last_roster_signature = None

    def _build_local_meta(self, name=None):
        app = self.app
        if name:
            self.local_name = str(name).strip()[:24] or str(getattr(app, "pet_name", "珠珠"))[:24]
        addresses = _petzhu_mp_local_addresses()
        try:
            screen_w = int(app.root.winfo_screenwidth())
            screen_h = int(app.root.winfo_screenheight())
        except Exception:
            screen_w, screen_h = 1920, 1080
        assets = {"sprites": {}, "songs": [], "active_song": None}
        # 只传递人设明确指定的自定义姿态图；普通姿态使用各端内置默认图。
        for pose in ("normal", "talk", "pat"):
            try:
                path = str(app._persona_sprite_path(pose) or "").strip()
                if not path or not os.path.isfile(path):
                    continue
                with Image.open(path) as source:
                    image = source.convert("RGBA")
                    image.thumbnail((600, 600), getattr(Image, "Resampling", Image).LANCZOS)
                    data = io.BytesIO()
                    image.save(data, format="PNG")
                    payload = data.getvalue()
                if payload and len(payload) <= _PETZHU_MP_MAX_IMAGE:
                    assets["sprites"][pose] = base64.b64encode(payload).decode("ascii")
            except Exception:
                # 个别自定义图片无法读取时不阻断进房，对方将使用内置默认图像。
                continue
        seen_songs = set()
        for path in list(getattr(app, "hum_song_paths", []) or [])[:6]:
            try:
                path = os.path.abspath(str(path))
                if path in seen_songs or not os.path.isfile(path):
                    continue
                seen_songs.add(path)
                with open(path, "rb") as f:
                    raw = f.read(_PETZHU_MP_MAX_SONG + 1)
                if len(raw) > _PETZHU_MP_MAX_SONG:
                    continue
                data = json.loads(raw.decode("utf-8-sig"))
                if isinstance(data, dict):
                    assets["songs"].append({"name": os.path.basename(path)[:100], "data": data})
            except Exception:
                continue
        current_song = None
        if getattr(app, "_idle_hum_playing", False):
            current_song = getattr(app, "_idle_song_runtime_data", None)
        elif getattr(app, "_song_playing", False):
            current_song = getattr(app, "_song_data", None)
        elif getattr(app, "_chat_song_playing", False):
            current_song = getattr(app, "_idle_song_data", None)
        if isinstance(current_song, dict):
            try:
                if len(json.dumps(current_song, ensure_ascii=False).encode("utf-8")) <= 2 * 1024 * 1024:
                    assets["active_song"] = current_song
            except Exception:
                pass
        while len(assets["songs"]) > 1:
            if len(json.dumps(assets, ensure_ascii=False).encode("utf-8")) <= 3 * 1024 * 1024:
                break
            assets["songs"].pop()
        return {
            "id": self.local_id, "name": self.local_name, "ip": addresses[0],
            "addresses": addresses[:8], "screen_w": screen_w, "screen_h": screen_h,
            "is_host": self.mode == "host", "assets": assets,
        }

    def _set_status(self, text, kind="status"):
        self.events.put({"type": kind, "text": str(text)[:500]})

    def start_host(self, name=None):
        self.stop(notify=False, quiet=True)
        self.mode = "host"
        self.stop_event.clear()
        self._manual_stop = False
        self.local_id = uuid.uuid4().hex[:12]
        self._local_meta = self._build_local_meta(name)
        server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try:
            server.bind(("0.0.0.0", 0))
            server.listen(8)
            server.settimeout(0.5)
        except Exception:
            server.close()
            self.mode = "offline"
            raise
        self.server_socket = server
        self.port = int(server.getsockname()[1])
        self.room_key = secrets.token_hex(8)
        self.host = str((self._local_meta.get("addresses") or ["127.0.0.1"])[0])
        self.room_code = "%s:%d:%s" % (self.host, self.port, self.room_key)
        self.running = True
        self.connected = True
        self._local_meta.update({"id": self.local_id, "name": self.local_name, "ip": self.host, "is_host": True})
        self.server_thread = threading.Thread(target=self._accept_loop, name="PETZhu-MP-Host", daemon=True)
        self.server_thread.start()
        self._set_status("房间已创建。连接码已生成；异地连接需要虚拟局域网或端口转发。")
        return self.room_code

    def join_room(self, code, name=None):
        parts = str(code or "").strip().rsplit(":", 2)
        if len(parts) != 3:
            raise ValueError("连接码格式应为 IP:端口:邀请码")
        host, port_text, key = parts[0].strip().strip("[]"), parts[1].strip(), parts[2].strip().lower()
        try:
            port = int(port_text)
        except Exception:
            raise ValueError("连接码里的端口无效")
        if not host or not (1 <= port <= 65535) or not re.fullmatch(r"[0-9a-f]{16}", key):
            raise ValueError("连接码无效，请完整复制房主显示的连接码")
        self.stop(notify=False, quiet=True)
        self.mode = "client"
        self.stop_event.clear()
        self._manual_stop = False
        self.local_id = uuid.uuid4().hex[:12]
        self.host, self.port, self.room_key = host, port, key
        self.room_code = "%s:%d:%s" % (host, port, key)
        self._local_meta = self._build_local_meta(name)
        self._local_meta.update({"id": self.local_id, "name": self.local_name, "is_host": False})
        self.running = True
        self.connected = False
        self._set_status("正在连接房主并同步桌宠资源……")
        threading.Thread(target=self._join_worker, name="PETZhu-MP-Join", daemon=True).start()

    def _join_worker(self):
        sock = None
        try:
            sock = socket.create_connection((self.host, self.port), timeout=12)
            sock.settimeout(None)
            send_lock = threading.Lock()
            _petzhu_mp_send_socket(sock, {"type": "hello", "key": self.room_key, "meta": self._local_meta}, send_lock)
            stream = sock.makefile("rb")
            first = _petzhu_mp_read_json_line(stream)
            if first.get("type") == "reject":
                raise ConnectionError(str(first.get("reason", "房间拒绝了连接")))
            if first.get("type") != "welcome":
                raise ConnectionError("房主返回了无法识别的数据")
            self.client_socket, self.client_stream, self.write_lock = sock, stream, send_lock
            self._load_roster(first.get("members", []), first.get("states", {}))
            self.events.put({"type": "welcome", "members": first.get("members", [])})
            self._set_status("已连接，正在等待房间成员完成资源检查……")
            self._client_read_loop(sock, stream)
        except Exception as exc:
            if sock is not None:
                try: sock.close()
                except Exception: pass
            if not self._manual_stop and not self.stop_event.is_set():
                self.connected = False
                self.running = False
                self.mode = "offline"
                self._set_status("连接失败：%s" % str(exc))

    def _accept_loop(self):
        while self.running and not self.stop_event.is_set():
            try:
                sock, addr = self.server_socket.accept()
            except socket.timeout:
                continue
            except OSError:
                break
            except Exception:
                continue
            try:
                sock.settimeout(15)
                threading.Thread(target=self._server_peer_worker, args=(sock, addr),
                                 name="PETZhu-MP-Peer", daemon=True).start()
            except Exception:
                try: sock.close()
                except Exception: pass

    def _participants_locked(self):
        return [self.local_id] + list(self.peers.keys())

    def _host_send_one(self, pid, packet):
        with self.lock:
            sock = self._peer_sockets.get(pid)
            lock = self._peer_locks.get(pid)
        if sock is None:
            return False
        try:
            _petzhu_mp_send_socket(sock, packet, lock)
            return True
        except Exception:
            return False

    def _host_broadcast(self, packet, exclude=None):
        with self.lock:
            targets = [(pid, self._peer_sockets.get(pid), self._peer_locks.get(pid))
                       for pid in self._peer_sockets if pid != exclude]
        for _pid, sock, lock in targets:
            if sock is not None:
                try: _petzhu_mp_send_socket(sock, packet, lock)
                except Exception: pass

    def _roster_packet(self):
        with self.lock:
            host_meta = dict(self._local_meta)
            host_meta.update({"id": self.local_id, "name": self.local_name, "ip": self.host, "is_host": True})
            members = [host_meta] + [dict(m) for m in self.peers.values()]
            states = {pid: dict(value) for pid, value in self.states.items()}
            if self.local_state:
                states[self.local_id] = dict(self.local_state)
        return {"type": "roster", "members": members, "states": states}

    def _broadcast_roster(self):
        packet = self._roster_packet()
        self.events.put(packet)
        self._host_broadcast(packet)

    def _server_peer_worker(self, sock, addr):
        stream = None
        pid = ""
        generation_map = getattr(self, "_mp_peer_socket_generations", {})
        generation = generation_map.get(id(sock), getattr(self, "_mp_session_generation", 0))
        try:
            stream = sock.makefile("rb")
            hello = _petzhu_mp_read_json_line(stream)
            if generation != getattr(self, "_mp_session_generation", 0):
                return
            if hello.get("type") != "hello" or str(hello.get("key", "")).lower() != self.room_key:
                _petzhu_mp_send_socket(sock, {"type": "reject", "reason": "邀请码不正确"})
                return
            meta = hello.get("meta") if isinstance(hello.get("meta"), dict) else {}
            pid = str(meta.get("id", ""))[:32]
            if not pid or pid == self.local_id:
                _petzhu_mp_send_socket(sock, {"type": "reject", "reason": "玩家标识无效"})
                return
            with self.lock:
                # Re-check while holding the same lock used by stop()'s generation bump.
                if generation != getattr(self, "_mp_session_generation", 0):
                    return
                if len(self.peers) >= _PETZHU_MP_MAX_PEERS - 1:
                    _petzhu_mp_send_socket(sock, {"type": "reject", "reason": "房间已满（最多 8 个桌宠）"})
                    return
                if pid in self.peers:
                    _petzhu_mp_send_socket(sock, {"type": "reject", "reason": "该桌宠已在房间内"})
                    return
                peer_meta = {
                    "id": pid, "name": str(meta.get("name", "桌宠") or "桌宠")[:24],
                    "ip": str(addr[0]), "addresses": [str(addr[0])],
                    "screen_w": max(1, min(20000, int(meta.get("screen_w", 1920) or 1920))),
                    "screen_h": max(1, min(20000, int(meta.get("screen_h", 1080) or 1080))),
                    "is_host": False, "assets": meta.get("assets", {}) if isinstance(meta.get("assets", {}), dict) else {},
                    "trail_profile": _petzhu_mp_sanitize_trail_profile(meta.get("trail_profile")),
                }
                existing_ids = set(self._participants_locked())
                self.peers[pid] = peer_meta
                self._peer_sockets[pid] = sock
                self._peer_locks[pid] = threading.Lock()
                self._pending_asset_sync[pid] = {"existing": existing_ids,
                    "from_existing": set(), "new_to_existing": set(), "failed": set()}
                roster = self._roster_packet()
                timeout = threading.Timer(15.0, self._force_asset_ready, args=(pid,))
                timeout.daemon = True
                self._ready_timeouts[pid] = timeout
                timeout.start()
            sock.settimeout(None)
            _petzhu_mp_send_socket(sock, {"type": "welcome", "members": roster["members"],
                                          "states": roster["states"], "host_id": self.local_id},
                                   self._peer_locks[pid])
            self.events.put({"type": "peer_join", "member": dict(peer_meta)})
            self._host_broadcast({"type": "peer_join", "member": dict(peer_meta)}, exclude=pid)
            # peer_join already carries the new member; the full roster would resend every
            # existing member's base64 PNG/song assets to everyone a second time.
            while self.running and not self.stop_event.is_set():
                packet = _petzhu_mp_read_json_line(stream)
                # A socket accepted by a previous room must never mutate a newer room.
                if generation != getattr(self, "_mp_session_generation", 0):
                    break
                ptype = str(packet.get("type", ""))
                if ptype == "state":
                    state = packet.get("state")
                    if not isinstance(state, dict): continue
                    state = dict(state)
                    state.update({"peer_id": pid, "name": peer_meta["name"], "ip": peer_meta["ip"]})
                    with self.lock: self.states[pid] = state
                    out = {"type": "state", "peer_id": pid, "state": state}
                    self._host_broadcast(out, exclude=pid)
                elif ptype == "chat":
                    msg = str(packet.get("text", "")).strip()[:1000]
                    if msg:
                        out = {"type": "chat", "peer_id": pid, "name": peer_meta["name"],
                               "ip": peer_meta["ip"], "text": msg, "time": time.time()}
                        self.events.put(out)
                        self._host_broadcast(out)
                elif ptype == "command":
                    target = str(packet.get("target", ""))[:32]
                    cmd = str(packet.get("command", ""))[:24]
                    data = packet.get("data", {})
                    if not isinstance(data, dict):
                        data = {}
                    out = {"type": "command", "peer_id": pid, "name": peer_meta["name"],
                           "command": cmd, "target": target, "data": data}
                    if target == self.local_id:
                        self.events.put(out)
                    elif target in self.peers:
                        self._host_send_one(target, out)
                elif ptype == "choir":
                    # Choir control uses the same room router as other reliable events.
                    # Invite/accept/decline/leave are point-to-point; session updates and
                    # playback controls are broadcast to the room (excluding the sender).
                    action = str(packet.get("action", ""))[:32]
                    if action not in ("invite", "accept", "decline", "member_update", "leave_member",
                                      "start", "pause", "finish", "disband", "song_switch"):
                        continue
                    target = str(packet.get("target", "") or "")[:32]
                    data = packet.get("data", {})
                    if not isinstance(data, dict):
                        data = {}
                    out = {"type": "choir", "action": action, "peer_id": pid,
                           "name": peer_meta["name"], "target": target, "data": data,
                           "sent_at": time.time()}
                    if target:
                        if target == self.local_id:
                            self.events.put(out)
                        elif target in self.peers:
                            self._host_send_one(target, out)
                    else:
                        self.events.put(out)
                        self._host_broadcast(out, exclude=pid)
                elif ptype == "visual_event":
                    event = packet.get("event")
                    if isinstance(event, dict):
                        out = {"type": "visual_event", "peer_id": pid, "name": peer_meta["name"],
                               "event": event, "sent_at": time.time()}
                        self.events.put(out)
                        self._host_broadcast(out, exclude=pid)
                elif ptype == "song_tick":
                    out = dict(packet); out["peer_id"] = pid; out["name"] = peer_meta["name"]
                    self.events.put(out); self._host_broadcast(out, exclude=pid)
                elif ptype == "song_stop":
                    out = {"type": "song_stop", "peer_id": pid}
                    self.events.put(out); self._host_broadcast(out, exclude=pid)
                elif ptype == "trail_config":
                    profile = _petzhu_mp_sanitize_trail_profile(packet.get("profile"))
                    peer_meta["trail_profile"] = profile
                    with self.lock:
                        if pid in self.peers:
                            self.peers[pid]["trail_profile"] = profile
                    out = {"type": "trail_config", "peer_id": pid, "profile": profile,
                           "sent_at": time.time()}
                    self.events.put(out)
                    # Tiny, event-driven profile update; no style information rides in per-frame states.
                    self._host_broadcast(out, exclude=pid)
                elif ptype == "asset_ack":
                    self._record_asset_ack(pid, str(packet.get("target", ""))[:32], bool(packet.get("ok", False)))
                elif ptype == "leave":
                    break
        except Exception:
            pass
        finally:
            try:
                if stream is not None: stream.close()
            except Exception: pass
            try: sock.close()
            except Exception: pass
            if pid:
                with self.lock:
                    existed = pid in self.peers
                    self.peers.pop(pid, None); self.states.pop(pid, None)
                    self._peer_sockets.pop(pid, None); self._peer_locks.pop(pid, None)
                    self._pending_asset_sync.pop(pid, None)
                    timer = self._ready_timeouts.pop(pid, None)
                if timer:
                    try: timer.cancel()
                    except Exception: pass
                if existed and self.running and not self.stop_event.is_set():
                    self.events.put({"type": "peer_leave", "peer_id": pid})
                    self._host_broadcast({"type": "peer_leave", "peer_id": pid})
                    # peer_leave is enough to incrementally update clients; avoid re-sending all assets.

    def _record_asset_ack(self, receiver, target, ok):
        ready_pid = None
        with self.lock:
            for joining, data in self._pending_asset_sync.items():
                existing = data["existing"]
                if joining == receiver and target in existing:
                    data["new_to_existing"].add(target)
                    if not ok: data["failed"].add("%s:%s" % (receiver, target))
                elif joining == target and receiver in existing:
                    data["from_existing"].add(receiver)
                    if not ok: data["failed"].add("%s:%s" % (receiver, target))
            for joining, data in self._pending_asset_sync.items():
                existing = data["existing"]
                if existing.issubset(data["from_existing"]) and existing.issubset(data["new_to_existing"]):
                    ready_pid = joining; break
        if ready_pid: self._send_asset_ready(ready_pid, False)

    def _force_asset_ready(self, pid):
        self._send_asset_ready(pid, True)

    def _send_asset_ready(self, pid, timed_out=False):
        with self.lock:
            data = self._pending_asset_sync.pop(pid, None)
            timer = self._ready_timeouts.pop(pid, None)
            exists = pid in self.peers
            failed = bool(data and data.get("failed"))
        if timer:
            try: timer.cancel()
            except Exception: pass
        if exists:
            packet = {"type": "asset_ready", "fallback": bool(timed_out or failed), "timed_out": bool(timed_out)}
            self._host_send_one(pid, packet)
            self.events.put({"type": "assets_ready", "peer_id": pid, "fallback": bool(timed_out or failed), "timed_out": bool(timed_out)})

    def _client_read_loop(self, sock, stream):
        generation = getattr(self, "_mp_session_generation", 0)
        try:
            while self.running and not self.stop_event.is_set() and generation == getattr(self, "_mp_session_generation", 0):
                packet = _petzhu_mp_read_json_line(stream)
                # Drop any buffered message delivered by a superseded connection.
                if generation != getattr(self, "_mp_session_generation", 0):
                    break
                ptype = str(packet.get("type", ""))
                if ptype == "state":
                    pid = str(packet.get("peer_id", "")); state = packet.get("state")
                    if pid and pid != self.local_id and isinstance(state, dict):
                        with self.lock: self.states[pid] = dict(state)
                elif ptype == "roster":
                    self._load_roster(packet.get("members", []), packet.get("states", {})); self.events.put(packet)
                elif ptype == "peer_join":
                    member = packet.get("member")
                    if isinstance(member, dict) and member.get("id"):
                        with self.lock: self.peers[str(member["id"])] = member
                        self.events.put(packet)
                elif ptype == "peer_leave":
                    pid = str(packet.get("peer_id", ""))
                    with self.lock: self.peers.pop(pid, None); self.states.pop(pid, None)
                    self.events.put(packet)
                elif ptype == "trail_config":
                    pid = str(packet.get("peer_id", ""))[:32]
                    profile = _petzhu_mp_sanitize_trail_profile(packet.get("profile"))
                    if pid:
                        with self.lock:
                            if pid in self.peers:
                                self.peers[pid]["trail_profile"] = profile
                    packet["profile"] = profile
                    self.events.put(packet)
                elif ptype == "choir":
                    self.events.put(packet)
                elif ptype in ("chat", "song_tick", "song_stop", "visual_event"):
                    self.events.put(packet)
                elif ptype == "command":
                    if str(packet.get("target", "")) in ("", self.local_id): self.events.put(packet)
                elif ptype == "asset_ready":
                    self.connected = True; self.events.put(packet)
                    self._set_status("联机成功。成员资源已检查；不能解码的图像会使用默认珠珠图像。")
                elif ptype == "room_closed":
                    self.events.put(packet); self.connected = False; self.running = False; break
                elif ptype == "reject":
                    self._set_status("连接被拒绝：" + str(packet.get("reason", "未知原因"))); break
        except Exception as exc:
            if not self._manual_stop and not self.stop_event.is_set():
                self.events.put({"type": "disconnected", "reason": str(exc)[:200]})
        finally:
            if not self._manual_stop and not self.stop_event.is_set() and self.mode == "client":
                was_connected = self.connected
                self.connected = False; self.running = False
                if was_connected: self.events.put({"type": "disconnected", "reason": "与房主的连接已断开"})

    def _load_roster(self, members, states):
        new_peers = {}
        for meta in members if isinstance(members, list) else []:
            if isinstance(meta, dict):
                pid = str(meta.get("id", ""))
                if pid and pid != self.local_id: new_peers[pid] = meta
        new_states = {}
        for pid, state in (states or {}).items() if isinstance(states, dict) else []:
            if str(pid) != self.local_id and isinstance(state, dict): new_states[str(pid)] = state
        with self.lock:
            self.peers = new_peers; self.states.update(new_states)
            for pid in list(self.states):
                if pid not in self.peers: self.states.pop(pid, None)

    def get_members(self):
        """返回包含本人的房间成员清单；远端桌宠渲染层会自行排除 local_id。"""
        with self.lock:
            if not self.running or self.mode == "offline":
                return []
            local_meta = dict(self._local_meta or {})
            local_meta.update({
                "id": self.local_id,
                "name": self.local_name,
                "ip": self.host if self.mode == "host" else str(local_meta.get("ip", "未知地址")),
                "is_host": self.mode == "host",
            })
            return [local_meta] + [dict(m) for m in self.peers.values()]

    def get_states(self):
        with self.lock: return {pid: dict(value) for pid, value in self.states.items()}

    def publish_state(self, state):
        if not self.running: return
        packet = {"type": "state", "state": state, "peer_id": self.local_id}
        with self.lock: self.local_state = dict(state)
        try:
            if self.mode == "host": self._host_broadcast(packet)
            elif self.client_socket is not None: _petzhu_mp_send_socket(self.client_socket, packet, self.write_lock)
        except Exception: pass

    def send_chat(self, text):
        if not self.connected or not self.running: return False
        text = str(text or "").strip()[:1000]
        if not text: return False
        try:
            if self.mode == "host":
                out = {"type": "chat", "peer_id": self.local_id, "name": self.local_name,
                       "ip": self.host, "text": text, "time": time.time()}
                self.events.put(out); self._host_broadcast(out)
            else: _petzhu_mp_send_socket(self.client_socket, {"type": "chat", "text": text}, self.write_lock)
            return True
        except Exception: return False

    def send_command(self, target, command="visit", data=None):
        if not self.connected or not self.running: return False
        target = str(target or "")[:32]
        payload = data if isinstance(data, dict) else {}
        packet = {"type": "command", "target": target, "command": str(command)[:24], "data": payload}
        try:
            if self.mode == "host":
                if target == self.local_id:
                    self.events.put({**packet, "peer_id": self.local_id, "name": self.local_name})
                    return True
                return self._host_send_one(target, {**packet, "peer_id": self.local_id, "name": self.local_name})
            _petzhu_mp_send_socket(self.client_socket, packet, self.write_lock)
            return True
        except Exception:
            return False

    def send_song_tick(self, song_id, step, data=None, bpm=128):
        if not self.connected or not self.running: return
        packet = {"type": "song_tick", "peer_id": self.local_id, "song_id": str(song_id),
                  "step": int(step), "bpm": int(bpm), "data": data if isinstance(data, dict) else None,
                  "sent_at": time.time()}
        try:
            if self.mode == "host": self._host_broadcast(packet)
            elif self.client_socket is not None: _petzhu_mp_send_socket(self.client_socket, packet, self.write_lock)
        except Exception: pass

    def send_song_stop(self):
        if not self.connected or not self.running: return
        packet = {"type": "song_stop", "peer_id": self.local_id}
        try:
            if self.mode == "host": self._host_broadcast(packet)
            elif self.client_socket is not None: _petzhu_mp_send_socket(self.client_socket, packet, self.write_lock)
        except Exception: pass

    def send_visual_event(self, event):
        """转发短时视觉事件（点击星光等）；状态快照则负责维持动作的持续部分。"""
        if not self.connected or not self.running or not isinstance(event, dict):
            return False
        packet = {"type": "visual_event", "event": event}
        try:
            if self.mode == "host":
                out = {"type": "visual_event", "peer_id": self.local_id, "name": self.local_name,
                       "event": event, "sent_at": time.time()}
                self._host_broadcast(out)
                return True
            if self.client_socket is not None:
                _petzhu_mp_send_socket(self.client_socket, packet, self.write_lock)
                return True
        except Exception:
            return False
        return False

    def ack_assets(self, target_id, ok=True):
        try:
            if self.mode == "host": self._record_asset_ack(self.local_id, str(target_id), bool(ok))
            elif self.mode == "client" and self.client_socket is not None:
                _petzhu_mp_send_socket(self.client_socket, {"type": "asset_ack", "target": str(target_id), "ok": bool(ok)}, self.write_lock)
        except Exception: pass

    def stop(self, notify=True, quiet=False):
        mode, was_running = self.mode, self.running
        self._manual_stop = True; self.stop_event.set(); self.running = False; self.connected = False
        if mode == "host" and notify and self.server_socket is not None:
            self._host_broadcast({"type": "room_closed", "reason": "房主关闭了房间"})
        elif mode == "client" and self.client_socket is not None and was_running:
            try: _petzhu_mp_send_socket(self.client_socket, {"type": "leave"}, self.write_lock)
            except Exception: pass
        for timer in list(self._ready_timeouts.values()):
            try: timer.cancel()
            except Exception: pass
        self._ready_timeouts.clear(); self._pending_asset_sync.clear()
        for sock in [self.server_socket, self.client_socket] + list(self._peer_sockets.values()):
            try:
                if sock is not None: sock.shutdown(socket.SHUT_RDWR)
            except Exception: pass
            try:
                if sock is not None: sock.close()
            except Exception: pass
        try:
            if self.client_stream is not None: self.client_stream.close()
        except Exception: pass
        self.server_socket = None; self.client_socket = None; self.client_stream = None
        with self.lock:
            self.peers.clear(); self.states.clear(); self.local_state = {}
            self._peer_sockets.clear(); self._peer_locks.clear()
        self.mode = "offline"; self.room_code = ""; self.host = ""; self.port = 0; self.room_key = ""
        self._manual_stop = False
        if was_running and not quiet: self._set_status("房间已关闭" if mode == "host" else "已断开联机")


class _PETZhuRemotePetView:
    """在桌面上单独显示另一位玩家的桌宠，而不是放进房间容器。"""
    def __init__(self, app, peer_id, meta):
        self.app, self.peer_id, self.meta = app, str(peer_id), dict(meta or {})
        self.win = tk.Toplevel(app.root); _safe_overrideredirect(self.win, True)
        try:
            self.win.attributes("-topmost", True); self.win.wm_attributes("-transparentcolor", TRANSPARENT_COLOR)
        except Exception: pass
        self.win.configure(bg=TRANSPARENT_COLOR)
        self._display_scale = max(0.05, min(4.0, float(getattr(app, "_pet_display_scale", 1.0) or 1.0)))
        self.w = max(48, int(getattr(app, "canvas_w", 340))); self.h = max(60, int(getattr(app, "canvas_h", 250)))
        self.canvas = tk.Canvas(self.win, width=self.w, height=self.h, bg=TRANSPARENT_COLOR, highlightthickness=0, bd=0)
        # 只保护远端转述气泡的三个 Canvas 图元；名字、桌宠动作以及其他 UI
        # 仍保留原有主题行为，避免为了气泡颜色而改变整张远端画布。
        self.canvas._petzhu_theme_hue_preserve_item_ids = set()
        self.canvas.pack()
        self._custom_pil = {}; self._custom_photo = {}; self._photo_refs = {}
        self._default_pil = {}; self._default_photo_cache = {}
        self._assets_loaded = False; self._asset_ok = True; self._last_geometry = None; self._last_meta_assets = None
        self.slot = 0
        self._source_origin = None
        self._load_default_assets()
        self.pet_x = int(getattr(app, "pet_x", 20)); self.pet_y = int(getattr(app, "pet_y", 85))
        self.pet_w = int(getattr(app, "pet_w", 150)); self.pet_h = int(getattr(app, "pet_h", 150))
        self.bubble_y = int(getattr(app, "bubble_y", 0)); self.bubble_h = int(getattr(app, "bubble_h", 80))
        margin = max(1, int(getattr(app, "margin", round(18 * self._display_scale)) or round(18 * self._display_scale)))
        content_x = int(getattr(app, "_song_content_x", 0) or 0)
        base_width = max(self.pet_w + 2 * margin, int(round(340 * self._display_scale)))
        bx1, bx2, by1 = content_x + margin, content_x + base_width - margin, self.bubble_y
        by2 = by1 + self.bubble_h
        fill = str(globals().get("BUBBLE_FILL", "#fff7fb")); edge = str(globals().get("BUBBLE_OUTLINE", "#e3adc5"))
        ink = str(globals().get("BUBBLE_TEXT", "#604154"))
        outline_w = max(1, int(round(2 * self._display_scale)))
        tail_half = max(2, int(round(9 * self._display_scale)))
        tail_h = max(2, int(round(10 * self._display_scale)))
        pad_x = max(2, int(round(16 * self._display_scale)))
        self.bubble_bg_id = self.canvas.create_rectangle(bx1, by1, bx2, by2, fill=fill, outline=edge, width=outline_w, state="hidden")
        self.bubble_tail_id = self.canvas.create_polygon([content_x+base_width//2-tail_half,by2-1,content_x+base_width//2+tail_half,by2-1,content_x+base_width//2,by2+tail_h], fill=fill, outline=edge, width=outline_w, state="hidden")
        self.bubble_text_id = self.canvas.create_text(bx1+pad_x, by1+self.bubble_h//2, anchor="w", width=max(8,bx2-bx1-2*pad_x), text="", fill=ink, font=("微软雅黑", max(4,int(getattr(app, "_bubble_font_size", round(12*self._display_scale)) or round(12*self._display_scale))), "bold"), justify="left", state="hidden")
        # These IDs are set immediately after creation and then remain immune to
        # the receiver's hue transform. Purge any initial-color records as well,
        # so later global theme refreshes cannot repaint a sender-colored relay.
        self.canvas._petzhu_theme_hue_preserve_item_ids = {
            int(self.bubble_bg_id), int(self.bubble_tail_id), int(self.bubble_text_id)
        }
        try:
            tracked = _PETZHU_THEME_HUE_STATE["canvases"].get(self.canvas, {})
            for _protected_id in self.canvas._petzhu_theme_hue_preserve_item_ids:
                tracked.pop(_protected_id, None)
        except Exception:
            pass
        self.pet_item = self.canvas.create_image(self.pet_x, self.pet_y, anchor="nw")
        self.name_id = self.canvas.create_text(self.pet_x+self.pet_w//2, max(by2+11,self.pet_y-7), text=str(self.meta.get("name","桌宠"))[:24], fill="#f2a6cb", font=("微软雅黑",max(4,int(round(9*self._display_scale))),"bold"), state="hidden")
        self.entry_bg_id = self.canvas.create_rectangle(margin,self.h-max(1,int(round(38*self._display_scale))),self.w-margin,self.h-max(1,int(round(8*self._display_scale))),fill="#ffffff",outline="#b9cee6",width=outline_w, state="hidden")
        self.entry_text_id = self.canvas.create_text(margin+max(1,int(round(9*self._display_scale))),self.h-max(1,int(round(23*self._display_scale))),anchor="w",text="与%s说话……"%str(self.meta.get("name","桌宠"))[:16],fill="#7387a2",font=("微软雅黑",max(4,int(round(9*self._display_scale))),), state="hidden")
        # 远端桌宠不显示输入栏；点击可抚摸，按住拖动则控制主人电脑上的真实桌宠移动。
        self._drag_anchor = None
        self._drag_start_pointer = None
        self._drag_start_window = None
        self._drag_moved = False
        self._dragging_remote = False
        self._drag_pending_xy = None
        self._drag_send_after = None
        self._await_remote_move_until = 0.0
        self.canvas.tag_bind(self.pet_item, "<ButtonPress-1>", self._on_pet_press)
        self.canvas.bind("<B1-Motion>", self._on_pet_drag_motion, add="+")
        self.canvas.bind("<ButtonRelease-1>", self._on_pet_release, add="+")
        self._load_assets()

    def _load_assets(self):
        assets = self.meta.get("assets", {}) if isinstance(self.meta.get("assets", {}), dict) else {}
        # update_meta() 只有在收到新的 assets 对象时才会清除此标记，避免每 30ms
        # 把整份 base64 图片反复 repr/比较，造成联机窗口无谓的 CPU 和内存开销。
        if self._assets_loaded:
            return self._asset_ok
        self._assets_loaded = True
        self._custom_pil = {}
        ok = True
        sprites = assets.get("sprites", {}) if isinstance(assets.get("sprites", {}), dict) else {}
        for pose, payload in sprites.items():
            if pose not in ("normal","talk","pat") or not payload: continue
            try:
                raw=base64.b64decode(str(payload).encode("ascii"),validate=True)
                if len(raw)>_PETZHU_MP_MAX_IMAGE: raise ValueError("图片过大")
                with Image.open(io.BytesIO(raw)) as source:
                    image=source.convert("RGBA"); image.load()
                if image.width>2000 or image.height>2000: raise ValueError("图片尺寸过大")
                self._custom_pil[pose]=image
            except Exception:
                ok = False
        # 按需求处理：自定义资源有任一项下载/解码失败时，此桌宠整体使用接收端的默认图像。
        if not ok:
            self._custom_pil = {}
        self._asset_ok=ok
        cache=self.app._mp_remote_song_cache.setdefault(self.peer_id,{})
        for item in assets.get("songs",[]) if isinstance(assets.get("songs",[]),list) else []:
            if isinstance(item,dict) and isinstance(item.get("data"),dict): cache[str(item.get("name","曲目"))[:100]]=item["data"]
        if isinstance(assets.get("active_song"),dict): cache["__active__"]=assets["active_song"]
        return ok

    def update_meta(self, meta):
        old=self.meta.get("assets"); new=(meta or {}).get("assets")
        self.meta.update(dict(meta or {}))
        if new is not None and new is not old:
            self._assets_loaded=False; self._load_assets()
            self._remote_raw_base_pil_cache = {}
            self._remote_transformed_base_key = None
            self._remote_transformed_base_pils = None
            self._remote_sprite_transform_origin = (0, 0)
            self._visual_singing_frames = None
            self._visual_deform_frames = None
            self._visual_photo_cache = {}
        try:
            name=str(self.meta.get("name","桌宠"))[:24]
            self.canvas.itemconfigure(self.name_id,text=name)
            self.canvas.itemconfigure(self.entry_text_id,text="与%s说话……"%name[:16])
            # 远端桌宠只有本机拥有者的输入栏；浏览者看到的独立桌宠不显示输入框。
            self.canvas.itemconfigure(self.entry_bg_id, state="hidden")
            self.canvas.itemconfigure(self.entry_text_id, state="hidden")
        except Exception: pass

    def _load_default_assets(self):
        """加载随程序打包的默认珠珠图，而非借用本机玩家自己的自定义图像。"""
        for pose, filename in (("normal", "normal1.png"), ("talk", "normal2.png"), ("pat", "normal3.png")):
            try:
                path = find_asset(filename)
                if path and os.path.isfile(path):
                    with Image.open(path) as source:
                        image = source.convert("RGBA")
                        image.load()
                    self._default_pil[pose] = image
            except Exception:
                continue

    def _default_photo(self, pose, state):
        try:
            base = self._default_pil.get(pose) or self._default_pil.get("normal")
            if base is None:
                # 最后的兼容兜底：旧发行包若没有随 EXE 打入默认 PNG，仍然保持画面可见。
                if pose == "pat":
                    frames = getattr(self.app, "_breath_blink_frames", [])
                    if frames: return frames[int(float(state.get("breath_phase", 0))*len(frames))%len(frames)]
                return self.app.imgs.get(pose) or self.app.imgs.get("normal")
            phase = float(state.get("breath_phase", 0.0) or 0.0)
            scale = 1.0 + math.sin(phase * math.tau) * 0.012
            if state.get("effect") == "spring":
                spring = abs(math.sin(time.perf_counter() * 15.0))
                width_scale = scale + 0.075 * spring
                height_scale = scale - 0.11 * spring
            else:
                width_scale = scale
                height_scale = scale
            width = max(1, int(self.pet_w * width_scale))
            height = max(1, int(self.pet_h * height_scale))
            key = (pose, width, height)
            photo = self._default_photo_cache.get(key)
            if photo is None:
                photo = ImageTk.PhotoImage(base.resize((width, height), getattr(Image, "Resampling", Image).LANCZOS))
                self._default_photo_cache[key] = photo
                if len(self._default_photo_cache) > 36:
                    self._default_photo_cache.pop(next(iter(self._default_photo_cache)))
            return photo
        except Exception:
            try: return self.app.imgs.get(pose) or self.app.imgs.get("normal")
            except Exception: return None

    def _custom_photo_for(self, pose, state):
        base=self._custom_pil.get(pose) or self._custom_pil.get("normal")
        if base is None: return None
        phase=float(state.get("breath_phase",0) or 0); wobble=math.sin(phase*math.tau)*0.018
        if state.get("singing"): wobble+=math.sin(time.perf_counter()*2.8)*0.025
        if state.get("effect") == "spring": wobble += abs(math.sin(time.perf_counter()*15.0))*0.07
        width=max(1,int(self.pet_w*(1+wobble))); height=max(1,int(self.pet_h*(1-wobble*.65)))
        key=(pose,width,height); photo=self._custom_photo.get(key)
        if photo is None:
            try:
                photo=ImageTk.PhotoImage(base.resize((width,height),getattr(Image,"Resampling",Image).LANCZOS))
                self._custom_photo[key]=photo
                if len(self._custom_photo)>32: self._custom_photo.pop(next(iter(self._custom_photo)))
            except Exception: return None
        return photo

    def set_slot(self, slot):
        """兼容旧调用但不分配桌面位置；位置始终来自桌宠主人电脑的真实坐标。"""
        self.slot = None

    def update_state(self, state):
        # 统一使用文件末尾的权威实现，确保坐标按来源屏幕与本机屏幕分辨率换算。
        return _petzhu_mp_remote_update_state(self, state)

    def _show_remote_potion(self, potion, state):
        try:
            sw = max(1, int(self.app.root.winfo_screenwidth()))
            sh = max(1, int(self.app.root.winfo_screenheight()))
            x = int(float(potion.get("x", 0) or 0))
            y = int(float(potion.get("y", 0) or 0))
            scale = max(0.05, min(4.0, float(getattr(self, "_display_scale", 1.0) or 1.0)))
            width, height = max(8, int(round(56 * scale))), max(8, int(round(66 * scale)))
            if not hasattr(self, "_potion_win") or self._potion_win is None or not self._potion_win.winfo_exists():
                self._potion_win = tk.Toplevel(self.app.root)
                _safe_overrideredirect(self._potion_win, True)
                self._potion_win.attributes("-topmost", True)
                try: self._potion_win.wm_attributes("-transparentcolor", TRANSPARENT_COLOR)
                except Exception: pass
                self._potion_win.configure(bg=TRANSPARENT_COLOR)
                self._potion_canvas = tk.Canvas(self._potion_win, width=width, height=height,
                                                bg=TRANSPARENT_COLOR, highlightthickness=0, bd=0)
                self._potion_canvas.pack()
                c = self._potion_canvas
                def sc(v): return max(1, int(round(v * scale)))
                c.create_rectangle(sc(18), sc(22), sc(38), sc(51), fill="#7fc8ff", outline="#3a80c8", width=max(1, sc(2)))
                c.create_rectangle(sc(22), sc(11), sc(34), sc(22), fill="#a8d8ff", outline="#3a80c8", width=max(1, sc(2)))
                c.create_rectangle(sc(20), sc(6), sc(36), sc(11), fill="#e8e8e8", outline="#909090", width=max(1, sc(2)))
                c.create_text(sc(11), sc(16), text="✦", fill="#ffe98a", font=("Arial", max(4, sc(10)), "bold"))
            else:
                try:
                    self._potion_canvas.configure(width=width, height=height)
                except Exception:
                    pass
            geometry = "%dx%d+%d+%d" % (width, height, max(0, min(sw-width, x)), max(0, min(sh-height, y)))
            if geometry != getattr(self, "_last_potion_geometry", None):
                self._potion_win.geometry(geometry)
                self._last_potion_geometry = geometry
        except Exception:
            self._hide_remote_potion()

    def _hide_remote_potion(self):
        try:
            win=getattr(self,"_potion_win",None)
            if win is not None and win.winfo_exists(): win.destroy()
        except Exception: pass
        self._potion_win=None

    def _on_pet_press(self, event=None):
        try:
            if event is None:
                return
            self._dragging_remote = True
            self._drag_moved = False
            wx, wy = int(self.win.winfo_x()), int(self.win.winfo_y())
            self._drag_anchor = (int(event.x_root) - wx, int(event.y_root) - wy)
            self._drag_start_pointer = (int(event.x_root), int(event.y_root))
            self._drag_start_window = (wx, wy)
            self._drag_pending_xy = (wx, wy)
        except Exception:
            self._dragging_remote = False
            self._drag_anchor = None

    def _queue_remote_move_send(self, force=False):
        try:
            after_id = getattr(self, "_drag_send_after", None)
            if after_id is not None:
                if not force:
                    return
                try:
                    self.win.after_cancel(after_id)
                except Exception:
                    pass
                self._drag_send_after = None
            if force:
                self._flush_remote_move_send()
            else:
                self._drag_send_after = self.win.after(30, self._flush_remote_move_send)
        except Exception:
            self._flush_remote_move_send()

    def _flush_remote_move_send(self):
        self._drag_send_after = None
        pending = getattr(self, "_drag_pending_xy", None)
        if not pending or not getattr(self.app, "_mp", None):
            return
        try:
            x, y = int(pending[0]), int(pending[1])
            sw = max(1, int(self.app.root.winfo_screenwidth()))
            sh = max(1, int(self.app.root.winfo_screenheight()))
            ww = max(1, int(self.win.winfo_width()))
            wh = max(1, int(self.win.winfo_height()))
            # 直接按接收端屏幕宽高归一化坐标；主人端再乘自己的屏幕尺寸，
            # 与正常位置广播采用同一套比例换算，而不是按窗口可用区重新分配位置。
            x = max(0, min(sw - ww, x))
            y = max(0, min(sh - wh, y))
            self._drag_pending_xy = (x, y)
            self.app._mp_move_peer(self.peer_id, x / float(sw), y / float(sh))
        except Exception:
            pass

    def _on_pet_drag_motion(self, event=None):
        if not getattr(self, "_dragging_remote", False) or self._drag_anchor is None or event is None:
            return
        try:
            x = int(event.x_root) - int(self._drag_anchor[0])
            y = int(event.y_root) - int(self._drag_anchor[1])
            sw = max(1, int(self.app.root.winfo_screenwidth()))
            sh = max(1, int(self.app.root.winfo_screenheight()))
            x = max(0, min(max(0, sw - self.w), x))
            y = max(0, min(max(0, sh - self.h), y))
            start_pointer = self._drag_start_pointer or (int(event.x_root), int(event.y_root))
            if (abs(int(event.x_root) - start_pointer[0]) + abs(int(event.y_root) - start_pointer[1])) >= 4:
                self._drag_moved = True
            if not self._drag_moved:
                return
            geom = "%dx%d+%d+%d" % (self.w, self.h, x, y)
            self.win.geometry(geom)
            self._last_geometry = geom
            self._drag_pending_xy = (x, y)
            self._queue_remote_move_send(False)
        except Exception:
            pass

    def _on_pet_release(self, event=None):
        if not getattr(self, "_dragging_remote", False):
            return
        moved = bool(getattr(self, "_drag_moved", False))
        self._dragging_remote = False
        self._drag_anchor = None
        if moved:
            self._queue_remote_move_send(True)
            self._await_remote_move_until = time.monotonic() + 1.0
        else:
            try:
                self.app._mp_visit_peer(self.peer_id, "pat")
            except Exception:
                pass
        self._drag_start_pointer = None
        self._drag_start_window = None

    def _on_pet_click(self,event=None):
        # 旧版兼容入口；正常交互由 press/release 区分点击与拖动。
        try: self.app._mp_visit_peer(self.peer_id,"pat")
        except Exception: pass

    def destroy(self):
        try:
            if self._drag_send_after is not None and self.win.winfo_exists():
                self.win.after_cancel(self._drag_send_after)
        except Exception:
            pass
        self._drag_send_after = None
        self._hide_remote_potion()
        try:
            if self.win is not None and self.win.winfo_exists(): self.win.destroy()
        except Exception: pass


# End of PETZhu desktop multiplayer layer.


def _petzhu_normalize_sprite_transform_v1(value=None):
    """规范化桌宠 PNG 显示变换；仅影响精灵图片，不缩放其他 UI。"""
    data = value if isinstance(value, dict) else {}
    try:
        scale_percent = int(round(float(data.get("scale_percent", data.get("scale", 100)))))
    except (TypeError, ValueError, OverflowError):
        scale_percent = 100
    try:
        offset_x = int(round(float(data.get("offset_x", 0))))
    except (TypeError, ValueError, OverflowError):
        offset_x = 0
    try:
        offset_y = int(round(float(data.get("offset_y", 0))))
    except (TypeError, ValueError, OverflowError):
        offset_y = 0
    return {
        "scale_percent": max(25, min(300, scale_percent)),
        "offset_x": max(-800, min(800, offset_x)),
        "offset_y": max(-800, min(800, offset_y)),
    }


