    def _story_entity_color(self, name):
        story = self.story_current
        if not isinstance(story, dict):
            return self.STORY_ENTITY_COLORS[0]
        name = str(name or "").strip()
        if not name:
            return self.STORY_ENTITY_COLORS[0]
        colors = story.setdefault("entity_colors", {})
        if name == "珠珠":
            colors[name] = self.STORY_ZHUZHU_NAME_COLOR
            return self.STORY_ZHUZHU_NAME_COLOR
        if colors.get(name):
            return str(colors[name])
        score = sum((i + 1) * ord(ch) for i, ch in enumerate(name))
        color = self.STORY_ENTITY_COLORS[score % len(self.STORY_ENTITY_COLORS)]
        colors[name] = color
        return color

    def _story_entity_tag(self, name):
        name = str(name or "").strip()
        score = sum((i + 1) * ord(ch) for i, ch in enumerate(name))
        return "story_entity_%08x" % (score & 0xFFFFFFFF)

    def _story_collect_entities(self, update):
        story = self.story_current
        if not isinstance(story, dict):
            return []
        result = []
        raw = update.get("entities", []) if isinstance(update, dict) else []
        if isinstance(raw, list):
            for item in raw:
                if isinstance(item, dict):
                    name = str(item.get("name", "")).strip()
                    kind = str(item.get("kind", "entity")).strip() or "entity"
                else:
                    name = str(item).strip(); kind = "entity"
                if name and len(name) <= 48:
                    self._story_entity_color(name)
                    result.append({"name": name, "kind": kind})
        ch = story.get("character", {})
        world = story.get("world", {})
        for name, kind in ((ch.get("name"), "player"), ("珠珠", "character"), (world.get("location"), "place")):
            name = str(name or "").strip()
            if name and not any(x.get("name") == name for x in result):
                self._story_entity_color(name)
                result.append({"name": name, "kind": kind})
        return sorted({x["name"]: x for x in result}.values(), key=lambda x: len(x["name"]), reverse=True)

    def _story_configure_reader_tags(self):
        """阅读器文本标签按全局主题选择高对比度颜色。"""
        box = getattr(self, "story_reader_text", None)
        if box is None:
            return
        fs = int(getattr(self, "story_reader_font_size", 22) or 22)
        if bool(getattr(self, "_context_palette_light", False)):
            # 白底阅读区采用深粉标题、深蓝正文；继续故事正文框本身是深粉色。
            # 深粉正文区搭配白色标题/强调文字与深蓝正文，避免字色融进背景。
            title_color = "#ffffff"
            chapter_color = "#1e2a3a"
            action_color = "#ffffff"
            plot_color = "#26364a"
            dialogue_color = "#1e2a3a"
            body_color = "#1e2a3a"
        else:
            title_color = self.STORY_TITLE_COLOR
            chapter_color = self.STORY_CHAPTER_COLOR
            action_color = self.STORY_ACTION_COLOR
            plot_color = self.STORY_PLOT_COLOR
            dialogue_color = self.STORY_DIALOGUE_COLOR
            body_color = "#e8f0ff"
        box.tag_config("story_title", foreground=title_color, font=("微软雅黑", max(18, fs + 8), "bold"), spacing1=8, spacing3=14)
        box.tag_config("story_chapter", foreground=chapter_color, font=("微软雅黑", max(15, fs + 5), "bold"), spacing1=14, spacing3=10)
        box.tag_config("story_action", foreground=action_color, font=("微软雅黑", max(13, fs + 2), "bold"), spacing1=6, spacing3=8)
        box.tag_config("story_plot", foreground=plot_color, font=("微软雅黑", max(12, fs + 1), "bold"), spacing1=5, spacing3=8)
        box.tag_config("story_dialogue", foreground=dialogue_color)
        box.tag_config("story_body", foreground=body_color, font=("微软雅黑", fs))
        if isinstance(self.story_current, dict):
            for name, color in (self.story_current.get("entity_colors", {}) or {}).items():
                # 浅色主题下将过亮的实体颜色压暗，避免粉底/白底上难以阅读。
                try:
                    if bool(getattr(self, "_context_palette_light", False)):
                        rgb = tuple(int(color[i:i+2], 16) for i in (1, 3, 5))
                        color = "#%02x%02x%02x" % tuple(int(c * 0.72) for c in rgb)
                except Exception:
                    pass
                box.tag_config(self._story_entity_tag(name), foreground=str(color), underline=True)

    def _story_insert_rich_text(self, text, entities=None, base_tag="story_body"):
        box = self.story_reader_text
        text = str(text or "")
        start = box.index("end-1c")
        box.insert("end", text, (base_tag,))
        try:
            dialogue_re = re.compile(r'“[^”\n]{1,300}”|「[^」\n]{1,300}」|"[^"\n]{1,300}"')
            for m in dialogue_re.finditer(text):
                box.tag_add("story_dialogue", "%s+%dchars" % (start, m.start()), "%s+%dchars" % (start, m.end()))
        except Exception:
            pass
        for entity in sorted(entities or [], key=lambda x: len(str(x.get("name", ""))), reverse=True):
            name = str(entity.get("name", "")).strip()
            if not name:
                continue
            tag = self._story_entity_tag(name)
            box.tag_config(tag, foreground=self._story_entity_color(name), underline=True)
            pos = 0
            while True:
                idx = text.find(name, pos)
                if idx < 0:
                    break
                box.tag_add(tag, "%s+%dchars" % (start, idx), "%s+%dchars" % (start, idx + len(name)))
                pos = idx + len(name)
        return start

    def _story_style_guide(self, style):
        style = str(style or self.STORY_DEFAULT_WRITING_STYLE).strip()
        style = self.STORY_WRITING_STYLE_ALIASES.get(style, style)
        if style == "自由定调":
            return "按玩家自己输入的文风执行，但必须保持自然、清楚、易读，并严格服从FF14世界观。"
        return self.STORY_WRITING_STYLE_GUIDES.get(style, self.STORY_WRITING_STYLE_GUIDES[self.STORY_DEFAULT_WRITING_STYLE])

    def _story_normalize_hooks(self, raw_hooks, chapter_count):
        """将蓝图中的伏笔统一为少量、可追踪、必须有用途和回收窗口的结构。"""
        hooks = []
        if not isinstance(raw_hooks, list):
            raw_hooks = []
        for idx, item in enumerate(raw_hooks[:EORZEA_STORY_MAX_TOTAL_HOOKS], 1):
            if isinstance(item, dict):
                summary = str(item.get("summary", item.get("text", ""))).strip()
                purpose = str(item.get("purpose", "")).strip()
                hid = str(item.get("id", "H%d" % idx)).strip() or ("H%d" % idx)
                try:
                    intro = max(1, min(chapter_count, int(item.get("introduced_chapter", min(chapter_count, 1 + (idx - 1) * 2)))))
                except Exception:
                    intro = min(chapter_count, 1 + (idx - 1) * 2)
                try:
                    payoff = max(intro + 1, min(chapter_count, int(item.get("payoff_chapter", min(chapter_count, intro + 2)))))
                except Exception:
                    payoff = min(chapter_count, intro + 2)
                required = bool(item.get("must_resolve", True))
            else:
                summary = str(item).strip()
                purpose = "服务后续人物选择或因果推进"
                hid = "H%d" % idx
                intro = min(chapter_count, 1 + (idx - 1) * 2)
                payoff = min(chapter_count, intro + 2)
                required = True
            if not summary:
                continue
            hooks.append({
                "id": hid,
                "summary": summary,
                "purpose": purpose or "服务人物塑造与因果推进",
                "introduced_chapter": intro,
                "payoff_chapter": payoff,
                "must_resolve": required,
            })
        return hooks

