    def _story_entity_color(self, name):
        story = self.story_current
        if not isinstance(story, dict):
            return self.STORY_ENTITY_COLORS[0]
        name = str(name or "").strip()
        if not name:
            return self.STORY_ENTITY_COLORS[0]
        colors = story.setdefault("entity_colors", {})
        if name == "珠珠":
            colors[name] = self.STORY_ZHUZHU_NAME_COLOR
            return self.STORY_ZHUZHU_NAME_COLOR
        if colors.get(name):
            return str(colors[name])
        score = sum((i + 1) * ord(ch) for i, ch in enumerate(name))
        color = self.STORY_ENTITY_COLORS[score % len(self.STORY_ENTITY_COLORS)]
        colors[name] = color
        return color

    def _story_entity_tag(self, name):
        name = str(name or "").strip()
        score = sum((i + 1) * ord(ch) for i, ch in enumerate(name))
        return "story_entity_%08x" % (score & 0xFFFFFFFF)

    def _story_collect_entities(self, update):
        story = self.story_current
        if not isinstance(story, dict):
            return []
        result = []
        raw = update.get("entities", []) if isinstance(update, dict) else []
        if isinstance(raw, list):
            for item in raw:
                if isinstance(item, dict):
                    name = str(item.get("name", "")).strip()
                    kind = str(item.get("kind", "entity")).strip() or "entity"
                else:
                    name = str(item).strip(); kind = "entity"
                if name and len(name) <= 48:
                    self._story_entity_color(name)
                    result.append({"name": name, "kind": kind})
        ch = story.get("character", {})
        world = story.get("world", {})
        desktop_pet_name = str(getattr(self, "pet_name", "珠珠") or "珠珠").strip()
        for name, kind in ((ch.get("name"), "player"), ("珠珠", "character"), (desktop_pet_name, "desktop_pet"), (world.get("location"), "place")):
            name = str(name or "").strip()
            if name and not any(x.get("name") == name for x in result):
                self._story_entity_color(name)
                result.append({"name": name, "kind": kind})
        return sorted({x["name"]: x for x in result}.values(), key=lambda x: len(x["name"]), reverse=True)

    def _story_configure_reader_tags(self):
        """阅读器富文本标签；白底主题使用浅粉纸面、深蓝正文和深粉标题。"""
        box = getattr(self, "story_reader_text", None)
        if box is None:
            return
        fs = int(getattr(self, "story_reader_font_size", 22) or 22)
        light = bool(getattr(self, "_context_palette_light", False))
        if light:
            title_color = "#b52d70"
            chapter_color = "#9d285f"
            action_color = "#b52d70"
            plot_color = "#5d3150"
            dialogue_color = "#1e2a3a"
            body_color = "#1e2a3a"
        else:
            title_color = self.STORY_TITLE_COLOR
            chapter_color = self.STORY_CHAPTER_COLOR
            action_color = self.STORY_ACTION_COLOR
            plot_color = self.STORY_PLOT_COLOR
            dialogue_color = self.STORY_DIALOGUE_COLOR
            body_color = "#e8f0ff"
        box.tag_config("story_title", foreground=title_color, font=("微软雅黑", max(18, fs + 8), "bold"), spacing1=8, spacing3=14)
        box.tag_config("story_chapter", foreground=chapter_color, font=("微软雅黑", max(15, fs + 5), "bold"), spacing1=14, spacing3=10)
        box.tag_config("story_action", foreground=action_color, font=("微软雅黑", max(13, fs + 2), "bold"), spacing1=6, spacing3=8)
        box.tag_config("story_plot", foreground=plot_color, font=("微软雅黑", max(12, fs + 1), "bold"), spacing1=5, spacing3=8)
        box.tag_config("story_dialogue", foreground=dialogue_color)
        box.tag_config("story_body", foreground=body_color, font=("微软雅黑", fs))
        if isinstance(self.story_current, dict):
            desktop_pet_name = str(getattr(self, "pet_name", "珠珠") or "珠珠").strip()
            for name, color in (self.story_current.get("entity_colors", {}) or {}).items():
                tag = self._story_entity_tag(name)
                if str(name).strip() == desktop_pet_name:
                    # 仅桌宠自定义名称随着“主题色”变化；刷新其余富文本标签时也不能覆盖它。
                    base_name_color = str(getattr(self, "STORY_ZHUZHU_NAME_COLOR", "#ff8ac6"))
                    try:
                        box._petzhu_theme_hue_exempt_name_tag = tag
                        box._petzhu_theme_hue_exempt_name_base_color = base_name_color
                        _PETZHU_THEME_HUE_STATE["widgets"].add(box)
                    except Exception:
                        pass
                    color = _petzhu_shift_theme_color(base_name_color)
                else:
                    try:
                        if light:
                            rgb = tuple(int(str(color)[i:i+2], 16) for i in (1, 3, 5))
                            luminance = 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2]
                            if luminance > 170:
                                color = "#%02x%02x%02x" % tuple(int(c * 0.62) for c in rgb)
                    except Exception:
                        pass
                box.tag_config(tag, foreground=str(color), underline=True)

    def _story_insert_rich_text(self, text, entities=None, base_tag="story_body"):
        box = self.story_reader_text
        text = str(text or "")
        start = box.index("end-1c")
        box.insert("end", text, (base_tag,))
        try:
            dialogue_re = re.compile(r'“[^”\n]{1,300}”|「[^」\n]{1,300}」|"[^"\n]{1,300}"')
            for m in dialogue_re.finditer(text):
                box.tag_add("story_dialogue", "%s+%dchars" % (start, m.start()), "%s+%dchars" % (start, m.end()))
        except Exception:
            pass
        for entity in sorted(entities or [], key=lambda x: len(str(x.get("name", ""))), reverse=True):
            name = str(entity.get("name", "")).strip()
            if not name:
                continue
            tag = self._story_entity_tag(name)
            desktop_pet_name = str(getattr(self, "pet_name", "珠珠") or "珠珠").strip()
            if name == desktop_pet_name:
                # 只有玩家设定的桌宠名称跟随主题色；原角色“珠珠”、NPC、地点和其他实体沿用原配色。
                base_name_color = str(getattr(self, "STORY_ZHUZHU_NAME_COLOR", "#ff8ac6"))
                try:
                    box._petzhu_theme_hue_exempt_name_tag = tag
                    box._petzhu_theme_hue_exempt_name_base_color = base_name_color
                    _PETZHU_THEME_HUE_STATE["widgets"].add(box)
                except Exception:
                    pass
                name_color = _petzhu_shift_theme_color(base_name_color)
            else:
                name_color = self._story_entity_color(name)
            box.tag_config(tag, foreground=name_color, underline=True)
            pos = 0
            while True:
                idx = text.find(name, pos)
                if idx < 0:
                    break
                box.tag_add(tag, "%s+%dchars" % (start, idx), "%s+%dchars" % (start, idx + len(name)))
                pos = idx + len(name)
        return start

    def _story_style_guide(self, style):
        style = str(style or self.STORY_DEFAULT_WRITING_STYLE).strip()
        style = self.STORY_WRITING_STYLE_ALIASES.get(style, style)
        if style == "自由定调":
            return "按玩家自己输入的文风执行，但必须保持自然、清楚、易读，并严格服从FF14世界观。"
        return self.STORY_WRITING_STYLE_GUIDES.get(style, self.STORY_WRITING_STYLE_GUIDES[self.STORY_DEFAULT_WRITING_STYLE])

    def _story_normalize_hooks(self, raw_hooks, chapter_count):
        """将蓝图中的伏笔统一为少量、可追踪、必须有用途和回收窗口的结构。"""
        hooks = []
        if not isinstance(raw_hooks, list):
            raw_hooks = []
        for idx, item in enumerate(raw_hooks[:EORZEA_STORY_MAX_TOTAL_HOOKS], 1):
            if isinstance(item, dict):
                summary = str(item.get("summary", item.get("text", ""))).strip()
                purpose = str(item.get("purpose", "")).strip()
                hid = str(item.get("id", "H%d" % idx)).strip() or ("H%d" % idx)
                try:
                    intro = max(1, min(chapter_count, int(item.get("introduced_chapter", min(chapter_count, 1 + (idx - 1) * 2)))))
                except Exception:
                    intro = min(chapter_count, 1 + (idx - 1) * 2)
                try:
                    payoff = max(intro + 1, min(chapter_count, int(item.get("payoff_chapter", min(chapter_count, intro + 2)))))
                except Exception:
                    payoff = min(chapter_count, intro + 2)
                required = bool(item.get("must_resolve", True))
            else:
                summary = str(item).strip()
                purpose = "服务后续人物选择或因果推进"
                hid = "H%d" % idx
                intro = min(chapter_count, 1 + (idx - 1) * 2)
                payoff = min(chapter_count, intro + 2)
                required = True
            if not summary:
                continue
            hooks.append({
                "id": hid,
                "summary": summary,
                "purpose": purpose or "服务人物塑造与因果推进",
                "introduced_chapter": intro,
                "payoff_chapter": payoff,
                "must_resolve": required,
            })
        return hooks


    def _story_random_race_clan(self):
        race = random.choice(self.STORY_RACES)
        return race, race.split("·", 1)[1] if "·" in race else ""

    def _story_random_name(self, race_value, gender="男性", clan_value=""):
        """按FF14各族实际命名逻辑生成角色名，而非简单抽现成NPC姓名。"""
        race = str(race_value or "").split("·", 1)[0]
        clan = str(clan_value or "").strip()
        gender = str(gender or "男性")
        if gender == "不公开":
            gender = random.choice(["男性", "女性"])

        if race == "人族":
            if clan == "高地之民":
                return "%s %s" % (random.choice(self.STORY_HYUR_HIGH_GIVEN), random.choice(self.STORY_HYUR_HIGH_SURNAME))
            return "%s %s" % (random.choice(self.STORY_HYUR_MID_GIVEN), random.choice(self.STORY_HYUR_MID_SURNAME))

        if race == "精灵族":
            if gender == "女性":
                given = random.choice(self.STORY_ELEZEN_GIVEN_STEMS) + random.choice(self.STORY_ELEZEN_F_SUFFIX)
            else:
                given = random.choice(self.STORY_ELEZEN_M_STEMS) + random.choice(self.STORY_ELEZEN_M_SUFFIX)
            surnames = self.STORY_ELEZEN_DUSK_SURNAMES if clan == "黑影之民" else self.STORY_ELEZEN_WILD_SURNAMES
            return "%s %s" % (given, random.choice(surnames))

        if race == "拉拉菲尔族":
            a = random.choice(self.STORY_LALA_SYLLABLES)
            b = random.choice(self.STORY_LALA_LONG)
            c = random.choice([x for x in self.STORY_LALA_SYLLABLES if x.lower() != a.lower()])
            if clan == "沙漠之民":
                if gender == "女性":
                    return "%s%s%s %s%s" % (a, a, b, a, b)
                return "%s%s%s %s%s%s" % (a, a, b, c, c, b)
            if gender == "女性":
                return "%s%s%s %s%s" % (a, b, b, a, b)
            return "%s%s %s%s" % (a, b, c, b)

        if race == "猫魅族":
            if clan == "逐日之民":
                letter = random.choice(self.STORY_MIQO_TRIBE_LETTERS)
                given = random.choice(self.STORY_MIQO_GIVEN)
                if gender == "男性":
                    # 绝大多数是Tia，少量随机到Nunh，避免把玩家默认生成成稀有社会身份。
                    title = random.choices(["Tia", "Nunh"], weights=[9, 1], k=1)[0]
                    return "%s'%s %s" % (letter, given, title)
                sire = random.choice(self.STORY_MIQO_GIVEN)
                return "%s'%s %s" % (letter, given, sire)
            given = random.choice(self.STORY_MIQO_KEEPER_GIVEN)
            family = random.choice(self.STORY_MIQO_KEEPER_SURNAME)
            if gender == "男性":
                suffix = random.choice(["'a", "'to", "'li", "'sae", "'ra", "'ir", "'wo", "'ya", "'zi", "'tan"])
                return "%s%s %s" % (given, suffix, family)
            return "%s %s" % (given, family)

        if race == "鲁加族":
            if clan == "北洋之民":
                first_a = random.choice(self.STORY_ROEGA_OLD_A)
                first_b = random.choice(self.STORY_ROEGA_F_END if gender == "女性" else self.STORY_ROEGA_OLD_B)
                first = first_a + first_b
                father = random.choice(self.STORY_ROEGA_OLD_A) + random.choice(self.STORY_ROEGA_OLD_B)
                return "%s %s%s" % (first, father, "wyn" if gender == "女性" else "syn")
            return "%s %s" % (random.choice(self.STORY_ROEGA_HELL_DESC), random.choice(self.STORY_ROEGA_HELL_NOUN))

        if race == "敖龙族":
            if clan == "晨曦之民":
                return "%s %s" % (random.choice(self.STORY_AURA_RAEN_GIVEN), random.choice(self.STORY_AURA_RAEN_SURNAME))
            given = random.choice(self.STORY_AURA_XAELA_GIVEN_A) + random.choice(self.STORY_AURA_XAELA_GIVEN_B)
            return "%s %s" % (given, random.choice(self.STORY_AURA_XAELA_CLANS))

        if race == "硌狮族":
            given = random.choice(self.STORY_HROTH_GIVEN)
            queen = random.choice(self.STORY_HROTH_QUEEN).lstrip("A")
            if queen:
                queen = queen[0].upper() + queen[1:]
            # “掠日之民/迷踪之民”是角色创建器中的社会状态标签；官方规则本身使用Helion/Lost概念。
            if clan == "掠日之民":
                return "%s A%s" % (given, queen)
            return "%s %ssch" % (given, queen)

        if race == "维埃拉族":
            use_city_name = random.random() < 0.35
            given = random.choice(self.STORY_VIERA_CITY_NAMES if use_city_name else self.STORY_VIERA_FOREST)
            if clan == "密林之民":
                if gender == "男性":
                    return "%s %s-%s" % (given, random.choice(self.STORY_VIERA_RAVA_MALE_A), random.choice(self.STORY_VIERA_RAVA_MALE_B))
                return "%s %s" % (given, random.choice(self.STORY_VIERA_VILLAGES_RAVA)) if random.random() > 0.25 else given
            if gender == "男性":
                return "%s %s" % (given, random.choice(self.STORY_VIERA_VEENA_MALE))
            return "%s %s" % (given, random.choice(self.STORY_VIERA_VILLAGES_VEENA)) if random.random() > 0.25 else given

        return "%s %s" % (random.choice(self.STORY_HYUR_MID_GIVEN), random.choice(self.STORY_HYUR_MID_SURNAME))

    def _story_random_identity(self, race_value, clan_value="", hometown=""):
        race = str(race_value or "").strip()
        clan = str(clan_value or "").strip()
        pool = []
        if race in self.STORY_RACES:
            prefix = race.split("·", 1)[0]
            pool = list(self.STORY_IDENTITY_TEMPLATES.get(race, self.STORY_IDENTITY_TEMPLATES.get(prefix, [])))
            pool.extend(self.STORY_IDENTITY_EXTRAS.get(race, []))
        if not pool:
            pool = list(self.STORY_IDENTITY_FALLBACK)
        identity = random.choice(pool)
        # 少量根据开局地点做自然适配；不引入新的职业或超出身份设定的能力。
        home = str(hometown or "").strip()
        if home:
            replacements = {
                "黑暗森林": "黑衣森林",
                "斯卡泰山脉": "斯卡泰山脉",
                "阿吉姆大草原": "阿吉姆大草原",
            }
            for a,b in replacements.items():
                identity = identity.replace(a,b)
        return identity

