                if err:
                    status2.config(text="生成失败：%s"%err,fg="#ff7777"); return
                put_form({k:card.get(k,"") for k in ("name","gender","race","clan","hometown","identity","appearance","personality","past","goal","weakness")})
                status2.config(text="AI人物卡已生成；故事主线保持不变。",fg="#5cd68a")
