        right_page = tk.Frame(book, bg=theme_colors["value"].get("app_bg", theme_colors["value"]["page"]), bd=0, highlightthickness=0)
        tools_page = tk.Frame(book, bg=theme_colors["value"]["panel"], bd=0, highlightthickness=0)
        left_page.pack_propagate(False)
        right_page.pack_propagate(False)
        tools_page.pack_propagate(False)
