        left_window = book.create_window(0, 0, window=left_page, anchor="nw", tags=("page_windows",))
        right_window = book.create_window(0, 0, window=right_page, anchor="nw", tags=("page_windows",))
        tools_window = book.create_window(0, 0, window=tools_page, anchor="nw", tags=("page_windows",))
        book_redraw_job = {"after": None}

        def draw_book_art(_event=None):
            """三栏拼贴界面：左侧导航、中间日记纸、右侧快捷功能。"""
            book_redraw_job["after"] = None
            try:
                aw, ah = int(book.winfo_width()), int(book.winfo_height())
                width = aw if aw >= 300 else 1100
                height = ah if ah >= 300 else 700
                book.delete("book_art")
                # 工作台外框随当前记录分类变色。
                current_theme = theme_colors["value"]
                book.create_rectangle(3, 3, width-3, height-3, fill=current_theme["app_bg"], outline=current_theme["panel_edge"], width=2, tags="book_art")
                left_x, pad, top = 10, 10, 10
                # 固定左右栏宽度：首次绘制时 Canvas 还可能处于临时尺寸，
                # 若按 width 比例计算，首帧会使用最小宽度，映射窗口后又变宽，
                # 造成左侧“记录分类 / 日历索引”整列可见地横向拉伸。
                # 左右功能栏保持固定宽度，只让中间正文页吸收窗口宽度变化。
                left_w = 205
                tools_w = 190
                center_x = left_x + left_w + pad
                tools_x = width - tools_w - 10
                center_w = max(340, tools_x - center_x - pad)
                panel_y, panel_h = 11, height - 22
                # 浅色阴影与卡片边框。
                panels = [
                    (left_x, panel_y, left_x+left_w, panel_y+panel_h, current_theme["panel"], current_theme["panel_edge"]),
                    (center_x, panel_y, center_x+center_w, panel_y+panel_h, current_theme["light"], current_theme["edge"]),
                    (tools_x, panel_y, width-10, panel_y+panel_h, current_theme["panel"], current_theme["panel_edge"]),
                ]
                for x1, y1, x2, y2, fill, outline in panels:
                    book.create_rectangle(x1+3, y1+4, x2+3, y2+4, fill=current_theme["shadow"], outline="", tags="book_art")
                    book.create_rectangle(x1, y1, x2, y2, fill=fill, outline=outline, width=2, tags="book_art")
                    book.create_line(x1+8, y1+28, x2-8, y1+28, fill=outline, width=1, tags="book_art")
                # 彩纸几何拼贴：分散在卡片边缘和空白处，不遮正文控件。
                collage = [
                    ([(left_x+8, panel_y+8), (left_x+39, panel_y+8), (left_x+29, panel_y+20), (left_x+3, panel_y+18)], "#f5bfd2"),
                    ([(center_x+center_w-70, panel_y+6), (center_x+center_w-43, panel_y+6), (center_x+center_w-52, panel_y+24), (center_x+center_w-78, panel_y+20)], "#c9def7"),
                    ([(tools_x+18, panel_y+9), (tools_x+37, panel_y+9), (tools_x+42, panel_y+26), (tools_x+21, panel_y+24)], "#f4d7a6"),
                    ([(center_x+9, panel_y+panel_h-32), (center_x+33, panel_y+panel_h-27), (center_x+27, panel_y+panel_h-9), (center_x+6, panel_y+panel_h-15)], "#d9c9f2"),
                    ([(tools_x+tools_w-40, panel_y+panel_h-35), (tools_x+tools_w-15, panel_y+panel_h-31), (tools_x+tools_w-22, panel_y+panel_h-9), (tools_x+tools_w-44, panel_y+panel_h-16)], "#c8e8dc"),
                    ([(center_x+center_w-118, panel_y+panel_h-7), (center_x+center_w-75, panel_y+panel_h-7), (center_x+center_w-91, panel_y+panel_h-18), (center_x+center_w-129, panel_y+panel_h-16)], "#f4c6d8"),
                    ([(left_x+left_w-24, panel_y+panel_h-45), (left_x+left_w-8, panel_y+panel_h-41), (left_x+left_w-13, panel_y+panel_h-23), (left_x+left_w-29, panel_y+panel_h-28)], "#d6c5ef"),
                ]
                for pts, color in collage:
                    flat = [coord for point in pts for coord in point]
                    book.create_polygon(*flat, fill=color, outline="#ffffff", width=1, tags="book_art")
                for cx, cy, r, color in [
                    (center_x+18, panel_y+45, 4, "#f2b7cc"),
                    (center_x+center_w-22, panel_y+48, 5, "#e9c5da"),
                    (left_x+left_w-17, panel_y+49, 4, "#bcd8f4"),
                    (tools_x+tools_w-23, panel_y+48, 4, "#e6c3ee"),
                ]:
                    book.create_oval(cx-r, cy-r, cx+r, cy+r, fill=color, outline="", tags="book_art")
                page_y, page_h = 14, height - 28
                book.coords(left_window, left_x+5, page_y)
                book.itemconfigure(left_window, width=left_w-10, height=page_h)
                book.coords(right_window, center_x+5, page_y)
                book.itemconfigure(right_window, width=center_w-10, height=page_h)
                book.coords(tools_window, tools_x+5, page_y)
                book.itemconfigure(tools_window, width=tools_w-10, height=page_h)
                book.tag_lower("book_art")
                for item in (left_window, right_window, tools_window):
                    book.tag_raise(item)
            except Exception:
                pass

        def queue_book_redraw(_event=None):
            if book_redraw_job["after"] is None:
                try:
                    book_redraw_job["after"] = book.after_idle(draw_book_art)
                except Exception:
                    book_redraw_job["after"] = None

