        ink = theme_colors["value"]["ui_ink"]
        ink_soft = theme_colors["value"]["ui_soft"]
        accent = theme_colors["value"]["accent"]

        # 左侧五个选项直接对应纸张；打开存档时高亮当前正在使用的纸张。
        nav_selected = {"value": _paper_to_section_initial.get(theme_name["value"], "日记")}
