        font_sizes = {"小": 16, "中": 19, "大": 22, "特大": 25}
        font_size_state = {"value": font_sizes[ui_font_preset["value"]]}
        font_buttons = {}
        font_base_registry = {}
        font_objects = {}  # 保留 tkfont.Font 引用，统一同步全本控件字号
        font_scale_map = {"小": 0.82, "中": 0.96, "大": 1.12, "特大": 1.32}
        topic_row = tk.Frame(right_page, bg=theme_colors["value"].get("app_bg", paper))
