        def enable_widget_background_transparency(widget, key_color=None):
            """为单个 Windows 子窗口设置色键透明。

            正文 Text 使用当前纸张底色作为自身色键，而不是荧绿色：背景空白会透出
            下层纸纹/本页像素背景，字形抗锯齿仍以纸张色混合，因此不会出现绿边。
            贴纸 Canvas 不传 key_color，继续使用笔记本窗口的专用透明键。
            """
            key_color = str(key_color or transparent_key)
            # PyInstaller --onefile 下，Tk Text/Canvas 的子 HWND 使用 WS_EX_LAYERED +
            # LWA_COLORKEY 在部分 Windows/Tk 组合里会导致首次重绘透明/空白，且 -windowed
            # 没有控制台可见异常。冻结版本采用不透明纸色安全路径，保证主界面可见；
            # 源码运行仍保留原来的纸纹透明效果。贴纸层会根据 False 返回值退回预览区。
            if os.name != "nt" or bool(getattr(sys, "frozen", False)):
                try:
                    widget.configure(bg=key_color)
                except Exception:
                    pass
                return False
            try:
                import ctypes
                from ctypes import wintypes
                win.update_idletasks()
                user32 = ctypes.WinDLL("user32", use_last_error=True)
                get_long = getattr(user32, "GetWindowLongPtrW", user32.GetWindowLongW)
                set_long = getattr(user32, "SetWindowLongPtrW", user32.SetWindowLongW)
                hwnd = wintypes.HWND(widget.winfo_id())
                get_long.argtypes = [wintypes.HWND, ctypes.c_int]
                get_long.restype = ctypes.c_ssize_t
                set_long.argtypes = [wintypes.HWND, ctypes.c_int, ctypes.c_ssize_t]
                set_long.restype = ctypes.c_ssize_t
                ex_style = int(get_long(hwnd, -20))
                ws_ex_layered = 0x00080000
                if not ex_style & ws_ex_layered:
                    set_long(hwnd, -20, ex_style | ws_ex_layered)
                r, g, b = (int(key_color[i:i+2], 16) for i in (1, 3, 5))
                colorref = r | (g << 8) | (b << 16)
                user32.SetLayeredWindowAttributes.argtypes = [wintypes.HWND, wintypes.COLORREF,
                                                               wintypes.BYTE, wintypes.DWORD]
                user32.SetLayeredWindowAttributes.restype = wintypes.BOOL
                ok = bool(user32.SetLayeredWindowAttributes(hwnd, colorref, 0, 0x00000001))
                if not ok:
                    widget.configure(bg=key_color)
                return ok
            except Exception:
                try:
                    widget.configure(bg=key_color)
                except Exception:
                    pass
                return False

        def enable_note_text_background_transparency():
            """外沿保持不透明纯色，只有正文 Text 在 Windows 上透出内部纸张纹理。"""
            note_frame_transparency["enabled"] = False
