# ============================================================
# PETZhu v29 follow-up:
# - Hide relay instruction text while relay mode is off.
# - Centralize relay button palette/state; older code had three writers for bg only,
#   while the generic API-window theme painter repainted every Tk Button and the local
#   button updater forced hardcoded dark colors. These conflicting writers caused colors
#   to appear inconsistent after theme changes or periodic refreshes.
# ============================================================
def _petzhu_mp_relay_theme_color(app, saturation=0.62, value=0.66):
    """Build a relay-control color from the current PETZhu theme hue, not a fixed pink.

    The hue slider controls the accent hue. Saturation/value are deliberately chosen
    per UI state so the selected color remains readable on both light and dark panels.
    """
    try:
        hue = float(getattr(app, "theme_hue", _PETZHU_THEME_HUE_STATE.get("hue", _PETZHU_THEME_HUE_DEFAULT))) % 360.0
    except Exception:
        hue = float(_PETZHU_THEME_HUE_STATE.get("hue", _PETZHU_THEME_HUE_DEFAULT)) % 360.0
    try:
        sat = max(0.0, min(1.0, float(saturation)))
        val = max(0.0, min(1.0, float(value)))
    except Exception:
        sat, val = 0.62, 0.66
    r, g, b = colorsys.hsv_to_rgb(hue / 360.0, sat, val)
    return "#%02x%02x%02x" % (round(r * 255), round(g * 255), round(b * 255))


def _petzhu_mp_update_relay_control_visuals(app):
    """Keep relay toggle buttons on the current theme hue across all refresh paths."""
    light = bool(getattr(app, "_context_palette_light", False))
    if light:
        # The off state stays light and low emphasis, but its tint follows the theme.
        off_bg = _petzhu_mp_relay_theme_color(app, saturation=0.20, value=0.96)
        off_fg = "#1e2a3a"
        off_active = _petzhu_mp_relay_theme_color(app, saturation=0.34, value=0.88)
        on_bg = _petzhu_mp_relay_theme_color(app, saturation=0.66, value=0.62)
        on_active = _petzhu_mp_relay_theme_color(app, saturation=0.70, value=0.74)
    else:
        # Dark-mode off state is a subtle dark tint of the selected theme hue.
        off_bg = _petzhu_mp_relay_theme_color(app, saturation=0.28, value=0.24)
        off_fg = "#f5f7fb"
        off_active = _petzhu_mp_relay_theme_color(app, saturation=0.42, value=0.34)
        on_bg = _petzhu_mp_relay_theme_color(app, saturation=0.66, value=0.62)
        on_active = _petzhu_mp_relay_theme_color(app, saturation=0.70, value=0.74)
    on_fg = "#ffffff"

    def style(button, on, room=False):
        try:
            if button is None or not button.winfo_exists():
                return
            bg, fg, active_bg = (on_bg, on_fg, on_active) if on else (off_bg, off_fg, off_active)
            text = (("转述模式：开" if on else "切换到桌宠转述") if room
                    else ("转述：开" if on else "转述：关"))
            button.configure(bg=bg, fg=fg, activebackground=active_bg,
                             activeforeground=on_fg, disabledforeground=fg,
                             highlightbackground=active_bg if on else off_bg,
                             highlightcolor=active_bg, relief="flat", bd=0,
                             text=text)
        except Exception:
            pass

    style(getattr(app, "_mp_local_relay_button", None),
          bool(getattr(app, "_mp_local_relay_mode", False)), room=False)
    ui = getattr(app, "_mp_ui", {}) or {}
    room_on = bool(getattr(app, "_mp_room_relay_mode", False))
    style(ui.get("room_relay_button"), room_on, room=True)

    # The hint is shown only while room relay mode is active; keep it themed too.
    hint = ui.get("relay_hint")
    row = ui.get("relay_row")
    json_button = ui.get("relay_json_button")
    try:
        if hint is not None and hint.winfo_exists():
            if row is not None and row.winfo_exists():
                try:
                    row_bg = str(row.cget("bg"))
                except Exception:
                    row_bg = "#fff0f6" if light else str(getattr(app, "C_BG", "#172536"))
            else:
                row_bg = "#fff0f6" if light else str(getattr(app, "C_BG", "#172536"))
            hint_fg = _petzhu_mp_relay_theme_color(app, saturation=0.52, value=0.36) if light else _petzhu_mp_relay_theme_color(app, saturation=0.22, value=0.80)
            hint.configure(bg=row_bg, fg=hint_fg)
            should_show = room_on
            is_packed = hint.winfo_manager() == "pack"
            if should_show and not is_packed:
                if json_button is not None and json_button.winfo_exists():
                    hint.pack(side="left", padx=(7, 0), fill="x", expand=True, before=json_button)
                else:
                    hint.pack(side="left", padx=(7, 0), fill="x", expand=True)
            elif not should_show and is_packed:
                hint.pack_forget()
    except Exception:
        pass


# Reapply relay-specific palette after the generic theme walker; it previously overwrote the
# active/on color with the common button color. This wrapper also makes theme switching stable.
_PETZHU_MP_V29_ORIGINAL_WINDOW_THEME = MaoPet._apply_window_pink_theme
def _petzhu_mp_window_theme_with_relay_controls(self, win):
    result = _PETZHU_MP_V29_ORIGINAL_WINDOW_THEME(self, win)
    try:
        api_win = getattr(self, "_api_win", None)
        if win is api_win or (win is not None and api_win is not None and win == api_win):
            _petzhu_mp_update_relay_control_visuals(self)
    except Exception:
        pass
    return result
MaoPet._apply_window_pink_theme = _petzhu_mp_window_theme_with_relay_controls

# Keep correct colors after bulk auxiliary theme refreshes too (including dark/light transitions).
_PETZHU_MP_V29_ORIGINAL_AUX_THEMES = MaoPet._apply_auxiliary_window_themes
def _petzhu_mp_aux_themes_with_relay_controls(self):
    result = _PETZHU_MP_V29_ORIGINAL_AUX_THEMES(self)
    try:
        _petzhu_mp_update_relay_control_visuals(self)
    except Exception:
        pass
    return result
MaoPet._apply_auxiliary_window_themes = _petzhu_mp_aux_themes_with_relay_controls


# ============================================================
# PETZhu v31: robust placeholder isolation for local and room inputs
# Prevent grey hint text ("和xx说话…" / "让xx转达..." / "群聊消息...")
# from ever being interpreted as user content, even after mode/name/theme changes.
# ============================================================
def _petzhu_mp_remember_placeholder(entry, value):
    try:
        value = str(value or "").strip()
        if not value:
            return
        history = list(getattr(entry, "_petzhu_mp_placeholder_history", []) or [])
        if value in history:
            history.remove(value)
        history.append(value)
        entry._petzhu_mp_placeholder_history = history[-24:]
    except Exception:
        pass


def _petzhu_mp_placeholder_candidates(app, entry=None, room=False):
    values = set()
    def add(value):
        try:
            value = str(value or "").strip()
            if value:
                values.add(value)
        except Exception:
            pass
    add(getattr(app, "placeholder", ""))
    add(getattr(app, "_mp_local_normal_placeholder", ""))
    add(getattr(app, "_mp_local_placeholder_display", ""))
    add(getattr(app, "_mp_room_placeholder_display", ""))
    name = str(getattr(app, "pet_name", "珠珠") or "珠珠")[:24]
    # Track both ellipsis spellings and both modes. This also protects against a
    # stale placeholder left behind when a mode toggle/name change races with focus.
    for value in (
        "和珠珠说话…", "和珠珠说话...", "群聊消息...", "群聊消息…",
        "让%s转达..." % name, "让%s转达…" % name,
        "和%s说话…" % name, "和%s说话..." % name,
    ):
        add(value)
    if entry is not None:
        for attr in ("_petzhu_mp_placeholder_text", "_petzhu_mp_local_placeholder_text",
                     "_petzhu_mp_room_placeholder_text"):
            add(getattr(entry, attr, ""))
        for value in list(getattr(entry, "_petzhu_mp_placeholder_history", []) or []):
            add(value)
    return values


def _petzhu_mp_is_placeholder(value, app, entry=None, room=False):
    value = str(value or "").strip()
    return bool(value and value in _petzhu_mp_placeholder_candidates(app, entry, room))


def _petzhu_mp_sync_local_placeholder_v31(app):
    entry = getattr(app, "entry", None)
    if entry is None:
        return
    try:
        old_placeholder = str(getattr(app, "placeholder", "") or "")
        current = str(entry.get() or "")
        known_hint = (not current.strip()) or _petzhu_mp_is_placeholder(current, app, entry, room=False)
        new = ("让%s转达..." % str(getattr(app, "pet_name", "珠珠") or "珠珠")[:24]
               if getattr(app, "_mp_local_relay_mode", False)
               else str(getattr(app, "_mp_local_normal_placeholder", "和珠珠说话…") or "和珠珠说话…"))
        _petzhu_mp_remember_placeholder(entry, old_placeholder)
        _petzhu_mp_remember_placeholder(entry, new)
        app._mp_local_placeholder_display = new
        entry._petzhu_mp_local_placeholder_text = new
        if known_hint:
            entry.delete(0, "end")
            entry.insert(0, new)
            entry._petzhu_mp_placeholder_active = True
            try:
                entry.configure(fg=("#7387a2" if getattr(app, "_context_palette_light", False)
                                    else getattr(app, "C_PLACEHOLDER", "#8fa7c3")))
            except Exception:
                pass
        else:
            # Text already being typed is user data: mode changes must not overwrite it.
            entry._petzhu_mp_placeholder_active = False
        app.placeholder = new
    except Exception:
        pass


def _petzhu_mp_local_focus_in_guard(app, event=None):
    entry = getattr(app, "entry", None)
    if entry is None:
        return
    try:
        current = str(entry.get() or "")
        if _petzhu_mp_is_placeholder(current, app, entry, room=False):
            entry.delete(0, "end")
            entry._petzhu_mp_placeholder_active = False
        try:
            entry.configure(fg=(getattr(app, "C_BG", "#172536")
                               if getattr(app, "_context_palette_light", False)
                               else getattr(app, "C_FG", "#ffffff")))
        except Exception:
            pass
    except Exception:
        pass


def _petzhu_mp_local_focus_out_guard(app, event=None):
    entry = getattr(app, "entry", None)
    if entry is None:
        return
    try:
        current = str(entry.get() or "")
        if (not current.strip()) or _petzhu_mp_is_placeholder(current, app, entry, room=False):
            _petzhu_mp_sync_local_placeholder_v31(app)
            entry._petzhu_mp_placeholder_active = True
        else:
            entry._petzhu_mp_placeholder_active = False
    except Exception:
        pass


_PETZHU_MP_V31_ORIGINAL_INIT = MaoPet.__init__
def _petzhu_mp_init_placeholder_guard_v31(self, root):
    _PETZHU_MP_V31_ORIGINAL_INIT(self, root)
    try:
        entry = getattr(self, "entry", None)
        if entry is not None and entry.winfo_exists():
            _petzhu_mp_remember_placeholder(entry, getattr(self, "placeholder", ""))
            _petzhu_mp_remember_placeholder(entry, getattr(self, "_mp_local_normal_placeholder", ""))
            entry.bind("<FocusIn>", lambda event, app=self: _petzhu_mp_local_focus_in_guard(app, event), add="+")
            entry.bind("<FocusOut>", lambda event, app=self: _petzhu_mp_local_focus_out_guard(app, event), add="+")
    except Exception:
        pass


def _petzhu_mp_on_submit_placeholder_guard_v31(self, event=None):
    try:
        entry = getattr(self, "entry", None)
        value = str(entry.get() or "").strip() if entry is not None else ""
        if not value:
            return "break"
        # Run this guard in BOTH normal chat and relay mode, before calling any API
        # or network send method. Use stored/current/legacy hint values, not only
        # app.placeholder, which changes when the mode is toggled.
        if _petzhu_mp_is_placeholder(value, self, entry, room=False):
            try:
                entry.delete(0, "end")
                _petzhu_mp_sync_local_placeholder_v31(self)
            except Exception:
                pass
            return "break"
    except Exception:
        pass
    return _PETZHU_MP_V31_ORIGINAL_SUBMIT(self, event)


_PETZHU_MP_V31_ORIGINAL_SUBMIT = MaoPet.on_submit


def _petzhu_mp_set_room_chat_placeholder_v31(app, entry):
    try:
        new = ("让%s转达..." % str(getattr(app, "pet_name", "珠珠") or "珠珠")[:24]
               if getattr(app, "_mp_room_relay_mode", False) else "群聊消息...")
        current = str(entry.get() or "")
        is_hint = (not current.strip()) or _petzhu_mp_is_placeholder(current, app, entry, room=True)
        _petzhu_mp_remember_placeholder(entry, getattr(entry, "_petzhu_mp_placeholder_text", ""))
        _petzhu_mp_remember_placeholder(entry, new)
        entry._petzhu_mp_placeholder_text = new
        entry._petzhu_mp_room_placeholder_text = new
        app._mp_room_placeholder_display = new
        if is_hint:
            entry.delete(0, "end")
            entry.insert(0, new)
            entry._petzhu_mp_placeholder_active = True
            try:
                light = bool(getattr(app, "_context_palette_light", False))
                entry.configure(fg=("#7387a2" if light else "#8fa7c3"))
            except Exception:
                pass
        else:
            entry._petzhu_mp_placeholder_active = False
    except Exception:
        pass


# Existing send callback is defined when the API/room window is created. Wrap it
# after creation so placeholder guards always run before chat or relay dispatch.
_PETZHU_MP_V31_ORIGINAL_SHOW_API = MaoPet.show_api_config
def _petzhu_mp_show_api_placeholder_guard_v31(self):
    result = _PETZHU_MP_V31_ORIGINAL_SHOW_API(self)
    try:
        ui = getattr(self, "_mp_ui", {}) or {}
        entry = ui.get("chat_entry")
        if entry is None or not entry.winfo_exists():
            return result
        _petzhu_mp_remember_placeholder(entry, getattr(entry, "_petzhu_mp_placeholder_text", ""))
        _petzhu_mp_remember_placeholder(entry, "群聊消息...")
        _petzhu_mp_remember_placeholder(entry, "群聊消息…")
        _petzhu_mp_remember_placeholder(entry, "让%s转达..." % str(getattr(self, "pet_name", "珠珠") or "珠珠")[:24])
        if not getattr(entry, "_petzhu_mp_v31_focus_guard", False):
            def room_focus_in(event=None, app=self, widget=entry):
                try:
                    current = str(widget.get() or "")
                    if _petzhu_mp_is_placeholder(current, app, widget, room=True):
                        widget.delete(0, "end")
                        widget._petzhu_mp_placeholder_active = False
                    light = bool(getattr(app, "_context_palette_light", False))
                    widget.configure(fg=("#1e2a3a" if light else "#e8f0ff"))
                except Exception:
                    pass
            def room_focus_out(event=None, app=self, widget=entry):
                try:
                    current = str(widget.get() or "")
                    if (not current.strip()) or _petzhu_mp_is_placeholder(current, app, widget, room=True):
                        _petzhu_mp_set_room_chat_placeholder_v31(app, widget)
                    else:
                        widget._petzhu_mp_placeholder_active = False
                except Exception:
                    pass
            entry.bind("<FocusIn>", room_focus_in, add="+")
            entry.bind("<FocusOut>", room_focus_out, add="+")
            entry._petzhu_mp_v31_focus_guard = True
        old_sender = ui.get("room_chat_send_handler")
        if old_sender is not None and not getattr(entry, "_petzhu_mp_v31_sender_wrapped", False):
            def guarded_room_sender(event=None, app=self, widget=entry, sender=old_sender):
                try:
                    value = str(widget.get() or "").strip()
                    if (not value) or _petzhu_mp_is_placeholder(value, app, widget, room=True):
                        return "break"
                except Exception:
                    return "break"
                return sender(event)
            entry.bind("<Return>", guarded_room_sender)
            ui["room_chat_send_handler"] = guarded_room_sender
            entry._petzhu_mp_v31_sender_wrapped = True
    except Exception:
        pass
    return result


# Replace global helper used by the existing room toggle and focus callbacks.
_petzhu_mp_sync_local_placeholder = _petzhu_mp_sync_local_placeholder_v31
_petzhu_mp_set_room_chat_placeholder = _petzhu_mp_set_room_chat_placeholder_v31
MaoPet.__init__ = _petzhu_mp_init_placeholder_guard_v31
MaoPet.on_submit = _petzhu_mp_on_submit_placeholder_guard_v31
MaoPet.show_api_config = _petzhu_mp_show_api_placeholder_guard_v31



# v32: preserve live input and caret when switching local/room relay modes.
# Tk normally sends FocusOut to the Entry before a Button command runs. Since this
# project implements placeholders as literal Entry text, FocusOut could insert a
# hint (and gray foreground) between the user's current text and the mode toggle.
# Capture the focused Entry at ButtonPress, skip placeholder insertion while the
# toggle is pending, then restore the exact user text/caret and focus after toggle.
def _petzhu_mp_capture_entry_before_relay_toggle_v32(app, entry, room=False, event=None):
    try:
        if entry is None or not entry.winfo_exists():
            return
        try:
            focused = entry.focus_get() is entry
        except Exception:
            focused = False
        attr = "_mp_room_toggle_focus_snapshot" if room else "_mp_local_toggle_focus_snapshot"
        if not focused:
            setattr(app, attr, None)
            return
        current = str(entry.get() or "")
        try:
            hint = _petzhu_mp_is_placeholder(current, app, entry, room=room)
        except Exception:
            hint = current in (
                str(getattr(entry, "_petzhu_mp_placeholder_text", "") or ""),
                str(getattr(app, "placeholder", "") or ""),
            )
        # A displayed gray hint is not user input. Preserve every other character verbatim.
        original_text = "" if hint else current
        try:
            insert_index = 0 if hint else int(entry.index("insert"))
        except Exception:
            insert_index = len(original_text)
        selection = None
        try:
            selection = (int(entry.index("sel.first")), int(entry.index("sel.last")))
        except Exception:
            pass
        snapshot = {
            "focused": True,
            "mode": bool(getattr(app, "_mp_room_relay_mode" if room else "_mp_local_relay_mode", False)),
            "text": original_text,
            "insert": max(0, min(insert_index, len(original_text))),
            "selection": selection,
            "room": bool(room),
        }
        setattr(app, attr, snapshot)

        # If the click is cancelled (mouse released outside the button), don't leave a
        # stale snapshot that could affect a later toggle.
        def expire():
            try:
                if getattr(app, attr, None) is not snapshot:
                    return
                setattr(app, attr, None)
                try:
                    still_focused = entry.focus_get() is entry
                except Exception:
                    still_focused = False
                if not still_focused:
                    if room:
                        _petzhu_mp_set_room_chat_placeholder(app, entry)
                    else:
                        _petzhu_mp_sync_local_placeholder(app)
            except Exception:
                pass
        try:
            app.root.after(650, expire)
        except Exception:
            pass
    except Exception:
        pass


def _petzhu_mp_restore_entry_after_toggle_v32(app, entry, snapshot, room=False):
    """Restore text and caret without installing any placeholder while the user is editing."""
    try:
        current_mode = bool(getattr(app, "_mp_room_relay_mode" if room else "_mp_local_relay_mode", False))
        old_mode = bool(snapshot.get("mode", False))
        # FocusOut happens on mouse-down, before Button command flips the mode. In that
        # phase, simply leave the entry alone; the next call after mode change consumes it.
        attr = "_mp_room_toggle_focus_snapshot" if room else "_mp_local_toggle_focus_snapshot"
        if current_mode == old_mode:
            return False
        setattr(app, attr, None)
        text_value = str(snapshot.get("text", "") or "")
        entry.delete(0, "end")
        if text_value:
            entry.insert(0, text_value)
        entry._petzhu_mp_placeholder_active = False
        if room:
            hint = _petzhu_mp_room_chat_placeholder(app, entry)
            entry._petzhu_mp_placeholder_text = hint
            entry._petzhu_mp_room_placeholder_text = hint
            app._mp_room_placeholder_display = hint
            try:
                entry.configure(fg=("#1e2a3a" if getattr(app, "_context_palette_light", False) else "#e8f0ff"))
            except Exception:
                pass
        else:
            hint = ("让%s转达..." % str(getattr(app, "pet_name", "珠珠") or "珠珠")[:24]
                    if current_mode else str(getattr(app, "_mp_local_normal_placeholder", "和珠珠说话…") or "和珠珠说话…"))
            app.placeholder = hint
            app._mp_local_placeholder_display = hint
            entry._petzhu_mp_local_placeholder_text = hint
            try:
                entry.configure(fg=(getattr(app, "C_BG", "#1e2a3a") if getattr(app, "_context_palette_light", False)
                                    else getattr(app, "C_FG", "#ffffff")))
            except Exception:
                pass

        insert_index = max(0, min(int(snapshot.get("insert", len(text_value)) or 0), len(text_value)))
        selection = snapshot.get("selection")
        def restore_focus():
            try:
                if not entry.winfo_exists():
                    return
                entry.focus_set()
                entry.icursor(insert_index)
                if selection and text_value:
                    first = max(0, min(int(selection[0]), len(text_value)))
                    last = max(first, min(int(selection[1]), len(text_value)))
                    if last > first:
                        entry.selection_range(first, last)
                entry._petzhu_mp_placeholder_active = False
                if room:
                    entry.configure(fg=("#1e2a3a" if getattr(app, "_context_palette_light", False) else "#e8f0ff"))
                else:
                    entry.configure(fg=(getattr(app, "C_BG", "#1e2a3a") if getattr(app, "_context_palette_light", False)
                                        else getattr(app, "C_FG", "#ffffff")))
            except Exception:
                pass
        try:
            app.root.after_idle(restore_focus)
        except Exception:
            restore_focus()
        return True
    except Exception:
        return False


def _petzhu_mp_sync_local_placeholder_v32(app):
    entry = getattr(app, "entry", None)
    if entry is None:
        return
    try:
        snapshot = getattr(app, "_mp_local_toggle_focus_snapshot", None)
        if isinstance(snapshot, dict) and snapshot.get("focused"):
            # During FocusOut, mode has not flipped yet; don't add a gray literal placeholder.
            if _petzhu_mp_restore_entry_after_toggle_v32(app, entry, snapshot, room=False):
                return
            if bool(getattr(app, "_mp_local_relay_mode", False)) == bool(snapshot.get("mode", False)):
                return
        old_placeholder = str(getattr(app, "placeholder", "") or "")
        current = str(entry.get() or "")
        new = ("让%s转达..." % str(getattr(app, "pet_name", "珠珠") or "珠珠")[:24]
               if getattr(app, "_mp_local_relay_mode", False)
               else str(getattr(app, "_mp_local_normal_placeholder", "和珠珠说话…") or "和珠珠说话…"))
        _petzhu_mp_remember_placeholder(entry, old_placeholder)
        _petzhu_mp_remember_placeholder(entry, new)
        app._mp_local_placeholder_display = new
        entry._petzhu_mp_local_placeholder_text = new
        if (not current.strip()) or _petzhu_mp_is_placeholder(current, app, entry, room=False):
            entry.delete(0, "end")
            entry.insert(0, new)
            entry._petzhu_mp_placeholder_active = True
            try:
                entry.configure(fg=("#7387a2" if getattr(app, "_context_palette_light", False)
                                    else getattr(app, "C_PLACEHOLDER", "#8fa7c3")))
            except Exception:
                pass
        else:
            # User text is data; changing the mode must not replace, gray, or move its caret.
            entry._petzhu_mp_placeholder_active = False
        app.placeholder = new
    except Exception:
        pass


def _petzhu_mp_local_focus_out_guard_v32(app, event=None):
    entry = getattr(app, "entry", None)
    if entry is None:
        return
    try:
        snapshot = getattr(app, "_mp_local_toggle_focus_snapshot", None)
        if isinstance(snapshot, dict) and snapshot.get("focused") and bool(snapshot.get("mode", False)) == bool(getattr(app, "_mp_local_relay_mode", False)):
            # Mouse-down on the mode button will shortly toggle mode. Don't inject a hint now.
            return
        current = str(entry.get() or "")
        if (not current.strip()) or _petzhu_mp_is_placeholder(current, app, entry, room=False):
            _petzhu_mp_sync_local_placeholder_v32(app)
            entry._petzhu_mp_placeholder_active = True
        else:
            entry._petzhu_mp_placeholder_active = False
    except Exception:
        pass


def _petzhu_mp_set_room_chat_placeholder_v32(app, entry):
    try:
        snapshot = getattr(app, "_mp_room_toggle_focus_snapshot", None)
        if isinstance(snapshot, dict) and snapshot.get("focused"):
            if _petzhu_mp_restore_entry_after_toggle_v32(app, entry, snapshot, room=True):
                return
            if bool(getattr(app, "_mp_room_relay_mode", False)) == bool(snapshot.get("mode", False)):
                return
        new = _petzhu_mp_room_chat_placeholder(app, entry)
        old = str(getattr(entry, "_petzhu_mp_placeholder_text", "") or "")
        current = str(entry.get() or "")
        _petzhu_mp_remember_placeholder(entry, old)
        _petzhu_mp_remember_placeholder(entry, new)
        entry._petzhu_mp_placeholder_text = new
        entry._petzhu_mp_room_placeholder_text = new
        app._mp_room_placeholder_display = new
        if (not current.strip()) or _petzhu_mp_is_placeholder(current, app, entry, room=True):
            entry.delete(0, "end")
            entry.insert(0, new)
            entry._petzhu_mp_placeholder_active = True
            try:
                entry.configure(fg=("#7387a2" if getattr(app, "_context_palette_light", False) else "#8fa7c3"))
            except Exception:
                pass
        else:
            entry._petzhu_mp_placeholder_active = False
    except Exception:
        pass


# Replace the previously installed helpers; existing closures resolve these globals
# when their callbacks run.
_petzhu_mp_sync_local_placeholder = _petzhu_mp_sync_local_placeholder_v32
_petzhu_mp_sync_local_placeholder_v31 = _petzhu_mp_sync_local_placeholder_v32
_petzhu_mp_local_focus_out_guard = _petzhu_mp_local_focus_out_guard_v32
_petzhu_mp_set_room_chat_placeholder = _petzhu_mp_set_room_chat_placeholder_v32
_petzhu_mp_set_room_chat_placeholder_v31 = _petzhu_mp_set_room_chat_placeholder_v32


# Attach the focus snapshot to the two existing toggle buttons. ButtonPress binding runs
# before Tk's Button class binding changes keyboard focus, so we can preserve the Entry caret.
_PETZHU_MP_V32_PREVIOUS_INIT = MaoPet.__init__
def _petzhu_mp_init_focus_snapshot_v32(self, root):
    _PETZHU_MP_V32_PREVIOUS_INIT(self, root)
    try:
        button = getattr(self, "_mp_local_relay_button", None)
        entry = getattr(self, "entry", None)
        if button is not None and entry is not None and not getattr(button, "_petzhu_mp_focus_snapshot_bound", False):
            button.bind("<ButtonPress-1>",
                lambda event, app=self, widget=entry: _petzhu_mp_capture_entry_before_relay_toggle_v32(app, widget, False, event), add="+")
            button._petzhu_mp_focus_snapshot_bound = True
    except Exception:
        pass
MaoPet.__init__ = _petzhu_mp_init_focus_snapshot_v32


_PETZHU_MP_V32_PREVIOUS_SHOW_API = MaoPet.show_api_config
def _petzhu_mp_show_api_focus_snapshot_v32(self):
    result = _PETZHU_MP_V32_PREVIOUS_SHOW_API(self)
    try:
        ui = getattr(self, "_mp_ui", {}) or {}
        entry, button = ui.get("chat_entry"), ui.get("room_relay_button")
        if entry is not None and button is not None and entry.winfo_exists() and button.winfo_exists() \
                and not getattr(button, "_petzhu_mp_focus_snapshot_bound", False):
            button.bind("<ButtonPress-1>",
                lambda event, app=self, widget=entry: _petzhu_mp_capture_entry_before_relay_toggle_v32(app, widget, True, event), add="+")
            button._petzhu_mp_focus_snapshot_bound = True
    except Exception:
        pass
    return result
MaoPet.show_api_config = _petzhu_mp_show_api_focus_snapshot_v32



# ============================================================
# PETZhu 联机合唱 v35（修复成员嘴型、按拍摇摆与跨电脑起唱时钟）
# - 每首歌独立上传、邀请、下载确认；每个参与者可配置多个声部的音色/音量。
# - 发起者独占开始/暂停/解散权限；参与者可随时退出。
# - 所有已加入合唱的电脑根据同一乐谱和成员分工本地混音；嘴型按主旋律 > 和声 > 低音 > 打击选一个声部。
# ============================================================

_PETZHU_CHOIR_PARTS = (
    ("melody", "主旋律", 0),
    ("harmony", "和声", 1),
    ("bass", "低音", 2),
    ("drums", "打击", 3),
)
_PETZHU_CHOIR_PART_LABELS = {key: label for key, label, _idx in _PETZHU_CHOIR_PARTS}
_PETZHU_CHOIR_PART_INDEX = {key: idx for key, _label, idx in _PETZHU_CHOIR_PARTS}
_PETZHU_CHOIR_PART_PRIORITY = {key: order for order, (key, _label, _idx) in enumerate(_PETZHU_CHOIR_PARTS)}
_PETZHU_CHOIR_ALLOWED_ACTIONS = {
    "invite", "accept", "decline", "member_update", "leave_member",
    "start", "pause", "finish", "disband",
}
_PETZHU_CHOIR_CHANNEL_START = 32
_PETZHU_CHOIR_CHANNEL_COUNT = 32


def _petzhu_choir_clean_voices(raw, song_data=None):
    """Validate per-member voice overrides without trusting a network packet."""
    out = {}
    if not isinstance(raw, dict):
        return out
    tracks = song_data.get("tracks", []) if isinstance(song_data, dict) else []
    for key, _label, index in _PETZHU_CHOIR_PARTS:
        item = raw.get(key)
        if not isinstance(item, dict):
            continue
        try:
            tone = str(item.get("tone", "") or "")
            if tone not in SONG_TONE_PRESETS:
                source_track = tracks[index] if index < len(tracks) and isinstance(tracks[index], dict) else {}
                tone = str(source_track.get("tone", "pixel_lead") or "pixel_lead")
            if tone not in SONG_TONE_PRESETS:
                tone = "pixel_lead"
            volume = max(0, min(100, int(round(float(item.get("volume", 80))))))
        except Exception:
            continue
        out[key] = {"tone": tone, "volume": volume}
    return out


def _petzhu_choir_member_wire(session):
    members = []
    raw = session.get("members", {}) if isinstance(session, dict) else {}
    if not isinstance(raw, dict):
        return members
    song = session.get("song_data") if isinstance(session.get("song_data"), dict) else None
    for pid, value in raw.items():
        if not isinstance(value, dict):
            continue
        members.append({
            "id": str(pid)[:32],
            "name": str(value.get("name", "桌宠") or "桌宠")[:24],
            "status": str(value.get("status", "pending") or "pending")[:16],
            "voices": _petzhu_choir_clean_voices(value.get("voices", {}), song),
            "downloaded": bool(value.get("downloaded", False)),
        })
    return members


def _petzhu_choir_members_from_wire(values, song_data):
    members = {}
    if not isinstance(values, list):
        return members
    valid_status = {"pending", "accepted", "declined", "left"}
    for value in values[:8]:
        if not isinstance(value, dict):
            continue
        pid = str(value.get("id", "") or "")[:32]
        if not pid:
            continue
        status = str(value.get("status", "pending") or "pending")
        if status not in valid_status:
            status = "pending"
        members[pid] = {
            "name": str(value.get("name", "桌宠") or "桌宠")[:24],
            "status": status,
            "voices": _petzhu_choir_clean_voices(value.get("voices", {}), song_data),
            "downloaded": bool(value.get("downloaded", False)),
        }
    return members


def _petzhu_choir_send(self, action, data=None, target=None):
    """Send a reliable choir event and keep a concrete diagnostic on failure."""
    action = str(action or "")[:32]
    if action not in _PETZHU_CHOIR_ALLOWED_ACTIONS:
        self._last_choir_send_error = "不支持的合唱指令。"
        return False
    data = data if isinstance(data, dict) else {}
    manager = self
    self._last_choir_send_error = ""
    if not getattr(manager, "running", False):
        self._last_choir_send_error = "联机房间尚未运行。"
        return False
    if not getattr(manager, "connected", False):
        self._last_choir_send_error = "当前连接尚未完成资源同步，或连接已断开。"
        return False
    target = str(target or "")[:32]
    try:
        if manager.mode == "host":
            out = {"type": "choir", "action": action, "peer_id": manager.local_id,
                   "name": str(manager.local_name or getattr(getattr(manager, "app", None), "pet_name", "桌宠"))[:24],
                   "target": target, "data": data, "sent_at": time.time()}
            if target:
                if target == manager.local_id:
                    manager.events.put(out)
                    return True
                # Resolve against live host routing tables. The room roster shown by Tk can
                # be one refresh behind when another member disconnects.
                with manager.lock:
                    peer_exists = target in manager.peers
                    sock = manager._peer_sockets.get(target)
                    lock = manager._peer_locks.get(target)
                if not peer_exists:
                    self._last_choir_send_error = "选中的成员已离开房间，成员列表可能尚未刷新。请刷新成员列表后重试。"
                    return False
                if sock is None:
                    self._last_choir_send_error = "成员仍显示在房间列表中，但发送连接已不可用。请刷新成员列表或让对方重新加入。"
                    return False
                try:
                    _petzhu_mp_send_socket(sock, out, lock)
                    return True
                except Exception as exc:
                    self._last_choir_send_error = "向该成员的连接发送数据失败：%s" % str(exc)[:180]
                    return False
            manager._host_broadcast(out)
            return True
        if manager.mode == "client":
            sock = getattr(manager, "client_socket", None)
            if sock is None:
                self._last_choir_send_error = "客户端连接不可用，可能已断开房间。"
                return False
            _petzhu_mp_send_socket(sock,
                {"type": "choir", "action": action, "target": target, "data": data},
                getattr(manager, "write_lock", None))
            return True
        self._last_choir_send_error = "当前不在有效房间中。"
    except Exception as exc:
        self._last_choir_send_error = "合唱消息发送失败：%s" % str(exc)[:180]
    return False

_PETZhuMultiplayer.send_choir = _petzhu_choir_send


def _petzhu_choir_status_text(app):
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return "尚未建立合唱团。先选择乐谱，再设置自己的声部并邀请房间成员。"
    status = str(session.get("status", "lobby"))
    if status == "playing":
        return "正在合唱：《%s》" % str(session.get("song_name", "未命名歌曲"))[:80]
    if status == "paused":
        return "合唱已暂停：《%s》" % str(session.get("song_name", "未命名歌曲"))[:80]
    if status == "finished":
        return "本轮歌曲已唱完，合唱团仍保留；可以重新开始或解散。"
    pending = sum(1 for m in session.get("members", {}).values()
                  if isinstance(m, dict) and m.get("status") == "pending")
    accepted = sum(1 for m in session.get("members", {}).values()
                   if isinstance(m, dict) and m.get("status") == "accepted")
    return "《%s》｜已加入 %d 人，等待回复/下载 %d 人。" % (
        str(session.get("song_name", "未命名歌曲"))[:60], accepted, pending)


def _petzhu_choir_refresh_ui(app):
    ui = getattr(app, "_choir_ui", None)
    if not isinstance(ui, dict):
        return
    win = ui.get("win")
    try:
        if win is None or not win.winfo_exists():
            return
    except Exception:
        return
    manager = getattr(app, "_mp", None)
    session = getattr(app, "_choir_session", None)
    try:
        ui["song_label"].configure(text=("已载入：《%s》" % app._choir_draft_song_name)
                                    if isinstance(getattr(app, "_choir_draft_song_data", None), dict)
                                    else "尚未选择乐谱")
    except Exception:
        pass
    try:
        status_label = ui.get("status")
        if status_label is not None and status_label.winfo_exists():
            status_label.configure(text=_petzhu_choir_status_text(app))
    except Exception:
        pass
    # Room member picker: invited/accepted people are omitted; declined/left members can be re-invited.
    try:
        lb = ui.get("room_members")
        if lb is not None and lb.winfo_exists():
            selected = lb.curselection()
            selected_id = None
            ids = list(ui.get("room_member_ids", []))
            if selected and selected[0] < len(ids):
                selected_id = ids[selected[0]]
            members = manager.get_members() if manager is not None else []
            room_ids = []
            rows = []
            sid = str(session.get("id", "")) if isinstance(session, dict) else ""
            local_id = str(getattr(manager, "local_id", "")) if manager is not None else ""
            choir_members = session.get("members", {}) if isinstance(session, dict) else {}
            for meta in members:
                pid = str(meta.get("id", "") or "")
                if not pid or pid == local_id:
                    continue
                existing = choir_members.get(pid, {}) if isinstance(choir_members, dict) else {}
                member_status = str(existing.get("status", "")) if isinstance(existing, dict) else ""
                if member_status in ("pending", "accepted"):
                    continue
                name = str(meta.get("name", "桌宠") or "桌宠")[:24]
                rows.append((pid, "%s  [%s]" % (name, pid)))
                room_ids.append(pid)
            lb.delete(0, "end")
            for _pid, row in rows:
                lb.insert("end", row)
            ui["room_member_ids"] = room_ids
            if selected_id in room_ids:
                idx = room_ids.index(selected_id); lb.selection_set(idx); lb.activate(idx)
    except Exception:
        pass
    try:
        lb = ui.get("choir_members")
        if lb is not None and lb.winfo_exists():
            lb.delete(0, "end")
            if not isinstance(session, dict):
                lb.insert("end", "（尚未建立合唱团）")
            else:
                for pid, member in session.get("members", {}).items():
                    if not isinstance(member, dict):
                        continue
                    role_labels = [label for key, label, _idx in _PETZHU_CHOIR_PARTS
                                   if key in _petzhu_choir_clean_voices(member.get("voices", {}), session.get("song_data"))]
                    voice_text = "/".join(role_labels) if role_labels else "未选择声部"
                    status_map = {"accepted": "已接受/已下载", "pending": "等待回复",
                                  "declined": "已拒绝", "left": "已退出"}
                    lb.insert("end", "%s  —  %s  —  %s" % (
                        str(member.get("name", "桌宠"))[:24], status_map.get(str(member.get("status", "")), "未知状态"), voice_text))
    except Exception:
        pass
    is_owner = bool(isinstance(session, dict) and str(session.get("owner_id", "")) == str(getattr(manager, "local_id", "")))
    status = str(session.get("status", "")) if isinstance(session, dict) else ""
    members = session.get("members", {}) if isinstance(session, dict) else {}
    pending = any(isinstance(m, dict) and m.get("status") == "pending" for m in members.values()) if isinstance(members, dict) else False
    accepted_other = any(pid != str(getattr(manager, "local_id", "")) and isinstance(m, dict) and m.get("status") == "accepted"
                         for pid, m in members.items()) if isinstance(members, dict) else False
    own_member = members.get(str(getattr(manager, "local_id", "")), {}) if isinstance(members, dict) else {}
    own_voices = _petzhu_choir_clean_voices(own_member.get("voices", {}), session.get("song_data") if isinstance(session, dict) else None) if isinstance(own_member, dict) else {}
    try:
        ui["own_voice_label"].configure(text=("我的声部：" + " / ".join(_PETZHU_CHOIR_PART_LABELS[k] for k in own_voices)
                                             if own_voices else "我的声部：尚未设置"))
    except Exception:
        pass
    try:
        if ui.get("loop_var") is not None and isinstance(session, dict):
            ui["loop_var"].set(bool(session.get("loop", False)))
    except Exception:
        pass
    try:
        can_invite = bool(is_owner and status == "lobby" and not session.get("has_started", False)
                          and isinstance(getattr(app, "_choir_draft_song_data", None), dict) and own_voices)
        ui["invite_btn"].configure(state=("normal" if can_invite else "disabled"))
        can_start = bool(is_owner and status in ("lobby", "paused", "finished") and not pending and own_voices
                         and (accepted_other or status in ("paused", "finished")))
        ui["start_btn"].configure(state=("normal" if can_start else "disabled"))
        ui["start_btn"].configure(text=("继续合唱" if status == "paused" else "开始合唱"))
        can_pause = bool(is_owner and status in ("playing", "paused"))
        ui["pause_btn"].configure(state=("normal" if can_pause else "disabled"),
                                   text=("暂停合唱" if status == "playing" else "继续合唱"))
        ui["disband_btn"].configure(state=("normal" if is_owner and isinstance(session, dict) else "disabled"))
        ui["leave_btn"].configure(state=("normal" if isinstance(session, dict) and not is_owner else "disabled"))
        ui["own_voice_btn"].configure(state=("normal" if is_owner and status in ("lobby", "finished") and not session.get("has_started", False) else "disabled"))
        ui["loop_check"].configure(state=("normal" if is_owner and status in ("lobby", "finished") else "disabled"))
        ui["load_btn"].configure(state=("normal" if not isinstance(session, dict) or is_owner else "disabled"))
    except Exception:
        pass


def _petzhu_choir_voice_config_dialog(app, parent, title, song_data, initial=None):
    """Choose any combination of four parts, with an independent tone and volume per part."""
    initial = _petzhu_choir_clean_voices(initial, song_data)
    win = tk.Toplevel(parent)
    # Do not use win.title() here: the app-wide persona-name hook rewrites names such as
    # "珠珠" to the local pet name, which is wrong when configuring another player's voice.
    try:
        win.tk.call("wm", "title", win._w, str(title))
    except Exception:
        win.title(title)
    win.transient(parent)
    win.resizable(False, False)
    win.configure(bg=getattr(app, "C_BG", "#182537"))
    bg = getattr(app, "C_BG", "#182537")
    fg = "#e8f0ff"
    choices = ["%s｜%s" % (tone, SONG_TONE_PRESETS[tone]["label"]) for tone in SONG_TONE_IDS]
    rows = {}
    # StringVar avoids the generic static-label name replacement hook as well.
    heading_var = tk.StringVar(master=win, value=str(title))
    tk.Label(win, textvariable=heading_var, bg=bg, fg=fg,
             font=("微软雅黑", 10, "bold"), anchor="w").pack(fill="x", padx=12, pady=(10, 2))
    tk.Label(win, text="可同时选择多个声部；每个声部独立设置音色和音量。", bg=bg, fg=fg,
             font=("微软雅黑", 9)).pack(fill="x", padx=12, pady=(3, 6))
    body = tk.Frame(win, bg=bg)
    body.pack(fill="both", expand=True, padx=12)
    for key, label, idx in _PETZHU_CHOIR_PARTS:
        row = tk.Frame(body, bg=bg)
        row.pack(fill="x", pady=3)
        source_track = song_data.get("tracks", [])[idx] if idx < len(song_data.get("tracks", [])) else {}
        tone_default = str(initial.get(key, {}).get("tone", source_track.get("tone", "pixel_lead")))
        if tone_default not in SONG_TONE_PRESETS:
            tone_default = "pixel_lead"
        vol_default = int(initial.get(key, {}).get("volume", source_track.get("volume", 80)))
        selected = tk.BooleanVar(value=(key in initial) or (not initial and key == "melody"))
        tk.Checkbutton(row, text=label, variable=selected, bg=bg, fg=fg, selectcolor=getattr(app, "C_TEXT_BG", "#22344a"),
                       activebackground=bg, activeforeground=fg, width=8, anchor="w").pack(side="left")
        tone_var = tk.StringVar(value="%s｜%s" % (tone_default, SONG_TONE_PRESETS[tone_default]["label"]))
        combo = ttk.Combobox(row, textvariable=tone_var, values=choices, state="readonly", width=21)
        combo.pack(side="left", padx=(4, 8))
        tk.Label(row, text="音量", bg=bg, fg=fg, font=("微软雅黑", 8)).pack(side="left")
        scale = tk.Scale(row, from_=0, to=100, orient="horizontal", resolution=5, showvalue=True,
                         length=170, bg=bg, fg=fg, troughcolor=getattr(app, "C_TEXT_BG", "#22344a"),
                         highlightthickness=0, bd=0)
        scale.set(max(0, min(100, vol_default)))
        scale.pack(side="left", padx=4)
        rows[key] = {"selected": selected, "tone": tone_var, "volume": scale}
    result = {"value": None}
    footer = tk.Frame(win, bg=bg)
    footer.pack(fill="x", padx=12, pady=(6, 10))
    def confirm():
        voices = {}
        for key, _label, _idx in _PETZHU_CHOIR_PARTS:
            row = rows[key]
            if not row["selected"].get():
                continue
            tone = str(row["tone"].get()).split("｜", 1)[0].strip()
            if tone not in SONG_TONE_PRESETS:
                tone = "pixel_lead"
            voices[key] = {"tone": tone, "volume": int(row["volume"].get())}
        if not voices:
            messagebox.showwarning("请选择声部", "至少选择一个要负责的声部。", parent=win)
            return
        result["value"] = voices
        win.destroy()
    tk.Button(footer, text="确定", command=confirm, bg="#365575", fg="#ffffff", bd=0, padx=18, pady=5).pack(side="right", padx=4)
    tk.Button(footer, text="取消", command=win.destroy, bg="#3b4655", fg="#ffffff", bd=0, padx=18, pady=5).pack(side="right", padx=4)
    win.geometry("690x340")
    win.grab_set()
    try:
        win.update_idletasks()
        sw, sh = win.winfo_screenwidth(), win.winfo_screenheight()
        ww, wh = win.winfo_width(), win.winfo_height()
        win.geometry("+%d+%d" % (max(0, (sw-ww)//2), max(0, (sh-wh)//2)))
    except Exception:
        pass
    parent.wait_window(win)
    return result["value"]


def _petzhu_choir_set_status(app, text):
    try:
        ui = getattr(app, "_choir_ui", {}) or {}
        label = ui.get("status")
        if label is not None and label.winfo_exists():
            label.configure(text=str(text)[:400])
    except Exception:
        pass


def _petzhu_choir_clear_local(app, notify=False, reason=""):
    session = getattr(app, "_choir_session", None)
    after_id = getattr(app, "_choir_after_id", None)
    if after_id is not None:
        try: app.root.after_cancel(after_id)
        except Exception: pass
    app._choir_after_id = None
    for channel in list(getattr(app, "_choir_channels", []) or []):
        try: channel.stop()
        except Exception: pass
    app._choir_playing = False
    app._choir_paused = False
    app._choir_active_mouth = False
    app._choir_anim_started_perf = 0.0
    try:
        app.song_mouth_on = False
        app._update_sprite()
    except Exception:
        pass
    app._choir_session = None
    if notify and isinstance(session, dict):
        _petzhu_choir_set_status(app, reason or "已退出合唱团。")
    _petzhu_choir_refresh_ui(app)


def _petzhu_choir_save_song_cache(app, session_id, song_name, song_data):
    if not isinstance(song_data, dict):
        raise ValueError("收到的乐谱不是有效数据。")
    payload = json.dumps(song_data, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    if len(payload) > _PETZHU_MP_MAX_SONG:
        raise ValueError("乐谱超过 420 KB 的合唱传输上限。")
    cache_dir = os.path.join(get_data_dir(), "choir_cache")
    os.makedirs(cache_dir, exist_ok=True)
    safe_name = re.sub(r"[^0-9A-Za-z_\-\u4e00-\u9fff]+", "_", str(song_name or "song"))[:60] or "song"
    path = os.path.join(cache_dir, "%s_%s.json" % (str(session_id)[:16], safe_name))
    tmp = path + ".tmp"
    with open(tmp, "wb") as f:
        f.write(payload); f.flush(); os.fsync(f.fileno())
    os.replace(tmp, path)
    return path


def _petzhu_choir_load_song(app):
    manager = getattr(app, "_mp", None)
    if manager is None:
        messagebox.showwarning("合唱", "联机模块尚未初始化。", parent=getattr(app, "_api_win", app.root))
        return
    path = filedialog.askopenfilename(parent=getattr(app, "_choir_ui", {}).get("win") or getattr(app, "_api_win", app.root),
                                      title="选择要合唱的乐谱",
                                      filetypes=[("珠珠 / BeepBox 乐谱", "*.json"), ("JSON 文件", "*.json")])
    if not path:
        return
    try:
        with open(path, "r", encoding="utf-8-sig") as f:
            raw = json.load(f)
        if isinstance(raw, dict) and isinstance(raw.get("channels"), list):
            song_data = app._song_convert_beepbox_data(raw)
        else:
            song_data = app._song_normalize(raw)
        if not isinstance(song_data, dict) or not isinstance(song_data.get("tracks"), list):
            raise ValueError("无法读取这个乐谱格式。")
        if not any(app._song_all_note_objects(track) for track in song_data.get("tracks", [])):
            raise ValueError("乐谱中没有可播放的音符。")
        encoded = json.dumps(song_data, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        if len(encoded) > _PETZHU_MP_MAX_SONG:
            raise ValueError("乐谱超过 420 KB，无法通过当前房间协议传输。请缩短乐谱或减少多余数据。")
        # A new song always starts a new recruitment cycle; an old chorus is explicitly ended.
        old = getattr(app, "_choir_session", None)
        if isinstance(old, dict):
            old_id = str(old.get("id", ""))
            owner_id = str(old.get("owner_id", ""))
            local_id = str(manager.local_id)
            if owner_id == local_id:
                manager.send_choir("disband", {"session_id": old_id, "reason": "发起者开始准备新歌曲，上一合唱团已结束。"})
            else:
                manager.send_choir("leave_member", {"session_id": old_id, "reason": "退出上一合唱团"}, target=owner_id)
            _petzhu_choir_clear_local(app, notify=False)
        app._choir_draft_song_data = song_data
        app._choir_draft_song_name = os.path.basename(path)
        app._choir_draft_song_path = path
        manager_name = str(getattr(manager, "local_name", "") or getattr(app, "pet_name", "桌宠"))[:24]
        session_id = uuid.uuid4().hex[:16]
        local_member = {"name": manager_name, "status": "accepted", "voices": {}, "downloaded": True}
        app._choir_session = {
            "id": session_id, "owner_id": str(manager.local_id), "owner_name": manager_name,
            "song_name": app._choir_draft_song_name, "song_data": song_data,
            "song_path": path, "loop": False, "status": "lobby", "members": {str(manager.local_id): local_member},
            "is_owner": True, "has_started": False, "start_step": 0, "next_step": 0,
        }
        _petzhu_choir_set_status(app, "乐谱已载入。下一步先设置自己的声部，再选中房间成员并邀请。")
        _petzhu_choir_refresh_ui(app)
    except Exception as exc:
        messagebox.showerror("读取合唱乐谱失败", str(exc), parent=getattr(app, "_choir_ui", {}).get("win") or getattr(app, "_api_win", app.root))


def _petzhu_choir_configure_own_voice(app):
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict) or str(session.get("owner_id", "")) != str(getattr(getattr(app, "_mp", None), "local_id", "")):
        messagebox.showinfo("合唱", "只有合唱发起者可以设置自己的声部。", parent=getattr(app, "_choir_ui", {}).get("win") or app.root)
        return
    song = session.get("song_data")
    if not isinstance(song, dict):
        messagebox.showinfo("合唱", "请先选择乐谱。", parent=getattr(app, "_choir_ui", {}).get("win") or app.root)
        return
    local_id = str(app._mp.local_id)
    member = session["members"].setdefault(local_id, {"name": str(app._mp.local_name), "status": "accepted", "downloaded": True})
    result = _petzhu_choir_voice_config_dialog(app, getattr(app, "_choir_ui", {}).get("win") or app.root,
                                                "设置发起者声部", song, member.get("voices", {}))
    if result is None:
        return
    member["voices"] = _petzhu_choir_clean_voices(result, song)
    session["status"] = "lobby"
    if getattr(app, "_choir_ui", None) and app._choir_ui.get("loop_var") is not None:
        session["loop"] = bool(app._choir_ui["loop_var"].get())
    _petzhu_choir_refresh_ui(app)


def _petzhu_choir_invite_selected(app):
    manager = getattr(app, "_mp", None)
    session = getattr(app, "_choir_session", None)
    ui = getattr(app, "_choir_ui", {}) or {}
    if manager is None or not manager.connected:
        messagebox.showinfo("合唱", "请先创建或加入联机房间。", parent=ui.get("win") or app.root)
        return
    if not isinstance(session, dict) or str(session.get("owner_id", "")) != str(manager.local_id):
        messagebox.showinfo("合唱", "请先上传乐谱并创建合唱。", parent=ui.get("win") or app.root)
        return
    if bool(session.get("has_started", False)) or session.get("status") != "lobby":
        messagebox.showinfo("合唱", "本首歌的合唱已经开始。若要唱新歌，请重新上传乐谱并重新邀请。", parent=ui.get("win") or app.root)
        return
    local_member = session.get("members", {}).get(str(manager.local_id), {})
    own_voices = _petzhu_choir_clean_voices(local_member.get("voices", {}), session.get("song_data")) if isinstance(local_member, dict) else {}
    if not own_voices:
        messagebox.showinfo("合唱", "请先设置发起者自己负责的声部、音色和音量。", parent=ui.get("win") or app.root)
        return
    lb = ui.get("room_members")
    selected = lb.curselection() if lb is not None else ()
    ids = list(ui.get("room_member_ids", []))
    if not selected or int(selected[0]) >= len(ids):
        messagebox.showinfo("合唱", "请先在房间成员列表中选中要邀请的桌宠。", parent=ui.get("win") or app.root)
        return
    target = str(ids[int(selected[0])])
    members = session.get("members", {})
    existing = members.get(target, {}) if isinstance(members, dict) else {}
    if isinstance(existing, dict) and existing.get("status") in ("pending", "accepted"):
        messagebox.showinfo("合唱", "这位成员已经收到邀请或已加入合唱。", parent=ui.get("win") or app.root)
        return
    # Re-resolve the selected member against the live roster immediately before invite.
    # This avoids a stale Tk listbox index targeting an old room member after a disconnect.
    live_members = manager.get_members()
    meta = next((m for m in live_members if str(m.get("id", "")) == target
                 and str(m.get("id", "")) != str(manager.local_id)), None)
    if meta is None:
        _petzhu_choir_refresh_ui(app)
        messagebox.showwarning("成员列表已更新", "选中的成员已经不在当前房间，请重新选择成员。",
                               parent=ui.get("win") or app.root)
        return
    target_name = str(meta.get("name", "桌宠") or "桌宠")[:24]
    voice_title = "设置成员负责的声部"
    assigned = _petzhu_choir_voice_config_dialog(app, ui.get("win") or app.root,
                                                  voice_title,
                                                  session["song_data"], None)
    if assigned is None:
        return
    assigned = _petzhu_choir_clean_voices(assigned, session["song_data"])
    live_members = manager.get_members()
    live_target = next((m for m in live_members if str(m.get("id", "")) == target
                        and str(m.get("id", "")) != str(manager.local_id)), None)
    if live_target is None:
        _petzhu_choir_refresh_ui(app)
        messagebox.showwarning("成员已离开", "配置声部期间，该成员已离开房间；乐谱未发送。",
                               parent=ui.get("win") or app.root)
        return
    # Use the current remote pet name, not the local pet name or a stale listbox label.
    target_name = str(live_target.get("name", target_name) or target_name)[:24]
    members[target] = {"name": target_name, "status": "pending", "voices": assigned, "downloaded": False}
    data = {
        "session_id": session["id"], "owner_id": manager.local_id,
        "owner_name": str(manager.local_name or getattr(app, "pet_name", "桌宠"))[:24],
        "song_name": str(session.get("song_name", "song"))[:100],
        "song_data": session["song_data"], "assigned_voices": assigned,
        "members": _petzhu_choir_member_wire(session), "loop": bool(session.get("loop", False)),
    }
    try:
        packet_size = len(json.dumps(data, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        if packet_size > _PETZHU_MP_MAX_SONG + 128 * 1024:
            raise ValueError("邀请包过大。请重新导入更精简的乐谱。")
    except Exception as exc:
        members.pop(target, None)
        messagebox.showerror("无法发送邀请", str(exc), parent=ui.get("win") or app.root)
        return
    if not manager.send_choir("invite", data, target=target):
        members.pop(target, None)
        reason = str(getattr(manager, "_last_choir_send_error", "") or "未知的发送错误。")
        _petzhu_choir_refresh_ui(app)
        messagebox.showerror("邀请失败", "无法向%s发送乐谱。\n\n原因：%s" % (target_name, reason),
                             parent=ui.get("win") or app.root)
    else:
        _petzhu_choir_set_status(app, "已向%s发送《%s》的乐谱和声部邀请；等待对方下载并接受。" % (target_name, session.get("song_name", "歌曲")))
    _petzhu_choir_refresh_ui(app)


def _petzhu_choir_invitation_received(app, packet):
    manager = getattr(app, "_mp", None)
    data = packet.get("data", {}) if isinstance(packet.get("data"), dict) else {}
    owner_id = str(packet.get("peer_id", "") or data.get("owner_id", ""))[:32]
    owner_name = str(packet.get("name", data.get("owner_name", "房间成员")) or "房间成员")[:24]
    session_id = str(data.get("session_id", "") or "")[:32]
    song_data_raw = data.get("song_data")
    reason = ""
    song_data = None
    try:
        if not session_id or not isinstance(song_data_raw, dict):
            raise ValueError("邀请中没有完整乐谱。")
        raw_bytes = json.dumps(song_data_raw, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        if len(raw_bytes) > _PETZHU_MP_MAX_SONG:
            raise ValueError("收到的乐谱超过大小限制。")
        song_data = app._song_normalize(song_data_raw)
        if not any(app._song_all_note_objects(t) for t in song_data.get("tracks", [])):
            raise ValueError("收到的乐谱没有可播放的音符。")
        # The invitation is not offered until the complete score has arrived, decoded and been atomically cached.
        cache_path = _petzhu_choir_save_song_cache(app, session_id, str(data.get("song_name", "歌曲")), song_data)
    except Exception as exc:
        reason = str(exc)
    if reason:
        if manager is not None:
            manager.send_choir("decline", {"session_id": session_id, "reason": reason}, target=owner_id)
        try:
            messagebox.showerror("合唱乐谱下载失败", reason, parent=getattr(app, "_api_win", app.root))
        except Exception:
            pass
        return
    if isinstance(getattr(app, "_choir_session", None), dict):
        messagebox.showinfo("合唱邀请", "你已经在另一个合唱团中。请先退出当前合唱，再接受新的邀请。", parent=getattr(app, "_api_win", app.root))
        if manager is not None:
            manager.send_choir("decline", {"session_id": session_id, "reason": "已经加入其他合唱团"}, target=owner_id)
        return
    assigned = _petzhu_choir_clean_voices(data.get("assigned_voices", {}), song_data)
    if not assigned:
        if manager is not None:
            manager.send_choir("decline", {"session_id": session_id, "reason": "邀请没有指定有效声部"}, target=owner_id)
        return
    member_list = _petzhu_choir_members_from_wire(data.get("members", []), song_data)
    local_id = str(manager.local_id if manager is not None else "")
    local_name = str(getattr(app, "pet_name", "桌宠") or "桌宠")[:24]
    member_list[local_id] = {"name": local_name, "status": "pending", "voices": assigned, "downloaded": True}
    roles = "、".join(_PETZHU_CHOIR_PART_LABELS[k] for k in assigned)
    song_name = str(data.get("song_name", "歌曲") or "歌曲")[:100]
    text = "%s 邀请你参加合唱：\n《%s》\n\n你已收到并保存完整乐谱。\n负责声部：%s\n\n接受后，发起者会在所有成员准备好后统一开始；合唱过程中你可以随时退出。" % (owner_name, song_name, roles)
    accepted = messagebox.askyesno("合唱邀请", text, parent=getattr(app, "_api_win", app.root))
    if not accepted:
        manager.send_choir("decline", {"session_id": session_id, "reason": "对方拒绝了合唱邀请"}, target=owner_id)
        return
    member_list[local_id]["status"] = "accepted"
    manager_name = str(getattr(manager, "local_name", local_name) or local_name)[:24]
    app._choir_session = {
        "id": session_id, "owner_id": owner_id, "owner_name": owner_name,
        "song_name": song_name, "song_data": song_data, "song_path": cache_path,
        "loop": bool(data.get("loop", False)), "status": "lobby", "members": member_list,
        "is_owner": False, "has_started": False, "start_step": 0, "next_step": 0,
    }
    member_list[local_id]["name"] = manager_name
    app._choir_draft_song_data = song_data
    app._choir_draft_song_name = song_name
    app._choir_draft_song_path = cache_path
    manager.send_choir("accept", {"session_id": session_id, "downloaded": True}, target=owner_id)
    _petzhu_choir_set_status(app, "已接受《%s》的合唱邀请，乐谱已下载完成。" % song_name)
    _petzhu_choir_refresh_ui(app)


def _petzhu_choir_local_start(app, start_step=0, delay=2.0, loop=None, start_at=None):
    """Schedule playback against one shared wall-clock instant, not packet-arrival time."""
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return False
    if loop is not None:
        session["loop"] = bool(loop)
    try:
        if start_at is not None:
            target_epoch = float(start_at)
            if not math.isfinite(target_epoch):
                raise ValueError("invalid start time")
            # Permit small network lateness while rejecting absurd timestamps.
            delta = max(-30.0, min(5.0, target_epoch - time.time()))
        else:
            delta = max(0.1, min(5.0, float(delay)))
            target_epoch = time.time() + delta
    except Exception:
        delta = max(0.1, min(5.0, float(delay)))
        target_epoch = time.time() + delta
    session["start_epoch"] = target_epoch
    session["status"] = "playing"
    session["has_started"] = True
    session["start_step"] = max(0, int(start_step))
    session["next_step"] = max(0, int(start_step))
    session["last_abs_step"] = max(0, int(start_step)) - 1
    scheduled_start_mono = time.monotonic() + delta
    # 16分音符网格：每拍4格。将动画时间原点回推 start_step 格，
    # 暂停后从中途续唱也沿用歌曲原本的节拍相位，不会重新从零摇摆。
    try:
        bpm_for_clock = max(50.0, min(240.0, float(session.get("song_data", {}).get("bpm", 128))))
    except Exception:
        bpm_for_clock = 128.0
    step_seconds_for_clock = 60.0 / bpm_for_clock / 4.0
    session["start_mono"] = scheduled_start_mono
    session["anim_start_perf"] = (time.perf_counter() + delta
                                    - max(0, int(start_step)) * step_seconds_for_clock)
    session["_choir_mouth_note_key"] = None
    session["_choir_mouth_loop_index"] = None
    app._choir_playing = True
    app._choir_paused = False
    app._choir_anim_started_perf = session["anim_start_perf"]
    app.song_mouth_on = False
    old_after = getattr(app, "_choir_after_id", None)
    if old_after is not None:
        try: app.root.after_cancel(old_after)
        except Exception: pass
    app._choir_after_id = None
    try:
        app.root.after(max(1, int(max(0.001, delta) * 1000)), lambda a=app: _petzhu_choir_playback_tick(a))
    except Exception:
        _petzhu_choir_playback_tick(app)
    try: app._update_sprite()
    except Exception: pass
    _petzhu_choir_refresh_ui(app)
    return True


def _petzhu_choir_stop_audio(app):
    for channel in list(getattr(app, "_choir_channels", []) or []):
        try: channel.stop()
        except Exception: pass


def _petzhu_choir_audio_channels(app):
    existing = getattr(app, "_choir_channels", None)
    if isinstance(existing, list) and len(existing) == _PETZHU_CHOIR_CHANNEL_COUNT:
        return existing
    if pygame is None or not _ensure_pygame_mixer():
        app._choir_channels = []
        return []
    try:
        needed = _PETZHU_CHOIR_CHANNEL_START + _PETZHU_CHOIR_CHANNEL_COUNT
        if pygame.mixer.get_num_channels() < needed:
            pygame.mixer.set_num_channels(needed)
        app._choir_channels = [pygame.mixer.Channel(i) for i in range(_PETZHU_CHOIR_CHANNEL_START, needed)]
    except Exception:
        app._choir_channels = []
    return app._choir_channels


def _petzhu_choir_track_active_at_step(track, step, total_steps, looping=False):
    """Return whether a note in this voice spans the current step (not merely starts here)."""
    if not isinstance(track, dict):
        return False
    notes = track.get("notes", {})
    if not isinstance(notes, dict):
        return False
    try:
        step = int(step)
        total_steps = max(1, int(total_steps))
    except Exception:
        return False
    for raw_start, raw_values in notes.items():
        try:
            start = int(raw_start)
        except Exception:
            continue
        values = raw_values if isinstance(raw_values, list) else [raw_values]
        for item in values:
            try:
                length = max(1, int(item.get("len", 1))) if isinstance(item, dict) else 1
            except Exception:
                length = 1
            if start <= step < start + length:
                return True
            if looping and start + length > total_steps and step < (start + length) % total_steps:
                return True
    return False


def _petzhu_choir_primary_mouth_role(local_voices, song_data):
    """选择该成员实际负责且乐谱中存在音符的最高优先级声部。"""
    tracks = song_data.get("tracks", []) if isinstance(song_data, dict) else []
    for role, _label, track_index in _PETZHU_CHOIR_PARTS:
        if role not in local_voices or track_index >= len(tracks):
            continue
        track = tracks[track_index]
        if not isinstance(track, dict):
            continue
        notes = track.get("notes", {})
        if isinstance(notes, dict) and any(notes.values()):
            return role
    return None


def _petzhu_choir_active_note_for_track(track, step):
    """返回当前格正在发声的最新音符键；无音符/休止时返回 None。"""
    if not isinstance(track, dict):
        return None
    notes = track.get("notes", {})
    if not isinstance(notes, dict):
        return None
    best = None
    try:
        step = int(step)
    except Exception:
        return None
    for raw_start, raw_values in notes.items():
        try:
            start = int(raw_start)
        except Exception:
            continue
        values = raw_values if isinstance(raw_values, list) else [raw_values]
        for item in values:
            try:
                if isinstance(item, dict):
                    row = int(item.get("row", 0))
                    length = max(1, int(item.get("len", 1)))
                else:
                    row = int(item)
                    length = 1
            except Exception:
                continue
            if start <= step < start + length:
                candidate = (start, row, length)
                if best is None or start > best[0]:
                    best = candidate
    return best


def _petzhu_choir_update_mouth_for_step(app, session, song_data, local_voices, step, absolute_step):
    """嘴型跟随本成员负责声部的新音符触发；延音不一直张嘴，休止时闭嘴。"""
    tracks = song_data.get("tracks", []) if isinstance(song_data, dict) else []
    role = _petzhu_choir_primary_mouth_role(local_voices, song_data)
    track_index = _PETZHU_CHOIR_PART_INDEX.get(role, -1) if role else -1
    active_note = None
    if 0 <= track_index < len(tracks):
        active_note = _petzhu_choir_active_note_for_track(tracks[track_index], step)
    steps = max(1, min(256, int(song_data.get("steps", 256) or 256)))
    loop_index = max(0, int(absolute_step)) // steps if session.get("loop", False) else 0
    if active_note is None or role is None:
        session["_choir_mouth_note_key"] = None
        session["_choir_mouth_loop_index"] = loop_index
        app.song_mouth_on = False
        app._song_vocal_short_close_at = 0.0
        return

    start, row, length = active_note
    note_key = (role, start, row, length, loop_index)
    previous_key = session.get("_choir_mouth_note_key")
    previous_loop = session.get("_choir_mouth_loop_index")
    now = time.perf_counter()
    if note_key != previous_key or loop_index != previous_loop:
        session["_choir_mouth_note_key"] = note_key
        session["_choir_mouth_loop_index"] = loop_index
        try:
            bpm = max(50.0, min(240.0, float(song_data.get("bpm", 128))))
        except Exception:
            bpm = 128.0
        step_seconds = 60.0 / bpm / 4.0
        app.song_mouth_on = True
        app._song_vocal_short_close_at = now + min(0.12, max(0.025, step_seconds * 0.32))
    elif now >= float(getattr(app, "_song_vocal_short_close_at", 0.0) or 0.0):
        app.song_mouth_on = False


def _petzhu_choir_play_voice_step(app, session, step, absolute_step=None):
    song_data = session.get("song_data") if isinstance(session.get("song_data"), dict) else {}
    tracks = song_data.get("tracks", [])
    members = session.get("members", {})
    channels = _petzhu_choir_audio_channels(app)
    channel_cursor = int(getattr(app, "_choir_channel_cursor", 0) or 0)
    manager = getattr(app, "_mp", None)
    local_id = str(getattr(manager, "local_id", ""))
    local_member = members.get(local_id, {}) if isinstance(members, dict) else {}
    local_voices = _petzhu_choir_clean_voices(local_member.get("voices", {}), song_data) if isinstance(local_member, dict) else {}
    if absolute_step is None:
        absolute_step = max(0, int(step))
    for pid, member in list(members.items()) if isinstance(members, dict) else []:
        if not isinstance(member, dict) or str(member.get("status", "")) != "accepted":
            continue
        voices = _petzhu_choir_clean_voices(member.get("voices", {}), song_data)
        for role, voice in voices.items():
            track_index = _PETZHU_CHOIR_PART_INDEX[role]
            if track_index >= len(tracks) or not isinstance(tracks[track_index], dict):
                continue
            track = tracks[track_index]
            raw_values = (track.get("notes", {}) or {}).get(str(int(step)), [])
            values = raw_values if isinstance(raw_values, list) else [raw_values]
            if not values:
                continue
            for item in values:
                try:
                    if isinstance(item, dict):
                        row = int(item.get("row", 0)); length = max(1, int(item.get("len", 1)))
                    else:
                        row = int(item); length = 1
                    tone = str(voice.get("tone", track.get("tone", "pixel_lead")))
                    volume = max(0, min(100, int(voice.get("volume", 80))))
                    base_volume = max(0, min(100, int(track.get("volume", 100))))
                    mixed_volume = volume * base_volume / 100.0
                    if mixed_volume <= 0 or not channels:
                        continue
                    sound = app._song_get_sound(row, tone, length, song_data=song_data,
                                                octave=int(track.get("octave", 0) or 0))
                    if sound is None:
                        continue
                    channel = None
                    for candidate in channels:
                        try:
                            if not candidate.get_busy():
                                channel = candidate; break
                        except Exception:
                            pass
                    if channel is None and channels:
                        channel = channels[channel_cursor % len(channels)]
                        channel_cursor += 1
                    if channel is not None:
                        channel.set_volume(max(0.0, min(1.0, mixed_volume / 100.0)))
                        channel.play(sound)
                except Exception:
                    continue
    app._choir_channel_cursor = channel_cursor
    _petzhu_choir_update_mouth_for_step(
        app, session, song_data, local_voices, step, int(absolute_step or 0)
    )
    try: app._update_sprite()
    except Exception: pass


def _petzhu_choir_playback_tick(app):
    app._choir_after_id = None
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict) or session.get("status") != "playing" or getattr(app, "_closing", False):
        return
    try:
        song_data = session.get("song_data", {})
        bpm = max(50.0, min(240.0, float(song_data.get("bpm", 128))))
        step_seconds = 60.0 / bpm / 4.0
        start_mono = float(session.get("start_mono", time.monotonic()) or time.monotonic())
        now = time.monotonic()
        if now < start_mono:
            app._choir_after_id = app.root.after(max(1, int((start_mono-now)*1000)), lambda a=app: _petzhu_choir_playback_tick(a))
            return
        start_step = max(0, int(session.get("start_step", 0) or 0))
        absolute_step = start_step + max(0, int((now - start_mono) / step_seconds))
        steps = max(1, min(256, int(song_data.get("steps", 256) or 256)))
        loop = bool(session.get("loop", False))
        if not loop and absolute_step >= steps:
            session["status"] = "finished"
            session["next_step"] = steps
            app._choir_playing = False
            app._choir_paused = False
            _petzhu_choir_stop_audio(app)
            app.song_mouth_on = False
            try: app._update_sprite()
            except Exception: pass
            manager = getattr(app, "_mp", None)
            if (isinstance(session, dict) and str(session.get("owner_id", "")) == str(getattr(manager, "local_id", "")) and manager is not None):
                manager.send_choir("finish", {"session_id": session.get("id"), "step": steps})
            _petzhu_choir_refresh_ui(app)
            return
        step = absolute_step % steps if loop else absolute_step
        last_abs = int(session.get("last_abs_step", start_step - 1))
        if absolute_step > last_abs:
            # If Windows briefly stalls, skip stale historical frames instead of bursting many late notes.
            _petzhu_choir_play_voice_step(app, session, step, absolute_step=absolute_step)
            session["last_abs_step"] = absolute_step
            session["next_step"] = (step + 1) % steps if loop else step + 1
        session["current_step"] = step
        next_boundary = start_mono + (int((now-start_mono) / step_seconds) + 1) * step_seconds
        delay_ms = max(1, min(20, int(round((next_boundary - time.monotonic()) * 1000.0))))
        app._choir_after_id = app.root.after(delay_ms, lambda a=app: _petzhu_choir_playback_tick(a))
    except Exception:
        session["status"] = "finished"
        app._choir_playing = False
        _petzhu_choir_stop_audio(app)
        _petzhu_choir_refresh_ui(app)


def _petzhu_choir_pause_local(app, step=None):
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return
    if step is None:
        step = int(session.get("next_step", 0) or 0)
    session["pause_step"] = max(0, int(step))
    session["status"] = "paused"
    app._choir_playing = False
    app._choir_paused = True
    after_id = getattr(app, "_choir_after_id", None)
    if after_id is not None:
        try: app.root.after_cancel(after_id)
        except Exception: pass
    app._choir_after_id = None
    _petzhu_choir_stop_audio(app)
    app.song_mouth_on = False
    try: app._update_sprite()
    except Exception: pass
    _petzhu_choir_refresh_ui(app)


def _petzhu_choir_start_from_ui(app):
    manager = getattr(app, "_mp", None)
    session = getattr(app, "_choir_session", None)
    ui = getattr(app, "_choir_ui", {}) or {}
    if manager is None or not isinstance(session, dict) or str(session.get("owner_id", "")) != str(manager.local_id):
        return
    members = session.get("members", {})
    if any(isinstance(m, dict) and m.get("status") == "pending" for m in members.values()):
        messagebox.showinfo("合唱", "还有成员尚未接受邀请或完成乐谱下载，请等待全部邀请得到回复。", parent=ui.get("win") or app.root)
        return
    accepted = [m for m in members.values() if isinstance(m, dict) and m.get("status") == "accepted"]
    if len(accepted) < 2:
        messagebox.showinfo("合唱", "至少需要发起者和一名已接受邀请的成员。", parent=ui.get("win") or app.root)
        return
    local_member = members.get(str(manager.local_id), {})
    voices = _petzhu_choir_clean_voices(local_member.get("voices", {}), session.get("song_data")) if isinstance(local_member, dict) else {}
    if not voices:
        messagebox.showinfo("合唱", "请先设置发起者自己的声部。", parent=ui.get("win") or app.root)
        return
    if session.get("status") == "playing":
        return
    if session.get("status") == "paused":
        start_step = int(session.get("pause_step", session.get("next_step", 0)) or 0)
    else:
        start_step = 0
    loop = bool(ui.get("loop_var").get()) if ui.get("loop_var") is not None else bool(session.get("loop", False))
    session["loop"] = loop
    delay = 3.0
    if _petzhu_choir_local_start(app, start_step=start_step, delay=delay, loop=loop, start_at=None):
        manager.send_choir("start", {"session_id": session.get("id"), "start_step": start_step,
                                      "loop": loop, "delay": delay,
                                      "song_name": session.get("song_name", "")})
        _petzhu_choir_set_status(app, "合唱倒计时：3、2、1。桌宠会保持原有呼吸动画。")


def _petzhu_choir_pause_from_ui(app):
    manager = getattr(app, "_mp", None)
    session = getattr(app, "_choir_session", None)
    ui = getattr(app, "_choir_ui", {}) or {}
    if manager is None or not isinstance(session, dict) or str(session.get("owner_id", "")) != str(manager.local_id):
        return
    if session.get("status") == "playing":
        song = session.get("song_data", {})
        step_sec = 60.0 / max(50.0, min(240.0, float(song.get("bpm", 128)))) / 4.0
        elapsed = max(0.0, time.monotonic() - float(session.get("start_mono", time.monotonic())))
        steps = max(1, int(song.get("steps", 256) or 256))
        current = int(session.get("start_step", 0) or 0) + int(elapsed / step_sec)
        if session.get("loop", False):
            pause_step = (current + 1) % steps
        else:
            pause_step = min(steps - 1, current + 1)
        _petzhu_choir_pause_local(app, pause_step)
        manager.send_choir("pause", {"session_id": session.get("id"), "step": pause_step})
    elif session.get("status") == "paused":
        _petzhu_choir_start_from_ui(app)


def _petzhu_choir_leave(app):
    manager = getattr(app, "_mp", None)
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return
    if str(session.get("owner_id", "")) == str(getattr(manager, "local_id", "")):
        messagebox.showinfo("合唱", "发起者不能单独退出；请使用‘解散合唱团’通知全体成员。", parent=getattr(app, "_choir_ui", {}).get("win") or app.root)
        return
    if manager is not None:
        manager.send_choir("leave_member", {"session_id": session.get("id"), "reason": "成员主动退出合唱团"}, target=str(session.get("owner_id", "")))
    _petzhu_choir_clear_local(app, notify=True, reason="你已退出合唱团；其他成员可以继续合唱。")


def _petzhu_choir_disband(app):
    manager = getattr(app, "_mp", None)
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return
    if manager is None or str(session.get("owner_id", "")) != str(manager.local_id):
        return
    if not messagebox.askyesno("解散合唱团", "向所有合唱成员发送解散提示并结束本次合唱团？", parent=getattr(app, "_choir_ui", {}).get("win") or app.root):
        return
    manager.send_choir("disband", {"session_id": session.get("id"), "reason": "发起者已解散合唱团。"})
    _petzhu_choir_clear_local(app, notify=True, reason="已解散合唱团。")


def _petzhu_mp_handle_choir_packet(app, packet):
    manager = getattr(app, "_mp", None)
    if manager is None or not isinstance(packet, dict):
        return
    action = str(packet.get("action", "") or "")[:32]
    if action not in _PETZHU_CHOIR_ALLOWED_ACTIONS:
        return
    sender = str(packet.get("peer_id", "") or "")[:32]
    data = packet.get("data", {}) if isinstance(packet.get("data"), dict) else {}
    session_id = str(data.get("session_id", "") or "")[:32]
    local_id = str(manager.local_id)
    if action == "invite":
        _petzhu_choir_invitation_received(app, packet)
        return
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict) or session_id != str(session.get("id", "")):
        return
    owner_id = str(session.get("owner_id", "") or "")
    is_owner = owner_id == local_id
    if action in ("accept", "decline") and is_owner:
        target_member = session.get("members", {}).get(sender)
        if not isinstance(target_member, dict) or target_member.get("status") != "pending":
            return
        if action == "accept" and bool(data.get("downloaded", False)):
            target_member["status"] = "accepted"
            target_member["downloaded"] = True
        else:
            target_member["status"] = "declined"
        session["members"][sender] = target_member
        manager.send_choir("member_update", {"session_id": session_id,
            "members": _petzhu_choir_member_wire(session), "loop": bool(session.get("loop", False))})
        _petzhu_choir_set_status(app, (str(target_member.get("name", "成员")) +
            ("已接受并完成乐谱下载。" if target_member.get("status") == "accepted" else "拒绝了合唱邀请。")))
        _petzhu_choir_refresh_ui(app)
    elif action == "member_update":
        # Only the owner is authoritative for roster/download status and loop settings.
        if sender != owner_id:
            return
        members = _petzhu_choir_members_from_wire(data.get("members", []), session.get("song_data"))
        if members:
            session["members"] = members
        if "loop" in data:
            session["loop"] = bool(data.get("loop"))
        _petzhu_choir_refresh_ui(app)
    elif action == "leave_member" and is_owner:
        member = session.get("members", {}).get(sender)
        if isinstance(member, dict) and member.get("status") == "accepted":
            member["status"] = "left"
            session["members"][sender] = member
            manager.send_choir("member_update", {"session_id": session_id,
                "members": _petzhu_choir_member_wire(session), "loop": bool(session.get("loop", False))})
            _petzhu_choir_set_status(app, "%s 已退出；其他成员会继续合唱。" % member.get("name", "一名成员"))
            _petzhu_choir_refresh_ui(app)
    elif action in ("start", "pause", "finish", "disband"):
        # Only the session originator is authorized to control playback or disband it.
        if sender != owner_id:
            return
        if action == "start":
            session["loop"] = bool(data.get("loop", session.get("loop", False)))
            start_step = max(0, int(data.get("start_step", 0) or 0))
            # 跨电脑的 time.time() 未必同源；统一采用本消息到达后的相对预备时长，
            # 避免系统时钟偏差造成邀请成员提前/延后起唱与摇摆错拍。
            try:
                relative_delay = max(0.5, min(5.0, float(data.get("delay", 3.0) or 3.0)))
            except Exception:
                relative_delay = 3.0
            _petzhu_choir_local_start(app, start_step=start_step,
                delay=relative_delay, loop=session["loop"], start_at=None)
        elif action == "pause":
            _petzhu_choir_pause_local(app, max(0, int(data.get("step", session.get("next_step", 0)) or 0)))
        elif action == "finish":
            session["status"] = "finished"
            app._choir_playing = False
            _petzhu_choir_stop_audio(app)
            app.song_mouth_on = False
            try: app._update_sprite()
            except Exception: pass
            _petzhu_choir_refresh_ui(app)
        elif action == "disband":
            reason = str(data.get("reason", "发起者已解散合唱团。") or "发起者已解散合唱团。")[:200]
            _petzhu_choir_clear_local(app, notify=True, reason=reason)
            if sender != local_id:
                try: messagebox.showinfo("合唱团已解散", reason, parent=getattr(app, "_api_win", app.root))
                except Exception: pass
    elif action == "decline" and not is_owner:
        # A target may reject only the session's own invitation; it should not alter a live chorus.
        return


def _petzhu_mp_choir_peer_disconnected(app, peer_id):
    session = getattr(app, "_choir_session", None)
    manager = getattr(app, "_mp", None)
    if not isinstance(session, dict):
        return
    pid = str(peer_id or "")
    member = session.get("members", {}).get(pid)
    if not isinstance(member, dict) or member.get("status") not in ("accepted", "pending"):
        return
    member["status"] = "left"
    session["members"][pid] = member
    if manager is not None and str(session.get("owner_id", "")) == str(manager.local_id):
        manager.send_choir("member_update", {"session_id": session.get("id"),
            "members": _petzhu_choir_member_wire(session), "loop": bool(session.get("loop", False))})
    _petzhu_choir_set_status(app, "%s 已断开，剩余成员可继续合唱。" % member.get("name", "成员"))
    _petzhu_choir_refresh_ui(app)



def _petzhu_choir_loop_setting_changed(app):
    """Persist the owner's checkbox immediately so periodic UI refresh cannot revert it."""
    ui = getattr(app, "_choir_ui", None)
    session = getattr(app, "_choir_session", None)
    if not isinstance(ui, dict) or not isinstance(session, dict):
        return
    loop_var = ui.get("loop_var")
    if loop_var is None:
        return
    manager = getattr(app, "_mp", None)
    is_owner = (manager is not None and
                str(session.get("owner_id", "")) == str(getattr(manager, "local_id", "")))
    if not is_owner or str(session.get("status", "")) not in ("lobby", "finished"):
        # Defensive guard: if the control is invoked after the owner/status has changed,
        # restore the authoritative session value instead of allowing a stale UI edit.
        try:
            loop_var.set(bool(session.get("loop", False)))
        except Exception:
            pass
        return

    # IMPORTANT: _petzhu_choir_refresh_ui runs periodically and mirrors session['loop'] back
    # into this variable. Store a user's click first, otherwise refresh overwrites it ~0.8s later.
    loop_enabled = bool(loop_var.get())
    session["loop"] = loop_enabled

    # Keep already-invited members' displayed session state current. The start packet also
    # includes this value, so playback remains correct even if this informational update fails.
    try:
        if manager is not None and getattr(manager, "connected", False):
            manager.send_choir("member_update", {
                "session_id": session.get("id"),
                "members": _petzhu_choir_member_wire(session),
                "loop": loop_enabled,
            })
    except Exception:
        pass

    try:
        _petzhu_choir_set_status(app, "循环播放已%s；开始合唱时会把此设置同步给全体成员。" %
                                 ("开启" if loop_enabled else "关闭"))
    except Exception:
        pass
    # Refresh labels/buttons, now against the just-persisted value. This is safe because
    # BooleanVar.set() does not invoke the Checkbutton's command callback.
    try:
        _petzhu_choir_refresh_ui(app)
    except Exception:
        pass


def _petzhu_choir_open_ui(app):
    current = getattr(app, "_choir_ui", None)
    if isinstance(current, dict):
        win = current.get("win")
        try:
            if win is not None and win.winfo_exists():
                win.deiconify(); win.lift(); _petzhu_choir_refresh_ui(app); return
        except Exception:
            pass
    parent = getattr(app, "_api_win", None)
    try:
        if parent is None or not parent.winfo_exists():
            parent = app.root
    except Exception:
        parent = app.root
    win = tk.Toplevel(parent)
    win.title("联机合唱")
    win.configure(bg=app.C_BG)
    win.geometry("790x560")
    win.minsize(720, 520)
    bg = app.C_BG
    fg = "#e8f0ff"
    top = tk.Frame(win, bg=bg); top.pack(fill="x", padx=12, pady=(10, 4))
    load_btn = tk.Button(top, text="上传/选择乐谱", command=lambda a=app: _petzhu_choir_load_song(a),
                         bg="#365575", fg="#ffffff", bd=0, padx=10, pady=4)
    load_btn.pack(side="left")
    song_label = tk.Label(top, text="尚未选择乐谱", bg=bg, fg=fg, anchor="w", font=("微软雅黑", 9))
    song_label.pack(side="left", fill="x", expand=True, padx=8)
    own_row = tk.Frame(win, bg=bg); own_row.pack(fill="x", padx=12, pady=3)
