def _petzhu_mp_show_api_with_choir(self):
    result = _PETZHU_MP_PREVIOUS_SHOW_API_CHOIR(self)
    try:
        ui = getattr(self, "_mp_ui", {}) or {}
        lb = ui.get("members")
        if lb is not None and lb.winfo_exists():
            parent = lb.master
            button = getattr(self, "_mp_choir_open_button", None)
            if button is None or not button.winfo_exists():
                button = tk.Button(parent, text="合唱管理", command=lambda a=self: _petzhu_choir_open_ui(a),
                                   bg="#365575", fg="#ffffff", bd=0, relief="flat",
                                   font=("微软雅黑", 9), padx=10, pady=4, cursor="hand2")
                button.pack(fill="x", pady=(3, 0))
                self._mp_choir_open_button = button
            else:
                button.configure(state="normal")
    except Exception:
        pass
    return result

# Integrate choir controls into the existing API/online panel.
_PETZHU_MP_PREVIOUS_SHOW_API_CHOIR = MaoPet.show_api_config
MaoPet.show_api_config = _petzhu_mp_show_api_with_choir

# Local singing deformation and mouth animation reuse existing sprite frames; choir state doesn't hijack the song editor.
_PETZHU_CHOIR_ORIGINAL_UPDATE_SPRITE = MaoPet._update_sprite
_PETZHU_CHOIR_ORIGINAL_ANIM_LOOP = MaoPet._anim_loop

def _petzhu_choir_update_sprite(app, *args, **kwargs):
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict) or session.get("status") != "playing":
        return _PETZHU_CHOIR_ORIGINAL_UPDATE_SPRITE(app, *args, **kwargs)
    old_playing = bool(getattr(app, "_song_playing", False))
    old_data = getattr(app, "_song_data", None)
    old_started = float(getattr(app, "_song_vocal_anim_started_at", 0.0) or 0.0)
    try:
        app._song_playing = True
        app._song_data = session.get("song_data")
        app._song_vocal_anim_started_at = float(session.get("anim_start_perf", time.perf_counter()) or time.perf_counter())
        return _PETZHU_CHOIR_ORIGINAL_UPDATE_SPRITE(app, *args, **kwargs)
    finally:
        app._song_playing = old_playing
        app._song_data = old_data
        app._song_vocal_anim_started_at = old_started


def _petzhu_choir_anim_loop(app, *args, **kwargs):
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict) or session.get("status") != "playing":
        return _PETZHU_CHOIR_ORIGINAL_ANIM_LOOP(app, *args, **kwargs)
    old_playing = bool(getattr(app, "_song_playing", False))
    old_data = getattr(app, "_song_data", None)
    old_started = float(getattr(app, "_song_vocal_anim_started_at", 0.0) or 0.0)
    try:
        app._song_playing = True
        app._song_data = session.get("song_data")
        app._song_vocal_anim_started_at = float(session.get("anim_start_perf", time.perf_counter()) or time.perf_counter())
        return _PETZHU_CHOIR_ORIGINAL_ANIM_LOOP(app, *args, **kwargs)
    finally:
        app._song_playing = old_playing
        app._song_data = old_data
        app._song_vocal_anim_started_at = old_started

MaoPet._update_sprite = _petzhu_choir_update_sprite
MaoPet._anim_loop = _petzhu_choir_anim_loop

# Add choir singing to the existing visual state without modifying ordinary song/editor flags.
_PETZHU_CHOIR_ORIGINAL_STATE = _petzhu_mp_state

def _petzhu_choir_mp_state(app):
    state = _PETZHU_CHOIR_ORIGINAL_STATE(app)
    session = getattr(app, "_choir_session", None)
    if isinstance(session, dict) and session.get("status") == "playing":
        song = session.get("song_data", {})
        bpm = max(50.0, min(240.0, float(song.get("bpm", 128))))
        start = float(session.get("anim_start_perf", time.perf_counter()) or time.perf_counter())
        elapsed = max(0.0, time.perf_counter() - start)
        cycle = max(0.20, 60.0 / bpm)  # one full sway cycle per quarter-note beat
        phase = (elapsed % cycle) / cycle
        state.update({"singing": True, "actual_singing": True, "music_window_open": False,
                      "song_mouth_on": bool(getattr(app, "song_mouth_on", False)),
                      "song_bpm": bpm, "song_phase": phase, "song_frame_idx": int(phase * 48) % 48,
                      "song_elapsed": elapsed, "visual_mode": "singing", "choir_session_id": str(session.get("id", ""))})
    return state

_petzhu_mp_state = _petzhu_choir_mp_state


def _petzhu_choir_close_views(app):
    _petzhu_choir_clear_local(app, notify=False)
    return _PETZHU_CHOIR_ORIGINAL_CLOSE_VIEWS(app)

_PETZHU_CHOIR_ORIGINAL_CLOSE_VIEWS = _petzhu_mp_close_views
_petzhu_mp_close_views = _petzhu_choir_close_views


# ============================================================
# PETZhu 联机合唱 v37：倒计时期间保留呼吸、稳态窗口层级、固定成员标题
# ============================================================

def _petzhu_choir_library_paths_v36(app):
    base = os.path.join(get_data_dir(), "choir_library")
    return base, os.path.join(base, "library.json")


def _petzhu_choir_library_entries_v36(app, force=False):
    """读取本机持久化乐谱曲库；不受房间群聊记录上限影响。"""
    base, manifest = _petzhu_choir_library_paths_v36(app)
    os.makedirs(base, exist_ok=True)
    try:
        mtime = os.path.getmtime(manifest) if os.path.isfile(manifest) else 0.0
    except Exception:
        mtime = 0.0
    if (not force and getattr(app, "_choir_library_entries_v36", None) is not None
            and getattr(app, "_choir_library_mtime_v36", None) == mtime):
        return list(app._choir_library_entries_v36)
    entries = []
    try:
        with open(manifest, "r", encoding="utf-8") as f:
            raw = json.load(f)
        raw_entries = raw.get("songs", []) if isinstance(raw, dict) else []
        if isinstance(raw_entries, list):
            for item in raw_entries:
                if not isinstance(item, dict):
                    continue
                sid = str(item.get("id", "") or "")
                filename = str(item.get("file", "") or "")
                if not re.fullmatch(r"[0-9a-f]{64}", sid):
                    continue
                if filename != sid + ".json":
                    filename = sid + ".json"
                path = os.path.join(base, filename)
                if not os.path.isfile(path):
                    continue
                entries.append({
                    "id": sid,
                    "name": str(item.get("name", "歌曲") or "歌曲")[:100],
                    "file": filename,
                    "sha256": sid,
                    "updated": float(item.get("updated", 0.0) or 0.0),
                })
    except Exception:
        entries = []
    entries.sort(key=lambda x: (float(x.get("updated", 0) or 0), str(x.get("name", ""))), reverse=True)
    app._choir_library_entries_v36 = entries
    app._choir_library_mtime_v36 = mtime
    return list(entries)


def _petzhu_choir_library_save_v36(app, song_name, song_data):
    if not isinstance(song_data, dict) or not isinstance(song_data.get("tracks"), list):
        raise ValueError("乐谱数据无效，不能保存到本地曲库。")
    payload = json.dumps(song_data, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8")
    if len(payload) > _PETZHU_MP_MAX_SONG:
        raise ValueError("乐谱超过当前合唱传输上限，无法保存。")
    digest = hashlib.sha256(payload).hexdigest()
    base, manifest = _petzhu_choir_library_paths_v36(app)
    os.makedirs(base, exist_ok=True)
    score_path = os.path.join(base, digest + ".json")
    if not os.path.isfile(score_path):
        tmp_score = score_path + ".tmp"
        with open(tmp_score, "wb") as f:
            f.write(payload)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_score, score_path)
    entries = _petzhu_choir_library_entries_v36(app, force=True)
    display_name = os.path.basename(str(song_name or "歌曲")).strip()[:100] or "歌曲"
    found = False
    now = time.time()
    for item in entries:
        if item["id"] == digest:
            item["name"] = display_name
            item["updated"] = now
            found = True
            break
    if not found:
        entries.append({"id": digest, "name": display_name, "file": digest + ".json", "sha256": digest, "updated": now})
    entries.sort(key=lambda x: (float(x.get("updated", 0) or 0), str(x.get("name", ""))), reverse=True)
    tmp_manifest = manifest + ".tmp"
    with open(tmp_manifest, "w", encoding="utf-8") as f:
        json.dump({"format": "PETZhu-Choir-Library", "version": 1, "songs": entries}, f, ensure_ascii=False, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp_manifest, manifest)
    try:
        app._choir_library_mtime_v36 = os.path.getmtime(manifest)
    except Exception:
        app._choir_library_mtime_v36 = None
    app._choir_library_entries_v36 = entries
    return {"id": digest, "name": display_name, "file": digest + ".json", "path": score_path}


def _petzhu_choir_begin_song_v36(app, song_data, song_name, song_path):
    """选新歌与选旧歌共用同一套流程：新建会话、清理上一轮并重新邀请。"""
    manager = getattr(app, "_mp", None)
    if manager is None or not getattr(manager, "connected", False):
        messagebox.showwarning("合唱", "请先创建或加入联机房间。", parent=getattr(app, "_choir_ui", {}).get("win") or getattr(app, "_api_win", app.root))
        return False
    encoded = json.dumps(song_data, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    if len(encoded) > _PETZHU_MP_MAX_SONG:
        raise ValueError("乐谱超过 420 KB 的合唱传输上限。")
    old = getattr(app, "_choir_session", None)
    if isinstance(old, dict):
        old_id = str(old.get("id", ""))
        owner_id = str(old.get("owner_id", ""))
        local_id = str(manager.local_id)
        if owner_id == local_id:
            manager.send_choir("disband", {"session_id": old_id, "reason": "发起者准备了另一首歌曲，上一合唱团已结束。"})
        else:
            manager.send_choir("leave_member", {"session_id": old_id, "reason": "退出上一合唱团"}, target=owner_id)
        _petzhu_choir_clear_local(app, notify=False)
    display_name = str(song_name or "歌曲")[:100]
    app._choir_draft_song_data = song_data
    app._choir_draft_song_name = display_name
    app._choir_draft_song_path = str(song_path or "")
    manager_name = str(getattr(manager, "local_name", "") or getattr(app, "pet_name", "桌宠"))[:24]
    session_id = uuid.uuid4().hex[:16]
    local_member = {"name": manager_name, "status": "accepted", "voices": {}, "downloaded": True}
    app._choir_session = {
        "id": session_id, "owner_id": str(manager.local_id), "owner_name": manager_name,
        "song_name": display_name, "song_data": song_data,
        "song_path": str(song_path or ""), "loop": False, "status": "lobby", "members": {str(manager.local_id): local_member},
        "is_owner": True, "has_started": False, "start_step": 0, "next_step": 0,
    }
    _petzhu_choir_set_status(app, "《%s》已就绪。下一步先设置自己的声部，再选中房间成员并邀请。" % display_name)
    _petzhu_choir_refresh_ui(app)
    return True


def _petzhu_choir_load_song_v36(app):
    manager = getattr(app, "_mp", None)
    if manager is None:
        messagebox.showwarning("合唱", "联机模块尚未初始化。", parent=getattr(app, "_api_win", app.root))
        return
    path = filedialog.askopenfilename(parent=getattr(app, "_choir_ui", {}).get("win") or getattr(app, "_api_win", app.root),
                                      title="导入新的合唱乐谱",
                                      filetypes=[("珠珠 / BeepBox 乐谱", "*.json"), ("JSON 文件", "*.json")])
    if not path:
        return
    try:
        with open(path, "r", encoding="utf-8-sig") as f:
            raw = json.load(f)
        if isinstance(raw, dict) and isinstance(raw.get("channels"), list):
            song_data = app._song_convert_beepbox_data(raw)
        else:
            song_data = app._song_normalize(raw)
        if not isinstance(song_data, dict) or not isinstance(song_data.get("tracks"), list):
            raise ValueError("无法读取这个乐谱格式。")
        if not any(app._song_all_note_objects(track) for track in song_data.get("tracks", [])):
            raise ValueError("乐谱中没有可播放的音符。")
        song_name = os.path.basename(path)
        entry = _petzhu_choir_library_save_v36(app, song_name, song_data)
        # Use a stable local cache path instead of depending on the original file's location.
        _petzhu_choir_begin_song_v36(app, song_data, entry["name"], entry["path"])
    except Exception as exc:
        messagebox.showerror("读取合唱乐谱失败", str(exc), parent=getattr(app, "_choir_ui", {}).get("win") or getattr(app, "_api_win", app.root))
    _petzhu_choir_refresh_ui(app)


_petzhu_choir_load_song = _petzhu_choir_load_song_v36

def _petzhu_choir_select_saved_song_v36(app):
    ui = getattr(app, "_choir_ui", {}) or {}
    combo = ui.get("library_combo")
    if combo is None:
        return
    label = str(combo.get() or "").strip()
    mapping = ui.get("library_label_to_id", {})
    sid = mapping.get(label) if isinstance(mapping, dict) else None
    if not sid:
        messagebox.showinfo("合唱曲库", "请先从本地曲库中选择一首已保存的歌曲。", parent=ui.get("win") or app.root)
        return
    entry = next((x for x in _petzhu_choir_library_entries_v36(app) if x.get("id") == sid), None)
    if not entry:
        _petzhu_choir_refresh_ui(app)
        messagebox.showwarning("合唱曲库", "这首歌曲的本地记录不存在，请刷新后重试。", parent=ui.get("win") or app.root)
        return
    base, _manifest = _petzhu_choir_library_paths_v36(app)
    path = os.path.join(base, entry["file"])
    try:
        with open(path, "r", encoding="utf-8") as f:
            raw = json.load(f)
        song_data = raw  # 曲库文件本身就是已标准化的可播放格式；原样读取避免反复导入时改写乐谱。
        if not isinstance(song_data, dict) or not isinstance(song_data.get("tracks"), list) or not any(app._song_all_note_objects(t) for t in song_data.get("tracks", [])):
            raise ValueError("保存的乐谱没有可播放的音符。")
        _petzhu_choir_begin_song_v36(app, song_data, entry["name"], path)
    except Exception as exc:
        messagebox.showerror("读取已保存歌曲失败", str(exc), parent=ui.get("win") or app.root)
    _petzhu_choir_refresh_ui(app)


def _petzhu_choir_update_mouth_for_step_v36(app, session, song_data, local_voices, step, absolute_step):
    """完全复用编曲界面的 _song_update_vocal_step；只将该成员负责的优先声部作为嘴型轨。"""
    tracks = song_data.get("tracks", []) if isinstance(song_data, dict) else []
    role = _petzhu_choir_primary_mouth_role(local_voices, song_data)
    track_index = _PETZHU_CHOIR_PART_INDEX.get(role, -1) if role else -1
    if not (0 <= track_index < len(tracks) and isinstance(tracks[track_index], dict)):
        try:
            app._song_reset_vocal(stop_animation=False)
        except Exception:
            app.song_mouth_on = False
            app._song_vocal_short_close_at = 0.0
        session["_choir_mouth_cache_key_v36"] = None
        return
    cache_key = (id(song_data), role)
    if session.get("_choir_mouth_cache_key_v36") != cache_key:
        # Build a stable, single-track view so the editor's existing selector reads this exact role.
        session["_choir_mouth_song_data_v36"] = {
            "bpm": song_data.get("bpm", 128),
            "steps": song_data.get("steps", 256),
            "rows": song_data.get("rows", 48),
            "tracks": [tracks[track_index]],
        }
        session["_choir_mouth_cache_key_v36"] = cache_key
        try:
            app._song_reset_vocal(stop_animation=False)
        except Exception:
            app._song_vocal_key = None
            app.song_mouth_on = False
    mouth_song = session.get("_choir_mouth_song_data_v36")
    if not isinstance(mouth_song, dict):
        app.song_mouth_on = False
        return
    # _song_update_vocal_step expects the scheduled start time of this grid cell in perf_counter units.
    try:
        bpm = max(50.0, min(240.0, float(song_data.get("bpm", 128) or 128)))
    except Exception:
        bpm = 128.0
    step_seconds = 60.0 / bpm / 4.0
    start_step = max(0, int(session.get("start_step", 0) or 0))
    start_mono = float(session.get("start_mono", time.monotonic()) or time.monotonic())
    cell_start_mono = start_mono + max(0, int(absolute_step) - start_step) * step_seconds
    late_by = max(0.0, time.monotonic() - cell_start_mono)
    step_started_perf = time.perf_counter() - late_by
    loop_index = max(0, int(absolute_step)) // max(1, int(song_data.get("steps", 256) or 256)) if session.get("loop", False) else 0
    if session.get("_choir_mouth_loop_index_v36") != loop_index:
        session["_choir_mouth_loop_index_v36"] = loop_index
        # An editor loop is another pass through the note grid; clear its previous note key so a note
        # at the loop boundary can retrigger just as it does when the editor restarts that grid.
        try:
            app._song_vocal_key = None
        except Exception:
            pass
    try:
        app._song_update_vocal_step(mouth_song, int(step), step_started_at=step_started_perf)
    except Exception:
        # Fail closed: never leave the mouth stuck open if a malformed/custom song is received.
        try:
            app._song_reset_vocal(stop_animation=False)
        except Exception:
            app.song_mouth_on = False


# The editor's short-mouth pulse logic is called on every musical grid step, so use the same helper.
_petzhu_choir_update_mouth_for_step = _petzhu_choir_update_mouth_for_step_v36
