# Put the choir window in the same topmost layer as the pet when the user's setting is enabled.
_PETZHU_CHOIR_V36_PREVIOUS_OPEN_UI = _petzhu_choir_open_ui

def _petzhu_choir_install_library_controls_v36(app):
    ui = getattr(app, "_choir_ui", None)
    if not isinstance(ui, dict):
        return
    win = ui.get("win")
    try:
        if win is None or not win.winfo_exists():
            return
        win.attributes("-topmost", bool(getattr(app, "pet_chat_topmost", True)))
        if bool(getattr(app, "pet_chat_topmost", True)):
            win.lift()
    except Exception:
        pass
    if ui.get("library_combo") is None or not ui.get("library_combo").winfo_exists():
        try:
            content = ui["room_members"].master.master
            row = tk.Frame(win, bg=app.C_BG)
            row.pack(fill="x", padx=12, pady=(0, 4), before=content)
            tk.Label(row, text="本地曲库", bg=app.C_BG, fg="#e8f0ff", font=("微软雅黑", 9)).pack(side="left", padx=(0, 6))
            var = tk.StringVar(value="")
            combo = ttk.Combobox(row, textvariable=var, state="readonly", width=42, font=("微软雅黑", 9))
            combo.pack(side="left", fill="x", expand=True, padx=(0, 6))
            button = tk.Button(row, text="使用所选歌曲", command=lambda a=app: _petzhu_choir_select_saved_song_v36(a),
                               bg="#365575", fg="#ffffff", bd=0, padx=10, pady=4, cursor="hand2")
            button.pack(side="left")
            ui["library_row"] = row
            ui["library_var"] = var
            ui["library_combo"] = combo
            ui["library_btn"] = button
            ui["library_label_to_id"] = {}
            try:
                win.geometry("840x610")
                win.minsize(760, 570)
                win.update_idletasks()
                sw, sh = win.winfo_screenwidth(), win.winfo_screenheight()
                ww, wh = win.winfo_width(), win.winfo_height()
                win.geometry("%dx%d+%d+%d" % (min(ww, max(640, sw-30)), min(wh, max(480, sh-60)),
                                                max(0, min(win.winfo_x(), sw-ww)), max(0, min(win.winfo_y(), sh-wh))))
            except Exception:
                pass
        except Exception:
            return
    # Bring topmost state back after pack/layout and refresh visible saved scores.
    try:
        win.attributes("-topmost", bool(getattr(app, "pet_chat_topmost", True)))
        if bool(getattr(app, "pet_chat_topmost", True)):
            win.lift()
    except Exception:
        pass
    _petzhu_choir_refresh_ui(app)


def _petzhu_choir_open_ui_v36(app):
    _PETZHU_CHOIR_V36_PREVIOUS_OPEN_UI(app)
    _petzhu_choir_install_library_controls_v36(app)

_petzhu_choir_open_ui = _petzhu_choir_open_ui_v36

_PETZHU_CHOIR_V36_PREVIOUS_REFRESH_UI = _petzhu_choir_refresh_ui
def _petzhu_choir_refresh_ui_v36(app):
    _PETZHU_CHOIR_V36_PREVIOUS_REFRESH_UI(app)
    ui = getattr(app, "_choir_ui", {}) or {}
    combo = ui.get("library_combo")
    if combo is None:
        return
    try:
        entries = _petzhu_choir_library_entries_v36(app)
        labels = []
        label_to_id = {}
        for item in entries:
            label = "%s  ·  %s" % (str(item.get("name", "歌曲"))[:80], str(item.get("id", ""))[:8])
            labels.append(label)
            label_to_id[label] = item["id"]
        old = str(combo.get() or "")
        combo.configure(values=labels)
        ui["library_label_to_id"] = label_to_id
        if old in label_to_id:
            combo.set(old)
        elif labels:
            combo.set(labels[0])
        else:
            combo.set("")
    except Exception:
        pass
