# The remote desktop renderer must use the same two-beat sway phase as the local composer.
_PETZHU_CHOIR_V36_PREVIOUS_MP_STATE = _petzhu_mp_state
def _petzhu_choir_mp_state_v36(app):
    state = _PETZHU_CHOIR_V36_PREVIOUS_MP_STATE(app)
    session = getattr(app, "_choir_session", None)
    if isinstance(session, dict) and session.get("status") == "playing":
        song = session.get("song_data", {})
        try:
            bpm = max(50.0, min(240.0, float(song.get("bpm", 128) or 128)))
        except Exception:
            bpm = 128.0
        started = float(session.get("anim_start_perf", time.perf_counter()) or time.perf_counter())
        elapsed = max(0.0, time.perf_counter() - started)
        cycle = max(0.20, 120.0 / bpm)  # identical to the composing interface: two beats per full sway
        phase = (elapsed % cycle) / cycle
        state.update({"song_bpm": bpm, "song_phase": phase, "song_frame_idx": int(phase * 48) % 48,
                      "song_elapsed": elapsed, "song_mouth_on": bool(getattr(app, "song_mouth_on", False)),
                      "singing": True, "actual_singing": True, "visual_mode": "singing"})
    return state

_petzhu_mp_state = _petzhu_choir_mp_state_v36


# ============================================================
# PETZhu 合唱 v37：呼吸不中断 + 3/2/1 倒计时 + 稳定窗口层级 + 固定成员标题
# ============================================================

def _petzhu_choir_countdown_clear_v37(app, cancel_timer=True):
    timer_id = getattr(app, "_choir_countdown_after_id_v37", None)
    if cancel_timer and timer_id is not None:
        try:
            app.root.after_cancel(timer_id)
        except Exception:
            pass
    app._choir_countdown_after_id_v37 = None
    try:
        canvas = getattr(app, "canvas", None)
        if canvas is not None and canvas.winfo_exists():
            canvas.delete("petzhu_choir_countdown_v37")
    except Exception:
        pass
    app._choir_countdown_value_v37 = None


def _petzhu_choir_countdown_draw_v37(app, value):
    canvas = getattr(app, "canvas", None)
    if canvas is None:
        return
    try:
        if not canvas.winfo_exists():
            return
        canvas.delete("petzhu_choir_countdown_v37")
        width = max(1, int(canvas.winfo_width()))
        height = max(1, int(canvas.winfo_height()))
        # The number sits inside the existing pet window; no additional window or modal overlay is created.
        x = width * 0.5
        y = max(16, min(height * 0.22, height - 16))
        scale_h = max(1, int(getattr(app, "pet_h", height) or height))
        font_size = max(18, min(54, int(round(scale_h * 0.23))))
        hue = 330
        try:
            hue = int(_PETZHU_THEME_HUE_STATE.get("hue", 330)) % 360
        except Exception:
            pass
        rr, gg, bb = colorsys.hsv_to_rgb(hue / 360.0, 0.52, 1.0)
        color = "#%02x%02x%02x" % (round(rr * 255), round(gg * 255), round(bb * 255))
        # A small dark offset creates contrast without freezing/changing the pet image or breathing loop.
        canvas.create_text(x + 2, y + 2, text=str(value), fill="#233044",
                           font=("Arial", font_size, "bold"), tags=("petzhu_choir_countdown_v37",))
        canvas.create_text(x, y, text=str(value), fill=color,
                           font=("Arial", font_size, "bold"), tags=("petzhu_choir_countdown_v37",))
        try:
            canvas.tag_raise("petzhu_choir_countdown_v37")
        except Exception:
            pass
        app._choir_countdown_value_v37 = int(value)
    except Exception:
        pass


def _petzhu_choir_countdown_tick_v37(app, session_id):
    app._choir_countdown_after_id_v37 = None
    session = getattr(app, "_choir_session", None)
    if (not isinstance(session, dict) or str(session.get("id", "")) != str(session_id)
            or session.get("status") != "countdown" or getattr(app, "_closing", False)):
        _petzhu_choir_countdown_clear_v37(app, cancel_timer=False)
        return
    target = float(session.get("start_mono", time.monotonic()) or time.monotonic())
    remaining = target - time.monotonic()
    if remaining <= 0.0:
        _petzhu_choir_countdown_clear_v37(app, cancel_timer=False)
        session["status"] = "playing"
        app._choir_playing = True
        app._choir_paused = False
        try:
            app._update_sprite()
        except Exception:
            pass
        _petzhu_choir_set_status(app, "合唱开始。")
        try:
            _petzhu_choir_refresh_ui(app)
        except Exception:
            pass
        _petzhu_choir_playback_tick(app)
        return
    number = max(1, min(3, int(math.ceil(remaining - 1e-6))))
    if getattr(app, "_choir_countdown_value_v37", None) != number:
        _petzhu_choir_countdown_draw_v37(app, number)
        _petzhu_choir_set_status(app, "合唱倒计时：%d" % number)
    # Wake at the next integer boundary, but poll more frequently close to the exact shared start time.
    to_boundary = remaining - (number - 1)
    wait_ms = max(25, min(250, int(max(0.025, to_boundary) * 1000)))
    try:
        app._choir_countdown_after_id_v37 = app.root.after(
            wait_ms, lambda a=app, sid=str(session_id): _petzhu_choir_countdown_tick_v37(a, sid))
    except Exception:
        app._choir_countdown_after_id_v37 = None


def _petzhu_choir_local_start_v37(app, start_step=0, delay=3.0, loop=None, start_at=None):
    """Schedule a 3-2-1 countdown while normal breathing continues; music animation begins only at the deadline."""
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return False
    if loop is not None:
        session["loop"] = bool(loop)
    try:
        if start_at is not None:
            target_epoch = float(start_at)
            if not math.isfinite(target_epoch):
                raise ValueError("invalid start time")
            delta = max(0.1, min(5.0, target_epoch - time.time()))
        else:
            delta = max(0.1, min(5.0, float(delay)))
            target_epoch = time.time() + delta
    except Exception:
        delta = max(0.1, min(5.0, float(delay)))
        target_epoch = time.time() + delta
    # A normal start always shows 3, 2, 1. Old clients may still send a shorter delay; normalize it.
    if start_at is None and delta < 3.0:
        delta = 3.0
        target_epoch = time.time() + delta
    session["start_epoch"] = target_epoch
    session["status"] = "countdown"
    session["has_started"] = True
    session["start_step"] = max(0, int(start_step))
    session["next_step"] = max(0, int(start_step))
    session["last_abs_step"] = max(0, int(start_step)) - 1
    target_mono = time.monotonic() + delta
    try:
        bpm = max(50.0, min(240.0, float(session.get("song_data", {}).get("bpm", 128) or 128)))
    except Exception:
        bpm = 128.0
    step_seconds = 60.0 / bpm / 4.0
    session["start_mono"] = target_mono
    session["anim_start_perf"] = time.perf_counter() + delta - max(0, int(start_step)) * step_seconds
    session["_choir_mouth_cache_key_v36"] = None
    session["_choir_mouth_loop_index_v36"] = None
    session["_choir_mouth_note_key"] = None
    session["_choir_mouth_loop_index"] = None
    app._choir_playing = False
    app._choir_paused = False
    app._choir_anim_started_perf = 0.0
    # Cancels either a prior playback callback or a previous countdown without touching normal animation timers.
    for attr in ("_choir_after_id", "_choir_countdown_after_id_v37"):
        timer = getattr(app, attr, None)
        if timer is not None:
            try:
                app.root.after_cancel(timer)
            except Exception:
                pass
        setattr(app, attr, None)
    _petzhu_choir_countdown_clear_v37(app, cancel_timer=False)
    try:
        app.song_mouth_on = False
        app._song_vocal_key = None
        app._song_vocal_short_close_at = 0.0
    except Exception:
        pass
    _petzhu_choir_countdown_draw_v37(app, min(3, max(1, int(math.ceil(delta)))))
    _petzhu_choir_set_status(app, "合唱倒计时：%d" % min(3, max(1, int(math.ceil(delta)))))
    # Crucial: session status is 'countdown', so the choir sprite wrappers delegate to the ordinary
    # _update_sprite/_anim_loop and breathing continues; no song deformation flags are enabled yet.
    try:
        app._update_sprite()
    except Exception:
        pass
    try:
        _petzhu_choir_refresh_ui(app)
    except Exception:
        pass
    try:
        app._choir_countdown_after_id_v37 = app.root.after(
            25, lambda a=app, sid=str(session.get("id", "")): _petzhu_choir_countdown_tick_v37(a, sid))
    except Exception:
        _petzhu_choir_countdown_tick_v37(app, str(session.get("id", "")))
    return True


# Replace the v36 start wrapper; we preserve its mouth-track cache reset behavior in this implementation.
_petzhu_choir_local_start = _petzhu_choir_local_start_v37

_PETZHU_CHOIR_V37_PREVIOUS_CLEAR_LOCAL = _petzhu_choir_clear_local
def _petzhu_choir_clear_local_v37(app, notify=False, reason=""):
    _petzhu_choir_countdown_clear_v37(app, cancel_timer=True)
    return _PETZHU_CHOIR_V37_PREVIOUS_CLEAR_LOCAL(app, notify=notify, reason=reason)
_petzhu_choir_clear_local = _petzhu_choir_clear_local_v37

# Avoid the 30 Hz trail refresh from repeatedly lifting the choir window over newly opened dialogs.
# The pet/trail layer still follows the topmost preference, but the choir Toplevel is only assigned
# the -topmost attribute when its state actually changes; no recurring lift() is issued.
_PETZHU_CHOIR_V37_BASE_APPLY_TOPMOST = globals().get("_PETZHU_MP_V36_PREVIOUS_APPLY_TOPMOST", None)
def _petzhu_mp_apply_topmost_stable_v37(self, *args, **kwargs):
    base = _PETZHU_CHOIR_V37_BASE_APPLY_TOPMOST
    result = base(self, *args, **kwargs) if callable(base) else None
    ui = getattr(self, "_choir_ui", {}) or {}
    win = ui.get("win")
    try:
        if win is not None and win.winfo_exists():
            enabled = bool(getattr(self, "pet_chat_topmost", True))
            prior = getattr(win, "_petzhu_choir_topmost_applied_v37", None)
            if prior is None or bool(prior) != enabled:
                win.attributes("-topmost", enabled)
                win._petzhu_choir_topmost_applied_v37 = enabled
    except Exception:
        pass
    return result
MaoPet._mp_apply_topmost_to_all = _petzhu_mp_apply_topmost_stable_v37



# ============================================================
# PETZhu 合唱 v38：合唱团期间禁止独立自动哼歌
# ============================================================
def _petzhu_choir_membership_blocks_idle_hum_v38(app):
    """本机仍属于合唱会话期间，屏蔽独立哼歌；完成一首歌但未解散也算合唱团期间。"""
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return False
    status = str(session.get("status", "lobby") or "lobby").strip().lower()
    return status not in {"disbanded", "left", "cancelled", "closed", "rejected"}


def _petzhu_choir_stop_idle_hum_for_session_v38(app):
    """合唱会话建立时立即终止已经在播放的独立自动哼歌，不触碰合唱声部通道。"""
    if not _petzhu_choir_membership_blocks_idle_hum_v38(app):
        return
    if bool(getattr(app, "_idle_hum_playing", False)):
        try:
            app._idle_hum_stop()
        except Exception:
            for channel in list(getattr(app, "_idle_hum_channels", []) or []):
                try:
                    channel.stop()
                except Exception:
                    pass
            app._idle_hum_playing = False
            app._idle_hum_channels = []
            app._idle_hum_after = None
    # The API's independent generated-hum path uses a separate runtime from saved idle songs.
    # Stop only the free-standing generated hum, never a choir track or ordinary lyric/dialogue.
    if (bool(getattr(app, "_chat_song_playing", False))
            and str(getattr(app, "_chat_song_mode", "")) == "generated_hum"):
        try:
            app._stop_chat_song_runtime()
        except Exception:
            pass


_PETZHU_CHOIR_V38_PREVIOUS_IDLE_HUM_START = MaoPet._idle_hum_start

def _petzhu_choir_idle_hum_start_v38(self, explicit=False):
    """The standalone hum engine cannot start while a choir session is active."""
    if _petzhu_choir_membership_blocks_idle_hum_v38(self):
        _petzhu_choir_stop_idle_hum_for_session_v38(self)
        return False
    return _PETZHU_CHOIR_V38_PREVIOUS_IDLE_HUM_START(self, explicit=explicit)

MaoPet._idle_hum_start = _petzhu_choir_idle_hum_start_v38


_PETZHU_CHOIR_V38_PREVIOUS_AUTO_HUM_LOOP = MaoPet._auto_hum_loop

def _petzhu_choir_auto_hum_loop_v38(self):
    """The 5–10 minute timer remains dormant during a choir and resumes after it is cleared."""
    if getattr(self, "_closing", False) or getattr(self, "_quitting", False):
        return
    if _petzhu_choir_membership_blocks_idle_hum_v38(self):
        _petzhu_choir_stop_idle_hum_for_session_v38(self)
        # Preserve one future timer without polling; once the session is cleared, humming can resume.
        try:
            self.root.after(random.randint(HUM_MIN, HUM_MAX) * 1000, self._auto_hum_loop)
        except Exception:
            pass
        return
    return _PETZHU_CHOIR_V38_PREVIOUS_AUTO_HUM_LOOP(self)

MaoPet._auto_hum_loop = _petzhu_choir_auto_hum_loop_v38


# AI replies can also start a separate generated-hum sequence. That route must respect the same
# choir lock, otherwise a random hum could overlap the deliberately assigned choir parts.
_PETZHU_CHOIR_V38_PREVIOUS_GENERATED_HUM = MaoPet._chat_song_start_generated_hum

def _petzhu_choir_generated_hum_start_v38(self, seed_text=""):
    if _petzhu_choir_membership_blocks_idle_hum_v38(self):
        return False
    return _PETZHU_CHOIR_V38_PREVIOUS_GENERATED_HUM(self, seed_text)

MaoPet._chat_song_start_generated_hum = _petzhu_choir_generated_hum_start_v38


def _petzhu_choir_wrap_session_creator_v38(func):
    if not callable(func):
        return func
    def wrapped(app, *args, **kwargs):
        result = func(app, *args, **kwargs)
        _petzhu_choir_stop_idle_hum_for_session_v38(app)
        return result
    wrapped.__name__ = getattr(func, "__name__", "choir_session_creator")
    wrapped.__doc__ = getattr(func, "__doc__", None)
    return wrapped

# Stop any existing idle/generated hum immediately after uploading a new song or accepting an invite.
if callable(globals().get("_petzhu_choir_load_song")):
    _petzhu_choir_load_song = _petzhu_choir_wrap_session_creator_v38(_petzhu_choir_load_song)
if callable(globals().get("_petzhu_choir_begin_song_v36")):
    _petzhu_choir_begin_song_v36 = _petzhu_choir_wrap_session_creator_v38(_petzhu_choir_begin_song_v36)
if callable(globals().get("_petzhu_choir_select_saved_song_v36")):
    _petzhu_choir_select_saved_song_v36 = _petzhu_choir_wrap_session_creator_v38(_petzhu_choir_select_saved_song_v36)
if callable(globals().get("_petzhu_choir_invitation_received")):
    _petzhu_choir_invitation_received = _petzhu_choir_wrap_session_creator_v38(_petzhu_choir_invitation_received)


