# PETZhu 联机合唱 v39：多首歌单、重复曲目、整份歌单循环与自动切歌
# ============================================================

_PETZHU_CHOIR_V39_PREVIOUS_OPEN_UI = _petzhu_choir_open_ui
_PETZHU_CHOIR_V39_PREVIOUS_REFRESH_UI = _petzhu_choir_refresh_ui
_PETZHU_CHOIR_V39_PREVIOUS_PLAYBACK_TICK = _petzhu_choir_playback_tick
_PETZHU_CHOIR_V39_PREVIOUS_START_FROM_UI = _petzhu_choir_start_from_ui
_PETZHU_CHOIR_V39_PREVIOUS_PAUSE_FROM_UI = _petzhu_choir_pause_from_ui
_PETZHU_CHOIR_V39_PREVIOUS_PACKET_HANDLER = _petzhu_mp_handle_choir_packet
_PETZHU_CHOIR_V39_PREVIOUS_STATUS_TEXT = _petzhu_choir_status_text
_PETZHU_CHOIR_V39_PREVIOUS_INVITATION_HANDLER = _petzhu_choir_invitation_received

_PETZHU_CHOIR_PLAYLIST_MAX_SONGS_V39 = 32
_PETZHU_CHOIR_PLAYLIST_MAX_BYTES_V39 = 16 * 1024 * 1024
_PETZHU_CHOIR_SWITCH_DELAY_V39 = 1.0
_PETZHU_CHOIR_ALLOWED_ACTIONS.add("song_switch")


def _petzhu_choir_playlist_entry_v39(name, song_data, song_path=""):
    return {
        "name": str(name or "歌曲")[:100],
        "song_data": copy.deepcopy(song_data),
        "song_path": str(song_path or ""),
    }


def _petzhu_choir_playlist_v39(session):
    if not isinstance(session, dict):
        return []
    playlist = session.get("playlist")
    if isinstance(playlist, list):
        return [item for item in playlist if isinstance(item, dict)
                and isinstance(item.get("song_data"), dict)]
    return []


def _petzhu_choir_playlist_set_current_v39(session, index):
    playlist = _petzhu_choir_playlist_v39(session)
    if not playlist:
        return False
    try:
        index = int(index)
    except Exception:
        return False
    if index < 0 or index >= len(playlist):
        return False
    entry = playlist[index]
    session["song_index"] = index
    session["song_name"] = str(entry.get("name", "歌曲") or "歌曲")[:100]
    session["song_data"] = entry["song_data"]
    session["song_path"] = str(entry.get("song_path", "") or "")
    session["_choir_mouth_note_key"] = None
    session["_choir_mouth_loop_index"] = None
    session["_choir_mouth_cache_key_v36"] = None
    session["_choir_mouth_loop_index_v36"] = None
    return True


def _petzhu_choir_playlist_commit_v39(app, session):
    playlist = _petzhu_choir_playlist_v39(session)
    session["playlist"] = playlist
    session["_playlist_initialized_v39"] = True
    if playlist:
        # The playlist is editable only before invitations are accepted, so its first item
        # is also the score used by the one-time voice-assignment dialogs.
        _petzhu_choir_playlist_set_current_v39(session, 0)
        app._choir_draft_song_data = playlist[0]["song_data"]
        app._choir_draft_song_name = playlist[0]["name"]
        app._choir_draft_song_path = playlist[0].get("song_path", "")
        session["status"] = "lobby"
        session["has_started"] = False
        session["start_step"] = 0
        session["next_step"] = 0
    else:
        app._choir_draft_song_data = None
        app._choir_draft_song_name = ""
        app._choir_draft_song_path = ""
        session["song_index"] = 0
        session["song_name"] = "歌单为空"
    _petzhu_choir_refresh_ui(app)


def _petzhu_choir_playlist_remote_members_v39(session, local_id):
    members = session.get("members", {}) if isinstance(session, dict) else {}
    return any(str(pid) != str(local_id) and isinstance(member, dict)
               and member.get("status") in ("pending", "accepted")
               for pid, member in members.items()) if isinstance(members, dict) else False


def _petzhu_choir_playlist_can_edit_v39(app, show_message=True):
    manager = getattr(app, "_mp", None)
    session = getattr(app, "_choir_session", None)
    parent = (getattr(app, "_choir_ui", {}) or {}).get("win") or getattr(app, "_api_win", None) or app.root
    if manager is None or not getattr(manager, "connected", False):
        if show_message:
            messagebox.showinfo("合唱歌单", "请先创建或加入联机房间，再准备歌单。", parent=parent)
        return False
    if isinstance(session, dict):
        if str(session.get("owner_id", "")) != str(manager.local_id):
            if show_message:
                messagebox.showinfo("合唱歌单", "只有合唱发起者可以编辑歌单。", parent=parent)
            return False
        if session.get("status") != "lobby" or bool(session.get("has_started", False)):
            if show_message:
                messagebox.showinfo("合唱歌单", "歌单已进入合唱阶段，不能再修改。请解散本团后重新准备歌单。", parent=parent)
            return False
        if _petzhu_choir_playlist_remote_members_v39(session, manager.local_id):
            if show_message:
                messagebox.showinfo("合唱歌单", "已有成员收到邀请或加入合唱。为避免各电脑歌单不一致，请先完成歌单编辑，再邀请成员。", parent=parent)
            return False
    return True


def _petzhu_choir_append_song_v39(app, song_data, song_name, song_path=""):
    if not _petzhu_choir_playlist_can_edit_v39(app, show_message=True):
        return False
    if not isinstance(song_data, dict) or not isinstance(song_data.get("tracks"), list):
        messagebox.showerror("合唱歌单", "这首歌曲不是有效的乐谱数据。",
                             parent=(getattr(app, "_choir_ui", {}) or {}).get("win") or app.root)
        return False
    try:
        encoded = json.dumps(song_data, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        if len(encoded) > _PETZHU_MP_MAX_SONG:
            raise ValueError("单首歌曲超过 420 KB 的联机传输上限。")
        if not any(app._song_all_note_objects(track) for track in song_data.get("tracks", [])):
            raise ValueError("乐谱中没有可播放的音符。")
    except Exception as exc:
        messagebox.showerror("合唱歌单", str(exc), parent=(getattr(app, "_choir_ui", {}) or {}).get("win") or app.root)
        return False

    manager = getattr(app, "_mp", None)
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        try:
            created = _petzhu_choir_begin_song_v36(app, song_data, song_name, song_path)
        except Exception as exc:
            messagebox.showerror("创建合唱歌单失败", str(exc),
                                 parent=(getattr(app, "_choir_ui", {}) or {}).get("win") or app.root)
            return False
        if not created:
            return False
        session = getattr(app, "_choir_session", None)
        if not isinstance(session, dict):
            return False
        session["playlist"] = []
        session["_playlist_initialized_v39"] = True

    playlist = _petzhu_choir_playlist_v39(session)
    if len(playlist) >= _PETZHU_CHOIR_PLAYLIST_MAX_SONGS_V39:
        messagebox.showwarning("合唱歌单", "每份歌单最多添加 %d 首歌曲。" % _PETZHU_CHOIR_PLAYLIST_MAX_SONGS_V39,
                               parent=(getattr(app, "_choir_ui", {}) or {}).get("win") or app.root)
        return False

    # Migrate a one-song session created by an earlier build, but don't resurrect a song
    # after the user deliberately emptied this version's playlist.
    if not bool(session.get("_playlist_initialized_v39", False)) and not playlist:
        old_data = session.get("song_data")
        old_name = session.get("song_name", "歌曲")
        old_path = session.get("song_path", "")
        if isinstance(old_data, dict) and any(app._song_all_note_objects(t) for t in old_data.get("tracks", [])):
            playlist.append(_petzhu_choir_playlist_entry_v39(old_name, old_data, old_path))
        session["_playlist_initialized_v39"] = True

    if len(playlist) >= _PETZHU_CHOIR_PLAYLIST_MAX_SONGS_V39:
        messagebox.showwarning("合唱歌单", "迁移原歌曲后已达到每份歌单 %d 首的上限。" % _PETZHU_CHOIR_PLAYLIST_MAX_SONGS_V39,
                               parent=(getattr(app, "_choir_ui", {}) or {}).get("win") or app.root)
        return False
    playlist.append(_petzhu_choir_playlist_entry_v39(song_name, song_data, song_path))
    session["playlist"] = playlist
    session["_playlist_initialized_v39"] = True
    _petzhu_choir_playlist_commit_v39(app, session)
    _petzhu_choir_set_status(app, "已将《%s》加入歌单（共 %d 首）。可以继续添加歌曲或调整顺序；准备完成后再邀请成员。" %
                             (str(song_name or "歌曲")[:80], len(playlist)))
    _petzhu_choir_refresh_ui(app)
    return True


def _petzhu_choir_load_song_v39(app):
    manager = getattr(app, "_mp", None)
    if manager is None:
        messagebox.showwarning("合唱", "联机模块尚未初始化。", parent=(getattr(app, "_choir_ui", {}) or {}).get("win") or app.root)
        return
    if not _petzhu_choir_playlist_can_edit_v39(app, show_message=True):
        return
    path = filedialog.askopenfilename(
        parent=(getattr(app, "_choir_ui", {}) or {}).get("win") or getattr(app, "_api_win", app.root),
        title="选择要加入合唱歌单的歌曲",
        filetypes=[("珠珠 / BeepBox 乐谱", "*.json"), ("JSON 文件", "*.json")])
    if not path:
        return
    try:
        with open(path, "r", encoding="utf-8-sig") as source:
            raw = json.load(source)
        if isinstance(raw, dict) and isinstance(raw.get("channels"), list):
            song_data = app._song_convert_beepbox_data(raw)
        else:
            song_data = app._song_normalize(raw)
        if not isinstance(song_data, dict) or not isinstance(song_data.get("tracks"), list):
            raise ValueError("无法读取这个乐谱格式。")
        if not any(app._song_all_note_objects(track) for track in song_data.get("tracks", [])):
            raise ValueError("乐谱中没有可播放的音符。")
        entry = _petzhu_choir_library_save_v36(app, os.path.basename(path), song_data)
        _petzhu_choir_append_song_v39(app, song_data, entry.get("name", os.path.basename(path)), entry.get("path", path))
    except Exception as exc:
        messagebox.showerror("读取合唱乐谱失败", str(exc),
                             parent=(getattr(app, "_choir_ui", {}) or {}).get("win") or getattr(app, "_api_win", app.root))
    _petzhu_choir_refresh_ui(app)


def _petzhu_choir_select_saved_song_v39(app):
    ui = getattr(app, "_choir_ui", {}) or {}
    combo = ui.get("library_combo")
    if combo is None:
        return
    if not _petzhu_choir_playlist_can_edit_v39(app, show_message=True):
        return
    label = str(combo.get() or "").strip()
    mapping = ui.get("library_label_to_id", {})
    song_id = mapping.get(label) if isinstance(mapping, dict) else None
    if not song_id:
        messagebox.showinfo("合唱曲库", "请先从本地曲库中选择一首已保存的歌曲。", parent=ui.get("win") or app.root)
        return
    entry = next((item for item in _petzhu_choir_library_entries_v36(app) if item.get("id") == song_id), None)
    if not entry:
        _petzhu_choir_refresh_ui(app)
        messagebox.showwarning("合唱曲库", "这首歌曲的本地记录不存在，请刷新后重试。", parent=ui.get("win") or app.root)
        return
    base, _manifest = _petzhu_choir_library_paths_v36(app)
    path = os.path.join(base, entry["file"])
    try:
        with open(path, "r", encoding="utf-8") as source:
            song_data = json.load(source)
        if (not isinstance(song_data, dict) or not isinstance(song_data.get("tracks"), list)
                or not any(app._song_all_note_objects(track) for track in song_data.get("tracks", []))):
            raise ValueError("保存的乐谱没有可播放的音符。")
        # Each click appends another entry, even when the same library item was selected before.
        _petzhu_choir_append_song_v39(app, song_data, entry["name"], path)
    except Exception as exc:
        messagebox.showerror("读取已保存歌曲失败", str(exc), parent=ui.get("win") or app.root)
    _petzhu_choir_refresh_ui(app)


def _petzhu_choir_playlist_move_v39(app, offset):
    if not _petzhu_choir_playlist_can_edit_v39(app, show_message=True):
        return
    ui = getattr(app, "_choir_ui", {}) or {}
    lb = ui.get("playlist_listbox")
    session = getattr(app, "_choir_session", None)
    if lb is None or not isinstance(session, dict):
        return
    selected = lb.curselection()
    if not selected:
        return
    source_index = int(selected[0])
    playlist = _petzhu_choir_playlist_v39(session)
    target_index = source_index + int(offset)
    if target_index < 0 or target_index >= len(playlist):
        return
    playlist[source_index], playlist[target_index] = playlist[target_index], playlist[source_index]
    session["playlist"] = playlist
    _petzhu_choir_playlist_commit_v39(app, session)
    try:
        lb.selection_clear(0, "end")
        lb.selection_set(target_index)
        lb.activate(target_index)
    except Exception:
        pass


def _petzhu_choir_playlist_remove_v39(app, clear_all=False):
    if not _petzhu_choir_playlist_can_edit_v39(app, show_message=True):
        return
    ui = getattr(app, "_choir_ui", {}) or {}
    lb = ui.get("playlist_listbox")
    session = getattr(app, "_choir_session", None)
    if lb is None or not isinstance(session, dict):
        return
    playlist = _petzhu_choir_playlist_v39(session)
    if clear_all:
        if not playlist:
            return
        playlist = []
    else:
        selected = lb.curselection()
        if not selected:
            messagebox.showinfo("合唱歌单", "请先选中要移除的歌曲。", parent=ui.get("win") or app.root)
            return
        index = int(selected[0])
        if index < 0 or index >= len(playlist):
            return
        playlist.pop(index)
    session["playlist"] = playlist
    session["_playlist_initialized_v39"] = True
    _petzhu_choir_playlist_commit_v39(app, session)


def _petzhu_choir_install_playlist_controls_v39(app):
    ui = getattr(app, "_choir_ui", None)
    if not isinstance(ui, dict):
        return
    win = ui.get("win")
    try:
        if win is None or not win.winfo_exists():
            return
    except Exception:
        return
    if ui.get("playlist_listbox") is None:
        try:
            content = ui["room_members"].master.master
            panel = tk.LabelFrame(win, text="本次合唱歌单（按列表顺序播放；同一首歌可以重复添加）",
                                  bg=app.C_BG, fg="#e8f0ff", padx=6, pady=5)
            panel.pack(fill="x", padx=12, pady=(0, 5), before=content)
            listbox = tk.Listbox(panel, height=4, bg=app.C_TEXT_BG, fg="#e8f0ff",
                                 selectbackground="#3f5b78", relief="flat",
                                 font=("微软雅黑", 9), activestyle="none", exportselection=False)
            listbox.pack(side="left", fill="both", expand=True, padx=(0, 6))
            buttons = tk.Frame(panel, bg=app.C_BG)
            buttons.pack(side="left", fill="y")
            button_options = dict(bg="#365575", fg="#ffffff", activebackground="#466887",
                                  activeforeground="#ffffff", bd=0, relief="flat",
                                  font=("微软雅黑", 8), padx=8, pady=3, cursor="hand2")
            tk.Button(buttons, text="上移", command=lambda a=app: _petzhu_choir_playlist_move_v39(a, -1), **button_options).pack(fill="x", pady=1)
            tk.Button(buttons, text="下移", command=lambda a=app: _petzhu_choir_playlist_move_v39(a, 1), **button_options).pack(fill="x", pady=1)
            tk.Button(buttons, text="移除", command=lambda a=app: _petzhu_choir_playlist_remove_v39(a, False), **button_options).pack(fill="x", pady=1)
            tk.Button(buttons, text="清空", command=lambda a=app: _petzhu_choir_playlist_remove_v39(a, True), **button_options).pack(fill="x", pady=1)
            ui["playlist_panel"] = panel
            ui["playlist_listbox"] = listbox
            ui["playlist_signature_v39"] = None
            try:
                ui["load_btn"].configure(text="导入歌曲并加入歌单")
            except Exception:
                pass
            try:
                if ui.get("library_btn") is not None:
                    ui["library_btn"].configure(text="加入所选歌曲")
            except Exception:
                pass
            try:
                ui["loop_check"].configure(text="循环播放整个歌单")
            except Exception:
                pass
        except Exception:
            return
    try:
        win.update_idletasks()
        sw, sh = win.winfo_screenwidth(), win.winfo_screenheight()
        width = min(860, max(760, sw - 30))
        height = min(750, max(600, sh - 50))
        x = max(0, min(win.winfo_x(), sw - width))
        y = max(0, min(win.winfo_y(), sh - height))
        win.geometry("%dx%d+%d+%d" % (width, height, x, y))
        win.minsize(min(760, width), min(600, height))
    except Exception:
        pass
    _petzhu_choir_refresh_ui(app)


def _petzhu_choir_open_ui_v39(app):
    _PETZHU_CHOIR_V39_PREVIOUS_OPEN_UI(app)
    _petzhu_choir_install_playlist_controls_v39(app)


# Preserve the v36 song-library controls, but selecting a saved song now appends it to the playlist.
_petzhu_choir_load_song = _petzhu_choir_load_song_v39
_petzhu_choir_select_saved_song_v36 = _petzhu_choir_select_saved_song_v39
_petzhu_choir_open_ui = _petzhu_choir_open_ui_v39


def _petzhu_choir_playlist_status_text_v39(app):
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return "尚未建立合唱歌单。导入歌曲或从本地曲库添加歌曲，再邀请成员。"
    playlist = _petzhu_choir_playlist_v39(session)
    count = len(playlist)
    status = str(session.get("status", "lobby") or "lobby")
    if status == "playing":
        idx = max(0, min(count - 1, int(session.get("song_index", 0) or 0))) if count else 0
        name = str(session.get("song_name", "歌曲") or "歌曲")[:70]
        loop_text = "歌单循环开启" if session.get("loop", False) else "歌单循环关闭"
        return "正在合唱（第 %d/%d 首）：《%s》｜%s" % (idx + 1, max(1, count), name, loop_text)
    if status == "countdown":
        number = getattr(app, "_choir_countdown_value_v37", None)
        if number is None:
            return "合唱倒计时：3、2、1……即将开始歌单。"
        return "合唱倒计时：%s" % str(number)
    if status == "switching":
        idx = max(0, min(count - 1, int(session.get("song_index", 0) or 0))) if count else 0
        return "正在切换到第 %d/%d 首：《%s》……" % (idx + 1, max(1, count), str(session.get("song_name", "歌曲"))[:70])
    if status == "awaiting_switch":
        return "本首歌曲已结束，正在等待发起者同步下一首……"
    if status == "paused":
        idx = max(0, min(count - 1, int(session.get("song_index", 0) or 0))) if count else 0
        return "合唱已暂停（第 %d/%d 首）：《%s》" % (idx + 1, max(1, count), str(session.get("song_name", "歌曲"))[:70])
    if status == "finished":
        return "歌单已全部合唱完毕；合唱团保留，可以重新从第一首开始或解散。"
    if not count:
        return "歌单为空。先添加歌曲；允许重复添加同一首歌。"
    pending = sum(1 for m in session.get("members", {}).values()
                  if isinstance(m, dict) and m.get("status") == "pending")
    accepted = sum(1 for m in session.get("members", {}).values()
                   if isinstance(m, dict) and m.get("status") == "accepted")
    return "歌单共 %d 首｜已加入 %d 人，等待回复/下载 %d 人。" % (count, accepted, pending)


_PETZHU_CHOIR_V39_PREVIOUS_REFRESH_UI = _petzhu_choir_refresh_ui

def _petzhu_choir_refresh_ui_v39(app):
    _PETZHU_CHOIR_V39_PREVIOUS_REFRESH_UI(app)
    ui = getattr(app, "_choir_ui", {}) or {}
    win = ui.get("win")
    try:
        if win is None or not win.winfo_exists():
            return
    except Exception:
        return
    manager = getattr(app, "_mp", None)
    session = getattr(app, "_choir_session", None)
    playlist = _petzhu_choir_playlist_v39(session)
    try:
        label = ui.get("song_label")
        if label is not None and label.winfo_exists():
            if playlist:
                first = str(playlist[0].get("name", "歌曲") or "歌曲")
                label.configure(text="歌单 %d 首｜首曲：《%s》" % (len(playlist), first[:70]))
            else:
                label.configure(text="歌单为空：导入歌曲或从本地曲库添加")
    except Exception:
        pass
    try:
        lb = ui.get("playlist_listbox")
        if lb is not None and lb.winfo_exists():
            signature = tuple((str(item.get("name", "歌曲")), str(item.get("song_path", "")), id(item.get("song_data"))) for item in playlist)
            if signature != ui.get("playlist_signature_v39"):
                old_sel = lb.curselection()
                old_idx = int(old_sel[0]) if old_sel else -1
                lb.delete(0, "end")
                for idx, item in enumerate(playlist, 1):
                    lb.insert("end", "%02d. %s" % (idx, str(item.get("name", "歌曲") or "歌曲")[:100]))
                ui["playlist_signature_v39"] = signature
                if playlist:
                    chosen = min(max(0, old_idx), len(playlist) - 1) if old_idx >= 0 else 0
                    lb.selection_set(chosen)
                    lb.activate(chosen)
    except Exception:
        pass
    connected = bool(manager is not None and getattr(manager, "connected", False))
    is_owner = bool(isinstance(session, dict) and manager is not None
                    and str(session.get("owner_id", "")) == str(getattr(manager, "local_id", "")))
    # Before the first song is added there is no session yet; allow the import/library
    # controls as soon as the local client is connected to a room.
    locked = not connected
    if isinstance(session, dict):
        locked = (not is_owner or session.get("status") != "lobby"
                  or bool(session.get("has_started", False))
                  or (manager is not None and
                      _petzhu_choir_playlist_remote_members_v39(session, manager.local_id)))
    try:
        controls_state = "disabled" if locked or not bool(getattr(manager, "connected", False)) else "normal"
        lb = ui.get("playlist_listbox")
        if lb is not None and lb.winfo_exists():
            lb.configure(state="disabled" if locked else "normal")
        panel = ui.get("playlist_panel")
        if panel is not None and panel.winfo_exists():
            for child in panel.winfo_children():
                if isinstance(child, tk.Frame):
                    for button in child.winfo_children():
                        if isinstance(button, tk.Button):
                            button.configure(state=controls_state)
        if ui.get("load_btn") is not None:
            ui["load_btn"].configure(state=controls_state)
        if ui.get("library_btn") is not None:
            ui["library_btn"].configure(state=controls_state)
    except Exception:
        pass
    try:
        if ui.get("status") is not None:
            ui["status"].configure(text=_petzhu_choir_playlist_status_text_v39(app))
    except Exception:
        pass

_petzhu_choir_refresh_ui = _petzhu_choir_refresh_ui_v39


def _petzhu_choir_start_from_ui_v39(app):
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return _PETZHU_CHOIR_V39_PREVIOUS_START_FROM_UI(app)
    playlist = _petzhu_choir_playlist_v39(session)
    if not playlist:
        messagebox.showinfo("合唱", "请先把至少一首歌曲加入歌单。",
                            parent=(getattr(app, "_choir_ui", {}) or {}).get("win") or app.root)
        return
    if session.get("status") in ("lobby", "finished"):
        _petzhu_choir_playlist_set_current_v39(session, 0)
    return _PETZHU_CHOIR_V39_PREVIOUS_START_FROM_UI(app)

_petzhu_choir_start_from_ui = _petzhu_choir_start_from_ui_v39


def _petzhu_choir_pause_from_ui_v39(app):
    manager = getattr(app, "_mp", None)
    session = getattr(app, "_choir_session", None)
    ui = getattr(app, "_choir_ui", {}) or {}
    if manager is None or not isinstance(session, dict) or str(session.get("owner_id", "")) != str(manager.local_id):
        return
    if session.get("status") == "playing":
        song = session.get("song_data", {})
        try:
            step_sec = 60.0 / max(50.0, min(240.0, float(song.get("bpm", 128) or 128))) / 4.0
            elapsed = max(0.0, time.monotonic() - float(session.get("start_mono", time.monotonic())))
            steps = max(1, int(song.get("steps", 256) or 256))
            current = int(session.get("start_step", 0) or 0) + int(elapsed / step_sec)
            pause_step = min(steps - 1, current + 1)
            _petzhu_choir_pause_local(app, pause_step)
            manager.send_choir("pause", {"session_id": session.get("id"), "step": pause_step})
        except Exception as exc:
            _petzhu_choir_set_status(app, "暂停合唱失败：%s" % str(exc)[:160])
    elif session.get("status") == "paused":
        _petzhu_choir_start_from_ui(app)
    _petzhu_choir_refresh_ui(app)

_petzhu_choir_pause_from_ui = _petzhu_choir_pause_from_ui_v39


def _petzhu_choir_switch_activate_v39(app, session_id, index, target_mono, target_perf):
    app._choir_after_id = None
    session = getattr(app, "_choir_session", None)
    if (not isinstance(session, dict) or str(session.get("id", "")) != str(session_id)
            or str(session.get("status", "")) != "switching"
            or int(session.get("song_index", -1)) != int(index)
            or getattr(app, "_closing", False)):
        return
    session["status"] = "playing"
    session["start_mono"] = float(target_mono)
    session["anim_start_perf"] = float(target_perf)
    session["start_step"] = 0
    session["next_step"] = 0
    session["last_abs_step"] = -1
    app._choir_playing = True
    app._choir_paused = False
    app._choir_anim_started_perf = float(target_perf)
    try:
        app._update_sprite()
    except Exception:
        pass
    _petzhu_choir_set_status(app, "已自动切换到《%s》，继续合唱。" % session.get("song_name", "歌曲"))
    _petzhu_choir_refresh_ui(app)
    _petzhu_choir_playback_tick(app)


def _petzhu_choir_switch_song_local_v39(app, index, delay=None):
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return False
    playlist = _petzhu_choir_playlist_v39(session)
    try:
        index = int(index)
    except Exception:
        return False
    if index < 0 or index >= len(playlist):
        return False
    try:
        delay = max(0.15, min(3.0, float(_PETZHU_CHOIR_SWITCH_DELAY_V39 if delay is None else delay)))
    except Exception:
        delay = _PETZHU_CHOIR_SWITCH_DELAY_V39
    old_after = getattr(app, "_choir_after_id", None)
    if old_after is not None:
        try:
            app.root.after_cancel(old_after)
        except Exception:
            pass
    app._choir_after_id = None
    _petzhu_choir_stop_audio(app)
    try:
        app.song_mouth_on = False
        app._song_vocal_key = None
        app._song_vocal_short_close_at = 0.0
    except Exception:
        pass
    if not _petzhu_choir_playlist_set_current_v39(session, index):
        return False
    session["status"] = "switching"
    session["has_started"] = True
    session["start_step"] = 0
    session["next_step"] = 0
    session["pause_step"] = 0
    session["last_abs_step"] = -1
    session["switch_started_at_v39"] = time.monotonic()
    target_mono = time.monotonic() + delay
    target_perf = time.perf_counter() + delay
    session["start_mono"] = target_mono
    session["anim_start_perf"] = target_perf
    session["_choir_mouth_note_key"] = None
    session["_choir_mouth_loop_index"] = None
    app._choir_playing = False
    app._choir_paused = False
    app._choir_anim_started_perf = 0.0
    try:
        app._update_sprite()
    except Exception:
        pass
    _petzhu_choir_refresh_ui(app)
    try:
        app._choir_after_id = app.root.after(
            max(1, int(delay * 1000)),
            lambda a=app, sid=str(session.get("id", "")), idx=index, tm=target_mono, tp=target_perf:
                _petzhu_choir_switch_activate_v39(a, sid, idx, tm, tp))
    except Exception:
        _petzhu_choir_switch_activate_v39(app, str(session.get("id", "")), index, target_mono, target_perf)
    return True


def _petzhu_choir_finish_playlist_v39(app, send_packet=True):
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return
    session["status"] = "finished"
    session["next_step"] = max(1, int(session.get("song_data", {}).get("steps", 256) or 256))
    app._choir_playing = False
    app._choir_paused = False
    _petzhu_choir_stop_audio(app)
    try:
        app.song_mouth_on = False
        app._update_sprite()
    except Exception:
        pass
    manager = getattr(app, "_mp", None)
    if send_packet and manager is not None and str(session.get("owner_id", "")) == str(manager.local_id):
        manager.send_choir("finish", {"session_id": session.get("id"), "step": session["next_step"]})
    _petzhu_choir_set_status(app, "歌单已全部合唱完毕。")
    _petzhu_choir_refresh_ui(app)


def _petzhu_choir_playback_tick_v39(app):
    app._choir_after_id = None
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict) or session.get("status") != "playing" or getattr(app, "_closing", False):
        return
    try:
        playlist = _petzhu_choir_playlist_v39(session)
        if not playlist:
            _petzhu_choir_finish_playlist_v39(app, send_packet=True)
            return
        song_index = max(0, min(len(playlist) - 1, int(session.get("song_index", 0) or 0)))
        # Keep the current score bound to the authoritative playlist item.
        if not isinstance(session.get("song_data"), dict):
            _petzhu_choir_playlist_set_current_v39(session, song_index)
        song_data = session.get("song_data", {})
        bpm = max(50.0, min(240.0, float(song_data.get("bpm", 128) or 128)))
        step_seconds = 60.0 / bpm / 4.0
        start_mono = float(session.get("start_mono", time.monotonic()) or time.monotonic())
        now = time.monotonic()
        if now < start_mono:
            app._choir_after_id = app.root.after(max(1, int((start_mono - now) * 1000)),
                                                  lambda a=app: _petzhu_choir_playback_tick(a))
            return
        start_step = max(0, int(session.get("start_step", 0) or 0))
        absolute_step = start_step + max(0, int((now - start_mono) / step_seconds))
        steps = max(1, min(256, int(song_data.get("steps", 256) or 256)))
        if absolute_step >= steps:
            _petzhu_choir_stop_audio(app)
            try:
                app.song_mouth_on = False
                app._update_sprite()
            except Exception:
                pass
            manager = getattr(app, "_mp", None)
            is_owner = manager is not None and str(session.get("owner_id", "")) == str(getattr(manager, "local_id", ""))
            if not is_owner:
                # Clients wait for the single authoritative switch/finish packet; they never prompt the user.
                session["status"] = "awaiting_switch"
                app._choir_playing = False
                app._choir_paused = False
                _petzhu_choir_set_status(app, "本首歌曲已结束，等待发起者同步下一首……")
                _petzhu_choir_refresh_ui(app)
                return
            next_index = song_index + 1
            if next_index >= len(playlist):
                if bool(session.get("loop", False)):
                    next_index = 0
                else:
                    _petzhu_choir_finish_playlist_v39(app, send_packet=True)
                    return
            delay = _PETZHU_CHOIR_SWITCH_DELAY_V39
            # Send only the target index: every member already has the exact same ordered playlist.
            manager.send_choir("song_switch", {
                "session_id": session.get("id"),
                "playlist_index": next_index,
                "delay": delay,
                "loop": bool(session.get("loop", False)),
            })
            _petzhu_choir_switch_song_local_v39(app, next_index, delay=delay)
            return
        step = absolute_step
        last_abs = int(session.get("last_abs_step", start_step - 1))
        if absolute_step > last_abs:
            _petzhu_choir_play_voice_step(app, session, step, absolute_step=absolute_step)
            session["last_abs_step"] = absolute_step
            session["next_step"] = step + 1
        session["current_step"] = step
        next_boundary = start_mono + (int((now - start_mono) / step_seconds) + 1) * step_seconds
        delay_ms = max(1, min(20, int(round((next_boundary - time.monotonic()) * 1000.0))))
        app._choir_after_id = app.root.after(delay_ms, lambda a=app: _petzhu_choir_playback_tick(a))
    except Exception as exc:
        session["status"] = "finished"
        app._choir_playing = False
        _petzhu_choir_stop_audio(app)
        _petzhu_choir_set_status(app, "合唱播放遇到错误，已停止：%s" % str(exc)[:120])
        _petzhu_choir_refresh_ui(app)

_petzhu_choir_playback_tick = _petzhu_choir_playback_tick_v39


def _petzhu_choir_packet_handler_v39(app, packet):
    if isinstance(packet, dict) and str(packet.get("action", "") or "")[:32] == "song_switch":
        manager = getattr(app, "_mp", None)
        if manager is None:
            return
        data = packet.get("data", {}) if isinstance(packet.get("data"), dict) else {}
        session_id = str(data.get("session_id", "") or "")[:32]
        sender = str(packet.get("peer_id", "") or "")[:32]
        session = getattr(app, "_choir_session", None)
        if not isinstance(session, dict) or session_id != str(session.get("id", "")):
            return
        if sender != str(session.get("owner_id", "")):
            return
        try:
            index = int(data.get("playlist_index", -1))
            delay = max(0.15, min(3.0, float(data.get("delay", _PETZHU_CHOIR_SWITCH_DELAY_V39))))
        except Exception:
            return
        playlist = _petzhu_choir_playlist_v39(session)
        if index < 0 or index >= len(playlist):
            return
        session["loop"] = bool(data.get("loop", session.get("loop", False)))
        # No member confirmation or per-song invitation: switch to the pre-downloaded item directly.
        _petzhu_choir_switch_song_local_v39(app, index, delay=delay)
        return
    return _PETZHU_CHOIR_V39_PREVIOUS_PACKET_HANDLER(app, packet)

_petzhu_mp_handle_choir_packet = _petzhu_choir_packet_handler_v39


def _petzhu_choir_invitation_received_v39(app, packet):
    manager = getattr(app, "_mp", None)
    data = packet.get("data", {}) if isinstance(packet, dict) and isinstance(packet.get("data"), dict) else {}
    owner_id = str(packet.get("peer_id", "") or data.get("owner_id", ""))[:32]
    owner_name = str(packet.get("name", data.get("owner_name", "房间成员")) or "房间成员")[:24]
    session_id = str(data.get("session_id", "") or "")[:32]
    parent = getattr(app, "_api_win", None)
    try:
        if parent is None or not parent.winfo_exists():
            parent = app.root
    except Exception:
        parent = app.root
    if not session_id or not owner_id or manager is None:
        return
    if isinstance(getattr(app, "_choir_session", None), dict):
        messagebox.showinfo("合唱邀请", "你已经在另一个合唱团中。请先退出当前合唱，再接受新的邀请。", parent=parent)
        manager.send_choir("decline", {"session_id": session_id, "reason": "已经加入其他合唱团"}, target=owner_id)
        return

    raw_playlist = data.get("playlist")
    if not isinstance(raw_playlist, list) or not raw_playlist:
        legacy_song = data.get("song_data")
        raw_playlist = [{"name": data.get("song_name", "歌曲"), "song_data": legacy_song}]
    if len(raw_playlist) > _PETZHU_CHOIR_PLAYLIST_MAX_SONGS_V39:
        manager.send_choir("decline", {"session_id": session_id, "reason": "歌单歌曲数量超过上限"}, target=owner_id)
        messagebox.showerror("合唱乐谱下载失败", "歌单最多支持 %d 首歌曲。" % _PETZHU_CHOIR_PLAYLIST_MAX_SONGS_V39, parent=parent)
        return

    playlist = []
    total_bytes = 0
    try:
        for idx, entry in enumerate(raw_playlist):
            if not isinstance(entry, dict) or not isinstance(entry.get("song_data"), dict):
                raise ValueError("歌单第 %d 首歌曲没有有效乐谱。" % (idx + 1))
            raw_song = entry["song_data"]
            encoded = json.dumps(raw_song, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
            if len(encoded) > _PETZHU_MP_MAX_SONG:
                raise ValueError("歌单第 %d 首歌曲超过 420 KB 的传输上限。" % (idx + 1))
            total_bytes += len(encoded)
            if total_bytes > _PETZHU_CHOIR_PLAYLIST_MAX_BYTES_V39:
                raise ValueError("整份歌单超过 16 MB 的传输上限，请减少歌曲数量或精简乐谱。")
            song_data = app._song_normalize(raw_song)
            if (not isinstance(song_data, dict) or not isinstance(song_data.get("tracks"), list)
                    or not any(app._song_all_note_objects(track) for track in song_data.get("tracks", []))):
                raise ValueError("歌单第 %d 首歌曲没有可播放的音符。" % (idx + 1))
            song_name = str(entry.get("name", "歌曲 %d" % (idx + 1)) or ("歌曲 %d" % (idx + 1)))[:100]
            cache_name = "%02d_%s" % (idx + 1, song_name)
            cache_path = _petzhu_choir_save_song_cache(app, session_id, cache_name, song_data)
            playlist.append(_petzhu_choir_playlist_entry_v39(song_name, song_data, cache_path))
            try:
                _petzhu_choir_library_save_v36(app, song_name, song_data)
            except Exception:
                pass
    except Exception as exc:
        reason = str(exc)[:220]
        manager.send_choir("decline", {"session_id": session_id, "reason": reason}, target=owner_id)
        messagebox.showerror("合唱乐谱下载失败", reason, parent=parent)
        return

    first_song = playlist[0]["song_data"]
    assigned = _petzhu_choir_clean_voices(data.get("assigned_voices", {}), first_song)
    if not assigned:
        manager.send_choir("decline", {"session_id": session_id, "reason": "邀请没有指定有效声部"}, target=owner_id)
        return
    member_list = _petzhu_choir_members_from_wire(data.get("members", []), first_song)
    local_id = str(getattr(manager, "local_id", ""))
    local_name = str(getattr(app, "pet_name", "桌宠") or "桌宠")[:24]
    member_list[local_id] = {"name": local_name, "status": "pending", "voices": assigned, "downloaded": True}
    roles = "、".join(_PETZHU_CHOIR_PART_LABELS[key] for key in assigned)
    song_name = str(playlist[0].get("name", "歌曲") or "歌曲")
    invite_text = ("%s 邀请你参加合唱歌单：\n共 %d 首，第一首是《%s》\n\n"
                   "整份歌单已下载并保存。负责声部：%s\n\n"
                   "接受一次后即可跟随房主按顺序自动切歌；切歌时不需要再次确认。合唱过程中可以随时退出。" %
                   (owner_name, len(playlist), song_name, roles))
    accepted = messagebox.askyesno("合唱歌单邀请", invite_text, parent=parent)
    if not accepted:
        manager.send_choir("decline", {"session_id": session_id, "reason": "对方拒绝了合唱邀请"}, target=owner_id)
        return

    member_list[local_id]["status"] = "accepted"
    manager_name = str(getattr(manager, "local_name", local_name) or local_name)[:24]
    app._choir_session = {
        "id": session_id, "owner_id": owner_id, "owner_name": owner_name,
        "song_name": song_name, "song_data": first_song, "song_path": playlist[0].get("song_path", ""),
        "playlist": playlist, "_playlist_initialized_v39": True, "song_index": 0,
        "loop": bool(data.get("loop", False)), "status": "lobby", "members": member_list,
        "is_owner": False, "has_started": False, "start_step": 0, "next_step": 0,
    }
    member_list[local_id]["name"] = manager_name
    app._choir_draft_song_data = first_song
    app._choir_draft_song_name = song_name
    app._choir_draft_song_path = playlist[0].get("song_path", "")
    # Preserve v38's guarantee: stop any already-running idle hum immediately upon joining.
    try:
        _petzhu_choir_stop_idle_hum_for_session_v38(app)
    except Exception:
        pass
    manager.send_choir("accept", {"session_id": session_id, "downloaded": True}, target=owner_id)
    _petzhu_choir_set_status(app, "已接受 %d 首歌曲的合唱歌单；接下来由发起者统一开始和自动切歌。" % len(playlist))
    _petzhu_choir_refresh_ui(app)

_petzhu_choir_invitation_received = _petzhu_choir_invitation_received_v39


def _petzhu_choir_invite_selected_v39(app):
    manager = getattr(app, "_mp", None)
    session = getattr(app, "_choir_session", None)
    ui = getattr(app, "_choir_ui", {}) or {}
    parent = ui.get("win") or app.root
    if manager is None or not getattr(manager, "connected", False):
        messagebox.showinfo("合唱", "请先创建或加入联机房间。", parent=parent)
        return
    if not isinstance(session, dict) or str(session.get("owner_id", "")) != str(manager.local_id):
        messagebox.showinfo("合唱", "请先创建歌单；只有发起者可以邀请成员。", parent=parent)
        return
    playlist = _petzhu_choir_playlist_v39(session)
    if not playlist:
        messagebox.showinfo("合唱", "请先至少添加一首歌曲到歌单。", parent=parent)
        return
    if bool(session.get("has_started", False)) or session.get("status") != "lobby":
        messagebox.showinfo("合唱", "歌单已经开始播放，不能再邀请新成员。", parent=parent)
        return
    local_member = session.get("members", {}).get(str(manager.local_id), {})
    own_voices = _petzhu_choir_clean_voices(local_member.get("voices", {}), playlist[0]["song_data"]) if isinstance(local_member, dict) else {}
    if not own_voices:
        messagebox.showinfo("合唱", "请先设置发起者自己负责的声部、音色和音量。", parent=parent)
        return
    lb = ui.get("room_members")
    selected = lb.curselection() if lb is not None else ()
    ids = list(ui.get("room_member_ids", []))
    if not selected or int(selected[0]) >= len(ids):
        messagebox.showinfo("合唱", "请先在房间成员列表中选中要邀请的桌宠。", parent=parent)
        return
    target = str(ids[int(selected[0])])
    existing = session.get("members", {}).get(target, {})
    if isinstance(existing, dict) and existing.get("status") in ("pending", "accepted"):
        messagebox.showinfo("合唱", "这位成员已经收到邀请或已加入合唱。", parent=parent)
        return
    live = next((item for item in manager.get_members()
                 if str(item.get("id", "")) == target and str(item.get("id", "")) != str(manager.local_id)), None)
    if live is None:
        _petzhu_choir_refresh_ui(app)
        messagebox.showwarning("成员列表已更新", "选中的成员已经不在当前房间，请刷新后重试。", parent=parent)
        return
    assigned = _petzhu_choir_voice_config_dialog(app, parent, "设置成员负责的声部", playlist[0]["song_data"], None)
    if assigned is None:
        return
    assigned = _petzhu_choir_clean_voices(assigned, playlist[0]["song_data"])
    if not assigned:
        messagebox.showinfo("合唱", "至少为该成员选择一个声部。", parent=parent)
        return
    live = next((item for item in manager.get_members()
                 if str(item.get("id", "")) == target and str(item.get("id", "")) != str(manager.local_id)), None)
    if live is None:
        _petzhu_choir_refresh_ui(app)
        messagebox.showwarning("成员已离开", "配置声部期间，该成员已离开房间；邀请未发送。", parent=parent)
        return
    target_name = str(live.get("name", "桌宠") or "桌宠")[:24]
    session.setdefault("members", {})[target] = {
        "name": target_name, "status": "pending", "voices": assigned, "downloaded": False
    }
    wire_playlist = [{"name": str(item.get("name", "歌曲"))[:100], "song_data": item["song_data"]}
                     for item in playlist]
    data = {
        "session_id": session["id"], "owner_id": manager.local_id,
        "owner_name": str(manager.local_name or getattr(app, "pet_name", "桌宠"))[:24],
        "song_name": str(playlist[0].get("name", "歌曲"))[:100],
        "song_data": playlist[0]["song_data"],
        "playlist": wire_playlist,
        "assigned_voices": assigned,
        "members": _petzhu_choir_member_wire(session),
        "loop": bool(session.get("loop", False)),
    }
    try:
        packet_size = len(json.dumps(data, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
        if packet_size > _PETZHU_CHOIR_PLAYLIST_MAX_BYTES_V39 + 512 * 1024:
            raise ValueError("整份歌单邀请包超过联机传输上限（约 16.5 MB）。请减少歌曲数量或精简乐谱。")
    except Exception as exc:
        session["members"].pop(target, None)
        messagebox.showerror("无法发送邀请", str(exc), parent=parent)
        _petzhu_choir_refresh_ui(app)
        return
    if not manager.send_choir("invite", data, target=target):
        session["members"].pop(target, None)
        reason = str(getattr(manager, "_last_choir_send_error", "") or "未知的发送错误。")
        messagebox.showerror("邀请失败", "无法向%s发送整份歌单。\n\n原因：%s" % (target_name, reason), parent=parent)
    else:
        _petzhu_choir_set_status(app, "已向%s发送包含 %d 首歌曲的歌单和声部邀请；对方只需接受一次。" % (target_name, len(playlist)))
    _petzhu_choir_refresh_ui(app)

_petzhu_choir_invite_selected = _petzhu_choir_invite_selected_v39


def _petzhu_choir_status_text_v39(app):
    return _petzhu_choir_playlist_status_text_v39(app)

_petzhu_choir_status_text = _petzhu_choir_status_text_v39



# ============================================================
# PETZhu v42: install the choir-window first-frame theme fix BEFORE main().
# The previous v41 block sat below main(); since Tk's mainloop blocks there,
# that patch was not installed until the application had already been closed.
# ============================================================
def _petzhu_choir_open_ui_v42(app):
    ui = getattr(app, "_choir_ui", None)
    existing_win = ui.get("win") if isinstance(ui, dict) else None

    def _apply_light_palette_hidden(win):
        """Apply the current light palette while the Toplevel is withdrawn."""
        if not bool(getattr(app, "_context_palette_light", False)):
            return
        try:
            app._apply_window_pink_theme(win)
            return
        except Exception:
            pass
        # Defensive fallback for incomplete theme-helper support. Apply a complete
        # first-frame palette to all standard Tk widgets before showing the window.
        try:
            win.configure(bg="#fff0f6")
            walk = getattr(app, "_walk_widget_tree", None)
            if callable(walk):
                widgets = list(walk(win))
            else:
                widgets = []
                stack = [win]
                while stack:
                    widget = stack.pop()
                    widgets.append(widget)
                    try:
                        stack.extend(widget.winfo_children())
                    except Exception:
                        pass
            for widget in widgets:
                try:
                    cls = str(widget.winfo_class())
                    if cls in ("Frame", "Labelframe", "Toplevel"):
                        widget.configure(bg="#fff0f6")
                    elif cls in ("Label", "Checkbutton", "Radiobutton"):
                        widget.configure(bg="#fff0f6", fg="#1e2a3a")
                    elif cls in ("Entry", "Text", "Listbox", "Spinbox"):
                        widget.configure(bg="#fceaf2", fg="#1e2a3a",
                                         insertbackground="#1e2a3a",
                                         selectbackground="#d96fa8",
                                         selectforeground="#ffffff")
                    elif cls in ("Button", "Menubutton"):
                        widget.configure(bg="#f0bfd6", fg="#1e2a3a",
                                         activebackground="#d96fa8",
                                         activeforeground="#ffffff")
                except Exception:
                    pass
        except Exception:
            pass

    # Re-opening an existing window must also be themed while hidden. The old
    # opener calls deiconify() immediately, which could reveal stale/dark colors.
    try:
        if existing_win is not None and existing_win.winfo_exists():
            try:
                existing_win.withdraw()
            except Exception:
                pass
            _petzhu_choir_install_playlist_controls_v39(app)
            _apply_light_palette_hidden(existing_win)
            try:
                existing_win.update_idletasks()
                existing_win.deiconify()
                existing_win.lift()
            except Exception:
                pass
            try:
                _petzhu_choir_refresh_ui(app)
            except Exception:
                pass
            return
    except Exception:
        pass

    # Create any new Toplevel hidden before returning control to Tk's event loop.
    # The hook is installed only for the synchronous constructor call and restored
    # immediately afterwards; no global behavior persists after this function.
    toplevel_cls = tk.Toplevel
    original_init = toplevel_cls.__init__

    def _withdraw_toplevel_during_init(self, *args, **kwargs):
        original_init(self, *args, **kwargs)
        try:
            self.withdraw()
        except Exception:
            pass

    try:
        toplevel_cls.__init__ = _withdraw_toplevel_during_init
        _PETZHU_CHOIR_V39_PREVIOUS_OPEN_UI(app)
    finally:
        toplevel_cls.__init__ = original_init

    _petzhu_choir_install_playlist_controls_v39(app)
    ui = getattr(app, "_choir_ui", None)
    win = ui.get("win") if isinstance(ui, dict) else None
    try:
        if win is None or not win.winfo_exists():
            return
    except Exception:
        return

    _apply_light_palette_hidden(win)
    try:
        win.update_idletasks()
    except Exception:
        pass
    try:
        win.deiconify()
        win.lift()
    except Exception:
        pass


_petzhu_choir_open_ui = _petzhu_choir_open_ui_v42


# ============================================================
# PETZhu v45: API/联机窗口 first-frame flash root fix.
# 原 show_api_config() 在整个控件树创建完之前就会显示 Toplevel；
# v43/v44 的“函数返回后再处理”已经错过首次映射。
# 这里在本次 API 窗口创建调用期间拦截 Toplevel.__init__，创建后立即 withdraw，
# 等完整的 API + 联机中继 + 合唱控件全部安装并应用当前主题后才 deiconify。
# 作用范围严格限制于同步调用 show_api_config() 的这段时间。
# ============================================================
_PETZHU_API_V45_PREVIOUS_SHOW_API = MaoPet.show_api_config

def _petzhu_show_api_atomic_first_paint_v45(self):
    # 已存在的窗口走原有重提交流程，不创建新 Toplevel。
    existing = getattr(self, "_api_win", None)
    try:
        if existing is not None and existing.winfo_exists():
            return _PETZHU_API_V45_PREVIOUS_SHOW_API(self)
    except Exception:
        pass

    toplevel_cls = tk.Toplevel
    original_init = toplevel_cls.__init__
    original_deiconify = tk.Wm.wm_deiconify
    original_deiconify_alias = tk.Wm.deiconify
    original_lift = tk.Misc.tkraise
    original_lift_alias = tk.Misc.lift
    original_focus_force = tk.Misc.focus_force

    def _create_withdrawn_toplevel(widget, *args, **kwargs):
        # 原生 Toplevel 创建后马上撤下映射；Tk 处理下一轮绘制事件前，
        # 调用栈会继续构建其所有子控件和最终主题色。
        original_init(widget, *args, **kwargs)
        try:
            widget._petzhu_api_pending_show_v45 = True
            widget.withdraw()
        except Exception:
            pass

    def _defer_window_show(original_method):
        def wrapped(widget, *args, **kwargs):
            if bool(getattr(widget, "_petzhu_api_pending_show_v45", False)):
                return None
            return original_method(widget, *args, **kwargs)
        return wrapped

    # 旧版 show_api_config 包装器会在内部提前 deiconify/lift/focus。
    # 临时延迟这三个动作，否则外层的 withdraw 无法阻止那个早于主题完成的显示。
    deferred_deiconify = _defer_window_show(original_deiconify)
    deferred_lift = _defer_window_show(original_lift)
    deferred_focus_force = _defer_window_show(original_focus_force)
    result = None
    try:
        toplevel_cls.__init__ = _create_withdrawn_toplevel
        tk.Wm.wm_deiconify = deferred_deiconify
        tk.Wm.deiconify = deferred_deiconify
        tk.Misc.tkraise = deferred_lift
        tk.Misc.lift = deferred_lift
        tk.Misc.focus_force = deferred_focus_force
        result = _PETZHU_API_V45_PREVIOUS_SHOW_API(self)
    finally:
        # 无论 API 构建是否抛错，都恢复 Tkinter 类方法，避免影响其他窗口。
        toplevel_cls.__init__ = original_init
        tk.Wm.wm_deiconify = original_deiconify
        tk.Wm.deiconify = original_deiconify_alias
        tk.Misc.tkraise = original_lift
        tk.Misc.lift = original_lift_alias
        tk.Misc.focus_force = original_focus_force

    win = getattr(self, "_api_win", None)
    try:
        if win is not None and win.winfo_exists():
            # 外层包装已追加完 API 中继控件与合唱按钮；在显示前统一落到当前主题。
            try:
                self._apply_window_pink_theme(win)
            except Exception:
                pass
            try:
                _petzhu_mp_update_relay_control_visuals(self)
            except Exception:
                pass
            win.update_idletasks()
            try:
                win._petzhu_api_pending_show_v45 = False
            except Exception:
                pass
            original_deiconify(win)
            original_lift(win)
            try:
                original_focus_force(win)
            except Exception:
                pass
    except Exception:
        try:
            if win is not None:
                win._petzhu_api_pending_show_v45 = False
        except Exception:
            pass
    return result

MaoPet.show_api_config = _petzhu_show_api_atomic_first_paint_v45


# ============================================================
# PETZhu v46: API/联机窗口的主题原子首帧。
#
# Root fix vs the earlier retries:
# 1) The core constructor supplies the correct theme background in Toplevel's
#    creation command (not in a later configure call).
# 2) The core immediately withdraws the window and marks it pending.
# 3) Intermediate wrappers may update geometry while hidden, but none is allowed
#    to show/focus the window. The final wrapper below calls the pre-v45 chain,
#    so the complete API + online panel + relay/chat + choir UI is built first.
# 4) The window is themed and idle geometry is flushed while withdrawn, then shown
#    exactly once. This avoids the previous temporary monkeypatching of Tk classes.
# ============================================================
_PETZHU_API_V46_PREVIOUS_SHOW_API = _petzhu_mp_show_api_with_choir

def _petzhu_show_api_finalized_theme_first_paint_v46(self):
    win = getattr(self, "_api_win", None)
    live = False
    withdrawn = False
    try:
        live = bool(win is not None and win.winfo_exists())
        withdrawn = live and str(win.state()).lower() == "withdrawn"
    except Exception:
        live = False
        withdrawn = False

    # A visible existing window needs no teardown; this path only refreshes its
    # existing controls and keeps the original behavior.
    if live and not withdrawn:
        return _PETZHU_API_V46_PREVIOUS_SHOW_API(self)

    # If a live API window is retained but withdrawn, keep it hidden through the
    # same wrapper chain. A brand-new one is created hidden by the core constructor.
    if live and withdrawn:
        try:
            win._petzhu_api_pending_show_v46 = True
        except Exception:
            pass

    result = _PETZHU_API_V46_PREVIOUS_SHOW_API(self)
    win = getattr(self, "_api_win", None)
    try:
        if win is None or not win.winfo_exists():
            return result

        # Reassert the hidden state before final theme application. This is a safety
        # barrier against any intermediate wrapper accidentally calling a show method.
        try:
            win.withdraw()
        except Exception:
            pass
        try:
            win._petzhu_api_pending_show_v46 = True
        except Exception:
            pass

        # Apply the selected palette to the complete widget tree while hidden.
        # Dark mode already has explicit dark widget colors from the constructors;
        # the pink helper is intentionally a no-op in dark mode.
        try:
            if bool(getattr(self, "_context_palette_light", False)):
                self._apply_window_pink_theme(win)
            else:
                win.configure(bg=str(getattr(self, "C_BG", "#1e2a3a") or "#1e2a3a"))
        except Exception:
            pass
        try:
            _petzhu_mp_update_relay_control_visuals(self)
        except Exception:
            pass
        try:
            _petzhu_mp_render_chat(self)
        except Exception:
            pass

        # Geometry/layout flush is safe now because the Toplevel is still withdrawn.
        try:
            win.update_idletasks()
        except Exception:
            pass

        try:
            win._petzhu_api_pending_show_v46 = False
        except Exception:
            pass
        try:
            win.deiconify()
            win.lift()
            win.focus_force()
        except Exception:
            pass
    except Exception:
        try:
            if win is not None:
                win._petzhu_api_pending_show_v46 = False
        except Exception:
            pass
    return result

MaoPet.show_api_config = _petzhu_show_api_finalized_theme_first_paint_v46


# ============================================================
# PETZhu v47: API/联机黑底闪白的真实路径修复。
# v46 的两个缺口：
# 1) 对 state()==normal 的存活窗口直接 return，根本不重新应用主题；
# 2) 深色模式只改 Toplevel 背景，未恢复已被浅色主题改色的子控件。
# 另外，通用 <Map> after_idle 主题回调可能在 deiconify 后再次扫描该窗口。
# v47 对这三条路径一并处理：先修复已有可见窗再 raise；隐藏窗/新窗口始终在
# 完整控件树配色后显示；API 窗口不再接受通用 Map 回调的二次改色。
# ============================================================
_PETZHU_API_V47_PREVIOUS_SHOW_API = _PETZHU_API_V46_PREVIOUS_SHOW_API


def _petzhu_api_apply_native_frame_theme_v48(app, win):
    """在窗口仍隐藏时设置 Windows 原生标题栏/边框颜色，避免深色外框先闪白。

    Tk 的 bg 只控制客户区；Windows DWM 单独绘制非客户区。此函数只作用于
    API/联机 Toplevel，且在 deiconify 前调用；旧版 Windows 不支持的属性会被忽略。
    """
    if os.name != "nt":
        return False
    try:
        if win is None or not win.winfo_exists():
            return False
    except Exception:
        return False

    light = bool(getattr(app, "_context_palette_light", False))
    if light:
        window_bg = "#fff0f6"
        title_fg = "#1e2a3a"
        use_dark = 0
    else:
        window_bg = str(getattr(app, "C_BG", "#1e2a3a") or "#1e2a3a")
        title_fg = str(getattr(app, "C_FG", "#e8f0ff") or "#e8f0ff")
        use_dark = 1

    def colorref(hex_color):
        s = str(hex_color or "").strip().lstrip("#")
        if len(s) != 6:
            return 0x001E2A3A
        r = int(s[0:2], 16)
        g = int(s[2:4], 16)
        b = int(s[4:6], 16)
        # COLORREF is 0x00BBGGRR, not an RGB integer.
        return r | (g << 8) | (b << 16)

    try:
        from ctypes import wintypes
        dwmapi = ctypes.WinDLL("dwmapi", use_last_error=True)
        set_attr = dwmapi.DwmSetWindowAttribute
        set_attr.argtypes = [wintypes.HWND, wintypes.DWORD, ctypes.c_void_p, wintypes.DWORD]
        set_attr.restype = ctypes.c_long
        # Prefer the actual external frame HWND returned by "wm frame". On some
        # Tk/Windows builds winfo_id() identifies the client HWND inside that frame;
        # retain it as a fallback in case wm frame is unavailable.
        hwnd_values = []
        try:
            raw_frame = str(win.tk.call("wm", "frame", win._w) or "").strip()
            if raw_frame:
                try:
                    frame_value = int(raw_frame, 0)
                except ValueError:
                    frame_value = int(raw_frame, 16) if all(c in "0123456789abcdefABCDEF" for c in raw_frame) else 0
                if frame_value > 0:
                    hwnd_values.append(frame_value)
        except Exception:
            pass
        try:
            client_value = int(win.winfo_id())
            if client_value > 0 and client_value not in hwnd_values:
                hwnd_values.append(client_value)
        except Exception:
            pass
        if not hwnd_values:
            return False

        def apply_value(attribute, value, value_type):
            try:
                storage = value_type(value)
                payload = ctypes.byref(storage)
                payload_size = ctypes.sizeof(storage)
                for handle_value in hwnd_values:
                    try:
                        hr = int(set_attr(wintypes.HWND(handle_value), attribute, payload, payload_size))
                        if hr >= 0:
                            return True
                    except Exception:
                        continue
            except Exception:
                # Older Windows builds do not recognize all DWM attributes.
                pass
            return False

        # DWMWA_USE_IMMERSIVE_DARK_MODE (20) controls the system-drawn caption theme.
        apply_value(20, use_dark, ctypes.c_int)
        # Windows 11 DWM attributes: border (34), caption (35), title text (36).
        apply_value(34, colorref(window_bg), ctypes.c_uint32)
        apply_value(35, colorref(window_bg), ctypes.c_uint32)
        apply_value(36, colorref(title_fg), ctypes.c_uint32)
        try:
            win.configure(bg=window_bg)
        except Exception:
            pass
        return True
    except Exception:
        return False


def _petzhu_api_walk_widgets_v47(root):
    yield root
    try:
        children = root.winfo_children()
    except Exception:
        children = []
    for child in children:
        yield from _petzhu_api_walk_widgets_v47(child)


def _petzhu_api_apply_current_palette_v47(app, win):
    """Apply the selected palette to the complete API widget tree synchronously."""
    try:
        if win is None or not win.winfo_exists():
            return
    except Exception:
        return

    if bool(getattr(app, "_context_palette_light", False)):
        # This helper remembers the original colors before painting light mode.
        try:
            app._apply_window_pink_theme(win)
        except Exception:
            pass
        return

    # Deep restore first: the original colors recorded by the light-theme helper are
    # per-widget. Restoring only Toplevel(bg=...) leaves white/pink child frames behind.
    try:
        cache = getattr(app, "_context_theme_originals", {})
        if isinstance(cache, dict):
            for widget in list(_petzhu_api_walk_widgets_v47(win)):
                try:
                    if not widget.winfo_exists():
                        continue
                except Exception:
                    continue
                saved = cache.get(widget)
                if not isinstance(saved, dict):
                    continue
                opts = saved.get("options", {})
                if isinstance(opts, dict) and opts:
                    try:
                        widget.configure(**opts)
                    except Exception:
                        pass
                if str(getattr(widget, "winfo_class", lambda: "")()) == "Canvas":
                    for item_id, item_opts in (saved.get("canvas_items", {}) or {}).items():
                        try:
                            if int(item_id) in widget.find_all():
                                widget.itemconfigure(item_id, **item_opts)
                        except Exception:
                            pass
    except Exception:
        pass

    # Defensive normalization for light-colored widgets created after a theme snapshot
    # (for example, a newly-added choir button). Keep semantic green/red buttons intact.
    dark_window = str(getattr(app, "C_BG", "#1e2a3a") or "#1e2a3a")
    dark_field = str(getattr(app, "C_TEXT_BG", "#111a26") or "#111a26")
    dark_fg = str(getattr(app, "C_FG", "#e8f0ff") or "#e8f0ff")
    dark_edge = str(getattr(app, "C_BORDER", "#7fb1e8") or "#7fb1e8")
    pale_bgs = {
        "#fff0f6", "#fff7fb", "#fceaf2", "#f7e2ed", "#f4dce8",
        "#f0bfd6", "#efa8ca", "#d96fa8", "#edc0d5", "#fcebf3",
        "#f2d5e3", "#e9a0c4", "#f2a6cb",
    }
    pale_fg_to_dark = {
        "#1e2a3a": dark_fg,
        "#78566a": "#8a9bb5",
        "#b52d70": "#f2a6cb",
        "#243247": dark_fg,
        "#526880": "#9fb4c8",
        "#667b94": "#8a9bb5",
    }
    pale_button_bgs = {"#f0bfd6", "#efa8ca", "#d96fa8", "#fff0f6", "#fff7fb", "#fceaf2"}
    for widget in list(_petzhu_api_walk_widgets_v47(win)):
        try:
            if not widget.winfo_exists():
                continue
            cls = str(widget.winfo_class())
            try:
                bg = str(widget.cget("background") or "").lower()
            except Exception:
                bg = ""
            try:
                fg = str(widget.cget("foreground") or "").lower()
            except Exception:
                fg = ""
            updates = {}
            if cls in ("Toplevel", "Frame", "Labelframe", "Label") and bg in pale_bgs:
                updates["bg"] = dark_window
                if fg in pale_fg_to_dark:
                    updates["fg"] = pale_fg_to_dark[fg]
            elif cls in ("Entry", "Text", "Listbox", "Spinbox") and bg in pale_bgs:
                updates.update(bg=dark_field, fg=dark_fg, insertbackground=dark_fg,
                               selectbackground="#365575", selectforeground="#ffffff",
                               highlightbackground=dark_edge, highlightcolor=dark_edge)
            elif cls in ("Checkbutton", "Radiobutton"):
                if bg in pale_bgs:
                    updates["bg"] = dark_window
                if fg in pale_fg_to_dark:
                    updates["fg"] = pale_fg_to_dark[fg]
                try:
                    if str(widget.cget("selectcolor") or "").lower() in pale_bgs:
                        updates["selectcolor"] = dark_field
                except Exception:
                    pass
                try:
                    if str(widget.cget("activebackground") or "").lower() in pale_bgs:
                        updates["activebackground"] = dark_edge
                except Exception:
                    pass
            elif cls in ("Button", "Menubutton"):
                if bg in pale_button_bgs:
                    # Only replace light-theme pinks; keep existing semantic/dark buttons.
                    updates["bg"] = "#365575" if bg in ("#f0bfd6", "#efa8ca", "#d96fa8") else "#2a3a4a"
                if fg in pale_fg_to_dark:
                    updates["fg"] = "#ffffff"
                try:
                    if str(widget.cget("activebackground") or "").lower() in pale_bgs:
                        updates["activebackground"] = dark_edge
                except Exception:
                    pass
            elif cls == "Canvas" and bg in pale_bgs:
                updates["bg"] = dark_field
            elif cls in ("Scrollbar", "TScrollbar"):
                if bg in pale_bgs:
                    updates["bg"] = "#2a3a4a"
                try:
                    if str(widget.cget("troughcolor") or "").lower() in pale_bgs:
                        updates["troughcolor"] = dark_window
                except Exception:
                    pass
            else:
                if bg in pale_bgs:
                    updates["bg"] = dark_window
                if fg in pale_fg_to_dark:
                    updates["fg"] = pale_fg_to_dark[fg]
            if updates:
                try:
                    widget.configure(**updates)
                except Exception:
                    pass
        except Exception:
            pass

    try:
        win.configure(bg=dark_window)
    except Exception:
        pass


def _petzhu_show_api_atomic_theme_v47(self):
    win = getattr(self, "_api_win", None)
    live = False
    state = ""
    try:
        live = bool(win is not None and win.winfo_exists())
        state = str(win.state()).lower() if live else ""
    except Exception:
        live = False
        state = ""

    # Do not bypass final theming for a live normal-state window. v46 did so, which
    # is precisely the path that could expose stale light colors when raised again.
    keep_visible = bool(live and state == "normal")
    if keep_visible:
        # Correct client palette and native non-client frame before the old chain raises it.
        try:
            self._petzhu_api_theme_initializing_v47 = True
            _petzhu_api_apply_current_palette_v47(self, win)
            _petzhu_api_apply_native_frame_theme_v48(self, win)
        except Exception:
            pass
    else:
        # New, withdrawn or minimized window: keep it invisible through all wrappers.
        if live:
            try:
                win.withdraw()
            except Exception:
                pass
        if live:
            try:
                win._petzhu_api_pending_show_v46 = True
            except Exception:
                pass
        self._petzhu_api_theme_initializing_v47 = True

    result = None
    try:
        result = _PETZHU_API_V47_PREVIOUS_SHOW_API(self)
        win = getattr(self, "_api_win", None)
        if win is None or not win.winfo_exists():
            return result

        if not keep_visible:
            try:
                win.withdraw()
            except Exception:
                pass
            try:
                win._petzhu_api_pending_show_v46 = True
            except Exception:
                pass

        try:
            _petzhu_mp_update_relay_control_visuals(self)
        except Exception:
            pass
        try:
            _petzhu_mp_render_chat(self)
        except Exception:
            pass
        _petzhu_api_apply_current_palette_v47(self, win)
        try:
            # Realize geometry while withdrawn, then configure Windows' native frame.
            win.update_idletasks()
        except Exception:
            pass
        _petzhu_api_apply_native_frame_theme_v48(self, win)
        try:
            # Flush any frame/theme-related idle work before the first visible frame.
            win.update_idletasks()
        except Exception:
            pass

        try:
            win._petzhu_api_pending_show_v46 = False
        except Exception:
            pass
        if not keep_visible:
            try:
                win.deiconify()
                win.lift()
                win.focus_force()
            except Exception:
                pass
        else:
            # Existing visible window was themed before it was raised; retain normal behavior.
            try:
                win.lift()
                win.focus_force()
            except Exception:
                pass
        return result
    except Exception:
        # Do not leave a window withdrawn or the Map guard enabled if an unrelated
        # widget refresh raises during UI construction. Reapply the current colors first.
        try:
            failed_win = getattr(self, "_api_win", None)
            if failed_win is not None and failed_win.winfo_exists():
                _petzhu_api_apply_current_palette_v47(self, failed_win)
                try:
                    failed_win._petzhu_api_pending_show_v46 = False
                except Exception:
                    pass
                if not keep_visible:
                    failed_win.deiconify()
        except Exception:
            pass
        raise
    finally:
        try:
            self._petzhu_api_theme_initializing_v47 = False
        except Exception:
            pass


MaoPet.show_api_config = _petzhu_show_api_atomic_theme_v47



# ============================================================
# PETZhu v49: API/联机面板首帧闪白根因修复（接入最终实际入口）
#
# v45 的创建期保护曾被 v46/v47 的 show_api_config 赋值绕开；因此后续只在
# 显示前补色，仍不能约束旧包装器里的 deiconify/lift/focus 和窗口管理器首帧。
# v49 在当前真正生效的 show_api_config 外层统一设栅栏：创建/重开期间透明、隐藏，
# 完整构建并应用当前主题和 DWM 外框后才恢复不透明并映射。深色主题同时恢复
# 浅色主题曾修改过的子控件原色，防止背景大块白色残留。
# ============================================================
_PETZHU_API_V49_PREVIOUS_SHOW_API = MaoPet.show_api_config


def _petzhu_show_api_atomic_palette_v49(self):
    win = getattr(self, "_api_win", None)
    live = False
    state = ""
    try:
        live = bool(win is not None and win.winfo_exists())
        state = str(win.state()).lower() if live else ""
    except Exception:
        live, state = False, ""

    # 已经正常显示的窗口不撤下，避免用户再次点击时出现真正的隐藏/重显闪烁。
    if live and state == "normal":
        try:
            _petzhu_api_apply_current_palette_v47(self, win)
            _petzhu_api_apply_native_frame_theme_v48(self, win)
        except Exception:
            pass
        return _PETZHU_API_V49_PREVIOUS_SHOW_API(self)

    # 已存在但隐藏/最小化的窗口也要经过同一条“隐藏→主题完整→显示”通道。
    if live:
        try:
            win._petzhu_api_pending_show_v49 = True
            win._petzhu_api_pending_show_v46 = True
            try:
                win.attributes("-alpha", 0.0)
                win._petzhu_api_alpha_hidden_v49 = True
            except Exception:
                win._petzhu_api_alpha_hidden_v49 = False
            win.withdraw()
        except Exception:
            pass

    toplevel_cls = tk.Toplevel
    original_init = toplevel_cls.__init__
    original_wm_deiconify = tk.Wm.wm_deiconify
    original_deiconify = tk.Wm.deiconify
    original_tkraise = tk.Misc.tkraise
    original_lift = tk.Misc.lift
    original_focus_force = tk.Misc.focus_force

    def _is_pending_api(widget):
        try:
            return bool(getattr(widget, "_petzhu_api_pending_show_v49", False))
        except Exception:
            return False

    def _create_api_toplevel_hidden(widget, *args, **kwargs):
        # This handler only exists during the synchronous API-window constructor call.
        # The API window is parented to app.root; do not affect unrelated top-levels.
        parent = args[0] if args else kwargs.get("master", None)
        is_api_parent = parent is getattr(self, "root", None)
        if not is_api_parent:
            return original_init(widget, *args, **kwargs)

        light = bool(getattr(self, "_context_palette_light", False))
        initial_bg = "#fff0f6" if light else str(getattr(self, "C_BG", "#1e2a3a") or "#1e2a3a")
        # Pass the final color to Tcl's toplevel creation command itself; it is not a
        # post-map configure. Mark pending before Tk initializes the widget so no later
        # wrapper can reveal it while the constructor chain is still running.
        kwargs = dict(kwargs)
        kwargs["bg"] = initial_bg
        widget._petzhu_api_pending_show_v49 = True
        try:
            original_init(widget, *args, **kwargs)
            try:
                widget.configure(bg=initial_bg)
            except Exception:
                pass
            try:
                widget.attributes("-alpha", 0.0)
                widget._petzhu_api_alpha_hidden_v49 = True
            except Exception:
                widget._petzhu_api_alpha_hidden_v49 = False
            try:
                widget.withdraw()
            except Exception:
                pass
        except Exception:
            try:
                widget._petzhu_api_pending_show_v49 = False
            except Exception:
                pass
            raise

    def _defer_show(original_method):
        def wrapped(widget, *args, **kwargs):
            if _is_pending_api(widget):
                return None
            return original_method(widget, *args, **kwargs)
        return wrapped

    deferred_wm_deiconify = _defer_show(original_wm_deiconify)
    deferred_deiconify = _defer_show(original_deiconify)
    deferred_tkraise = _defer_show(original_tkraise)
    deferred_lift = _defer_show(original_lift)
    deferred_focus_force = _defer_show(original_focus_force)
    result = None
    error_info = None

    try:
        toplevel_cls.__init__ = _create_api_toplevel_hidden
        tk.Wm.wm_deiconify = deferred_wm_deiconify
        tk.Wm.deiconify = deferred_deiconify
        tk.Misc.tkraise = deferred_tkraise
        tk.Misc.lift = deferred_lift
        tk.Misc.focus_force = deferred_focus_force

        # Call the actual active wrapper chain. It installs API fields, online controls,
        # relay chat and choir controls. Any attempt to map/raise/focus the API window is
        # deferred until this outer function has committed the final palette.
        result = _PETZHU_API_V49_PREVIOUS_SHOW_API(self)
        win = getattr(self, "_api_win", None)
        if win is not None and win.winfo_exists():
            try:
                win._petzhu_api_pending_show_v49 = True
                win._petzhu_api_pending_show_v46 = True
                win.withdraw()
            except Exception:
                pass
            try:
                _petzhu_mp_render_chat(self)
            except Exception:
                pass
            _petzhu_api_apply_current_palette_v47(self, win)
            try:
                _petzhu_mp_update_relay_control_visuals(self)
            except Exception:
                pass
            try:
                _petzhu_mp_render_chat(self)
            except Exception:
                pass
            try:
                win.update_idletasks()
            except Exception:
                pass
            # Windows' non-client frame must be themed before any visible mapping.
            _petzhu_api_apply_native_frame_theme_v48(self, win)
            try:
                win.update_idletasks()
            except Exception:
                pass
    except BaseException:
        error_info = sys.exc_info()
    finally:
        # Never leave process-wide Tk methods patched, even if a legacy wrapper fails.
        toplevel_cls.__init__ = original_init
        tk.Wm.wm_deiconify = original_wm_deiconify
        tk.Wm.deiconify = original_deiconify
        tk.Misc.tkraise = original_tkraise
        tk.Misc.lift = original_lift
        tk.Misc.focus_force = original_focus_force

    win = getattr(self, "_api_win", None)
    try:
        if win is not None and win.winfo_exists():
            # On a construction failure, make a best effort to restore a usable window
            # rather than leaving a transparent or withdrawn Toplevel behind.
            if error_info is not None:
                try:
                    _petzhu_api_apply_current_palette_v47(self, win)
                    _petzhu_api_apply_native_frame_theme_v48(self, win)
                    win.update_idletasks()
                except Exception:
                    pass
            try:
                win._petzhu_api_pending_show_v49 = False
                win._petzhu_api_pending_show_v46 = False
            except Exception:
                pass
            try:
                if bool(getattr(win, "_petzhu_api_alpha_hidden_v49", False)):
                    win.attributes("-alpha", 1.0)
                win._petzhu_api_alpha_hidden_v49 = False
            except Exception:
                pass
            # A newly built or previously hidden window gets exactly one visible mapping,
            # after client and native-frame colors have been committed.
            try:
                win.deiconify()
                win.lift()
                win.focus_force()
            except Exception:
                pass
    except Exception:
        pass

    if error_info is not None:
        raise error_info[1].with_traceback(error_info[2])
    return result


MaoPet.show_api_config = _petzhu_show_api_atomic_palette_v49


# ============================================================
# PETZhu v50：联机第一阶段稳定性修复
# - 放行歌单自动切歌消息。
# - 限制远端歌曲缓存的条目数与总字节数。
# - 房间切换时为连接分代，关闭/等待旧线程与套接字，防止旧连接污染新房间。
# ============================================================

# Remote song cache policy. Keep recent scores plus each peer's current score, but never
# allow generated-hum song IDs to accumulate without bound over a long session.
_PETZHU_MP_REMOTE_SONG_CACHE_MAX_ENTRIES_V50 = 8
_PETZHU_MP_REMOTE_SONG_CACHE_MAX_ENTRY_BYTES_V50 = 2 * 1024 * 1024
_PETZHU_MP_REMOTE_SONG_CACHE_TOTAL_BYTES_V50 = 24 * 1024 * 1024
_PETZHU_MP_REMOTE_SONG_CACHE_TRACKER_ATTR_V50 = "_mp_remote_song_cache_sizes_v50"
_PETZHU_MP_REMOTE_SONG_CACHE_LOCK_ATTR_V50 = "_mp_remote_song_cache_lock_v50"


def _petzhu_mp_song_cache_lock_v50(app):
    lock = getattr(app, _PETZHU_MP_REMOTE_SONG_CACHE_LOCK_ATTR_V50, None)
    if lock is None:
        lock = threading.RLock()
        setattr(app, _PETZHU_MP_REMOTE_SONG_CACHE_LOCK_ATTR_V50, lock)
    return lock


def _petzhu_mp_song_cache_tracker_v50(app):
    tracker = getattr(app, _PETZHU_MP_REMOTE_SONG_CACHE_TRACKER_ATTR_V50, None)
    if not isinstance(tracker, OrderedDict):
        tracker = OrderedDict()
        setattr(app, _PETZHU_MP_REMOTE_SONG_CACHE_TRACKER_ATTR_V50, tracker)
    return tracker


def _petzhu_mp_song_cache_drop_v50(app, peer_id, song_id):
    caches = getattr(app, "_mp_remote_song_cache", {})
    cache = caches.get(peer_id) if isinstance(caches, dict) else None
    if isinstance(cache, dict):
        cache.pop(song_id, None)
    tracker = _petzhu_mp_song_cache_tracker_v50(app)
    tracker.pop((str(peer_id), str(song_id)), None)


def _petzhu_mp_song_cache_trim_v50(app):
    with _petzhu_mp_song_cache_lock_v50(app):
        caches = getattr(app, "_mp_remote_song_cache", {})
        current_ids = getattr(app, "_mp_remote_song_current", {})
        if not isinstance(caches, dict):
            return
        tracker = _petzhu_mp_song_cache_tracker_v50(app)

        # Discard accounting for entries that were removed by peer-leave cleanup.
        for tracked_key in list(tracker.keys()):
            peer_id, song_id = tracked_key
            peer_cache = caches.get(peer_id)
            if not isinstance(peer_cache, dict) or song_id not in peer_cache:
                tracker.pop(tracked_key, None)

        # Bound each peer independently. Never evict the score currently being played.
        for peer_id, peer_cache in list(caches.items()):
            if not isinstance(peer_cache, dict):
                caches.pop(peer_id, None)
                continue
            current_id = str(current_ids.get(peer_id, "") or "")
            while len(peer_cache) > _PETZHU_MP_REMOTE_SONG_CACHE_MAX_ENTRIES_V50:
                removable = next((key for key in peer_cache.keys() if str(key) != current_id), None)
                if removable is None:
                    break
                _petzhu_mp_song_cache_drop_v50(app, peer_id, removable)

        total_bytes = sum(tracker.values())
        while total_bytes > _PETZHU_MP_REMOTE_SONG_CACHE_TOTAL_BYTES_V50 and tracker:
            candidate = None
            for tracked_key in tracker.keys():
                peer_id, song_id = tracked_key
                current_id = str(current_ids.get(peer_id, "") or "")
                if str(song_id) != current_id:
                    candidate = tracked_key
                    break
            if candidate is None:
                # With at most seven remote peers and a 2 MiB per-score cap, protected active
                # scores alone fit within the global budget.
                break
            peer_id, song_id = candidate
            removed_size = tracker.get(candidate, 0)
            _petzhu_mp_song_cache_drop_v50(app, peer_id, song_id)
            total_bytes = max(0, total_bytes - removed_size)


def _petzhu_mp_song_cache_store_v50(app, peer_id, song_id, data, make_current=False):
    peer_id = str(peer_id or "")[:32]
    song_id = str(song_id or "")[:100]
    if not peer_id or not song_id or not isinstance(data, dict):
        return False
    try:
        size = len(json.dumps(data, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
    except Exception:
        return False
    if size <= 0 or size > _PETZHU_MP_REMOTE_SONG_CACHE_MAX_ENTRY_BYTES_V50:
        # Reject oversize entries even if they arrived through a resource/roster path.
        with _petzhu_mp_song_cache_lock_v50(app):
            _petzhu_mp_song_cache_drop_v50(app, peer_id, song_id)
        return False

    with _petzhu_mp_song_cache_lock_v50(app):
        caches = getattr(app, "_mp_remote_song_cache", None)
        if not isinstance(caches, dict):
            caches = app._mp_remote_song_cache = {}
        cache = caches.setdefault(peer_id, {})
        if not isinstance(cache, dict):
            cache = caches[peer_id] = {}
        # Dict insertion order is used as a cheap per-peer LRU. Move refreshed items to end.
        cache.pop(song_id, None)
        cache[song_id] = data
        tracker = _petzhu_mp_song_cache_tracker_v50(app)
        tracker.pop((peer_id, song_id), None)
        tracker[(peer_id, song_id)] = size
        if make_current:
            current = getattr(app, "_mp_remote_song_current", None)
            if not isinstance(current, dict):
                current = app._mp_remote_song_current = {}
            current[peer_id] = song_id
        _petzhu_mp_song_cache_trim_v50(app)
        return song_id in cache


# The playback worker calls this original function through a global reference. Replace that
# reference with a bounded adapter; data is stored once, then the existing synthesizer reads
# it by song_id exactly as before.
_PETZHU_MP_REMOTE_SONG_TICK_UNBOUNDED_V50 = _PETZHU_MP_ORIGINAL_REMOTE_SONG_TICK


def _petzhu_mp_remote_song_tick_bounded_v50(app, packet):
    if not isinstance(packet, dict):
        return
    pid = str(packet.get("peer_id", "") or "")[:32]
    song_id = str(packet.get("song_id", "") or "")[:100]
    if not pid or not song_id:
        return
    data = packet.get("data")
    safe_packet = dict(packet)
    if isinstance(data, dict):
        if not _petzhu_mp_song_cache_store_v50(app, pid, song_id, data, make_current=True):
            return
        # Avoid a second direct/unbounded cache insert in the legacy tick implementation.
        safe_packet["data"] = None
    else:
        with _petzhu_mp_song_cache_lock_v50(app):
            cache = getattr(app, "_mp_remote_song_cache", {}).get(pid, {})
            if song_id in cache:
                try:
                    existing_data = cache.pop(song_id)
                    cache[song_id] = existing_data
                    tracker = _petzhu_mp_song_cache_tracker_v50(app)
                    tracked_key = (pid, song_id)
                    if tracked_key in tracker:
                        tracker.move_to_end(tracked_key)
                except Exception:
                    pass
            current = getattr(app, "_mp_remote_song_current", {}).get(pid, "")
            if song_id not in cache and current:
                # Preserve original fallback semantics; the score data remains the current one.
                pass
    try:
        return _PETZHU_MP_REMOTE_SONG_TICK_UNBOUNDED_V50(app, safe_packet)
    finally:
        _petzhu_mp_song_cache_trim_v50(app)


_PETZHU_MP_ORIGINAL_REMOTE_SONG_TICK = _petzhu_mp_remote_song_tick_bounded_v50


# Asset advertisements also populate the remote score dictionary. Account for them and apply
# the same limits after the original image/resource loader finishes.
_PETZHU_MP_REMOTE_VIEW_LOAD_ASSETS_PRE_V50 = _PETZhuRemotePetView._load_assets


def _petzhu_mp_remote_view_load_assets_bounded_v50(self):
    result = _PETZHU_MP_REMOTE_VIEW_LOAD_ASSETS_PRE_V50(self)
    try:
        cache = getattr(self.app, "_mp_remote_song_cache", {}).get(str(self.peer_id), {})
        if isinstance(cache, dict):
            for song_id, song_data in list(cache.items()):
                _petzhu_mp_song_cache_store_v50(self.app, self.peer_id, song_id, song_data,
                    make_current=(str(getattr(self.app, "_mp_remote_song_current", {}).get(str(self.peer_id), "")) == str(song_id)))
    except Exception:
        pass
    return result


_PETZhuRemotePetView._load_assets = _petzhu_mp_remote_view_load_assets_bounded_v50


# Connection generation prevents a late connect/handshake from an old attempt from replacing
# the socket or mode of a newer room. Pending handshake sockets are separately tracked so stop()
# can close them even before they become client_socket.
def _petzhu_mp_generation_init_v50(self):
    if not isinstance(getattr(self, "_mp_session_generation", None), int):
        self._mp_session_generation = 0
    if not isinstance(getattr(self, "_mp_peer_worker_threads_v50", None), set):
        self._mp_peer_worker_threads_v50 = set()
    if not isinstance(getattr(self, "_mp_peer_worker_sockets_v50", None), set):
        self._mp_peer_worker_sockets_v50 = set()
    if not isinstance(getattr(self, "_mp_peer_socket_generations", None), dict):
        self._mp_peer_socket_generations = {}
    if not hasattr(self, "_mp_peer_workers_lock_v50"):
        self._mp_peer_workers_lock_v50 = threading.RLock()
    if not hasattr(self, "_pending_client_socket_v50"):
        self._pending_client_socket_v50 = None


_PETZHU_MP_STOP_BEFORE_LIFECYCLE_V50 = _PETZhuMultiplayer.stop


def _petzhu_mp_stop_lifecycle_v50(self, notify=True, quiet=False):
    _petzhu_mp_generation_init_v50(self)
    with self.lock:
        self._mp_session_generation += 1
        old_server_thread = getattr(self, "server_thread", None)
        old_client_thread = getattr(self, "client_thread", None)
        pending_sock = getattr(self, "_pending_client_socket_v50", None)
    preserve_stop_status = bool(getattr(self, "running", False) and not quiet)

    # Discard messages queued by the previous room before its workers are stopped.
    events = getattr(self, "events", None)
    if events is not None:
        while True:
            try:
                events.get_nowait()
                try: events.task_done()
                except Exception: pass
            except queue.Empty:
                break
            except Exception:
                break

    result = _PETZHU_MP_STOP_BEFORE_LIFECYCLE_V50(self, notify=notify, quiet=quiet)
    latest_pending_sock = getattr(self, "_pending_client_socket_v50", None)

    # First stop the accept loop so no more peer workers can be spawned, then close all sockets
    # accepted during a handshake (those sockets are not in _peer_sockets yet).
    deadline = time.monotonic() + 2.5
    current_thread = threading.current_thread()
    if old_server_thread is not None and old_server_thread is not current_thread:
        try: old_server_thread.join(max(0.0, deadline - time.monotonic()))
        except Exception: pass

    with getattr(self, "_mp_peer_workers_lock_v50"):
        worker_sockets = list(getattr(self, "_mp_peer_worker_sockets_v50", set()))
        worker_threads = list(getattr(self, "_mp_peer_worker_threads_v50", set()))
    if pending_sock is not None:
        worker_sockets.append(pending_sock)
    if latest_pending_sock is not None and latest_pending_sock not in worker_sockets:
        worker_sockets.append(latest_pending_sock)
    for sock in worker_sockets:
        try: _petzhu_mp_forget_socket(sock)
        except Exception: pass
        try: sock.shutdown(socket.SHUT_RDWR)
        except Exception: pass
        try: sock.close()
        except Exception: pass

    for thread in [old_client_thread] + worker_threads:
        if thread is None or thread is current_thread:
            continue
        if time.monotonic() >= deadline:
            break
        try: thread.join(max(0.0, deadline - time.monotonic()))
        except Exception: pass

    if old_server_thread is getattr(self, "server_thread", None):
        if old_server_thread is None or not old_server_thread.is_alive():
            self.server_thread = None
    if old_client_thread is getattr(self, "client_thread", None):
        if old_client_thread is None or not old_client_thread.is_alive():
            self.client_thread = None
    if getattr(self, "_pending_client_socket_v50", None) in (pending_sock, latest_pending_sock):
        self._pending_client_socket_v50 = None

    if events is not None:
        last_status = None
        while True:
            try:
                item = events.get_nowait()
                if preserve_stop_status and isinstance(item, dict) and item.get("type") == "status":
                    last_status = item
                try: events.task_done()
                except Exception: pass
            except queue.Empty:
                break
            except Exception:
                break
        if last_status is not None:
            try: events.put(last_status)
            except Exception: pass
    return result


_PETZhuMultiplayer.stop = _petzhu_mp_stop_lifecycle_v50


# Make the server accept loop capture its own listener socket and register worker threads before
# they start. This closes the race where a new room replaces self.server_socket while an old
# accept loop/worker is still waking up.
def _petzhu_mp_server_peer_worker_tracked_v50(self, sock, addr):
    _petzhu_mp_generation_init_v50(self)
    current = threading.current_thread()
    with self._mp_peer_workers_lock_v50:
        self._mp_peer_worker_threads_v50.add(current)
        self._mp_peer_worker_sockets_v50.add(sock)
        self._mp_peer_socket_generations.setdefault(id(sock), self._mp_session_generation)
    try:
        return _PETZHU_MP_SERVER_PEER_WORKER_PRE_V50(self, sock, addr)
    finally:
        with self._mp_peer_workers_lock_v50:
            self._mp_peer_worker_threads_v50.discard(current)
            self._mp_peer_worker_sockets_v50.discard(sock)
            self._mp_peer_socket_generations.pop(id(sock), None)
        try: _petzhu_mp_forget_socket(sock)
        except Exception: pass
        try: sock.close()
        except Exception: pass


_PETZHU_MP_SERVER_PEER_WORKER_PRE_V50 = _PETZhuMultiplayer._server_peer_worker
_PETZhuMultiplayer._server_peer_worker = _petzhu_mp_server_peer_worker_tracked_v50


def _petzhu_mp_accept_loop_lifecycle_v50(self):
    _petzhu_mp_generation_init_v50(self)
    listener = getattr(self, "server_socket", None)
    if listener is None:
        return
    generation = self._mp_session_generation
    while self.running and not self.stop_event.is_set() and generation == self._mp_session_generation:
        try:
            sock, addr = listener.accept()
        except socket.timeout:
            continue
        except OSError:
            break
        except Exception:
            if not self.running or self.stop_event.is_set():
                break
            continue
        worker = None
        try:
            sock.settimeout(15)
            worker = threading.Thread(target=self._server_peer_worker, args=(sock, addr),
                                      name="PETZhu-MP-Peer", daemon=True)
            with self._mp_peer_workers_lock_v50:
                self._mp_peer_worker_threads_v50.add(worker)
                self._mp_peer_worker_sockets_v50.add(sock)
                self._mp_peer_socket_generations[id(sock)] = generation
            worker.start()
        except Exception:
            with self._mp_peer_workers_lock_v50:
                if worker is not None:
                    self._mp_peer_worker_threads_v50.discard(worker)
                self._mp_peer_worker_sockets_v50.discard(sock)
                self._mp_peer_socket_generations.pop(id(sock), None)
            try: sock.close()
            except Exception: pass


_PETZhuMultiplayer._accept_loop = _petzhu_mp_accept_loop_lifecycle_v50


def _petzhu_mp_join_worker_generation_v50(self, generation):
    sock = None
    stream = None
    send_lock = threading.Lock()
    _petzhu_mp_generation_init_v50(self)
    try:
        sock = socket.create_connection((self.host, self.port), timeout=12)
        if (generation != self._mp_session_generation or not self.running
                or self.stop_event.is_set()):
            try: sock.close()
            except Exception: pass
            return
        with self.lock:
            if generation != self._mp_session_generation or not self.running:
                try: sock.close()
                except Exception: pass
                return
            self._pending_client_socket_v50 = sock
        # Keep a handshake timeout until the welcome packet is fully read. A silent endpoint
        # must not leave a daemon worker blocked indefinitely before client_socket is registered.
        sock.settimeout(12)
        _petzhu_mp_send_socket(sock, {"type": "hello", "key": self.room_key, "meta": self._local_meta}, send_lock)
        stream = sock.makefile("rb")
        first = _petzhu_mp_read_json_line(stream)
        if generation != self._mp_session_generation or not self.running or self.stop_event.is_set():
            return
        if first.get("type") == "reject":
            raise ConnectionError(str(first.get("reason", "房间拒绝了连接")))
        if first.get("type") != "welcome":
            raise ConnectionError("房主返回了无法识别的数据")
        with self.lock:
            if generation != self._mp_session_generation or not self.running or self.stop_event.is_set():
                return
            sock.settimeout(None)
            self.client_socket, self.client_stream, self.write_lock = sock, stream, send_lock
            self._pending_client_socket_v50 = None
            # Commit handshake state atomically with the generation check. If stop() wins the
            # lock first, no old roster or welcome event can leak into the next room.
            self._load_roster(first.get("members", []), first.get("states", {}))
            self.events.put({"type": "welcome", "members": first.get("members", [])})
            self._set_status("已连接，正在等待房间成员完成资源检查……")
        self._client_read_loop(sock, stream)
    except Exception as exc:
        if generation == getattr(self, "_mp_session_generation", -1):
            if not getattr(self, "_manual_stop", False) and not self.stop_event.is_set():
                self.connected = False
                self.running = False
                self.mode = "offline"
                self._set_status("连接失败：%s" % str(exc))
    finally:
        if stream is not None:
            try: stream.close()
            except Exception: pass
        if sock is not None:
            try: _petzhu_mp_forget_socket(sock)
            except Exception: pass
            try: sock.shutdown(socket.SHUT_RDWR)
            except Exception: pass
            try: sock.close()
            except Exception: pass
        with self.lock:
            if getattr(self, "client_socket", None) is sock:
                self.client_socket = None
                self.client_stream = None
            if getattr(self, "_pending_client_socket_v50", None) is sock:
                self._pending_client_socket_v50 = None
        if getattr(self, "client_thread", None) is threading.current_thread():
            self.client_thread = None


def _petzhu_mp_join_room_lifecycle_v50(self, code, name=None):
    parts = str(code or "").strip().rsplit(":", 2)
    if len(parts) != 3:
        raise ValueError("连接码格式应为 IP:端口:邀请码")
    host, port_text, key = parts[0].strip().strip("[]"), parts[1].strip(), parts[2].strip().lower()
    try:
        port = int(port_text)
    except Exception:
        raise ValueError("连接码里的端口无效")
    if not host or not (1 <= port <= 65535) or not re.fullmatch(r"[0-9a-f]{16}", key):
        raise ValueError("连接码无效，请完整复制房主显示的连接码")

    self.stop(notify=False, quiet=True)
    _petzhu_mp_generation_init_v50(self)
    generation = self._mp_session_generation
    self.mode = "client"
    self.stop_event.clear()
    self._manual_stop = False
    self.local_id = uuid.uuid4().hex[:12]
    self.host, self.port, self.room_key = host, port, key
    self.room_code = "%s:%d:%s" % (host, port, key)
    self._local_meta = self._build_local_meta(name)
    self._local_meta.update({"id": self.local_id, "name": self.local_name, "is_host": False})
    self.running = True
    self.connected = False
    self._set_status("正在连接房主并同步桌宠资源……")
    worker = threading.Thread(target=_petzhu_mp_join_worker_generation_v50,
                               args=(self, generation), name="PETZhu-MP-Join", daemon=True)
    self.client_thread = worker
    worker.start()


_PETZhuMultiplayer.join_room = _petzhu_mp_join_room_lifecycle_v50



# PETZhu v48: native Windows API/联机 outer-frame first-paint theme fix.
# The DWM caption/border colors are now set while the API Toplevel is withdrawn,
# before the initial deiconify, rather than relying on Tk client-area bg alone.


# ============================================================
# PETZhu v51：联机合唱无缝切歌，连续保留摇摆相位
# - 歌曲边界不再进入 switching/awaiting_switch 状态或设置人为等待。
# - 所有成员根据各自当前曲目的节拍边界立即切到下一首；房主消息只作权威校验/纠偏。
# - 变更 BPM 时将当前摇摆相位映射到新 BPM，避免动画重置或相位跳变。
# ============================================================

_PETZHU_CHOIR_V51_PREVIOUS_PLAYBACK_TICK = _petzhu_choir_playback_tick
_PETZHU_CHOIR_V51_PREVIOUS_PACKET_HANDLER = _petzhu_mp_handle_choir_packet
_PETZHU_CHOIR_SWITCH_DELAY_V39 = 0.0


def _petzhu_choir_swing_anchor_v51(session, old_song_data, new_song_data, boundary_mono):
    """Return an animation clock anchor whose phase matches the outgoing song at the boundary."""
    try:
        boundary_perf = time.perf_counter() + (float(boundary_mono) - time.monotonic())
    except Exception:
        boundary_perf = time.perf_counter()
    old_anchor = 0.0
    try:
        old_anchor = float(session.get("anim_start_perf", 0.0) or 0.0)
    except Exception:
        old_anchor = 0.0
    try:
        old_bpm = max(1.0, min(400.0, float(old_song_data.get("bpm", 128) or 128)))
    except Exception:
        old_bpm = 128.0
    try:
        new_bpm = max(1.0, min(400.0, float(new_song_data.get("bpm", 128) or 128)))
    except Exception:
        new_bpm = 128.0
    old_cycle = max(0.20, 120.0 / old_bpm)
    new_cycle = max(0.20, 120.0 / new_bpm)
    if old_anchor > 0.0:
        phase = ((boundary_perf - old_anchor) % old_cycle) / old_cycle
    else:
        phase = 0.0
    # Preserve the deformation frame phase at the exact musical boundary, even when BPM changes.
    return boundary_perf - phase * new_cycle


def _petzhu_choir_switch_song_local_v51(app, index, delay=None, boundary_mono=None):
    """Switch scores on a musical boundary without stopping the singing animation."""
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return False
    playlist = _petzhu_choir_playlist_v39(session)
    try:
        index = int(index)
    except Exception:
        return False
    if index < 0 or index >= len(playlist):
        return False

    current_index = int(session.get("song_index", -1) or 0)
    if current_index == index and session.get("status") == "playing":
        # The server's song_switch often arrives after this client has already advanced locally.
        # It is an acknowledgement, not an instruction to restart the same song.
        return True

    old_song = session.get("song_data", {})
    if not isinstance(old_song, dict):
        old_song = {}
    now_mono = time.monotonic()
    if boundary_mono is None:
        if session.get("status") == "playing":
            try:
                old_bpm = max(50.0, min(240.0, float(old_song.get("bpm", 128) or 128)))
                old_step_sec = 60.0 / old_bpm / 4.0
                old_steps = max(1, min(256, int(old_song.get("steps", 256) or 256)))
                old_start_step = max(0, int(session.get("start_step", 0) or 0))
                boundary_mono = float(session.get("start_mono", now_mono) or now_mono) + max(0, old_steps - old_start_step) * old_step_sec
            except Exception:
                boundary_mono = now_mono
        else:
            # Legacy awaiting_switch sessions can recover immediately, but without a countdown.
            boundary_mono = now_mono
    try:
        boundary_mono = float(boundary_mono)
        if not math.isfinite(boundary_mono):
            boundary_mono = now_mono
    except Exception:
        boundary_mono = now_mono

    old_after = getattr(app, "_choir_after_id", None)
    if old_after is not None:
        try:
            app.root.after_cancel(old_after)
        except Exception:
            pass
    app._choir_after_id = None

    # End only the outgoing song's scheduled sounds; do not clear the singing visual state.
    _petzhu_choir_stop_audio(app)
    if not _petzhu_choir_playlist_set_current_v39(session, index):
        return False
    new_song = session.get("song_data", {})
    if not isinstance(new_song, dict):
        new_song = {}
    swing_anchor = _petzhu_choir_swing_anchor_v51(session, old_song, new_song, boundary_mono)

    session["status"] = "playing"
    session["has_started"] = True
    session["start_mono"] = boundary_mono
    session["start_step"] = 0
    session["next_step"] = 0
    session["current_step"] = 0
    session["last_abs_step"] = -1
    session["pause_step"] = 0
    session["anim_start_perf"] = swing_anchor
    session["switch_started_at_v51"] = boundary_mono
    session.pop("_choir_authoritative_next_index_v51", None)
    # A new song has new note keys, while the continuous animation clock is intentionally kept.
    session["_choir_mouth_note_key"] = None
    session["_choir_mouth_loop_index"] = None
    session["_choir_mouth_cache_key_v36"] = None
    session["_choir_mouth_loop_index_v36"] = None
    app._choir_playing = True
    app._choir_paused = False
    app._choir_anim_started_perf = swing_anchor
    # Deliberately do not set song_mouth_on=False, clear the swing anchor, or call a countdown.
    try:
        app._update_sprite()
    except Exception:
        pass
    try:
        _petzhu_choir_set_status(app, "正在合唱第 %d/%d 首：《%s》" % (
            index + 1, len(playlist), str(session.get("song_name", "歌曲"))[:80]))
        _petzhu_choir_refresh_ui(app)
    except Exception:
        pass
    # Run the next track's first due musical step immediately, using the previous track's exact end.
    _petzhu_choir_playback_tick_v51(app)
    return True


def _petzhu_choir_playback_tick_v51(app):
    """Playback ticker with a continuous boundary between playlist items."""
    app._choir_after_id = None
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict) or session.get("status") != "playing" or getattr(app, "_closing", False):
        return
    try:
        playlist = _petzhu_choir_playlist_v39(session)
        if not playlist:
            _petzhu_choir_finish_playlist_v39(app, send_packet=True)
            return
        song_index = max(0, min(len(playlist) - 1, int(session.get("song_index", 0) or 0)))
        if not isinstance(session.get("song_data"), dict):
            if not _petzhu_choir_playlist_set_current_v39(session, song_index):
                _petzhu_choir_finish_playlist_v39(app, send_packet=True)
                return
        song_data = session.get("song_data", {})
        bpm = max(50.0, min(240.0, float(song_data.get("bpm", 128) or 128)))
        step_seconds = 60.0 / bpm / 4.0
        start_mono = float(session.get("start_mono", time.monotonic()) or time.monotonic())
        now = time.monotonic()
        if now < start_mono:
            app._choir_after_id = app.root.after(
                max(1, int((start_mono - now) * 1000)),
                lambda a=app: _petzhu_choir_playback_tick(a))
            return
        start_step = max(0, int(session.get("start_step", 0) or 0))
        absolute_step = start_step + max(0, int((now - start_mono) / step_seconds))
        steps = max(1, min(256, int(song_data.get("steps", 256) or 256)))
        if absolute_step >= steps:
            # Compute the exact scheduled end instead of using callback-arrival time, so the
            # outgoing song's slight UI timer jitter does not get accumulated in later tracks.
            boundary_mono = start_mono + max(0, steps - start_step) * step_seconds
            manager = getattr(app, "_mp", None)
            is_owner = (manager is not None and
                        str(session.get("owner_id", "")) == str(getattr(manager, "local_id", "")))
            next_index = song_index + 1
            if next_index >= len(playlist):
                if bool(session.get("loop", False)):
                    next_index = 0
                else:
                    _petzhu_choir_finish_playlist_v39(app, send_packet=is_owner)
                    return
            if is_owner and manager is not None:
                try:
                    manager.send_choir("song_switch", {
                        "session_id": session.get("id"),
                        "playlist_index": next_index,
                        "delay": 0.0,
                        "loop": bool(session.get("loop", False)),
                    })
                except Exception:
                    pass
            # Clients also advance from their preloaded playlist at their own precise beat boundary;
            # they never stop in awaiting_switch waiting for network latency.
            _petzhu_choir_switch_song_local_v51(app, next_index, delay=0.0, boundary_mono=boundary_mono)
            return

        step = absolute_step
        last_abs = int(session.get("last_abs_step", start_step - 1))
        if absolute_step > last_abs:
            _petzhu_choir_play_voice_step(app, session, step, absolute_step=absolute_step)
            session["last_abs_step"] = absolute_step
            session["next_step"] = step + 1
        session["current_step"] = step
        next_boundary = start_mono + (int((now - start_mono) / step_seconds) + 1) * step_seconds
        delay_ms = max(1, min(20, int(round((next_boundary - time.monotonic()) * 1000.0))))
        app._choir_after_id = app.root.after(delay_ms, lambda a=app: _petzhu_choir_playback_tick(a))
    except Exception as exc:
        session["status"] = "finished"
        app._choir_playing = False
        app._choir_paused = False
        _petzhu_choir_stop_audio(app)
        _petzhu_choir_set_status(app, "合唱播放遇到错误，已停止：%s" % str(exc)[:120])
        _petzhu_choir_refresh_ui(app)


_petzhu_choir_playback_tick_v39 = _petzhu_choir_playback_tick_v51
_petzhu_choir_playback_tick = _petzhu_choir_playback_tick_v51
_petzhu_choir_switch_song_local_v39 = _petzhu_choir_switch_song_local_v51


def _petzhu_choir_packet_handler_v51(app, packet):
    if isinstance(packet, dict) and str(packet.get("action", "") or "")[:32] == "song_switch":
        manager = getattr(app, "_mp", None)
        if manager is None:
            return
        data = packet.get("data", {}) if isinstance(packet.get("data"), dict) else {}
        session_id = str(data.get("session_id", "") or "")[:32]
        sender = str(packet.get("peer_id", "") or "")[:32]
        session = getattr(app, "_choir_session", None)
        if not isinstance(session, dict) or session_id != str(session.get("id", "")):
            return
        if sender != str(session.get("owner_id", "")):
            return
        try:
            index = int(data.get("playlist_index", -1))
        except Exception:
            return
        playlist = _petzhu_choir_playlist_v39(session)
        if index < 0 or index >= len(playlist):
            return
        session["loop"] = bool(data.get("loop", session.get("loop", False)))
        current_index = int(session.get("song_index", 0) or 0)
        if session.get("status") == "playing":
            if index == current_index:
                # Confirmation for an automatic local transition already applied; never restart it.
                return
            # The local timer knows the musical boundary more precisely than packet arrival.
            # If the boundary has passed, wake the ticker now; otherwise let it switch at that boundary.
            song = session.get("song_data", {})
            try:
                bpm = max(50.0, min(240.0, float(song.get("bpm", 128) or 128)))
                step_seconds = 60.0 / bpm / 4.0
                steps = max(1, min(256, int(song.get("steps", 256) or 256)))
                start_step = max(0, int(session.get("start_step", 0) or 0))
                end_mono = float(session.get("start_mono", time.monotonic()) or time.monotonic()) + max(0, steps - start_step) * step_seconds
            except Exception:
                end_mono = time.monotonic()
            expected = current_index + 1
            if expected >= len(playlist):
                expected = 0 if bool(session.get("loop", False)) else -1
            if index == expected:
                session["_choir_authoritative_next_index_v51"] = index
                if time.monotonic() >= end_mono:
                    _petzhu_choir_playback_tick_v51(app)
            return
        if session.get("status") in ("awaiting_switch", "switching"):
            _petzhu_choir_switch_song_local_v51(app, index, delay=0.0, boundary_mono=time.monotonic())
        return
    return _PETZHU_CHOIR_V51_PREVIOUS_PACKET_HANDLER(app, packet)


_petzhu_mp_handle_choir_packet = _petzhu_choir_packet_handler_v51



# ============================================================
# PETZhu 联机 v52：解散后关闭房主界面、本地曲库上限 30、重开歌单同步索引
# ============================================================

# --- 1) 房主解散成功后关闭本机合唱管理窗口 ----------------------
_PETZHU_CHOIR_V52_PREVIOUS_DISBAND = _petzhu_choir_disband

def _petzhu_choir_disband_v52(app):
    ui = getattr(app, "_choir_ui", None)
    win = ui.get("win") if isinstance(ui, dict) else None
    had_owner_session = isinstance(getattr(app, "_choir_session", None), dict)
    _PETZHU_CHOIR_V52_PREVIOUS_DISBAND(app)
    # The previous handler leaves the session intact when the confirmation is cancelled.
    # Close only after the owner actually disbanded/cleared their session.
    if had_owner_session and getattr(app, "_choir_session", None) is None:
        try:
            if win is not None and win.winfo_exists():
                win.destroy()
        except Exception:
            pass
        try:
            if getattr(app, "_choir_ui", None) is ui:
                app._choir_ui = None
        except Exception:
            pass

_petzhu_choir_disband = _petzhu_choir_disband_v52


# --- 2) 本地曲库最多保留最近使用/保存的 30 首不同乐谱 ----------
_PETZHU_CHOIR_LIBRARY_CAPACITY_V52 = 30
_PETZHU_CHOIR_V52_PREVIOUS_LIBRARY_ENTRIES = _petzhu_choir_library_entries_v36
_PETZHU_CHOIR_V52_PREVIOUS_LIBRARY_SAVE = _petzhu_choir_library_save_v36

def _petzhu_choir_library_trim_v52(app, entries):
    """Keep only the 30 most recently saved unique library entries and persist the manifest."""
    if not isinstance(entries, list):
        entries = []
    valid = []
    seen = set()
    for item in entries:
        if not isinstance(item, dict):
            continue
        sid = str(item.get("id", "") or "")
        if not re.fullmatch(r"[0-9a-f]{64}", sid) or sid in seen:
            continue
        seen.add(sid)
        valid.append(dict(item))
    valid.sort(key=lambda x: (float(x.get("updated", 0.0) or 0.0), str(x.get("name", ""))), reverse=True)
    kept = valid[:_PETZHU_CHOIR_LIBRARY_CAPACITY_V52]
    if len(valid) <= _PETZHU_CHOIR_LIBRARY_CAPACITY_V52 and len(valid) == len(entries):
        app._choir_library_entries_v36 = list(kept)
        return list(kept)

    base, manifest = _petzhu_choir_library_paths_v36(app)
    os.makedirs(base, exist_ok=True)
    temp_manifest = manifest + ".v52.tmp"
    with open(temp_manifest, "w", encoding="utf-8") as f:
        json.dump({"format": "PETZhu-Choir-Library", "version": 1, "songs": kept},
                  f, ensure_ascii=False, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(temp_manifest, manifest)

    kept_ids = {str(item.get("id", "")) for item in kept}
    # Remove score files that have just been evicted, so the limit applies to disk as well.
    for item in valid[_PETZHU_CHOIR_LIBRARY_CAPACITY_V52:]:
        sid = str(item.get("id", "") or "")
        if not re.fullmatch(r"[0-9a-f]{64}", sid) or sid in kept_ids:
            continue
        old_path = os.path.join(base, sid + ".json")
        try:
            if os.path.isfile(old_path):
                os.remove(old_path)
        except OSError:
            pass
    app._choir_library_entries_v36 = list(kept)
    try:
        app._choir_library_mtime_v36 = os.path.getmtime(manifest)
    except OSError:
        app._choir_library_mtime_v36 = None
    return list(kept)


def _petzhu_choir_library_entries_v52(app, force=False):
    entries = _PETZHU_CHOIR_V52_PREVIOUS_LIBRARY_ENTRIES(app, force=force)
    return _petzhu_choir_library_trim_v52(app, entries)


def _petzhu_choir_library_save_v52(app, song_name, song_data):
    result = _PETZHU_CHOIR_V52_PREVIOUS_LIBRARY_SAVE(app, song_name, song_data)
    # The underlying writer handles hash de-duplication and atomic score writes. Trim
    # after it commits so importing a pre-existing library with >30 entries is corrected too.
    _petzhu_choir_library_entries_v52(app, force=True)
    return result

_petzhu_choir_library_entries_v36 = _petzhu_choir_library_entries_v52
_petzhu_choir_library_save_v36 = _petzhu_choir_library_save_v52


# --- 3) Every fresh run explicitly starts all members on the same score index --------
_PETZHU_CHOIR_V52_PREVIOUS_START_FROM_UI = _petzhu_choir_start_from_ui
_PETZHU_CHOIR_V52_PREVIOUS_PACKET_HANDLER = _petzhu_mp_handle_choir_packet

def _petzhu_choir_start_from_ui_v52(app):
    manager = getattr(app, "_mp", None)
    session = getattr(app, "_choir_session", None)
    if not isinstance(session, dict):
        return _PETZHU_CHOIR_V52_PREVIOUS_START_FROM_UI(app)
    if manager is None or str(session.get("owner_id", "")) != str(getattr(manager, "local_id", "")):
        return

    playlist = _petzhu_choir_playlist_v39(session)
    ui = getattr(app, "_choir_ui", {}) or {}
    parent = ui.get("win") or getattr(app, "_api_win", None) or app.root
    if not playlist:
        messagebox.showinfo("合唱", "请先把至少一首歌曲加入歌单。", parent=parent)
        return
    current_status = str(session.get("status", "lobby") or "lobby")
    if current_status in ("playing", "countdown"):
        return
    is_resume = current_status == "paused"
    if is_resume:
        try:
            target_index = max(0, min(len(playlist) - 1, int(session.get("song_index", 0) or 0)))
        except Exception:
            target_index = 0
        start_step = max(0, int(session.get("pause_step", session.get("next_step", 0)) or 0))
    else:
        # A completed playlist always restarts from track 1, regardless of whether loop was
        # toggled after completion. Do not trust the stale song_index left on members.
        target_index = 0
        start_step = 0

    members = session.get("members", {})
    if not isinstance(members, dict):
        members = {}
    if any(isinstance(m, dict) and m.get("status") == "pending" for m in members.values()):
        messagebox.showinfo("合唱", "还有成员尚未接受邀请或完成乐谱下载，请等待全部邀请得到回复。", parent=parent)
        return
    accepted = [m for m in members.values() if isinstance(m, dict) and m.get("status") == "accepted"]
    if len(accepted) < 2:
        messagebox.showinfo("合唱", "至少需要发起者和一名已接受邀请的成员。", parent=parent)
        return

    if not _petzhu_choir_playlist_set_current_v39(session, target_index):
        messagebox.showerror("合唱", "无法定位歌单中的起始歌曲。", parent=parent)
        return
    local_member = members.get(str(manager.local_id), {})
    voices = _petzhu_choir_clean_voices(local_member.get("voices", {}), session.get("song_data")) \
        if isinstance(local_member, dict) else {}
    if not voices:
        messagebox.showinfo("合唱", "请先设置发起者自己的声部。", parent=parent)
        return

    if not is_resume:
        _petzhu_choir_stop_audio(app)
        session["current_step"] = -1
        session["next_step"] = 0
        session["last_abs_step"] = -1
        session["pause_step"] = 0
        session["start_step"] = 0
    else:
        session["current_step"] = start_step - 1
        session["next_step"] = start_step
        session["last_abs_step"] = start_step - 1

    loop_var = ui.get("loop_var") if isinstance(ui, dict) else None
    try:
        loop_enabled = bool(loop_var.get()) if loop_var is not None else bool(session.get("loop", False))
    except Exception:
        loop_enabled = bool(session.get("loop", False))
    session["loop"] = loop_enabled
    delay = 3.0
    if _petzhu_choir_local_start(app, start_step=start_step, delay=delay, loop=loop_enabled, start_at=None):
        manager.send_choir("start", {
            "session_id": session.get("id"),
            "start_step": start_step,
            "playlist_index": target_index,
            "loop": loop_enabled,
            "delay": delay,
            "song_name": session.get("song_name", ""),
        })
        _petzhu_choir_set_status(app, "合唱倒计时：3、2、1。所有成员将从第 %d 首同步开始。" % (target_index + 1))

_petzhu_choir_start_from_ui = _petzhu_choir_start_from_ui_v52


def _petzhu_mp_handle_choir_packet_v52(app, packet):
    if isinstance(packet, dict) and str(packet.get("action", "") or "")[:32] == "start":
        manager = getattr(app, "_mp", None)
        data = packet.get("data", {}) if isinstance(packet.get("data"), dict) else {}
        sender = str(packet.get("peer_id", "") or "")[:32]
        session_id = str(data.get("session_id", "") or "")[:32]
        session = getattr(app, "_choir_session", None)
        if (manager is None or not isinstance(session, dict)
                or session_id != str(session.get("id", ""))
                or sender != str(session.get("owner_id", ""))):
            return
        playlist = _petzhu_choir_playlist_v39(session)
        if not playlist:
            return
        try:
            start_step = max(0, int(data.get("start_step", 0) or 0))
        except Exception:
            start_step = 0
        try:
            fallback_index = 0 if str(session.get("status", "")) in ("finished", "lobby") else int(session.get("song_index", 0) or 0)
            playlist_index = int(data.get("playlist_index", fallback_index))
        except Exception:
            playlist_index = 0
        if playlist_index < 0 or playlist_index >= len(playlist):
            return
        if str(session.get("status", "")) in ("playing", "countdown"):
            # Ignore stale/duplicate start commands so they cannot restart the music under a live mouth animation.
            return
        # Crucial: the old protocol sent only start_step, leaving members on the final song of
        # the previous run. Align song_data/song_index before the ordinary synchronized countdown.
        _petzhu_choir_stop_audio(app)
        if not _petzhu_choir_playlist_set_current_v39(session, playlist_index):
            return
        session["loop"] = bool(data.get("loop", session.get("loop", False)))
        session["current_step"] = start_step - 1
        session["next_step"] = start_step
        session["last_abs_step"] = start_step - 1
        session["start_step"] = start_step
        session["pause_step"] = start_step
        try:
            app.song_mouth_on = False
            app._song_vocal_key = None
            app._song_vocal_short_close_at = 0.0
        except Exception:
            pass
        return _PETZHU_CHOIR_V52_PREVIOUS_PACKET_HANDLER(app, packet)
    return _PETZHU_CHOIR_V52_PREVIOUS_PACKET_HANDLER(app, packet)

_petzhu_mp_handle_choir_packet = _petzhu_mp_handle_choir_packet_v52



# ============================================================
# PETZhu v54: hard input caps for relay speech.
# - 84 total typed characters, with a separate maximum of 48 Han characters.
# - Tk validation prevents extra characters being entered, not merely sent.
# - Oversized paste operations are truncated to the longest accepted prefix.
# ============================================================
_PETZHU_MP_RELAY_V54_MAX_TOTAL_CHARS = 84
_PETZHU_MP_RELAY_V54_MAX_HAN_CHARS = 48
_PETZHU_MP_RELAY_V54_PREVIOUS_VALIDATE = _petzhu_mp_relay_validate
_PETZHU_MP_RELAY_V54_PREVIOUS_LOCAL_TOGGLE = _petzhu_mp_toggle_local_relay
_PETZHU_MP_RELAY_V54_PREVIOUS_ROOM_PLACEHOLDER = _petzhu_mp_set_room_chat_placeholder
_PETZHU_MP_RELAY_V54_PREVIOUS_INIT = MaoPet.__init__
_PETZHU_MP_RELAY_V54_PREVIOUS_SHOW_API = MaoPet.show_api_config


def _petzhu_mp_relay_v54_is_han(ch):
    if not ch:
        return False
    n = ord(ch)
    return (
        0x3400 <= n <= 0x4DBF or
        0x4E00 <= n <= 0x9FFF or
        0xF900 <= n <= 0xFAFF or
        0x20000 <= n <= 0x2FA1F or
        0x30000 <= n <= 0x3134F
    )


def _petzhu_mp_relay_v54_han_count(value):
    return sum(1 for ch in str(value or "") if _petzhu_mp_relay_v54_is_han(ch))


def _petzhu_mp_relay_v54_fits(value):
    value = str(value or "")
    han_count = _petzhu_mp_relay_v54_han_count(value)
    other_count = len(value) - han_count
    return (other_count <= _PETZHU_MP_RELAY_V54_MAX_TOTAL_CHARS
            and han_count <= _PETZHU_MP_RELAY_V54_MAX_HAN_CHARS)


def _petzhu_mp_relay_v54_clip(value):
    """Return the longest prefix respecting both limits, preserving typed order."""
    value = str(value or "")
    result = []
    han_count = 0
    other_count = 0
    for ch in value:
        is_han = _petzhu_mp_relay_v54_is_han(ch)
        if is_han and han_count >= _PETZHU_MP_RELAY_V54_MAX_HAN_CHARS:
            break
        if not is_han and other_count >= _PETZHU_MP_RELAY_V54_MAX_TOTAL_CHARS:
            break
        result.append(ch)
        if is_han:
            han_count += 1
        else:
            other_count += 1
    return "".join(result)


def _petzhu_mp_relay_validate_v54(value):
    value = str(value or "").replace("\r", " ").replace("\n", " ").strip()
    if not value:
        return False, "请输入要转述的话。", value
    if not _petzhu_mp_relay_v54_fits(value):
        return False, "转述最多 84 个非汉字字符（英文、数字、标点等），中文汉字最多 48 个；达到各自上限后无法继续输入相应字符。", value
    return True, "", value


# Rebind the validation function used by all relay send paths.
_petzhu_mp_relay_validate = _petzhu_mp_relay_validate_v54


def _petzhu_mp_relay_v54_mode_enabled(app, mode):
    if mode == "local":
        return bool(getattr(app, "_mp_local_relay_mode", False))
    return bool(getattr(app, "_mp_room_relay_mode", False))


def _petzhu_mp_relay_v54_install_entry_limit(app, entry, mode):
    """Install live validation on an Entry. Normal chat remains unrestricted."""
    try:
        if entry is None or not entry.winfo_exists():
            return False
        existing = getattr(entry, "_petzhu_mp_relay_v54_mode", None)
        if existing == mode and str(entry.cget("validate")) == "key":
            return True

        def validate_proposed(proposed, _app=app, _entry=entry, _mode=mode):
            try:
                if not _petzhu_mp_relay_v54_mode_enabled(_app, _mode):
                    return True
                return _petzhu_mp_relay_v54_fits(proposed)
            except Exception:
                # Fail open only if a widget is being destroyed or Tk is shutting down;
                # the send-time validator remains as a second guard.
                return True

        command = entry.register(validate_proposed)
        entry.configure(validate="key", validatecommand=(command, "%P"))
        entry._petzhu_mp_relay_v54_mode = mode
        entry._petzhu_mp_relay_v54_validate_command = command
        entry._petzhu_mp_relay_v54_validate_callback = validate_proposed

        def paste_limited(event=None, _app=app, _entry=entry, _mode=mode):
            # Return None in ordinary chat so Tk's normal clipboard binding proceeds.
            if not _petzhu_mp_relay_v54_mode_enabled(_app, _mode):
                return None
            try:
                pasted = str(_entry.clipboard_get())
            except Exception:
                return "break"
            pasted = pasted.replace("\r\n", " ").replace("\r", " ").replace("\n", " ")
            try:
                current = str(_entry.get() or "")
                try:
                    sel_start = int(_entry.index("sel.first"))
                    sel_end = int(_entry.index("sel.last"))
                    has_selection = True
                except Exception:
                    sel_start = sel_end = int(_entry.index("insert"))
                    has_selection = False
                base = current[:sel_start] + current[sel_end:]
                accepted = []
                han_count = _petzhu_mp_relay_v54_han_count(base)
                other_count = len(base) - han_count
                # Count Han and non-Han characters independently, including in mixed text.
                for ch in pasted:
                    is_han = _petzhu_mp_relay_v54_is_han(ch)
                    if is_han and han_count >= _PETZHU_MP_RELAY_V54_MAX_HAN_CHARS:
                        break
                    if not is_han and other_count >= _PETZHU_MP_RELAY_V54_MAX_TOTAL_CHARS:
                        break
                    accepted.append(ch)
                    if is_han:
                        han_count += 1
                    else:
                        other_count += 1
                if not accepted:
                    return "break"
                if has_selection:
                    _entry.delete(sel_start, sel_end)
                    insert_at = sel_start
                else:
                    insert_at = sel_start
                _entry.insert(insert_at, "".join(accepted))
            except Exception:
                # Let the normal validator reject an oversized paste if clipboard handling fails.
                return "break"
            return "break"

        # Widget-level virtual paste handler runs before the default class handler.
        entry.bind("<<Paste>>", paste_limited, add="+")
        return True
    except Exception:
        return False


def _petzhu_mp_relay_v54_clip_entry_if_needed(app, entry, mode):
    try:
        if entry is None or not entry.winfo_exists() or not _petzhu_mp_relay_v54_mode_enabled(app, mode):
            return
        current = str(entry.get() or "")
        clipped = _petzhu_mp_relay_v54_clip(current)
        if clipped != current:
            try:
                insert_pos = int(entry.index("insert"))
            except Exception:
                insert_pos = len(current)
            entry.delete(0, "end")
            entry.insert(0, clipped)
            entry.icursor(min(insert_pos, len(clipped)))
    except Exception:
        pass


def _petzhu_mp_relay_v54_init(self, *args, **kwargs):
    result = _PETZHU_MP_RELAY_V54_PREVIOUS_INIT(self, *args, **kwargs)
    try:
        _petzhu_mp_relay_v54_install_entry_limit(self, getattr(self, "entry", None), "local")
    except Exception:
        pass
    return result


def _petzhu_mp_relay_v54_show_api(self, *args, **kwargs):
    result = _PETZHU_MP_RELAY_V54_PREVIOUS_SHOW_API(self, *args, **kwargs)
    try:
        ui = getattr(self, "_mp_ui", {}) or {}
        entry = ui.get("chat_entry")
        if _petzhu_mp_relay_v54_install_entry_limit(self, entry, "room"):
            _petzhu_mp_relay_v54_clip_entry_if_needed(self, entry, "room")
    except Exception:
        pass
    return result


def _petzhu_mp_relay_v54_local_toggle(app):
    result = _PETZHU_MP_RELAY_V54_PREVIOUS_LOCAL_TOGGLE(app)
    try:
        _petzhu_mp_relay_v54_install_entry_limit(app, getattr(app, "entry", None), "local")
        _petzhu_mp_relay_v54_clip_entry_if_needed(app, getattr(app, "entry", None), "local")
    except Exception:
        pass
    return result


def _petzhu_mp_relay_v54_room_placeholder(app, entry):
    result = _PETZHU_MP_RELAY_V54_PREVIOUS_ROOM_PLACEHOLDER(app, entry)
    try:
        _petzhu_mp_relay_v54_install_entry_limit(app, entry, "room")
        _petzhu_mp_relay_v54_clip_entry_if_needed(app, entry, "room")
    except Exception:
        pass
    return result


# Explicitly describe the hard caps in the room-relay UI. This hint is visible while
# relay mode is active; it no longer suggests the previous soft send-time limit.
def _petzhu_mp_relay_v54_show_api_hint(self, *args, **kwargs):
    result = _PETZHU_MP_RELAY_V54_PREVIOUS_SHOW_API(self, *args, **kwargs)
    try:
        ui = getattr(self, "_mp_ui", {}) or {}
        hint = ui.get("relay_hint")
        if hint is not None and hint.winfo_exists():
            hint.configure(text="原样转述，不调用 API；英文、数字、标点等非汉字字符最多 84 个，中文汉字最多 48 个，达到各自上限后无法继续输入相应字符")
        entry = ui.get("chat_entry")
        if entry is not None:
            _petzhu_mp_relay_v54_install_entry_limit(self, entry, "room")
            _petzhu_mp_relay_v54_clip_entry_if_needed(self, entry, "room")
    except Exception:
        pass
    return result


MaoPet.__init__ = _petzhu_mp_relay_v54_init
MaoPet.show_api_config = _petzhu_mp_relay_v54_show_api_hint
_petzhu_mp_toggle_local_relay = _petzhu_mp_relay_v54_local_toggle
_petzhu_mp_set_room_chat_placeholder = _petzhu_mp_relay_v54_room_placeholder



# ============================================================
# PETZhu v55: don't show literal grey placeholder while an input Entry keeps focus.
# After relay send, the Entry is cleared but remains focused; previous placeholder
# helpers inserted "让xx转达..." immediately and left the caret before that grey text.
# Keep focused fields genuinely empty until the user moves focus away.
# ============================================================
def _petzhu_mp_v55_entry_has_focus(entry):
    try:
        if entry is None or not entry.winfo_exists():
            return False
    except Exception:
        return False
    try:
        focused = entry.focus_get()
        if focused is entry:
            return True
        if focused is not None and str(focused) == str(entry):
            return True
    except Exception:
        pass
    return False


_PETZHU_MP_V55_PREVIOUS_LOCAL_SYNC = _petzhu_mp_sync_local_placeholder
_PETZHU_MP_V55_PREVIOUS_ROOM_PLACEHOLDER = _petzhu_mp_set_room_chat_placeholder


def _petzhu_mp_sync_local_placeholder_v55(app):
    entry = getattr(app, "entry", None)
    if entry is None:
        return
    try:
        old_placeholder = str(getattr(app, "placeholder", "") or "")
        new_placeholder = (
            "让%s转达..." % str(getattr(app, "pet_name", "珠珠") or "珠珠")[:24]
            if getattr(app, "_mp_local_relay_mode", False)
            else str(getattr(app, "_mp_local_normal_placeholder", "和珠珠说话…") or "和珠珠说话…")
        )
        _petzhu_mp_remember_placeholder(entry, old_placeholder)
        _petzhu_mp_remember_placeholder(entry, new_placeholder)
        entry._petzhu_mp_local_placeholder_text = new_placeholder
        app._mp_local_placeholder_display = new_placeholder
        app.placeholder = new_placeholder

        if _petzhu_mp_v55_entry_has_focus(entry):
            # A focused Entry is actively being edited: never insert any hint string.
            current = str(entry.get() or "")
            if _petzhu_mp_is_placeholder(current, app, entry, room=False):
                entry.delete(0, "end")
            entry._petzhu_mp_placeholder_active = False
            try:
                light = bool(getattr(app, "_context_palette_light", False))
                entry.configure(fg=(getattr(app, "C_BG", "#1e2a3a") if light
                                    else getattr(app, "C_FG", "#ffffff")))
            except Exception:
                pass
            return
    except Exception:
        # Fall through to the original helper for its established recovery logic.
        pass
    return _PETZHU_MP_V55_PREVIOUS_LOCAL_SYNC(app)


def _petzhu_mp_set_room_chat_placeholder_v55(app, entry):
    if entry is None:
        return
    try:
        new_placeholder = (
            "让%s转达..." % str(getattr(app, "pet_name", "珠珠") or "珠珠")[:24]
            if getattr(app, "_mp_room_relay_mode", False)
            else "群聊消息..."
        )
        old_placeholder = str(getattr(entry, "_petzhu_mp_placeholder_text", "") or "")
        _petzhu_mp_remember_placeholder(entry, old_placeholder)
        _petzhu_mp_remember_placeholder(entry, new_placeholder)
        entry._petzhu_mp_placeholder_text = new_placeholder
        entry._petzhu_mp_room_placeholder_text = new_placeholder
        app._mp_room_placeholder_display = new_placeholder

        if _petzhu_mp_v55_entry_has_focus(entry):
            # Do not gray the next characters typed after sending a relay message.
            current = str(entry.get() or "")
            if _petzhu_mp_is_placeholder(current, app, entry, room=True):
                entry.delete(0, "end")
            entry._petzhu_mp_placeholder_active = False
            try:
                light = bool(getattr(app, "_context_palette_light", False))
                entry.configure(fg=("#1e2a3a" if light else "#e8f0ff"))
            except Exception:
                pass
            return
    except Exception:
        # Use the existing implementation if the focus-aware path cannot be applied.
        pass
    return _PETZHU_MP_V55_PREVIOUS_ROOM_PLACEHOLDER(app, entry)


def _petzhu_mp_on_submit_relay_v55(self, event=None):
    if not getattr(self, "_mp_local_relay_mode", False):
        return _PETZHU_MP_RELAY_ORIG_SUBMIT(self, event)
    entry = getattr(self, "entry", None)
    try:
        value = str(entry.get() or "").strip() if entry is not None else ""
    except Exception:
        value = ""
    if not value or _petzhu_mp_is_placeholder(value, self, entry, room=False):
        return "break"
    if _petzhu_mp_start_relay(self, value):
        try:
            entry.delete(0, "end")
            entry._petzhu_mp_placeholder_active = False
            # The focus-aware helper leaves the field empty and uses the normal text
            # color if the caret is still here; it restores a hint only after focus-out.
            _petzhu_mp_sync_local_placeholder(self)
        except Exception:
            pass
    return "break"


# Existing callbacks resolve these module globals when they run, so both local and
# room send paths, periodic theme refreshes, and mode toggles share the focus-aware rule.
_petzhu_mp_sync_local_placeholder = _petzhu_mp_sync_local_placeholder_v55
_petzhu_mp_sync_local_placeholder_v31 = _petzhu_mp_sync_local_placeholder_v55
_petzhu_mp_sync_local_placeholder_v32 = _petzhu_mp_sync_local_placeholder_v55
_petzhu_mp_set_room_chat_placeholder = _petzhu_mp_set_room_chat_placeholder_v55
_petzhu_mp_set_room_chat_placeholder_v31 = _petzhu_mp_set_room_chat_placeholder_v55
_petzhu_mp_set_room_chat_placeholder_v32 = _petzhu_mp_set_room_chat_placeholder_v55
_petzhu_mp_on_submit_relay = _petzhu_mp_on_submit_relay_v55
_PETZHU_MP_V31_ORIGINAL_SUBMIT = _petzhu_mp_on_submit_relay_v55


# ============================================================
# PETZhu v56: API/联机面板在首次显示前确定最终配色。
# - 首次打开前快照当前明暗主题与主题色相，所有控件在隐藏状态下统一落色。
# - API/联机浅色控件（尤其成员 Listbox、Labelframe 标题）不再保留深色默认值。
# - Windows 标题栏/边框使用同一主题色相，不再固定为原始粉色。
# - 后续切换明暗/色相主题时，也重刷 API 面板及系统标题栏。
# ============================================================

def _petzhu_api_v56_make_palette(app):
    light = bool(getattr(app, "_context_palette_light", False))
    try:
        hue = int(_PETZHU_THEME_HUE_STATE.get("hue", _PETZHU_THEME_HUE_DEFAULT)) % 360
    except Exception:
        hue = int(_PETZHU_THEME_HUE_DEFAULT) % 360
    # Use the same source colors as the existing API light-theme painter, but resolve
    # their final hue now, before the API window is mapped for its first visible frame.
    if light:
        shift = _petzhu_shift_theme_color
        return {
            "light": True,
            "hue": hue,
            "window": shift("#fff0f6"),
            "surface": shift("#fceaf2"),
            "button": shift("#f0bfd6"),
            "active": shift("#d96fa8"),
            "edge": shift("#e6a1bf"),
            "heading": shift("#b52d70"),
            "fg": "#1e2a3a",
            "muted": "#78566a",
            "white": "#ffffff",
        }
    return {
        "light": False,
        "hue": hue,
        "window": str(getattr(app, "C_BG", "#1e2a3a") or "#1e2a3a"),
        "surface": str(getattr(app, "C_TEXT_BG", "#111a26") or "#111a26"),
        "button": "#2a3a4a",
        "active": str(getattr(app, "C_BORDER", "#3f5b78") or "#3f5b78"),
        "edge": str(getattr(app, "C_BORDER", "#7fb1e8") or "#7fb1e8"),
        "heading": str(getattr(app, "C_FG", "#e8f0ff") or "#e8f0ff"),
        "fg": str(getattr(app, "C_FG", "#e8f0ff") or "#e8f0ff"),
        "muted": "#a9bdd4",
        "white": "#ffffff",
    }


def _petzhu_api_v56_snapshot_palette(app):
    """Capture the palette once at the beginning of show_api_config()."""
    palette = _petzhu_api_v56_make_palette(app)
    try:
        app._petzhu_api_palette_snapshot_v56 = dict(palette)
    except Exception:
        pass
    return palette


def _petzhu_api_v56_palette_for(app):
    try:
        snap = getattr(app, "_petzhu_api_palette_snapshot_v56", None)
        if isinstance(snap, dict) and "window" in snap:
            return snap
    except Exception:
        pass
    return _petzhu_api_v56_make_palette(app)


def _petzhu_api_force_light_palette_v56(app, win):
    """Force every API descendant to the already-resolved light palette while hidden."""
    try:
        if win is None or not win.winfo_exists():
            return
    except Exception:
        return
    palette = _petzhu_api_v56_palette_for(app)
    if not palette.get("light"):
        return
    window_bg = palette["window"]
    surface_bg = palette["surface"]
    button_bg = palette["button"]
    active_bg = palette["active"]
    edge = palette["edge"]
    fg = palette["fg"]
    white = palette["white"]

    try:
        widgets = list(_petzhu_api_walk_widgets_v47(win))
    except Exception:
        widgets = [win]

    for widget in widgets:
        try:
            if not widget.winfo_exists():
                continue
            cls = str(widget.winfo_class())
            updates = {}
            if widget is win or cls in ("Toplevel", "Frame"):
                updates["bg"] = window_bg
            elif cls == "Labelframe":
                # The frame's caption was previously left in its old pale-blue fg.
                updates.update(bg=window_bg, fg=fg, highlightbackground=edge)
            elif cls == "Label":
                # Preserve the semantic foreground chosen by the existing light painter;
                # only align the background with the resolved outer surface.
                updates["bg"] = window_bg
            elif cls in ("Entry", "Text", "Listbox", "Spinbox"):
                updates.update(
                    bg=surface_bg, fg=fg, insertbackground=fg,
                    selectbackground=active_bg, selectforeground=white,
                    highlightbackground=edge, highlightcolor=active_bg,
                )
            elif cls in ("Checkbutton", "Radiobutton"):
                updates.update(
                    bg=window_bg, fg=fg, selectcolor=surface_bg,
                    activebackground=active_bg, activeforeground=white,
                    disabledforeground=palette["muted"],
                )
            elif cls in ("Button", "TButton", "Menubutton"):
                updates.update(
                    bg=button_bg, fg=fg, activebackground=active_bg,
                    activeforeground=white, highlightbackground=edge,
                    highlightcolor=active_bg,
                )
            elif cls in ("Scale", "TScale"):
                updates.update(
                    bg=window_bg, fg=fg, troughcolor=surface_bg,
                    activebackground=active_bg, highlightbackground=edge,
                )
            elif cls in ("Scrollbar", "TScrollbar"):
                updates.update(bg=button_bg, troughcolor=surface_bg, activebackground=active_bg)
            elif cls == "Canvas":
                updates.update(bg=surface_bg, highlightbackground=edge)
            elif cls == "Menu":
                updates.update(bg=surface_bg, fg=fg, activebackground=active_bg,
                               activeforeground=white)
            if updates:
                try:
                    widget.configure(**updates)
                except Exception:
                    # ttk widgets may reject classic Tk color options; their parent surface
                    # still receives the correct first-paint color.
                    pass
        except Exception:
            pass

    # The API and online section's top-level surfaces must share the same final color.
    try:
        win.configure(bg=window_bg)
    except Exception:
        pass


def _petzhu_api_apply_native_frame_theme_v56(app, win):
    """Set DWM caption/border to the same hue-rotated color as the hidden client area."""
    try:
        if win is None or not win.winfo_exists():
            return False
    except Exception:
        return False

    palette = _petzhu_api_v56_palette_for(app)
    light = bool(palette.get("light"))
    window_bg = palette["window"]
    title_fg = "#1e2a3a" if light else str(getattr(app, "C_FG", "#e8f0ff") or "#e8f0ff")
    try:
        win.configure(bg=window_bg)
    except Exception:
        pass
    if os.name != "nt":
        return True

    def colorref(hex_color):
        value = str(hex_color or "").strip().lstrip("#")
        if len(value) != 6:
            return 0x001E2A3A
        r, g, b = int(value[0:2], 16), int(value[2:4], 16), int(value[4:6], 16)
        return r | (g << 8) | (b << 16)

    try:
        from ctypes import wintypes
        dwmapi = ctypes.WinDLL("dwmapi", use_last_error=True)
        set_attr = dwmapi.DwmSetWindowAttribute
        set_attr.argtypes = [wintypes.HWND, wintypes.DWORD, ctypes.c_void_p, wintypes.DWORD]
        set_attr.restype = ctypes.c_long
        hwnds = []
        try:
            frame = str(win.tk.call("wm", "frame", win._w) or "").strip()
            if frame:
                try:
                    handle = int(frame, 0)
                except ValueError:
                    handle = int(frame, 16) if all(c in "0123456789abcdefABCDEF" for c in frame) else 0
                if handle > 0:
                    hwnds.append(handle)
        except Exception:
            pass
        try:
            client = int(win.winfo_id())
            if client > 0 and client not in hwnds:
                hwnds.append(client)
        except Exception:
            pass
        if not hwnds:
            return False

        def apply(attribute, value, value_type):
            storage = value_type(value)
            ptr = ctypes.byref(storage)
            size = ctypes.sizeof(storage)
            for hwnd in hwnds:
                try:
                    if int(set_attr(wintypes.HWND(hwnd), attribute, ptr, size)) >= 0:
                        break
                except Exception:
                    continue

        apply(20, 0 if light else 1, ctypes.c_int)  # DWMWA_USE_IMMERSIVE_DARK_MODE
        apply(34, colorref(window_bg), ctypes.c_uint32)  # DWMWA_BORDER_COLOR
        apply(35, colorref(window_bg), ctypes.c_uint32)  # DWMWA_CAPTION_COLOR
        apply(36, colorref(title_fg), ctypes.c_uint32)   # DWMWA_TEXT_COLOR
        return True
    except Exception:
        return False


# All existing v49/v47 wrappers resolve these globals at call time, so swapping the
# helpers here fixes first display and subsequent theme refreshes without bypassing the
# existing API/chat/choir construction chain.
_petzhu_api_apply_native_frame_theme_v48 = _petzhu_api_apply_native_frame_theme_v56

_PETZHU_API_V56_PREVIOUS_WINDOW_THEME = MaoPet._apply_window_pink_theme
def _petzhu_api_window_theme_v56(self, win):
    result = _PETZHU_API_V56_PREVIOUS_WINDOW_THEME(self, win)
    try:
        api_win = getattr(self, "_api_win", None)
        if api_win is not None and win is api_win and bool(getattr(self, "_context_palette_light", False)):
            _petzhu_api_force_light_palette_v56(self, win)
            # Relay-specific on/off colors are semantic controls and must be the final pass.
            try:
                _petzhu_mp_update_relay_control_visuals(self)
            except Exception:
                pass
    except Exception:
        pass
    return result

MaoPet._apply_window_pink_theme = _petzhu_api_window_theme_v56


_PETZHU_API_V56_PREVIOUS_SHOW_API = MaoPet.show_api_config
def _petzhu_show_api_snapshot_palette_v56(self, *args, **kwargs):
    """Freeze the selected hue before any API widgets are constructed."""
    _petzhu_api_v56_snapshot_palette(self)
    try:
        result = _PETZHU_API_V56_PREVIOUS_SHOW_API(self, *args, **kwargs)
        win = getattr(self, "_api_win", None)
        try:
            if win is not None and win.winfo_exists():
                # The v49 wrapper has already mapped new windows only after hidden theming;
                # reinforce the complete palette after refreshes that add/update controls.
                if bool(getattr(self, "_context_palette_light", False)):
                    _petzhu_api_force_light_palette_v56(self, win)
                _petzhu_api_apply_native_frame_theme_v56(self, win)
                try:
                    win.update_idletasks()
                except Exception:
                    pass
        except Exception:
            pass
        return result
    finally:
        try:
            self._petzhu_api_palette_snapshot_v56 = None
        except Exception:
            pass

MaoPet.show_api_config = _petzhu_show_api_snapshot_palette_v56


# Theme changes also update the native Windows caption and the explicit API control palette.
_PETZHU_API_V56_PREVIOUS_AUX_THEME = MaoPet._apply_auxiliary_window_themes
def _petzhu_api_auxiliary_theme_v56(self, *args, **kwargs):
    result = _PETZHU_API_V56_PREVIOUS_AUX_THEME(self, *args, **kwargs)
    try:
        win = getattr(self, "_api_win", None)
        if win is not None and win.winfo_exists():
            if bool(getattr(self, "_context_palette_light", False)):
                _petzhu_api_force_light_palette_v56(self, win)
            _petzhu_api_apply_native_frame_theme_v56(self, win)
    except Exception:
        pass
    return result

MaoPet._apply_auxiliary_window_themes = _petzhu_api_auxiliary_theme_v56


# v58: 修复星星主题渐变与高频联机成员刷新重复写入 Listbox 颜色造成的闪烁。
# ============================================================
# PETZhu v57: 修复浅色主题下房间成员 Listbox 仍然显示深色的问题。
# 根因：v56 把 insertbackground 一并传给 Listbox；Tk Listbox 不支持此选项，
# configure() 因 unknown option 整体失败，异常又被宽泛捕获，因此该列表未换色。
# v57 在创建时使用最终色板，并在每次整窗换色后单独用 Listbox 支持的选项重刷。
# ============================================================
def _petzhu_api_v57_apply_room_members_list_palette(app, win=None):
    # 根因修复：联机主循环每 30~125ms 都会调用 _mp_refresh_member_list；
    # v57 的包装器即使成员名单没有变化，也会继续调用本函数。
    # 星星主题切换时，主题动画每 25ms 将 Listbox 颜色从旧调色板插值到新调色板；
    # 若这里每个网络 tick 都把颜色强制拉回最终主题色，就会与动画帧来回争写，
    # 表现为成员列表区域不停闪烁。动画期间必须由统一主题过渡独占颜色写入。
    if bool(getattr(app, "_context_theme_transition_running", False)):
        return True
    try:
        ui = getattr(app, "_mp_ui", {})
        lb = ui.get("members") if isinstance(ui, dict) else None
        if lb is None or not lb.winfo_exists():
            return False
        try:
            if str(lb.winfo_class()) != "Listbox":
                return False
        except Exception:
            pass
        light = bool(getattr(app, "_context_palette_light", False))
        if light:
            palette = _petzhu_api_v56_make_palette(app)
            desired = {
                "bg": palette["surface"],
                "fg": palette["fg"],
                "selectbackground": palette["active"],
                "selectforeground": palette["white"],
                "highlightbackground": palette["edge"],
                "highlightcolor": palette["active"],
                "highlightthickness": 0,
            }
        else:
            desired = {
                "bg": str(getattr(app, "C_TEXT_BG", "#111a26") or "#111a26"),
                "fg": str(getattr(app, "C_FG", "#e8f0ff") or "#e8f0ff"),
                "selectbackground": "#3f5b78",
                "selectforeground": "#ffffff",
                "highlightbackground": str(getattr(app, "C_BORDER", "#7fb1e8") or "#7fb1e8"),
                "highlightcolor": str(getattr(app, "C_BORDER", "#7fb1e8") or "#7fb1e8"),
                "highlightthickness": 0,
            }
        # Avoid needless reconfiguration on every network tick; only submit supported
        # Listbox options and only when at least one property has drifted.
        changed = False
        for key, value in desired.items():
            try:
                current = lb.cget(key)
                if str(current).lower() != str(value).lower():
                    changed = True
                    break
            except Exception:
                changed = True
                break
        if changed:
            lb.configure(**desired)
        return True
    except Exception:
        return False


# Make the existing recursive theme pass safe for Listboxes without rewriting its legacy
# behavior for Entry/Text/Spinbox, where insertbackground is a valid option.
_PETZHU_API_V57_PREVIOUS_FORCE_LIGHT_PALETTE = _petzhu_api_force_light_palette_v56
def _petzhu_api_force_light_palette_v57(app, win):
    result = _PETZHU_API_V57_PREVIOUS_FORCE_LIGHT_PALETTE(app, win)
    try:
        if bool(getattr(app, "_context_palette_light", False)) and win is not None and win.winfo_exists():
            for widget in _petzhu_api_walk_widgets_v47(win):
                try:
                    if str(widget.winfo_class()) != "Listbox" or not widget.winfo_exists():
                        continue
                    palette = _petzhu_api_v56_make_palette(app)
                    desired = {
                        "bg": palette["surface"],
                        "fg": palette["fg"],
                        "selectbackground": palette["active"],
                        "selectforeground": palette["white"],
                        "highlightbackground": palette["edge"],
                        "highlightcolor": palette["active"],
                        "highlightthickness": 0,
                    }
                    try:
                        needs_update = any(str(widget.cget(k)).lower() != str(v).lower()
                                           for k, v in desired.items())
                    except Exception:
                        needs_update = True
                    if needs_update:
                        widget.configure(**desired)
                except Exception:
                    continue
    except Exception:
        pass
    try:
        _petzhu_api_v57_apply_room_members_list_palette(app, win)
    except Exception:
        pass
    return result

_petzhu_api_force_light_palette_v56 = _petzhu_api_force_light_palette_v57


# Listbox colors are also reasserted after member refresh and the recurring network tick.
# This protects against any older theme wrapper repainting C_TEXT_BG over this widget.
_PETZHU_API_V57_PREVIOUS_REFRESH_MEMBERS = MaoPet._mp_refresh_member_list
def _petzhu_api_refresh_members_v57(self, *args, **kwargs):
    result = _PETZHU_API_V57_PREVIOUS_REFRESH_MEMBERS(self, *args, **kwargs)
    _petzhu_api_v57_apply_room_members_list_palette(self, getattr(self, "_api_win", None))
    return result
MaoPet._mp_refresh_member_list = _petzhu_api_refresh_members_v57

_PETZHU_API_V57_PREVIOUS_SHOW_API = MaoPet.show_api_config
def _petzhu_api_show_api_v57(self, *args, **kwargs):
    result = _PETZHU_API_V57_PREVIOUS_SHOW_API(self, *args, **kwargs)
    try:
        win = getattr(self, "_api_win", None)
        if win is not None and win.winfo_exists():
            if bool(getattr(self, "_context_palette_light", False)):
                _petzhu_api_force_light_palette_v56(self, win)
            _petzhu_api_v57_apply_room_members_list_palette(self, win)
            try:
                win.update_idletasks()
            except Exception:
                pass
    except Exception:
        pass
    return result
MaoPet.show_api_config = _petzhu_api_show_api_v57

_PETZHU_API_V57_PREVIOUS_WINDOW_THEME = MaoPet._apply_window_pink_theme
def _petzhu_api_window_theme_v57(self, win):
    result = _PETZHU_API_V57_PREVIOUS_WINDOW_THEME(self, win)
    try:
        if win is getattr(self, "_api_win", None):
            _petzhu_api_v57_apply_room_members_list_palette(self, win)
    except Exception:
        pass
    return result
MaoPet._apply_window_pink_theme = _petzhu_api_window_theme_v57

_PETZHU_API_V57_PREVIOUS_AUX_THEME = MaoPet._apply_auxiliary_window_themes
def _petzhu_api_auxiliary_theme_v57(self, *args, **kwargs):
    result = _PETZHU_API_V57_PREVIOUS_AUX_THEME(self, *args, **kwargs)
    try:
        win = getattr(self, "_api_win", None)
        if win is not None and win.winfo_exists():
            if bool(getattr(self, "_context_palette_light", False)):
                _petzhu_api_force_light_palette_v56(self, win)
            _petzhu_api_v57_apply_room_members_list_palette(self, win)
    except Exception:
        pass
    return result
MaoPet._apply_auxiliary_window_themes = _petzhu_api_auxiliary_theme_v57



