def _petzhu_mp_roleplay_text_v59(value):
    text = str(value if value is not None else "")
    for old, new in _PETZHU_MP_RP_TEXT_REPLACEMENTS_V59:
        if old == "负责声部：":
            text = re.sub(r"(?<!本次)负责声部：", new, text)
        elif old in text:
            text = text.replace(old, new)
    # These short labels are applied only in room roster display, never to nicknames or chat.
    # Keep dynamic song/member values intact while improving frequently formatted status lines.
    try:
        text = re.sub(
            r"已向(.+?)发送包含\s*(\d+)\s*首歌曲的歌单和声部邀请；对方只需接受一次。",
            r"已向\1送出包含 \2 首曲目的合唱邀约；伙伴只需应邀一次。", text)
        text = re.sub(
            r"《(.+?)》已就绪。下一步先设置自己的声部，再选中房间成员并邀请。",
            r"《\1》已收入曲目准备。接下来安排好自己的声部，再从营地名册邀请伙伴加入。", text)
        text = re.sub(
            r"歌单共\s*(\d+)\s*首｜已加入\s*(\d+)\s*人，等待回复/下载\s*(\d+)\s*人。",
            r"曲目清单共 \1 首｜已集结 \2 位伙伴，仍有 \3 位等待回应或接收曲谱。", text)
        text = re.sub(
            r"已接受\s*(\d+)\s*首歌曲的合唱歌单；接下来由发起者统一开始和自动切歌。",
            r"已接下包含 \1 首曲目的合唱邀约；接下来由领唱者统一起奏，曲目将按顺序自动衔接。", text)
        text = re.sub(
            r"《(.+?)》｜已加入\s*(\d+)\s*人，等待回复/下载\s*(\d+)\s*人。",
            r"《\1》｜已有 \2 位伙伴集结，仍有 \3 位等待回应或接收曲谱。", text)
        text = re.sub(
            r"正在合唱第\s*(\d+)/(\d+)\s*首：《([^》]+)》",
            r"合奏进行中 · 曲目 \1/\2：《\3》", text)
        text = re.sub(
            r"所有成员将从第\s*(\d+)\s*首同步开始。",
            r"全体伙伴将从第 \1 首曲目同步起奏。", text)
    except Exception:
        pass
    return text

