def _petzhu_mp_apply_roleplay_ui_v59(app, win=None):
    if app is None:
        return
    win = win or getattr(app, "_api_win", None)
    try:
        if win is None or not win.winfo_exists():
            return
    except Exception:
        return
    try:
        win._petzhu_multiplayer_dialog_context = True
        if win is getattr(app, "_api_win", None):
            win.title("API和联机")
    except Exception:
        pass
    pending = [win]
    seen = set()
    while pending:
        widget = pending.pop()
        if widget is None or id(widget) in seen:
            continue
        seen.add(id(widget))
        try:
            pending.extend(widget.winfo_children())
        except Exception:
            pass
        try:
            if not widget.winfo_exists():
                continue
            current = str(widget.cget("text"))
        except Exception:
            continue
        updated = _PETZHU_MP_RP_UI_LABELS_V59.get(current)
        if updated is None:
            updated = _petzhu_mp_roleplay_text_v59(current)
        if updated != current:
            try: widget.configure(text=updated)
            except Exception: pass

