# ----------------------------------------------------------------
# 自绘托盘菜单：在“置顶/退出”之间加入“拖尾”“弹珠”两个勾选项。
# 所有修改都在 Tk 主线程完成，并同步到玩耍设置和 API 联机快捷设置。
# ----------------------------------------------------------------
def _petzhu_show_styled_tray_menu_v60(self, cursor_x=0, cursor_y=0):
    if getattr(self, "_closing", False):
        return
    self._close_styled_tray_menu()
    try:
        win = tk.Toplevel(self.root)
        self._styled_tray_menu_win = win
        win.overrideredirect(True)
        win.attributes("-topmost", True)

        light_palette = {
            "outer": "#f2cbdc", "border": "#e3adc5", "bg": "#fff8fb",
            "row": "#fff8fb", "hover": "#ffe8f2", "fg": "#604154",
            "muted": "#a06e86", "accent": _petzhu_shift_theme_color("#c85e8d"),
            "divider": "#efd5e1", "danger": "#b84a63", "danger_hover": "#ffe1e8",
        }
        dark_palette = {
            "outer": "#263b53", "border": "#496786", "bg": "#1c2b3e",
            "row": "#1c2b3e", "hover": "#304760", "fg": "#e6effb",
            "muted": "#a3b9d5", "accent": _petzhu_shift_theme_color("#c85e8d"),
            "divider": "#405873", "danger": "#ffadba", "danger_hover": "#493447",
        }

        def palette_for(light):
            palette = dict(light_palette if light else dark_palette)
            try:
                palette["accent"] = _petzhu_shift_theme_color("#c85e8d")
            except Exception:
                pass
            return palette

        outer = tk.Frame(win, bg="#fff8fb", bd=0, highlightthickness=1,
                         highlightbackground="#e3adc5", highlightcolor="#e3adc5")
        outer.pack(fill="both", expand=True)
        body = tk.Frame(outer, bg="#fff8fb", bd=0)
        body.pack(fill="both", expand=True, padx=2, pady=2)

        hover = {"topmost": False, "local_trail": False, "marble": False, "exit": False}
        option_rows = {}
        row_specs = (
            ("topmost", "置顶"),
            ("local_trail", "拖尾"),
            ("marble", "弹珠"),
        )

        def current_value(key):
            if key == "topmost":
                return bool(getattr(self, "pet_chat_topmost", True))
            if key == "local_trail":
                return bool(getattr(self, "pet_trail_enabled", True))
            if key == "marble":
                return bool(getattr(self, "pet_marble_effect_enabled", True))
            return False

        for key, label_text in row_specs:
            row = tk.Frame(body, bg="#fff8fb", height=21, cursor="hand2")
            row.pack(fill="x", pady=(0, 1))
            row.pack_propagate(False)
            mark = tk.Label(row, text=("✓" if current_value(key) else ""), width=2,
                            bg="#fff8fb", fg="#c85e8d", font=("Segoe UI Symbol", 10, "bold"), cursor="hand2")
            mark.pack(side="left", padx=(3, 0), fill="y")
            label = tk.Label(row, text=label_text, anchor="w", bg="#fff8fb", fg="#604154",
                             font=("微软雅黑", 9), cursor="hand2")
            label.pack(side="left", fill="both", expand=True, padx=(2, 3))
            option_rows[key] = {"row": row, "mark": mark, "label": label}

        divider = tk.Frame(body, bg="#efd5e1", height=1)
        divider.pack(fill="x", padx=3, pady=(1, 2))
        row_exit = tk.Frame(body, bg="#fff8fb", height=21, cursor="hand2")
        row_exit.pack(fill="x")
        row_exit.pack_propagate(False)
        exit_icon = tk.Label(row_exit, text="×", width=2, bg="#fff8fb", fg="#b84a63",
                             font=("Segoe UI Symbol", 13), cursor="hand2")
        exit_icon.pack(side="left", padx=(3, 0), fill="y")
        exit_label = tk.Label(row_exit, text="退出", anchor="w", bg="#fff8fb", fg="#b84a63",
                              font=("微软雅黑", 9), cursor="hand2")
        exit_label.pack(side="left", fill="both", expand=True, padx=(2, 3))

        def sync_setting_vars():
            try:
                refresher = getattr(self, "_mp_refresh_quick_option_vars", None)
                if callable(refresher):
                    refresher()
            except Exception:
                pass
            # Settings variables may exist even when the API window has not been created.
            try:
                for key, variable in (getattr(self, "_petzhu_play_setting_vars_v22", {}) or {}).items():
                    if key == "marble":
                        wanted = bool(getattr(self, "pet_marble_effect_enabled", True))
                    elif key == "local_trail":
                        wanted = bool(getattr(self, "pet_trail_enabled", True))
                    elif key == "topmost":
                        wanted = bool(getattr(self, "pet_chat_topmost", True))
                    else:
                        continue
                    if variable is not None and bool(variable.get()) != wanted:
                        variable.set(wanted)
            except Exception:
                pass

        def toggle_option(key):
            if key == "topmost":
                enabled = not bool(getattr(self, "pet_chat_topmost", True))
                self.pet_chat_topmost = enabled
                try:
                    self.root.attributes("-topmost", enabled)
                except Exception:
                    pass
                try:
                    self._mp_apply_topmost_to_all()
                except Exception:
                    pass
            elif key == "local_trail":
                enabled = not bool(getattr(self, "pet_trail_enabled", True))
                self.pet_trail_enabled = enabled
                try:
                    self._mp_update_trail_runtime()
                except Exception:
                    pass
            elif key == "marble":
                enabled = not bool(getattr(self, "pet_marble_effect_enabled", True))
                self.pet_marble_effect_enabled = enabled
                if not enabled:
                    try:
                        if (getattr(self, "_spring_active", False)
                                or getattr(self, "_spring_after_id", None) is not None
                                or getattr(self, "_spring_ground_squash_active", False)
                                or getattr(self, "_spring_ground_squash_after_id", None) is not None):
                            self._cancel_edge_spring(restore=True)
                        elif getattr(self, "_edge_squash_active", False):
                            self._reset_edge_squash()
                    except Exception:
                        try:
                            self._reset_edge_squash()
                        except Exception:
                            pass
            try:
                self._save_config()
            except Exception:
                pass
            sync_setting_vars()
            paint(last_palette.get("value") or palette_for(bool(getattr(self, "_context_palette_light", True))))

        def bind_option(key, widget):
            def on_release(_event=None):
                toggle_option(key)
                return "break"
            widget.bind("<ButtonRelease-1>", on_release)
            widget.bind("<Enter>", lambda _e, k=key: hover.__setitem__(k, True))
            widget.bind("<Leave>", lambda _e, k=key: hover.__setitem__(k, False))

        for key, widgets in option_rows.items():
            for widget in (widgets["row"], widgets["mark"], widgets["label"]):
                bind_option(key, widget)

        def exit_menu(_event=None):
            self._close_styled_tray_menu(win)
            self._quit_from_tray()
            return "break"
        for widget in (row_exit, exit_icon, exit_label):
            widget.bind("<ButtonRelease-1>", exit_menu)
            widget.bind("<Enter>", lambda _e: hover.__setitem__("exit", True))
            widget.bind("<Leave>", lambda _e: hover.__setitem__("exit", False))

        last_palette = {"value": None}
        transition_state = {"token": int(getattr(self, "_context_theme_transition_token", 0) or 0), "start": None}

        def paint(palette):
            try:
                win.configure(bg=palette["outer"])
                outer.configure(bg=palette["bg"], highlightbackground=palette["border"], highlightcolor=palette["border"])
                body.configure(bg=palette["bg"])
                for key, widgets in option_rows.items():
                    row_bg = palette["hover"] if hover[key] else palette["row"]
                    widgets["row"].configure(bg=row_bg)
                    widgets["mark"].configure(bg=row_bg, fg=palette["accent"] if current_value(key) else palette["muted"],
                                               text="✓" if current_value(key) else "")
                    widgets["label"].configure(bg=row_bg, fg=palette["fg"])
                divider.configure(bg=palette["divider"])
                exit_bg = palette["danger_hover"] if hover["exit"] else palette["row"]
                row_exit.configure(bg=exit_bg)
                exit_icon.configure(bg=exit_bg, fg=palette["danger"])
                exit_label.configure(bg=exit_bg, fg=palette["danger"])
            except Exception:
                pass

        def apply_palette(palette):
            last_palette["value"] = dict(palette)
            paint(palette)

        def theme_tick():
            try:
                if not win.winfo_exists():
                    return
                is_light = bool(getattr(self, "_context_palette_light", True))
                target = palette_for(is_light)
                transitioning = bool(getattr(self, "_context_theme_transition_running", False))
                progress_value = getattr(self, "_context_theme_transition_progress", None)
                token = int(getattr(self, "_context_theme_transition_token", 0) or 0)
                if transitioning:
                    if token != transition_state["token"]:
                        transition_state["token"] = token
                        transition_state["start"] = dict(last_palette["value"] or palette_for(not is_light))
                    if transition_state["start"] is None:
                        transition_state["start"] = palette_for(not is_light)
                    try:
                        progress = max(0.0, min(1.0, float(progress_value)))
                    except Exception:
                        progress = 0.0
                    start = transition_state["start"]
                    current = {key: self._tray_blend_hex(start.get(key, val), val, progress) for key, val in target.items()}
                else:
                    current = target
                    transition_state["token"] = token
                    transition_state["start"] = None
                apply_palette(current)
                sync_setting_vars()
                self._styled_tray_menu_theme_after = win.after(80, theme_tick)
            except Exception:
                self._styled_tray_menu_theme_after = None

        win.bind("<Escape>", lambda _e: self._close_styled_tray_menu(win))
        win.bind("<FocusOut>", lambda _e: win.after(140, lambda w=win: self._styled_tray_menu_focus_check(w)))
        win.update_idletasks()
        width, height = 124, 105
        sw, sh = max(1, win.winfo_screenwidth()), max(1, win.winfo_screenheight())
        gx = max(4, min(int(cursor_x) - width + 10, sw - width - 4))
        gy = max(4, min(int(cursor_y) - height - 6, sh - height - 4))
        win.geometry(f"{width}x{height}+{gx}+{gy}")
        current_light = bool(getattr(self, "_context_palette_light", True))
        progress_value = getattr(self, "_context_theme_transition_progress", None)
        if bool(getattr(self, "_context_theme_transition_running", False)) and progress_value is not None:
            try:
                p0 = max(0.0, min(1.0, float(progress_value)))
            except Exception:
                p0 = 0.0
            start0, target0 = palette_for(not current_light), palette_for(current_light)
            initial = {key: self._tray_blend_hex(start0.get(key, val), val, p0) for key, val in target0.items()}
            transition_state["start"] = start0
        else:
            initial = palette_for(current_light)
        apply_palette(initial)
        win.lift()
        win.focus_force()
        theme_tick()
    except Exception:
        try:
            self._close_styled_tray_menu()
        except Exception:
            pass

MaoPet._show_styled_tray_menu = _petzhu_show_styled_tray_menu_v60



# ============================================================
# PETZhu v64: 根治联机弹窗不显示
# - 保留正常窗口管理器标题栏，避免 overrideredirect Toplevel 在部分 Windows/Tk 上不映射。
# - 不再 transient 到隐藏的父窗口；映射失败会立即触发原生 messagebox 回退。
# - 仍保留桌宠黑底/白底与主题色的自绘内容区。
# ============================================================
# ============================================================
# PETZhu v62: 修复联机自绘弹窗无声消失
# 根因处理：v59 的旧自绘弹窗把整个构建/显示过程包在宽泛的 except 中，
# 一旦 Toplevel/抓取焦点/模态设置出错就销毁窗口并返回默认值，用户看起来像是
# “点击后什么弹窗也没有”。v62 使用可失败回退的弹窗，并在 parent 缺失时解析
# 当前 PETZhu 实例；自绘失败时恢复显示原生弹窗，绝不吞掉提示。
# ============================================================
_PETZHU_MP_DIALOG_ORIGINAL_SHOW_V62 = _PETZHU_MP_MESSAGEBOX_SHOW_ORIGINAL_V59
_PETZHU_MP_DIALOG_ORIGINAL_ASKSTRING_V62 = _PETZHU_MP_SIMPLEDIALOG_ASKSTRING_ORIGINAL_V59
_PETZHU_MP_DIALOG_LAST_FALLBACK_ERROR_V62 = ""


def _petzhu_mp_dialog_resolve_parent_v62(app, parent=None):
    """Prefer a visible owner; a withdrawn/iconified parent can hide transient dialogs on Windows."""
    candidates = [parent]
    if app is not None:
        for attr in ("_choir_ui", "_mp_ui"):
            try:
                item = getattr(app, attr, None) or {}
                if isinstance(item, dict):
                    candidates.extend((item.get("win"), item.get("frame")))
            except Exception:
                pass
        candidates.extend((getattr(app, "_api_win", None), getattr(app, "root", None)))
    seen = set()
    existing_fallback = None
    for candidate in candidates:
        if candidate is None or id(candidate) in seen:
            continue
        seen.add(id(candidate))
        try:
            if not candidate.winfo_exists():
                continue
            if existing_fallback is None:
                existing_fallback = candidate
            try:
                if bool(candidate.winfo_viewable()) and str(candidate.state()) not in ("withdrawn", "iconic", "iconified"):
                    return candidate
            except Exception:
                # Some widget types do not expose window state; viewability alone is sufficient.
                try:
                    if bool(candidate.winfo_viewable()):
                        return candidate
                except Exception:
                    pass
        except Exception:
            pass
    return existing_fallback


def _petzhu_mp_dialog_should_theme_v62(app, parent, title):
    if app is None:
        return False
    terms = ("联机", "合唱", "房间", "聚会", "营地", "连接码", "曲谱", "歌单", "成员", "邀请", "群聊")
    title_text = str(title or "")
    current = parent
    seen = set()
    for _ in range(96):
        if current is None or id(current) in seen:
            break
        seen.add(id(current))
        try:
            if bool(getattr(current, "_petzhu_multiplayer_dialog_context", False)):
                return True
        except Exception:
            pass
        try:
            if current is getattr(app, "_api_win", None) and current is not None:
                return True
        except Exception:
            pass
        try:
            mp_ui = getattr(app, "_mp_ui", {}) or {}
            choir_ui = getattr(app, "_choir_ui", {}) or {}
            if isinstance(mp_ui, dict) and current in (mp_ui.get("frame"), mp_ui.get("win")):
                return True
            if isinstance(choir_ui, dict) and current is choir_ui.get("win"):
                return True
        except Exception:
            pass
        try:
            current = getattr(current, "master", None)
        except Exception:
            current = None
    # There are older call sites with parent=None; rely on the current app and network title.
    if any(term in title_text for term in terms):
        return True
    return False


def _petzhu_mp_dialog_make_visible_v62(app, title, message, icon="info", dialog_type="ok",
                                       parent=None, input_value=None, input_show=""):
    """Build one PETZhu dialog. Exceptions intentionally propagate to the safe native fallback."""
    palette = _petzhu_mp_dialog_palette_v59(app)
    parent_win = _petzhu_mp_dialog_resolve_parent_v62(app, parent)
    win = tk.Toplevel(parent_win) if parent_win is not None else tk.Toplevel()
    win.configure(bg=palette["outer"])
    win._petzhu_theme_hue_exempt = True
    win._petzhu_multiplayer_dialog_context = True
    win.withdraw()
    # Keep the normal Windows window-manager decorations. The previous borderless
    # overrideredirect Toplevel could be created but never mapped/activated on some Windows/Tk
    # combinations; callers then swallowed the exception and users saw no dialog at all.
    win.title(str(title or "提示"))
    if parent_win is not None:
        try:
            if bool(parent_win.winfo_viewable()):
                win.transient(parent_win)
        except Exception:
            # Do not make the dialog transient to a hidden/withdrawn root window.
            pass

    result_type = str(dialog_type or "ok").lower()
    default_cancel = "no" if result_type in ("yesno", "yesnocancel") else (
        "cancel" if "cancel" in result_type else ("ignore" if result_type == "abortretryignore" else "ok"))
    answer = {"value": None}
    finished = {"value": False}

    border = tk.Frame(win, bg=palette["panel"], highlightthickness=1,
                      highlightbackground=palette["edge"], highlightcolor=palette["edge"])
    border.pack(fill="both", expand=True, padx=1, pady=1)
    tk.Frame(border, bg=palette["accent"], height=4).pack(fill="x")
    header = tk.Frame(border, bg=palette["panel"])
    header.pack(fill="x", padx=15, pady=(10, 5))
    symbol = {"info": "✦", "warning": "!", "error": "×", "question": "?"}.get(str(icon or "info").lower(), "✦")
    tk.Label(header, text=symbol, bg=palette["panel"], fg=palette["accent"],
             font=("微软雅黑", 15, "bold"), width=2).pack(side="left", padx=(0, 7))
    tk.Label(header, text=str(title or "提示"), bg=palette["panel"], fg=palette["fg"],
             font=("微软雅黑", 11, "bold"), anchor="w", justify="left").pack(side="left", fill="x", expand=True)
    body = tk.Frame(border, bg=palette["panel"])
    body.pack(fill="both", expand=True, padx=22, pady=(5, 12))

    input_entry = None
    if input_value is not None:
        tk.Label(body, text=str(message or ""), bg=palette["panel"], fg=palette["fg"],
                 font=("微软雅黑", 9), justify="left", anchor="w", wraplength=480).pack(fill="x", pady=(0, 9))
        input_entry = tk.Entry(body, bg=palette["input"], fg=palette["fg"],
                               insertbackground=palette["insert"], selectbackground=palette["accent"],
                               selectforeground="#ffffff", relief="flat", bd=0,
                               highlightthickness=1, highlightbackground=palette["edge"],
                               highlightcolor=palette["accent"], font=("微软雅黑", 10), show=input_show or "")
        input_entry.pack(fill="x", ipady=6)
        if input_value:
            input_entry.insert(0, str(input_value))
            input_entry.icursor("end")
    else:
        text = str(message or "")
        if len(text) > 900:
            body_text = ScrolledText(body, height=9, wrap="word", bg=palette["panel"], fg=palette["fg"],
                                     insertbackground=palette["insert"], selectbackground=palette["accent"],
                                     selectforeground="#ffffff", relief="flat", bd=0,
                                     font=("微软雅黑", 9), padx=2, pady=2)
            body_text.pack(fill="both", expand=True)
            body_text.insert("1.0", text)
            body_text.configure(state="disabled")
        else:
            tk.Label(body, text=text, bg=palette["panel"], fg=palette["fg"],
                     font=("微软雅黑", 9), justify="left", anchor="w", wraplength=480,
                     padx=0, pady=1).pack(fill="x", expand=True, anchor="w")

    footer = tk.Frame(border, bg=palette["panel"])
    footer.pack(fill="x", padx=16, pady=(0, 14))
    buttons = _petzhu_mp_dialog_button_texts_v59(result_type, title)
    for index, (caption, token) in enumerate(buttons):
        is_primary = index == 0
        def make_command(value):
            def _command():
                if finished["value"]:
                    return
                finished["value"] = True
                if value == "ok" and input_entry is not None:
                    answer["value"] = input_entry.get()
                else:
                    answer["value"] = value
                try:
                    if win.winfo_exists():
                        win.grab_release()
                except Exception:
                    pass
                try:
                    win.destroy()
                except Exception:
                    pass
            return _command
        tk.Button(footer, text=caption, command=make_command(token),
                  bg=(palette["accent"] if is_primary else palette["button"]),
                  fg=(palette["accent_fg"] if is_primary else palette["button_fg"]),
                  activebackground=(palette["edge"] if is_primary else palette["surface"]),
                  activeforeground=(palette["accent_fg"] if is_primary else palette["fg"]),
                  relief="flat", bd=0, font=("微软雅黑", 9, "bold" if is_primary else "normal"),
                  padx=16, pady=6, cursor="hand2").pack(side="right", padx=(6, 0))

    def close_window(_event=None):
        if finished["value"]:
            return "break"
        finished["value"] = True
        answer["value"] = default_cancel
        try:
            win.grab_release()
        except Exception:
            pass
        try:
            win.destroy()
        except Exception:
            pass
        return "break"

    win.protocol("WM_DELETE_WINDOW", close_window)
    win.bind("<Escape>", close_window)
    win.bind("<Return>", lambda _e: (footer.winfo_children()[0].invoke(), "break") if footer.winfo_children() else close_window())
    win.update_idletasks()
    width = max(360, min(560, int(win.winfo_reqwidth())))
    height = max(160, min(max(210, int(win.winfo_screenheight()) - 100), int(win.winfo_reqheight())))
    sw, sh = int(win.winfo_screenwidth()), int(win.winfo_screenheight())
    x = y = None
    if parent_win is not None:
        try:
            pw, ph = int(parent_win.winfo_width()), int(parent_win.winfo_height())
            if pw > 220 and ph > 180:
                x = int(parent_win.winfo_rootx() + (pw - width) / 2)
                y = int(parent_win.winfo_rooty() + (ph - height) / 2)
        except Exception:
            pass
    if x is None:
        x, y = (sw - width) // 2, (sh - height) // 2
    x = max(0, min(max(0, sw - width), int(x)))
    y = max(0, min(max(0, sh - height), int(y)))
    win.geometry(f"{width}x{height}+{x}+{y}")
    # Keep the modal above sibling PETZhu windows for its entire lifetime. The previous
    # implementation removed -topmost after 120ms; if another Toplevel was active, the
    # custom dialog could then fall behind it even though grab_set() was still active.
    # Set topmost before mapping the window, then lift/focus it both immediately and once
    # Tk has completed the first geometry/visibility pass. The attribute disappears with
    # this Toplevel when the dialog is closed; it is not a persistent application setting.
    try:
        win.attributes("-topmost", True)
    except Exception:
        pass
    win.deiconify()
    # Force Tk to flush mapping/geometry now, and detect the exact failure rather than entering
    # wait_window() forever with an invisible Toplevel. The wrapper catches this and displays
    # the native messagebox as a fallback.
    win.update_idletasks()
    try:
        win.update()
    except Exception:
        pass
    try:
        if not bool(win.winfo_ismapped()):
            try:
                win.state("normal")
                win.update_idletasks()
                win.update()
            except Exception:
                pass
            if not bool(win.winfo_ismapped()):
                raise RuntimeError("PETZhu 联机弹窗已创建，但 Windows 未将窗口映射到屏幕。")
    except AttributeError:
        pass
    try:
        win.lift()
    except Exception:
        pass
    try:
        win.grab_set()
    except Exception:
        # Some Windows/Tk combinations reject grab on an overrideredirect dialog; it remains visible.
        pass
    def _raise_modal_dialog_v63(w=win):
        try:
            if w.winfo_exists():
                w.attributes("-topmost", True)
                w.lift()
                w.focus_force()
        except Exception:
            pass
    try:
        win.after_idle(_raise_modal_dialog_v63)
    except Exception:
        pass
    if input_entry is not None:
        input_entry.focus_set()
        input_entry.selection_range(0, "end")
    else:
        win.focus_force()
    win.wait_window()
    return answer["value"] if answer["value"] is not None else default_cancel


def _petzhu_mp_themed_messagebox_show_v62(title=None, message=None, _icon=None, _type=None, **options):
    global _PETZHU_MP_DIALOG_LAST_FALLBACK_ERROR_V62
    parent = options.get("parent")
    app = _petzhu_mp_find_dialog_app_v59(parent, title)
    if _petzhu_mp_dialog_should_theme_v62(app, parent, title):
        resolved_parent = _petzhu_mp_dialog_resolve_parent_v62(app, parent)
        try:
            shown_message = str(message or "")
            detail = options.get("detail")
            if detail:
                shown_message = (shown_message + "\n\n" + str(detail)).strip()
            return _petzhu_mp_dialog_make_visible_v62(
                app, str(title or "提示"), shown_message,
                icon=_icon or "info", dialog_type=_type or "ok", parent=resolved_parent)
        except Exception as exc:
            # Never swallow dialog creation failure: fall back to the original Windows/Tk popup.
            _PETZHU_MP_DIALOG_LAST_FALLBACK_ERROR_V62 = repr(exc)
            try:
                fallback_options = dict(options)
                if resolved_parent is not None:
                    fallback_options["parent"] = resolved_parent
                return _PETZHU_MP_DIALOG_ORIGINAL_SHOW_V62(title, message, _icon, _type, **fallback_options)
            except Exception:
                # Preserve standard messagebox behavior as the last resort.
                raise
    return _PETZHU_MP_DIALOG_ORIGINAL_SHOW_V62(title, message, _icon, _type, **options)


def _petzhu_mp_themed_askstring_v62(title, prompt, **options):
    parent = options.get("parent")
    app = _petzhu_mp_find_dialog_app_v59(parent, title)
    if not _petzhu_mp_dialog_should_theme_v62(app, parent, title):
        return _PETZHU_MP_DIALOG_ORIGINAL_ASKSTRING_V62(title, prompt, **options)
    resolved_parent = _petzhu_mp_dialog_resolve_parent_v62(app, parent)
    try:
        result = _petzhu_mp_dialog_make_visible_v62(
            app, str(title or "输入"), str(prompt or ""), icon="question", dialog_type="okcancel",
            parent=resolved_parent, input_value=options.get("initialvalue", ""),
            input_show=options.get("show", "") or "")
        return None if result in (None, "cancel", "no") else result
    except Exception as exc:
        global _PETZHU_MP_DIALOG_LAST_FALLBACK_ERROR_V62
        _PETZHU_MP_DIALOG_LAST_FALLBACK_ERROR_V62 = repr(exc)
        fallback_options = dict(options)
        if resolved_parent is not None:
            fallback_options["parent"] = resolved_parent
        return _PETZHU_MP_DIALOG_ORIGINAL_ASKSTRING_V62(title, prompt, **fallback_options)


# Replace both entry points together so old callbacks and standard Tk messagebox helpers use
# the same reliable modal path. The non-network dialogs continue to use the original behavior.
messagebox._show = _petzhu_mp_themed_messagebox_show_v62
messagebox._show._petzhu_mp_themed_v59 = True
simpledialog.askstring = _petzhu_mp_themed_askstring_v62


# ============================================================
# v65：普通界面仅在自身获得焦点时置顶；弹窗保持原有置顶行为
# ============================================================
# 适用对象是带正常窗口边框的 Tk Toplevel 界面（API、设置、故事、曲谱编辑器等）。
# 桌宠透明本体、远端桌宠、拖尾/特效、无边框菜单不属于普通界面，继续沿用原逻辑。
# 原有代码中各窗口大量显式设置 -topmost=True；通过 WM 属性入口统一按焦点状态裁决，
# 避免逐个界面打补丁，也避免周期性刷新重新把失焦窗口压在其他程序上面。
_PETZHU_FOCUS_TOPMOST_V65_STATE = {"installed": False}


def _petzhu_focus_topmost_is_popup_v65(window):
    """返回需要保留置顶的弹窗/浮层；检查在窗口显示后仍然有效。"""
    try:
        if bool(getattr(window, "_petzhu_multiplayer_dialog_context", False)):
            return True
        if bool(getattr(window, "_petzhu_focus_topmost_exempt", False)):
            return True
        # 无边框窗口通常是桌宠、菜单、动画覆盖层或轻量浮层，而非普通应用界面。
        try:
            if bool(window.overrideredirect()):
                return True
        except Exception:
            pass
        # 通过 grab_set 打开的 Tk 模态对话框会设置此标记；活动期间持续在其他界面之上。
        try:
            grab = window.grab_current()
            if grab is not None and grab.winfo_toplevel() is window:
                return True
        except Exception:
            pass
    except Exception:
        pass
    return False


def _petzhu_focus_topmost_is_regular_v65(window):
    """只有普通 Toplevel 界面接受焦点置顶策略；Tk 根窗和弹窗不纳入。"""
    try:
        if not isinstance(window, tk.Toplevel):
            return False
        if not bool(window.winfo_exists()):
            return False
        if _petzhu_focus_topmost_is_popup_v65(window):
            return False
        return True
    except Exception:
        return False


def _petzhu_focus_topmost_has_focus_v65(window):
    """判断当前系统焦点是否属于这个顶层窗口，而不只判断某个控件是否有焦点。"""
    try:
        focused = window.focus_displayof()
        if focused is None:
            return False
        return focused.winfo_toplevel() is window
    except Exception:
        try:
            focused = window.focus_get()
            return focused is not None and focused.winfo_toplevel() is window
        except Exception:
            return False


def _petzhu_focus_topmost_apply_v65(window):
    """在 Tk 完成焦点切换后统一更新置顶；同一窗口内部移动焦点不会造成来回闪烁。"""
    try:
        window._petzhu_focus_topmost_after_v65 = None
        if not _petzhu_focus_topmost_is_regular_v65(window):
            return
        enabled = _petzhu_focus_topmost_has_focus_v65(window)
        prior = getattr(window, "_petzhu_focus_topmost_active_v65", None)
        if prior is not None and bool(prior) == bool(enabled):
            return
        window._petzhu_focus_topmost_active_v65 = bool(enabled)
        original = _PETZHU_FOCUS_TOPMOST_V65_STATE.get("original_wm_attributes")
        if callable(original):
            original(window, "-topmost", bool(enabled))
        else:
            window.tk.call("wm", "attributes", window._w, "-topmost", bool(enabled))
        if enabled:
            # 只在获得焦点时提升一次；不做周期性 lift，也不抢走其他窗口的键盘输入。
            try:
                window.lift()
            except Exception:
                pass
    except Exception:
        # 置顶策略失败不应影响窗口本身的正常交互。
        pass


def _petzhu_focus_topmost_schedule_v65(window, _event=None):
    """合并 FocusIn/FocusOut 连发事件，等焦点归属稳定后再应用，避免窗口内控件切换闪烁。"""
    try:
        if not _petzhu_focus_topmost_is_regular_v65(window):
            return
        old_id = getattr(window, "_petzhu_focus_topmost_after_v65", None)
        if old_id:
            try:
                window.after_cancel(old_id)
            except Exception:
                pass
        window._petzhu_focus_topmost_after_v65 = window.after_idle(
            lambda w=window: _petzhu_focus_topmost_apply_v65(w)
        )
    except Exception:
        pass


def _petzhu_focus_topmost_install_v65():
    if _PETZHU_FOCUS_TOPMOST_V65_STATE.get("installed"):
        return
    _PETZHU_FOCUS_TOPMOST_V65_STATE["installed"] = True
    _PETZHU_FOCUS_TOPMOST_V65_STATE["original_wm_attributes"] = tk.Wm.wm_attributes
    _PETZHU_FOCUS_TOPMOST_V65_STATE["original_toplevel_init"] = tk.Toplevel.__init__
    _PETZHU_FOCUS_TOPMOST_V65_STATE["original_toplevel_grab_set"] = tk.Toplevel.grab_set
    original_wm_attributes = _PETZHU_FOCUS_TOPMOST_V65_STATE["original_wm_attributes"]
    original_toplevel_init = _PETZHU_FOCUS_TOPMOST_V65_STATE["original_toplevel_init"]
    original_toplevel_grab_set = _PETZHU_FOCUS_TOPMOST_V65_STATE["original_toplevel_grab_set"]

    def focus_aware_wm_attributes(self, *args, **kwargs):
        # 只处理“设置” -topmost，不拦截属性查询。正常界面收到任何置顶写入时，
        # 都以当前焦点为准：调用方即使周期性写 True，也无法把失焦窗口留在最前面；
        # 调用方写 False 也不能让当前正在使用的界面意外掉到后面。
        requested_index = None
        requested_key = None
        requested_value = None
        try:
            if kwargs and "topmost" in kwargs:
                requested_key = "topmost"
                requested_value = kwargs.get("topmost")
            elif len(args) >= 2 and str(args[0]).lower().lstrip("-") == "topmost":
                requested_index = 1
                requested_value = args[1]
            if requested_key is not None or requested_index is not None:
                if _petzhu_focus_topmost_is_regular_v65(self):
                    requested_value = bool(_petzhu_focus_topmost_has_focus_v65(self))
                    if requested_key is not None:
                        kwargs = dict(kwargs)
                        kwargs[requested_key] = requested_value
                    else:
                        args = list(args)
                        args[requested_index] = requested_value
                        args = tuple(args)
        except Exception:
            pass
        return original_wm_attributes(self, *args, **kwargs)

    focus_aware_wm_attributes._petzhu_focus_topmost_v65 = True
    # Tkinter exposes both spellings; in supported Python versions they are aliases, but assign both.
    tk.Wm.wm_attributes = focus_aware_wm_attributes
    tk.Wm.attributes = focus_aware_wm_attributes

    def focus_aware_toplevel_init(self, *args, **kwargs):
        original_toplevel_init(self, *args, **kwargs)
        try:
            self._petzhu_focus_topmost_managed_v65 = True
            self._petzhu_focus_topmost_active_v65 = None
            self._petzhu_focus_topmost_after_v65 = None
            # A binding on the toplevel bindtag also observes focus changes on its child widgets.
            self.bind("<FocusIn>", lambda event, w=self: _petzhu_focus_topmost_schedule_v65(w, event), add="+")
            self.bind("<FocusOut>", lambda event, w=self: _petzhu_focus_topmost_schedule_v65(w, event), add="+")
            self.bind("<Map>", lambda event, w=self: _petzhu_focus_topmost_schedule_v65(w, event), add="+")
        except Exception:
            pass

    focus_aware_toplevel_init._petzhu_focus_topmost_v65 = True
    tk.Toplevel.__init__ = focus_aware_toplevel_init

    def focus_aware_toplevel_grab_set(self, *args, **kwargs):
        # grab_set 是这里区分模态弹窗与普通界面的可靠信号。让对话框继续置顶，
        # 并且不参与普通界面的 FocusOut 降层处理。
        try:
            self._petzhu_focus_topmost_exempt = True
            original_wm_attributes(self, "-topmost", True)
        except Exception:
            pass
        return original_toplevel_grab_set(self, *args, **kwargs)

    focus_aware_toplevel_grab_set._petzhu_focus_topmost_v65 = True
    tk.Toplevel.grab_set = focus_aware_toplevel_grab_set


_petzhu_focus_topmost_install_v65()

# ============================================================
# v66: 本机多桌宠群聊第一版
# v69: 修复群聊 AI 回复队列属性名不一致，并校验完整 API 配置
# 共享本地 SQLite 消息总线；各桌宠使用自己的 API、人设和记忆。
# ============================================================

def _petzhu_groupchat_db_path_v1():
    """不同 PETZhu 实例共享的本机群聊数据库；不开放网络端口。"""
    override = str(os.environ.get("PETZHU_GROUPCHAT_DB", "") or "").strip()
    if override:
        return os.path.abspath(os.path.expanduser(override))
    if os.name == "nt":
        base = os.environ.get("LOCALAPPDATA") or os.path.join(os.path.expanduser("~"), "AppData", "Local")
    else:
        base = os.path.join(os.path.expanduser("~"), ".local", "share")
    return os.path.join(base, "PETZhu", "group_chat_v1.sqlite3")


def _petzhu_groupchat_connect_v1(app):
    import sqlite3
    path = str(getattr(app, "_petzhu_groupchat_db_path_v1", "") or _petzhu_groupchat_db_path_v1())
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    conn = sqlite3.connect(path, timeout=3.0, isolation_level=None)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA busy_timeout=3000")
    try:
        conn.execute("PRAGMA journal_mode=WAL")
    except Exception:
        pass
    conn.execute("PRAGMA synchronous=NORMAL")
    return conn


def _petzhu_groupchat_init_db_v1(app):
    conn = _petzhu_groupchat_connect_v1(app)
    try:
        conn.executescript("""
        CREATE TABLE IF NOT EXISTS gc_participants (
            id TEXT PRIMARY KEY,
            profile_key TEXT NOT NULL,
            name TEXT NOT NULL,
            pid INTEGER NOT NULL DEFAULT 0,
            api_ready INTEGER NOT NULL DEFAULT 0,
            last_seen REAL NOT NULL,
            started_at REAL NOT NULL
        );
        CREATE TABLE IF NOT EXISTS gc_messages (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            created_at REAL NOT NULL,
            sender_id TEXT NOT NULL,
            sender_type TEXT NOT NULL,
            sender_name TEXT NOT NULL,
            text TEXT NOT NULL,
            mode TEXT NOT NULL DEFAULT 'free',
            target_id TEXT NOT NULL DEFAULT '',
            chain_root INTEGER NOT NULL DEFAULT 0,
            chain_depth INTEGER NOT NULL DEFAULT 0
        );
        CREATE INDEX IF NOT EXISTS gc_messages_created_idx ON gc_messages(id);
        CREATE TABLE IF NOT EXISTS gc_jobs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            root_id INTEGER NOT NULL,
            participant_id TEXT NOT NULL,
            mode TEXT NOT NULL,
            turn_index INTEGER NOT NULL DEFAULT 0,
            status TEXT NOT NULL DEFAULT 'pending',
            lease_until REAL NOT NULL DEFAULT 0,
            UNIQUE(root_id, participant_id)
        );
        CREATE INDEX IF NOT EXISTS gc_jobs_ready_idx ON gc_jobs(participant_id, status, root_id, turn_index);
        CREATE TABLE IF NOT EXISTS gc_memories (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            profile_key TEXT NOT NULL,
            memory TEXT NOT NULL,
            updated_at REAL NOT NULL,
            UNIQUE(profile_key, memory)
        );
        CREATE TABLE IF NOT EXISTS gc_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
        """)
    finally:
        conn.close()


def _petzhu_groupchat_profile_key_v1(app):
    try:
        data_dir = os.path.normcase(os.path.abspath(get_data_dir()))
    except Exception:
        data_dir = os.path.normcase(os.getcwd())
    name = str(getattr(app, "pet_name", "桌宠") or "桌宠").strip()[:48]
    return hashlib.sha256((data_dir + "|" + name).encode("utf-8", "replace")).hexdigest()[:24]


def _petzhu_groupchat_heartbeat_v1(app):
    conn = _petzhu_groupchat_connect_v1(app)
    now = time.time()
    try:
        conn.execute("""
            INSERT INTO gc_participants(id,profile_key,name,pid,api_ready,last_seen,started_at)
            VALUES(?,?,?,?,?,?,?)
            ON CONFLICT(id) DO UPDATE SET profile_key=excluded.profile_key,
              name=excluded.name,pid=excluded.pid,api_ready=excluded.api_ready,last_seen=excluded.last_seen
        """, (
            str(app._petzhu_groupchat_id_v1), str(app._petzhu_groupchat_profile_key_v1),
            str(getattr(app, "pet_name", "桌宠") or "桌宠")[:24], int(os.getpid()),
            1 if (
                str(getattr(app, "api_key", "") or "").strip()
                and str(getattr(app, "api_url", "") or "").strip()
                and str(getattr(app, "api_model", "") or "").strip()
            ) else 0,
            now, float(getattr(app, "_petzhu_groupchat_started_at_v1", now) or now),
        ))
    finally:
        conn.close()


def _petzhu_groupchat_get_members_v1(app, api_only=False):
    conn = _petzhu_groupchat_connect_v1(app)
    now = time.time()
    try:
        query = "SELECT * FROM gc_participants WHERE last_seen >= ?"
        params = [now - 8.0]
        if api_only:
            query += " AND api_ready=1"
        query += " ORDER BY started_at, name, id"
        return [dict(row) for row in conn.execute(query, params).fetchall()]
    finally:
        conn.close()


def _petzhu_groupchat_meta_get_v1(conn, key, default=""):
    row = conn.execute("SELECT value FROM gc_meta WHERE key=?", (str(key),)).fetchone()
    return str(row[0]) if row else str(default)


def _petzhu_groupchat_meta_set_v1(conn, key, value):
    conn.execute("INSERT INTO gc_meta(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
                 (str(key), str(value)))


def _petzhu_groupchat_add_system_message_v1(app, text):
    conn = _petzhu_groupchat_connect_v1(app)
    try:
        conn.execute("INSERT INTO gc_messages(created_at,sender_id,sender_type,sender_name,text,mode,target_id,chain_root,chain_depth) VALUES(?,?,?,?,?,?,?,?,?)",
                     (time.time(), "system", "system", "群聊提示", str(text)[:600], "system", "", 0, 0))
        conn.execute("DELETE FROM gc_messages WHERE id NOT IN (SELECT id FROM gc_messages ORDER BY id DESC LIMIT 1000)")
        conn.execute("DELETE FROM gc_jobs WHERE status IN ('done','skipped') AND root_id NOT IN (SELECT id FROM gc_messages)")
    finally:
        conn.close()


def _petzhu_groupchat_rotate_members_v1(conn, members, last_id=""):
    members = list(members or [])
    if not members:
        return []
    index = next((i for i, item in enumerate(members) if str(item.get("id")) == str(last_id)), -1)
    if index < 0:
        return members
    return members[index + 1:] + members[:index + 1]


def _petzhu_groupchat_resolve_explicit_targets_v95(text, active):
    """Only resolve unambiguous addressees; mentioning a name as the topic is not enough."""
    raw = str(text or "").strip()
    if not raw:
        return []
    members = sorted(
        (p for p in (active or []) if str(p.get("id", "") or "") and str(p.get("name", "") or "").strip()),
        key=lambda p: len(str(p.get("name", "") or "")), reverse=True)
    found = []

    # Explicit @mentions can appear anywhere in the message; at each @, select the longest
    # known display name so names that share a prefix are never mistaken for two recipients.
    mention_hits = []
    for marker in re.finditer(r"@\s*", raw):
        remaining = raw[marker.end():]
        selected = next((p for p in members
                         if remaining.startswith(str(p.get("name", "") or "").strip())), None)
        if selected is not None:
            mention_hits.append((marker.start(), str(selected.get("id"))))
    if mention_hits:
        for _, member_id in sorted(mention_hits):
            if member_id not in found:
                found.append(member_id)
        return found

    # A leading name is treated as direct address only when followed by a vocative/prompt form.
    # Thus “珠珠导师今天在忙什么” is a topic mention, not necessarily a message to 珠珠.
    for member in members:
        name = str(member.get("name", "") or "").strip()
        if not name:
            continue
        rest = raw[len(raw) - len(raw.lstrip()):]
        if not rest.startswith(name):
            continue
        tail = rest[len(name):]
        tail = tail.lstrip()
        direct_prefix = re.match(
            r"(?:[，,:：、!！?？…]+\s*|(?:你(?:觉得|认为|看|说|知道|能|可以|要不要|有没有)|"
            r"请|能不能|可以吗|帮我|告诉我|说说|在吗|听我说|回答一下|看一下))",
            tail,
            flags=re.I,
        )
        if direct_prefix:
            return [str(member.get("id"))]

    # Common explicit constructions such as “我想问问珠珠……” or “想听香咕噜说说……”.
    for member in members:
        name = str(member.get("name", "") or "").strip()
        if not name:
            continue
        pattern = r"(?:我想问(?:问)?|我问|问问|想问|想听听|想听|找一下|找|请教)\s*" + re.escape(name) + r"(?=[，,:：、\s]|$)"
        if re.search(pattern, raw):
            return [str(member.get("id"))]
    return []


def _petzhu_groupchat_send_user_v1(app, text, mode="free", target_id=""):
    text = str(text or "").strip()
    if not text:
        return False, "先写点内容再发送吧。"
    text = text[:4000]
    mode = mode if mode in ("free", "mention", "all") else "free"
    active = _petzhu_groupchat_get_members_v1(app, api_only=True)
    if not active:
        _petzhu_groupchat_add_system_message_v1(app, "目前没有已配置 API 的在线桌宠可以回复。")
        return False, "没有可用的在线桌宠；请确认至少一只桌宠已配置 API。"

    routed_target_id = str(target_id or "")
    explicit_target_ids = []
    if mode == "free":
        explicit_target_ids = _petzhu_groupchat_resolve_explicit_targets_v95(text, active)
        # Route a clearly addressed message to the addressee(s), rather than selecting an unrelated pet.
        if explicit_target_ids:
            routed_target_id = "|".join(explicit_target_ids)
            candidates = [p for p in active if str(p.get("id", "")) in explicit_target_ids]
            candidates.sort(key=lambda p: explicit_target_ids.index(str(p.get("id", ""))))
        else:
            candidates = None
    else:
        candidates = None

    if mode == "mention":
        target = next((p for p in active if str(p["id"]) == str(target_id)), None)
        if target is None:
            return False, "请选择一只在线且已配置 API 的桌宠。"
        candidates = [target]
        routed_target_id = str(target_id)
    elif mode == "all":
        conn0 = _petzhu_groupchat_connect_v1(app)
        try:
            last = _petzhu_groupchat_meta_get_v1(conn0, "last_responder", "")
            candidates = _petzhu_groupchat_rotate_members_v1(conn0, active, last)
        finally:
            conn0.close()
        routed_target_id = ""
    elif mode == "free" and not explicit_target_ids:
        conn0 = _petzhu_groupchat_connect_v1(app)
        try:
            last = _petzhu_groupchat_meta_get_v1(conn0, "last_responder", "")
            rotated = _petzhu_groupchat_rotate_members_v1(conn0, active, last)
            candidates = rotated[:1]
        finally:
            conn0.close()
        routed_target_id = ""

    conn = _petzhu_groupchat_connect_v1(app)
    try:
        conn.execute("BEGIN IMMEDIATE")
        now = time.time()
        cur = conn.execute(
            "INSERT INTO gc_messages(created_at,sender_id,sender_type,sender_name,text,mode,target_id,chain_root,chain_depth) VALUES(?,?,?,?,?,?,?,?,?)",
            (now, "human", "user", "你", text, mode, routed_target_id, 0, 0))
        root_id = int(cur.lastrowid)
        conn.execute("UPDATE gc_messages SET chain_root=? WHERE id=?", (root_id, root_id))
        for order, member in enumerate(candidates or []):
            conn.execute("INSERT OR IGNORE INTO gc_jobs(root_id,participant_id,mode,turn_index,status,lease_until) VALUES(?,?,?,?,?,0)",
                         (root_id, str(member["id"]), mode, order, "pending"))
        conn.execute("DELETE FROM gc_messages WHERE id NOT IN (SELECT id FROM gc_messages ORDER BY id DESC LIMIT 1000)")
        conn.execute("DELETE FROM gc_jobs WHERE status IN ('done','skipped') AND root_id NOT IN (SELECT id FROM gc_messages)")
        conn.commit()
    except Exception:
        try: conn.rollback()
        except Exception: pass
        raise
    finally:
        conn.close()
    return True, ""

def _petzhu_groupchat_fetch_messages_v1(app, after_id=0, limit=100):
    conn = _petzhu_groupchat_connect_v1(app)
    try:
        rows = conn.execute("SELECT * FROM gc_messages WHERE id>? ORDER BY id LIMIT ?", (int(after_id), int(limit))).fetchall()
        return [dict(row) for row in rows]
    finally:
        conn.close()


def _petzhu_groupchat_recent_context_v1(app, root_id, limit=22):
    conn = _petzhu_groupchat_connect_v1(app)
    try:
        latest_row = conn.execute("SELECT COALESCE(MAX(id),0) FROM gc_messages").fetchone()
        latest = int(latest_row[0] or 0)
        cutoff = max(0, latest - int(limit))
        rows = conn.execute("SELECT * FROM gc_messages WHERE id>=? OR id=? ORDER BY id", (cutoff, int(root_id))).fetchall()
        messages = [dict(row) for row in rows][-int(limit):]
        memories = conn.execute("SELECT memory FROM gc_memories WHERE profile_key=? ORDER BY updated_at DESC,id DESC LIMIT 12",
                                (str(app._petzhu_groupchat_profile_key_v1),)).fetchall()
        return messages, [str(r[0]) for r in memories]
    finally:
        conn.close()


def _petzhu_groupchat_claim_job_v1(app):
    conn = _petzhu_groupchat_connect_v1(app)
    now = time.time()
    try:
        conn.execute("BEGIN IMMEDIATE")
        # 离线实例遗留的任务标记为跳过，避免全员讨论永远卡在某个离线成员。
        conn.execute("""
            UPDATE gc_jobs SET status='skipped', lease_until=0
            WHERE status IN ('pending','working') AND participant_id IN
              (SELECT id FROM gc_participants WHERE last_seen < ?)
        """, (now - 8.0,))
        row = conn.execute("""
            SELECT j.* FROM gc_jobs j
            WHERE j.participant_id=? AND
              (j.status='pending' OR (j.status='working' AND j.lease_until < ?))
              AND NOT EXISTS (
                SELECT 1 FROM gc_jobs prev
                WHERE prev.root_id=j.root_id AND prev.turn_index<j.turn_index
                  AND prev.status NOT IN ('done','skipped')
              )
            ORDER BY j.root_id,j.turn_index,j.id LIMIT 1
        """, (str(app._petzhu_groupchat_id_v1), now)).fetchone()
        if row is None:
            conn.commit()
            return None
        changed = conn.execute("UPDATE gc_jobs SET status='working', lease_until=? WHERE id=? AND (status='pending' OR lease_until<?)",
                               (now + 90.0, int(row["id"]), now)).rowcount
        conn.commit()
        return dict(row) if changed else None
    except Exception:
        try: conn.rollback()
        except Exception: pass
        return None
    finally:
        conn.close()


# v73: Root fix for group-chat names: exclude the entire group-chat widget tree from the
# periodic persona-name walker, preserve raw message text, and serialize peer utterances as
# identity-tagged transcript records instead of assistant messages belonging to this pet.
def _petzhu_groupchat_generate_worker_v1(app, job):
    raw_reply = ""
    err = ""
    other_names = []
    local_memories = []
    context = []
    memories = []
    name = str(getattr(app, "pet_name", "桌宠") or "桌宠")[:24]
    try:
        api_key = str(getattr(app, "api_key", "") or "").strip()
        api_url = str(getattr(app, "api_url", "") or "").strip()
        api_model = str(getattr(app, "api_model", "") or "").strip()
        if not api_key or not api_url or not api_model:
            raise RuntimeError("missing_api_config")
        # 群聊始终采用桌宠自己的现实人设，不跟随阅读器当前选择切入某个故事存档世界线。
        try:
            base_prompt = str(app._effective_desktop_persona_prompt() or "").strip()
            profession_prompt = str(app._effective_profession_knowledge_prompt() or "").strip()
            if profession_prompt:
                base_prompt += "\n\n" + profession_prompt
            if str(globals().get("RAID_CHAT_KNOWLEDGE", "") or "").strip():
                base_prompt += "\n\n" + str(globals().get("RAID_CHAT_KNOWLEDGE", "") or "").strip()
            local_memories = [str(m).strip() for m in (getattr(app, "memories", []) or []) if str(m).strip()]
            if local_memories:
                base_prompt += "\n\n【这只桌宠自己的长期重要记忆】\n" + "\n".join("- " + m for m in local_memories[-100:])
            temp_lines = _petzhu_temporary_memory_context_v85(app, limit=16)
            if temp_lines:
                base_prompt += "\n\n【近期临时记忆（最多保留7天，可能过时）】\n" + "\n".join(temp_lines)
        except Exception:
            base_prompt = str(app._build_system_prompt("") or "").strip()
        members = _petzhu_groupchat_get_members_v1(app)
        current_instance_id = str(getattr(app, "_petzhu_groupchat_id_v1", "") or "")
        other_names = list(dict.fromkeys(
            str(p.get("name", "桌宠") or "桌宠")[:24]
            for p in members if str(p.get("id", "")) != current_instance_id
        ))
        member_names = [str(p.get("name", "桌宠") or "桌宠")[:24] for p in members]
        mode = str(job.get("mode", "free"))
        extra = (
            "\n\n【本机桌宠群聊规则】\n"
            "你正在和用户以及其他独立桌宠共同聊天。你当前的身份始终是桌宠「%s」，必须严格遵守你自己的完整人设；不要代替其他桌宠发言，也不要把对方的经历说成自己的。\n"
            "当前在线桌宠包括：%s。把最近群聊记录当作连续对话，根据上一条真正回应，不要复述已经说过的话。像即时聊天一样发言：通常说 1—3 句简短自然的话，必要时可以更多；不要写成长篇独白，每句话尽量只表达一个清楚的意思，不要使用 Markdown。程序会把不同句子拆成多条消息，逐条发送。不要为了凑数量硬拆，也不要在一句话尚未说完时输出内部说明。\n"
            "记忆必须严格分层：[MEM:简短记忆] 只保存长期仍有用的稳定偏好、身份事实、反复习惯、重要关系变化、明确承诺或长期目标；\n"
            "日常闲聊、一次吃了什么、刚才在做什么、当前话题、临时心情和近几天计划不得进入 [MEM]，应使用 [TMEM:简短临时记忆]；\n"
            "每次可输出0或1条 [MEM]，也可输出0或1条 [TMEM]；没有值得记的内容就不输出。两种标记都会自动收走，不显示给群聊成员。\n"
        ) % (name, "、".join(member_names) if member_names else "暂无其他桌宠")
        # 实际运行中的成员名单优先于人设旧名、别名或习惯性自称；每个成员是不同身份。
        # 不让模型把别的桌宠/人物的名字和称谓归一成当前说话者的名字。
        if other_names:
            extra += (
                "\n【人物姓名与称谓必须原样保留】\n"
                "当前说话者的实际显示名是「%s」。同一群聊中的其他独立桌宠实际名称为：%s。\n"
                "这些名字对应不同的角色/实例，不是可互换的别名。引用最近对话、人设、记忆里的其他人物时，必须沿用原文姓名和称谓；"
                "禁止因为你自己的名字、旧称、别名或人设中出现过相同名字，就把其他人的名字改成自己的名字。\n"
            ) % (name, "、".join(other_names))
            example_rules = "；".join("「%s导师」不能改写成「%s导师」" % (other, name) for other in other_names[:5] if other != name)
            if example_rules:
                extra += "例如：" + example_rules + "。其他称谓同样必须保留原名。\n"
        else:
            extra += (
                "\n【人物姓名与称谓必须原样保留】\n"
                "引用人设、记忆和历史对话中的其他人物时，姓名和称谓必须照原文保留；"
                "不得因自己的当前显示名、旧称或别名而自动改写其他人的名字。\n"
            )
        if mode == "all":
            extra += "这是一轮全员讨论，请表达自己的真实看法，并接着前面成员的观点说，不要重复其他成员。\n"
        elif mode == "mention":
            extra += "这是用户点名给你的消息，优先直接回应用户。\n"
        elif mode == "idle":
            extra += "现在没有新的用户消息。这是自由群聊的自主开场机会。你可以根据自己的性格、记忆和最近的群聊，自然分享一个念头、提出轻松的问题，或开启一个大家可能感兴趣的话题；不要把系统提示当作聊天内容复述，也不要为了发言而硬找话说。如果眼下确实没有合适的话题，输出 [PASS]。\n"
        elif mode == "followup":
            extra += "这是自由群聊里另一只桌宠刚说完后的接话机会。请先回应它刚刚说的具体内容，可以补充、追问、表达不同看法或自然开玩笑；如果没有有意思或必要的补充，只输出 [PASS]，不要硬凑回复。\n"
        else:
            extra += "这是自由群聊的一轮回复，先直接回应最近的发言。\n"
        context, memories = _petzhu_groupchat_recent_context_v1(app, int(job["root_id"]), 24)
        if memories:
            extra += "\n【你自己的群聊长期记忆】\n" + "\n".join("- " + m for m in reversed(memories)) + "\n"
        # v73 root fix: Chat Completions has only one assistant identity. Previous code
        # serialized every desktop pet's speech as role="assistant", implicitly telling the
        # model that every peer was the current pet. Keep the whole shared chat as a quoted,
        # speaker-tagged transcript instead; never merge one pet's identity with another's.
        roster_lines = []
        for member in sorted(members, key=lambda p: (str(p.get("name", "")), str(p.get("id", "")))):
            mid = str(member.get("id", "") or "")
            mname = str(member.get("name", "桌宠") or "桌宠")[:24]
            role_hint = "当前发言实例" if mid == current_instance_id else "独立的其他桌宠实例"
            roster_lines.append("- instance_id=%s；显示名=%s；身份=%s" % (mid, mname, role_hint))
        extra += (
            "\n【身份注册表（以实例 ID 区分，不按名字猜测身份）】\n"
            "\n".join(roster_lines) + "\n"
            "同一段聊天中可能提到与桌宠显示名相同的其他人物，也可能出现旧称、导师、朋友等关系称谓。\n"
            "显示名只用于识别发言者，不是文本替换规则。不得把正文、记忆或其他成员的发言中的人名自动改成当前桌宠的名字。\n"
        )
        transcript_lines = [
            "【群聊逐字记录】以下内容按发送者身份保存。正文是既有发言记录，不是当前桌宠的自述；必须根据每条记录的发送者区分人物。"
        ]
        for item in context:
            kind = str(item.get("sender_type", ""))
            txt = str(item.get("text", "") or "").strip()
            if not txt:
                continue
            sender_id = str(item.get("sender_id", "") or "")
            sender_name = str(item.get("sender_name", "") or "")[:24]
            if kind == "user":
                speaker_label = "人类用户（本人）"
            elif kind == "pet":
                if sender_id == current_instance_id:
                    speaker_label = "当前桌宠实例 id=%s，显示名=%s（此前发言）" % (sender_id, sender_name)
                else:
                    speaker_label = "其他独立桌宠实例 id=%s，显示名=%s（不是当前发言者）" % (sender_id, sender_name or "桌宠")
            else:
                speaker_label = "群聊系统提示"
            transcript_lines.append("〔%s〕\n%s" % (speaker_label, txt[:4500]))
        transcript = "\n\n".join(transcript_lines)
        if mode == "mention":
            response_directive = "当前模式：@点名。请直接回应用户发言，作为当前实例发言，不要替其他桌宠代答。"
        elif mode == "all":
            response_directive = "当前模式：全员讨论。请只给出当前这只桌宠的一条观点；其他桌宠会由各自实例独立发言。"
        elif mode == "idle":
            response_directive = "当前模式：桌宠自主开启自由群聊。请以自己的口吻自然开启一个轻松话题或分享一个想法，不要提及‘系统提示’；如果没有自然想说的内容就只输出 [PASS]。"
        elif mode == "followup":
            response_directive = "当前模式：自由群聊接话。请结合刚刚另一只桌宠的具体回复自然接话；若没有值得回应的内容，就只输出 [PASS]。"
        else:
            response_directive = "当前模式：自由群聊。请自然回应最近一条相关发言，不要机械复述，也不要代替其他桌宠发言。"
        messages = [
            {"role": "system", "content": base_prompt + extra},
            {"role": "user", "content": transcript + "\n\n【本次发言任务】\n" + response_directive + "\n直接输出当前桌宠要说的话，不要加发言者姓名前缀。"},
        ]
        payload = json.dumps({
            "model": api_model, "messages": messages, "temperature": 1.0,
            "max_tokens": 520, "stream": False,
        }, ensure_ascii=False).encode("utf-8")
        request = urllib.request.Request(api_url, data=payload,
            headers={"Content-Type": "application/json", "Authorization": "Bearer " + api_key}, method="POST")
        with urllib.request.urlopen(request, timeout=40) as response:
            response_data = json.loads(response.read().decode("utf-8"))
        raw_reply = str(response_data["choices"][0]["message"]["content"] or "").strip()
        if not raw_reply:
            raise RuntimeError("empty_reply")
    except Exception as exc:
        # 群聊里给出可操作的错误类别，但绝不记录 API key 或完整请求内容。
        if isinstance(exc, RuntimeError):
            err = "请检查这只桌宠的 API 配置（Key、接口地址和模型名）。"
        elif isinstance(exc, urllib.error.HTTPError):
            err = "API 返回 HTTP %s，请检查接口地址、模型权限或额度。" % int(getattr(exc, "code", 0) or 0)
        elif isinstance(exc, urllib.error.URLError):
            err = "无法连接 API 服务，请检查网络和接口地址。"
        elif isinstance(exc, (json.JSONDecodeError, KeyError, IndexError, TypeError)):
            err = "API 返回内容格式不符合预期，请检查接口兼容性。"
        else:
            err = "请求没有成功，请检查网络或 API 配置。"
    # The UI tick consumes this exact v1 queue. A mismatched legacy attribute name
    # silently discarded every AI result, leaving jobs in "working" until lease expiry.
    try:
        result_queue = getattr(app, "_petzhu_groupchat_result_queue_v1", None)
        if result_queue is not None:
            result_queue.put((dict(job), raw_reply, err))
        else:
            # Defensive fallback for a shutdown/reinitialization race: do not create a
            # second queue that no UI poller owns. Mark the job retryable instead.
            try:
                conn = _petzhu_groupchat_connect_v1(app)
                try:
                    conn.execute(
                        "UPDATE gc_jobs SET status='pending', lease_until=0 WHERE id=? AND status='working'",
                        (int(job.get("id", 0) or 0),),
                    )
                finally:
                    conn.close()
            except Exception:
                pass
    except Exception:
        pass


def _petzhu_groupchat_finish_job_v1(app, job, raw_reply, err):
    root_id = int(job.get("root_id", 0) or 0)
    participant_id = str(job.get("participant_id", "") or "")
    job_id = int(job.get("id", 0) or 0)
    mode = str(job.get("mode", "free") or "free")
    turn_index = int(job.get("turn_index", 0) or 0)
    name = str(getattr(app, "pet_name", "桌宠") or "桌宠")[:24]
    profile_key = str(getattr(app, "_petzhu_groupchat_profile_key_v1", "") or "")
    memory_items = []
    clean = ""
    is_pass = False
    if not err:
        raw = str(raw_reply or "").strip()
        is_pass = raw.strip() == "[PASS]"
        if not is_pass:
            try:
                memory_items = [str(x).strip() for x in re.findall(r"\[MEM[:：](.+?)\]", raw, flags=re.S) if str(x).strip()]
                clean = app._extract_memory(raw) if hasattr(app, "_extract_memory") else re.sub(r"\[MEM[:：].+?\]", "", raw, flags=re.S).strip()
            except Exception:
                clean = re.sub(r"\[MEM[:：].+?\]", "", raw, flags=re.S).strip()
            try:
                clean = app._strip_singing_markup(clean)
            except Exception:
                clean = re.sub(r"<\/?song>|\[/?HUM\]", "", clean, flags=re.I).strip()
            if "[PASS]" in clean:
                clean = clean.replace("[PASS]", "").strip()
            # 群聊是一段包含多个独立角色的共同对话；不要套用单只桌宠的对白替换规则，
            # 否则用户自定义的“珠珠=>香咕噜”等替换可能改写其他成员的姓名。
            clean = str(clean or "").strip()[:1600]
    conn = _petzhu_groupchat_connect_v1(app)
    now = time.time()
    try:
        conn.execute("BEGIN IMMEDIATE")
        jobrow = conn.execute("SELECT status FROM gc_jobs WHERE id=?", (job_id,)).fetchone()
        if jobrow is None or str(jobrow[0]) not in ("working", "pending"):
            conn.commit()
            return
        if clean and not err and not is_pass:
            conn.execute("INSERT INTO gc_messages(created_at,sender_id,sender_type,sender_name,text,mode,target_id,chain_root,chain_depth) VALUES(?,?,?,?,?,?,?,?,?)",
                         (now, participant_id, "pet", name, clean, mode, "", root_id, turn_index + 1))
        elif err:
            conn.execute("INSERT INTO gc_messages(created_at,sender_id,sender_type,sender_name,text,mode,target_id,chain_root,chain_depth) VALUES(?,?,?,?,?,?,?,?,?)",
                         (now, "system", "system", "群聊提示", "%s 暂时没能接上话（%s）" % (name, str(err)[:180]), "system", "", root_id, turn_index + 1))
        conn.execute("UPDATE gc_jobs SET status='done',lease_until=0 WHERE id=?", (job_id,))
        _petzhu_groupchat_meta_set_v1(conn, "last_responder", participant_id)
        for memory in memory_items:
            memory = re.sub(r"\s+", " ", memory).strip()[:220]
            if memory:
                conn.execute("INSERT OR IGNORE INTO gc_memories(profile_key,memory,updated_at) VALUES(?,?,?)", (profile_key, memory, now))
        # 自由群聊允许桌宠围绕刚才的话题自然接续几轮，不必等待用户每次发言。
        # 每个根话题最多 8 条桌宠发言（turn_index 0..7）；[PASS]、错误或无内容都会自然结束。
        # 新的 UNIQUE(root_id, participant_id, turn_index) 约束允许同一只桌宠在不同轮次再次接话。
        if mode in ("free", "followup", "idle") and not err and not is_pass and clean and turn_index < 7:
            rows = [dict(r) for r in conn.execute(
                "SELECT * FROM gc_participants WHERE last_seen>=? AND api_ready=1 ORDER BY started_at,name,id",
                (now - 8.0,)).fetchall()]
            if len(rows) >= 2:
                rotated = _petzhu_groupchat_rotate_members_v1(conn, rows, participant_id)
                next_person = next((candidate for candidate in rotated
                                    if str(candidate.get("id", "")) != participant_id), None)
                if next_person is not None:
                    next_turn = turn_index + 1
                    conn.execute("INSERT OR IGNORE INTO gc_jobs(root_id,participant_id,mode,turn_index,status,lease_until) VALUES(?,?,?,?,?,0)",
                                 (root_id, str(next_person["id"]), "followup", next_turn, "pending"))
        conn.execute("DELETE FROM gc_messages WHERE id NOT IN (SELECT id FROM gc_messages ORDER BY id DESC LIMIT 1000)")
        conn.execute("DELETE FROM gc_jobs WHERE status IN ('done','skipped') AND root_id NOT IN (SELECT id FROM gc_messages)")
        conn.commit()
    except Exception:
        try: conn.rollback()
        except Exception: pass
    finally:
        conn.close()


def _petzhu_groupchat_palette_v1(app):
    light = bool(getattr(app, "_context_palette_light", True))
    try:
        hue = int(getattr(app, "theme_hue", _PETZHU_THEME_HUE_STATE.get("hue", 330))) % 360
    except Exception:
        hue = 330
    rr, gg, bb = colorsys.hsv_to_rgb(hue / 360.0, 0.46, 0.88)
    accent = "#%02x%02x%02x" % (round(rr * 255), round(gg * 255), round(bb * 255))
    if light:
        return {"light": True, "bg": "#fff8fb", "surface": "#ffffff", "surface2": "#f7edf3",
                "fg": "#40313c", "muted": "#967e8e", "edge": "#ead4e0", "accent": accent,
                "accent_soft": "#f5dbe9", "accent_text": "#ffffff", "pet_bubble": "#f2eaf8",
                "user_bubble": "#f6dce9", "system_bubble": "#f3f0f5", "input": "#ffffff", "online": "#42b883"}
    return {"light": False, "bg": "#141824", "surface": "#1c2232", "surface2": "#252d40",
            "fg": "#edf0fa", "muted": "#9da7bd", "edge": "#343d54", "accent": accent,
            "accent_soft": "#393044", "accent_text": "#ffffff", "pet_bubble": "#252c40",
            "user_bubble": "#353047", "system_bubble": "#252938", "input": "#191f2d", "online": "#55cf95"}


def _petzhu_groupchat_set_role_v1(widget, role):
    try:
        widget._petzhu_groupchat_role_v1 = str(role)
    except Exception:
        pass
    return widget


def _petzhu_groupchat_walk_widgets_v1(root):
    result = []
    try:
        todo = list(root.winfo_children())
        while todo:
            child = todo.pop()
            result.append(child)
            try: todo.extend(child.winfo_children())
            except Exception: pass
    except Exception:
        pass
    return result


def _petzhu_groupchat_apply_palette_v1(win, palette):
    try:
        win.configure(bg=palette["bg"])
    except Exception:
        pass
    roles = {
        "bg": "bg", "surface": "surface", "surface2": "surface2", "fg": "fg",
        "muted": "muted", "edge": "edge", "accent": "accent", "accent_soft": "accent_soft",
        "pet_bubble": "pet_bubble", "user_bubble": "user_bubble", "system_bubble": "system_bubble",
        "input": "input", "avatar": "accent_soft", "online": "online", "accent_text": "accent_text",
    }
    for widget in [win] + _petzhu_groupchat_walk_widgets_v1(win):
        role = str(getattr(widget, "_petzhu_groupchat_role_v1", "bg"))
        color_key = roles.get(role, "bg")
        bg = palette.get(color_key, palette["bg"])
        try:
            if isinstance(widget, tk.Canvas):
                widget.configure(bg=bg, highlightbackground=palette["edge"], highlightcolor=palette["edge"])
            elif isinstance(widget, tk.Text):
                widget.configure(bg=bg, fg=palette["fg"], insertbackground=palette["fg"], selectbackground=palette["accent"], selectforeground="#ffffff")
            elif isinstance(widget, tk.Button):
                fg = palette["accent_text"] if role == "accent" else palette["fg"]
                widget.configure(bg=bg, fg=fg, activebackground=palette["accent"], activeforeground="#ffffff",
                                 highlightbackground=palette["edge"], bd=0, relief="flat")
            elif isinstance(widget, tk.Label):
                if role in ("avatar", "accent"):
                    fg = palette["accent_text"]
                elif role == "online":
                    fg = palette["online"]
                elif role in ("muted", "speaker_muted"):
                    fg = palette["muted"]
                elif role == "speaker_pet":
                    fg = palette["accent"]
                elif role == "speaker_user":
                    fg = palette["accent"]
                else:
                    fg = palette["fg"]
                widget.configure(bg=bg, fg=fg)
            elif isinstance(widget, tk.Frame):
                widget.configure(bg=bg, highlightbackground=palette["edge"])
            elif isinstance(widget, tk.Scrollbar):
                widget.configure(bg=palette["surface2"], troughcolor=palette["bg"], activebackground=palette["accent"])
            elif isinstance(widget, tk.OptionMenu):
                widget.configure(bg=bg, fg=palette["fg"], activebackground=palette["accent"], activeforeground="#ffffff", highlightthickness=0)
                try:
                    widget["menu"].configure(bg=palette["surface"], fg=palette["fg"], activebackground=palette["accent"], activeforeground="#ffffff")
                except Exception:
                    pass
        except Exception:
            pass


def _petzhu_groupchat_render_message_v1(app, win, inner, item, palette):
    if not win.winfo_exists():
        return None
    row = tk.Frame(inner, bg=palette["bg"])
    sender_type = str(item.get("sender_type", "system"))
    name = str(item.get("sender_name", "桌宠") or "桌宠")[:24]
    text_value = str(item.get("text", "") or "")[:1600]
    try:
        stamp = time.strftime("%H:%M", time.localtime(float(item.get("created_at", time.time()) or time.time())))
    except Exception:
        stamp = time.strftime("%H:%M")
    if sender_type == "user":
        row.pack(fill="x", padx=10, pady=4)
        right = tk.Frame(row, bg=palette["bg"])
        right.pack(side="right", anchor="e", padx=(42, 2))
        meta = tk.Label(right, text="你  ·  " + stamp, bg=palette["bg"], fg=palette["muted"], font=("微软雅黑", 8), anchor="e")
        _petzhu_groupchat_set_role_v1(meta, "muted"); meta.pack(anchor="e", pady=(0, 2))
        bubble = tk.Label(right, text=text_value, bg=palette["user_bubble"], fg=palette["fg"], justify="left", anchor="w",
                          wraplength=430, padx=11, pady=8, font=("微软雅黑", 9), bd=0, relief="flat")
        _petzhu_groupchat_set_role_v1(bubble, "user_bubble"); bubble.pack(anchor="e")
    elif sender_type == "system":
        row.pack(fill="x", padx=16, pady=5)
        bubble = tk.Label(row, text=text_value, bg=palette["system_bubble"], fg=palette["muted"], justify="center",
                          wraplength=500, padx=10, pady=5, font=("微软雅黑", 8), bd=0)
        _petzhu_groupchat_set_role_v1(bubble, "system_bubble"); bubble.pack(anchor="center")
    else:
        row.pack(fill="x", padx=10, pady=4)
        avatar = tk.Label(row, text=(name[:1] or "宠"), bg=palette["accent_soft"], fg=palette["accent"],
                          width=2, height=1, font=("微软雅黑", 10, "bold"), bd=0, padx=5, pady=5)
        _petzhu_groupchat_set_role_v1(avatar, "avatar"); avatar.pack(side="left", anchor="n", padx=(0, 7), pady=(16, 0))
        left = tk.Frame(row, bg=palette["bg"]); left.pack(side="left", anchor="w", fill="x", expand=True)
        meta = tk.Label(left, text=name + "  ·  " + stamp, bg=palette["bg"], fg=palette["accent"], font=("微软雅黑", 8), anchor="w")
        _petzhu_groupchat_set_role_v1(meta, "speaker_pet"); meta.pack(anchor="w", pady=(0, 2))
        bubble = tk.Label(left, text=text_value, bg=palette["pet_bubble"], fg=palette["fg"], justify="left", anchor="w",
                          wraplength=470, padx=11, pady=8, font=("微软雅黑", 9), bd=0, relief="flat")
        _petzhu_groupchat_set_role_v1(bubble, "pet_bubble"); bubble.pack(anchor="w")
    row._petzhu_groupchat_message_id_v1 = int(item.get("id", 0) or 0)
    return row


def _petzhu_groupchat_refresh_members_ui_v1(app, win, memberbar, palette):
    members = _petzhu_groupchat_get_members_v1(app)
    signature = tuple((str(m["id"]), str(m["name"]), bool(m["api_ready"])) for m in members)
    if signature == getattr(win, "_petzhu_groupchat_member_signature_v1", None):
        return
    win._petzhu_groupchat_member_signature_v1 = signature
    for child in list(memberbar.winfo_children()):
        try: child.destroy()
        except Exception: pass
    # 人类是固定成员；在线桌宠按当前注册表横向排列。
    human = tk.Frame(memberbar, bg=palette["surface"], padx=7, pady=4, highlightthickness=1, highlightbackground=palette["edge"])
    _petzhu_groupchat_set_role_v1(human, "surface"); human.pack(side="left", padx=(0, 5))
    av = tk.Label(human, text="你", width=2, bg=palette["accent_soft"], fg=palette["accent"], font=("微软雅黑", 9, "bold"))
    _petzhu_groupchat_set_role_v1(av, "avatar"); av.pack(side="left", padx=(0, 4))
    nm = tk.Label(human, text="你", bg=palette["surface"], fg=palette["fg"], font=("微软雅黑", 8, "bold"))
    _petzhu_groupchat_set_role_v1(nm, "fg"); nm.pack(side="left")
    for member in members:
        name = str(member.get("name", "桌宠") or "桌宠")[:24]
        chip = tk.Frame(memberbar, bg=palette["surface"], padx=7, pady=4, highlightthickness=1, highlightbackground=palette["edge"])
        _petzhu_groupchat_set_role_v1(chip, "surface"); chip.pack(side="left", padx=(0, 5))
        avatar = tk.Label(chip, text=(name[:1] or "宠"), width=2, bg=palette["accent_soft"], fg=palette["accent"], font=("微软雅黑", 9, "bold"))
        _petzhu_groupchat_set_role_v1(avatar, "avatar"); avatar.pack(side="left", padx=(0, 4))
        member_name = tk.Label(chip, text=name, bg=palette["surface"], fg=palette["fg"], font=("微软雅黑", 8, "bold"))
        _petzhu_groupchat_set_role_v1(member_name, "fg"); member_name.pack(side="left")
        if bool(member.get("api_ready")):
            dot = tk.Label(chip, text=" ●", bg=palette["surface"], fg=palette["online"], font=("微软雅黑", 7))
            _petzhu_groupchat_set_role_v1(dot, "online"); dot.pack(side="left")
        else:
            dot = tk.Label(chip, text=" · API未配", bg=palette["surface"], fg=palette["muted"], font=("微软雅黑", 7))
            _petzhu_groupchat_set_role_v1(dot, "muted"); dot.pack(side="left")


def _petzhu_groupchat_open_memories_v1(app, parent):
    palette = _petzhu_groupchat_palette_v1(app)
    win = tk.Toplevel(parent)
    win.title("桌宠群聊 · 自动整理的记忆")
    win.geometry("500x400")
    win.minsize(400, 300)
    win._petzhu_theme_hue_exempt = True
    box = tk.Text(win, wrap="word", bg=palette["surface"], fg=palette["fg"], insertbackground=palette["fg"], relief="flat", font=("微软雅黑", 9), padx=12, pady=10)
    _petzhu_groupchat_set_role_v1(box, "input"); box.pack(fill="both", expand=True, padx=12, pady=12)
    conn = _petzhu_groupchat_connect_v1(app)
    try:
        rows = conn.execute("SELECT p.name,m.memory,m.updated_at FROM gc_memories m LEFT JOIN gc_participants p ON p.profile_key=m.profile_key ORDER BY m.updated_at DESC LIMIT 100").fetchall()
    finally:
        conn.close()
    if not rows:
        box.insert("end", "还没有整理出长期记忆。\n重要的偏好、约定和共同经历会在聊天中自动记录。")
    else:
        seen = set()
        for row in rows:
            name = str(row[0] or "桌宠")
            memory = str(row[1] or "")
            key = (name, memory)
            if key in seen: continue
            seen.add(key)
            stamp = time.strftime("%Y-%m-%d %H:%M", time.localtime(float(row[2] or time.time())))
            box.insert("end", "%s · %s\n%s\n\n" % (name, stamp, memory))
    box.configure(state="disabled")
    _petzhu_groupchat_apply_palette_v1(win, palette)
    try: win.transient(parent); win.lift()
    except Exception: pass


def _petzhu_groupchat_open_v1(app):
    existing = getattr(app, "_petzhu_groupchat_win_v1", None)
    try:
        if existing is not None and existing.winfo_exists():
            existing.deiconify(); existing.lift(); existing.focus_force(); return
    except Exception:
        pass
    parent = getattr(app, "_api_win", None)
    try:
        if parent is None or not parent.winfo_exists(): parent = app.root
    except Exception:
        parent = app.root
    palette = _petzhu_groupchat_palette_v1(app)
    win = tk.Toplevel(parent)
    app._petzhu_groupchat_win_v1 = win
    win.title("PETZhu · 桌宠群聊")
    win.geometry("760x650")
    win.minsize(620, 500)
    win._petzhu_theme_hue_exempt = True
    win._petzhu_groupchat_active_v1 = True
    palette_signature = (bool(palette["light"]), palette["accent"])

    header = tk.Frame(win, bg=palette["bg"], padx=12, pady=10)
    _petzhu_groupchat_set_role_v1(header, "bg"); header.pack(fill="x")
    title_row = tk.Frame(header, bg=palette["bg"])
    _petzhu_groupchat_set_role_v1(title_row, "bg"); title_row.pack(fill="x")
    title = tk.Label(title_row, text="我们的群聊", bg=palette["bg"], fg=palette["fg"], font=("微软雅黑", 13, "bold"), anchor="w")
    _petzhu_groupchat_set_role_v1(title, "fg"); title.pack(side="left")
    subtitle = tk.Label(title_row, text="同一台电脑上的桌宠都可以加入", bg=palette["bg"], fg=palette["muted"], font=("微软雅黑", 8), anchor="w")
    _petzhu_groupchat_set_role_v1(subtitle, "muted"); subtitle.pack(side="left", padx=(10, 0))
    memories_btn = tk.Button(title_row, text="群聊记忆", command=lambda a=app, p=win: _petzhu_groupchat_open_memories_v1(a, p), bg=palette["surface2"], fg=palette["fg"], font=("微软雅黑", 8), padx=9, pady=4)
    _petzhu_groupchat_set_role_v1(memories_btn, "surface2"); memories_btn.pack(side="right")
    memberbar = tk.Frame(header, bg=palette["bg"])
    _petzhu_groupchat_set_role_v1(memberbar, "bg"); memberbar.pack(fill="x", pady=(9, 0))

    outer = tk.Frame(win, bg=palette["bg"], padx=10, pady=0)
    _petzhu_groupchat_set_role_v1(outer, "bg"); outer.pack(fill="both", expand=True, pady=(0, 8))
    mode_row = tk.Frame(outer, bg=palette["bg"])
    _petzhu_groupchat_set_role_v1(mode_row, "bg"); mode_row.pack(fill="x", pady=(2, 7))
    mode_var = tk.StringVar(value="free")
    mode_buttons = {}
    target_var = tk.StringVar(value="选择成员")
    target_map = {}
    target_menu = tk.OptionMenu(mode_row, target_var, "选择成员")
    _petzhu_groupchat_set_role_v1(target_menu, "surface2")
    target_menu.configure(font=("微软雅黑", 8), padx=4, pady=2, highlightthickness=0)

    def update_modes():
        current = mode_var.get()
        for key, button in mode_buttons.items():
            is_on = key == current
            try:
                button.configure(bg=palette["accent"] if is_on else palette["surface2"],
                                 fg="#ffffff" if is_on else palette["fg"])
            except Exception: pass
        try:
            target_menu.configure(state=("normal" if current == "mention" else "disabled"))
        except Exception: pass
        try:
            hint.configure(text={"free": "自由群聊：桌宠可以自然接话，也能根据话题自行开启聊天。",
                                 "mention": "@点名：只让选中的桌宠回复。",
                                 "all": "全员讨论：在线桌宠按顺序各说一次。"}.get(current, ""))
        except Exception: pass

    for key, label in (("free", "自由群聊"), ("mention", "@点名"), ("all", "全员讨论")):
        button = tk.Button(mode_row, text=label, command=lambda k=key: (mode_var.set(k), update_modes()),
                           bg=palette["surface2"], fg=palette["fg"], activebackground=palette["accent"],
                           activeforeground="#ffffff", font=("微软雅黑", 8), padx=10, pady=4, bd=0, relief="flat")
        _petzhu_groupchat_set_role_v1(button, "surface2")
        button.pack(side="left", padx=(0, 5))
        mode_buttons[key] = button
    target_menu.pack(side="left", padx=(3, 0))
    chat_area = tk.Frame(outer, bg=palette["surface"], highlightthickness=1, highlightbackground=palette["edge"])
    _petzhu_groupchat_set_role_v1(chat_area, "surface"); chat_area.pack(fill="both", expand=True)
    canvas = tk.Canvas(chat_area, bg=palette["bg"], highlightthickness=0, bd=0)
    _petzhu_groupchat_set_role_v1(canvas, "bg")
    scrollbar = tk.Scrollbar(chat_area, orient="vertical", command=canvas.yview)
    _petzhu_groupchat_set_role_v1(scrollbar, "surface2")
    canvas.configure(yscrollcommand=scrollbar.set)
    scrollbar.pack(side="right", fill="y")
    canvas.pack(side="left", fill="both", expand=True)
    inner = tk.Frame(canvas, bg=palette["bg"])
    _petzhu_groupchat_set_role_v1(inner, "bg")
    inner_window = canvas.create_window((0, 0), window=inner, anchor="nw")
    inner.bind("<Configure>", lambda _e, c=canvas: c.configure(scrollregion=c.bbox("all")))
    canvas.bind("<Configure>", lambda event, c=canvas, item=inner_window: c.itemconfigure(item, width=event.width))
    def wheel(event, c=canvas):
        try: c.yview_scroll(int(-1 * (event.delta / 120)), "units")
        except Exception: pass
        return "break"
    canvas.bind("<MouseWheel>", wheel)

    hint = tk.Label(outer, text="", bg=palette["bg"], fg=palette["muted"], font=("微软雅黑", 8), anchor="w")
    _petzhu_groupchat_set_role_v1(hint, "muted"); hint.pack(fill="x", pady=(6, 4))
    input_border = tk.Frame(outer, bg=palette["edge"], padx=1, pady=1)
    _petzhu_groupchat_set_role_v1(input_border, "edge"); input_border.pack(fill="x")
    input_box = tk.Text(input_border, height=3, wrap="word", bg=palette["input"], fg=palette["fg"], insertbackground=palette["fg"],
                        relief="flat", bd=0, font=("微软雅黑", 9), padx=9, pady=7, undo=True)
    _petzhu_groupchat_set_role_v1(input_box, "input"); input_box.pack(fill="x")
    bottom = tk.Frame(outer, bg=palette["bg"])
    _petzhu_groupchat_set_role_v1(bottom, "bg"); bottom.pack(fill="x", pady=(7, 0))
    notice = tk.Label(bottom, text="重要偏好和共同经历会自动整理到相关桌宠的记忆中。", bg=palette["bg"], fg=palette["muted"], font=("微软雅黑", 8), anchor="w")
    _petzhu_groupchat_set_role_v1(notice, "muted"); notice.pack(side="left", fill="x", expand=True)
    send_button = tk.Button(bottom, text="发送  ↗", bg=palette["accent"], fg="#ffffff", activebackground=palette["accent"],
                            activeforeground="#ffffff", bd=0, relief="flat", font=("微软雅黑", 9, "bold"), padx=18, pady=6)
    _petzhu_groupchat_set_role_v1(send_button, "accent"); send_button.pack(side="right")

    win._petzhu_groupchat_rows_v1 = []
    win._petzhu_groupchat_cursor_v1 = 0
    win._petzhu_groupchat_palette_signature_v1 = palette_signature
    win._petzhu_groupchat_refs_v1 = {"memberbar": memberbar, "canvas": canvas, "inner": inner, "hint": hint,
                                     "input": input_box, "mode_var": mode_var, "target_var": target_var,
                                     "target_map": target_map, "target_menu": target_menu, "update_modes": update_modes,
                                     "notice": notice}

    def populate_targets():
        try:
            members = _petzhu_groupchat_get_members_v1(app, api_only=True)
            displays = []
            fresh_map = {}
            for m in members:
                display = "%s · %s" % (str(m["name"])[:18], str(m["id"])[-4:])
                displays.append(display)
                fresh_map[display] = str(m["id"])
            signature = tuple((d, fresh_map[d]) for d in displays)
            target_map.clear(); target_map.update(fresh_map)
            if signature == getattr(win, "_petzhu_groupchat_target_signature_v1", None):
                if target_var.get() not in target_map and displays:
                    target_var.set(displays[0])
                return
            win._petzhu_groupchat_target_signature_v1 = signature
            menu = target_menu["menu"]
            menu.delete(0, "end")
            for display in displays:
                menu.add_command(label=display, command=lambda d=display: (target_var.set(d), mode_var.set("mention"), update_modes()))
            if target_var.get() not in target_map:
                target_var.set(displays[0] if displays else "没有可回复的桌宠")
            update_modes()
        except Exception:
            pass

    def send_message(event=None):
        value = input_box.get("1.0", "end-1c").strip()
        if not value:
            return "break"
        mode = mode_var.get()
        target_id = target_map.get(target_var.get(), "") if mode == "mention" else ""
        try:
            ok, reason = _petzhu_groupchat_send_user_v1(app, value, mode=mode, target_id=target_id)
        except Exception as exc:
            ok, reason = False, "群聊消息暂时没能保存：%s" % str(exc)[:160]
        if ok:
            input_box.delete("1.0", "end")
            hint.configure(text={"free": "已发送，桌宠们会接着聊。", "mention": "已发送给指定桌宠。", "all": "已发起全员讨论。"}.get(mode, "已发送。"))
        else:
            hint.configure(text=reason or "发送失败，请稍后再试。")
        return "break"

    send_button.configure(command=send_message)
    def on_return(event):
        if int(getattr(event, "state", 0) or 0) & 0x0001:
            return None  # Shift+Enter 换行
        return send_message(event)
    input_box.bind("<Return>", on_return)
    input_box.bind("<Control-Return>", send_message)

    def refresh_ui():
        if not win.winfo_exists() or bool(getattr(app, "_closing", False)):
            return
        try:
            current_palette = _petzhu_groupchat_palette_v1(app)
            signature = (bool(current_palette["light"]), current_palette["accent"])
            if signature != getattr(win, "_petzhu_groupchat_palette_signature_v1", None):
                win._petzhu_groupchat_palette_signature_v1 = signature
                _petzhu_groupchat_apply_palette_v1(win, current_palette)
                # New messages use the latest accent after a star-theme change.
                palette.clear(); palette.update(current_palette)
                update_modes()
            _petzhu_groupchat_refresh_members_ui_v1(app, win, memberbar, palette)
            populate_targets()
            new_messages = _petzhu_groupchat_fetch_messages_v1(app, int(getattr(win, "_petzhu_groupchat_cursor_v1", 0) or 0), 200)
            for item in new_messages:
                row = _petzhu_groupchat_render_message_v1(app, win, inner, item, palette)
                if row is not None:
                    win._petzhu_groupchat_rows_v1.append((int(item.get("id", 0) or 0), row))
                    win._petzhu_groupchat_cursor_v1 = max(int(getattr(win, "_petzhu_groupchat_cursor_v1", 0) or 0), int(item.get("id", 0) or 0))
            while len(win._petzhu_groupchat_rows_v1) > 120:
                _, old_row = win._petzhu_groupchat_rows_v1.pop(0)
                try: old_row.destroy()
                except Exception: pass
            if new_messages:
                canvas.update_idletasks(); canvas.yview_moveto(1.0)
            if bool(getattr(app, "_context_palette_light", True)):
                notice.configure(text="重要偏好和共同经历会自动整理到相关桌宠的记忆中。")
            win._petzhu_groupchat_after_v1 = win.after(700, refresh_ui)
        except tk.TclError:
            return
        except Exception:
            try: win._petzhu_groupchat_after_v1 = win.after(1200, refresh_ui)
            except Exception: pass

    # Load a compact recent history before polling for new messages.
    try:
        history = _petzhu_groupchat_fetch_messages_v1(app, 0, 1000)[-80:]
        for item in history:
            row = _petzhu_groupchat_render_message_v1(app, win, inner, item, palette)
            if row is not None:
                win._petzhu_groupchat_rows_v1.append((int(item.get("id", 0) or 0), row))
                win._petzhu_groupchat_cursor_v1 = max(win._petzhu_groupchat_cursor_v1, int(item.get("id", 0) or 0))
    except Exception:
        pass
    _petzhu_groupchat_refresh_members_ui_v1(app, win, memberbar, palette)
    populate_targets(); update_modes()
    _petzhu_groupchat_apply_palette_v1(win, palette)
    win.protocol("WM_DELETE_WINDOW", lambda w=win, a=app: _petzhu_groupchat_close_window_v1(a, w))
    try:
        win.transient(parent)
        win.lift()
        win.focus_force()
    except Exception:
        pass
    try: canvas.update_idletasks(); canvas.yview_moveto(1.0)
    except Exception: pass
    refresh_ui()


def _petzhu_groupchat_close_window_v1(app, win):
    try:
        after_id = getattr(win, "_petzhu_groupchat_after_v1", None)
        if after_id:
            try: win.after_cancel(after_id)
            except Exception: pass
        win.destroy()
    except Exception:
        pass
    if getattr(app, "_petzhu_groupchat_win_v1", None) is win:
        app._petzhu_groupchat_win_v1 = None


def _petzhu_groupchat_tick_v1(app):
    if bool(getattr(app, "_closing", False)) or bool(getattr(app, "_petzhu_groupchat_stopped_v1", False)):
        return
    try:
        _petzhu_groupchat_heartbeat_v1(app)
    except Exception as exc:
        if not getattr(app, "_petzhu_groupchat_error_shown_v1", False):
            app._petzhu_groupchat_error_shown_v1 = True
            # 群聊是附加功能，数据库不可用时不要影响桌宠本身。
            try: app._petzhu_groupchat_error_v1 = str(exc)[:200]
            except Exception: pass
    try:
        result_queue = getattr(app, "_petzhu_groupchat_result_queue_v1", None)
        while result_queue is not None:
            result = result_queue.get_nowait()
            job, raw_reply, error = result
            _petzhu_groupchat_finish_job_v1(app, job, raw_reply, error)
            app._petzhu_groupchat_busy_v1 = False
    except queue.Empty:
        pass
    except Exception:
        app._petzhu_groupchat_busy_v1 = False
    if not bool(getattr(app, "_petzhu_groupchat_busy_v1", False)):
        try:
            job = _petzhu_groupchat_claim_job_v1(app)
        except Exception:
            job = None
        if job:
            app._petzhu_groupchat_busy_v1 = True
            threading.Thread(target=_petzhu_groupchat_generate_worker_v1, args=(app, job),
                             name="PETZhuGroupChatAI", daemon=True).start()
    try:
        delay_ms = 220 if _petzhu_groupchat_has_pending_segments_v79(app) else 850
        app.root.after(delay_ms, lambda a=app: _petzhu_groupchat_tick_v1(a))
    except Exception:
        pass


def _petzhu_groupchat_boot_v1(app):
    try:
        app._petzhu_groupchat_db_path_v1 = _petzhu_groupchat_db_path_v1()
        app._petzhu_groupchat_profile_key_v1 = _petzhu_groupchat_profile_key_v1(app)
        app._petzhu_groupchat_started_at_v1 = time.time()
        app._petzhu_groupchat_id_v1 = "%s-%s-%s" % (
            app._petzhu_groupchat_profile_key_v1, os.getpid(), uuid.uuid4().hex[:8])
        app._petzhu_groupchat_result_queue_v1 = queue.Queue()
        app._petzhu_groupchat_busy_v1 = False
        app._petzhu_groupchat_stopped_v1 = False
        app._petzhu_groupchat_win_v1 = None
        _petzhu_groupchat_init_db_v1(app)
        _petzhu_groupchat_heartbeat_v1(app)
        app.root.after(850, lambda a=app: _petzhu_groupchat_tick_v1(a))
    except Exception as exc:
        app._petzhu_groupchat_error_v1 = str(exc)[:240]


def _petzhu_groupchat_shutdown_v1(app):
    try:
        app._petzhu_groupchat_stopped_v1 = True
        conn = _petzhu_groupchat_connect_v1(app)
        try:
            conn.execute("UPDATE gc_participants SET last_seen=0 WHERE id=?", (str(app._petzhu_groupchat_id_v1),))
            conn.execute("UPDATE gc_jobs SET status='skipped',lease_until=0 WHERE participant_id=? AND status IN ('pending','working')",
                         (str(app._petzhu_groupchat_id_v1),))
        finally:
            conn.close()
    except Exception:
        pass
    win = getattr(app, "_petzhu_groupchat_win_v1", None)
    if win is not None:
        try: _petzhu_groupchat_close_window_v1(app, win)
        except Exception: pass


def _petzhu_groupchat_show_api_button_v1(app):
    win = getattr(app, "_api_win", None)
    try:
        if win is None or not win.winfo_exists():
            return
        if bool(getattr(win, "_petzhu_groupchat_button_added_v1", False)):
            return
        stack = [win]
        title_label = None
        while stack:
            widget = stack.pop()
            try:
                if isinstance(widget, tk.Label) and str(widget.cget("text")) == "房间群聊":
                    title_label = widget
                    break
                stack.extend(widget.winfo_children())
            except Exception:
                pass
        if title_label is None:
            # 兼容标题因旧主题包装而变形的情况：优先从联机右侧聊天控件定位父容器。
            chat_widget = (getattr(app, "_mp_ui", {}) or {}).get("chat")
            if chat_widget is not None and chat_widget.winfo_exists():
                parent = chat_widget.master
            else:
                return
        else:
            parent = title_label.master
        chat_widget = (getattr(app, "_mp_ui", {}) or {}).get("chat")
        if chat_widget is None or not chat_widget.winfo_exists():
            return
        palette = _petzhu_groupchat_palette_v1(app)
        button = tk.Button(parent, text="打开桌宠群聊…", command=lambda a=app: _petzhu_groupchat_open_v1(a),
                           bg=palette["accent"], fg="#ffffff", activebackground=palette["accent"],
                           activeforeground="#ffffff", bd=0, relief="flat", padx=8, pady=3,
                           font=("微软雅黑", 8, "bold"), cursor="hand2")
        button.pack(fill="x", before=chat_widget, pady=(3, 4))
        win._petzhu_groupchat_button_added_v1 = True
    except Exception:
        pass


def _petzhu_groupchat_show_api_wrapper_v1(self, *args, **kwargs):
    result = _PETZHU_GROUPCHAT_PREVIOUS_SHOW_API_V1(self, *args, **kwargs)
    try:
        self.root.after(250, lambda a=self: _petzhu_groupchat_show_api_button_v1(a))
        self.root.after(900, lambda a=self: _petzhu_groupchat_show_api_button_v1(a))
    except Exception:
        pass
    return result


def _petzhu_groupchat_init_wrapper_v1(self, root):
    _PETZHU_GROUPCHAT_PREVIOUS_INIT_V1(self, root)
    _petzhu_groupchat_boot_v1(self)


def _petzhu_groupchat_quit_wrapper_v1(self, *args, **kwargs):
    try:
        _petzhu_groupchat_shutdown_v1(self)
    except Exception:
        pass
    return _PETZHU_GROUPCHAT_PREVIOUS_QUIT_V1(self, *args, **kwargs)


