# ============================================================
# v67: 桌宠群聊 UI / 名称隔离 / 独立顶层窗口修复
# ============================================================

_PETZHU_GROUPCHAT_OPEN_WINDOWS_V67 = weakref.WeakSet()
_PETZHU_GROUPCHAT_PREVIOUS_APPLY_HUE_V67 = _petzhu_apply_global_theme_hue


def _petzhu_groupchat_palette_v1(app):
    # 色相预览期间以全局实时值为准；提交设置后 app.theme_hue 也会保持一致。
    light = bool(getattr(app, "_context_palette_light", True))
    try:
        hue = int(_PETZHU_THEME_HUE_STATE.get("hue", getattr(app, "theme_hue", 330))) % 360
    except Exception:
        try: hue = int(getattr(app, "theme_hue", 330)) % 360
        except Exception: hue = 330
    rr, gg, bb = colorsys.hsv_to_rgb(hue / 360.0, 0.58, 0.88)
    accent = "#%02x%02x%02x" % (round(rr * 255), round(gg * 255), round(bb * 255))
    luminance = 0.2126 * rr + 0.7152 * gg + 0.0722 * bb
    accent_text = "#211923" if luminance > 0.64 else "#ffffff"
    if light:
        return {"light": True, "bg": "#f8f6fa", "surface": "#ffffff", "surface2": "#f1edf5",
                "fg": "#302a38", "muted": "#817889", "edge": "#ded7e6", "accent": accent,
                "accent_soft": "#f0e3f5", "accent_text": accent_text, "pet_bubble": "#f2edf8",
                "user_bubble": "#f3dfee", "system_bubble": "#f0edf3", "input": "#ffffff", "online": "#239b6b"}
    return {"light": False, "bg": "#121622", "surface": "#1a2030", "surface2": "#252c40",
            "fg": "#edf0fa", "muted": "#a2abc0", "edge": "#343d54", "accent": accent,
            "accent_soft": "#343044", "accent_text": accent_text, "pet_bubble": "#242b3e",
            "user_bubble": "#343047", "system_bubble": "#222837", "input": "#171d2b", "online": "#55d49b"}


# Share each instance's own normal-pose image path so this PC can show the correct pet avatar.
_PETZHU_GROUPCHAT_PREVIOUS_INIT_DB_V67 = _petzhu_groupchat_init_db_v1
_PETZHU_GROUPCHAT_PREVIOUS_HEARTBEAT_V67 = _petzhu_groupchat_heartbeat_v1
_PETZHU_GROUPCHAT_PREVIOUS_FETCH_MESSAGES_V67 = _petzhu_groupchat_fetch_messages_v1


def _petzhu_groupchat_init_db_v1(app):
    _PETZHU_GROUPCHAT_PREVIOUS_INIT_DB_V67(app)
    conn = _petzhu_groupchat_connect_v1(app)
    try:
        columns = {str(row[1]) for row in conn.execute("PRAGMA table_info(gc_participants)").fetchall()}
        if "avatar_path" not in columns:
            conn.execute("ALTER TABLE gc_participants ADD COLUMN avatar_path TEXT NOT NULL DEFAULT ''")
    finally:
        conn.close()


def _petzhu_groupchat_local_avatar_path_v67(app):
    for key in ("normal", "talk", "pat"):
        try:
            path = str(app._persona_sprite_path(key) or "").strip()
        except Exception:
            path = ""
        if path and os.path.isfile(path):
            return os.path.abspath(path)
    return ""


def _petzhu_groupchat_heartbeat_v1(app):
    _PETZHU_GROUPCHAT_PREVIOUS_HEARTBEAT_V67(app)
    try:
        avatar_path = _petzhu_groupchat_local_avatar_path_v67(app)
        conn = _petzhu_groupchat_connect_v1(app)
        try:
            conn.execute("UPDATE gc_participants SET avatar_path=? WHERE id=?",
                         (avatar_path, str(getattr(app, "_petzhu_groupchat_id_v1", ""))))
        finally:
            conn.close()
    except Exception:
        pass


def _petzhu_groupchat_fetch_messages_v1(app, after_id=0, limit=100):
    conn = _petzhu_groupchat_connect_v1(app)
    try:
        rows = conn.execute("""
            SELECT m.*, COALESCE(p.avatar_path,'') AS sender_avatar_path
            FROM gc_messages m LEFT JOIN gc_participants p ON p.id=m.sender_id
            WHERE m.id>? ORDER BY m.id LIMIT ?
        """, (int(after_id), int(limit))).fetchall()
        return [dict(row) for row in rows]
    finally:
        conn.close()


def _petzhu_groupchat_avatar_photo_v67(win, path, size=42):
    path = str(path or "").strip()
    if not path or not os.path.isfile(path):
        return None
    try:
        cache = getattr(win, "_petzhu_groupchat_avatar_cache_v67", None)
        if not isinstance(cache, dict):
            cache = {}
            win._petzhu_groupchat_avatar_cache_v67 = cache
        stat = os.stat(path)
        key = (os.path.normcase(os.path.abspath(path)), int(size), int(stat.st_mtime_ns), int(stat.st_size))
        if key in cache:
            return cache[key]
        with Image.open(path) as opened:
            image = opened.convert("RGBA")
        resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS", getattr(Image, "LANCZOS", 1))
        image.thumbnail((int(size), int(size)), resampling)
        # Keep a square, transparent canvas so custom portrait/sprite sizes line up in a row.
        try:
            canvas_image = Image.new("RGBA", (int(size), int(size)), (0, 0, 0, 0))
            canvas_image.alpha_composite(image, ((int(size) - image.width) // 2, (int(size) - image.height) // 2))
            image = canvas_image
        except Exception:
            pass
        photo = ImageTk.PhotoImage(image, master=win)
        cache[key] = photo
        # Bound the in-window image cache in case persona art changes during a long session.
        while len(cache) > 64:
            cache.pop(next(iter(cache)))
        return photo
    except Exception:
        return None


_PETZHU_GROUPCHAT_BG_ROLES_V67 = {
    "bg", "surface", "surface2", "edge", "accent", "accent_soft",
    "pet_bubble", "user_bubble", "system_bubble", "input", "avatar"
}
_PETZHU_GROUPCHAT_FG_ROLES_V67 = {"fg", "muted", "online", "speaker_pet", "speaker_user"}


def _petzhu_groupchat_set_role_v1(widget, role):
    role = str(role)
    try:
        widget._petzhu_groupchat_role_v1 = role
        # 语义角色只代表文字颜色时，背景继承最近的有背景语义的父容器。
        if role in _PETZHU_GROUPCHAT_FG_ROLES_V67:
            current = getattr(widget, "master", None)
            bg_role = "bg"
            seen = set()
            for _ in range(64):
                if current is None or id(current) in seen:
                    break
                seen.add(id(current))
                candidate = str(getattr(current, "_petzhu_groupchat_role_v1", "bg"))
                if candidate in _PETZHU_GROUPCHAT_BG_ROLES_V67:
                    bg_role = candidate
                    break
                current = getattr(current, "master", None)
            widget._petzhu_groupchat_bg_role_v67 = bg_role
        elif role in _PETZHU_GROUPCHAT_BG_ROLES_V67:
            widget._petzhu_groupchat_bg_role_v67 = role
    except Exception:
        pass
    return widget


def _petzhu_groupchat_walk_widgets_v1(root):
    result = []
    try:
        todo = list(root.winfo_children())
        while todo:
            child = todo.pop()
            result.append(child)
            try: todo.extend(child.winfo_children())
            except Exception: pass
    except Exception:
        pass
    return result


def _petzhu_groupchat_apply_palette_v1(win, palette):
    try: win.configure(bg=palette["bg"])
    except Exception: pass
    for widget in [win] + _petzhu_groupchat_walk_widgets_v1(win):
        role = str(getattr(widget, "_petzhu_groupchat_role_v1", "bg"))
        if role in _PETZHU_GROUPCHAT_BG_ROLES_V67:
            bg_role = "accent_soft" if role == "avatar" else role
        else:
            bg_role = str(getattr(widget, "_petzhu_groupchat_bg_role_v67", "bg"))
        bg = palette.get(bg_role, palette["bg"])
        if role == "fg": fg = palette["fg"]
        elif role == "muted": fg = palette["muted"]
        elif role == "online": fg = palette["online"]
        elif role in ("speaker_pet", "speaker_user", "avatar"): fg = palette["accent"]
        elif role == "accent": fg = palette["accent_text"]
        else: fg = palette["fg"]
        try:
            if isinstance(widget, tk.Canvas):
                widget.configure(bg=bg, highlightbackground=palette["edge"], highlightcolor=palette["edge"])
            elif isinstance(widget, tk.Text):
                widget.configure(bg=bg, fg=palette["fg"], insertbackground=palette["fg"],
                                 selectbackground=palette["accent"], selectforeground=palette["accent_text"])
            elif isinstance(widget, tk.Button):
                button_fg = palette["accent_text"] if role == "accent" else palette["fg"]
                widget.configure(bg=bg, fg=button_fg, activebackground=palette["accent"],
                                 activeforeground=palette["accent_text"], highlightbackground=palette["edge"],
                                 bd=0, relief="flat")
            elif isinstance(widget, tk.Label):
                widget.configure(bg=bg, fg=fg)
            elif isinstance(widget, tk.Frame):
                widget.configure(bg=bg, highlightbackground=palette["edge"])
            elif isinstance(widget, tk.Scrollbar):
                widget.configure(bg=palette["surface2"], troughcolor=palette["bg"], activebackground=palette["accent"])
            elif isinstance(widget, tk.OptionMenu):
                widget.configure(bg=bg, fg=palette["fg"], activebackground=palette["accent"],
                                 activeforeground=palette["accent_text"], highlightthickness=0)
                try:
                    widget["menu"].configure(bg=palette["surface"], fg=palette["fg"],
                                              activebackground=palette["accent"], activeforeground=palette["accent_text"])
                except Exception: pass
        except Exception:
            pass


def _petzhu_groupchat_render_message_v1(app, win, inner, item, palette):
    if not win.winfo_exists(): return None
    sender_type = str(item.get("sender_type", "system"))
    name = str(item.get("sender_name", "桌宠") or "桌宠")[:24]
    text_value = str(item.get("text", "") or "")[:2400]
    try: stamp = time.strftime("%H:%M", time.localtime(float(item.get("created_at", time.time()) or time.time())))
    except Exception: stamp = time.strftime("%H:%M")
    row = tk.Frame(inner, bg=palette["bg"])
    _petzhu_groupchat_set_role_v1(row, "bg")
    if sender_type == "user":
        row.pack(fill="x", padx=14, pady=6)
        spacer = tk.Frame(row, bg=palette["bg"]); _petzhu_groupchat_set_role_v1(spacer, "bg")
        spacer.pack(side="left", fill="x", expand=True)
        right = tk.Frame(row, bg=palette["bg"]); _petzhu_groupchat_set_role_v1(right, "bg")
        right.pack(side="right", anchor="e", padx=(30, 2))
        meta = tk.Label(right, text="你  ·  " + stamp, bg=palette["bg"], fg=palette["muted"],
                        font=("微软雅黑", 9), anchor="e")
        _petzhu_groupchat_set_role_v1(meta, "muted"); meta.pack(anchor="e", pady=(0, 4))
        bubble = tk.Label(right, text=text_value, bg=palette["user_bubble"], fg=palette["fg"], justify="left",
                          anchor="w", wraplength=500, padx=14, pady=10, font=("微软雅黑", 10), bd=0, relief="flat")
        _petzhu_groupchat_set_role_v1(bubble, "user_bubble"); bubble.pack(anchor="e")
    elif sender_type == "system":
        row.pack(fill="x", padx=18, pady=6)
        bubble = tk.Label(row, text=text_value, bg=palette["system_bubble"], fg=palette["muted"], justify="center",
                          wraplength=560, padx=12, pady=7, font=("微软雅黑", 9), bd=0)
        _petzhu_groupchat_set_role_v1(bubble, "system_bubble"); bubble.pack(anchor="center")
    else:
        row.pack(fill="x", padx=14, pady=6)
        avatar_photo = _petzhu_groupchat_avatar_photo_v67(win, item.get("sender_avatar_path", ""), 42)
        if avatar_photo is not None:
            avatar = tk.Label(row, image=avatar_photo, bg=palette["bg"], bd=0, padx=0, pady=0)
            avatar.image = avatar_photo
            _petzhu_groupchat_set_role_v1(avatar, "bg")
        else:
            avatar = tk.Label(row, text=(name[:1] or "宠"), bg=palette["accent_soft"], fg=palette["accent"],
                              width=2, height=1, font=("微软雅黑", 12, "bold"), bd=0, padx=7, pady=7)
            _petzhu_groupchat_set_role_v1(avatar, "avatar")
        avatar.pack(side="left", anchor="n", padx=(0, 9), pady=(18, 0))
        left = tk.Frame(row, bg=palette["bg"]); _petzhu_groupchat_set_role_v1(left, "bg")
        left.pack(side="left", anchor="w", fill="x", expand=True)
        meta = tk.Label(left, text=name + "  ·  " + stamp, bg=palette["bg"], fg=palette["accent"],
                        font=("微软雅黑", 9, "bold"), anchor="w")
        _petzhu_groupchat_set_role_v1(meta, "speaker_pet"); meta.pack(anchor="w", pady=(0, 4))
        bubble = tk.Label(left, text=text_value, bg=palette["pet_bubble"], fg=palette["fg"], justify="left",
                          anchor="w", wraplength=490, padx=14, pady=10, font=("微软雅黑", 10), bd=0, relief="flat")
        _petzhu_groupchat_set_role_v1(bubble, "pet_bubble"); bubble.pack(anchor="w")
    row._petzhu_groupchat_message_id_v1 = int(item.get("id", 0) or 0)
    return row


