def _petzhu_groupchat_sidebar_refresh_v67(app, win, members_frame, memories_frame, palette, force=False):
    """Refresh sidebar only when its data changes; keep static memory-note widgets alive during theme fades."""
    now = time.monotonic()
    if not force and now - float(getattr(win, "_petzhu_groupchat_sidebar_last_v67", 0) or 0) < 1.5:
        return
    win._petzhu_groupchat_sidebar_last_v67 = now

    # Member cards are rebuilt only when the roster signature changes.
    members = _petzhu_groupchat_get_members_v1(app)
    member_signature = tuple(
        (str(m.get("id")), str(m.get("name")), bool(m.get("api_ready")), str(m.get("avatar_path", "")))
        for m in members
    )
    if force or member_signature != getattr(win, "_petzhu_groupchat_sidebar_members_sig_v67", None):
        win._petzhu_groupchat_sidebar_members_sig_v67 = member_signature
        for child in list(members_frame.winfo_children()):
            try:
                child.destroy()
            except Exception:
                pass
        if not members:
            label = tk.Label(
                members_frame, text="目前没有其他在线桌宠。", bg=palette["surface"], fg=palette["muted"],
                anchor="w", justify="left", wraplength=205, font=("微软雅黑", 9)
            )
            _petzhu_groupchat_set_role_v1(label, "muted")
            label.pack(fill="x", padx=10, pady=7)
        for member in members:
            name = str(member.get("name", "桌宠") or "桌宠")[:24]
            card = tk.Frame(members_frame, bg=palette["surface"], padx=8, pady=7)
            _petzhu_groupchat_set_role_v1(card, "surface")
            card.pack(fill="x", padx=5, pady=2)
            avatar_photo = _petzhu_groupchat_avatar_photo_v67(win, member.get("avatar_path", ""), 38)
            if avatar_photo is not None:
                avatar = tk.Label(card, image=avatar_photo, bg=palette["surface"], bd=0, padx=0, pady=0)
                avatar.image = avatar_photo
                _petzhu_groupchat_set_role_v1(avatar, "surface")
            else:
                avatar = tk.Label(
                    card, text=name[:1] or "宠", bg=palette["accent_soft"], fg=palette["accent"],
                    width=2, font=("微软雅黑", 10, "bold"), padx=3, pady=4
                )
                _petzhu_groupchat_set_role_v1(avatar, "avatar")
            avatar.pack(side="left", padx=(0, 7))
            text_box = tk.Frame(card, bg=palette["surface"])
            _petzhu_groupchat_set_role_v1(text_box, "surface")
            text_box.pack(side="left", fill="x", expand=True)
            label = tk.Label(
                text_box, text=name, bg=palette["surface"], fg=palette["fg"],
                font=("微软雅黑", 9, "bold"), anchor="w"
            )
            _petzhu_groupchat_set_role_v1(label, "fg")
            label.pack(anchor="w")
            state = "在线 · API就绪" if bool(member.get("api_ready")) else "在线 · 未配置API"
            sub = tk.Label(
                text_box, text=state, bg=palette["surface"],
                fg=palette["online"] if bool(member.get("api_ready")) else palette["muted"],
                font=("微软雅黑", 8), anchor="w"
            )
            _petzhu_groupchat_set_role_v1(sub, "online" if bool(member.get("api_ready")) else "muted")
            sub.pack(anchor="w", pady=(1, 0))

    # Fetch the most recent memories. The previous implementation destroyed and recreated
    # this entire frame on every sidebar refresh, even when nothing changed. During the
    # 20ms theme animation frames that could expose an unpainted/default-color frame, making
    # only the explanatory empty-state label visibly blink. Keep widgets stable unless data differs.
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        try:
            rows = conn.execute("""
                SELECT m.memory, m.updated_at,
                       COALESCE((SELECT p.name FROM gc_participants p WHERE p.profile_key=m.profile_key ORDER BY p.last_seen DESC LIMIT 1),'桌宠') AS pet_name
                FROM gc_memories m ORDER BY m.updated_at DESC, m.id DESC LIMIT 4
            """).fetchall()
        finally:
            conn.close()
    except Exception:
        rows = []

    memory_signature = tuple((str(row[0] or ""), float(row[1] or 0), str(row[2] or "桌宠")) for row in rows)
    if force or memory_signature != getattr(win, "_petzhu_groupchat_sidebar_memory_sig_v75", None):
        win._petzhu_groupchat_sidebar_memory_sig_v75 = memory_signature
        for child in list(memories_frame.winfo_children()):
            try:
                child.destroy()
            except Exception:
                pass
        if not rows:
            empty = tk.Label(
                memories_frame,
                text="有意义的偏好、约定和共同经历会自动整理在这里。",
                bg=palette["surface"], fg=palette["muted"], justify="left", anchor="w",
                wraplength=205, font=("微软雅黑", 8)
            )
            _petzhu_groupchat_set_role_v1(empty, "muted")
            empty.pack(fill="x", padx=10, pady=8)
        else:
            for row in rows:
                pet_name = str(row[2] or "桌宠")[:20]
                memory = str(row[0] or "")[:115]
                stamp = time.strftime("%m-%d", time.localtime(float(row[1] or time.time())))
                item_frame = tk.Frame(memories_frame, bg=palette["surface"], padx=8, pady=6)
                _petzhu_groupchat_set_role_v1(item_frame, "surface")
                item_frame.pack(fill="x", padx=5, pady=2)
                meta = tk.Label(
                    item_frame, text=pet_name + " · " + stamp, bg=palette["surface"],
                    fg=palette["accent"], font=("微软雅黑", 8, "bold"), anchor="w"
                )
                _petzhu_groupchat_set_role_v1(meta, "speaker_pet")
                meta.pack(fill="x")
                body = tk.Label(
                    item_frame, text=memory, bg=palette["surface"], fg=palette["fg"],
                    justify="left", anchor="w", wraplength=200, font=("微软雅黑", 8)
                )
                _petzhu_groupchat_set_role_v1(body, "fg")
                body.pack(fill="x", pady=(3, 0))


def _petzhu_groupchat_open_memories_v1(app, parent):
    palette = _petzhu_groupchat_palette_v1(app)
    win = tk.Toplevel(parent)
    win.withdraw()  # 先设置完整配色，再显示记忆窗口。
    win._petzhu_groupchat_preserve_names_v1 = True
    win._petzhu_theme_hue_exempt = True
    win._petzhu_groupchat_active_v1 = True
    win._petzhu_groupchat_owner_app_v67 = app
    win._petzhu_groupchat_palette_v67 = dict(palette)
    win._petzhu_groupchat_palette_signature_v1 = (bool(palette["light"]), palette["accent"])
    try: _PETZHU_GROUPCHAT_OPEN_WINDOWS_V67.add(win)
    except Exception: pass
    win.title("桌宠群聊 · 自动整理的记忆")
    win.geometry("540x440")
    win.minsize(420, 320)
    outer = tk.Frame(win, bg=palette["bg"], padx=12, pady=12)
    _petzhu_groupchat_set_role_v1(outer, "bg"); outer.pack(fill="both", expand=True)
    box = tk.Text(outer, wrap="word", bg=palette["input"], fg=palette["fg"], insertbackground=palette["fg"],
                  relief="flat", font=("微软雅黑", 10), padx=12, pady=10)
    _petzhu_groupchat_set_role_v1(box, "input"); box.pack(fill="both", expand=True)
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        try:
            rows = conn.execute("""
                SELECT m.profile_key,m.memory,m.updated_at,
                       COALESCE((SELECT p.name FROM gc_participants p WHERE p.profile_key=m.profile_key ORDER BY p.last_seen DESC LIMIT 1),'桌宠') AS pet_name
                FROM gc_memories m ORDER BY m.updated_at DESC,m.id DESC LIMIT 200
            """).fetchall()
        finally: conn.close()
    except Exception:
        rows = []
    if not rows:
        box.insert("end", "还没有整理出长期记忆。\n重要的偏好、约定和共同经历会在聊天中自动记录。")
    else:
        seen = set()
        for row in rows:
            name = str(row[3] or "桌宠")
            memory = str(row[1] or "")
            key = (str(row[0]), memory)
            if key in seen: continue
            seen.add(key)
            stamp = time.strftime("%Y-%m-%d %H:%M", time.localtime(float(row[2] or time.time())))
            box.insert("end", "%s · %s\n%s\n\n" % (name, stamp, memory))
    box.configure(state="disabled")
    _petzhu_groupchat_apply_palette_v1(win, palette)
    try:
        win.update_idletasks()
        win.deiconify()
        win.update_idletasks()
        win.lift()
    except Exception: pass
    return win


def _petzhu_groupchat_open_v1(app):
    existing = getattr(app, "_petzhu_groupchat_win_v1", None)
    try:
        if existing is not None and existing.winfo_exists():
            # Window may have remained hidden while the theme changed; reapply the complete live palette before showing it.
            fresh_palette = _petzhu_groupchat_palette_v1(app)
            fresh_signature = (bool(fresh_palette["light"]), fresh_palette["accent"])
            stored_palette = getattr(existing, "_petzhu_groupchat_palette_v67", None)
            if isinstance(stored_palette, dict):
                stored_palette.clear(); stored_palette.update(fresh_palette)
            existing._petzhu_groupchat_palette_signature_v1 = fresh_signature
            _petzhu_groupchat_apply_palette_v1(existing, fresh_palette)
            refs = getattr(existing, "_petzhu_groupchat_refs_v1", {}) or {}
            if callable(refs.get("update_modes")): refs["update_modes"]()
            existing.update_idletasks()
            existing.deiconify(); existing.update_idletasks(); existing.lift(); existing.focus_force()
            return
    except Exception: pass

    # 关键：主群聊窗口属于 PETZhu 的主 Tk 根窗口，而不是 API/联机 Toplevel。
    # 不调用 transient，因此关闭 API 窗口不会连带隐藏或销毁群聊。
    root = getattr(app, "root", None)
    try:
        if root is None or not root.winfo_exists():
            root = tk._default_root
    except Exception:
        root = tk._default_root
    if root is None:
        raise RuntimeError("桌宠主窗口尚未初始化，无法打开群聊。")
    palette = _petzhu_groupchat_palette_v1(app)
    win = tk.Toplevel(root)
    win.withdraw()  # 首帧之前隐藏；所有控件创建并应用最终色板后再显示。
    win._petzhu_groupchat_preserve_names_v1 = True
    win._petzhu_theme_hue_exempt = True
    win._petzhu_groupchat_active_v1 = True
    win._petzhu_groupchat_owner_app_v67 = app
    app._petzhu_groupchat_win_v1 = win
    win.title("PETZhu · 桌宠群聊")
    win.geometry("1020x700")
    win.minsize(850, 590)
    win.configure(bg=palette["bg"])
    _PETZHU_GROUPCHAT_OPEN_WINDOWS_V67.add(win)
    palette_signature = (bool(palette["light"]), palette["accent"])

    outer = tk.Frame(win, bg=palette["bg"], padx=12, pady=10)
    _petzhu_groupchat_set_role_v1(outer, "bg"); outer.pack(fill="both", expand=True)

    # Header: compact identity, purpose, and one-click memory access.
    header = tk.Frame(outer, bg=palette["bg"])
    _petzhu_groupchat_set_role_v1(header, "bg"); header.pack(fill="x", pady=(0, 8))
    brand = tk.Label(header, text="✦", bg=palette["accent_soft"], fg=palette["accent"], width=2,
                     font=("微软雅黑", 15, "bold"), padx=8, pady=4)
    _petzhu_groupchat_set_role_v1(brand, "avatar"); brand.pack(side="left", padx=(0, 10))
    heading = tk.Frame(header, bg=palette["bg"]); _petzhu_groupchat_set_role_v1(heading, "bg")
    heading.pack(side="left", fill="x", expand=True)
    title = tk.Label(heading, text="桌宠群聊", bg=palette["bg"], fg=palette["fg"], font=("微软雅黑", 14, "bold"), anchor="w")
    _petzhu_groupchat_set_role_v1(title, "fg"); title.pack(anchor="w")
    subtitle = tk.Label(heading, text="你和本机在线桌宠一起聊天", bg=palette["bg"], fg=palette["muted"], font=("微软雅黑", 9), anchor="w")
    _petzhu_groupchat_set_role_v1(subtitle, "muted"); subtitle.pack(anchor="w", pady=(2, 0))
    memories_btn = tk.Button(header, text="✧  群聊记忆", command=lambda a=app, p=win: _petzhu_groupchat_open_memories_v1(a, p),
                             bg=palette["surface2"], fg=palette["fg"], activebackground=palette["accent"],
                             activeforeground=palette["accent_text"], font=("微软雅黑", 9), padx=12, pady=7, bd=0, relief="flat")
    _petzhu_groupchat_set_role_v1(memories_btn, "surface2"); memories_btn.pack(side="right", padx=(8, 0))

    # v84: group-chat text-size control; the selected size is read from the shared chat DB.
    font_container = tk.Frame(header, bg=palette["bg"])
    _petzhu_groupchat_set_role_v1(font_container, "bg")
    font_container.pack(side="right", padx=(8, 0))
    font_label = tk.Label(font_container, text="字号", bg=palette["bg"], fg=palette["muted"],
                          font=("微软雅黑", 9), anchor="e")
    _petzhu_groupchat_set_role_v1(font_label, "muted")
    font_label.pack(side="left", padx=(0, 4))
    font_size_var = tk.StringVar(master=win, value=_petzhu_groupchat_get_font_choice_v84(app))
    font_size_menu = tk.OptionMenu(
        font_container, font_size_var, "小", "中", "大", "特大",
        command=lambda choice, a=app, w=win, v=font_size_var: _petzhu_groupchat_set_font_choice_v84(a, w, choice, v),
    )
    _petzhu_groupchat_set_role_v1(font_size_menu, "surface2")
    font_size_menu.configure(font=("微软雅黑", 9), padx=4, pady=2, bd=0, relief="flat", highlightthickness=0,
                             bg=palette["surface2"], fg=palette["fg"], activebackground=palette["accent"],
                             activeforeground=palette["accent_text"])
    try:
        font_size_menu["menu"].configure(bg=palette["surface2"], fg=palette["fg"],
                                         activebackground=palette["accent"], activeforeground=palette["accent_text"])
    except Exception:
        pass
    font_size_menu.pack(side="left")

    memberbar = tk.Frame(outer, bg=palette["surface"], padx=8, pady=7, highlightthickness=1, highlightbackground=palette["edge"])
    _petzhu_groupchat_set_role_v1(memberbar, "surface"); memberbar.pack(fill="x", pady=(0, 10))

    body = tk.Frame(outer, bg=palette["bg"]); _petzhu_groupchat_set_role_v1(body, "bg")
    body.pack(fill="both", expand=True)
    # v87: use a two-column grid, not competing left/right pack expansion.
    # The sidebar occupies a dedicated fixed-width grid column; only the chat column expands.
    body.grid_rowconfigure(0, weight=1)
    body.grid_columnconfigure(0, weight=1, minsize=400)
    body.grid_columnconfigure(1, weight=0, minsize=250)
    chat_panel = tk.Frame(body, bg=palette["surface"], highlightthickness=1, highlightbackground=palette["edge"])
    _petzhu_groupchat_set_role_v1(chat_panel, "surface")
    sidebar = tk.Frame(body, bg=palette["surface"], width=250, highlightthickness=1, highlightbackground=palette["edge"])
    _petzhu_groupchat_set_role_v1(sidebar, "surface")
    # Prevent sidebar child requests (which change with font size/wrapping) from resizing the column.
    sidebar.configure(width=250)
    sidebar.pack_propagate(False)
    sidebar.grid_propagate(False)
    sidebar.grid(row=0, column=1, sticky="ns")
    chat_panel.grid(row=0, column=0, sticky="nsew", padx=(0, 9))

    # Conversation mode tabs and mention target.
    mode_row = tk.Frame(chat_panel, bg=palette["surface"], padx=10, pady=9)
    _petzhu_groupchat_set_role_v1(mode_row, "surface"); mode_row.pack(fill="x")
    mode_var = tk.StringVar(value="free")
    mode_buttons = {}
    target_var = tk.StringVar(value="选择成员")
    target_map = {}
    target_menu = tk.OptionMenu(mode_row, target_var, "选择成员")
    _petzhu_groupchat_set_role_v1(target_menu, "surface2")
    target_menu.configure(font=("微软雅黑", 9), padx=5, pady=3, highlightthickness=0)

    def update_modes():
        current = mode_var.get()
        for key, button in mode_buttons.items():
            role = "accent" if key == current else "surface2"
            _petzhu_groupchat_set_role_v1(button, role)
            try:
                button.configure(bg=palette["accent"] if key == current else palette["surface2"],
                                 fg=palette["accent_text"] if key == current else palette["fg"])
            except Exception: pass
        try: target_menu.configure(state=("normal" if current == "mention" else "disabled"))
        except Exception: pass
        text = {"free": "自由群聊　·　桌宠会判断消息是在对谁说，再决定是否接话。",
                "mention": "@点名　·　只由你选中的桌宠回复。",
                "all": "全员讨论　·　在线桌宠按顺序各说一次。"}.get(current, "")
        try: hint.configure(text=text)
        except Exception: pass

    update_modes = _petzhu_groupchat_name_safe_callback_v71(update_modes)

    for key, label in (("free", "自由群聊"), ("mention", "@ 点名"), ("all", "全员讨论")):
        button = tk.Button(mode_row, text=label, command=lambda k=key: (mode_var.set(k), update_modes()),
                           bg=palette["accent"] if key == "free" else palette["surface2"],
                           fg=palette["accent_text"] if key == "free" else palette["fg"],
                           activebackground=palette["accent"], activeforeground=palette["accent_text"],
                           font=("微软雅黑", 9, "bold"), padx=12, pady=6, bd=0, relief="flat", cursor="hand2")
        _petzhu_groupchat_set_role_v1(button, "accent" if key == "free" else "surface2")
        button.pack(side="left", padx=(0, 6))
        mode_buttons[key] = button
    target_menu.pack(side="left", padx=(2, 0))
    autochat_var = tk.BooleanVar(master=win, value=_petzhu_groupchat_autochat_enabled_v78(app))
    autochat_check = tk.Checkbutton(
        mode_row, text="允许桌宠自主聊天", variable=autochat_var,
        command=lambda a=app, v=autochat_var: _petzhu_groupchat_set_autochat_enabled_v78(a, bool(v.get())),
        bg=palette["surface"], fg=palette["fg"], activebackground=palette["surface"],
        activeforeground=palette["fg"], selectcolor=palette["surface2"],
        font=("微软雅黑", 8), bd=0, highlightthickness=0, padx=4,
    )
    _petzhu_groupchat_set_role_v1(autochat_check, "surface")
    autochat_check.pack(side="right", padx=(6, 0))

    chat_area = tk.Frame(chat_panel, bg=palette["bg"])
    _petzhu_groupchat_set_role_v1(chat_area, "bg"); chat_area.pack(fill="both", expand=True, padx=1, pady=(0, 1))
    canvas = tk.Canvas(chat_area, bg=palette["bg"], highlightthickness=0, bd=0)
    _petzhu_groupchat_set_role_v1(canvas, "bg")
    scrollbar = tk.Scrollbar(chat_area, orient="vertical", command=canvas.yview)
    _petzhu_groupchat_set_role_v1(scrollbar, "surface2")
    canvas.configure(yscrollcommand=scrollbar.set)
    scrollbar.pack(side="right", fill="y")
    canvas.pack(side="left", fill="both", expand=True)
    inner = tk.Frame(canvas, bg=palette["bg"]); _petzhu_groupchat_set_role_v1(inner, "bg")
    inner_window = canvas.create_window((0, 0), window=inner, anchor="nw")
    inner.bind("<Configure>", lambda _e, c=canvas: c.configure(scrollregion=c.bbox("all")))
    canvas.bind("<Configure>", lambda event, c=canvas, item=inner_window: c.itemconfigure(item, width=event.width))
    def wheel(event, c=canvas):
        try: c.yview_scroll(int(-1 * (event.delta / 120)), "units")
        except Exception: pass
        return "break"
    canvas.bind("<MouseWheel>", wheel)

    hint = tk.Label(chat_panel, text="", bg=palette["surface"], fg=palette["muted"], font=("微软雅黑", 8), anchor="w")
    _petzhu_groupchat_set_role_v1(hint, "muted"); hint.pack(fill="x", padx=12, pady=(5, 7))
    input_frame = tk.Frame(chat_panel, bg=palette["edge"], padx=1, pady=1)
    _petzhu_groupchat_set_role_v1(input_frame, "edge"); input_frame.pack(fill="x", padx=9, pady=(0, 9))
    input_box = tk.Text(input_frame, height=3, wrap="word", bg=palette["input"], fg=palette["fg"], insertbackground=palette["fg"],
                        relief="flat", bd=0, font=("微软雅黑", 10), padx=11, pady=8, undo=True)
    _petzhu_groupchat_set_role_v1(input_box, "input"); input_box.pack(fill="x")
    compose_row = tk.Frame(chat_panel, bg=palette["surface"], padx=10, pady=0)
    _petzhu_groupchat_set_role_v1(compose_row, "surface"); compose_row.pack(fill="x", pady=(0, 9))
    compose_hint = tk.Label(compose_row, text="Enter 发送 · Shift+Enter 换行", bg=palette["surface"], fg=palette["muted"], font=("微软雅黑", 8), anchor="w")
    _petzhu_groupchat_set_role_v1(compose_hint, "muted"); compose_hint.pack(side="left")
    send_button = tk.Button(compose_row, text="发送  ↗", bg=palette["accent"], fg=palette["accent_text"], activebackground=palette["accent"],
                            activeforeground=palette["accent_text"], bd=0, relief="flat", font=("微软雅黑", 9, "bold"), padx=20, pady=7, cursor="hand2")
    _petzhu_groupchat_set_role_v1(send_button, "accent"); send_button.pack(side="right")

    # Sidebar: member status and recent auto-collected memories.
    side_title = tk.Label(sidebar, text="群聊成员", bg=palette["surface"], fg=palette["fg"], font=("微软雅黑", 10, "bold"), anchor="w")
    _petzhu_groupchat_set_role_v1(side_title, "fg"); side_title.pack(fill="x", padx=12, pady=(12, 8))
    members_frame = tk.Frame(sidebar, bg=palette["surface"]); _petzhu_groupchat_set_role_v1(members_frame, "surface")
    members_frame.pack(fill="x", padx=5)
    separator = tk.Frame(sidebar, bg=palette["edge"], height=1); _petzhu_groupchat_set_role_v1(separator, "edge")
    separator.pack(fill="x", padx=10, pady=(10, 0))
    memory_title = tk.Label(sidebar, text="✧  自动整理的记忆", bg=palette["surface"], fg=palette["fg"], font=("微软雅黑", 10, "bold"), anchor="w")
    _petzhu_groupchat_set_role_v1(memory_title, "fg"); memory_title.pack(fill="x", padx=12, pady=(11, 5))
    memory_note = tk.Label(sidebar, text="每只桌宠只记录适合自己的经历。", bg=palette["surface"], fg=palette["muted"], font=("微软雅黑", 8), anchor="w", justify="left", wraplength=220)
    _petzhu_groupchat_set_role_v1(memory_note, "muted"); memory_note.pack(fill="x", padx=12, pady=(0, 5))
    memories_frame = tk.Frame(sidebar, bg=palette["surface"]); _petzhu_groupchat_set_role_v1(memories_frame, "surface")
    memories_frame.pack(fill="x", padx=5)
    view_memories_btn = tk.Button(sidebar, text="查看全部记忆", command=lambda a=app, p=win: _petzhu_groupchat_open_memories_v1(a, p),
                                  bg=palette["surface2"], fg=palette["fg"], activebackground=palette["accent"],
                                  activeforeground=palette["accent_text"], font=("微软雅黑", 8), padx=10, pady=5, bd=0, relief="flat")
    _petzhu_groupchat_set_role_v1(view_memories_btn, "surface2"); view_memories_btn.pack(side="bottom", fill="x", padx=10, pady=10)

    win._petzhu_groupchat_rows_v1 = []
    win._petzhu_groupchat_cursor_v1 = 0
    win._petzhu_groupchat_palette_signature_v1 = palette_signature
    win._petzhu_groupchat_palette_v67 = palette
    win._petzhu_groupchat_refs_v1 = {"body": body, "chat_panel": chat_panel, "sidebar": sidebar,
                                     "memberbar": memberbar, "canvas": canvas, "inner": inner, "hint": hint,
                                     "input": input_box, "mode_var": mode_var, "target_var": target_var,
                                     "target_map": target_map, "target_menu": target_menu, "update_modes": update_modes,
                                     "notice": memory_note, "members_frame": members_frame, "memories_frame": memories_frame,
                                     "autochat_var_v78": autochat_var, "autochat_check_v78": autochat_check,
                                     "font_container_v84": font_container,
                                     "font_size_var_v84": font_size_var, "font_size_menu_v84": font_size_menu}
    win._petzhu_groupchat_font_choice_v84 = font_size_var.get()

    def populate_targets():
        try:
            members = _petzhu_groupchat_get_members_v1(app, api_only=True)
            displays, fresh_map = [], {}
            for member in members:
                display = "%s · %s" % (str(member.get("name", "桌宠"))[:18], str(member.get("id", ""))[-4:])
                displays.append(display); fresh_map[display] = str(member["id"])
            signature = tuple((display, fresh_map[display]) for display in displays)
            target_map.clear(); target_map.update(fresh_map)
            if signature == getattr(win, "_petzhu_groupchat_target_signature_v1", None):
                if target_var.get() not in target_map and displays: target_var.set(displays[0])
                return
            win._petzhu_groupchat_target_signature_v1 = signature
            menu = target_menu["menu"]; menu.delete(0, "end")
            for display in displays:
                menu.add_command(label=display, command=lambda d=display: (target_var.set(d), mode_var.set("mention"), update_modes()))
            if target_var.get() not in target_map: target_var.set(displays[0] if displays else "没有可回复的桌宠")
            update_modes()
        except Exception: pass

    populate_targets = _petzhu_groupchat_name_safe_callback_v71(populate_targets)

    def send_message(event=None):
        value = input_box.get("1.0", "end-1c").strip()
        if not value: return "break"
        mode = mode_var.get()
        target_id = target_map.get(target_var.get(), "") if mode == "mention" else ""
        try: ok, reason = _petzhu_groupchat_send_user_v1(app, value, mode=mode, target_id=target_id)
        except Exception as exc: ok, reason = False, "群聊消息暂时没能保存：%s" % str(exc)[:160]
        if ok:
            input_box.delete("1.0", "end")
            hint.configure(text={"free": "已发送，桌宠们会接着聊。", "mention": "已发送给指定桌宠。", "all": "已发起全员讨论。"}.get(mode, "已发送。"))
        else: hint.configure(text=reason or "发送失败，请稍后再试。")
        return "break"

    send_message = _petzhu_groupchat_name_safe_callback_v71(send_message)
    send_button.configure(command=send_message)
    def on_return(event):
        if int(getattr(event, "state", 0) or 0) & 0x0001: return None
        return send_message(event)
    input_box.bind("<Return>", on_return)
    input_box.bind("<Control-Return>", send_message)

    def refresh_ui():
        if not win.winfo_exists(): return
        try:
            current_palette = _petzhu_groupchat_palette_v1(app)
            signature = (bool(current_palette["light"]), current_palette["accent"])
            if signature != getattr(win, "_petzhu_groupchat_palette_signature_v1", None):
                win._petzhu_groupchat_palette_signature_v1 = signature
                palette.clear(); palette.update(current_palette)
                _petzhu_groupchat_apply_palette_v1(win, palette)
                update_modes()
            _petzhu_groupchat_refresh_members_ui_v1(app, win, memberbar, palette)
            populate_targets()
            _petzhu_groupchat_sidebar_refresh_v67(app, win, members_frame, memories_frame, palette)
            # v100: 自动跟随由明确的用户滚动状态控制，而不是用 0.985 近似值猜测。
            # 用户只要向上滚动一格，就立即暂停自动拉回底部。
            was_at_bottom = bool(getattr(win, "_petzhu_groupchat_follow_latest_v100", True))
            new_messages = _petzhu_groupchat_fetch_messages_v1(app, int(getattr(win, "_petzhu_groupchat_cursor_v1", 0) or 0), 200)
            for item in new_messages:
                row = _petzhu_groupchat_render_message_v1(app, win, inner, item, palette)
                if row is not None:
                    win._petzhu_groupchat_rows_v1.append((int(item.get("id", 0) or 0), row))
                    win._petzhu_groupchat_cursor_v1 = max(int(getattr(win, "_petzhu_groupchat_cursor_v1", 0) or 0), int(item.get("id", 0) or 0))
            while len(win._petzhu_groupchat_rows_v1) > 120:
                _, old_row = win._petzhu_groupchat_rows_v1.pop(0)
                try: old_row.destroy()
                except Exception: pass
            if new_messages and was_at_bottom:
                canvas.update_idletasks(); canvas.yview_moveto(1.0)
            win._petzhu_groupchat_after_v1 = win.after(500, refresh_ui)
        except tk.TclError:
            return
        except Exception:
            try: win._petzhu_groupchat_after_v1 = win.after(1200, refresh_ui)
            except Exception: pass

    refresh_ui = _petzhu_groupchat_name_safe_callback_v71(refresh_ui)

    try:
        history = _petzhu_groupchat_fetch_messages_v1(app, 0, 1000)[-80:]
        for item in history:
            row = _petzhu_groupchat_render_message_v1(app, win, inner, item, palette)
            if row is not None:
                win._petzhu_groupchat_rows_v1.append((int(item.get("id", 0) or 0), row))
                win._petzhu_groupchat_cursor_v1 = max(win._petzhu_groupchat_cursor_v1, int(item.get("id", 0) or 0))
    except Exception: pass
    _petzhu_groupchat_refresh_members_ui_v1(app, win, memberbar, palette)
    populate_targets()
    _petzhu_groupchat_sidebar_refresh_v67(app, win, members_frame, memories_frame, palette, force=True)
    update_modes()
    _petzhu_groupchat_apply_palette_v1(win, palette)
    win.protocol("WM_DELETE_WINDOW", lambda w=win, a=app: _petzhu_groupchat_close_window_v1(a, w))
    # Deliberately no transient(parent): closing API/联机 Toplevel must not affect this window.
    try:
        # 窗口仍隐藏时先完成布局和全控件配色，防止默认粉色/系统底色闪现。
        win.update_idletasks()
        _petzhu_groupchat_apply_palette_v1(win, palette)
        _petzhu_groupchat_apply_font_size_v84(win, app, font_size_var.get(), include_tree=True)
        win.deiconify()
        win.update_idletasks()
        win.lift(); win.focus_force()
        canvas.update_idletasks(); canvas.yview_moveto(1.0)
    except Exception: pass
    refresh_ui()


def _petzhu_groupchat_theme_update_v67(win):
    try:
        if not win.winfo_exists(): return
        app = getattr(win, "_petzhu_groupchat_owner_app_v67", None)
        if app is None: return
        palette = _petzhu_groupchat_palette_v1(app)
        signature = (bool(palette["light"]), palette["accent"])
        if signature != getattr(win, "_petzhu_groupchat_palette_signature_v1", None):
            win._petzhu_groupchat_palette_signature_v1 = signature
            stored = getattr(win, "_petzhu_groupchat_palette_v67", None)
            if isinstance(stored, dict): stored.clear(); stored.update(palette)
            _petzhu_groupchat_apply_palette_v1(win, palette)
            refs = getattr(win, "_petzhu_groupchat_refs_v1", {}) or {}
            if callable(refs.get("update_modes")): refs["update_modes"]()
            # Member/sidebar cards are static widgets whose colors are reapplied above;
            # no rebuilding here to avoid flicker during star-color preview.
    except Exception: pass


def _petzhu_apply_global_theme_hue_v67(hue):
    result = _PETZHU_GROUPCHAT_PREVIOUS_APPLY_HUE_V67(hue)
    for win in list(_PETZHU_GROUPCHAT_OPEN_WINDOWS_V67):
        try:
            if not win.winfo_exists():
                _PETZHU_GROUPCHAT_OPEN_WINDOWS_V67.discard(win)
                continue
            pending = getattr(win, "_petzhu_groupchat_theme_after_v67", None)
            if pending is None:
                win._petzhu_groupchat_theme_after_v67 = win.after(45, lambda w=win: _petzhu_groupchat_theme_after_cb_v67(w))
        except Exception: pass
    return result


def _petzhu_groupchat_theme_after_cb_v67(win):
    try: win._petzhu_groupchat_theme_after_v67 = None
    except Exception: pass
    _petzhu_groupchat_theme_update_v67(win)


def _petzhu_groupchat_close_window_v1(app, win):
    try:
        after_id = getattr(win, "_petzhu_groupchat_after_v1", None)
        if after_id:
            try: win.after_cancel(after_id)
            except Exception: pass
        theme_after = getattr(win, "_petzhu_groupchat_theme_after_v67", None)
        if theme_after:
            try: win.after_cancel(theme_after)
            except Exception: pass
        try: _PETZHU_GROUPCHAT_OPEN_WINDOWS_V67.discard(win)
        except Exception: pass
        win.destroy()
    except Exception: pass
    if getattr(app, "_petzhu_groupchat_win_v1", None) is win:
        app._petzhu_groupchat_win_v1 = None


_petzhu_apply_global_theme_hue = _petzhu_apply_global_theme_hue_v67



# ============================================================
# v68: Group chat identity-safe content and deterministic first-frame theming
# ============================================================

_PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68 = 0
_PETZHU_GROUPCHAT_OPEN_PRE_V68 = _petzhu_groupchat_open_v1


def _petzhu_groupchat_mix_color_v68(base, tint, amount):
    """Blend two #RRGGBB colors; all UI tints are derived from the currently selected theme hue."""
    try:
        a = tuple(int(str(base)[i:i+2], 16) for i in (1, 3, 5))
        b = tuple(int(str(tint)[i:i+2], 16) for i in (1, 3, 5))
        amount = max(0.0, min(1.0, float(amount)))
        return "#%02x%02x%02x" % tuple(round(x * (1.0-amount) + y * amount) for x, y in zip(a, b))
    except Exception:
        return str(base)


def _petzhu_groupchat_palette_v1(app):
    """Generate every surface and accent from the live theme before any group-chat widget is shown."""
    light = bool(getattr(app, "_context_palette_light", True))
    try:
        hue = int(_PETZHU_THEME_HUE_STATE.get("hue", getattr(app, "theme_hue", 330))) % 360
    except Exception:
        try: hue = int(getattr(app, "theme_hue", 330)) % 360
        except Exception: hue = 330
    rr, gg, bb = colorsys.hsv_to_rgb(hue / 360.0, 0.62, 0.82)
    accent = "#%02x%02x%02x" % (round(rr*255), round(gg*255), round(bb*255))
    lum = 0.2126 * rr + 0.7152 * gg + 0.0722 * bb
    accent_text = "#25202b" if lum >= 0.58 else "#ffffff"
    if light:
        neutral_bg = "#fbfafc"
        return {
            "light": True, "hue": hue,
            "bg": _petzhu_groupchat_mix_color_v68(neutral_bg, accent, 0.035),
            "surface": "#ffffff",
            "surface2": _petzhu_groupchat_mix_color_v68("#f6f4f8", accent, 0.13),
            "fg": "#302a38",
            "muted": _petzhu_groupchat_mix_color_v68("#776f7e", accent, 0.13),
            "edge": _petzhu_groupchat_mix_color_v68("#ded9e4", accent, 0.32),
            "accent": accent, "accent_soft": _petzhu_groupchat_mix_color_v68("#ffffff", accent, 0.19),
            "accent_text": accent_text,
            "pet_bubble": _petzhu_groupchat_mix_color_v68("#faf9fc", accent, 0.12),
            "user_bubble": _petzhu_groupchat_mix_color_v68("#fbf9fc", accent, 0.27),
            "system_bubble": _petzhu_groupchat_mix_color_v68("#f0eff3", accent, 0.13),
            "input": "#ffffff", "online": "#21875f",
        }
    dark_bg = "#11141d"
    dark_surface = "#1b202c"
    return {
        "light": False, "hue": hue,
        "bg": _petzhu_groupchat_mix_color_v68(dark_bg, accent, 0.035),
        "surface": _petzhu_groupchat_mix_color_v68(dark_surface, accent, 0.075),
        "surface2": _petzhu_groupchat_mix_color_v68("#252b3b", accent, 0.15),
        "fg": "#edf0fa",
        "muted": _petzhu_groupchat_mix_color_v68("#9ca5b8", accent, 0.16),
        "edge": _petzhu_groupchat_mix_color_v68("#353b4c", accent, 0.31),
        "accent": accent, "accent_soft": _petzhu_groupchat_mix_color_v68("#202431", accent, 0.34),
        "accent_text": accent_text,
        "pet_bubble": _petzhu_groupchat_mix_color_v68("#222838", accent, 0.17),
        "user_bubble": _petzhu_groupchat_mix_color_v68("#25293a", accent, 0.32),
        "system_bubble": _petzhu_groupchat_mix_color_v68("#1c212c", accent, 0.13),
        "input": _petzhu_groupchat_mix_color_v68("#151b27", accent, 0.07),
        "online": "#55d49b",
    }


def _petzhu_groupchat_apply_palette_v1(win, palette):
    """Apply palette by semantic color roles to every descendant, including controls often missed by earlier patches."""
    try: win.configure(bg=palette["bg"])
    except Exception: pass
    children = [win] + _petzhu_groupchat_walk_widgets_v1(win)
    for widget in children:
        role = str(getattr(widget, "_petzhu_groupchat_role_v1", "bg"))
        if role in _PETZHU_GROUPCHAT_BG_ROLES_V67:
            bg_role = "accent_soft" if role == "avatar" else role
        else:
            bg_role = str(getattr(widget, "_petzhu_groupchat_bg_role_v67", "bg"))
        bg = palette.get(bg_role, palette["bg"])
        if role == "muted": fg = palette["muted"]
        elif role == "online": fg = palette["online"]
        elif role in ("speaker_pet", "speaker_user"): fg = palette["accent"]
        elif role in ("accent",): fg = palette["accent_text"]
        else: fg = palette["fg"]
        try:
            if isinstance(widget, tk.OptionMenu):
                widget.configure(bg=bg, fg=fg, activebackground=palette["accent"],
                                 activeforeground=palette["accent_text"], highlightthickness=0,
                                 relief="flat", bd=0)
                menu = widget["menu"]
                menu.configure(bg=palette["surface2"], fg=palette["fg"],
                               activebackground=palette["accent"], activeforeground=palette["accent_text"],
                               selectcolor=palette["accent"])
            elif isinstance(widget, tk.Menu):
                widget.configure(bg=palette["surface2"], fg=palette["fg"],
                                 activebackground=palette["accent"], activeforeground=palette["accent_text"],
                                 disabledforeground=palette["muted"])
            elif isinstance(widget, tk.Canvas):
                widget.configure(bg=bg, highlightbackground=palette["edge"], highlightcolor=palette["edge"])
            elif isinstance(widget, tk.Text):
                widget.configure(bg=bg, fg=fg, insertbackground=palette["fg"],
                                 selectbackground=palette["accent"], selectforeground=palette["accent_text"],
                                 highlightbackground=palette["edge"], highlightcolor=palette["accent"])
            elif isinstance(widget, tk.Entry):
                widget.configure(bg=bg, fg=fg, insertbackground=palette["fg"],
                                 selectbackground=palette["accent"], selectforeground=palette["accent_text"],
                                 highlightbackground=palette["edge"], highlightcolor=palette["accent"])
            elif isinstance(widget, tk.Listbox):
                widget.configure(bg=bg, fg=fg, selectbackground=palette["accent"],
                                 selectforeground=palette["accent_text"], highlightbackground=palette["edge"])
            elif isinstance(widget, tk.Button):
                btn_fg = palette["accent_text"] if role == "accent" else palette["fg"]
                widget.configure(bg=bg, fg=btn_fg, activebackground=palette["accent"],
                                 activeforeground=palette["accent_text"], disabledforeground=palette["muted"],
                                 highlightbackground=palette["edge"], bd=0, relief="flat")
            elif isinstance(widget, (tk.Checkbutton, tk.Radiobutton)):
                widget.configure(bg=bg, fg=fg, activebackground=palette["accent"],
                                 activeforeground=palette["accent_text"], selectcolor=palette["surface2"],
                                 disabledforeground=palette["muted"], highlightbackground=palette["edge"])
            elif isinstance(widget, tk.Menubutton):
                widget.configure(bg=bg, fg=fg, activebackground=palette["accent"],
                                 activeforeground=palette["accent_text"], highlightbackground=palette["edge"], bd=0)
            elif isinstance(widget, tk.Label):
                widget.configure(bg=bg, fg=fg)
            elif isinstance(widget, tk.Frame):
                widget.configure(bg=bg, highlightbackground=palette["edge"])
            elif isinstance(widget, tk.Scrollbar):
                widget.configure(bg=palette["surface2"], troughcolor=palette["bg"],
                                 activebackground=palette["accent"], highlightbackground=palette["edge"])
            elif isinstance(widget, tk.Scale):
                widget.configure(bg=bg, fg=fg, troughcolor=palette["surface2"],
                                 activebackground=palette["accent"], highlightbackground=palette["edge"])
            elif isinstance(widget, tk.Spinbox):
                widget.configure(bg=bg, fg=fg, insertbackground=palette["fg"],
                                 buttonbackground=palette["surface2"], highlightbackground=palette["edge"])
        except Exception:
            # Some platform/Tk versions do not expose every option on every widget class.
            pass


def _petzhu_groupchat_open_v1(app):
    global _PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68
    _PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68 += 1
    try:
        return _PETZHU_GROUPCHAT_OPEN_PRE_V68(app)
    finally:
        _PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68 = max(0, _PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68 - 1)



# Apply the same name-preservation guard to every dynamic row/card rebuild, not only initial window creation.
def _petzhu_groupchat_preserve_names_call_v68(func):
    def _wrapped(*args, **kwargs):
        global _PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68
        _PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68 += 1
        try:
            return func(*args, **kwargs)
        finally:
            _PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68 = max(0, _PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68 - 1)
    _wrapped.__name__ = getattr(func, "__name__", "groupchat_preserve_names")
    _wrapped.__doc__ = getattr(func, "__doc__", None)
    return _wrapped


_PETZHU_GROUPCHAT_RENDER_PRE_NAME_GUARD_V68 = _petzhu_groupchat_render_message_v1
_PETZHU_GROUPCHAT_MEMBERS_PRE_NAME_GUARD_V68 = _petzhu_groupchat_refresh_members_ui_v1
_PETZHU_GROUPCHAT_SIDEBAR_PRE_NAME_GUARD_V68 = _petzhu_groupchat_sidebar_refresh_v67
_PETZHU_GROUPCHAT_MEMORIES_PRE_NAME_GUARD_V68 = _petzhu_groupchat_open_memories_v1
_petzhu_groupchat_render_message_v1 = _petzhu_groupchat_preserve_names_call_v68(_PETZHU_GROUPCHAT_RENDER_PRE_NAME_GUARD_V68)
_petzhu_groupchat_refresh_members_ui_v1 = _petzhu_groupchat_preserve_names_call_v68(_PETZHU_GROUPCHAT_MEMBERS_PRE_NAME_GUARD_V68)
_petzhu_groupchat_sidebar_refresh_v67 = _petzhu_groupchat_preserve_names_call_v68(_PETZHU_GROUPCHAT_SIDEBAR_PRE_NAME_GUARD_V68)
