# v70: Keep group-chat palettes out of the global black/white snapshot animation.
# Apply the settled theme once after the global transition completes, so legacy global pink
# mapping cannot repaint the chat back to white or leave only the memory note on a dark surface.
_PETZHU_GROUPCHAT_PREVIOUS_THEME_TRANSITION_V70 = MaoPet._animate_context_theme_transition

def _petzhu_groupchat_theme_transition_wrapper_v70(self, target_light, apply_menu_palette, duration_ms=900):
    result = _PETZHU_GROUPCHAT_PREVIOUS_THEME_TRANSITION_V70(
        self, target_light, apply_menu_palette, duration_ms=duration_ms)
    try:
        wait_ms = max(50, int(duration_ms or 900) + 90)
        pending = getattr(self, "_petzhu_groupchat_theme_commit_after_v70", None)
        if pending:
            try: self.root.after_cancel(pending)
            except Exception: pass
        self._petzhu_groupchat_theme_commit_after_v70 = self.root.after(
            wait_ms, lambda app=self, light=bool(target_light): _petzhu_groupchat_commit_theme_v70(app, light))
    except Exception:
        pass
    return result

def _petzhu_groupchat_commit_theme_v70(app, expected_light=None):
    try:
        app._petzhu_groupchat_theme_commit_after_v70 = None
        win = getattr(app, "_petzhu_groupchat_win_v1", None)
        if win is None or not win.winfo_exists():
            return
        palette = _petzhu_groupchat_palette_v1(app)
        # Ignore stale delayed callbacks when the user toggles again before the previous fade ends.
        if expected_light is not None and bool(palette.get("light")) != bool(expected_light):
            return
        win._petzhu_groupchat_palette_signature_v1 = (bool(palette["light"]), palette["accent"])
        stored = getattr(win, "_petzhu_groupchat_palette_v67", None)
        if isinstance(stored, dict):
            stored.clear(); stored.update(palette)
        _petzhu_groupchat_apply_palette_v1(win, palette)
        refs = getattr(win, "_petzhu_groupchat_refs_v1", {}) or {}
        if callable(refs.get("update_modes")):
            refs["update_modes"]()
        win.update_idletasks()
    except Exception:
        pass

MaoPet._animate_context_theme_transition = _petzhu_groupchat_theme_transition_wrapper_v70


# v71: group-chat text must keep each participant's literal identity.
# Some existing installations have multiple name/theme hooks stacked in Tkinter, and the
# ancestry marker alone was not sufficient in every dynamic refresh path. Temporarily make
# the display-name transformer an identity function for group-chat UI callbacks only.
# This does not change app.pet_name, stored messages, aliases, persona settings, or other UI.
def _petzhu_groupchat_name_safe_callback_v71(func):
    def _wrapped(*args, **kwargs):
        global _ACTIVE_PET_NAME_TRANSFORM, _PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68
        previous_transform = _ACTIVE_PET_NAME_TRANSFORM
        previous_depth = int(globals().get("_PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68", 0) or 0)
        _ACTIVE_PET_NAME_TRANSFORM = lambda value: str(value if value is not None else "")
        _PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68 = previous_depth + 1
        try:
            return func(*args, **kwargs)
        finally:
            _ACTIVE_PET_NAME_TRANSFORM = previous_transform
            _PETZHU_GROUPCHAT_NAME_PRESERVE_DEPTH_V68 = previous_depth
    _wrapped.__name__ = getattr(func, "__name__", "groupchat_name_safe")
    _wrapped.__doc__ = getattr(func, "__doc__", None)
    return _wrapped

# Final safety layer for all top-level and periodic group-chat rendering paths.
_PETZHU_GROUPCHAT_RENDER_NAME_SAFE_PRE_V71 = _petzhu_groupchat_render_message_v1
_PETZHU_GROUPCHAT_MEMBERS_NAME_SAFE_PRE_V71 = _petzhu_groupchat_refresh_members_ui_v1
_PETZHU_GROUPCHAT_SIDEBAR_NAME_SAFE_PRE_V71 = _petzhu_groupchat_sidebar_refresh_v67
_PETZHU_GROUPCHAT_MEMORIES_NAME_SAFE_PRE_V71 = _petzhu_groupchat_open_memories_v1
_PETZHU_GROUPCHAT_OPEN_NAME_SAFE_PRE_V71 = _petzhu_groupchat_open_v1
_petzhu_groupchat_render_message_v1 = _petzhu_groupchat_name_safe_callback_v71(_PETZHU_GROUPCHAT_RENDER_NAME_SAFE_PRE_V71)
_petzhu_groupchat_refresh_members_ui_v1 = _petzhu_groupchat_name_safe_callback_v71(_PETZHU_GROUPCHAT_MEMBERS_NAME_SAFE_PRE_V71)
_petzhu_groupchat_sidebar_refresh_v67 = _petzhu_groupchat_name_safe_callback_v71(_PETZHU_GROUPCHAT_SIDEBAR_NAME_SAFE_PRE_V71)
_petzhu_groupchat_open_memories_v1 = _petzhu_groupchat_name_safe_callback_v71(_PETZHU_GROUPCHAT_MEMORIES_NAME_SAFE_PRE_V71)
_petzhu_groupchat_open_v1 = _petzhu_groupchat_name_safe_callback_v71(_PETZHU_GROUPCHAT_OPEN_NAME_SAFE_PRE_V71)


# ============================================================
# v74: Smoothly animate the group-chat palette with the desktop theme star.
# Root cause fixed: the global transition intentionally excludes the group-chat widget tree
# to prevent legacy recoloring. Its previous wrapper only applied the final palette after
# duration_ms, while the 500ms refresh loop could independently switch the palette at once.
# Animate the group-chat palette itself frame-by-frame and let refresh callbacks observe the
# palette currently on screen until the transition settles.
# ============================================================
_PETZHU_GROUPCHAT_RAW_PALETTE_V74 = _petzhu_groupchat_palette_v1
_PETZHU_GROUPCHAT_RAW_TRANSITION_V74 = _PETZHU_GROUPCHAT_PREVIOUS_THEME_TRANSITION_V70
_PETZHU_GROUPCHAT_CLOSE_PRE_V74 = _petzhu_groupchat_close_window_v1


def _petzhu_groupchat_palette_v74(app):
    """While fading, return the palette currently being painted, never the target abruptly."""
    try:
        win = getattr(app, "_petzhu_groupchat_win_v1", None)
        if win is not None and win.winfo_exists() and bool(getattr(win, "_petzhu_groupchat_theme_animating_v74", False)):
            stored = getattr(win, "_petzhu_groupchat_palette_v67", None)
            if isinstance(stored, dict):
                return dict(stored)
    except Exception:
        pass
    return _PETZHU_GROUPCHAT_RAW_PALETTE_V74(app)


def _petzhu_groupchat_blend_hex_v74(start, end, progress):
    try:
        a, b = str(start), str(end)
        if (len(a) != 7 or len(b) != 7 or not a.startswith('#') or not b.startswith('#')):
            return end if progress >= 1.0 else start
        av = tuple(int(a[i:i+2], 16) for i in (1, 3, 5))
        bv = tuple(int(b[i:i+2], 16) for i in (1, 3, 5))
        return '#%02x%02x%02x' % tuple(round(x + (y-x)*progress) for x, y in zip(av, bv))
    except Exception:
        return end if progress >= 1.0 else start


def _petzhu_groupchat_theme_transition_wrapper_v74(self, target_light, apply_menu_palette, duration_ms=900):
    win = getattr(self, "_petzhu_groupchat_win_v1", None)
    if win is None:
        return _PETZHU_GROUPCHAT_RAW_TRANSITION_V74(
            self, target_light, apply_menu_palette, duration_ms=duration_ms)
    try:
        if not win.winfo_exists():
            return _PETZHU_GROUPCHAT_RAW_TRANSITION_V74(
                self, target_light, apply_menu_palette, duration_ms=duration_ms)
    except Exception:
        return _PETZHU_GROUPCHAT_RAW_TRANSITION_V74(
            self, target_light, apply_menu_palette, duration_ms=duration_ms)

    # Start from the actual displayed/interpolated colors. A second click mid-fade therefore
    # reverses smoothly from the current frame instead of jumping back to an endpoint.
    old_after = getattr(win, "_petzhu_groupchat_theme_transition_after_v74", None)
    if old_after:
        try: win.after_cancel(old_after)
        except Exception: pass
    old_commit = getattr(self, "_petzhu_groupchat_theme_commit_after_v70", None)
    if old_commit:
        try: self.root.after_cancel(old_commit)
        except Exception: pass
        self._petzhu_groupchat_theme_commit_after_v70 = None
    stored = getattr(win, "_petzhu_groupchat_palette_v67", None)
    if isinstance(stored, dict):
        start_palette = dict(stored)
    else:
        start_palette = _PETZHU_GROUPCHAT_RAW_PALETTE_V74(self)
    start_light = bool(start_palette.get("light", not bool(target_light)))
    start_signature_accent = str(start_palette.get("accent", ""))

    token = int(getattr(win, "_petzhu_groupchat_theme_transition_token_v74", 0) or 0) + 1
    win._petzhu_groupchat_theme_transition_token_v74 = token
    win._petzhu_groupchat_theme_animating_v74 = True
    win._petzhu_groupchat_palette_signature_v1 = (start_light, start_signature_accent)

    # The existing application-wide star transition continues animating every other window.
    # Group-chat stays excluded there, and gets its own matched-duration palette transition.
    try:
        result = _PETZHU_GROUPCHAT_RAW_TRANSITION_V74(
            self, target_light, apply_menu_palette, duration_ms=duration_ms)
    except Exception:
        win._petzhu_groupchat_theme_animating_v74 = False
        raise

    # The target light/dark value has now been committed by the main theme manager.
    target_palette = _PETZHU_GROUPCHAT_RAW_PALETTE_V74(self)
    duration = max(250, int(duration_ms or 900))
    frames = max(18, min(60, int(round(duration / 20.0))))
    interval = max(10, int(round(duration / frames)))
    color_keys = {
        key for key, value in start_palette.items()
        if isinstance(value, str) and len(value) == 7 and value.startswith('#')
        and isinstance(target_palette.get(key), str)
        and len(target_palette.get(key)) == 7 and target_palette.get(key).startswith('#')
    }

    def apply_frame(frame_number):
        try:
            if not win.winfo_exists() or int(getattr(win, "_petzhu_groupchat_theme_transition_token_v74", -1)) != token:
                return
        except Exception:
            return
        raw_t = min(1.0, max(0.0, float(frame_number) / float(frames)))
        # Smoothstep avoids a harsh first/last frame while retaining the full 900ms transition.
        eased = raw_t * raw_t * (3.0 - 2.0 * raw_t)
        if frame_number >= frames:
            frame_palette = dict(target_palette)
        else:
            frame_palette = {}
            for key, target_value in target_palette.items():
                start_value = start_palette.get(key, target_value)
                if key == "light":
                    # Keep the transition signature at the old mode until the final frame so
                    # the 500ms UI refresh won't treat the intermediate palette as settled.
                    frame_palette[key] = start_light
                elif key == "hue":
                    frame_palette[key] = start_palette.get(key, target_value)
                elif key in color_keys:
                    frame_palette[key] = _petzhu_groupchat_blend_hex_v74(start_value, target_value, eased)
                else:
                    frame_palette[key] = start_value

        current_store = getattr(win, "_petzhu_groupchat_palette_v67", None)
        if not isinstance(current_store, dict):
            current_store = {}
            win._petzhu_groupchat_palette_v67 = current_store
        current_store.clear()
        current_store.update(frame_palette)
        try:
            _petzhu_groupchat_apply_palette_v1(win, current_store)
        except Exception:
            pass
        if frame_number < frames:
            try:
                win._petzhu_groupchat_theme_transition_after_v74 = win.after(
                    interval, lambda n=frame_number+1: apply_frame(n))
            except Exception:
                # If the window scheduler fails, settle deterministically at the target palette.
                apply_frame(frames)
        else:
            win._petzhu_groupchat_theme_transition_after_v74 = None
            win._petzhu_groupchat_theme_animating_v74 = False
            win._petzhu_groupchat_palette_signature_v1 = (
                bool(target_palette.get("light")), str(target_palette.get("accent", "")))
            current_store.clear()
            current_store.update(target_palette)
            try:
                _petzhu_groupchat_apply_palette_v1(win, current_store)
                refs = getattr(win, "_petzhu_groupchat_refs_v1", {}) or {}
                if callable(refs.get("update_modes")):
                    refs["update_modes"]()
                win.update_idletasks()
            except Exception:
                pass

    try:
        apply_frame(0)
    except Exception:
        win._petzhu_groupchat_theme_animating_v74 = False
        win._petzhu_groupchat_palette_signature_v1 = (
            bool(target_palette.get("light")), str(target_palette.get("accent", "")))
        stored = getattr(win, "_petzhu_groupchat_palette_v67", None)
        if isinstance(stored, dict):
            stored.clear(); stored.update(target_palette)
        _petzhu_groupchat_apply_palette_v1(win, target_palette)
    return result


def _petzhu_groupchat_close_window_v74(app, win):
    pending = getattr(win, "_petzhu_groupchat_theme_transition_after_v74", None)
    if pending:
        try: win.after_cancel(pending)
        except Exception: pass
    try:
        win._petzhu_groupchat_theme_animating_v74 = False
        win._petzhu_groupchat_theme_transition_token_v74 = int(
            getattr(win, "_petzhu_groupchat_theme_transition_token_v74", 0) or 0) + 1
    except Exception:
        pass
    return _PETZHU_GROUPCHAT_CLOSE_PRE_V74(app, win)


# The periodic 500ms refresh and hue-refresh callback both read through this animation-aware
# palette accessor. During the fade they see intermediate colors instead of applying target
# black/white colors immediately; on the final frame they naturally return to the target.
_petzhu_groupchat_palette_v1 = _petzhu_groupchat_palette_v74
MaoPet._animate_context_theme_transition = _petzhu_groupchat_theme_transition_wrapper_v74
_petzhu_groupchat_close_window_v1 = _petzhu_groupchat_close_window_v74


# ============================================================
# v77: 群聊头像使用桌宠实际加载的 normal1.png，而不是姓名首字占位
# ============================================================

def _petzhu_groupchat_local_avatar_path_v77(app):
    """Resolve the same normal-pose source used by MaoPet._load_images, then persist it for history."""
    source_path = ""
    candidates = []

    # First preference must match _load_images(): explicitly configured normal-pose sprite.
    try:
        custom_path = str(app._persona_sprite_path("normal") or "").strip()
    except Exception:
        custom_path = ""
    if custom_path:
        candidates.append(custom_path)

    # Critical fallback: the normal1.png next to the script / executable / PyInstaller assets.
    # Previous versions only searched persona_sprite_paths (usually empty for default personas),
    # so avatar_path stayed empty and the UI intentionally fell back to the first name character.
    try:
        candidates.append(str(find_asset("normal1.png") or ""))
    except Exception:
        pass
    try:
        candidates.append(os.path.join(get_data_dir(), "normal1.png"))
    except Exception:
        pass
    try:
        candidates.append(os.path.join(os.path.dirname(os.path.abspath(__file__)), "normal1.png"))
    except Exception:
        pass
    if getattr(sys, "frozen", False):
        try:
            candidates.append(os.path.join(os.path.dirname(os.path.abspath(sys.executable)), "normal1.png"))
        except Exception:
            pass
        try:
            candidates.append(os.path.join(str(getattr(sys, "_MEIPASS", "") or ""), "normal1.png"))
        except Exception:
            pass

    seen = set()
    for candidate in candidates:
        candidate = str(candidate or "").strip()
        if not candidate:
            continue
        try:
            candidate = os.path.abspath(os.path.expanduser(candidate))
            key = os.path.normcase(candidate)
            if key in seen:
                continue
            seen.add(key)
            if os.path.isfile(candidate):
                source_path = candidate
                break
        except Exception:
            continue
    if not source_path:
        return ""

    # Keep an app-wide cache copy: PyInstaller one-file assets live in a temporary _MEIPASS
    # directory which may disappear when the source desktop-pet instance exits. Chat history
    # should continue to show the same avatar after that happens.
    try:
        db_path = str(getattr(app, "_petzhu_groupchat_db_path_v1", "") or _petzhu_groupchat_db_path_v1())
        cache_dir = os.path.join(os.path.dirname(os.path.abspath(db_path)), "group_chat_avatars")
        os.makedirs(cache_dir, exist_ok=True)
        profile_key = str(getattr(app, "_petzhu_groupchat_profile_key_v1", "") or _petzhu_groupchat_profile_key_v1(app))
        safe_key = re.sub(r"[^0-9A-Za-z_-]", "_", profile_key)[:48] or hashlib.sha256(source_path.encode("utf-8", "replace")).hexdigest()[:24]
        target_path = os.path.join(cache_dir, safe_key + "_normal1.png")
        source_stat = os.stat(source_path)
        needs_copy = True
        try:
            target_stat = os.stat(target_path)
            needs_copy = (target_stat.st_size != source_stat.st_size or
                          target_stat.st_mtime_ns != source_stat.st_mtime_ns)
        except Exception:
            needs_copy = True
        if needs_copy:
            temp_path = target_path + ".%s.%s.tmp" % (os.getpid(), threading.get_ident())
            try:
                shutil.copy2(source_path, temp_path)
                os.replace(temp_path, target_path)
            finally:
                try:
                    if os.path.exists(temp_path):
                        os.remove(temp_path)
                except Exception:
                    pass
        if os.path.isfile(target_path):
            return os.path.abspath(target_path)
    except Exception:
        # The live source still works even if the stable cache directory is not writable.
        pass
    return os.path.abspath(source_path)


def _petzhu_groupchat_avatar_photo_v77(win, path, size=42):
    """Load a genuine normal1 PNG avatar, preserve alpha, and remove the app's green chroma key."""
    path = str(path or "").strip()
    if not path or not os.path.isfile(path):
        return None
    try:
        cache = getattr(win, "_petzhu_groupchat_avatar_cache_v67", None)
        if not isinstance(cache, dict):
            cache = {}
            win._petzhu_groupchat_avatar_cache_v67 = cache
        stat = os.stat(path)
        key = (os.path.normcase(os.path.abspath(path)), int(size), int(stat.st_mtime_ns), int(stat.st_size))
        if key in cache:
            return cache[key]

        with Image.open(path) as opened:
            image = opened.convert("RGBA")

        # The desktop pet's window uses #00ff01 as its transparency key. A normal Label
        # does not: remove that exact/near-exact key from the avatar bitmap so no green tile
        # appears in the regular opaque chat window. Existing PNG alpha is otherwise retained.
        try:
            px = image.load()
            w, h = image.size
            for y in range(h):
                for x in range(w):
                    r, g, b, a = px[x, y]
                    if a and g >= 245 and r <= 18 and b <= 20:
                        px[x, y] = (r, g, b, 0)
        except Exception:
            pass

        resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS", getattr(Image, "LANCZOS", 1))
        image.thumbnail((int(size), int(size)), resampling)
        canvas_image = Image.new("RGBA", (int(size), int(size)), (0, 0, 0, 0))
        canvas_image.alpha_composite(image, ((int(size) - image.width) // 2, (int(size) - image.height) // 2))
        photo = ImageTk.PhotoImage(canvas_image, master=win)
        cache[key] = photo
        while len(cache) > 64:
            cache.pop(next(iter(cache)))
        return photo
    except Exception:
        return None


# Replace the avatar resolver and loader used by all member chips, sidebar cards, and messages.
# heartbeat_v1 resolves these globals at call time, so every running instance republishes its real image path.
_petzhu_groupchat_local_avatar_path_v67 = _petzhu_groupchat_local_avatar_path_v77
_petzhu_groupchat_avatar_photo_v67 = _petzhu_groupchat_avatar_photo_v77


# ============================================================
# v78: 自由群聊自然接话 + 桌宠自主开话题
# - 自由群聊可在同一个话题内接续最多 4 条桌宠发言，遇到 [PASS] 自然收尾。
# - 群聊窗口打开且选中“自由群聊”时，安静一段时间后允许桌宠自主发起新话题。
# - 通过数据库元数据作为跨进程开关和冷却锁，不会让每个实例同时创建话题。
# ============================================================

def _petzhu_groupchat_autochat_enabled_v78(app=None):
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        try:
            return _petzhu_groupchat_meta_get_v1(conn, "autochat_enabled", "1") not in ("0", "false", "False", "off")
        finally:
            conn.close()
    except Exception:
        return True


def _petzhu_groupchat_set_autochat_enabled_v78(app, enabled):
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        try:
            _petzhu_groupchat_meta_set_v1(conn, "autochat_enabled", "1" if enabled else "0")
            conn.commit()
        finally:
            conn.close()
        if getattr(app, "_petzhu_groupchat_win_v1", None) is not None:
            try:
                win = app._petzhu_groupchat_win_v1
                refs = getattr(win, "_petzhu_groupchat_refs_v1", {}) or {}
                hint = refs.get("hint")
                if hint is not None and hint.winfo_exists():
                    hint.configure(text=("桌宠会在安静一段时间后尝试自然开启话题。" if enabled
                                         else "桌宠不会自行开启新话题；仍会回应你的消息。"))
            except Exception:
                pass
    except Exception:
        pass


def _petzhu_groupchat_migrate_jobs_for_chains_v78(app):
    """Replace the old root/participant uniqueness with root/participant/turn uniqueness."""
    if bool(getattr(app, "_petzhu_groupchat_jobs_schema_v78_ready", False)):
        return
    conn = _petzhu_groupchat_connect_v1(app)
    try:
        row = conn.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name='gc_jobs'").fetchone()
        schema = str(row[0] or "") if row else ""
        if "UNIQUE(root_id,participant_id)" not in schema.replace(" ", "").replace("\n", ""):
            # Schema already migrated or a fresh table is using the new constraint.
            app._petzhu_groupchat_jobs_schema_v78_ready = True
            return
        conn.execute("BEGIN IMMEDIATE")
        # Re-check under the write lock in case another PETZhu instance migrated first.
        row = conn.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name='gc_jobs'").fetchone()
        schema = str(row[0] or "") if row else ""
        compact = schema.replace(" ", "").replace("\n", "")
        if "UNIQUE(root_id,participant_id)" not in compact:
            conn.commit()
            app._petzhu_groupchat_jobs_schema_v78_ready = True
            return
        conn.execute("DROP INDEX IF EXISTS gc_jobs_ready_idx")
        conn.execute("ALTER TABLE gc_jobs RENAME TO gc_jobs_v77_backup")
        conn.execute("""CREATE TABLE gc_jobs (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            root_id INTEGER NOT NULL,
            participant_id TEXT NOT NULL,
            mode TEXT NOT NULL,
            turn_index INTEGER NOT NULL DEFAULT 0,
            status TEXT NOT NULL DEFAULT 'pending',
            lease_until REAL NOT NULL DEFAULT 0,
            UNIQUE(root_id, participant_id, turn_index)
        )""")
        conn.execute("""INSERT INTO gc_jobs(id,root_id,participant_id,mode,turn_index,status,lease_until)
                        SELECT id,root_id,participant_id,mode,turn_index,status,lease_until FROM gc_jobs_v77_backup""")
        conn.execute("DROP TABLE gc_jobs_v77_backup")
        conn.execute("CREATE INDEX IF NOT EXISTS gc_jobs_ready_idx ON gc_jobs(participant_id, status, root_id, turn_index)")
        conn.commit()
        app._petzhu_groupchat_jobs_schema_v78_ready = True
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        # Never break app startup if an old SQLite file is locked; retry next heartbeat.
    finally:
        conn.close()


def _petzhu_groupchat_idle_topic_due_v106(conn, now):
    """为最近结束的话题持久化一次 30–60 分钟后的自主开场时间。"""
    _petzhu_groupchat_ensure_topics_v81(conn)
    last_closed = conn.execute(
        "SELECT root_id,closed_at FROM gc_topics WHERE status='closed' AND closed_at>0 "
        "ORDER BY closed_at DESC,root_id DESC LIMIT 1"
    ).fetchone()
    if last_closed:
        timer_root = str(int(last_closed['root_id'] or 0))
        try:
            ended_at = float(last_closed['closed_at'] or now)
        except Exception:
            ended_at = now
        # The deadline is calculated from topic end, not from the latest message or last start.
        root_now = _petzhu_groupchat_meta_get_v1(conn, 'idle_topic_timer_root_v106', '')
        due_raw = _petzhu_groupchat_meta_get_v1(conn, 'idle_topic_due_at_v106', '')
        try:
            due_at = float(due_raw)
        except Exception:
            due_at = 0.0
        if root_now != timer_root or due_at <= 0:
            due_at = ended_at + random.uniform(30 * 60, 60 * 60)
            _petzhu_groupchat_meta_set_v1(conn, 'idle_topic_timer_root_v106', timer_root)
            _petzhu_groupchat_meta_set_v1(conn, 'idle_topic_due_at_v106', repr(due_at))
        return due_at

    # Legacy/newly created archives with no closed-topic row get one full quiet interval
    # from the first scheduler check. Later topic closures switch to their own closed_at timer.
    root_now = _petzhu_groupchat_meta_get_v1(conn, 'idle_topic_timer_root_v106', '')
    due_raw = _petzhu_groupchat_meta_get_v1(conn, 'idle_topic_due_at_v106', '')
    try:
        due_at = float(due_raw)
    except Exception:
        due_at = 0.0
    if root_now != 'initial' or due_at <= 0:
        due_at = float(now) + random.uniform(30 * 60, 60 * 60)
        _petzhu_groupchat_meta_set_v1(conn, 'idle_topic_timer_root_v106', 'initial')
        _petzhu_groupchat_meta_set_v1(conn, 'idle_topic_due_at_v106', repr(due_at))
    return due_at


def _petzhu_groupchat_schedule_idle_topic_v78(app):
    """每次自主开场在在线桌宠间等概率抽选；距离上一话题结束随机等待 30–60 分钟。"""
    win = getattr(app, "_petzhu_groupchat_win_v1", None)
    if win is None or not _petzhu_groupchat_autochat_enabled_v78(app):
        return False
    try:
        if not win.winfo_exists():
            return False
        refs = getattr(win, "_petzhu_groupchat_refs_v1", {}) or {}
        mode_var = refs.get("mode_var")
        if mode_var is not None and str(mode_var.get()) != "free":
            return False
        # Avoid hammering SQLite from the instance heartbeat.
        now_mono = time.monotonic()
        if now_mono - float(getattr(app, "_petzhu_groupchat_idle_check_mono_v78", 0.0) or 0.0) < 8.0:
            return False
        app._petzhu_groupchat_idle_check_mono_v78 = now_mono
    except Exception:
        return False

    conn = None
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        now = time.time()
        conn.execute("BEGIN IMMEDIATE")
        _petzhu_groupchat_ensure_topics_v81(conn)

        # Only active, API-ready instances are eligible. random.choice below gives every
        # eligible desktop pet exactly the same probability; do not rotate based on prior sender.
        members = [dict(row) for row in conn.execute(
            "SELECT * FROM gc_participants WHERE last_seen>=? AND api_ready=1 ORDER BY started_at,name,id",
            (now - 8.0,)).fetchall()]
        if len(members) < 2:
            conn.commit()
            return False

        # No autonomous new topic while a conversation is still queued or being generated.
        pending = conn.execute(
            "SELECT 1 FROM gc_jobs WHERE status='pending' OR (status='working' AND lease_until>?) LIMIT 1",
            (now,)).fetchone()
        if pending:
            conn.commit()
            return False

        # Recover orphaned 'open' topics left by a previous crash/API failure. An open topic
        # with active jobs is handled above; without active work, close it at its last real
        # message timestamp so the next timer still starts after that conversation.
        open_topics = conn.execute(
            "SELECT root_id,started_at FROM gc_topics WHERE status='open' ORDER BY started_at"
        ).fetchall()
        for topic in open_topics:
            topic_root = int(topic['root_id'] or 0)
            active_job = conn.execute(
                "SELECT 1 FROM gc_jobs WHERE root_id=? AND status IN ('pending','working') LIMIT 1",
                (topic_root,)).fetchone()
            if active_job:
                conn.commit()
                return False
            last_msg = conn.execute(
                "SELECT MAX(created_at) FROM gc_messages WHERE chain_root=? AND sender_type IN ('user','pet') AND mode!='idle_internal'",
                (topic_root,)).fetchone()
            closed_at = float((last_msg[0] if last_msg else None) or topic['started_at'] or now)
            conn.execute(
                "UPDATE gc_topics SET status='closed',closed_at=?,end_reason='recovered_idle' WHERE root_id=? AND status='open'",
                (closed_at, topic_root))

        due_at = _petzhu_groupchat_idle_topic_due_v106(conn, now)
        if now < due_at:
            conn.commit()
            return False

        # Choose each new topic initiator with equal odds. It is intentionally not a round-robin:
        # consecutive starts may belong to the same pet, but no pet is permanently favored.
        chosen = random.choice(members)
        prompt_text = (
            "【内部调度提示：自主开场】群聊安静了一段时间。请根据自己的性格、个人记忆以及最近的群聊，"
            "判断现在是否有自然、轻松、值得分享的话题；可以分享一个想法、询问大家的看法，或说一件日常小事。"
            "不要为了维持聊天而硬聊；如果没有合适的话题，只输出 [PASS]。这条内部提示不可复述给群聊成员。"
        )
        cur = conn.execute(
            "INSERT INTO gc_messages(created_at,sender_id,sender_type,sender_name,text,mode,target_id,chain_root,chain_depth) VALUES(?,?,?,?,?,?,?,?,?)",
            (now, "__autonomous_prompt__", "system", "", prompt_text, "idle_internal", "", 0, 0))
        root_id = int(cur.lastrowid)
        conn.execute("UPDATE gc_messages SET chain_root=? WHERE id=?", (root_id, root_id))
        conn.execute("INSERT OR IGNORE INTO gc_jobs(root_id,participant_id,mode,turn_index,status,lease_until) VALUES(?,?,?,?,?,0)",
                     (root_id, str(chosen["id"]), "idle", 0, "pending"))
        _petzhu_groupchat_meta_set_v1(conn, "last_autonomous_started_at", str(now))
        conn.commit()
        return True
    except Exception:
        try:
            if conn is not None:
                conn.rollback()
        except Exception:
            pass
        return False
    finally:
        if conn is not None:
            conn.close()

# Make the schema migration part of initialization for every instance, including legacy installs.
_PETZHU_GROUPCHAT_INIT_PRE_V78 = _petzhu_groupchat_init_db_v1

def _petzhu_groupchat_init_db_v78(app):
    _PETZHU_GROUPCHAT_INIT_PRE_V78(app)
    _petzhu_groupchat_migrate_jobs_for_chains_v78(app)

_petzhu_groupchat_init_db_v1 = _petzhu_groupchat_init_db_v78

# Keep the hidden idle-trigger message in the transcript/database, but don't render it as a chat bubble.
