def _petzhu_groupchat_render_message_v78(app, win, inner, item, palette):
    if str(item.get("mode", "")) == "idle_internal":
        try:
            spacer = tk.Frame(inner, bg=palette.get("bg", "#141824"), height=1, bd=0, highlightthickness=0)
            _petzhu_groupchat_set_role_v1(spacer, "bg")
            spacer.pack(fill="x", padx=0, pady=0)
            spacer.pack_propagate(False)
            return spacer
        except Exception:
            # As a fallback, the internal trigger is still phrased as a non-secret system hint.
            return _PETZHU_GROUPCHAT_RENDER_PRE_V78(app, win, inner, item, palette)
    return _PETZHU_GROUPCHAT_RENDER_PRE_V78(app, win, inner, item, palette)

