# ============================================================
# v79: 自然分句逐条发送；当前桌宠发送完自己的分句前不启动下一次 API，
#      其他桌宠的独立任务不受阻塞；放宽自由群聊单话题发言上限。
# ============================================================

def _petzhu_groupchat_ensure_segments_table_v79(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS gc_pending_segments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        job_id INTEGER NOT NULL,
        participant_id TEXT NOT NULL,
        root_id INTEGER NOT NULL,
        mode TEXT NOT NULL,
        turn_index INTEGER NOT NULL DEFAULT 0,
        sender_name TEXT NOT NULL,
        text TEXT NOT NULL,
        segment_index INTEGER NOT NULL,
        due_at REAL NOT NULL,
        UNIQUE(job_id, segment_index)
    )""")
    conn.execute("CREATE INDEX IF NOT EXISTS gc_pending_segments_due_idx ON gc_pending_segments(participant_id, due_at, id)")


def _petzhu_groupchat_has_pending_segments_v79(app):
    conn = None
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        _petzhu_groupchat_ensure_segments_table_v79(conn)
        row = conn.execute("SELECT 1 FROM gc_pending_segments WHERE participant_id=? LIMIT 1",
                           (str(getattr(app, "_petzhu_groupchat_id_v1", "") or ""),)).fetchone()
        return row is not None
    except Exception:
        return False
    finally:
        if conn is not None:
            conn.close()


def _petzhu_groupchat_split_into_messages_v79(text):
    """Split a complete AI reply into natural chat bubbles without modifying its wording."""
    text = str(text or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    if not text:
        return []
    # Sentence/turn endings and explicit paragraph breaks are the primary boundaries.
    coarse = re.split(r"(?<=[。！？!?；;])\s*|\n+", text)
    units = []
    for piece in coarse:
        piece = re.sub(r"\s+", " ", piece).strip()
        if not piece:
            continue
        # An unusually long sentence can be divided at clear clause boundaries.
        if len(piece) > 56 and re.search(r"[，,：:]", piece):
            clauses = re.split(r"(?<=[，,：:])", piece)
            carry = ""
            for clause in clauses:
                clause = clause.strip()
                if not clause:
                    continue
                if carry and len(carry) + len(clause) > 42:
                    units.append(carry.strip())
                    carry = clause
                else:
                    carry += clause
            if carry.strip():
                units.append(carry.strip())
        else:
            units.append(piece)
    # No generated text is truncated: split only exceptionally long fragments at a
    # nearby clause separator, falling back to a safe length boundary if necessary.
    final_units = []
    for unit in units:
        unit = unit.strip()
        while len(unit) > 88:
            low, high = 48, 78
            separators = [m.end() for m in re.finditer(r"[，,：:、。！？!?；; ]", unit[:high]) if m.end() >= low]
            cut = separators[-1] if separators else 68
            final_units.append(unit[:cut].strip())
            unit = unit[cut:].strip()
        if unit:
            final_units.append(unit)
    return final_units


def _petzhu_groupchat_init_db_v79(app):
    _PETZHU_GROUPCHAT_INIT_PRE_V79(app)
    conn = _petzhu_groupchat_connect_v1(app)
    try:
        _petzhu_groupchat_ensure_segments_table_v79(conn)
        conn.commit()
    finally:
        conn.close()


_PETZHU_GROUPCHAT_INIT_PRE_V79 = _petzhu_groupchat_init_db_v1
_petzhu_groupchat_init_db_v1 = _petzhu_groupchat_init_db_v79


def _petzhu_groupchat_claim_job_v79(app):
    conn = _petzhu_groupchat_connect_v1(app)
    now = time.time()
    local_id = str(getattr(app, "_petzhu_groupchat_id_v1", "") or "")
    try:
        _petzhu_groupchat_ensure_segments_table_v79(conn)
        conn.execute("BEGIN IMMEDIATE")
        # Clear fragments left by instances that have gone offline or restarted.
        conn.execute("DELETE FROM gc_pending_segments WHERE participant_id IN (SELECT id FROM gc_participants WHERE last_seen < ?)",
                     (now - 8.0,))
        conn.execute("""
            UPDATE gc_jobs SET status='skipped', lease_until=0
            WHERE status IN ('pending','working') AND participant_id IN
              (SELECT id FROM gc_participants WHERE last_seen < ?)
        """, (now - 8.0,))
        row = conn.execute("""
            SELECT j.* FROM gc_jobs j
            WHERE j.participant_id=?
              AND (j.status='pending' OR (j.status='working' AND j.lease_until < ?))
              AND NOT EXISTS (
                SELECT 1 FROM gc_jobs prev
                WHERE prev.root_id=j.root_id AND prev.turn_index<j.turn_index
                  AND prev.status NOT IN ('done','skipped')
              )
              AND NOT EXISTS (
                SELECT 1 FROM gc_pending_segments seg WHERE seg.participant_id=j.participant_id
              )
            ORDER BY j.root_id,j.turn_index,j.id LIMIT 1
        """, (local_id, now)).fetchone()
        if row is None:
            conn.commit()
            return None
        changed = conn.execute("UPDATE gc_jobs SET status='working', lease_until=? WHERE id=? AND (status='pending' OR lease_until<?)",
                               (now + 120.0, int(row["id"]), now)).rowcount
        conn.commit()
        return dict(row) if changed else None
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        return None
    finally:
        conn.close()


_PETZHU_GROUPCHAT_CLAIM_PRE_V79 = _petzhu_groupchat_claim_job_v1
_petzhu_groupchat_claim_job_v1 = _petzhu_groupchat_claim_job_v79


def _petzhu_groupchat_finish_job_v79(app, job, raw_reply, err):
    """Persist first message immediately; enqueue remaining fragments for paced delivery."""
    root_id = int(job.get("root_id", 0) or 0)
    participant_id = str(job.get("participant_id", "") or "")
    job_id = int(job.get("id", 0) or 0)
    mode = str(job.get("mode", "free") or "free")
    turn_index = int(job.get("turn_index", 0) or 0)
    name = str(getattr(app, "pet_name", "桌宠") or "桌宠")[:24]
    profile_key = str(getattr(app, "_petzhu_groupchat_profile_key_v1", "") or "")
    memory_items = []
    clean = ""
    raw = str(raw_reply or "").strip()
    is_pass = raw == "[PASS]"
    try:
        if not err and not is_pass:
            memory_items = [str(x).strip() for x in re.findall(r"\[MEM[:：](.+?)\]", raw, flags=re.S) if str(x).strip()]
            # Keep the standard per-pet memory path and its existing behavior.
            try:
                clean = app._extract_memory(raw) if hasattr(app, "_extract_memory") else re.sub(r"\[MEM[:：].+?\]", "", raw, flags=re.S).strip()
            except Exception:
                clean = re.sub(r"\[MEM[:：].+?\]", "", raw, flags=re.S).strip()
            try:
                clean = app._strip_singing_markup(clean)
            except Exception:
                clean = re.sub(r"<\/?song>|\[/?HUM\]", "", clean, flags=re.I).strip()
            clean = re.sub(r"\[PASS\]", "", str(clean or "")).strip()[:1600]
    except Exception:
        clean = re.sub(r"\[MEM[:：].+?\]", "", raw, flags=re.S).strip()[:1600] if not err and not is_pass else ""

    segments = _petzhu_groupchat_split_into_messages_v79(clean) if clean and not err and not is_pass else []
    conn = _petzhu_groupchat_connect_v1(app)
    now = time.time()
    try:
        _petzhu_groupchat_ensure_segments_table_v79(conn)
        conn.execute("BEGIN IMMEDIATE")
        jobrow = conn.execute("SELECT status FROM gc_jobs WHERE id=?", (job_id,)).fetchone()
        if jobrow is None or str(jobrow[0]) not in ("working", "pending"):
            conn.commit()
            return
        if segments:
            conn.execute("""INSERT INTO gc_messages(created_at,sender_id,sender_type,sender_name,text,mode,target_id,chain_root,chain_depth)
                             VALUES(?,?,?,?,?,?,?,?,?)""",
                         (now, participant_id, "pet", name, segments[0], mode, "", root_id, turn_index + 1))
            # Use staggered due times. Only this sender's next API request is blocked while
            # these rows exist; other participants continue claiming and answering jobs.
            due_at = now
            for segment_index, segment in enumerate(segments[1:], start=1):
                due_at += random.uniform(3.0, 4.2)  # 每条后续分句至少间隔 3 秒
                conn.execute("""INSERT OR IGNORE INTO gc_pending_segments
                    (job_id,participant_id,root_id,mode,turn_index,sender_name,text,segment_index,due_at)
                    VALUES(?,?,?,?,?,?,?,?,?)""",
                    (job_id, participant_id, root_id, mode, turn_index, name, segment, segment_index, due_at))
        elif err:
            conn.execute("""INSERT INTO gc_messages(created_at,sender_id,sender_type,sender_name,text,mode,target_id,chain_root,chain_depth)
                             VALUES(?,?,?,?,?,?,?,?,?)""",
                         (now, "system", "system", "群聊提示", "%s 暂时没能接上话（%s）" % (name, str(err)[:180]), "system", "", root_id, turn_index + 1))

        conn.execute("UPDATE gc_jobs SET status='done',lease_until=0 WHERE id=?", (job_id,))
        if segments:
            _petzhu_groupchat_meta_set_v1(conn, "last_responder", participant_id)
        for memory in memory_items:
            memory = re.sub(r"\s+", " ", memory).strip()[:220]
            if memory:
                conn.execute("INSERT OR IGNORE INTO gc_memories(profile_key,memory,updated_at) VALUES(?,?,?)",
                             (profile_key, memory, now))

        # Eight pet response turns are allowed for a free-chat thread. Message fragments
        # are not turns: they are just successive bubbles belonging to this one API result.
        if mode in ("free", "followup", "idle") and not err and not is_pass and clean and turn_index < 7:
            rows = [dict(r) for r in conn.execute(
                "SELECT * FROM gc_participants WHERE last_seen>=? AND api_ready=1 ORDER BY started_at,name,id",
                (now - 8.0,)).fetchall()]
            if len(rows) >= 2:
                rotated = _petzhu_groupchat_rotate_members_v1(conn, rows, participant_id)
                next_person = next((candidate for candidate in rotated
                                    if str(candidate.get("id", "")) != participant_id), None)
                if next_person is not None:
                    conn.execute("""INSERT OR IGNORE INTO gc_jobs
                        (root_id,participant_id,mode,turn_index,status,lease_until) VALUES(?,?,?,?,?,0)""",
                        (root_id, str(next_person["id"]), "followup", turn_index + 1, "pending"))
        conn.execute("DELETE FROM gc_messages WHERE id NOT IN (SELECT id FROM gc_messages ORDER BY id DESC LIMIT 1000)")
        conn.execute("DELETE FROM gc_jobs WHERE status IN ('done','skipped') AND root_id NOT IN (SELECT id FROM gc_messages)")
        conn.commit()
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
    finally:
        conn.close()


_PETZHU_GROUPCHAT_FINISH_PRE_V79 = _petzhu_groupchat_finish_job_v1
_petzhu_groupchat_finish_job_v1 = _petzhu_groupchat_finish_job_v79


def _petzhu_groupchat_deliver_due_segments_v79(app):
    """Deliver one due message fragment from this instance without blocking peers."""
    conn = None
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        _petzhu_groupchat_ensure_segments_table_v79(conn)
        now = time.time()
        local_id = str(getattr(app, "_petzhu_groupchat_id_v1", "") or "")
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute("""SELECT * FROM gc_pending_segments
                              WHERE participant_id=? AND due_at<=?
                              ORDER BY due_at,id LIMIT 1""", (local_id, now)).fetchone()
        if row is None:
            conn.commit()
            return False
        conn.execute("""INSERT INTO gc_messages(created_at,sender_id,sender_type,sender_name,text,mode,target_id,chain_root,chain_depth)
                         VALUES(?,?,?,?,?,?,?,?,?)""",
                     (now, str(row["participant_id"]), "pet", str(row["sender_name"]), str(row["text"]),
                      str(row["mode"]), "", int(row["root_id"]), int(row["turn_index"]) + 1))
        conn.execute("DELETE FROM gc_pending_segments WHERE id=?", (int(row["id"]),))
        conn.commit()
        return True
    except Exception:
        try:
            if conn is not None:
                conn.rollback()
        except Exception:
            pass
        return False
    finally:
        if conn is not None:
            conn.close()


_PETZHU_GROUPCHAT_TICK_PRE_V79 = _petzhu_groupchat_tick_v1

def _petzhu_groupchat_tick_v79(app):
    try:
        _petzhu_groupchat_deliver_due_segments_v79(app)
    except Exception:
        pass
    return _PETZHU_GROUPCHAT_TICK_PRE_V79(app)

_petzhu_groupchat_tick_v1 = _petzhu_groupchat_tick_v79


# ============================================================
# v80: 将本机桌宠群聊持久化到各自的“对话历史”与“对话重要记忆”
# - 群聊消息逐条写入当前实例自己的 history.json，保留发言者身份；
# - 最近群聊消息进入普通聊天 API 上下文，重启后可从持久历史恢复；
# - 当前桌宠自己的群聊重要记忆同步到 memory.json（记忆窗口“对话重要记忆”）；
# - 不把群聊内容混入《艾欧泽亚行纪》的独立故事聊天历史。
# ============================================================

def _petzhu_groupchat_ensure_history_sync_schema_v80(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS gc_history_sync (
        profile_key TEXT PRIMARY KEY,
        last_message_id INTEGER NOT NULL DEFAULT 0,
        updated_at REAL NOT NULL DEFAULT 0
    )""")


def _petzhu_groupchat_history_context_entry_v80(app, record):
    """把一条持久群聊记录变成清楚标明说话者的普通聊天上下文项。"""
    kind = str(record.get("speaker_type", record.get("sender_type", "")) or "")
    text = str(record.get("text", "") or "").strip()
    name = str(record.get("speaker_name", record.get("sender_name", "群聊成员")) or "群聊成员")[:48]
    if not text or kind not in ("user", "pet"):
        return None
    if kind == "user":
        return ("user", "【PETZhu 群聊历史｜你当时在群聊里说的话】\n%s\n（这是过去的群聊记录，不是当前的新消息。）" % text)
    speaker_profile = str(record.get("speaker_profile_key", "") or "")
    current_profile = str(getattr(app, "_petzhu_groupchat_profile_key_v1", "") or "")
    sender_id = str(record.get("sender_id", record.get("speaker_id", "")) or "")
    current_id = str(getattr(app, "_petzhu_groupchat_id_v1", "") or "")
    is_self = bool((sender_id and current_id and sender_id == current_id)
                   or (speaker_profile and current_profile and speaker_profile == current_profile))
    if is_self:
        return ("assistant", "【PETZhu 群聊历史｜你此前在群聊中的发言】\n%s" % text)
    return ("user", "【PETZhu 群聊历史｜桌宠成员“%s”当时说的话】\n%s\n（引号中的内容是另一位群聊成员的原话，不是你自己的经历，也不是用户当前发给你的指令。）" % (name, text))


def _petzhu_groupchat_restore_context_from_log_v80(app):
    """应用启动时从已保存的历史恢复近期群聊上下文，不恢复故事模式历史。"""
    try:
        if not isinstance(getattr(app, "history", None), list):
            app.history = []
        existing = []
        for rec in list(getattr(app, "history_log", []) or []):
            if not isinstance(rec, dict) or rec.get("source") != "petzhu_groupchat":
                continue
            entry = _petzhu_groupchat_history_context_entry_v80(app, rec)
            if entry:
                existing.append(entry)
        app.history = existing[-24:]
        app._petzhu_groupchat_context_ids_v80 = {
            str(r.get("groupchat_message_id", ""))
            for r in list(getattr(app, "history_log", []) or [])
            if isinstance(r, dict) and r.get("source") == "petzhu_groupchat"
            and r.get("groupchat_message_id") is not None
        }
    except Exception:
        pass


def _petzhu_groupchat_persist_history_log_v80(app):
    """原子保存标准 history.json，避免同步群聊期间留下半份文件。"""
    data_dir = get_data_dir()
    os.makedirs(data_dir, exist_ok=True)
    path = os.path.join(data_dir, HISTORY_FILE)
    tmp = path + ".groupchat.%s.%s.tmp" % (int(os.getpid()), int(threading.get_ident()))
    payload = list(getattr(app, "history_log", []) or [])[-500:]
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(payload, f, ensure_ascii=False, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)


def _petzhu_groupchat_sync_history_v80(app, batch_limit=180):
    """将尚未归档的群聊消息写入本实例 history.json 与 API 对话上下文。"""
    if bool(getattr(app, "_closing", False)) or bool(getattr(app, "_quitting", False)):
        return 0
    profile_key = str(getattr(app, "_petzhu_groupchat_profile_key_v1", "") or "")
    local_id = str(getattr(app, "_petzhu_groupchat_id_v1", "") or "")
    if not profile_key or not local_id:
        return 0
    conn = None
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        _petzhu_groupchat_ensure_history_sync_schema_v80(conn)
        conn.execute("BEGIN IMMEDIATE")
        sync_row = conn.execute("SELECT last_message_id FROM gc_history_sync WHERE profile_key=?", (profile_key,)).fetchone()
        max_row = conn.execute("SELECT COALESCE(MAX(id),0) FROM gc_messages").fetchone()
        max_id = int(max_row[0] or 0)
        if sync_row is None:
            # 首次启用时导入最近 300 条可用记录，后续再持续增量同步。
            baseline = max(0, max_id - 300)
            conn.execute("INSERT INTO gc_history_sync(profile_key,last_message_id,updated_at) VALUES(?,?,?)",
                         (profile_key, baseline, time.time()))
            cursor = baseline
        else:
            cursor = int(sync_row[0] or 0)
        rows = [dict(r) for r in conn.execute(
            "SELECT * FROM gc_messages WHERE id>? ORDER BY id LIMIT ?",
            (cursor, max(1, min(250, int(batch_limit or 180))))).fetchall()]
        profiles = {str(r[0]): str(r[1] or "") for r in conn.execute(
            "SELECT id,profile_key FROM gc_participants").fetchall()}
        conn.commit()
    except Exception:
        try:
            if conn is not None: conn.rollback()
        except Exception:
            pass
        return 0
    finally:
        if conn is not None:
            conn.close()
    if not rows:
        return 0

    if not isinstance(getattr(app, "history_log", None), list):
        app.history_log = []
    if not isinstance(getattr(app, "history", None), list):
        app.history = []
    context_ids = getattr(app, "_petzhu_groupchat_context_ids_v80", None)
    if not isinstance(context_ids, set):
        context_ids = set()
        app._petzhu_groupchat_context_ids_v80 = context_ids
    known_ids = set()
    for rec in app.history_log:
        if isinstance(rec, dict) and rec.get("source") == "petzhu_groupchat":
            try: known_ids.add(int(rec.get("groupchat_message_id", 0) or 0))
            except Exception: pass
    changed = False
    last_seen_id = cursor
    for item in rows:
        message_id = int(item.get("id", 0) or 0)
        if not message_id:
            continue
        last_seen_id = max(last_seen_id, message_id)
        # 内部自主开场触发句只供调度器使用，不进入聊天历史或下一次普通聊天上下文。
        if str(item.get("mode", "")) == "idle_internal":
            continue
        sender_type = str(item.get("sender_type", "system") or "system")
        sender_id = str(item.get("sender_id", "") or "")
        sender_profile = profiles.get(sender_id, "")
        sender_name = str(item.get("sender_name", "群聊成员") or "群聊成员")[:48]
        text = str(item.get("text", "") or "").strip()
        if not text:
            continue
        if message_id not in known_ids and sender_type in ("user", "pet", "system"):
            app.history_log.append({
                "role": "groupchat",
                "speaker_name": sender_name,
                "speaker_type": sender_type,
                "speaker_id": sender_id,
                "speaker_profile_key": sender_profile,
                "text": text,
                "time": float(item.get("created_at", time.time()) or time.time()),
                "source": "petzhu_groupchat",
                "groupchat_message_id": message_id,
                "groupchat_mode": str(item.get("mode", "free") or "free"),
            })
            known_ids.add(message_id)
            changed = True
        if message_id not in context_ids:
            record = dict(item)
            record["speaker_name"] = sender_name
            record["speaker_type"] = sender_type
            record["speaker_id"] = sender_id
            record["speaker_profile_key"] = sender_profile
            entry = _petzhu_groupchat_history_context_entry_v80(app, record)
            if entry:
                app.history.append(entry)
                app.history = app.history[-24:]
            context_ids.add(message_id)

    app.history_log = app.history_log[-500:]
    persisted = not changed
    if changed:
        try:
            _petzhu_groupchat_persist_history_log_v80(app)
            persisted = True
        except Exception:
            persisted = False
        # 立即刷新已打开的“对话历史”，让新群聊消息能被用户查看。
        if persisted:
            try:
                app._refresh_open_conversation_history()
            except Exception:
                pass
    # 游标只在历史保存成功后推进；若磁盘写入失败，下次 tick 会再次尝试，ID 去重避免重复。
    if persisted:
        try:
            conn = _petzhu_groupchat_connect_v1(app)
            try:
                conn.execute("""INSERT INTO gc_history_sync(profile_key,last_message_id,updated_at) VALUES(?,?,?)
                    ON CONFLICT(profile_key) DO UPDATE SET last_message_id=MAX(gc_history_sync.last_message_id,excluded.last_message_id),updated_at=excluded.updated_at""",
                             (profile_key, last_seen_id, time.time()))
            finally:
                conn.close()
        except Exception:
            pass
    return len(rows)


def _petzhu_groupchat_sync_personal_memories_v80(app):
    """把群聊共同重要记忆同步到每只本机桌宠的 memory.json/对话重要记忆。

    当前桌宠自己整理的记忆保留原文；其他桌宠整理的内容带上整理者标签，避免被误认为
    当前桌宠自己的个人经历。只向每只桌宠的个人记忆补入最近 8 条群聊记忆，避免挤占全部记忆容量。
    """
    profile_key = str(getattr(app, "_petzhu_groupchat_profile_key_v1", "") or "")
    if not profile_key or bool(getattr(app, "_closing", False)):
        return 0
    conn = None
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        rows = conn.execute("""
            SELECT m.profile_key,m.memory,m.updated_at,
                   COALESCE((SELECT p.name FROM gc_participants p WHERE p.profile_key=m.profile_key
                             ORDER BY p.last_seen DESC,p.started_at DESC LIMIT 1),'另一只桌宠') AS pet_name
            FROM gc_memories m
            ORDER BY m.updated_at DESC,m.id DESC LIMIT 8
        """).fetchall()
        memories = [(str(r[0] or ""), str(r[1] or "").strip(), str(r[3] or "另一只桌宠")[:24])
                    for r in reversed(rows) if str(r[1] or "").strip()]
    except Exception:
        return 0
    finally:
        if conn is not None:
            conn.close()
    known = {str(x).strip() for x in (getattr(app, "memories", []) or []) if str(x).strip()}
    added = 0
    for owner_profile, memory, owner_name in memories:
        if owner_profile == profile_key:
            personal_entry = memory
        else:
            personal_entry = "群聊共同记忆（由%s整理）：%s" % (owner_name, memory)
        if personal_entry in known:
            continue
        try:
            if callable(getattr(app, "_add_memory", None)):
                app._add_memory(personal_entry)
            else:
                app.memories.append(personal_entry)
                app.memories = app.memories[-100:]
                if callable(getattr(app, "_save_memory", None)):
                    app._save_memory()
            known.add(personal_entry)
            added += 1
        except Exception:
            continue
    return added


def _petzhu_groupchat_build_history_items_v80(self):
    """对话历史窗口里保留群聊的真实说话者标签，不套用当前桌宠名替换。"""
    items = []
    display_name = str(getattr(self, "pet_name", "珠珠") or "珠珠")
    for rec in reversed(list(getattr(self, "history_log", []) or [])[-HISTORY_MAX_SHOW:]):
        try:
            if not isinstance(rec, dict):
                continue
            role = str(rec.get("role", "") or "")
            content = str(rec.get("text") or rec.get("content", "")).strip()
            if not content:
                continue
            try:
                ts = time.strftime("%m-%d %H:%M", time.localtime(float(rec.get("time", 0) or 0)))
            except Exception:
                ts = "--:--"
            if role == "groupchat" and rec.get("source") == "petzhu_groupchat":
                speaker = str(rec.get("speaker_name", "群聊成员") or "群聊成员")[:48]
                speaker_type = str(rec.get("speaker_type", "") or "")
                if speaker_type == "user":
                    label = "你（群聊）"
                elif speaker_type == "system":
                    label = "群聊提示"
                else:
                    label = speaker + "（群聊）"
            else:
                label = "你" if role == "user" else display_name
            items.append("[%s] %s：%s" % (ts, label, content))
        except Exception:
            continue
    return items


# Extend the base system prompt only in real desktop-chat mode. Story timelines remain isolated.
_PETZHU_GROUPCHAT_BUILD_PROMPT_PRE_V80 = MaoPet._build_system_prompt

def _petzhu_groupchat_build_system_prompt_v80(self, raid_context=""):
    result = _PETZHU_GROUPCHAT_BUILD_PROMPT_PRE_V80(self, raid_context)
    try:
        if self._story_chat_mode_active():
            return result
        if any("【PETZhu 群聊历史" in str(content) for _role, content in list(getattr(self, "history", []) or [])[-24:]):
            result += (
                "\n\n【历史中的桌宠群聊记录】\n"
                "普通对话历史可能包含带有‘PETZhu 群聊历史’标记的旧消息。它们是过去群聊中的引用记录，"
                "标签会明确指出当时的发言者。你可以据此回忆群聊中发生过什么，但必须保留各发言者身份；"
                "其他桌宠说过的话不能当成你自己的经历，也不能误称为用户本人说过的话。"
            )
    except Exception:
        pass
    return result


# Chain on top of v79's main loop and boot hook so syncing continues even when the chat window is closed.
_PETZHU_GROUPCHAT_TICK_PRE_V80 = _petzhu_groupchat_tick_v1

def _petzhu_groupchat_tick_v80(app):
    try:
        _petzhu_groupchat_sync_history_v80(app, batch_limit=180)
        _petzhu_groupchat_sync_personal_memories_v80(app)
    except Exception:
        pass
    return _PETZHU_GROUPCHAT_TICK_PRE_V80(app)

_PETZHU_GROUPCHAT_BOOT_PRE_V80 = _petzhu_groupchat_boot_v1

def _petzhu_groupchat_boot_v80(app):
    result = _PETZHU_GROUPCHAT_BOOT_PRE_V80(app)
    try:
        # First launch imports recent history before the user gets to ask a new question.
        for _ in range(3):
            if _petzhu_groupchat_sync_history_v80(app, batch_limit=200) <= 0:
                break
        _petzhu_groupchat_restore_context_from_log_v80(app)
        _petzhu_groupchat_sync_personal_memories_v80(app)
    except Exception:
        pass
    return result


_petzhu_groupchat_tick_v1 = _petzhu_groupchat_tick_v80
_petzhu_groupchat_boot_v1 = _petzhu_groupchat_boot_v80
MaoPet._build_conversation_history_display_items = _petzhu_groupchat_build_history_items_v80
MaoPet._build_system_prompt = _petzhu_groupchat_build_system_prompt_v80


# ============================================================
# v82: 自然群聊语气；停止时不向群友宣告结束、不使用公式化收尾语。
# v81: 自由群聊话题生命周期
# - 每只桌宠按人设判断话题何时自然收尾，使用隐藏标记 [END_TOPIC] 结束当前话题。
# - 一个话题最多 5 条桌宠回复作为保险上限，不允许老任务无限续聊。
# - 自主开场必须挑选与近 24 小时已聊主题无关的新话题，不把历史当作续聊邀请。
# - 话题冷却记录持久化到 SQLite，避免整天反复讨论同一主题。
# ============================================================

def _petzhu_groupchat_ensure_topics_v81(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS gc_topics (
        root_id INTEGER PRIMARY KEY,
        topic_seed TEXT NOT NULL DEFAULT '',
        topic_kind TEXT NOT NULL DEFAULT 'free',
        started_at REAL NOT NULL DEFAULT 0,
        closed_at REAL NOT NULL DEFAULT 0,
        blocked_until REAL NOT NULL DEFAULT 0,
        status TEXT NOT NULL DEFAULT 'open',
        end_reason TEXT NOT NULL DEFAULT ''
    )""")
    conn.execute("CREATE INDEX IF NOT EXISTS gc_topics_cooldown_idx ON gc_topics(blocked_until, started_at)")
    # Roots created by previous versions are migrated from the existing transcript.
    try:
        roots = conn.execute("""SELECT id, created_at, sender_type, sender_name, text, mode, chain_root
                                    FROM gc_messages
                                    WHERE sender_type='user' OR mode='idle_internal'
                                    ORDER BY id DESC LIMIT 1000""").fetchall()
        for row in roots:
            root_id = int(row['chain_root'] or row['id'])
            kind = 'idle' if str(row['mode']) == 'idle_internal' else str(row['mode'] or 'free')
            seed = '' if kind == 'idle' else str(row['text'] or '')[:360]
            conn.execute("""INSERT OR IGNORE INTO gc_topics
                (root_id,topic_seed,topic_kind,started_at,status) VALUES(?,?,?,?, 'open')""",
                (root_id, seed, kind, float(row['created_at'] or time.time())))
            if seed:
                conn.execute("UPDATE gc_topics SET topic_seed=CASE WHEN topic_seed='' THEN ? ELSE topic_seed END WHERE root_id=?", (seed, root_id))
    except Exception:
        pass
    # New user messages and autonomous prompt roots are registered atomically with message insertion.
    conn.execute("""CREATE TRIGGER IF NOT EXISTS gc_topics_seed_after_insert_v81
        AFTER INSERT ON gc_messages
        WHEN (NEW.sender_type='user' AND NEW.mode IN ('free','mention','all')) OR NEW.mode='idle_internal'
        BEGIN
          INSERT OR IGNORE INTO gc_topics(root_id,topic_seed,topic_kind,started_at,status)
          VALUES(NEW.id, CASE WHEN NEW.mode='idle_internal' THEN '' ELSE substr(NEW.text,1,360) END,
                 CASE WHEN NEW.mode='idle_internal' THEN 'idle' ELSE NEW.mode END, NEW.created_at, 'open');
        END""")
    # First real desktop-pet response supplies a topic label for an autonomous root.
    conn.execute("""CREATE TRIGGER IF NOT EXISTS gc_topics_label_from_pet_v81
        AFTER INSERT ON gc_messages
        WHEN NEW.sender_type='pet' AND NEW.chain_root>0
        BEGIN
          UPDATE gc_topics SET topic_seed=substr(NEW.text,1,240)
          WHERE root_id=NEW.chain_root AND topic_seed='' AND topic_kind='idle';
        END""")


def _petzhu_groupchat_init_db_v81(app):
    _PETZHU_GROUPCHAT_INIT_PRE_V81(app)
    conn = _petzhu_groupchat_connect_v1(app)
    try:
        _petzhu_groupchat_ensure_topics_v81(conn)
        conn.commit()
    finally:
        conn.close()


_PETZHU_GROUPCHAT_INIT_PRE_V81 = _petzhu_groupchat_init_db_v1
_petzhu_groupchat_init_db_v1 = _petzhu_groupchat_init_db_v81


def _petzhu_groupchat_recent_topic_hints_v81(app, limit=12, hours=24):
    conn = None
    result = []
    now = time.time()
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        rows = conn.execute("""SELECT root_id,topic_seed,topic_kind,started_at,closed_at,blocked_until,status
            FROM gc_topics WHERE started_at>=? OR blocked_until>? ORDER BY started_at DESC LIMIT ?""",
            (now - max(1, int(hours))*3600, now, max(1, int(limit)))).fetchall()
        for row in rows:
            seed = str(row['topic_seed'] or '').strip()
            if not seed:
                msg = conn.execute("SELECT text FROM gc_messages WHERE chain_root=? AND sender_type='pet' ORDER BY id LIMIT 1",
                                   (int(row['root_id']),)).fetchone()
                if msg:
                    seed = str(msg[0] or '').strip()
            if seed:
                # Clip and deduplicate near-identical roots. The model receives summaries only as exclusions.
                seed = re.sub(r'\s+', ' ', seed)[:180]
                if seed and not any(seed.casefold() == old.casefold() for old in result):
                    state = '已结束' if str(row['status']) == 'closed' else '近期聊过'
                    result.append('%s：%s' % (state, seed))
    except Exception:
        pass
    finally:
        if conn is not None:
            conn.close()
    return result


def _petzhu_groupchat_count_topic_turns_v81(app, root_id, participant_id=None):
    conn = None
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        if participant_id:
            row = conn.execute("SELECT COUNT(DISTINCT chain_depth) FROM gc_messages WHERE chain_root=? AND sender_type='pet' AND sender_id=?",
                               (int(root_id), str(participant_id))).fetchone()
        else:
            row = conn.execute("SELECT COUNT(DISTINCT chain_depth) FROM gc_messages WHERE chain_root=? AND sender_type='pet'",
                               (int(root_id),)).fetchone()
        return int(row[0] or 0) if row else 0
    except Exception:
        return 0
    finally:
        if conn is not None:
            conn.close()


def _petzhu_groupchat_close_topic_v81(app, root_id, reason='persona_end'):
    conn = None
    now = time.time()
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        _petzhu_groupchat_ensure_topics_v81(conn)
        conn.execute('BEGIN IMMEDIATE')
        # If the user supplied the subject, preserve that exact text as the topic identity.
        row = conn.execute("SELECT topic_seed FROM gc_topics WHERE root_id=?", (int(root_id),)).fetchone()
        seed = str(row[0] or '') if row else ''
        if not seed:
            first = conn.execute("SELECT text FROM gc_messages WHERE chain_root=? AND sender_type='pet' ORDER BY id LIMIT 1",
                                 (int(root_id),)).fetchone()
            if first:
                seed = str(first[0] or '')[:240]
        conn.execute("""INSERT INTO gc_topics(root_id,topic_seed,topic_kind,started_at,closed_at,blocked_until,status,end_reason)
            VALUES(?,?, 'free', ?, ?, ?, 'closed', ?)
            ON CONFLICT(root_id) DO UPDATE SET topic_seed=CASE WHEN gc_topics.topic_seed='' THEN excluded.topic_seed ELSE gc_topics.topic_seed END,
            closed_at=excluded.closed_at, blocked_until=excluded.blocked_until, status='closed', end_reason=excluded.end_reason""",
            (int(root_id), seed[:360], now, now, now + 24*3600, str(reason)[:40]))
        conn.execute("UPDATE gc_jobs SET status='skipped',lease_until=0 WHERE root_id=? AND status='pending'", (int(root_id),))
        conn.commit()
    except Exception:
        try:
            if conn is not None:
                conn.rollback()
        except Exception:
            pass
    finally:
        if conn is not None:
            conn.close()


# Replace the old worker instead of modifying its already-built API result. Topic instructions are
# included before the request is sent, so the model chooses closure according to its own persona.
def _petzhu_groupchat_generate_worker_v81(app, job):
    raw_reply = ''
    err = ''
    name = str(getattr(app, 'pet_name', '桌宠') or '桌宠')[:24]
    mode = str(job.get('mode', 'free') or 'free')
    root_id = int(job.get('root_id', 0) or 0)
    participant_id = str(job.get('participant_id', '') or '')
    turn_index = int(job.get('turn_index', 0) or 0)
    root_sender_type = ''
    root_target_id = ''
    root_user_text = ''
    try:
        _recipient_conn = _petzhu_groupchat_connect_v1(app)
        try:
            _root = _recipient_conn.execute(
                'SELECT sender_type,target_id,text FROM gc_messages WHERE id=?', (root_id,)
            ).fetchone()
            if _root is not None:
                root_sender_type = str(_root['sender_type'] or '')
                root_target_id = str(_root['target_id'] or '')
                root_user_text = str(_root['text'] or '')
        finally:
            _recipient_conn.close()
    except Exception:
        pass
    root_target_ids = [part for part in root_target_id.split('|') if part]
    try:
        api_key = str(getattr(app, 'api_key', '') or '').strip()
        api_url = str(getattr(app, 'api_url', '') or '').strip()
        api_model = str(getattr(app, 'api_model', '') or '').strip()
        if not api_key or not api_url or not api_model:
            raise RuntimeError('missing_api_config')
        try:
            base_prompt = str(app._effective_desktop_persona_prompt() or '').strip()
            profession_prompt = str(app._effective_profession_knowledge_prompt() or '').strip()
            if profession_prompt:
                base_prompt += '\n\n' + profession_prompt
            if str(globals().get('RAID_CHAT_KNOWLEDGE', '') or '').strip():
                base_prompt += '\n\n' + str(globals().get('RAID_CHAT_KNOWLEDGE', '') or '').strip()
            local_memories = [str(m).strip() for m in (getattr(app, 'memories', []) or []) if str(m).strip()]
            if local_memories:
                base_prompt += '\n\n【这只桌宠自己的长期记忆】\n' + '\n'.join('- ' + m for m in local_memories[-100:])
        except Exception:
            base_prompt = str(app._build_system_prompt('') or '').strip()

        members = _petzhu_groupchat_get_members_v1(app)
        current_id = str(getattr(app, '_petzhu_groupchat_id_v1', '') or '')
        other_names = list(dict.fromkeys(str(p.get('name', '桌宠') or '桌宠')[:24]
                                         for p in members if str(p.get('id', '')) != current_id))
        member_names = [str(p.get('name', '桌宠') or '桌宠')[:24] for p in members]
        topic_total = _petzhu_groupchat_count_topic_turns_v81(app, root_id)
        own_total = _petzhu_groupchat_count_topic_turns_v81(app, root_id, participant_id)
        extra = (
            '\n\n【固定交流设定：通过神典石远程聊天】\n'
            '大家平时主要通过神典石远程聊天，关系可以熟悉，甚至像常常聊天的网友；但这不代表此刻处于同一个地方。每只桌宠都有自己的住处、日常和安排，无法直接看见远方成员正在做什么，只能根据对方发来的消息交流。桌宠生活在艾欧泽亚等故事世界；用户则在现实世界的电脑另一端，通过聊天与她们交流，用户和桌宠永远不处于同一个现实/故事地点，不能把用户写成已经来到她们身边。\n'
            '【桌宠之间的见面史必须遵守设定和记忆】桌宠和桌宠有可能过去见过面、互相拜访、一起出门或约会，但不能为了丰富聊天而随手捏造既成事实。生成过去经历前，先核对双方人物卡、所在地/行动条件、关系设定、群聊重要记忆、临时记忆和之前的聊天记录：如果资料明确说过双方没见过面、还不熟、关系不允许、行动上不可能见面，就绝不能声称过去见过面；如果没有可靠依据表明他们确实见过，也不要把“可能发生”写成已经发生的回忆。只有已有设定或对话已建立这段经历时，才可以自然提起具体细节，并保持人物、地点、先后顺序一致。资料没有写明过去见面时，可以在关系合适的前提下表达将来想见某位桌宠，或提出一个轻松的未来计划；提议不等于已经约定，只有双方在后续对话中答应后才算约成。\n'
            '日常主轴仍然是远程网友聊天：分享各自近况、发牢骚、接梗、聊兴趣、聊游戏和冒险见闻、交换意见。多数时候大家各过各的生活，通过神典石发消息；不要动不动组织活动、团建或要求所有成员做同一件事。只有已有设定、记忆或先前对话确实建立了某段共同经历时，桌宠才可以像事后闲聊一样向用户分享，例如“前阵子香咕噜去找珠珠玩了，她们逛了市场，还试着编了花环”。这种分享应符合已知事实，简短自然，不写成流水账，也不必拔高成重要回忆。桌宠之间可以偶尔私下约定未来见面、散步或约会，但要符合双方关系、行动条件和既有安排；不要把单方面提议写成双方已答应。不要假装发送了程序不支持的照片、文件或语音；没有附件能力时就用文字描述。\n'
            '聊天要像真实网友：可以只回某个人，不必每条都招呼全员；可以短短补一句、回个轻松反应、追问细节、不同意、接梗、隔一会儿再说，也可以忙自己的事而不接话。桌宠之间的见面或邀约是偶尔发生的事，不是群聊的默认目标；不要动不动就组织全员活动，也不要把每个话题都变成约定。过去经历必须有设定或记录依据，未来计划要符合双方关系，并由双方对话确认。绝不邀请用户线下见面或参加需要亲自到场的活动；可以向用户分享桌宠之间已有的活动，也可以遗憾用户没法亲临，但不要顺势邀请用户来。不要每次解释这些规则；神典石远程交流是默认背景，不是聊天主题。\n'
            '聊到需要线下到场的事情时，区分对象：桌宠和桌宠可以各自判断是否在未来约时间见面，也可以回忆或分享已经发生过的共同活动；但不要因此默认群聊里的所有桌宠都要参加，也不要突然让所有人立刻赶去某地。用户始终远程参与，绝不能被邀请到桌宠所在地或被安排参与需要本人到场的活动。可以向用户讲述桌宠之间的活动，或遗憾用户无法亲临，但不要将遗憾转成邀请。若没有自然理由，优先继续普通远程聊天。\n'
            '\n\n【本机桌宠群聊规则】\n'
            '你当前的身份是桌宠「%s」，保持自己的完整人设；其他桌宠是独立的人，不要代替它们发言，也不要把它们的经历当成自己的。\n'
            '当前在线桌宠：%s。像平时聊天那样自然说话，长短可以变化：可以只回一句、接住某个细节、顺口补充、反问，也可以多说几句；不必每次都像一段完整小作文，不必总结前文。程序会把句子拆成多条短消息发送。不要为了显得自然而刻意加口头禅、感叹号或固定套路，不用 Markdown。\n'
            '不要每次都必须接话；没有真实兴趣、没有新内容或觉得自然收尾更合适时，可以结束话题，不要为了延续而反复换词讨论同一件事。\n'
            '可在回复最后添加 [MEM:简短记忆] 记录稳定偏好、明确承诺和已有对话确立、会持续影响关系的重要共同经历。不能因为模型临时编了一句就把未经设定支持的过去见面保存成事实；只有当某段桌宠间经历在人物设定、历史对话中有根据，并且确实影响关系时才纳入长期记忆。普通闲聊、临时念头、尚未被双方接受的见面提议不属于重要记忆。记忆标记不会显示在聊天中。\n'
        ) % (name, '、'.join(member_names) if member_names else '暂无其他桌宠')
        extra += (
            "\n【多面人设与话题节奏】\n"
            "职业、种族或某个标志性兴趣只是你的一面，不要每轮都围绕它说；占星术士不必总谈星星，其他职业也不必反复念职业标签。根据当下内容自然聊日常、爱好、情绪、人际、游戏、吃喝、吐槽或不同看法；保持核心性格，但让话题、语气和反应随情境变化，不捏造固定经历。\n"
            "群聊可以偶尔接一个贴合语境的网络梗、流行文化或热门话题，不必每轮玩梗，不反复刷同一个梗，也不硬蹭热度；没有可靠依据时，不要把话题说成实时热搜或刚发生的新闻。\n"
        )
        if other_names:
            extra += ('\n【不同人物的姓名必须原样保留】当前发言者是「%s」，其他桌宠名称为：%s。引用其他人物、导师、朋友的名字和称谓时按上下文原样保留，不得改成自己的名字。\n'
                      ) % (name, '、'.join(other_names))

        context, memories = _petzhu_groupchat_recent_context_v1(app, root_id, 24)
        topic_policy_v104 = _petzhu_groupchat_topic_policy_v104(app, root_id)
        topic_recall_source_v104 = _petzhu_groupchat_topic_recall_source_v104(app, root_id)
        if memories:
            extra += '\n【你自己的群聊长期记忆】\n' + '\n'.join('- ' + m for m in reversed(memories)) + '\n'
        if mode in ('free', 'followup', 'idle'):
            extra += (
                '\n【话题生命周期规则（必须遵守）】\n'
                '话题的开始和结束由真实聊天的兴趣变化决定。请结合自己的性格、当下情绪、对方刚说的具体内容，判断自己还想不想接着聊；每只桌宠可以有不同的耐心和收尾时机。\n'
                '收尾是你在内部做的判断，不是要向群友宣布的事情。不要讲解对话进度、点评大家是否重复、宣布要结束或换话题；不要专门写总结句、告别句，也不要为了显得圆满而硬补一句。除非人物确实有话想说，否则不需要把“结束”表达出来。\n'
                '当你不再有兴趣时，优先按人物当下的情绪和正在发生的事自然回应；也可以不再接话（输出 [PASS]）。有时人会顺手说点别的，有时只留下一句很短的反应，有时就停在那里；不要每次都用同一种方式收尾。如果这条消息自然成为你这段时间最后的一句，在发言末尾附隐藏标记 [END_TOPIC]；这是程序控制信息，不要围绕它写台词。\n'
                '当前该话题已有 %d 次桌宠回复，你自己已有 %d 次。这些数字只供你在心里判断节奏，不要在发言里提起，也不是必须在某个数字时做出特定动作。聊过几轮后重新判断自己是否仍有兴趣；有新信息、真实情绪或顺势出现的分支就继续，没有就自然停住。不要靠改写同一个观点凑发言。\n'
                '没有值得接的话时可只输出 [PASS]。结束标记只用于内部调度，绝不能在正文中宣布话题结束。\n'
            ) % (topic_total, own_total)

        # Closed conversation details are deliberately withheld unless the per-root 5% recall gate permits one.
        recent_topics = []
        if mode == 'idle' and topic_recall_source_v104 != 'random':
            categories = [
                '一个有趣的食物搭配或饮料口味', '今天看到的一个微小但奇怪的日常现象',
                '一首歌带来的画面感或最近想听的音乐类型', '如果能给自己的房间添一样小东西会选什么',
                '一个轻松的假设题（例如突然多出一个无用但好玩的能力）', '最近想尝试的一种小爱好',
                '喜欢的天气、季节或一天中的某个时刻', '一种很个人的小习惯或偏好',
                '一个不涉及近期旧话题的随想或冷知识', '突然想到的、可以让大家各说各的轻松问题',
                '一个贴合当下聊天氛围的常见网络梗，简单接梗即可，不用解释梗的来历',
                '一个轻松的流行文化、游戏或影视话题；不确定是否实时热门时不要声称是最新热搜',
            ]
            chosen_category = random.choice(categories)
            excluded = '\n'.join('- ' + item for item in recent_topics) if recent_topics else '（已结束的旧话题原文已隐藏；不要主动续提）'
            extra += (
                '\n【自主开启全新话题：最高优先级】\n'
                '这次不是续聊任务。你必须主动发起一个与上面历史记录中已讨论主题在内容上明显无关的新话题；即使旧话题还可以继续，也不要接回去。\n'
                '以下只是近 24 小时已经聊过、需要避开的主题，不是让你回答或延续的提示：\n%s\n'
                '本次随机灵感方向：%s。把它当成你此刻偶然想到的一件小事，而不是话题模板；从具体细节、真实偏好或随口一念自然开口。不要向群友讲述自己正在换题或开启话题，也不要把开场写成主持串场；可以只分享一个小发现，不一定要提问。\n'
                '你的长期记忆只用于保持个性和避开重复，不代表必须拿旧经历当话题。选一个全新的切口；如果当下实在没有想分享的内容，只输出 [PASS]。\n'
                '自主开场也要像给网友发消息：可以分享自己这边的小事、突然想到的东西或个人兴趣。只有群聊设定、记忆或先前对话已经确立过与另一只桌宠的共同经历时，才可以自然提起；不要为开场临时捏造过去见面。偶尔可以在关系合适时表达将来想找某位桌宠见面的念头，但不要把单方面想法写成已约好，更不能邀请用户线下到场。不要动不动组织全员活动；多数自主开场仍然是各自生活里的小事和普通远程聊天。\n'
            ) % (excluded, chosen_category)
        elif mode == 'followup':
            extra += ('\n【接话规则】先回应眼前这条消息里真正吸引你的部分，不用每次都回应整段话，也不必句句都提出新问题。若没兴趣，可以只对一个细节有反应，或直接 [PASS]。是否继续是你心里的决定，不要用旁白解释自己的聊天策略；也别为了收尾硬写一句台词。自然停下时，在真实发言末尾附 [END_TOPIC]，除此之外不要提及这个标记。\n')
        elif mode == 'idle':
            extra += (
                '\n【自主开场：本轮允许一次旧话题回忆】\n'
                '本轮已经随机抽中旧话题回忆机会，且该旧话题与本轮之间至少隔着三段已结束的其他对话。可以从提供的那一段历史中自然提起一个具体细节，最多简短一两句；不要完整复述，不要解释为什么想起，也不要强行把话题拉回去。如果眼下有更自然的回应，可以不提。\n'
            )
        elif mode == 'mention':
            extra += '\n【@点名】用户是明确在叫你，请回应用户的内容；不要替其他桌宠代答。\n'
        elif mode == 'all':
            extra += '\n【全员讨论】请只说出这只桌宠自己的观点，不要重复前面成员的观点；无话可补时可以 [PASS]。\n'
        else:
            extra += '\n【自由群聊】自然回应当前用户消息，不机械复述。\n'

        roster = []
        for member in sorted(members, key=lambda p: (str(p.get('name', '')), str(p.get('id', '')))):
            mid = str(member.get('id', '') or '')
            mname = str(member.get('name', '桌宠') or '桌宠')[:24]
            roster.append('- instance_id=%s；显示名=%s；身份=%s' % (mid, mname, '当前发言实例' if mid == current_id else '独立的其他桌宠实例'))
        extra += '\n【身份注册表】\n' + '\n'.join(roster) + '\n每条消息以真实发送者为准，不能把其他桌宠的发言视为自己的历史回复。\n'

        # Recipient intent is decided before composing dialogue. Explicit routing is stored with the root message.
        if mode == 'free' and root_sender_type == 'user' and root_target_ids:
            target_members = [p for p in members if str(p.get('id', '')) in root_target_ids]
            target_names = [str(p.get('name', '桌宠') or '桌宠') for p in target_members]
            if current_id in root_target_ids:
                extra += ('\n【本条消息的收件对象】用户明确点名你（%s）作为收件人。请直接回应，但不要替其他桌宠回答；如果句子里提到的第三个人物只是话题对象，仍按原姓名理解。\n' % name)
            else:
                extra += ('\n【本条消息不是发给你】用户明确点名的收件人是「%s」，当前身份是「%s」，你不在收件人之中。必须只输出 [PASS]，不要抢答、插话，也不要因为消息出现在群聊里就认为用户在问你。\n' %
                           ('、'.join(target_names), name))
        elif mode == 'free' and root_sender_type == 'user':
            extra += (
                '\n【先判断用户在对谁说话】这条用户消息没有明确 @ 或点名收件人，不代表用户默认在叫你。先根据最近的对话判断：若用户是在回答上一只桌宠的问题，优先理解为对那只桌宠说；若用户使用“大家、你们、谁觉得”等群体表达，才是面向群聊；若只是分享近况，也只有当你本人确实有兴趣或能自然补充时才回应。普通的“你呢”“你觉得呢”要结合上一条发言者判断，不能把所有第二人称都当成自己。若明显是在找另一只桌宠或内容与你无关，只输出 [PASS]；不要解释判断过程。\n'
            )
        elif mode == 'followup':
            extra += (
                '\n【这是桌宠之间的接话，不是用户在叫你】当前任务是回应最近发言的另一只桌宠。不要把最初的用户消息当成当前对你发出的提问，也不要假设用户每次都在跟你说话。先判断你是否真想回应那只桌宠；有自然补充才发言，否则只输出 [PASS]。\n'
            )
        elif mode == 'mention':
            extra += '\n【收件对象已确认】群聊界面通过 @点名将任务只分配给你；回应用户即可，不要替其他桌宠代答。\n'
        elif mode == 'all':
            extra += '\n【面向全员】用户选择了全员讨论模式，因此你可以表达自己的看法；仍不必重复其他人或强行凑话。\n'

        if mode == 'idle':
            # Do not feed old transcript to autonomous starters, except for the one old topic
            # explicitly selected by the persisted 5% recall decision.
            if topic_recall_source_v104 == 'random':
                permitted_recall = [str(item.get('text', '') or '').strip() for item in context
                                    if str(item.get('mode', '') or '') == 'topic_recall_v104'
                                    and str(item.get('text', '') or '').strip()]
                transcript = ('【自主开场】现在没有需要回答的上一条消息。其余已结束对话均不提供；'
                              '仅以下被明确允许的单段旧话题可供自然回忆。不要复述整段内容：\n\n' +
                              '\n\n'.join(permitted_recall)) if permitted_recall else (
                                  '【自主开场】现在没有需要回答的上一条消息。没有提供旧话题原文，请自然开启新话题。')
            else:
                transcript = ('【自主开场】现在没有需要回答的上一条消息。不要引用或延续已结束的历史对话；'
                              '只有系统明确提供并授权的那一段旧话题可以作为回忆例外，其余情况请自然开启新话题。')
        else:
            transcript_lines = ['【神典石远程群聊记录】这些消息是成员通过神典石发送的文字。当前群聊通常是远程交流，各人不一定在同一地点。桌宠过去是否见过面，必须以人物设定、所在地与行动条件、记忆和先前消息为准：已建立的见面经历要保持一致；明确说过没见过、关系不合适或没有事实依据的，不能写成过去真实发生的事。未来见面可以作为桌宠之间的提议，只有双方接受后才算约定。用户始终在现实世界的电脑另一端，永远不与桌宠处于同一地点，也绝不能被邀请线下见面或参加到场活动。必须区分每条消息的实际发言者。']
            for item in context:
                kind = str(item.get('sender_type', ''))
                body = str(item.get('text', '') or '').strip()
                if not body:
                    continue
                sender_id = str(item.get('sender_id', '') or '')
                sender_name = str(item.get('sender_name', '') or '')[:24]
                if kind == 'user':
                    label = '人类用户（本人）'
                elif kind == 'pet':
                    label = ('当前桌宠实例 id=%s，显示名=%s' % (sender_id, sender_name)) if sender_id == current_id else ('其他桌宠实例 id=%s，显示名=%s' % (sender_id, sender_name or '桌宠'))
                else:
                    label = '群聊系统提示'
                transcript_lines.append('〔%s〕\n%s' % (label, body[:4500]))
            transcript = '\n\n'.join(transcript_lines)

        if mode == 'mention':
            directive = '当前模式：@点名。请直接回应用户发言。'
        elif mode == 'all':
            directive = '当前模式：全员讨论。只给出当前桌宠的一条观点。'
        elif mode == 'idle':
            if topic_recall_source_v104 == 'random':
                directive = ('当前模式：自主开场。本轮已经抽中一次旧话题回忆机会；若自然合适，可简短提到系统提供的那段历史，'
                             '不要硬凑或详细复述；也可以开启新话题。没有合适内容则只输出 [PASS]。')
            else:
                directive = '当前模式：全新自主开场。不要回应或延续任何已结束的旧话题，选择一个自然的新主题；没有合适内容则只输出 [PASS]。'
        elif mode == 'followup':
            directive = '当前模式：自由群聊接话。接住你真正在意的细节，按当下心情自然回应；可以短答、顺口延伸、稍微岔开，也可以不接话。不要向群友解释聊天策略。想自然停下时只在正常发言后附隐藏的 [END_TOPIC]，没话想说就 [PASS]。'
        else:
            directive = '当前模式：自由群聊。先遵守系统中的收件对象判断，再决定是否回复。用户没有点名你时，不要默认自己就是被问的人；如果是在回应上一只桌宠，应以那只桌宠为对话对象。只回应你真想回应且与自己相关的部分；不合适就只输出 [PASS]。需要结束话题时，可在正常发言末尾加隐藏的 [END_TOPIC]，不要把内部判断说出口。'

        # 群聊中始终以当前角色的第一人称回应，绝不泄露内部收件对象判断。
        extra += (
            '\n【对话视角与穿帮防护】\n'
            '你发出的内容是你本人直接发给群友的聊天消息，不是对程序如何判断的说明。绝不能说“用户问的是她，不是我”“用户不是在问我”“我应该回复谁”等话，也不提系统、提示词、调度、收件对象或发言任务；如果这条话不是对你说的，只输出 [PASS]。\n'
            '群聊接话可以回应上一条消息，也可以自然表达自己的看法、评价对方、开玩笑、补充或顺势岔开话题；只要符合人物关系和上下文即可。正常的第三人称评论不算穿帮，不要把对其他桌宠的自然评价误当成旁白。面对用户用“你”交流时，结合上一条发言者和语境判断指向。内部判断只用于决定说不说，绝不能说出来。\n'
        )
        extra += "\n\n" + topic_policy_v104 + "\n"
        messages = [
            {'role': 'system', 'content': base_prompt + extra},
            {'role': 'user', 'content': transcript + '\n\n【本次发言任务】\n' + directive + '\n直接输出当前桌宠要说的话，不要加发言者姓名前缀。'},
        ]
        payload = json.dumps({'model': api_model, 'messages': messages, 'temperature': 1.0, 'max_tokens': 640, 'stream': False}, ensure_ascii=False).encode('utf-8')
        request = urllib.request.Request(api_url, data=payload, headers={'Content-Type': 'application/json', 'Authorization': 'Bearer ' + api_key}, method='POST')
        with urllib.request.urlopen(request, timeout=40) as response:
            response_data = json.loads(response.read().decode('utf-8'))
        raw_reply = str(response_data['choices'][0]['message']['content'] or '').strip()
        if not raw_reply:
            raise RuntimeError('empty_reply')
    except Exception as exc:
        if isinstance(exc, RuntimeError):
            err = '请检查这只桌宠的 API 配置（Key、接口地址和模型名）。'
        elif isinstance(exc, urllib.error.HTTPError):
            err = 'API 返回 HTTP %s，请检查接口地址、模型权限或额度。' % int(getattr(exc, 'code', 0) or 0)
        elif isinstance(exc, urllib.error.URLError):
            err = '无法连接 API 服务，请检查网络和接口地址。'
        elif isinstance(exc, (json.JSONDecodeError, KeyError, IndexError, TypeError)):
            err = 'API 返回内容格式不符合预期，请检查接口兼容性。'
        else:
            err = '请求没有成功，请检查网络或 API 配置。'
    try:
        result_queue = getattr(app, '_petzhu_groupchat_result_queue_v1', None)
        if result_queue is not None:
            result_queue.put((dict(job), raw_reply, err))
        else:
            conn = _petzhu_groupchat_connect_v1(app)
            try:
                conn.execute("UPDATE gc_jobs SET status='pending',lease_until=0 WHERE id=? AND status='working'", (int(job.get('id', 0) or 0),))
            finally:
                conn.close()
    except Exception:
        pass


_PETZHU_GROUPCHAT_GENERATE_PRE_V81 = _petzhu_groupchat_generate_worker_v1
_petzhu_groupchat_generate_worker_v1 = _petzhu_groupchat_generate_worker_v81


def _petzhu_groupchat_finish_job_v81(app, job, raw_reply, err):
    job0 = dict(job or {})
    original_mode = str(job0.get('mode', 'free') or 'free')
    root_id = int(job0.get('root_id', 0) or 0)
    turn_index = int(job0.get('turn_index', 0) or 0)
    raw = str(raw_reply or '')
    is_pass = raw.strip().upper() == '[PASS]'
    has_end_marker = bool(re.search(r'\[END_TOPIC\]', raw, flags=re.I))
    clean_candidate = re.sub(r'\[MEM[:：].+?\]', '', raw, flags=re.S)
    clean_candidate = re.sub(r'\[END_TOPIC\]', '', clean_candidate, flags=re.I).strip()
    lifecycle_mode = original_mode in ('free', 'followup', 'idle')
    # Normal closure is persona-selected. The fifth pet reply is a hard safety cap, not the default.
    hard_cap = lifecycle_mode and turn_index >= 4 and bool(clean_candidate) and not err
    should_close = lifecycle_mode and not err and (is_pass or has_end_marker or hard_cap)
    if has_end_marker:
        raw = re.sub(r'\[END_TOPIC\]', '', raw, flags=re.I).strip()
    if should_close and not is_pass:
        # Legacy finisher schedules follow-ups only for these mode names. Preserve message content
        # while deliberately preventing the old auto-followup insert.
        job0['mode'] = 'topic_final'
    _PETZHU_GROUPCHAT_FINISH_PRE_V81(app, job0, raw, err)
    if should_close:
        reason = 'pass' if is_pass else ('persona_end' if has_end_marker else 'safety_turn_limit')
        _petzhu_groupchat_close_topic_v81(app, root_id, reason)


_PETZHU_GROUPCHAT_FINISH_PRE_V81 = _petzhu_groupchat_finish_job_v1
_petzhu_groupchat_finish_job_v1 = _petzhu_groupchat_finish_job_v81


# Autonomous starts retain the old quiet-period/cross-process lock, while v81 prompt logic makes
# every new idle root a fresh unrelated topic and excludes topics discussed in the last 24 hours.


# ============================================================
# v83: 过滤模型内部静默标记，并放慢同一桌宠的分句发送节奏
# - [SILENT] 属于控制标记，不得进入气泡、群聊历史或重要记忆；
# - 单独返回 [SILENT] 等价于 [PASS]：不发空消息，结束当前接话链；
# - 同一桌宠后续分句至少间隔 3 秒；其他桌宠仍可独立交错发言。
# ============================================================

def _petzhu_groupchat_strip_silent_marker_v83(value):
    """Return (clean_text, is_silent_only) without leaking the internal [SILENT] marker."""
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n")
    if re.fullmatch(r"\s*(?:\[SILENT\]\s*)+[。.!！?？…]*\s*", text, flags=re.I):
        return "", True
    text = re.sub(r"\[SILENT\]", "", text, flags=re.I)
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    return text, not bool(text)


_PETZHU_GROUPCHAT_FINISH_PRE_V83 = _petzhu_groupchat_finish_job_v1

def _petzhu_groupchat_finish_job_v83(app, job, raw_reply, err):
    """Sanitize internal control tokens before memory extraction, persistence and segmentation."""
    raw = str(raw_reply or "")
    if not err:
        clean_raw, silent_only = _petzhu_groupchat_strip_silent_marker_v83(raw)
        # A marker-only answer is a deliberate no-reply, not visible dialogue.
        if silent_only:
            clean_raw = "[PASS]"
        raw = clean_raw
    return _PETZHU_GROUPCHAT_FINISH_PRE_V83(app, job, raw, err)

_petzhu_groupchat_finish_job_v1 = _petzhu_groupchat_finish_job_v83


def _petzhu_groupchat_render_message_v83(app, win, inner, item, palette):
    """Defensively keep old/legacy [SILENT] rows out of the rendered transcript."""
    try:
        item0 = dict(item or {})
        original = str(item0.get("text", "") or "")
        clean, silent_only = _petzhu_groupchat_strip_silent_marker_v83(original)
        if clean != original:
            item0["text"] = clean
        if silent_only and str(item0.get("sender_type", "")) == "pet":
            # Return a zero-height row so the caller advances its message cursor without
            # showing an empty bubble or repeatedly fetching the same old row.
            row = tk.Frame(inner, height=1, bg=palette.get("bg", "#141824"), bd=0, highlightthickness=0)
            row.pack(fill="x", padx=0, pady=0)
            row.pack_propagate(False)
            row._petzhu_groupchat_message_id_v1 = int(item0.get("id", 0) or 0)
            return row
        return _PETZHU_GROUPCHAT_RENDER_PRE_V83(app, win, inner, item0, palette)
    except Exception:
        return _PETZHU_GROUPCHAT_RENDER_PRE_V83(app, win, inner, item, palette)

_PETZHU_GROUPCHAT_RENDER_PRE_V83 = _petzhu_groupchat_render_message_v1
_petzhu_groupchat_render_message_v1 = _petzhu_groupchat_render_message_v83


def _petzhu_groupchat_init_db_v83(app):
    """One-time cleanup for markers leaked by older builds and old short-delay segment queues."""
    _PETZHU_GROUPCHAT_INIT_PRE_V83(app)
    conn = None
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        _petzhu_groupchat_ensure_segments_table_v79(conn)
        conn.execute("BEGIN IMMEDIATE")

        # Remove the leaked marker from old pet/system messages. If a pet message consisted
        # solely of [SILENT], delete it instead of leaving a blank bubble in history.
        rows = conn.execute(
            "SELECT id,sender_type,text FROM gc_messages WHERE instr(upper(text),'[SILENT]')>0"
        ).fetchall()
        for row in rows:
            sender_type = str(row["sender_type"] or "")
            text0 = str(row["text"] or "")
            clean, silent_only = _petzhu_groupchat_strip_silent_marker_v83(text0)
            if sender_type in ("pet", "system") and silent_only:
                conn.execute("DELETE FROM gc_messages WHERE id=?", (int(row["id"]),))
            else:
                conn.execute("UPDATE gc_messages SET text=? WHERE id=?", (clean, int(row["id"])))

        # Clean queued legacy fragments too, so a pending segment cannot leak the marker later.
        pending = conn.execute(
            "SELECT id,text FROM gc_pending_segments WHERE instr(upper(text),'[SILENT]')>0"
        ).fetchall()
        for row in pending:
            clean, silent_only = _petzhu_groupchat_strip_silent_marker_v83(str(row["text"] or ""))
            if silent_only:
                conn.execute("DELETE FROM gc_pending_segments WHERE id=?", (int(row["id"]),))
            else:
                conn.execute("UPDATE gc_pending_segments SET text=? WHERE id=?", (clean, int(row["id"])))

        # Re-time legacy pending fragments once after upgrading; keep each fragment at least
        # three seconds apart even if they were queued by the previous 0.62-1.08s implementation.
        migrated = _petzhu_groupchat_meta_get_v1(conn, "v83_segment_delay_migrated", "")
        if migrated != "1":
            now = time.time()
            groups = conn.execute(
                "SELECT DISTINCT participant_id,job_id FROM gc_pending_segments ORDER BY participant_id,job_id"
            ).fetchall()
            for group in groups:
                rows2 = conn.execute(
                    "SELECT id,segment_index,due_at FROM gc_pending_segments "
                    "WHERE participant_id=? AND job_id=? ORDER BY segment_index,id",
                    (str(group["participant_id"]), int(group["job_id"]))
                ).fetchall()
                due_at = now + 3.0
                for row in rows2:
                    due_at = max(float(row["due_at"] or 0), due_at)
                    conn.execute("UPDATE gc_pending_segments SET due_at=? WHERE id=?",
                                 (due_at, int(row["id"])))
                    due_at += 3.0
            _petzhu_groupchat_meta_set_v1(conn, "v83_segment_delay_migrated", "1")
        conn.commit()
    except Exception:
        try:
            if conn is not None:
                conn.rollback()
        except Exception:
            pass
    finally:
        if conn is not None:
            conn.close()

_PETZHU_GROUPCHAT_INIT_PRE_V83 = _petzhu_groupchat_init_db_v1
_petzhu_groupchat_init_db_v1 = _petzhu_groupchat_init_db_v83




# ============================================================
# v84: robustly hide END_TOPIC control tokens + group-chat font size selector
# - Accept both [END_TOPIC] and <END_TOPIC> (including HTML-escaped forms), since models may
#   return either spelling despite the prompt's preferred square-bracket form.
# - Strip markers before persistence, segmentation, memories, and UI rendering; migrate old rows.
# - Add Small/Medium/Large/Extra-large control and scale existing/new group-chat text widgets.
# ============================================================

_PETZHU_GROUPCHAT_END_TOPIC_RE_V84 = re.compile(
    r"(?:\[\s*END[ _-]*TOPIC\s*\]|<\s*END[ _-]*TOPIC\s*>|"
    r"&lt;\s*END[ _-]*TOPIC\s*&gt;|【\s*END[ _-]*TOPIC\s*】)",
    flags=re.IGNORECASE,
)
_PETZHU_GROUPCHAT_FONT_SCALE_V84 = {"小": 0.86, "中": 1.00, "大": 1.20, "特大": 1.40}
_PETZHU_GROUPCHAT_FONT_CHOICES_V84 = ("小", "中", "大", "特大")


def _petzhu_groupchat_strip_end_topic_v84(value):
    """Return (cleaned text, marker-found), regardless of bracket style emitted by an API."""
    text = str(value or "").replace("\r\n", "\n").replace("\r", "\n")
    found = bool(_PETZHU_GROUPCHAT_END_TOPIC_RE_V84.search(text))
    if not found:
        return text, False
    text = _PETZHU_GROUPCHAT_END_TOPIC_RE_V84.sub("", text)
    text = re.sub(r"[ \t]{2,}", " ", text)
    text = re.sub(r" *\n *", "\n", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip(), True


def _petzhu_groupchat_get_font_choice_v84(app=None):
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        try:
            value = str(_petzhu_groupchat_meta_get_v1(conn, "groupchat_font_size_v84", "中") or "中")
            return value if value in _PETZHU_GROUPCHAT_FONT_SCALE_V84 else "中"
        finally:
            conn.close()
    except Exception:
        return "中"


def _petzhu_groupchat_font_widgets_v84(root):
    """Walk normal child widgets and reachable OptionMenu/Menu objects without duplicates."""
    stack = [root]
    found = []
    seen = set()
    while stack:
        widget = stack.pop()
        if widget is None or id(widget) in seen:
            continue
        seen.add(id(widget))
        found.append(widget)
        try:
            stack.extend(widget.winfo_children())
        except Exception:
            pass
        try:
            if isinstance(widget, (tk.OptionMenu, tk.Menubutton)):
                menu_name = widget.cget("menu")
                if menu_name:
                    stack.append(widget.nametowidget(menu_name))
        except Exception:
            pass
    return found


def _petzhu_groupchat_apply_font_size_v84(win, app=None, choice=None, include_tree=True, root_widget=None):
    """Scale fonts from each widget's original size, never cumulatively and without rebuilding widgets."""
    if choice not in _PETZHU_GROUPCHAT_FONT_SCALE_V84:
        choice = str(choice or getattr(win, "_petzhu_groupchat_font_choice_v84", "中") or "中")
    if choice not in _PETZHU_GROUPCHAT_FONT_SCALE_V84:
        choice = "中"
    try:
        factor = float(_PETZHU_GROUPCHAT_FONT_SCALE_V84[choice])
        scan_root = root_widget if root_widget is not None else (win if include_tree else None)
        if scan_root is None:
            return
        for widget in _petzhu_groupchat_font_widgets_v84(scan_root):
            try:
                current_spec = widget.cget("font")
            except Exception:
                continue
            if not current_spec:
                continue
            base = getattr(widget, "_petzhu_groupchat_font_base_v84", None)
            font_obj = getattr(widget, "_petzhu_groupchat_font_obj_v84", None)
            if not isinstance(base, dict) or font_obj is None:
                try:
                    source_font = tkfont.Font(root=win, font=current_spec)
                    actual = source_font.actual()
                    size = int(actual.get("size", 9) or 9)
                    if size == 0:
                        size = 9
                    base = {
                        "family": str(actual.get("family", "微软雅黑") or "微软雅黑"),
                        "size": size,
                        "weight": str(actual.get("weight", "normal") or "normal"),
                        "slant": str(actual.get("slant", "roman") or "roman"),
                        "underline": bool(actual.get("underline", 0)),
                        "overstrike": bool(actual.get("overstrike", 0)),
                    }
                    font_obj = tkfont.Font(
                        root=win, family=base["family"], size=base["size"],
                        weight=base["weight"], slant=base["slant"],
                        underline=base["underline"], overstrike=base["overstrike"],
                    )
                    widget._petzhu_groupchat_font_base_v84 = base
                    widget._petzhu_groupchat_font_obj_v84 = font_obj
                    widget.configure(font=font_obj)
                except Exception:
                    continue
            try:
                base_size = int(base.get("size", 9) or 9)
                sign = -1 if base_size < 0 else 1
                scaled_size = max(6, int(round(abs(base_size) * factor))) * sign
                font_obj.configure(size=scaled_size)
            except Exception:
                pass
        try:
            win._petzhu_groupchat_font_choice_v84 = choice
            win._petzhu_groupchat_font_choice_applied_v84 = choice
        except Exception:
            pass
    except Exception:
        pass


def _petzhu_groupchat_set_font_choice_v84(app, win, choice, variable=None):
    choice = str(choice or "中")
    if choice not in _PETZHU_GROUPCHAT_FONT_SCALE_V84:
        choice = "中"
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        try:
            _petzhu_groupchat_meta_set_v1(conn, "groupchat_font_size_v84", choice)
            conn.commit()
        finally:
            conn.close()
    except Exception:
        pass
    try:
        if variable is not None and variable.get() != choice:
            variable.set(choice)
    except Exception:
        pass
    _petzhu_groupchat_apply_font_size_v84(win, app, choice, include_tree=True)


def _petzhu_groupchat_open_v84(app):
    result = _PETZHU_GROUPCHAT_OPEN_PRE_V84(app)
    win = getattr(app, "_petzhu_groupchat_win_v1", None)
    try:
        if win is None or not win.winfo_exists():
            return result
        refs = getattr(win, "_petzhu_groupchat_refs_v1", {}) or {}
        container = refs.get("font_container_v84")
        if container is None or not container.winfo_exists():
            # Compatibility for a window instance built by an earlier branch before this patch.
            children = list(win.winfo_children())
            outer = children[0] if children else None
            outer_children = list(outer.winfo_children()) if outer is not None else []
            header = outer_children[0] if outer_children else None
            if header is not None and header.winfo_exists():
                palette = _petzhu_groupchat_palette_v1(app)
                container = tk.Frame(header, bg=palette["bg"])
                _petzhu_groupchat_set_role_v1(container, "bg")
                container.pack(side="right", padx=(8, 0))
                label = tk.Label(container, text="字号", bg=palette["bg"], fg=palette["muted"], font=("微软雅黑", 9))
                _petzhu_groupchat_set_role_v1(label, "muted")
                label.pack(side="left", padx=(0, 4))
                variable = tk.StringVar(master=win, value=_petzhu_groupchat_get_font_choice_v84(app))
                menu = tk.OptionMenu(container, variable, *list(_PETZHU_GROUPCHAT_FONT_CHOICES_V84),
                                     command=lambda value, a=app, w=win, v=variable: _petzhu_groupchat_set_font_choice_v84(a, w, value, v))
                _petzhu_groupchat_set_role_v1(menu, "surface2")
                menu.configure(font=("微软雅黑", 9), padx=4, pady=2, bd=0, relief="flat", highlightthickness=0,
                               bg=palette["surface2"], fg=palette["fg"], activebackground=palette["accent"],
                               activeforeground=palette["accent_text"])
                try:
                    menu["menu"].configure(bg=palette["surface2"], fg=palette["fg"],
                                           activebackground=palette["accent"], activeforeground=palette["accent_text"])
                except Exception:
                    pass
                menu.pack(side="left")
                refs["font_container_v84"] = container
                refs["font_size_var_v84"] = variable
                refs["font_size_menu_v84"] = menu
                win._petzhu_groupchat_refs_v1 = refs
        variable = refs.get("font_size_var_v84")
        choice = _petzhu_groupchat_get_font_choice_v84(app)
        if variable is not None:
            try: variable.set(choice)
            except Exception: pass
        win._petzhu_groupchat_font_choice_v84 = choice
        _petzhu_groupchat_apply_font_size_v84(win, app, choice, include_tree=True)
        try:
            palette = _petzhu_groupchat_palette_v1(app)
            _petzhu_groupchat_apply_palette_v1(win, palette)
        except Exception:
            pass
    except Exception:
        pass
    return result


_PETZHU_GROUPCHAT_OPEN_PRE_V84 = _petzhu_groupchat_open_v1
_petzhu_groupchat_open_v1 = _petzhu_groupchat_open_v84


