def _petzhu_groupchat_finish_job_v84(app, job, raw_reply, err):
    raw = str(raw_reply or "")
    if not err:
        clean, found = _petzhu_groupchat_strip_end_topic_v84(raw)
        if found:
            # v81 already understands [END_TOPIC]. Normalize angle-bracket variants to its
            # canonical token so the existing topic lifecycle runs, then v81 removes the token
            # before memory extraction, persistence, and sentence segmentation.
            raw = _PETZHU_GROUPCHAT_END_TOPIC_RE_V84.sub("[END_TOPIC]", raw)
        else:
            raw = clean
    return _PETZHU_GROUPCHAT_FINISH_PRE_V84(app, job, raw, err)

