def _petzhu_groupchat_init_db_v84(app):
    _PETZHU_GROUPCHAT_INIT_PRE_V84(app)
    conn = None
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        conn.execute("BEGIN IMMEDIATE")
        # Migrate leaked [END_TOPIC], <END_TOPIC>, or HTML-escaped forms from old message rows.
        rows = conn.execute("SELECT id,sender_type,text FROM gc_messages WHERE instr(upper(text),'END_TOPIC')>0").fetchall()
        for row in rows:
            clean, found = _petzhu_groupchat_strip_end_topic_v84(str(row["text"] or ""))
            if not found:
                continue
            if not clean and str(row["sender_type"] or "") in ("pet", "system"):
                conn.execute("DELETE FROM gc_messages WHERE id=?", (int(row["id"]),))
            else:
                conn.execute("UPDATE gc_messages SET text=? WHERE id=?", (clean, int(row["id"])))

        # Remove marker-only queued bubbles; sanitize any other queued fragment before delivery.
        _petzhu_groupchat_ensure_segments_table_v79(conn)
        pending = conn.execute("SELECT id,text FROM gc_pending_segments WHERE instr(upper(text),'END_TOPIC')>0").fetchall()
        for row in pending:
            clean, found = _petzhu_groupchat_strip_end_topic_v84(str(row["text"] or ""))
            if not found:
                continue
            if not clean:
                conn.execute("DELETE FROM gc_pending_segments WHERE id=?", (int(row["id"]),))
            else:
                conn.execute("UPDATE gc_pending_segments SET text=? WHERE id=?", (clean, int(row["id"])))

        # Older leaked markers can also exist in auto-collected group-chat memories.
        memory_rows = conn.execute("SELECT rowid,memory FROM gc_memories WHERE instr(upper(memory),'END_TOPIC')>0").fetchall()
        for row in memory_rows:
            clean, found = _petzhu_groupchat_strip_end_topic_v84(str(row["memory"] or ""))
            if found:
                if clean:
                    conn.execute("UPDATE gc_memories SET memory=? WHERE rowid=?", (clean, int(row["rowid"])))
                else:
                    conn.execute("DELETE FROM gc_memories WHERE rowid=?", (int(row["rowid"]),))
        conn.commit()
    except Exception:
        try:
            if conn is not None:
                conn.rollback()
        except Exception:
            pass
    finally:
        if conn is not None:
            conn.close()

    # Sanitize already-synced personal chat history too; only the control token is removed.
    changed = False
    try:
        history_log = list(getattr(app, "history_log", []) or [])
        cleaned_log = []
        for rec in history_log:
            if not isinstance(rec, dict):
                cleaned_log.append(rec)
                continue
            rec0 = dict(rec)
            for key in ("text", "content", "message"):
                if key in rec0:
                    value, found = _petzhu_groupchat_strip_end_topic_v84(rec0.get(key, ""))
                    if found:
                        rec0[key] = value
                        changed = True
            if rec0.get("source") == "petzhu_groupchat" and not str(rec0.get("text", rec0.get("content", "")) or "").strip():
                changed = True
                continue
            cleaned_log.append(rec0)
        if changed:
            app.history_log = cleaned_log[-500:]
            try: _petzhu_groupchat_persist_history_log_v80(app)
            except Exception:
                try: app._save_history()
                except Exception: pass
            try: app._refresh_open_conversation_history()
            except Exception: pass
        ctx = list(getattr(app, "history", []) or [])
        ctx_changed = False
        ctx_out = []
        for entry in ctx:
            if isinstance(entry, (tuple, list)) and len(entry) >= 2:
                role, content = entry[0], str(entry[1] or "")
                clean, found = _petzhu_groupchat_strip_end_topic_v84(content)
                if found:
                    ctx_changed = True
                    content = clean
                ctx_out.append((role, content))
            else:
                ctx_out.append(entry)
        if ctx_changed:
            app.history = ctx_out[-24:]
    except Exception:
        pass

