def _petzhu_groupchat_send_user_v96(app, text, mode="free", target_id=""):
    """Any explicit @mention takes recipient-routing precedence over an old mode selection."""
    raw = str(text or "").strip()
    try:
        targets = _petzhu_groupchat_resolve_explicit_targets_v95(raw, _petzhu_groupchat_get_members_v1(app, api_only=True))
    except Exception:
        targets = []
    if targets:
        mode = "free"
        target_id = ""
    pending = getattr(app, "_petzhu_groupchat_pending_reply_context_v96", None)
    before_id = 0
    if isinstance(pending, dict):
        conn0 = None
        try:
            conn0 = _petzhu_groupchat_connect_v1(app)
            before_id = int(conn0.execute("SELECT COALESCE(MAX(id),0) FROM gc_messages").fetchone()[0] or 0)
        except Exception:
            before_id = 0
        finally:
            if conn0 is not None:
                try: conn0.close()
                except Exception: pass
    result = _PETZHU_GROUPCHAT_SEND_PRE_V96(app, raw, mode=mode, target_id=target_id)
    if not (isinstance(pending, dict) and result and bool(result[0])):
        return result
    conn = None
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        conn.execute("""CREATE TABLE IF NOT EXISTS gc_reply_context_v96 (
            message_id INTEGER PRIMARY KEY, reply_to_id INTEGER NOT NULL,
            reply_sender_id TEXT NOT NULL, reply_sender_name TEXT NOT NULL,
            reply_text TEXT NOT NULL, created_at REAL NOT NULL)""")
        row = conn.execute(
            "SELECT id FROM gc_messages WHERE id>? AND sender_type='user' AND sender_id='human' AND text=? ORDER BY id DESC LIMIT 1",
            (int(before_id), raw[:4000])).fetchone()
        if row is not None:
            conn.execute("INSERT OR REPLACE INTO gc_reply_context_v96(message_id,reply_to_id,reply_sender_id,reply_sender_name,reply_text,created_at) VALUES(?,?,?,?,?,?)",
                         (int(row[0]), int(pending.get("reply_to_id", 0) or 0), str(pending.get("sender_id", "") or ""),
                          str(pending.get("sender_name", "桌宠") or "桌宠"), str(pending.get("text", "") or "")[:4000], time.time()))
            conn.commit()
        try: delattr(app, "_petzhu_groupchat_pending_reply_context_v96")
        except Exception: app._petzhu_groupchat_pending_reply_context_v96 = None
        win = getattr(app, "_petzhu_groupchat_win_v1", None)
        if win is not None and win.winfo_exists():
            win._petzhu_groupchat_reply_context_v96 = None
    except Exception:
        # Visible @ routing remains functional if quote metadata cannot be persisted.
        pass
    finally:
        if conn is not None:
            try: conn.close()
            except Exception: pass
    return result


def _petzhu_groupchat_recent_context_v96(app, root_id, limit=22):
    messages, memories = _PETZHU_GROUPCHAT_RECENT_CONTEXT_PRE_V96(app, root_id, limit)
    conn = None
    try:
        conn = _petzhu_groupchat_connect_v1(app)
        row = conn.execute("SELECT reply_to_id,reply_sender_id,reply_sender_name,reply_text FROM gc_reply_context_v96 WHERE message_id=?",
                           (int(root_id),)).fetchone()
        if row is None:
            return messages, memories
        quoted_id, quoted_sender_id, quoted_name, quoted_text = row
        synthetic = {
            "id": int(root_id) - 0.25, "created_at": time.time(),
            "sender_id": "reply_reference", "sender_type": "system", "sender_name": "回复引用",
            "text": "当前用户使用右键回复了桌宠「%s」的指定消息（原消息 id=%s）：\n%s\n请把这条引用视为本次回复的直接上下文，回应用户新发的消息，不要机械复述原文。" % (
                str(quoted_name or "桌宠")[:48], int(quoted_id or 0), str(quoted_text or "")[:4000]),
            "mode": "reply_reference",
        }
        output, inserted = [], False
        for message in list(messages or []):
            if not inserted and int(message.get("id", 0) or 0) == int(root_id):
                output.append(synthetic)
                inserted = True
            output.append(message)
        if not inserted:
            output.insert(0, synthetic)
        return output[-(int(limit) + 1):], memories
    except Exception:
        return messages, memories
    finally:
        if conn is not None:
            try: conn.close()
            except Exception: pass


def _petzhu_groupchat_open_v96(app):
    result = _PETZHU_GROUPCHAT_OPEN_PRE_V96(app)
    try:
        win = getattr(app, "_petzhu_groupchat_win_v1", None)
        if win is None or not win.winfo_exists():
            return result
        refs = getattr(win, "_petzhu_groupchat_refs_v1", {}) or {}
        box = refs.get("input")
        mode_var = refs.get("mode_var")
        target_menu = refs.get("target_menu")
        # QQ-style @ is now inline in the composer; remove the old explicit @mode button
        # and separate target dropdown, while retaining free chat and all-discussion modes.
        try:
            mode_row = next((w for w in _petzhu_groupchat_walk_widgets_v1(win)
                             if isinstance(w, tk.Frame) and any(
                                 isinstance(c, tk.Button) and str(c.cget("text")) == "自由群聊"
                                 for c in w.winfo_children())), None)
            if mode_row is not None:
                for child in list(mode_row.winfo_children()):
                    if isinstance(child, tk.Button):
                        # The actual original label contains a space: "@ 点名".
                        # Normalize whitespace so every legacy @-mode variant is hidden.
                        label_key = re.sub(r"\s+", "", str(child.cget("text")))
                        if label_key in ("@点名", "@点名模式"):
                            child.pack_forget()
        except Exception:
            pass
        if target_menu is not None:
            try: target_menu.pack_forget()
            except Exception: pass
        if mode_var is not None and str(mode_var.get()) == "mention":
            try: mode_var.set("free")
            except Exception: pass
        # Keep the old type-to-open chooser, and add an explicit @ button beside Send.
        # Selecting a member after pressing the button replaces only the inserted @ token
        # at the current Text insertion mark, so it also works in the middle of a message.
        try:
            for widget in _petzhu_groupchat_walk_widgets_v1(win):
                if isinstance(widget, tk.Label) and "Shift+Enter" in str(widget.cget("text")):
                    widget.configure(text="点击 @成员 插入点名 · 也可直接输入 @ · 右键消息可回复")
        except Exception:
            pass
        try:
            existing_at_button = getattr(win, "_petzhu_groupchat_at_button_v97", None)
            if existing_at_button is None or not existing_at_button.winfo_exists():
                send_button = next((w for w in _petzhu_groupchat_walk_widgets_v1(win)
                                    if isinstance(w, tk.Button) and str(w.cget("text")).startswith("发送")), None)
                compose_row = getattr(send_button, "master", None) if send_button is not None else None
                if box is not None and box.winfo_exists() and compose_row is not None and compose_row.winfo_exists():
                    palette = _petzhu_groupchat_palette_v1(app)
                    def insert_at_and_open_picker(a=app, w=win, input_box=box):
                        try:
                            if not input_box.winfo_exists():
                                return
                            popup = getattr(w, "_petzhu_groupchat_at_popup_v96", None)
                            if popup is not None and popup.winfo_exists():
                                _petzhu_groupchat_at_popup_update_v96(a, w)
                                popup.lift()
                                return
                            # Text keeps its insertion mark when the button receives focus.
                            cursor = input_box.index("insert")
                            input_box.insert(cursor, "@")
                            input_box.mark_set("insert", "%s + 1 chars" % cursor)
                            input_box.focus_set()
                            _petzhu_groupchat_at_popup_update_v96(a, w)
                        except Exception:
                            pass
                    at_button = tk.Button(
                        compose_row, text="@ 成员", command=insert_at_and_open_picker,
                        bg=palette.get("surface2", palette.get("surface", "#eeeeee")),
                        fg=palette.get("fg", "#222222"),
                        activebackground=palette.get("accent", "#d96fa8"),
                        activeforeground=palette.get("accent_text", "#ffffff"),
                        font=("微软雅黑", 9, "bold"), padx=13, pady=7,
                        bd=0, relief="flat", cursor="hand2", takefocus=True,
                    )
                    _petzhu_groupchat_set_role_v1(at_button, "surface2")
                    at_button.pack(side="right", padx=(0, 8), before=send_button)
                    win._petzhu_groupchat_at_button_v97 = at_button
        except Exception:
            pass
        if box is not None and box.winfo_exists() and not bool(getattr(win, "_petzhu_groupchat_at_bindings_v96", False)):
            def refresh_popup(_event=None):
                _petzhu_groupchat_at_popup_update_v96(app, win)
            def keypress(event):
                popup = getattr(win, "_petzhu_groupchat_at_popup_v96", None)
                if popup is None or not popup.winfo_exists():
                    return None
                key = str(getattr(event, "keysym", "") or "")
                if key == "Up":
                    _petzhu_groupchat_at_popup_move_v96(win, -1); return "break"
                if key == "Down":
                    _petzhu_groupchat_at_popup_move_v96(win, 1); return "break"
                if key in ("Return", "KP_Enter"):
                    return _petzhu_groupchat_at_popup_choose_v96(app, win)
                if key == "Escape":
                    _petzhu_groupchat_at_popup_close_v96(win); return "break"
                return None
            def return_handler(event):
                popup = getattr(win, "_petzhu_groupchat_at_popup_v96", None)
                if popup is not None and popup.winfo_exists():
                    return _petzhu_groupchat_at_popup_choose_v96(app, win)
                if int(getattr(event, "state", 0) or 0) & 0x0001:
                    return None  # Shift+Enter keeps native multiline behavior.
                try:
                    send_button = next((w for w in _petzhu_groupchat_walk_widgets_v1(win)
                                        if isinstance(w, tk.Button) and str(w.cget("text")).startswith("发送")), None)
                    if send_button is not None:
                        send_button.invoke()
                except Exception:
                    pass
                return "break"
            box.bind("<KeyRelease>", refresh_popup, add="+")
            box.bind("<ButtonRelease-1>", refresh_popup, add="+")
            box.bind("<KeyPress>", keypress, add="+")
            box.bind("<Return>", return_handler)
            box.bind("<Control-Return>", lambda _e, w=win: (next((b.invoke() for b in _petzhu_groupchat_walk_widgets_v1(w)
                               if isinstance(b, tk.Button) and str(b.cget("text")).startswith("发送")), None), "break")[1])
            def close_popup_if_focus_left():
                popup = getattr(win, "_petzhu_groupchat_at_popup_v96", None)
                if popup is None or not popup.winfo_exists():
                    return
                try:
                    focused = win.focus_get()
                    if focused is not None:
                        path = str(focused)
                        popup_path = str(popup)
                        if path == popup_path or path.startswith(popup_path + "."):
                            return  # Keep the chooser open while the user clicks an item.
                except Exception:
                    pass
                _petzhu_groupchat_at_popup_close_v96(win)
            box.bind("<FocusOut>", lambda _e, w=win: w.after(180, close_popup_if_focus_left), add="+")
            win._petzhu_groupchat_at_bindings_v96 = True
        return result
    except Exception:
        return result


