_petzhu_groupchat_at_popup_update_v96 = _petzhu_groupchat_at_popup_update_v98


def _petzhu_groupchat_insert_mention_v98(app, win, member_id, member_name, trigger_start=None, trigger_end=None):
    """Replace the typed @ token and reliably leave the text caret ready for continued typing."""
    refs = getattr(win, "_petzhu_groupchat_refs_v1", {}) or {}
    box = refs.get("input")
    if box is None:
        return False
    try:
        if not box.winfo_exists():
            return False
        name = str(member_name or "").strip()[:48]
        member_id = str(member_id or "").strip()
        if not name or not member_id:
            return False

        # Snapshot insertion and replacement bounds before destroying/refocusing the popup.
        cursor = box.index(trigger_end or "insert")
        start = box.index(trigger_start) if trigger_start else cursor
        before = box.get("1.0", start)
        after = box.get(cursor, "end-1c")

        try:
            if box.tag_ranges("sel"):
                # Only clear a selected range if it lies inside the mention replacement span;
                # selecting from the popup must not delete unrelated composer text.
                box.tag_remove("sel", "1.0", "end")
        except Exception:
            pass

        insert_text = "@" + name
        # Add a space after the mention unless a separating whitespace already exists.
        if not after or not after[:1].isspace():
            insert_text += " "
        # Separate the mention from a preceding word, but avoid spaces after punctuation.
        if before and not before[-1:].isspace():
            prev = before[-1:]
            no_prefix_space_after = "，。！？；：、…·—）)]}》」』”’\"'"
            no_prefix_space_before = "（([{《「『“‘"
            if prev not in no_prefix_space_after and prev not in no_prefix_space_before:
                insert_text = " " + insert_text

        if trigger_start:
            box.delete(start, cursor)
        box.insert(start, insert_text)
        caret = "%s + %d chars" % (start, len(insert_text))
        box.mark_set("insert", caret)
        box.tag_remove("sel", "1.0", "end")
        box.see("insert")

        # Popdown click may transiently steal focus on Windows. Restore once Tk finishes
        # processing the listbox ButtonRelease and again shortly after its Toplevel is gone.
        def restore_input_focus():
            try:
                if box.winfo_exists():
                    box.mark_set("insert", caret)
                    box.focus_force()
                    box.see("insert")
            except Exception:
                pass
        try:
            box.focus_set()
            box.after_idle(restore_input_focus)
            box.after(45, restore_input_focus)
        except Exception:
            restore_input_focus()
        return True
    except Exception:
        return False


_petzhu_groupchat_insert_mention_v96 = _petzhu_groupchat_insert_mention_v98


def _petzhu_groupchat_at_popup_choose_v98(app, win, selected_index=None):
    try:
        candidates = list(getattr(win, "_petzhu_groupchat_at_candidates_v96", []) or [])
        refs = getattr(win, "_petzhu_groupchat_refs_v1", {}) or {}
        box = refs.get("input")
        listbox = getattr(win, "_petzhu_groupchat_at_popup_list_v96", None)
        if not candidates or box is None or not box.winfo_exists():
            _petzhu_groupchat_at_popup_close_v96(win)
            return "break"
        index = selected_index
        if index is None:
            selection = listbox.curselection() if listbox is not None and listbox.winfo_exists() else ()
            index = int(selection[0]) if selection else 0
        index = max(0, min(int(index), len(candidates) - 1))
        member = candidates[index]
        trigger = getattr(win, "_petzhu_groupchat_at_trigger_v96", None)
        # Save the Tk Text insertion mark before destroying the transient window.
        cursor = box.index("insert")
        _petzhu_groupchat_at_popup_close_v96(win)
        _petzhu_groupchat_insert_mention_v98(
            app, win, member.get("id", ""), member.get("name", ""),
            trigger_start=trigger, trigger_end=cursor,
        )
        return "break"
    except Exception:
        _petzhu_groupchat_at_popup_close_v96(win)
        try:
            box = (getattr(win, "_petzhu_groupchat_refs_v1", {}) or {}).get("input")
            if box is not None and box.winfo_exists():
                box.after_idle(box.focus_force)
        except Exception:
            pass
        return "break"


_petzhu_groupchat_at_popup_choose_v96 = _petzhu_groupchat_at_popup_choose_v98



