def _petzhu_groupchat_scale_at_button_v99(win, choice=None):
    try:
        if win is None or not win.winfo_exists():
            return
        button = getattr(win, "_petzhu_groupchat_at_button_v97", None)
        if button is None or not button.winfo_exists():
            return
        choice = str(choice or getattr(win, "_petzhu_groupchat_font_choice_v84", "中") or "中")
        scale_map = globals().get("_PETZHU_GROUPCHAT_FONT_SCALE_V86", {"小": 0.86, "中": 1.0, "大": 1.2, "特大": 1.4})
        factor = float(scale_map.get(choice, 1.0))
        scaled = max(7, int(round(9 * factor)))
        font_obj = getattr(button, "_petzhu_groupchat_at_button_font_v99", None)
        if font_obj is None:
            font_obj = tkfont.Font(root=win, family="微软雅黑", size=scaled, weight="bold")
            button._petzhu_groupchat_at_button_font_v99 = font_obj
            # Exclude this button from the generic tree scaler; the explicit helper owns it.
            button._petzhu_groupchat_keep_font_size_v86 = True
            button.configure(font=font_obj)
        elif int(font_obj.cget("size")) != scaled:
            font_obj.configure(size=scaled)
        # Store the actual selected size for diagnostics and future popup layout.
        button._petzhu_groupchat_applied_size_v99 = scaled
    except Exception:
        pass


def _petzhu_groupchat_apply_font_size_v99(win, app=None, choice=None, include_tree=True, root_widget=None):
    selected = str(choice or getattr(win, "_petzhu_groupchat_font_choice_v84", "中") or "中")
    _PETZHU_GROUPCHAT_APPLY_FONT_PRE_V99(win, app, selected, include_tree, root_widget)
    _petzhu_groupchat_scale_at_button_v99(win, selected)


