# ============================================================
# v100: Stable scroll-follow state for the group chat.
# - A single upward wheel tick immediately exits follow-latest mode.
# - New messages never pull a user out of history view.
# - Follow-latest resumes only when the user actually reaches the bottom.
# - Scrollbar thumb clicks/drags share the same state machine.
# ============================================================

_PETZHU_GROUPCHAT_WHEEL_HANDLER_PRE_V100 = _petzhu_groupchat_wheel_handler_v93
_PETZHU_GROUPCHAT_OPEN_PRE_V100 = _petzhu_groupchat_open_v1


def _petzhu_groupchat_at_bottom_v100(canvas):
    """Use a strict bottom test; 0.985 is too permissive for long message histories."""
    try:
        if canvas is None or not canvas.winfo_exists():
            return False
        yview = tuple(float(x) for x in canvas.yview())
        if len(yview) < 2:
            return False
        if yview[0] <= 0.0005 and yview[1] >= 0.9995:
            return True  # Content fits entirely; there is nowhere to scroll.
        return yview[1] >= 0.9995
    except Exception:
        return False


def _petzhu_groupchat_set_follow_latest_v100(win, enabled):
    try:
        if win is None or not win.winfo_exists():
            return
        win._petzhu_groupchat_follow_latest_v100 = bool(enabled)
        if not enabled:
            # Cancel a pending font/layout reflow that was captured while at the bottom.
            win._petzhu_groupchat_reflow_preserve_bottom_v86 = False
    except Exception:
        pass


def _petzhu_groupchat_wheel_handler_v100(event, win, canvas):
    """Track intentional scrolling before the periodic message refresh can run."""
    try:
        number = getattr(event, "num", None)
        if number == 4:
            direction = -1
        elif number == 5:
            direction = 1
        else:
            delta = int(getattr(event, "delta", 0) or 0)
            direction = -1 if delta > 0 else (1 if delta < 0 else 0)
        if direction < 0:
            _petzhu_groupchat_set_follow_latest_v100(win, False)
        result = _PETZHU_GROUPCHAT_WHEEL_HANDLER_PRE_V100(event, win, canvas)
        if direction > 0 and _petzhu_groupchat_at_bottom_v100(canvas):
            _petzhu_groupchat_set_follow_latest_v100(win, True)
        return result
    except Exception:
        try:
            return _PETZHU_GROUPCHAT_WHEEL_HANDLER_PRE_V100(event, win, canvas)
        except Exception:
            return "break"


_petzhu_groupchat_wheel_handler_v93 = _petzhu_groupchat_wheel_handler_v100


def _petzhu_groupchat_bind_scrollbar_follow_v100(win, canvas, scrollbar):
    """Wrap the native scrollbar command without replacing the native scrollbar widget."""
    if scrollbar is None or not scrollbar.winfo_exists() or getattr(scrollbar, "_petzhu_follow_latest_bound_v100", False):
        return
    original_command = canvas.yview
    def scroll_command(*args):
        try:
            before = tuple(float(x) for x in canvas.yview())
        except Exception:
            before = (0.0, 1.0)
        try:
            original_command(*args)
        except Exception:
            return
        try:
            after = tuple(float(x) for x in canvas.yview())
            moved_up = len(before) > 1 and len(after) > 1 and after[0] < before[0] - 0.00001
            moved_down = len(before) > 1 and len(after) > 1 and after[0] > before[0] + 0.00001
            if moved_up:
                _petzhu_groupchat_set_follow_latest_v100(win, False)
            elif _petzhu_groupchat_at_bottom_v100(canvas) and (moved_down or after == before):
                _petzhu_groupchat_set_follow_latest_v100(win, True)
            elif moved_down:
                _petzhu_groupchat_set_follow_latest_v100(win, False)
        except Exception:
            pass
    try:
        scrollbar.configure(command=scroll_command)
        scrollbar._petzhu_follow_latest_bound_v100 = True
        scrollbar._petzhu_follow_latest_original_command_v100 = original_command
    except Exception:
        pass


def _petzhu_groupchat_open_v100(app):
    result = _PETZHU_GROUPCHAT_OPEN_PRE_V100(app)
    try:
        win = getattr(app, "_petzhu_groupchat_win_v1", None)
        if win is None or not win.winfo_exists():
            return result
        if not hasattr(win, "_petzhu_groupchat_follow_latest_v100"):
            # A newly opened window begins in follow-latest mode; existing windows keep
            # the state chosen by the user's scroll gestures.
            win._petzhu_groupchat_follow_latest_v100 = True
        refs = getattr(win, "_petzhu_groupchat_refs_v1", {}) or {}
        canvas = refs.get("canvas")
        if canvas is not None and canvas.winfo_exists():
            try:
                scrollbars = [w for w in canvas.master.winfo_children() if isinstance(w, tk.Scrollbar)]
                if scrollbars:
                    _petzhu_groupchat_bind_scrollbar_follow_v100(win, canvas, scrollbars[0])
            except Exception:
                pass
    except Exception:
        pass
    return result


_petzhu_groupchat_open_v1 = _petzhu_groupchat_open_v100




